// XRPL account flags
const FLAGS = {
  lsfPasswordSpent:  0x00010000,
  lsfRequireDestTag: 0x00020000,
  lsfRequireAuth:    0x00040000,
  lsfDisallowXRP:    0x00080000,
  lsfDisableMaster:  0x00100000,
  lsfNoFreeze:       0x00200000,
  lsfGlobalFreeze:   0x00400000,
  lsfDefaultRipple:  0x00800000,
  lsfDepositAuth:    0x01000000,
};

// NFT flag bits
const NFT_FLAGS = {
  lsfBurnable:    0x0001,
  lsfOnlyXRP:     0x0002,
  lsfTrustLine:   0x0004,
  lsfTransferable:0x0008,
};

// TX types that are high-risk if in history
const DRAIN_TX_TYPES = new Set([
  'SetRegularKey', 'SignerListSet', 'AccountSet', 'AccountDelete',
  'EscrowCreate', 'PaymentChannelCreate', 'DepositPreauth',
]);

// Single source of truth for counterparty/destination category colors —
// used by the network map, the fund-flow summary bar, and the ranked
// counterparty list, so "this color always means this category" holds
// across every visual in the report instead of each one picking its own.
// (newWallet is intentionally NOT the same orange as issuer — they used to
// collide by coincidence, which is confusing since a report can show both
// in the same view and they mean very different things: one is a neutral
// categorization, the other is a drain-risk flag.)
const CP_CATEGORY_COLOR = {
  blackhole: '#ff5555', // critical — funds here are gone/irrecoverable
  exchange:  '#00d4ff', // known, regulated off-ramp
  newWallet: '#ff79c6', // risk-flagged — possible drain mule (age-based, not an entity type)
  issuer:    '#ffb86c', // token issuer (neutral categorization)
  wallet:    '#bd93f9', // known personal/labeled wallet
  other:     '#8be9fd', // unclassified
};

// Wash trading: suspicious cancel ratio threshold
const WASH_CANCEL_RATIO  = 0.55;  // >55% cancels of creates = suspicious
const WASH_SELF_RATIO     = 0.15;  // >15% payments round-trip
const WASH_MIN_TX         = 20;    // minimum tx count to score
const XRPL_EPOCH          = 946684800; // seconds between 1970-01-01 and 2000-01-01
const ANALYSIS_VERSION    = 'v3.1'; // shown in the Data Quality strip — matches the White Paper's own version

/* ─────────────────────────────
   Finding/Evidence data model
   Superset of the legacy {sev, label, detail} shape every existing
   renderer already destructures — `label: headline` is the compatibility
   shim, so findings built here render unmodified through the current
   report/panel code. Only new or rebuilt modules should use this; existing
   modules keep their current plain-object shape until migrated.
──────────────────────────────── */
// Risk Score category vocabulary a later phase will group modules into —
// tag findings now so that work isn't repeated when it lands.
const FINDING_CATEGORIES = new Set([
  'security', 'market-integrity', 'counterparty', 'issuer', 'liquidity', 'automation', 'data-quality', 'external-exposure',
]);

/** calculated/inferred/hypothesis are an optional, additive epistemic split
 *  on top of `observed` — the point of separating them is that a reader
 *  should never mistake a derived percentage (calculated) or a
 *  history-relative judgment (inferred) for a directly-observed ledger fact
 *  (observed), and never mistake an unproven possible explanation
 *  (hypothesis) for either. All default to empty/null so every existing
 *  finding built before this split still renders exactly as before. */
function mkFinding({
  module, category = null, sev, confidence = null, headline, detail = '',
  observed = [], calculated = [], inferred = [], hypothesis = null,
  alternativeExplanations = [], evidenceAgainstBenign = [],
  classification = null, hashes = [],
  // applicability: { applicable, reason } — an explicit, structured
  // statement of whether this detector's conclusion even applies to this
  // account, kept separate from `sev`. A plain sev:'ok' finding is
  // ambiguous between "checked and genuinely clean" and "this analysis
  // doesn't apply here" — those are different claims, and only the first
  // one should read as reassuring. Optional: most existing findings still
  // express this in prose via `classification`, which stays fully
  // supported; this is for call sites that want it as queryable data
  // (e.g. so the UI can render an explicit "N/A" state).
  applicability = null,
  // ownerImpact / externalImpact — plain-language statements of who is
  // actually affected if this finding is accurate, kept separate from each
  // other so a reader can't conflate "this affects the account holder's
  // own funds" with "this affects other people/the market." Optional.
  ownerImpact = null, externalImpact = null,
} = {}) {
  return {
    module, category, sev, confidence, headline, label: headline, detail,
    observed, calculated, inferred, hypothesis,
    alternativeExplanations, evidenceAgainstBenign, classification, hashes,
    applicability, ownerImpact, externalImpact,
  };
}

/* ─────────────────────────────
   Known Exchange / Entity Registry
──────────────────────────────── */
/* ─────────────────────────────
   State
──────────────────────────────── */
let _currentAddr    = null;
let _inspectAbort   = false;
let _pulseInterval  = null;  // kept for destroyInspector cleanup compatibility
let _xrpPriceUSD    = null;  // cached XRP/USD price — fetched once per session
let _xrpPriceFetched = false;
let _inspectorActive = true;

/* ── Account history cache ──
   Caches the EXPENSIVE part of an inspection — full account_tx pagination
   (Pass 1/2), the server-retention check, and wallet-lifetime verification
   — so re-inspecting the same address (e.g. clicking back and forth between
   a few accounts, or re-opening one from the Relationship Drawer) doesn't
   re-paginate thousands of transactions and re-run the AccountRoot scan
   from scratch every time. Deliberately in-memory only (a Map, not
   localStorage) — this history can run to thousands of transaction objects
   per account, well past what's sane to serialize into browser storage on
   every inspection, and the real cost this saves is redundant NETWORK
   round-trips within one session, not cross-session persistence. Current
   account state (balance/sequence/offers/NFTs/trustlines) is NEVER cached
   here — it's cheap, fast, and always re-fetched fresh so nothing shown
   is stale-looking.
   Keyed by network+address (never shared across networks — the same
   address string can have a completely different real history on Mainnet
   vs. Testnet vs. Xahau). INSPECTION_RESOLVER_VERSION exists so a future
   change to the wallet-lifetime verification logic can invalidate every
   previously-cached entry just by bumping this number. */
const INSPECTION_RESOLVER_VERSION = 1;
const INSPECTION_CACHE_TTL_MS = 3 * 60 * 1000; // 3 minutes
const _inspectionHistoryCache = new Map();
function _getCachedInspectionHistory(network, addr) {
  const entry = _inspectionHistoryCache.get(`${network}:${addr}`);
  if (!entry) return null;
  if (entry.resolverVersion !== INSPECTION_RESOLVER_VERSION) return null;
  if (Date.now() - entry.cachedAtMs > INSPECTION_CACHE_TTL_MS) return null;
  return entry;
}
function _setCachedInspectionHistory(network, addr, data) {
  _inspectionHistoryCache.set(`${network}:${addr}`, { ...data, resolverVersion: INSPECTION_RESOLVER_VERSION, cachedAtMs: Date.now() });
}

function _isInspectorActive() {
  return _inspectorActive && state.currentPage === 'dashboard' && state.currentTab === 'inspector' && !document.hidden;
}

async function _fetchJsonWithCorsFallback(url) {
  // corsproxy.io removed as an application dependency (unreliable in
  // practice — observed returning 403 during live testing) and, being a
  // relay for arbitrary third-party URLs, a broader trust concern than
  // this app wants to carry.
  const proxies = [
    (u) => `https://api.allorigins.win/raw?url=${encodeURIComponent(u)}`,
  ];
  const attempt = async (target) => {
    const signal = typeof AbortSignal?.timeout === 'function' ? AbortSignal.timeout(6000) : undefined;
    const res = await fetch(target, { mode: 'cors', cache: 'no-store', signal });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return await res.json();
  };

  try { return await attempt(url); }
  catch {
    for (const mk of proxies) {
      try { return await attempt(mk(url)); }
      catch { /* continue */ }
    }
    throw new Error('Price feed unavailable');
  }
}

/* ─────────────────────────────
   XRP Price (CoinGecko, cached)
──────────────────────────────── */
async function _fetchXrpPrice() {
  if (_xrpPriceFetched) return _xrpPriceUSD;
  _xrpPriceFetched = true;
  try {
    const d = await _fetchJsonWithCorsFallback('https://api.exchange.coinbase.com/products/XRP-USD/ticker');
    _xrpPriceUSD = Number(d?.price || 0) || null;
  } catch { _xrpPriceUSD = null; }
  return _xrpPriceUSD;
}

function _usd(xrp) {
  if (!_xrpPriceUSD || !xrp) return '';
  const val = xrp * _xrpPriceUSD;
  if (val >= 1_000_000) return ` (~$${(val/1_000_000).toFixed(2)}M)`;
  if (val >= 1_000)     return ` (~$${(val/1_000).toFixed(1)}K)`;
  return ` (~$${val.toFixed(2)})`;
}
/* ─────────────────────────────
   Lazy DOM cache (populated once after mount)
──────────────────────────────── */
let _dom = null;
function _getDOM() {
  if (_dom) return _dom;
  _dom = {
    input:   () => document.getElementById('inspect-addr'),
    err:     document.getElementById('inspect-err'),
    result:  document.getElementById('inspect-result'),
    empty:   document.getElementById('inspect-empty'),
    loading: document.getElementById('inspect-loading'),
    loadMsg: document.getElementById('inspect-loading-msg'),
    loadAddr: document.getElementById('inspect-loading-addr'),
    warn:    document.getElementById('inspect-warn'),
    badge:   document.getElementById('inspect-addr-badge'),
    score:   document.getElementById('inspect-risk-score'),
    label:   document.getElementById('inspect-risk-label'),
    nav:     document.getElementById('inspector-nav'),
    intel:   document.getElementById('inspector-intel-panel'),
  };
  return _dom;
}
// Called after HTML mounts to warm the cache
function _warmDOMCache() { _dom = null; _getDOM(); }



/* ─────────────────────────────
   Init
──────────────────────────────── */
export function initInspector() {
  _mountInspectorHTML();
  _mountInspectorNav();
  _mountInspectorIntelPanel();
  _mountHowToOverlay();
  _mountChartTooltip();

  $('inspect-addr')?.addEventListener('keydown', e => {
    if (e.key === 'Enter') runInspect();
  });

  // Paste full address → auto-run
  $('inspect-addr')?.addEventListener('paste', () => {
    setTimeout(() => {
      const v = $('inspect-addr')?.value.trim();
      if (v && isValidXrpAddress(v)) runInspect();
    }, 60);
  });

  // Section collapse (delegated to the panel) — headers are focusable
  // (tabindex+role="button" in the markup) so this also handles Enter/Space;
  // clicks originating on a nested real <button> (e.g. "Export JSON") are
  // ignored here so they don't *also* toggle the section as a side effect.
  const _toggleInspectorSection = hdr => {
    const sec = hdr?.closest('.inspector-section');
    if (!sec) return;
    const collapsed = sec.classList.toggle('collapsed');
    hdr.setAttribute('aria-expanded', String(!collapsed));
  };
  document.getElementById('tab-inspector')?.addEventListener('click', e => {
    if (e.target.closest('button')) return;
    const hdr = e.target.closest('.section-header');
    if (!hdr) return;
    _toggleInspectorSection(hdr);
  });
  document.getElementById('tab-inspector')?.addEventListener('keydown', e => {
    if (e.key !== 'Enter' && e.key !== ' ') return;
    const hdr = e.target.closest?.('.section-header');
    if (!hdr) return;
    e.preventDefault();
    _toggleInspectorSection(hdr);
  });

  // Bottom nav section jumps
  document.getElementById('inspector-nav')?.addEventListener('click', e => {
    const btn = e.target.closest('[data-jump]');
    if (!btn) return;
    const sec = document.getElementById('section-' + btn.dataset.jump);
    if (sec) {
      sec.classList.remove('collapsed');
      sec.querySelector('.section-header')?.setAttribute('aria-expanded', 'true');
      sec.scrollIntoView({ behavior: 'smooth', block: 'start' });
      // Brief highlight so a jump-nav click gives visible confirmation of
      // *which* card it landed on, not just a scroll with no feedback.
      sec.classList.remove('section-flash');
      void sec.offsetWidth; // restart the animation if the same section is clicked twice in a row
      sec.classList.add('section-flash');
      sec.addEventListener('animationend', () => sec.classList.remove('section-flash'), { once: true });
    }
    _navSetActive(btn.dataset.jumpKey || btn.dataset.jump);
  });

  // Scroll → highlight active section in nav
  // Scoped scroll listener - only processes when inspector is active
  // Debounced scroll listener - 80ms throttle
  let _scrollTick = false;
  window.addEventListener('scroll', () => {
    if (!_isInspectorActive()) return;
    if (!_scrollTick) {
      _scrollTick = true;
      requestAnimationFrame(() => { _navOnScroll(); _scrollTick = false; });
    }
  }, { passive: true });

  window.runInspect         = runInspect;
  window.inspectorCopyAddr  = _copyAddr;
  window.showInspectorHowTo = _showHowTo;
  window.hideInspectorHowTo = _hideHowTo;
  window.setEvidenceMatrixFilter = setEvidenceMatrixFilter;
  window.openEvidenceInspector   = openEvidenceInspector;
  window.runDistMarketFlowAnalysis = runDistMarketFlowAnalysis;

  // Warm DOM cache after HTML is in place
  _warmDOMCache();

  // Populate initial state dashboard
  initInspectorDashboard();

  // Re-populate wallets & recent each time the inspector tab is switched to
  window.addEventListener('naluxrp:tabchange', e => {
    if (e.detail?.tabId === 'inspector' && _isInspectorActive()) {
      _loadWallets();
      _loadRecentHistory();
      _renderWatchlistSection();
      // Ledger-driven pulse updates are skipped while this tab isn't active
      // (see _onLedgerForPulse), so refresh it once immediately on switching
      // back instead of leaving it showing whatever was last on-screen.
      _updatePulse();
    }
  });
}

export function setInspectorActive(active) {
  _inspectorActive = !!active;
  if (!_inspectorActive) _inspectAbort = true;
}

/* ─────────────────────────────
   Public: pre-fill + run from profile
──────────────────────────────── */
function inspectAddress(addr) {
  const inp = $('inspect-addr');
  if (inp) inp.value = addr;
  runInspect();
}

/* ─────────────────────────────
   Main entry
──────────────────────────────── */
export async function runInspect() {
  if (!_isInspectorActive()) return;
  const d     = _getDOM();
  const addr  = d.input()?.value.trim() || '';

  // Reset UI (single batch) — the bottom jump-nav hides along with the
  // result it navigates within; it has nothing to jump to otherwise (see
  // the CSS comment on #inspector-nav for the bug this fixes).
  [d.err, d.result, d.empty, d.warn, d.nav, d.intel].forEach(el => el && (el.style.display = 'none'));
  _inspectAbort = true;  // cancel any in-progress inspect

  if (!addr) { if (d.empty) d.empty.style.display = ''; return; }

  if (!isValidXrpAddress(addr)) {
    if (d.err) { d.err.textContent = `⚠ Invalid address: ${escHtml(addr)}`; d.err.style.display = ''; }
    return;
  }

  if (state.connectionState !== 'connected') {
    if (d.warn) d.warn.style.display = '';
    return;
  }

  _currentAddr  = addr;
  _inspectAbort = false;
  _expandedRiskCategory = null; // don't carry a stale expanded category over from a previous inspection
  // Don't carry stale Relationship Intelligence view/expand state over from a previous inspection.
  _relIntelView = 'tree';
  _relIntelExpandedBranch = null;
  _relIntelShowAll = {};
  _relIntelMatrixSort = { col: 'value', dir: 'desc' };
  _relIntelFocusAddr = null;
  _relIntelExpandedCohort = null;
  _relIntelFlowAsset = 'All';
  _relIntelMatrixHeat = 'value';
  if (d.loadAddr) d.loadAddr.textContent = shortAddr(addr);
  const _setMsg = m => {
    if (!d.loading) return;
    d.loading.style.display = '';
    if (d.loadMsg) d.loadMsg.textContent = m;
  };
  _setMsg('Fetching account data…');

  // ── Helpers ──────────────────────────────────────────────────────────────
  const _delay = ms => new Promise(r => setTimeout(r, ms));

  try {
    // ── Phase 1: Core account data (parallel — small payloads, safe) ─────────
    _setMsg('Fetching account data…');
    // Every one of these three needs its own .catch() — a transient
    // rate-limit/busy rejection on ANY of them inside Promise.all would
    // otherwise reject the whole batch and abort the entire inspection
    // with a generic, unhelpful "Internal error" rather than degrading
    // gracefully the way every other call in this file already does
    // (account_info/account_offers were missing theirs; account_nfts
    // already had it, which is what made this inconsistency visible).
    // account_info specifically uses wsSendResilient — the one proven,
    // live failure mode (a Clio node's documented "Internal error" bug on
    // account_info for AMM pseudo-accounts) falls back to another
    // configured endpoint instead of taking down the whole inspection.
    let infoErr = null;
    const [infoRes, offersRes, nftRes] = await Promise.all([
      wsSendResilient({ command: 'account_info', account: addr, ledger_index: 'validated' }).catch(e => { infoErr = e; return null; }),
      wsSend({ command: 'account_offers', account: addr, ledger_index: 'validated' }).catch(() => null),
      wsSend({ command: 'account_nfts',   account: addr, ledger_index: 'validated' }).catch(() => null),
    ]);
    if (_inspectAbort) return;

    // account_info is load-bearing for everything downstream — proceeding
    // with an empty {} would silently produce a nonsensical "0 XRP, unfunded"
    // style report instead of a clear, honest failure. account_offers/
    // account_nfts degrading to an empty list on failure is fine (an
    // incomplete offers/NFT picture, not a fabricated account). Two
    // genuinely different failure reasons need different messages: a valid
    // but never-funded address (rippled's real actNotFound/"Account not
    // found." response) is NOT the same situation as a transient node
    // rate-limit/busy rejection, and conflating them into one generic
    // message would regress the (previously correct, if accidental) clear
    // "account not found" read a never-funded address used to get.
    if (!infoRes?.result?.account_data) {
      if (d.loading) d.loading.style.display = 'none';
      const notFound = /account not found/i.test(infoErr?.message || '');
      const msg = notFound
        ? `This account (${addr}) has not been funded on the ledger, or does not exist.`
        : `Error: could not fetch account data${infoErr?.message ? ` (${infoErr.message})` : ' (the node may be temporarily unavailable or rate-limited)'} — please try again.`;
      if (d.err) { d.err.textContent = msg; d.err.style.display = ''; }
      return;
    }

    const acct   = infoRes?.result?.account_data || {};
    const offers = offersRes?.result?.offers      || [];
    const nfts   = nftRes?.result?.account_nfts   || [];

    // ── Phase 1b: Paginate account_lines (up to all trustlines) ──────────────
    // account_lines returns max 400 per call. We page until no marker remains.
    // 50ms between pages — small responses, safe to page quickly.
    _setMsg('Fetching trustlines…');
    const lines = [];
    let linesMarker = undefined;
    let linesPage = 0;
    do {
      linesPage++;
      const req = { command: 'account_lines', account: addr, ledger_index: 'validated', limit: 400 };
      if (linesMarker) req.marker = linesMarker;
      const res = await wsSend(req).catch(() => null);
      if (_inspectAbort) return;
      const batch = res?.result?.lines || [];
      lines.push(...batch);
      linesMarker = res?.result?.marker || null;
      if (linesPage > 1) await _delay(50);
    } while (linesMarker && lines.length < 4000);

    // ── Phase 1c: Paginate account_objects (escrows, paychans, checks…) ──────
    _setMsg('Fetching account objects…');
    const objects = [];
    let objMarker = undefined;
    let objPage = 0;
    do {
      objPage++;
      const req = { command: 'account_objects', account: addr, ledger_index: 'validated', limit: 400 };
      if (objMarker) req.marker = objMarker;
      const res = await wsSend(req).catch(() => null);
      if (_inspectAbort) return;
      const batch = res?.result?.account_objects || [];
      objects.push(...batch);
      objMarker = res?.result?.marker || null;
      if (objPage > 1) await _delay(50);
    } while (objMarker && objects.length < 2000);

    // ── Phase 1d: Supplemental (gateway_balances + AMM info + XRP price) ─────
    _setMsg('Fetching token supply, AMM data & price…');
    // AND, not OR: a real AMM LP token satisfies both the `03` prefix
    // convention AND the 40-hex-char length — a generic 40-hex custom
    // currency code that happens not to start with 03 is just an ordinary
    // token, not an LP token. Also exclude zero-balance lines: a closed/
    // fully-withdrawn LP trustline left open at 0 balance is not an active
    // position — this was the source of wildly inflated "N LP positions"
    // counts before this fix.
    const LP_ENRICH_CAP = 15;
    const lpLines = lines.filter(l => l.currency && Number(l.balance) !== 0 && l.currency.startsWith('03') && l.currency.length === 40);
    const [gatewayRes, , ...ammInfoResults] = await Promise.all([
      wsSend({ command: 'gateway_balances', account: addr, ledger_index: 'validated' }).catch(() => null),
      _fetchXrpPrice(),
      // Keyed by amm_account (the LP token's issuer IS the AMM account
      // itself) instead of guessing the trading pair — the old hardcoded
      // `asset: {currency:'XRP'}` silently produced no data for any
      // non-XRP-paired pool.
      ...lpLines.slice(0, LP_ENRICH_CAP).map(l =>
        wsSend({ command: 'amm_info', amm_account: l.account, ledger_index: 'validated' }).catch(() => null)
      ),
    ]);
    if (_inspectAbort) return;

    const gatewayBalances = gatewayRes?.result || null;
    const ammInfoMap = new Map();
    lpLines.slice(0, LP_ENRICH_CAP).forEach((l, i) => {
      if (ammInfoResults[i]?.result?.amm) ammInfoMap.set(l.currency, ammInfoResults[i].result.amm);
    });

    // ── Phase 2: Deep paginated transaction history ───────────────────────────
    //
    // Design rationale:
    //   - XRPL hard cap: 400 tx per account_tx request
    //   - wsSend is a single WebSocket — all requests share one connection
    //   - Safe sustained rate: ~3 req/sec (300ms between pages avoids server-side throttling)
    //   - We crawl newest→oldest using marker chaining until we hit the cap or run out
    //   - Separately, we crawl oldest→newest to anchor the genesis period
    //   - Dedup by hash, sort chronologically for all analysis
    //
    // Cap: window._inspectMaxTx (default 5,000). Power users can set higher in console.
    const TX_PAGE      = 400;                              // XRPL hard limit per request
    const TX_DELAY_MS  = 250;                              // ms between sequential tx pages
    const MAX_TX       = (window._inspectMaxTx || 5000);  // total tx cap
    const TX_PAGE_CAP  = Math.ceil(MAX_TX / TX_PAGE);     // max pages to fetch

    // The expensive part — full pagination + server-retention check +
    // wallet-lifetime verification — is cache-eligible; see
    // _getCachedInspectionHistory's comment. Current-state fields (balance,
    // offers, NFTs, trustlines — fetched above/below this block) are never
    // cached and always come back fresh regardless of a cache hit here.
    let txList, historyCoverage, walletAgeDays, walletCreatedTs, walletAgeVerified,
      walletActivationEvidence, accountLifetimeHistory;

    const _cachedHistory = _getCachedInspectionHistory(state.currentNetwork, addr);
    if (_cachedHistory) {
      _setMsg('Using cached transaction history…');
      ({ txList, historyCoverage, walletAgeDays, walletCreatedTs, walletAgeVerified,
         walletActivationEvidence, accountLifetimeHistory } = _cachedHistory);
    } else {
      const allRaw     = [];
      const seenHashes = new Set();

      const _addBatch = (batch) => {
        for (const item of (batch || [])) {
          const hash = item.tx_json?.hash || item.tx?.hash || item.hash || null;
          if (hash && seenHashes.has(hash)) continue;
          if (hash) seenHashes.add(hash);
          allRaw.push(item);
        }
      };

      // ── History coverage tracking ─────────────────────────────────────────
      // Whether the two passes below actually reached the true edges of this
      // account's history, or merely stopped because a cap was hit / a fetch
      // silently failed. Nothing downstream (wallet age, drain-velocity, offer
      // lifecycle resolution) can safely treat "nothing more found" as
      // confirmed-complete without checking this first — a swallowed network
      // error used to look identical to "no more transactions exist."
      historyCoverage = {
        newestToOldestComplete: false,
        oldestToNewestFetched:  false,
        hitTxCap:   false,
        hitPageCap: false,
        fetchErrorOccurred: false,
      };

      // ── Pass 1: newest→oldest (marker chain) ─────────────────────────────────
      // Captures: recent wash trading, security events, drain patterns, NFT exploits
      let marker1 = undefined;
      let lastPage = 0;
      for (let page = 1; page <= TX_PAGE_CAP && allRaw.length < MAX_TX; page++) {
        lastPage = page;
        if (_inspectAbort) return;
        _setMsg(`Fetching transactions — page ${page} (${allRaw.length.toLocaleString()} so far)…`);
        const req = {
          command: 'account_tx', account: addr,
          limit: TX_PAGE, ledger_index_min: -1, ledger_index_max: -1,
          forward: false,
        };
        if (marker1) req.marker = marker1;
        const res = await wsSend(req).catch(() => null);
        if (_inspectAbort) return;
        if (res == null) historyCoverage.fetchErrorOccurred = true;
        _addBatch(res?.result?.transactions);
        marker1 = res?.result?.marker || null;
        if (!marker1) break;                    // no more pages in this direction
        if (page < TX_PAGE_CAP && allRaw.length < MAX_TX) await _delay(TX_DELAY_MS);
      }
      historyCoverage.hitTxCap   = allRaw.length >= MAX_TX;
      historyCoverage.hitPageCap = !!marker1 && lastPage >= TX_PAGE_CAP;
      // Complete only if the marker chain genuinely ran out AND every page
      // along the way actually succeeded — a failed request's `res` is null,
      // so `res?.result?.marker` optional-chains to the same falsy value a
      // genuinely-final page produces. Without the fetchErrorOccurred check,
      // a transient rate-limit/busy rejection on the LAST page attempted
      // reads identically to "reached the true end of history," which is
      // exactly the kind of false completeness this field exists to prevent
      // (and which _resolveWalletLifetime's verification trusts downstream).
      historyCoverage.newestToOldestComplete = !marker1 && !historyCoverage.fetchErrorOccurred;

      // ── Pass 2: oldest→newest (anchors genesis, time-series start) ──────────
      // Only fetch if Pass 1 didn't already confirm it reached true genesis.
      // This must NOT be gated on allRaw.length (as it previously was): a
      // high-volume account can blow through MAX_TX within the last few DAYS
      // of recent activity alone, in which case Pass 1's capped window is the
      // one case this anchor pass is most needed to correct — skipping it
      // there left wallet-age silently derived from "oldest tx among the most
      // recent 5,000," which for a busy, long-established issuer produced a
      // wildly wrong "2 days old" / "⚠ New wallet" read instead of an honest
      // unresolved age.
      // Gated on `!newestToOldestComplete` rather than bare `marker1`: a
      // transient fetch failure partway through Pass 1 sets `marker1` back to
      // null (res?.result?.marker on a null res), which looks identical to a
      // genuinely-exhausted marker chain and silently broke the loop early.
      // `newestToOldestComplete` already folds in `fetchErrorOccurred`, so a
      // failed page correctly keeps this anchor pass running instead of
      // skipping it — the exact "2 days old" regression this block exists to
      // prevent, just reached via a network blip instead of a high tx count.
      if (!historyCoverage.newestToOldestComplete) {
        if (_inspectAbort) return;
        _setMsg(`Fetching oldest transactions (anchoring history start)…`);
        const oldestRes = await wsSend({
          command: 'account_tx', account: addr,
          limit: TX_PAGE, ledger_index_min: -1, ledger_index_max: -1,
          forward: true,
        }).catch(() => null);
        if (_inspectAbort) return;
        if (oldestRes == null) historyCoverage.fetchErrorOccurred = true;
        _addBatch(oldestRes?.result?.transactions);
        // This pass fetches a single page (no marker chaining) — a returned
        // marker means there's more oldest-direction history beyond it that
        // was never fetched, so genesis is NOT confirmed reached in that case.
        historyCoverage.oldestToNewestFetched = oldestRes != null && !oldestRes?.result?.marker;
        await _delay(TX_DELAY_MS);
      }

      txList = normaliseTxList(allRaw)
        .sort((a, b) => (a.tx.date ?? 0) - (b.tx.date ?? 0));

      // ── Pass 3: cross-endpoint genesis probe ─────────────────────────────────
      // Passes 1/2 only ever ask the ONE server the shared connection happens
      // to point at. For a busy, long-lived account, that server's pagination
      // can hit its cap/error without ever finding real AccountRoot creation
      // evidence — which looks identical whether the account is genuinely
      // young OR the connected server's own history retention simply doesn't
      // reach back far enough (confirmed live on SOLO: some configured nodes
      // retain only the last few million ledgers). Only probe when there's
      // an actual question to resolve — real evidence already found, or a
      // genuinely complete pagination with nothing more to look for, means
      // this is skipped entirely.
      if (!_findAccountRootCreationEvidence(txList, addr) &&
          (historyCoverage.hitTxCap || historyCoverage.hitPageCap || historyCoverage.fetchErrorOccurred)) {
        _setMsg('Checking other endpoints for deeper history…');
        const currentOldestLedger = txList[0]?.tx?.ledger_index ?? null;
        const probeResults = await fetchAcrossOtherEndpoints({
          command: 'account_tx', account: addr,
          limit: TX_PAGE, ledger_index_min: -1, ledger_index_max: -1, forward: true,
        }).catch(() => []);
        for (const result of probeResults) {
          const batch = result?.transactions || [];
          if (!batch.length) continue;
          // forward:true already returns oldest-first, so the batch's own
          // first entry is that endpoint's oldest known transaction.
          const probeOldestLedger = (batch[0].tx_json || batch[0].tx || {}).ledger_index ?? null;
          if (probeOldestLedger != null && (currentOldestLedger == null || probeOldestLedger < currentOldestLedger)) {
            _addBatch(batch);
            historyCoverage.crossEndpointGenesisRecovered = true;
            break; // one endpoint with genuinely deeper history is enough
          }
        }
        if (historyCoverage.crossEndpointGenesisRecovered) {
          txList = normaliseTxList(allRaw)
            .sort((a, b) => (a.tx.date ?? 0) - (b.tx.date ?? 0));
        }
      }

      // ── Wallet age / activation provenance ───────────────────────────────────
      // Only the server_info round-trip (network-dependent) stays inline here;
      // every actual verification RULE lives in the pure, debug-hookable
      // _resolveWalletLifetime so it can be unit-tested without a live socket.
      _setMsg('Verifying account lifetime…');
      let serverEarliestLedger = null;
      if (historyCoverage.newestToOldestComplete || historyCoverage.oldestToNewestFetched) {
        // Only worth the extra RPC when Pass 1/2 would otherwise be treated as
        // reaching real completeness — a marker still present already means
        // coverage is honestly partial regardless of server retention.
        const serverInfoRes = await wsSend({ command: 'server_info' }).catch(() => null);
        serverEarliestLedger = _parseCompleteLedgersMin(serverInfoRes?.result?.info?.complete_ledgers);
      }
      const resolved = _resolveWalletLifetime(txList, addr, historyCoverage, serverEarliestLedger);
      ({ walletAgeDays, walletCreatedTs, walletAgeVerified, walletActivationEvidence } = resolved);
      historyCoverage.serverEarliestLedger = serverEarliestLedger;
      historyCoverage.oldestFetchedTxLedger = resolved.oldestFetchedLedger;
      historyCoverage.possiblyBoundedByServerRetention = resolved.possiblyBoundedByServerRetention;
      if (walletActivationEvidence) _setMsg('✓ Account activation verified');
      accountLifetimeHistory = _buildAccountLifetimeHistory(txList, addr);

      _setCachedInspectionHistory(state.currentNetwork, addr, {
        txList, historyCoverage, walletAgeDays, walletCreatedTs, walletAgeVerified,
        walletActivationEvidence, accountLifetimeHistory,
      });
    }
    window._debugLastHistoryCoverage = historyCoverage;
    window._debugLastWalletLifetime = { walletAgeDays, walletCreatedTs, walletAgeVerified, walletActivationEvidence, txListLen: txList.length };

    // ── Live order book (most-traded pair) ───────────────────────────────────
    _setMsg('Analyzing market activity…');
    const pairCounts = new Map();
    for (const {tx} of txList) {
      if (tx.TransactionType !== 'OfferCreate' || !tx.TakerPays || !tx.TakerGets) continue;
      const getCurr = o => typeof o === 'string' ? 'XRP' : `${o.currency}+${o.issuer||''}`;
      const pair = [getCurr(tx.TakerPays), getCurr(tx.TakerGets)].sort().join('↔');
      pairCounts.set(pair, (pairCounts.get(pair) || 0) + 1);
    }
    let liveOrderBook = null;
    if (pairCounts.size > 0) {
      const topPairKey  = [...pairCounts.entries()].sort((a,b) => b[1]-a[1])[0][0];
      const [payStr, getStr] = topPairKey.split('↔');
      const parseCurr   = s => s === 'XRP' ? { currency: 'XRP' }
        : { currency: s.split('+')[0], issuer: s.split('+')[1] };
      const bookRes = await wsSend({
        command: 'book_offers',
        taker_pays: parseCurr(payStr),
        taker_gets: parseCurr(getStr),
        limit: 20, ledger_index: 'validated',
      }).catch(() => null);
      if (bookRes?.result?.offers?.length)
        liveOrderBook = { pair: topPairKey, offers: bookRes.result.offers };
    }

    // ── Counterparty age check (top 6 outbound destinations) ─────────────────
    // Sequential with tiny delay — 6 requests, no need to parallel-blast
    _setMsg('Resolving counterparties…');
    const outboundDests = [...new Set(
      txList
        .filter(({tx}) => tx.TransactionType === 'Payment' && tx.Account === addr && tx.Destination)
        .map(({tx}) => tx.Destination)
    )].slice(0, 6);

    const destAgeMap = new Map();
    for (const dest of outboundDests) {
      if (_inspectAbort) return;
      const res = await wsSend({ command: 'account_info', account: dest, ledger_index: 'validated' }).catch(() => null);
      const data = res?.result?.account_data;
      if (data) destAgeMap.set(dest, { sequence: data.Sequence || 0, balance: Number(data.Balance || 0) / 1e6 });
      await _delay(80);
    }

    // ── Issuer's own token/XRP AMM pool + LP holder lookup ────────────────────
    // Only for confirmed token issuers — one amm_info call to find the pool,
    // one account_lines page on the POOL account to see who its LP holders
    // are. Same "small number of targeted extra lookups" precedent as the
    // counterparty age check above. XRP-paired pools only for this first
    // pass — an issuer with multiple pairs/currencies picks its dominant one.
    let issuerAmmPool = null;
    const issuerObligationLines = lines.filter(l => Number(l.balance) < 0);
    if (issuerObligationLines.length > 0) {
      _setMsg('Analyzing AMM participation…');
      const currencyCounts = new Map();
      for (const l of issuerObligationLines) currencyCounts.set(l.currency, (currencyCounts.get(l.currency) || 0) + 1);
      const dominantCurrency = [...currencyCounts.entries()].sort((a, b) => b[1] - a[1])[0][0];
      const ammRes = await wsSend({
        command: 'amm_info',
        asset: { currency: dominantCurrency, issuer: addr },
        asset2: { currency: 'XRP' },
        ledger_index: 'validated',
      }).catch(() => null);
      const ammData = ammRes?.result?.amm || null;
      if (ammData?.account) {
        const lpLinesRes = await wsSend({ command: 'account_lines', account: ammData.account, ledger_index: 'validated', limit: 400 }).catch(() => null);
        const lpHolderLines = (lpLinesRes?.result?.lines || []).filter(l => isLpCurrency(l.currency) && Number(l.balance) !== 0);
        issuerAmmPool = { currency: dominantCurrency, pool: ammData, lpHolderLines, lpLinesTruncated: !!lpLinesRes?.result?.marker };
      }
    }

    // ── Common external funder lookup (candidate mirror groups) ──────────────
    // Issuer Connections' mirror-group detection needs to know, for accounts
    // the issuer did NOT create directly, whether several of them share one
    // external funding account — a confirmed, previously undetectable gap
    // (the existing address-clustering helper explicitly disclaims it:
    // "cannot detect a shared funding source"). Bounded to a capped number
    // of targeted per-wallet lookups — same "small number of targeted extra
    // lookups" precedent as the counterparty-age check and the AMM pool
    // lookup above. Each lookup is a single oldest-first account_tx page —
    // enough to find most simple token-recipient wallets' real AccountRoot
    // creation evidence without re-running this account's own full
    // Pass1/Pass2 pagination for every candidate.
    const commonFunderByAddr = new Map();
    if (issuerObligationLines.length > 0) {
      const { distributions, createdAccts } = _buildIssuerDistributionMap(txList, addr, lines);
      const candidateAddrs = new Set();
      for (const group of _bucketDistributionsByAmount(distributions)) {
        for (const { addr: a2 } of group) if (!createdAccts.has(a2)) candidateAddrs.add(a2);
      }
      const COMMON_FUNDER_LOOKUP_CAP = 15;
      const toCheck = [...candidateAddrs].slice(0, COMMON_FUNDER_LOOKUP_CAP);
      if (toCheck.length) {
        _setMsg('Checking for common funding sources…');
        for (const holderAddr of toCheck) {
          if (_inspectAbort) return;
          const res = await wsSend({
            command: 'account_tx', account: holderAddr,
            limit: 400, ledger_index_min: -1, ledger_index_max: -1, forward: true,
          }).catch(() => null);
          const holderTxList = normaliseTxList(res?.result?.transactions || []);
          const evidence = _findAccountRootCreationEvidence(holderTxList, holderAddr);
          if (evidence?.fundingAccount) commonFunderByAddr.set(holderAddr, evidence.fundingAccount);
          await _delay(80);
        }
      }
    }

    // ── Auction-window market data ────────────────────────────────────────────
    // ONLY when a pool this account has amm_info for currently has an ACTIVE
    // auction slot — a bounded, targeted fetch of that POOL's own tx
    // history. Every trade against an AMM necessarily touches the pool's
    // own reserves, so its account_tx contains every execution against it
    // (the same "shared ledger party sees all activity" trick already used
    // for a confirmed issuer's own token, applied to the pool account
    // instead). Capped tightly (at most 2 pools, ~1000 tx each) since this
    // is a supplementary lookup for a specific, narrow question — not the
    // primary canonical history.
    const auctionSlotPools = [];
    for (const pool of ammInfoMap.values()) if (pool.auction_slot) auctionSlotPools.push(pool);
    if (issuerAmmPool?.pool?.auction_slot && !auctionSlotPools.some(p => p.account === issuerAmmPool.pool.account)) {
      auctionSlotPools.push(issuerAmmPool.pool);
    }
    const AUCTION_POOL_TX_CAP = 1000;
    const AUCTION_POOL_TX_PAGE = 400;
    const auctionPoolTxByAccount = new Map();
    for (const pool of auctionSlotPools.slice(0, 2)) {
      if (_inspectAbort) return;
      const poolRaw = [];
      let poolMarker; let poolPage = 0;
      do {
        poolPage++;
        const req = { command: 'account_tx', account: pool.account, limit: AUCTION_POOL_TX_PAGE, ledger_index_min: -1, ledger_index_max: -1, forward: false };
        if (poolMarker) req.marker = poolMarker;
        const res = await wsSend(req).catch(() => null);
        if (_inspectAbort) return;
        poolRaw.push(...(res?.result?.transactions || []));
        poolMarker = res?.result?.marker || null;
        if (poolMarker) await _delay(150);
      } while (poolMarker && poolRaw.length < AUCTION_POOL_TX_CAP && poolPage < 3);
      const poolTxList = normaliseTxList(poolRaw).sort((a, b) => (a.tx.date ?? 0) - (b.tx.date ?? 0));
      auctionPoolTxByAccount.set(pool.account, { txList: poolTxList, truncated: !!poolMarker || poolTxList.length >= AUCTION_POOL_TX_CAP });
    }

    // ── Phase 3: Render ─────────────────────────────────────────────────────
    // Debug hook: after an inspection involving an active auction slot,
    // window._debugLastAuctionPoolTx.get(poolAccount) gives the raw
    // fetched pool tx data (txList, truncated) behind Auction Window/
    // Dominance — useful for diagnosing why either came back empty (e.g.
    // the real AMMBid/trade fell outside the bounded fetch window).
    window._debugLastAuctionPoolTx = auctionPoolTxByAccount;
    // Genuinely the last real stage before the result is ready — renderAll
    // runs every detector synchronously (drain risk, wash trading, security,
    // flow, forensic suite, etc.), which is real, non-trivial work for a
    // large history. The loader stays visible through this (moved from
    // hiding right after pagination finished, which left this entire phase
    // — order book, counterparties, AMM pool, and this analysis pass —
    // with nothing on screen, looking frozen rather than working) and only
    // hides once the result is actually ready to show, right below.
    _setMsg('Running forensic analysis…');
    renderAll(addr, acct, lines, offers, nfts, objects, txList, {
      gatewayBalances, ammInfoMap, destAgeMap, issuerAmmPool, auctionPoolTxByAccount, commonFunderByAddr,
      walletAgeDays, walletCreatedTs, walletAgeVerified, walletActivationEvidence, accountLifetimeHistory, historyCoverage, liveOrderBook,
    });

    if (d.loading) d.loading.style.display = 'none';
    if (d.result) { d.result.style.display = ''; _applyAnalystMode(); }
    // 'block', not '' — #inspector-nav's own base CSS rule is an
    // unconditional display:none (there's no longer a body.inspector
    // override to fall back to), so clearing the inline style would just
    // resolve back to none instead of actually showing it.
    if (d.nav) d.nav.style.display = 'block';
    if (d.intel) d.intel.style.display = 'block';
    _applyInspectorShellCollapseState();

    // ── Post-render: history, change detection, watchlist ──────────────────
    const riskVal = d.score ? Number(d.score.textContent) : null;
    _renderRiskScoreDiff(addr, isNaN(riskVal) ? null : riskVal);

    // Collect all findings for change detection fingerprint
    const _allFindings = window._lastAllFindings || [];
    addInspectHistory(addr, isNaN(riskVal) ? null : riskVal, _allFindings);
    _renderChangeBanner(addr, _allFindings);
    _recordRiskScoreTrend(addr, isNaN(riskVal) ? null : riskVal);
    _renderRiskScoreTrendChart(addr);

    // Update watchlist entry if this address is watched
    if (_isWatched(addr)) _updateWatchlistEntry(addr, isNaN(riskVal) ? null : riskVal);

    // Sort sections by severity after render
    _sortSectionsBySeverity();

  } catch (err) {
    if (_inspectAbort) return;
    if (d.loading) d.loading.style.display = 'none';
    console.error('runInspect failed:', err);
    if (d.err)     { d.err.textContent = `Error: ${escHtml(err.message)}`; d.err.style.display = ''; }
  }
}

/* ─────────────────────────────
   Normalise tx list
   Handles both old {tx, meta} and new {transaction, metadata} shapes
──────────────────────────────── */
function normaliseTxList(raw) {
  // Support both classic format ({ tx, meta }) and newer rippled v2 format
  // ({ tx_json, metadata, date, hash } — date/hash live at item level in v2).
  return raw.map(item => {
    const tx   = item.tx_json || item.tx || item.transaction || {};
    const meta = item.metadata || item.meta || {};
    // In v2, date (Ripple epoch seconds) is at item level — inject it.
    if (tx.date == null && item.date != null) tx.date = item.date;
    // hash is also at item level in v2 — inject it.
    if (!tx.hash && item.hash) tx.hash = item.hash;
    return { tx, meta };
  });
}

/* ── Account Lifetime: AccountRoot creation evidence ──
   The ONLY real proof an XRPL account was activated at a given moment: a
   validated, successful transaction whose metadata CREATED an AccountRoot
   ledger entry for this exact address. Everything else (oldest fetched tx,
   lowest Sequence seen, "first transaction in this dataset") is at best a
   lower bound — this is the one signal strong enough to upgrade an age
   estimate into a verified fact. Scans the already-fetched txList (no extra
   RPC calls); if the account's genesis era wasn't actually fetched, this
   simply finds nothing and callers fall back to the existing lower-bound
   estimate, exactly as before this existed.

   Returns every creation event found (there can be more than one — an
   address can be deleted via AccountDelete and later reused by someone
   else, who funds a brand-new AccountRoot at the same address), sorted
   oldest-first. */
function _findAllAccountRootCreationEvents(txList, addr) {
  const events = [];
  for (const { tx, meta } of txList) {
    if (meta?.TransactionResult !== 'tesSUCCESS') continue;
    for (const node of (meta.AffectedNodes || [])) {
      const created = node.CreatedNode;
      if (created?.LedgerEntryType !== 'AccountRoot') continue;
      if (created.NewFields?.Account !== addr) continue;
      events.push({
        ledgerIndex: tx.ledger_index || tx.LedgerIndex || null,
        transactionHash: tx.hash || null,
        timestamp: tx.date ?? null,
        // An ordinary account is activated by a Payment that funds it —
        // the funding account is whoever sent that Payment. Other creation
        // paths (e.g. an AMM pseudo-account, created by AMMCreate rather
        // than a Payment) won't have a simple single funder in this sense;
        // leave it null rather than attributing funding to the wrong actor.
        fundingAccount: tx.TransactionType === 'Payment' ? (tx.Account || null) : null,
        initialBalanceDrops: created.NewFields.Balance ?? null,
        creationTxType: tx.TransactionType || null,
      });
    }
  }
  return events.sort((a, b) => (a.timestamp ?? 0) - (b.timestamp ?? 0));
}

/* Current activation evidence — the CURRENT AccountRoot's own creation, not
   necessarily the address's first-ever one. For the overwhelming majority
   of accounts (never deleted/recreated) there's exactly one creation event
   and this is trivially correct; for a deleted-then-reused address, the
   most recent creation is the one that actually explains the account as it
   exists today — an earlier, superseded creation must not be presented as
   if it were still the current account's activation. */
function _findAccountRootCreationEvidence(txList, addr) {
  const events = _findAllAccountRootCreationEvents(txList, addr);
  return events.length ? events[events.length - 1] : null;
}

/* ── Account Lifetime: delete + recreation history ──
   XRPL accounts can be deleted (a successful AccountDelete sent BY the
   account itself) and the address later reused by funding it again — a
   genuinely different account in substance, sharing only the address
   string. Pairs every creation event found against every AccountDelete
   event found BY this account (sequentially, oldest-first) into discrete
   lifetime segments; the final, still-open segment (deletedAt: null)
   describes the CURRENT account. This is forensically important: an
   address with real activity back to 2021 that was deleted in 2024 and
   refunded in 2026 is NOT a "5-year-old account" today — it's a 2026
   account at an address with older, unrelated history. */
function _buildAccountLifetimeHistory(txList, addr) {
  const creations = _findAllAccountRootCreationEvents(txList, addr);
  const deletions = [];
  for (const { tx, meta } of txList) {
    if (meta?.TransactionResult !== 'tesSUCCESS') continue;
    if (tx.TransactionType !== 'AccountDelete' || tx.Account !== addr) continue;
    deletions.push({
      ledgerIndex: tx.ledger_index || tx.LedgerIndex || null,
      transactionHash: tx.hash || null,
      timestamp: tx.date ?? null,
      destination: tx.Destination || null,
    });
  }
  deletions.sort((a, b) => (a.timestamp ?? 0) - (b.timestamp ?? 0));

  const lifetimes = [];
  let di = 0;
  for (const c of creations) {
    // The next not-yet-consumed deletion that happened AT OR AFTER this
    // creation closes this lifetime segment; a deletion can't close a
    // lifetime that started after it.
    while (di < deletions.length && (deletions[di].timestamp ?? 0) < (c.timestamp ?? 0)) di++;
    const closingDeletion = di < deletions.length ? deletions[di++] : null;
    lifetimes.push({
      createdAt: c.timestamp, createdLedger: c.ledgerIndex, createdTxHash: c.transactionHash,
      fundingAccount: c.fundingAccount, initialBalanceDrops: c.initialBalanceDrops,
      deletedAt: closingDeletion?.timestamp ?? null,
      deletedLedger: closingDeletion?.ledgerIndex ?? null,
      deletedTxHash: closingDeletion?.transactionHash ?? null,
    });
  }

  return {
    lifetimes,
    deletedAndRecreated: creations.length > 1,
    earliestKnownHistory: lifetimes.length ? lifetimes[0] : null,
    currentLifetime: lifetimes.length ? lifetimes[lifetimes.length - 1] : null,
  };
}

/* ── Server history retention ──
   "No marker returned" from account_tx can mean the account's full history
   was genuinely traversed, OR this specific rippled node simply doesn't
   retain ledger history that far back and silently stops rather than
   erroring — a real, confirmed failure mode (a 7-year-old, high-volume
   issuer's marker chain ran dry after only ~3,600 transactions on a public
   node, reading as "complete" and producing a false "1 day old, VERIFIED"
   result). Parses server_info's `complete_ledgers` ("32570-91733154" or
   with gaps, "32570-50000000,50000100-91733154") down to the single
   earliest ledger index this server has available at all. */
function _parseCompleteLedgersMin(completeLedgersStr) {
  if (!completeLedgersStr || typeof completeLedgersStr !== 'string') return null;
  const starts = completeLedgersStr.split(',')
    .map(seg => Number(seg.split('-')[0]))
    .filter(Number.isFinite);
  return starts.length ? Math.min(...starts) : null;
}

/* ── Canonical wallet-age / activation resolver ──
   Pure (no network calls) — the caller fetches `serverEarliestLedger` via
   server_info itself and passes it in, so this stays unit-testable without
   a live socket. Two tiers of evidence, strongest first:
    1. Real AccountRoot creation evidence — a validated, successful tx whose
       metadata CREATED this exact AccountRoot. Proof, not an estimate,
       regardless of whether pagination happened to reach the true end of
       history by other means — finding the creation event IS reaching it.
    2. Oldest-fetched-transaction timestamp — only a LOWER BOUND, and only
       trusted as verified when pagination completeness is ALSO not
       suspiciously bounded by this specific server's own retention limit
       (see _parseCompleteLedgersMin's comment for the real bug this
       catches: a server that silently stops returning markers once it runs
       out of retained history, which reads identically to "genuinely
       reached this account's genesis" unless cross-checked). */
function _resolveWalletLifetime(txList, addr, historyCoverage, serverEarliestLedger) {
  const RIPPLE_EPOCH = 946684800;
  const walletActivationEvidence = _findAccountRootCreationEvidence(txList, addr);

  const oldestFetchedLedger = txList[0]?.tx ? (txList[0].tx.ledger_index || txList[0].tx.LedgerIndex || null) : null;
  // A generous margin (ledger count, not time — close cadence has varied
  // across XRPL's history, so this is deliberately conservative): pagination
  // completeness is only trusted as real age evidence when the server's own
  // earliest retained ledger sits comfortably BEFORE the oldest transaction
  // found — proof the server COULD have shown earlier activity if any
  // existed. This must be a fail-safe POSITIVE check, not a veto flag: if
  // the server_info lookup itself fails or returns nothing (serverEarliestLedger
  // stays null — including from a plain transient network hiccup), that is
  // NOT grounds to fall back to trusting "no marker returned" blindly. For a
  // forensics tool, an unconfirmed safety check must default to unverified,
  // never to verified.
  const SERVER_BOUNDARY_MARGIN_LEDGERS = 50000;
  const serverRetentionConfirmedSufficient = !!(
    serverEarliestLedger != null && oldestFetchedLedger != null &&
    (oldestFetchedLedger - serverEarliestLedger) >= SERVER_BOUNDARY_MARGIN_LEDGERS
  );
  const possiblyBoundedByServerRetention = !serverRetentionConfirmedSufficient;

  const walletAgeVerified = !!walletActivationEvidence || (
    (historyCoverage.newestToOldestComplete || historyCoverage.oldestToNewestFetched)
    && serverRetentionConfirmedSufficient
  );

  // Clamped at 0 — an account can never be a negative number of days old.
  // A tiny negative delta is possible for an account created within the
  // same second a read happens (ledger close time vs. local clock skew),
  // and Math.floor rounds that toward -1, not 0; left unclamped this
  // produces an absurd "-1 days old" read for the single most important
  // case to get right — a genuinely brand-new, fully verified account.
  let walletAgeDays = null, walletCreatedTs = null;
  if (walletActivationEvidence?.timestamp != null) {
    walletCreatedTs = (walletActivationEvidence.timestamp + RIPPLE_EPOCH) * 1000;
    walletAgeDays   = Math.max(0, Math.floor((Date.now() - walletCreatedTs) / 86400000));
  } else if (txList.length > 0) {
    const oldest = txList[0].tx;
    if (oldest?.date) {
      walletCreatedTs = (oldest.date + RIPPLE_EPOCH) * 1000;
      walletAgeDays   = Math.max(0, Math.floor((Date.now() - walletCreatedTs) / 86400000));
    }
  }

  return {
    walletAgeDays, walletCreatedTs, walletAgeVerified, walletActivationEvidence,
    oldestFetchedLedger, possiblyBoundedByServerRetention,
  };
}

/* ─────────────────────────────
   Shared amount helpers
   Used by the Offer Lifecycle Engine, the Balance Change Engine, and the
   AMM/LP fix — one source of truth instead of the XRP-vs-IOU normalization
   pattern that used to be re-typed slightly differently in half a dozen
   places (see e.g. the old wash-trading spoofing check).
──────────────────────────────── */
function amtNum(amount) {
  if (amount == null) return null;
  if (typeof amount === 'string') return Number(amount) / 1e6; // drops → XRP
  const v = Number(amount.value);
  return Number.isFinite(v) ? v : null;
}
function amtCurrency(amount) {
  return typeof amount === 'string' ? 'XRP' : (amount?.currency || null);
}
// AMM LP tokens use the `03` currency-code prefix convention and are always
// a full 40-hex-char code — both conditions together, not either alone (a
// generic 40-hex custom currency code that doesn't start with 03 is just an
// ordinary token, not an LP token; see the AMM position-count bug fix).
function isLpCurrency(currency) {
  return typeof currency === 'string' && currency.length === 40 && currency.startsWith('03');
}

/* ─────────────────────────────
   Balance Change Engine
   Reconstructs actual XRP/IOU/LP-token balance deltas for `addr` from a
   transaction's own metadata — for EVERY transaction type, not just
   Payment. This is what a Payment-only flow filter misses entirely: an
   OfferCreate that crosses the book moves real balance exactly like a
   Payment does, and previously wasn't counted at all.
──────────────────────────────── */
// Ledger entry types whose creation/deletion locks or releases part of this
// account's owner reserve — used to classify RESERVE_LOCK/RESERVE_RELEASE
// economic actions below without a second AffectedNodes pass.
const _RESERVE_OBJECT_TYPES = new Set(['Escrow', 'Check', 'PayChannel', 'Offer', 'SignerList', 'Ticket']);

/* ── AMM execution detection ──────────────────────────
   Verified directly against live ledger data (5 real transactions against
   the SOLO/XRP AMM, including a multi-hop path payment): an AMM pool's own
   AccountRoot node ALWAYS carries an AMMID field in its FinalFields/
   NewFields whenever a transaction executes against that pool. There is no
   separate LedgerEntryType:"AMM" node in a trading transaction's own
   metadata — AMMID on the pool's AccountRoot is the only signal. This is
   what lets a trade be classified CLOB vs AMM vs HYBRID from metadata alone,
   with no extra RPC calls. */
function _txTouchesAmm(meta) {
  if (!meta?.AffectedNodes?.length) return false;
  for (const node of meta.AffectedNodes) {
    const n = node.CreatedNode || node.ModifiedNode || node.DeletedNode;
    if (!n || n.LedgerEntryType !== 'AccountRoot') continue;
    if ((n.FinalFields || n.NewFields)?.AMMID) return true;
  }
  return false;
}

function _txTouchesOfferNode(meta) {
  if (!meta?.AffectedNodes?.length) return false;
  return meta.AffectedNodes.some(node => {
    const n = node.CreatedNode || node.ModifiedNode || node.DeletedNode;
    return n && n.LedgerEntryType === 'Offer';
  });
}

// Shared by extractBalanceDeltas, analyseIssuerMarketActivity, and
// analyseAuctionWindowMarket — all three independently re-typed this exact
// same 4-way combination of the two touch-detection primitives above.
function _classifyExecutionRoute(touchesAmm, touchesOffer) {
  return touchesAmm && touchesOffer ? 'HYBRID' : touchesAmm ? 'AMM' : touchesOffer ? 'CLOB' : 'UNKNOWN';
}

// Shared by Fund Flow, Inbound Flow, the Relationship Drawer, and Wash
// Execution's round-trip pairing — these four independently re-parsed "how
// much of which asset did this single Payment actually move" off raw
// tx.Amount, each with its own copy of the same string-vs-object check.
// Inbound Flow's own copy was already more correct than the other three: it
// prefers meta.delivered_amount over tx.Amount, which matters whenever they
// differ (a partial payment, tfPartialPayment, or slippage on a cross-
// currency payment) — tx.Amount is only ever what the SENDER specified as a
// maximum/target, not necessarily what the recipient actually received.
// This extends that same correct behavior to the other three call sites
// rather than leaving them on the less-accurate field.
function _extractPaymentAmount(tx, meta) {
  const amt = meta?.delivered_amount || tx.Amount;
  if (typeof amt === 'string') {
    // A ledger from before the "delivered_amount" amendment can report this
    // field as the literal string "unavailable" for a partial payment,
    // rather than a real drops value — Number("unavailable") silently
    // produces NaN. Left uncaught, NaN poisons every running sum it's
    // summed into: a single contaminated payment can turn an ENTIRE
    // destination/source/relationship total into NaN, and `NaN || 0`
    // (a common "default to zero" guard elsewhere) silently coerces that
    // back to a false, confident-looking 0 — which is how a report with
    // real, nonzero XRP flow can end up showing "No inbound or outbound
    // XRP flow found" while a destinations table right below it lists real
    // transfers. Returned as an explicit amountUnknown flag instead, so
    // callers can exclude it from numeric totals AND flag the total as
    // possibly incomplete, rather than either poisoning or silently
    // understating it.
    const xrp = Number(amt) / 1e6;
    if (!Number.isFinite(xrp)) return { amtXrp: null, amtToken: null, amountUnknown: true };
    return { amtXrp: xrp, amtToken: null, amountUnknown: false };
  }
  if (amt?.value) return { amtXrp: 0, amtToken: { value: Number(amt.value), currency: hexToAscii(amt.currency), issuer: amt.issuer }, amountUnknown: false };
  return { amtXrp: 0, amtToken: null, amountUnknown: false };
}

function extractBalanceDeltas(tx, meta, addr) {
  const out = { xrpDelta: 0, tokenDeltas: [], tokenDeltaMap: new Map(), lpDeltas: [], lpDeltaMap: new Map(), economicActions: [], route: null };
  if (!meta?.AffectedNodes?.length) return out;

  for (const node of meta.AffectedNodes) {
    const created  = node.CreatedNode;
    const modified = node.ModifiedNode;
    const deleted  = node.DeletedNode;
    const n = created || modified || deleted;
    if (!n) continue;

    if (n.LedgerEntryType === 'AccountRoot') {
      const account = n.FinalFields?.Account || n.NewFields?.Account;
      if (account !== addr) continue;
      const finalBal = Number((n.FinalFields || n.NewFields)?.Balance ?? 0);
      const prevBal  = created ? 0 : Number(n.PreviousFields?.Balance ?? finalBal);
      const delta    = (finalBal - prevBal) / 1e6;
      if (delta) out.xrpDelta += delta;
      continue;
    }

    if (n.LedgerEntryType === 'RippleState') {
      const fields = n.FinalFields || n.NewFields;
      const low  = fields?.LowLimit?.issuer;
      const high = fields?.HighLimit?.issuer;
      const isLow  = low === addr;
      const isHigh = high === addr;
      if (!isLow && !isHigh) continue; // trustline doesn't touch this account
      // RippleState.Balance is always signed from the LOW account's
      // perspective — flip sign when addr is the high account.
      const sign = isLow ? 1 : -1;
      const counterpartyIssuer = isLow ? high : low;
      const currency = fields?.Balance?.currency;
      const finalVal = deleted ? 0 : Number(fields?.Balance?.value ?? 0);
      const prevVal  = created ? 0 : Number(n.PreviousFields?.Balance?.value ?? (deleted ? fields?.Balance?.value ?? 0 : finalVal));
      const delta = (finalVal - prevVal) * sign;
      if (!delta || !currency) continue;

      const bucket = isLpCurrency(currency) ? out.lpDeltaMap : out.tokenDeltaMap;
      const key = `${currency}.${counterpartyIssuer}`;
      const prior = bucket.get(key) || { currency, issuer: counterpartyIssuer, delta: 0 };
      prior.delta += delta;
      bucket.set(key, prior);
      continue;
    }

    // Owner-reserve objects: created/deleted (not modified) for THIS account
    // locks/releases one reserve increment — a fact independent of any XRP/
    // token balance delta in the same transaction, so it's tracked
    // separately here rather than inferred from the deltas above.
    if (_RESERVE_OBJECT_TYPES.has(n.LedgerEntryType)) {
      const fields = n.FinalFields || n.NewFields;
      const owner = fields?.Account || fields?.Owner;
      if (owner === addr) {
        if (created) out.economicActions.push('RESERVE_LOCK');
        else if (deleted) out.economicActions.push('RESERVE_RELEASE');
      }
    }
  }

  out.tokenDeltas = [...out.tokenDeltaMap.values()];
  out.lpDeltas    = [...out.lpDeltaMap.values()];
  delete out.tokenDeltaMap;
  delete out.lpDeltaMap;

  // XRP direction + DEX/AMM classification — derived from the deltas and
  // transaction type already computed above, not a second data pass.
  if (out.xrpDelta > 0) out.economicActions.push('XRP_INFLOW');
  else if (out.xrpDelta < 0) out.economicActions.push('XRP_OUTFLOW');
  if (tx.TransactionType === 'AMMDeposit') out.economicActions.push('AMM_DEPOSIT');
  else if (tx.TransactionType === 'AMMWithdraw') out.economicActions.push('AMM_WITHDRAWAL');
  else if (out.xrpDelta !== 0 && (out.tokenDeltas.length || out.lpDeltas.length)) {
    out.economicActions.push('DEX_TRADE');
    // Route classification: which execution venue(s) actually filled this
    // trade, detected purely from ledger metadata (see _txTouchesAmm above).
    const touchesAmm = _txTouchesAmm(meta);
    const touchesOffer = _txTouchesOfferNode(meta);
    out.route = _classifyExecutionRoute(touchesAmm, touchesOffer);
    out.economicActions.push(`ROUTE_${out.route}`);
  }

  return out;
}

/* ── Canonical Execution Record ──────────────────────
   One record per real trade execution this account was party to, with its
   route (CLOB/AMM/HYBRID) classified from ledger metadata — see
   _txTouchesAmm. This doesn't replace buildOfferLifecycles (which reasons
   about a specific OfferCreate's own lifecycle) or extractBalanceDeltas
   (per-transaction economic effect) — it's the aggregate view across an
   account's whole history: how much of this account's trading actually ran
   through the order book vs. an AMM pool vs. both in the same transaction.
   Payment-with-Paths trades are included since a cross-currency payment can
   execute against the same venues as an OfferCreate. */
function buildExecutionLedger(txList, addr) {
  const executions = [];
  for (const { tx, meta } of txList) {
    if (meta?.TransactionResult !== 'tesSUCCESS') continue;
    if (tx.TransactionType !== 'OfferCreate' && tx.TransactionType !== 'Payment') continue;
    const delta = extractBalanceDeltas(tx, meta, addr);
    if (!delta.route) continue;
    executions.push({
      hash: tx.hash, date: tx.date, type: tx.TransactionType, route: delta.route,
      xrpDelta: delta.xrpDelta, tokenDeltas: delta.tokenDeltas,
    });
  }
  const total = executions.length;
  const clob = executions.filter(e => e.route === 'CLOB').length;
  const amm = executions.filter(e => e.route === 'AMM').length;
  const hybrid = executions.filter(e => e.route === 'HYBRID').length;
  const unknown = total - clob - amm - hybrid;
  return {
    executions,
    stats: {
      total, clob, amm, hybrid, unknown,
      clobPct: total ? (clob / total) * 100 : 0,
      ammPct: total ? (amm / total) * 100 : 0,
      hybridPct: total ? (hybrid / total) * 100 : 0,
    },
  };
}

/* ── Execution Routing finding ───────────────────────
   Purely informational: surfaces the CLOB/AMM/HYBRID split so a reader (or
   another module) knows what kind of venue this account's trades actually
   ran through. This matters for wash-trading interpretation specifically —
   an AMM-routed trade executes against pooled liquidity contributed by many
   unrelated LPs, not a single counterparty's resting order, so it cannot be
   a two-party "wash" in the same sense a matched pair of order-book offers
   can be. */
function analyseExecutionRouting(executionLedger) {
  const { stats } = executionLedger;
  if (!stats.total) return { findings: [], stats };

  const parts = [];
  if (stats.clob) parts.push(`${stats.clob} matched against the order book (CLOB)`);
  if (stats.amm) parts.push(`${stats.amm} matched against an AMM pool`);
  if (stats.hybrid) parts.push(`${stats.hybrid} matched against both an AMM pool and the order book in the same transaction`);
  if (stats.unknown) parts.push(`${stats.unknown} could not be classified from available metadata`);

  const findings = [mkFinding({
    module: 'Execution Routing', category: 'market-integrity', sev: 'info', confidence: 0.9,
    headline: `${stats.total} trade execution(s): ${fmt(stats.clobPct, 0)}% CLOB, ${fmt(stats.ammPct, 0)}% AMM${stats.hybrid ? `, ${fmt(stats.hybridPct, 0)}% hybrid` : ''}`,
    detail: 'Classifies each executed trade (OfferCreate or cross-currency Payment) by whether it matched against a resting order-book offer, an AMM pool, or both — detected directly from ledger metadata, since an AMM pool\'s own AccountRoot always carries an AMMID field whenever a trade touches it.',
    observed: parts,
    classification: (stats.amm || stats.hybrid)
      ? 'AMM-routed executions trade against pooled liquidity contributed by many unrelated liquidity providers, not a single counterparty\'s resting order — a materially different structure from an order-book trade for wash-trading or counterparty analysis elsewhere in this report.'
      : 'All classified trades in this account\'s history executed against the central order book.',
  })];
  return { findings, stats };
}

/* ── Issuer Market Activity ───────────────────────────
   Aggregate CLOB/AMM/HYBRID trading activity ACROSS ALL HOLDERS of a token
   this account issues — not just this account's own trades. This is
   possible with zero additional RPC calls: XRPL has no direct holder-to-
   holder trustline for an issued currency — every trustline for that
   currency is between a holder and the issuer — so ANY transfer of the
   token between two arbitrary holders necessarily touches at least one
   RippleState node naming the issuer, and rippled's account_tx indexing
   already surfaces those transactions under the issuer's own history. This
   account's already-fetched txList therefore already contains the token's
   full (fetched-window) trading activity; extractBalanceDeltas just needs
   to be run with the ISSUER as the reference address instead of a trader's
   own address to see it. */
// Shared by analyseIssuerMarketActivity and buildOfferLifecycles — both
// independently re-typed this exact same "is this account's history
// complete enough to trust" check against the shared historyCoverage
// object's two completeness flags.
function _historyCompletenessLabel(coverage) {
  return (coverage.newestToOldestComplete || coverage.oldestToNewestFetched) ? 'complete' : 'possibly-truncated';
}

function analyseIssuerMarketActivity(txList, addr, lines, historyCoverage = {}) {
  const issuedCurrencies = [...new Set((lines || []).filter(l => Number(l.balance) < 0).map(l => l.currency))];
  if (!issuedCurrencies.length) return { applicable: false, findings: [] };

  const currencySet = new Set(issuedCurrencies);
  const dataCompleteness = _historyCompletenessLabel(historyCoverage);

  const trades = [];
  const holderSet = new Set();
  // Per-holder GROSS amount sold, across every settled trade seen — zero
  // extra RPC calls, since this reuses the exact same extractBalanceDeltas
  // pass already run for volume/routing above. Deliberately GROSS, not a
  // running net total: a holder who received a large distribution and later
  // sold only part of it would still show net-POSITIVE (still holding more
  // than they started with) under a pure running net sum, invisibly hiding
  // real selling activity behind an earlier receipt. Summing only the
  // decreasing legs answers "how much has this wallet sold, in total" —
  // exactly the "seller" cohort question — regardless of what else it also
  // bought. A RippleState balance is stored from the ISSUER's own side of
  // the trustline, so a holder's position decreasing (selling — whether
  // redeeming to the issuer directly, or via a peer-to-peer/DEX/AMM trade
  // with another holder, which still touches both holders' own RippleState
  // entries) shows up here as the issuer's own delta trending POSITIVE for
  // that holder. Feeds the "seller" cohort in Holder Cohorts.
  const holderGrossSold = new Map();
  for (const { tx, meta } of txList) {
    if (meta?.TransactionResult !== 'tesSUCCESS') continue;
    if (tx.TransactionType !== 'OfferCreate' && tx.TransactionType !== 'Payment') continue;
    const delta = extractBalanceDeltas(tx, meta, addr);
    // tokenDeltas' `issuer` field is the OTHER party to the trustline —
    // when addr is the token's issuer, that other party is the actual
    // trading holder, not a second issuer.
    const relevant = delta.tokenDeltas.filter(d => currencySet.has(d.currency) && d.delta !== 0);
    if (!relevant.length) continue;
    for (const d of relevant) {
      holderSet.add(d.issuer);
      if (d.delta > 0) holderGrossSold.set(d.issuer, (holderGrossSold.get(d.issuer) || 0) + d.delta);
    }
    const touchesAmm = _txTouchesAmm(meta);
    const touchesOffer = _txTouchesOfferNode(meta);
    const route = _classifyExecutionRoute(touchesAmm, touchesOffer);
    const amount = relevant.reduce((s, d) => s + Math.abs(d.delta), 0);
    trades.push({ hash: tx.hash, date: tx.date, route, holders: relevant.map(d => d.issuer), amount });
  }

  const total = trades.length;
  const clob = trades.filter(t => t.route === 'CLOB').length;
  const amm = trades.filter(t => t.route === 'AMM').length;
  const hybrid = trades.filter(t => t.route === 'HYBRID').length;
  const unknown = total - clob - amm - hybrid;
  const stats = {
    total, clob, amm, hybrid, unknown,
    clobPct: total ? (clob / total) * 100 : 0,
    ammPct: total ? (amm / total) * 100 : 0,
    hybridPct: total ? (hybrid / total) * 100 : 0,
  };

  const findings = [];
  if (total > 0) {
    const currencyLabel = issuedCurrencies.map(hexToAscii).join('/');
    findings.push(mkFinding({
      module: 'Issuer Market Activity', category: 'market-integrity', sev: 'info',
      confidence: dataCompleteness === 'complete' ? 0.75 : 0.45,
      headline: `${total} settled trade(s) of ${currencyLabel} across ${holderSet.size} holder(s): ${fmt(stats.clobPct, 0)}% CLOB, ${fmt(stats.ammPct, 0)}% AMM${hybrid ? `, ${fmt(stats.hybridPct, 0)}% hybrid` : ''}`,
      detail: `Aggregate market activity for this account's issued currency across ALL holders trading it — not just this account's own trades. Reconstructed entirely from this account's own fetched transaction history: every trustline for an issued currency has the issuer as one of its two parties, so any transfer between two holders already appears here.`,
      observed: [
        `${total} settled trade(s) found in the fetched transaction history`,
        `${holderSet.size} distinct holder address(es) involved`,
        dataCompleteness === 'complete'
          ? 'Based on this account\'s complete fetched transaction history'
          : 'Transaction history may be truncated — this reflects only the fetched window, not necessarily this token\'s full lifetime trading activity',
      ],
      alternativeExplanations: ['Normal organic trading among holders', 'Coordinated or self-directed trading among related wallets — cannot be distinguished from this data alone without a wallet-relationship analysis'],
      classification: 'This reflects trading among the token\'s holders generally, not this issuer account\'s own trading activity — see Execution Routing in Market & DEX Activity for this account\'s own trades, if any.',
      ownerImpact: 'None directly — this describes market activity by third parties in the issuer\'s token, not the issuer\'s own funds.',
      externalImpact: 'Describes how this token is actually trading in aggregate (order-book vs. AMM-pool liquidity) — useful context for holders assessing where real liquidity for this token sits.',
    }));
  }

  return { applicable: true, issuedCurrencies, dataCompleteness, stats, holderCount: holderSet.size, findings, trades, holderGrossSold };
}

/* ── Holder Cohort Intelligence ───────────────────────
   Who currently holds the most (Top Holders — reuses
   analyseIssuerConnections' already-computed list, not recomputed here),
   who received the token earliest within the fetched history (Early
   Holders — new, from TrustSet history), and who provides pool liquidity
   (LP Holders — new, from a single targeted account_lines call on the AMM
   pool account). Then: how much of the token's aggregate trading volume
   (from analyseIssuerMarketActivity) did each cohort actually generate.
   Deliberately does NOT sum cohort percentages together — cohorts overlap
   (a wallet can be both an early holder and a top holder), matching this
   session's established false-equivalence discipline. */
function analyseHolderCohorts(txList, addr, historyCoverage, issuerConnAnalysis, issuerMarketActivity, issuerAmmPool) {
  if (!issuerMarketActivity?.applicable) return { applicable: false, findings: [] };
  const currencySet = new Set(issuerMarketActivity.issuedCurrencies);

  // ── Top Holders — reuse, don't recompute ────────────────────────────────
  const topHolders = (issuerConnAnalysis?.topHolders || []).slice(0, 25);
  const totalIssued = issuerConnAnalysis?.totalIssued || 0;
  const isSampleOnly = !!issuerConnAnalysis?.isSampleOnly;

  // ── Early Holders — first-seen TrustSet to this issuer's currency ───────
  const firstSeen = new Map();
  for (const { tx } of txList) {
    if (tx.TransactionType !== 'TrustSet') continue;
    const limit = tx.LimitAmount;
    if (typeof limit !== 'object' || limit.issuer !== addr || !currencySet.has(limit.currency)) continue;
    if (!tx.Account) continue;
    const prev = firstSeen.get(tx.Account);
    if (prev == null || tx.date < prev) firstSeen.set(tx.Account, tx.date);
  }
  const earlyHolders = [...firstSeen.entries()]
    .sort((a, b) => a[1] - b[1])
    .slice(0, 25)
    .map(([holderAddr, date]) => ({ addr: holderAddr, firstSeenDate: date }));
  const earlyHolderCoverageComplete = !!historyCoverage?.oldestToNewestFetched;

  // ── LP Holders — from the pool's own account_lines, when a pool exists ──
  let lpHolders = [];
  let lpTotalSupply = 0;
  if (issuerAmmPool?.lpHolderLines?.length) {
    const rawLp = issuerAmmPool.lpHolderLines
      .map(l => ({ addr: l.account, lpBalance: Math.abs(Number(l.balance)) }))
      .sort((a, b) => b.lpBalance - a.lpBalance);
    lpTotalSupply = rawLp.reduce((s, h) => s + h.lpBalance, 0);
    lpHolders = rawLp.slice(0, 25).map(h => ({ ...h, sharePct: lpTotalSupply ? (h.lpBalance / lpTotalSupply) * 100 : 0 }));
  }

  // ── Seller Holders — gross sellers, from data already fetched ───────────
  // Zero extra RPC calls: issuerMarketActivity.holderGrossSold already sums
  // each holder's decreasing-position legs (from the issuer's own trustline
  // view) across every settled trade in the fetched history, regardless of
  // who they traded with (issuer redemption, another holder peer-to-peer,
  // DEX, or AMM all touch this the same way). Deliberately GROSS rather
  // than a running net total — see the comment at holderGrossSold's
  // computation for why a net figure would hide a holder who received a
  // large distribution and later sold only part of it. Ranked by amount
  // sold, not trade count — one large sale matters more here than many
  // tiny ones.
  const grossSoldMap = issuerMarketActivity.holderGrossSold || new Map();
  const sellerHolders = [...grossSoldMap.entries()]
    .sort((a, b) => b[1] - a[1])
    .slice(0, 25)
    .map(([holderAddr, grossSold]) => ({ addr: holderAddr, grossSold }));

  // ── Cohort volume overlap ────────────────────────────────────────────────
  // A trade can involve more than one holder (two-sided settlement), so
  // membership checks below are inclusion tests, not partitions — cohort
  // percentages are not meant to be added across cohorts.
  const trades = issuerMarketActivity.trades || [];
  const totalTradeVolume = trades.reduce((s, t) => s + t.amount, 0);
  const totalTradeCount = trades.length;

  function cohortVolumeShare(cohortAddrs) {
    if (!cohortAddrs.size || !totalTradeCount) return null;
    let vol = 0, count = 0;
    for (const t of trades) {
      if (t.holders.some(h => cohortAddrs.has(h))) { vol += t.amount; count++; }
    }
    return {
      volumePct: totalTradeVolume ? (vol / totalTradeVolume) * 100 : 0,
      tradeCountPct: (count / totalTradeCount) * 100,
      tradeCount: count,
    };
  }

  const topHolderVolume = cohortVolumeShare(new Set(topHolders.map(h => h.addr)));
  const earlyHolderVolume = cohortVolumeShare(new Set(earlyHolders.map(h => h.addr)));
  const lpHolderVolume = cohortVolumeShare(new Set(lpHolders.map(h => h.addr)));

  const findings = [];
  if (topHolders.length || earlyHolders.length || lpHolders.length) {
    const topSupplyPct = totalIssued ? (topHolders.reduce((s, h) => s + h.balance, 0) / totalIssued) * 100 : null;
    const parts = [];
    if (topHolders.length) {
      parts.push(
        `Top ${topHolders.length} current holder(s)` +
        (topSupplyPct != null ? `: ${isSampleOnly ? '~' : ''}${fmt(topSupplyPct, 0)}% of ${isSampleOnly ? 'the visible sample' : 'total supply'}` : '') +
        (topHolderVolume ? `, generated ${fmt(topHolderVolume.volumePct, 0)}% of settled trade volume (${topHolderVolume.tradeCount} trade(s))` : ', no settled trades matched to this cohort in the fetched history')
      );
    }
    if (earlyHolders.length) {
      parts.push(
        `Earliest ${earlyHolders.length} holder(s)${earlyHolderCoverageComplete ? '' : ' (within fetched history only)'}` +
        (earlyHolderVolume ? `: generated ${fmt(earlyHolderVolume.volumePct, 0)}% of settled trade volume (${earlyHolderVolume.tradeCount} trade(s))` : ': no settled trades matched to this cohort in the fetched history')
      );
    }
    if (lpHolders.length) {
      parts.push(
        `${lpHolders.length} liquidity provider(s) of the ${hexToAscii(issuerAmmPool.currency)}/XRP pool` +
        (lpHolderVolume ? `: also generated ${fmt(lpHolderVolume.volumePct, 0)}% of settled trade volume as traders (${lpHolderVolume.tradeCount} trade(s))` : ': no settled trades matched to this cohort in the fetched history')
      );
    }
    if (sellerHolders.length) {
      const totalSold = sellerHolders.reduce((s, h) => s + h.grossSold, 0);
      parts.push(`${sellerHolders.length} seller(s) identified from settled trades, together selling ${fmt(totalSold, 0)} tokens out of their positions in the fetched history`);
    }

    findings.push(mkFinding({
      module: 'Holder Cohorts', category: 'market-integrity', sev: 'info', confidence: 0.5,
      headline: `Holder cohorts: ${topHolders.length} top, ${earlyHolders.length} early${lpHolders.length ? `, ${lpHolders.length} LP` : ''}${sellerHolders.length ? `, ${sellerHolders.length} seller` : ''}`,
      detail: 'Cohort supply/volume shares overlap — a wallet can belong to more than one cohort at once — so these percentages should not be added together across cohorts.',
      observed: parts,
      alternativeExplanations: ['Overlap between cohorts (e.g. an early holder who is also a current top holder, or a top holder who is also a net seller) is expected on its own and does not indicate coordination', 'A holder trimming part of a large position while remaining a top holder overall is ordinary portfolio management, not itself a red flag'],
      classification: 'Describes who currently holds the most, who received this token earliest (within the fetched history window), who provides pool liquidity, and whose aggregate settled trades reduced their own position — plus how much of the token\'s aggregate trading volume each group generated. This is holder/participation data, not a wash-trading conclusion by itself; see Issuer Market Activity and Execution Routing for trade-routing evidence.',
      applicability: earlyHolderCoverageComplete ? null : { applicable: true, reason: 'Early-holder ranking reflects only the fetched transaction history window, not confirmed to reach the token\'s true genesis — full oldest-to-newest history coverage was not established for this account.' },
    }));
  }

  // ── Overlap Matrix — every wallet appearing in 2+ cohorts ────────────────
  // A wallet belonging to several cohorts at once (e.g. an early holder who
  // is ALSO a top holder AND a net seller) deserves closer inspection than
  // any one cohort membership alone would suggest — not because overlap
  // itself proves anything, but because it's the concrete, checkable fact
  // an investigator would want surfaced rather than having to cross-
  // reference four separate lists by hand. Restricted to wallets in 2+
  // cohorts — single-cohort membership is just... being in that cohort, not
  // an "overlap" worth a row of its own.
  const cohortSets = {
    early: new Set(earlyHolders.map(h => h.addr)),
    top: new Set(topHolders.map(h => h.addr)),
    lp: new Set(lpHolders.map(h => h.addr)),
    seller: new Set(sellerHolders.map(h => h.addr)),
  };
  const allCohortAddrs = new Set([...cohortSets.early, ...cohortSets.top, ...cohortSets.lp, ...cohortSets.seller]);
  const overlapMatrix = [...allCohortAddrs]
    .map(a => ({
      addr: a,
      early: cohortSets.early.has(a), top: cohortSets.top.has(a), lp: cohortSets.lp.has(a), seller: cohortSets.seller.has(a),
      cohortCount: [cohortSets.early.has(a), cohortSets.top.has(a), cohortSets.lp.has(a), cohortSets.seller.has(a)].filter(Boolean).length,
    }))
    .filter(r => r.cohortCount >= 2)
    .sort((a, b) => b.cohortCount - a.cohortCount);

  return {
    applicable: true, topHolders, earlyHolders, lpHolders, lpTotalSupply, sellerHolders,
    earlyHolderCoverageComplete, totalIssued, isSampleOnly, overlapMatrix,
    cohortVolume: { top: topHolderVolume, early: earlyHolderVolume, lp: lpHolderVolume },
    findings,
  };
}

/** Splits an amm_info `amm` object's two reserve amounts into the XRP side
 *  and the token side — amounts come back as a plain drops string for XRP
 *  or an {currency,issuer,value} object for an IOU, in no guaranteed order. */
function _ammReserves(pool) {
  if (!pool) return null;
  const a1 = pool.amount, a2 = pool.amount2;
  const xrpAmount = typeof a1 === 'string' ? Number(a1) / 1e6 : typeof a2 === 'string' ? Number(a2) / 1e6 : null;
  const tokenAmount = typeof a1 === 'object' ? Number(a1.value) : typeof a2 === 'object' ? Number(a2.value) : null;
  const tokenCurrency = typeof a1 === 'object' ? a1.currency : typeof a2 === 'object' ? a2.currency : null;
  return { xrpAmount, tokenAmount, tokenCurrency };
}

/* ── LP ↔ Trader Overlap ──────────────────────────────
   Ranks this token's holders by their OWN settled trade volume (from
   Issuer Market Activity's per-trade holder attribution — no new data),
   then checks how many of the most active traders are also liquidity
   providers in the token's AMM pool. This is a market-STRUCTURE
   observation (LPs often trade their own pool as routine market-making),
   deliberately not framed as wash-trading evidence by itself. */
function analyseLpTraderOverlap(issuerMarketActivity, holderCohorts) {
  if (!issuerMarketActivity?.applicable || !holderCohorts?.applicable) return { applicable: false, findings: [] };
  const trades = issuerMarketActivity.trades || [];
  if (!trades.length || !holderCohorts.lpHolders?.length) return { applicable: false, findings: [] };

  const volumeByHolder = new Map();
  const tradeCountByHolder = new Map();
  let totalVolume = 0;
  for (const t of trades) {
    totalVolume += t.amount;
    for (const h of t.holders) {
      volumeByHolder.set(h, (volumeByHolder.get(h) || 0) + t.amount);
      tradeCountByHolder.set(h, (tradeCountByHolder.get(h) || 0) + 1);
    }
  }

  const MAJOR_TRADER_CAP = 25;
  const rankedTraders = [...volumeByHolder.entries()]
    .map(([holderAddr, volume]) => ({ addr: holderAddr, volume, tradeCount: tradeCountByHolder.get(holderAddr) || 0 }))
    .sort((a, b) => b.volume - a.volume);
  const majorTraders = rankedTraders.slice(0, MAJOR_TRADER_CAP);

  const lpAddrSet = new Set(holderCohorts.lpHolders.map(h => h.addr));
  const alsoLPs = majorTraders.filter(t => lpAddrSet.has(t.addr));
  const top10 = majorTraders.slice(0, 10);
  const top10AlsoLPs = top10.filter(t => lpAddrSet.has(t.addr));
  const lpTraderVolume = alsoLPs.reduce((s, t) => s + t.volume, 0);
  const lpTraderVolumePct = totalVolume ? (lpTraderVolume / totalVolume) * 100 : 0;

  const findings = [];
  if (majorTraders.length > 0) {
    const currencyLabel = hexToAscii(issuerMarketActivity.issuedCurrencies[0]);
    findings.push(mkFinding({
      module: 'LP / Trader Overlap', category: 'market-integrity', sev: 'info', confidence: 0.5,
      headline: `${alsoLPs.length} of ${majorTraders.length} major traders are also liquidity providers`,
      detail: `Compares ${currencyLabel}'s most active traders by settled volume against its AMM liquidity providers.`,
      observed: [
        `${majorTraders.length} distinct trading holder(s) ranked by settled trade volume`,
        `${alsoLPs.length} of them also hold LP tokens in the ${currencyLabel}/XRP pool`,
        `${top10AlsoLPs.length} of the top 10 traders by volume are also LPs`,
        `Traders who are also LPs generated ${fmt(lpTraderVolumePct, 0)}% of total settled trade volume`,
      ],
      alternativeExplanations: ['An LP actively trading against their own pool is common and often reflects routine, legitimate market-making, not manipulation'],
      classification: 'Overlap between liquidity provision and trading is a market-structure characteristic, not itself evidence of wash trading — see Wash Execution and Execution Routing for trade-authenticity evidence.',
    }));
  }

  return {
    applicable: true, majorTraders, alsoLpCount: alsoLPs.length, top10AlsoLpCount: top10AlsoLPs.length,
    lpTraderVolumePct, volumeByHolder: Object.fromEntries(volumeByHolder), tradeCountByHolder: Object.fromEntries(tradeCountByHolder),
    findings,
  };
}

function buildBalanceChangeSeries(txList, addr) {
  return txList.map(({ tx, meta }) => {
    const deltas = extractBalanceDeltas(tx, meta, addr);
    return {
      txHash: tx.hash, date: tx.date, type: tx.TransactionType,
      result: meta?.TransactionResult || null,
      xrpDelta: deltas.xrpDelta, tokenDeltas: deltas.tokenDeltas, lpDeltas: deltas.lpDeltas,
      economicActions: deltas.economicActions,
    };
  });
}

/* ── Balance History Reconstruction ──────────────────
   Walks backward from the account's CURRENT balance using the Balance
   Change Engine's per-transaction deltas. This is reliable for the recent
   tail of history regardless of whether pagination was truncated overall —
   Pass 1 always starts from "now" and pages backward, so a hitTxCap/
   hitPageCap truncation only ever cuts the OLDER boundary, never the
   recent end these drain-episode windows scan. The one thing that DOES
   matter here is historyCoverage.fetchErrorOccurred — a swallowed fetch
   failure could drop transactions from anywhere, including the recent tail.
──────────────────────────────────────────────────── */
function reconstructBalanceHistory(txList, addr, currentBalXrp) {
  const series = buildBalanceChangeSeries(txList, addr);
  let running = currentBalXrp;
  const out = new Array(series.length);
  for (let i = series.length - 1; i >= 0; i--) {
    const balanceAfter = running;
    running -= series[i].xrpDelta;
    out[i] = { ...series[i], balanceBefore: running, balanceAfter };
  }
  return out;
}

const DRAIN_WINDOW_SECONDS = [86400, 3 * 86400]; // 24h, 3d sliding windows
const DRAIN_TURNOVER_THRESHOLD = 0.5;             // >50% of opening balance turned over (gross outflow) — the trigger
const DRAIN_MIN_XRP        = 10;                  // ignore dust-level noise on tiny accounts

function _clamp01(n) { return Math.max(0, Math.min(1, n)); }

/** Classifies an already-computed episode into a behavioral bucket. Kept as
 *  a standalone, directly-testable function rather than inlined thresholds
 *  — see the plan's verification section for the specific edge cases
 *  (pure pass-through, genuine sweep, partial ambiguous outflow) this needs
 *  to get right. `actualDepletionPct` (bounded 0-1, based on opening vs.
 *  closing balance) drives severity; gross in/outflow only distinguishes
 *  WHY a high- or low-depletion episode looks the way it does. */
function classifyDrainEpisode({ grossOutflowXrp, grossInflowXrp, actualDepletionPct }) {
  const inflowRatio = grossOutflowXrp > 0 ? grossInflowXrp / grossOutflowXrp : 0;
  if (actualDepletionPct < 0.2 && inflowRatio >= 0.6) return 'pass-through';
  if (actualDepletionPct >= 0.5 && inflowRatio < 0.15) return 'sweep';
  if (actualDepletionPct >= 0.5) return 'potential-drain';
  return 'partial-outflow';
}

/** Sliding-window scan for periods of unusually large XRP turnover, then
 *  distinguishes real wealth loss from pass-through using the account's own
 *  balance trajectory rather than raw outflow volume. The trigger is gross
 *  turnover (catches both genuine drains AND pure pass-through activity,
 *  since both are worth surfacing) — actualDepletionPct, computed from
 *  opening vs. closing balance and clamped to [0,1], is what actually
 *  drives severity, and can never exceed 100% by construction the way a
 *  raw gross-outflow/opening-balance ratio could (a small-balance wallet
 *  that receives and forwards a large sum within the window used to be
 *  able to show outflow far exceeding its own opening balance — e.g.
 *  hundreds of thousands of percent — with nothing to prevent it).
 *  Independent of whether an auth-change transaction preceded it (that's
 *  recorded as a flag on the episode, not a prerequisite for detecting it —
 *  an owner-initiated drain with unchanged keys produces the same balance
 *  signature as a compromise-driven one). */
function findDrainEpisodes(balanceHistory, txList, addr, historyCoverage = {}) {
  const episodes = [];
  const n = balanceHistory.length;
  const authChangeTimes = txList
    .filter(({ tx }) => ['SetRegularKey', 'SignerListSet'].includes(tx.TransactionType))
    .map(({ tx }) => tx.date)
    .filter(t => t != null);

  for (const windowSec of DRAIN_WINDOW_SECONDS) {
    for (let i = 0; i < n; i++) {
      const start = balanceHistory[i];
      if (start.date == null || start.balanceBefore <= 0) continue;
      let grossOutflowXrp = 0, grossInflowXrp = 0;
      let peakBalanceXrp = start.balanceBefore;
      let j = i;
      while (j < n && balanceHistory[j].date != null && balanceHistory[j].date - start.date <= windowSec) {
        const e = balanceHistory[j];
        if (e.xrpDelta < 0) grossOutflowXrp += -e.xrpDelta;
        else if (e.xrpDelta > 0) grossInflowXrp += e.xrpDelta;
        if (e.balanceAfter > peakBalanceXrp) peakBalanceXrp = e.balanceAfter;
        j++;
      }
      const endIdx = Math.min(j, n) - 1;
      const openingBalanceXrp = start.balanceBefore;
      const closingBalanceXrp = balanceHistory[endIdx]?.balanceAfter ?? openingBalanceXrp;
      const grossTurnoverPct = openingBalanceXrp > 0 ? grossOutflowXrp / openingBalanceXrp : 0;
      // Bounded by construction: opening/closing are real balances (never
      // negative for XRP), so this ratio can't exceed 1 or go below 0.
      const actualDepletionPct = openingBalanceXrp > 0
        ? _clamp01((openingBalanceXrp - Math.min(closingBalanceXrp, openingBalanceXrp)) / openingBalanceXrp)
        : 0;
      const netOutflowXrp = grossOutflowXrp - grossInflowXrp;

      if (grossTurnoverPct >= DRAIN_TURNOVER_THRESHOLD && grossOutflowXrp > DRAIN_MIN_XRP) {
        episodes.push({
          windowSec, startDate: start.date, endDate: balanceHistory[endIdx]?.date ?? start.date,
          openingBalanceXrp, peakBalanceXrp, closingBalanceXrp,
          grossOutflowXrp, grossInflowXrp, netOutflowXrp,
          grossTurnoverPct, actualDepletionPct,
          classification: classifyDrainEpisode({ grossOutflowXrp, grossInflowXrp, actualDepletionPct }),
          startIdx: i, endIdx,
          triggeredByAuthChange: authChangeTimes.some(t => t <= start.date && start.date - t <= windowSec),
        });
      }
    }
  }

  // Collapse overlapping episodes to the single most severe one per time
  // region, so a slow multi-tx drain doesn't produce dozens of near-
  // duplicate entries. A real sliding window is scanned from every
  // transaction index AND across every window size in DRAIN_WINDOW_SECONDS
  // (e.g. 24h and 3d), so a single real event routinely produces several
  // candidates whose windows merely touch, sit a few seconds apart, or are
  // just a different-sized lens on the exact same underlying transactions
  // — not distinct events. Deliberately does NOT require matching windowSec
  // here: a transfer that happened within a single day gets caught by both
  // the 24h and 3d windows, describing the SAME event twice with "within
  // 24h" and "within 3d" as the only difference — confirmed live (identical
  // XRP amounts and depletion percentages reported under both labels for
  // the same account). Keep the most severe/most specific one (sorted by
  // depletion first, then by narrowest window — a tighter window covering
  // the same depletion is more precise information, not less).
  const EPISODE_MERGE_GAP_SEC = 300;
  episodes.sort((a, b) => b.actualDepletionPct - a.actualDepletionPct || a.windowSec - b.windowSec);
  const kept = [];
  for (const ep of episodes) {
    const overlaps = kept.some(k =>
      ep.startDate <= k.endDate + EPISODE_MERGE_GAP_SEC
      && ep.endDate   >= k.startDate - EPISODE_MERGE_GAP_SEC);
    if (!overlaps) kept.push(ep);
  }
  kept.sort((a, b) => a.startDate - b.startDate);

  const dataCompleteness = historyCoverage.fetchErrorOccurred ? 'possibly-incomplete' : 'complete';
  return kept.map(ep => ({ ...ep, dataCompleteness }));
}

// BASELINE_MIN_SAMPLE / computeAccountBaseline now live in shared-analysis.js
// (imported above, aliased to _computeAccountBaseline so the call sites
// below don't need to change).

/** Per-episode behavioral detail: new-recipient %, destination clustering,
 *  transfer-size anomaly vs. this account's own history, trust-line
 *  liquidation, and a DEX-conversion-preceding-withdrawal check — all
 *  computed from data already fetched, no extra RPC calls. */
function _enrichDrainEpisode(ep, balanceHistory, txList, addr) {
  const outbound = balanceHistory.slice(ep.startIdx, ep.endIdx + 1).filter(e => e.xrpDelta < 0);
  const outboundHashes = new Set(outbound.map(e => e.txHash));
  const outboundTxs = txList.filter(({ tx }) => outboundHashes.has(tx.hash) && tx.TransactionType === 'Payment');

  // New-recipient %: destinations never seen as a payment destination from
  // this account BEFORE the episode started.
  const priorDests = new Set(
    txList.filter(({ tx }) => tx.TransactionType === 'Payment' && tx.Account === addr && tx.date < ep.startDate)
      .map(({ tx }) => tx.Destination).filter(Boolean)
  );
  const episodeDests = [...new Set(outboundTxs.map(({ tx }) => tx.Destination).filter(Boolean))];
  const newDests = episodeDests.filter(d => !priorDests.has(d));
  const newRecipientPct = episodeDests.length ? newDests.length / episodeDests.length : null;

  // Destination clustering: known-entity breakdown + concentration on the top destination.
  const destTotals = new Map();
  for (const { tx } of outboundTxs) {
    const amt = typeof tx.Amount === 'string' ? Number(tx.Amount) / 1e6 : 0;
    destTotals.set(tx.Destination, (destTotals.get(tx.Destination) || 0) + amt);
  }
  const rankedDests = [...destTotals.entries()].sort((a, b) => b[1] - a[1]);
  const topDestShare = ep.grossOutflowXrp > 0 && rankedDests[0] ? rankedDests[0][1] / ep.grossOutflowXrp : null;
  const destEntities = rankedDests.map(([addr2, xrp]) => ({ addr: addr2, xrp, entity: getEntity(addr2) }));

  // Transfer-size anomaly: episode transfer sizes vs. this account's own
  // historical size baseline, computed from payments OUTSIDE the episode
  // window. Gated on the baseline's own sample-size applicability — a thin
  // history no longer produces a confident-looking anomaly claim.
  const baseline = _computeAccountBaseline(txList, addr, { excludeFrom: ep.startDate, excludeTo: ep.endDate });
  const median = arr => { const s = [...arr].sort((a, b) => a - b); return s.length ? s[Math.floor(s.length / 2)] : null; };
  const historicalMedian = baseline.medianXrp;
  const episodeSizes = outboundTxs.map(({ tx }) => Number(tx.Amount) / 1e6).filter(v => v > 0);
  const episodeMedian = median(episodeSizes);
  const transferSizeAnomaly = baseline.applicable && historicalMedian && episodeMedian ? episodeMedian / historicalMedian >= 5 : false;
  const exceedsOwnP95 = baseline.applicable && baseline.p95Xrp != null && episodeMedian != null ? episodeMedian > baseline.p95Xrp : false;

  // Trust-line liquidation: token balances that dropped sharply within the
  // episode window — a common precursor to converting to XRP and draining.
  const tokenDrops = new Map();
  for (const e of balanceHistory.slice(ep.startIdx, ep.endIdx + 1)) {
    for (const t of e.tokenDeltas) {
      if (t.delta >= 0) continue;
      const key = `${t.currency}.${t.issuer}`;
      tokenDrops.set(key, (tokenDrops.get(key) || 0) + -t.delta);
    }
  }
  const trustlineLiquidations = [...tokenDrops.entries()].map(([key, amount]) => ({ key, amount }));

  // DEX-conversion-preceding-withdrawal: a token→XRP conversion (negative
  // tokenDelta + positive xrpDelta in the same transaction) in the 48h
  // immediately before the episode, followed by this XRP outflow episode.
  const lookback = balanceHistory.filter(e => e.date != null && e.date < ep.startDate && ep.startDate - e.date <= 172800);
  const dexConversionPrecedingWithdrawal = lookback.some(e => e.xrpDelta > 0 && e.tokenDeltas.some(t => t.delta < 0));

  return { ...ep, newRecipientPct, newDestCount: newDests.length, episodeDestCount: episodeDests.length,
    topDestShare, destinations: destEntities.slice(0, 5), transferSizeAnomaly, historicalMedianXrp: historicalMedian, episodeMedianXrp: episodeMedian,
    exceedsOwnP95, baselineP95Xrp: baseline.p95Xrp, baselineSampleSize: baseline.sampleSize, baselineApplicable: baseline.applicable,
    trustlineLiquidations, dexConversionPrecedingWithdrawal, episodeHashes: [...outboundHashes] };
}

/* ─────────────────────────────
   Master render
──────────────────────────────── */
function renderAll(addr, acct, lines, offers, nfts, objects, txList, extraData = {}) {
  const {
    gatewayBalances = null, ammInfoMap = new Map(), destAgeMap = new Map(),
    walletAgeDays = null, walletCreatedTs = null, walletAgeVerified = false, walletActivationEvidence = null,
    accountLifetimeHistory = null,
    historyCoverage = null, liveOrderBook = null, issuerAmmPool = null,
    auctionPoolTxByAccount = new Map(), commonFunderByAddr = new Map(),
  } = extraData;
  const balXrp   = Number(acct.Balance || 0) / 1e6;
  const ownerCnt = Number(acct.OwnerCount || 0);
  const reserve  = 10 + ownerCnt * 2;
  const flags    = Number(acct.Flags || 0);
  const sequence = acct.Sequence ?? '—';

  // Extract sub-objects
  const signerLists    = objects.filter(o => o.LedgerEntryType === 'SignerList');
  const escrows        = objects.filter(o => o.LedgerEntryType === 'Escrow');
  const paychans       = objects.filter(o => o.LedgerEntryType === 'PayChannel');
  const depositAuths   = objects.filter(o => o.LedgerEntryType === 'DepositPreauth');
  const checks         = objects.filter(o => o.LedgerEntryType === 'Check');

  // ── Account role (computed first — several detectors below need it) ────
  // Role classification is deliberately narrow and evidence-gated rather
  // than trying to cover every role a full account-context model could:
  // "Token Issuer" is the one role this app can verify with real,
  // hard-to-accidentally-trigger on-ledger evidence (gateway_balances-
  // backed obligations require OTHER accounts to have deliberately
  // trusted this one first). Everything else defaults to being treated
  // as an ordinary personal/unknown account — never guessed into a
  // "project treasury," "exchange," or "market maker" role, since this
  // app has no project-disclosure registry, peer-group baselines, or
  // AMM pool-share-of-project data to support classifying those roles
  // with real evidence. Deliberately NOT based on NFT mint count: minting
  // even several NFTs is common, single-click behavior for an ordinary
  // individual and is not evidence of running a project/business.
  const issuerAnalysis     = analyseTokenIssuer(acct, lines, flags, txList);
  const isProjectAccount   = issuerAnalysis.isIssuer;
  // Aggregate market activity across ALL holders of this account's issued
  // token(s) — a different question from this account's OWN trades (that's
  // Execution Routing, below). Only meaningful for a confirmed issuer;
  // analyseIssuerMarketActivity exits immediately otherwise.
  const issuerMarketActivity = analyseIssuerMarketActivity(txList, addr, lines, historyCoverage);
  issuerAnalysis.signals.push(...issuerMarketActivity.findings);

  // ── Analysis passes ─────────────────────────────────────────────────────
  const securityAudit      = analyseSecurityPosture(acct, flags, signerLists, txList, historyCoverage, { offers, escrows, paychans, checks });
  const drainAnalysis      = analyseDrainRisk(acct, flags, signerLists, txList, paychans, escrows, addr, balXrp, historyCoverage, isProjectAccount);
  const nftAnalysis        = analyseNftRisk(nfts, txList, addr);
  const accountRoles       = analyseAccountRoles(lines, txList, addr, issuerAnalysis, nftAnalysis);
  const liveBookAnalysis   = analyseLiveOrderBook(liveOrderBook, addr);
  const offerLifecycles    = buildOfferLifecycles(txList, addr, historyCoverage || {});
  const fillRateAnalysis   = analyseOfferFillRate(offerLifecycles, addr);
  const executionLedger    = buildExecutionLedger(txList, addr);
  // Evidence family J (Auction-Group Relationship) needs to know, before
  // Spoofing runs, which currencies (if any) this account currently holds
  // or is authorized for the discounted-fee auction slot on. Computed
  // directly from ammInfoMap/issuerAmmPool (both available from the very
  // start of this function) rather than waiting for the full
  // ammGovernanceByPool pass below, which needs ammAnalysis.positions —
  // not yet computed at this point, and restructuring that dependency
  // order is riskier than this small, self-contained duplicate check.
  const auctionGroupCurrencies = new Set();
  for (const [currency, pool] of ammInfoMap.entries()) {
    const slot = pool?.auction_slot;
    if (slot && (slot.account === addr || (slot.auth_accounts || []).some(a => a.account === addr))) auctionGroupCurrencies.add(currency);
  }
  if (issuerAmmPool?.pool?.auction_slot) {
    const slot = issuerAmmPool.pool.auction_slot;
    if (slot.account === addr || (slot.auth_accounts || []).some(a => a.account === addr)) auctionGroupCurrencies.add(issuerAmmPool.currency);
  }
  const washAnalysis       = analyseWashTrading(txList, addr, lines, offerLifecycles, fillRateAnalysis, liveBookAnalysis, isProjectAccount, executionLedger, auctionGroupCurrencies);
  const ammAnalysis        = analyseAmmPositions(lines, txList, objects, ammInfoMap, addr);
  // AMM fee-voting + auction-slot governance — one entry per pool this
  // account has amm_info for (its own current LP positions, plus a
  // confirmed issuer's own paired pool), deduped by the pool's own
  // account address in case both sources point at the same pool.
  const ammGovernanceByPool = [];
  for (const p of ammAnalysis.positions) {
    const pool = ammInfoMap.get(p.currency);
    if (pool) ammGovernanceByPool.push({ currency: p.currency, poolAccount: pool.account, gov: analyseAmmGovernance(pool, addr) });
  }
  if (issuerAmmPool?.pool && !ammGovernanceByPool.some(g => g.poolAccount === issuerAmmPool.pool.account)) {
    ammGovernanceByPool.push({ currency: issuerAmmPool.currency, poolAccount: issuerAmmPool.pool.account, gov: analyseAmmGovernance(issuerAmmPool.pool, addr) });
  }
  for (const g of ammGovernanceByPool) ammAnalysis.signals.push(...buildAmmGovernanceFindings(g.gov, addr, hexToAscii(g.currency)));
  const ammBidHistory      = analyseAmmBidHistory(txList, addr);
  ammAnalysis.signals.push(...ammBidHistory.findings);
  // Auction-window market data — only computed for pools where the
  // targeted pool-tx-history fetch actually ran (i.e. an active auction
  // slot exists on a pool this account has amm_info for).
  for (const g of ammGovernanceByPool) {
    if (!g.gov.auctionSlot?.applicable) { g.auctionWindow = { applicable: false }; g.auctionDominance = { applicable: false }; continue; }
    const poolTxData = auctionPoolTxByAccount.get(g.poolAccount);
    g.auctionWindow = analyseAuctionWindowMarket(poolTxData, g.poolAccount, g.gov.auctionSlot);
    ammAnalysis.signals.push(...g.auctionWindow.findings);
    g.auctionDominance = analyseAuctionDominance(poolTxData);
    ammAnalysis.signals.push(...g.auctionDominance.findings);
    g.auctionEconomics = analyseAuctionEconomics(g.gov, g.auctionWindow);
    ammAnalysis.signals.push(...g.auctionEconomics.findings);
  }
  const benfordsAnalysis   = analyseBenfordsLaw(txList);
  const volConcAnalysis    = analyseVolumeConcentration(txList, addr);

  // ── Forensic Analytics Suite (4 new engines) ────────────────────────────
  const entropyAnalysis    = analyseShannonsEntropy(txList, addr);
  const zipfAnalysis       = analyseZipfsLaw(txList, addr);
  const timeSeriesAnalysis = analyseTimeSeries(txList);
  const grangerAnalysis    = analyseGrangerCausality(txList, addr);

  // ── New deep analysis ────────────────────────────────────────────────────
  const fundFlowAnalysis      = analyseFundFlow(txList, addr, destAgeMap);
  const feeAnalysis           = analyseFeeSpikePattern(txList);
  const destTagAnalysis       = analyseDestTagPatterns(txList, addr);
  const pathDepthAnalysis     = analysePathPaymentDepth(txList, addr);
  const issuerConnAnalysis    = analyseIssuerConnections(txList, addr, lines, gatewayBalances, commonFunderByAddr);
  const holderCohorts         = analyseHolderCohorts(txList, addr, historyCoverage, issuerConnAnalysis, issuerMarketActivity, issuerAmmPool);
  issuerAnalysis.signals.push(...holderCohorts.findings);
  const lpTraderOverlap       = analyseLpTraderOverlap(issuerMarketActivity, holderCohorts);
  issuerAnalysis.signals.push(...lpTraderOverlap.findings);
  // AMM Control Surface — needs holderCohorts/lpTraderOverlap, which
  // aren't computed until here, so this runs as its own pass over the
  // pools already identified above rather than inside that earlier loop.
  // holderCohorts/lpTraderOverlap are ALWAYS scoped to this account's own
  // issued currency (issuerAmmPool specifically) — only attach them to
  // THAT pool's entry; a different pool this account merely holds an
  // unrelated LP position in has no holder-cohort/trader-volume data
  // available and must not borrow the issuer pool's by mistake.
  for (const g of ammGovernanceByPool) {
    const isIssuerPool = issuerAmmPool?.pool && g.poolAccount === issuerAmmPool.pool.account;
    g.controlSurface = analyseAmmControlSurface(g.gov, isIssuerPool ? holderCohorts : null, g.auctionDominance, isIssuerPool ? lpTraderOverlap : null);
    ammAnalysis.signals.push(...g.controlSurface.findings);
  }
  const inboundFlowAnalysis   = analyseInboundFlow(txList, addr);
  const memoAnalysis          = analyseMemos(txList, addr);
  const memoDrainCorrelation  = analyseMemoDrainCorrelation(memoAnalysis, drainAnalysis, addr, isProjectAccount);
  memoAnalysis.signals.push(...memoDrainCorrelation.signals);
  const escrowDepthAnalysis   = analyseEscrowDepth(objects, txList, addr);
  const checkAnalysis         = analyseChecks(objects);

  // Overall risk score (0–100)
  const riskScore = computeOverallRisk(securityAudit, drainAnalysis, nftAnalysis, washAnalysis, benfordsAnalysis, volConcAnalysis, entropyAnalysis, zipfAnalysis, timeSeriesAnalysis, grangerAnalysis, feeAnalysis);

  const behaviorProfile = buildAccountBehaviorProfile(addr, txList, lines, accountRoles, issuerAnalysis, ammAnalysis, nftAnalysis, washAnalysis, offerLifecycles, walletAgeDays, historyCoverage, securityAudit);
  const ledgerMapBreakdown = buildLedgerInteractionBreakdown(txList, addr, {
    dexMarkets: behaviorProfile.footprint.dexMarkets,
    ammPools: behaviorProfile.footprint.ammPools,
    ammPoolsHistorical: behaviorProfile.footprint.ammPoolsHistorical,
    nftCount: nftAnalysis.nftCount,
    nftMintCount: nftAnalysis.mintCount,
  });
  const accountJourney = buildAccountJourney(txList, addr, walletCreatedTs, walletAgeVerified, walletActivationEvidence);
  const followTheMoney = buildFollowTheMoneyNarrative(fundFlowAnalysis, inboundFlowAnalysis, drainAnalysis.episodes, addr);
  const flowMotifs = detectFlowMotifs(txList, addr);

  // ── Render sections ──────────────────────────────────────────────────────
  renderAccountBehaviorExplorer(behaviorProfile, accountJourney, followTheMoney);
  renderHeader(addr, acct, balXrp, reserve, ownerCnt, sequence, riskScore, walletAgeDays, walletCreatedTs, walletAgeVerified, walletActivationEvidence, accountLifetimeHistory);
  renderSecurityAudit(securityAudit, acct, flags, signerLists, depositAuths, txList, addr, drainAnalysis.episodes, historyCoverage);
  renderDrainAnalysis(drainAnalysis, paychans, escrows, checks, fundFlowAnalysis);
  renderFundFlowPanel(fundFlowAnalysis, balXrp, inboundFlowAnalysis);
  renderFlowMotifsPanel(flowMotifs);
  renderNftPanel(nftAnalysis, nfts);
  renderWashPanel(washAnalysis);
  renderBenfordsPanel(benfordsAnalysis);
  renderVolConcPanel(volConcAnalysis);
  renderEntropyPanel(entropyAnalysis);
  renderZipfPanel(zipfAnalysis);
  renderTimeSeriesPanel(timeSeriesAnalysis);
  renderGrangerPanel(grangerAnalysis);
  renderForensicSuitePanel(benfordsAnalysis, entropyAnalysis, zipfAnalysis, timeSeriesAnalysis, grangerAnalysis);
  renderIssuerPanel(issuerAnalysis, lines, holderCohorts, issuerAmmPool);
  renderIssuerConnectionsPanel(issuerConnAnalysis, lines);
  renderDistMarketFlowPanel(issuerAnalysis, issuerConnAnalysis, issuerMarketActivity, holderCohorts);
  renderFeeAnalysisPanel(feeAnalysis);
  renderDestTagPanel(destTagAnalysis);
  renderPathDepthPanel(pathDepthAnalysis);
  renderAmmPanel(ammAnalysis, lines, ammGovernanceByPool, ammBidHistory);
  renderInboundFlowPanel(inboundFlowAnalysis);
  renderMemoPanel(memoAnalysis);
  renderEscrowDepthPanel(escrowDepthAnalysis);
  renderCheckPanel(checkAnalysis);
  renderLiveBookPanel(liveBookAnalysis);
  renderRiskBreakdown(riskScore, securityAudit, drainAnalysis, nftAnalysis, washAnalysis,
    benfordsAnalysis, volConcAnalysis, entropyAnalysis, zipfAnalysis, timeSeriesAnalysis,
    grangerAnalysis, feeAnalysis, inboundFlowAnalysis, memoAnalysis);
  renderTrustlines(lines);
  renderTxTimeline(txList, addr);
  renderActivityTimeline(txList);
  _renderWhoIsConnected(buildWhoIsConnectedSummary(txList, addr, flowMotifs));
  renderRelationshipLandscape(txList, addr, issuerConnAnalysis.mirrorGroups, inboundFlowAnalysis);
  renderLedgerInteractionMap(ledgerMapBreakdown);

  // ── Full Report section (always rendered last) ───────────────────────────
  // Cache txList so the CSV export button in the report can access it
  window._lastTxList = txList;
  window._lastBalXrp = balXrp;
  window._lastHistoryCoverage = historyCoverage;

  const reportContainer = $('inspect-report-body');
  if (reportContainer) {
    renderFullReport(
      reportContainer,
      addr, acct, balXrp, riskScore,
      securityAudit, drainAnalysis, nftAnalysis, washAnalysis,
      benfordsAnalysis, volConcAnalysis, issuerAnalysis,
      ammAnalysis, fundFlowAnalysis, issuerConnAnalysis, txList,
      entropyAnalysis, zipfAnalysis, timeSeriesAnalysis, grangerAnalysis,
      { feeAnalysis, destTagAnalysis, pathDepthAnalysis, gatewayBalances,
        inboundFlowAnalysis, memoAnalysis, escrowDepthAnalysis, checkAnalysis,
        liveBookAnalysis, walletAgeDays, walletCreatedTs, walletAgeVerified, walletActivationEvidence, historyCoverage }
    );
    // Same activity chart as the Account Overview section above, mounted a
    // second time into the report's own placeholder div — the report was
    // previously text-only. The counterparty breakdown is generated inline
    // as a ranked list within generateFullReport() itself (not this radial
    // network map, which stays exploratory-only in Account Overview).
    renderActivityTimeline(txList, 'inspect-report-activity-chart');
    // Quick verdict uses allFindings which are now cached
    renderQuickVerdict(riskScore, window._lastAllFindings || [], walletAgeDays, txList.length, window._lastCategoryRisk || {}, walletAgeVerified, historyCoverage, issuerAnalysis, accountRoles);
    _renderDataQualityStrip(computeDataQualitySummary(historyCoverage, executionLedger, issuerAmmPool, issuerAnalysis.isIssuer));
    renderImportantEventsTimeline(buildImportantEventsTimeline(
      buildSecurityTimeline(securityAudit.controlState || {}, txList, addr, drainAnalysis.episodes),
      drainAnalysis.episodes, feeAnalysis
    ));
    renderEvidenceMatrix(window._lastAllFindings || []);
    _applySmartCollapseDefaults();
    _syncNavStatusDots();
    // Cache full result for JSON export
    window._lastInspectResult = {
      addr, riskScore, walletAgeDays, walletAgeVerified, historyCoverage, txCount: txList.length,
      findings: window._lastAllFindings || [],
      timestamp: new Date().toISOString(),
    };
    // Init analyst mode and watchlist button
    _initAnalystMode();
    _renderWatchBtn(addr);
  }
}


/* ── Fund Flow Tracer ────────────────────────────── */
function analyseFundFlow(txList, addr, destAgeMap = new Map()) {
  const destinations = new Map();
  const drainSeq     = [];

  for (const { tx, meta } of txList) {
    if (tx.TransactionType !== 'Payment') continue;
    if (tx.Account !== addr) continue; // outbound only

    const dest = tx.Destination;
    if (!dest) continue;

    const { amtXrp, amtToken } = _extractPaymentAmount(tx, meta);

    // Path payment detection
    const hasPaths  = Array.isArray(tx.Paths) && tx.Paths.length > 0;
    const hasSendMax = tx.SendMax != null;
    const isPathPay  = hasPaths || hasSendMax;

    // Hop count from Paths
    const hopCount = hasPaths
      ? tx.Paths.reduce((mx, p) => Math.max(mx, (p || []).length + 1), 1)
      : (isPathPay ? 2 : 1);

    const ts  = getCloseTime(tx);
    const rec = { dest, amtXrp, amtToken, ts, isPathPay, hopCount, hash: tx.hash || tx.Hash || '', ledger: tx.ledger_index || tx.LedgerIndex || 0, destTag: tx.DestinationTag };

    drainSeq.push(rec);

    if (!destinations.has(dest)) {
      destinations.set(dest, {
        addr: dest,
        totalXrp:  0,
        txCount:   0,
        firstSeen: ts,
        lastSeen:  ts,
        entity:    getEntity(dest) || null,
        pathCount: 0,
        maxHops:   1,
        tokens:    new Map(),
        hashes:    [],
        hasUnknownAmount: false,
      });
    }
    const d = destinations.get(dest);
    // amtXrp is explicitly null (not 0/NaN) for a payment whose delivered
    // amount couldn't be determined — excluded from the sum rather than
    // poisoning it, with hasUnknownAmount flagging that this destination's
    // total may understate what it actually received.
    if (amtXrp != null) d.totalXrp += amtXrp; else d.hasUnknownAmount = true;
    d.txCount++;
    if (rec.hash) d.hashes.push(rec.hash);
    d.lastSeen   = Math.max(d.lastSeen, ts);
    d.firstSeen  = Math.min(d.firstSeen, ts);
    if (isPathPay) { d.pathCount++; d.maxHops = Math.max(d.maxHops, hopCount); }
    if (amtToken) {
      const k = `${amtToken.currency}.${shortAddr(amtToken.issuer || '')}`;
      d.tokens.set(k, (d.tokens.get(k) || 0) + amtToken.value);
    }
  }

  const topDests = [...destinations.values()]
    .sort((a, b) => b.totalXrp - a.totalXrp || b.txCount - a.txCount)
    .slice(0, 10)
    .map(d => ({ ...d, tokens: [...d.tokens.entries()].map(([k, v]) => ({ k, v })) }));

  const totalOut    = topDests.reduce((s, d) => s + d.totalXrp, 0);
  const totalPathPay = drainSeq.filter(o => o.isPathPay).length;
  const unknownAmountCount = [...destinations.values()].filter(d => d.hasUnknownAmount).length;

  // This account's own lifetime outbound-Payment size profile — lets a
  // destination's received amount be judged against what's actually typical
  // for THIS account, not an arbitrary fixed XRP threshold. Computed once,
  // unexcluded, only as a fallback sample-size check; the real per-destination
  // comparisons below each recompute it excluding that destination (see
  // newWalletDests) so a flagged transfer can never inflate its own baseline.
  const baseline = _computeAccountBaseline(txList, addr);

  // Counterparty age flags: new wallets receiving large amounts are drain mules
  const newWalletDests = topDests.filter(d => {
    const age = destAgeMap.get(d.addr);
    return age && age.sequence < 10 && d.totalXrp > 10;
  }).map(d => {
    // Excludes this destination's own payments so a large one-shot transfer
    // can't count itself into the "typical" size it's being compared against.
    const ownBaseline = _computeAccountBaseline(txList, addr, { excludeDest: d.addr });
    // Compare per-payment average, not the raw sum — d.totalXrp can be many
    // small payments to the same destination, which isn't the same claim as
    // "one transfer was Nx typical size".
    const avgPerPayment = d.txCount > 0 ? d.totalXrp / d.txCount : d.totalXrp;
    const shareOfTotalOut = totalOut > 0 ? d.totalXrp / totalOut : null;
    return {
      ...d,
      avgPerPayment,
      shareOfTotalOut,
      baselineSampleSize: ownBaseline.sampleSize,
      baselineApplicable: ownBaseline.applicable,
      sizeAnomalyMultiple: ownBaseline.applicable && ownBaseline.medianXrp ? avgPerPayment / ownBaseline.medianXrp : null,
      exceedsOwnP95: ownBaseline.applicable && ownBaseline.p95Xrp != null ? avgPerPayment > ownBaseline.p95Xrp : false,
      // Fallback signal for accounts too thin-history for a size baseline:
      // did this one new destination absorb most of everything this account
      // has sent out? That's meaningful regardless of per-payment history.
      dominatesOutflow: !ownBaseline.applicable && shareOfTotalOut != null && shareOfTotalOut >= 0.5,
    };
  });

  // Known-exchange destinations
  const exchangeDests = topDests.filter(d => d.entity?.type === 'exchange');
  const blackHoleDests= topDests.filter(d => d.entity?.type === 'blackhole');

  // Timeline — sort chronologically, cap at 30
  const timeline = [...drainSeq]
    .filter(o => o.amtXrp > 0.01 || o.amtToken)
    .sort((a, b) => a.ts - b.ts)
    .slice(0, 30);

  // Evidence-model findings — replaces three flat push() calls that used to
  // bypass the observed/calculated/inferred/hypothesis split every other
  // module already goes through.
  const signals = [];
  if (blackHoleDests.length) {
    signals.push(mkFinding({
      module: 'Fund Flow', category: 'counterparty', sev: 'critical', confidence: 0.95,
      headline: `Funds sent to ${blackHoleDests.length} black hole address(es)`,
      detail: 'These funds are permanently irrecoverable.',
      observed: blackHoleDests.map(d => `${fmt(d.totalXrp, 2)} XRP sent to ${shortAddr(d.addr)} across ${d.txCount} payment(s)`),
      classification: 'Black-hole addresses (no known private key, e.g. the XRPL "black hole" account) cannot return funds under any circumstance — this is a ledger-verifiable fact, not an inference.',
      hashes: blackHoleDests.flatMap(d => d.hashes),
    }));
  }
  if (exchangeDests.length) {
    signals.push(mkFinding({
      module: 'Fund Flow', category: 'counterparty', sev: 'info', confidence: 0.9,
      headline: `${exchangeDests.length} known exchange(s) received funds`,
      detail: exchangeDests.map(d => d.entity.name).join(', '),
      observed: exchangeDests.map(d => `${fmt(d.totalXrp, 2)} XRP sent to ${d.entity.name} (${shortAddr(d.addr)})`),
      classification: 'Routine off-ramp activity — receiving funds at a known, labeled exchange address is not itself a risk signal.',
      hashes: exchangeDests.flatMap(d => d.hashes),
    }));
  }
  for (const d of newWalletDests) {
    const sizeAnomaly = d.exceedsOwnP95 || (d.sizeAnomalyMultiple != null && d.sizeAnomalyMultiple >= 5);
    const strongEvidence = sizeAnomaly || d.dominatesOutflow;
    const perPaymentLabel = d.txCount > 1 ? `${fmt(d.avgPerPayment, 2)} XRP average per payment` : `${fmt(d.avgPerPayment, 2)} XRP`;
    signals.push(mkFinding({
      module: 'Fund Flow', category: 'counterparty',
      sev: strongEvidence ? 'critical' : 'warn',
      confidence: d.baselineApplicable ? 0.6 : (d.dominatesOutflow ? 0.5 : 0.4),
      headline: `Brand-new wallet received ${fmt(d.totalXrp, 2)} XRP`,
      detail: 'New wallets (ledger Sequence < 10) receiving large amounts are a classic drain-mule pattern.',
      observed: [
        `Destination ${shortAddr(d.addr)} has a ledger Sequence of ${destAgeMap.get(d.addr)?.sequence ?? '?'} (fewer than 10 transactions ever sent from it)`,
        `${fmt(d.totalXrp, 2)} XRP sent across ${d.txCount} payment(s)`,
      ],
      calculated: [
        d.shareOfTotalOut != null ? `${(d.shareOfTotalOut * 100).toFixed(0)}% of this account's total tracked outflow went to this single new destination` : null,
        d.sizeAnomalyMultiple != null ? `Payments to this destination average ${d.sizeAnomalyMultiple.toFixed(1)}x this account's own historical median payment size (${perPaymentLabel}, based on ${d.baselineSampleSize} prior payments to other destinations)` : null,
        d.exceedsOwnP95 ? `Exceeds this account's own 95th-percentile historical transfer size` : null,
        !d.baselineApplicable ? `This account has only ${d.baselineSampleSize} prior outbound payment(s) to other destinations — not enough history for a reliable size comparison` : null,
        d.dominatesOutflow ? `Absent a size baseline, this one new destination alone accounts for the majority of this account's entire tracked outflow` : null,
      ].filter(Boolean),
      inferred: strongEvidence
        ? ['This transfer is unusual both in destination novelty and in size relative to this account\'s own established behavior']
        : [],
      hypothesis: strongEvidence
        ? 'May represent a drain to a freshly created mule wallet, though a large one-time legitimate transfer to a new personal or exchange-deposit wallet remains equally consistent with the same ledger evidence.'
        : null,
      alternativeExplanations: [
        'A newly created personal wallet, or a fresh exchange deposit address (many exchanges rotate deposit addresses per user/transaction)',
        'A one-time large legitimate transfer unrelated to any compromise',
      ],
      evidenceAgainstBenign: !d.baselineApplicable && !d.dominatesOutflow ? ['Insufficient payment history on this account to say whether this size or destination pattern is actually unusual for it'] : [],
      classification: 'Wallet age (ledger Sequence) is an objective, ledger-verifiable fact; whether the transfer itself was authorized cannot be determined from flow data alone — see Drain Risk above for signing-authority context.',
      hashes: d.hashes,
    }));
  }

  return {
    timeline,
    destinations: topDests,
    totalOut,
    totalPathPay,
    uniqueDests: destinations.size,
    exchangeDests,
    blackHoleDests,
    newWalletDests,
    baseline,
    signals,
    unknownAmountCount,
  };
}

/* ── Issuer Connection Analysis ──────────────────── */
/* Shared with the async common-funder lookup pre-step in the main inspect
   flow (which needs the same candidate groups BEFORE analyseIssuerConnections
   runs, to know which addresses are worth an extra per-wallet account_tx
   fetch) — extracted so both call sites walk the issuer's tx history and
   bucket by amount exactly once, instead of drifting into two slightly
   different copies of the same grouping logic. */
function _buildIssuerDistributionMap(txList, addr, lines) {
  const distributions = new Map(); // destAddr → total tokens received from issuer
  const receiveTime  = new Map();
  const createdAccts = new Set();

  const issuedCurrencies = new Set(
    lines.filter(l => Number(l.balance) < 0).map(l => hexToAscii(l.currency))
  );

  for (const { tx, meta } of txList) {
    if (tx.Account !== addr) continue;

    if (tx.TransactionType === 'Payment') {
      const created = meta?.AffectedNodes?.some?.(n =>
        n.CreatedNode?.LedgerEntryType === 'AccountRoot' &&
        n.CreatedNode?.NewFields?.Account === tx.Destination
      );
      if (created && tx.Destination) createdAccts.add(tx.Destination);

      const amt = tx.Amount;
      if (typeof amt === 'object' && amt?.value && amt?.currency) {
        const curr = hexToAscii(amt.currency);
        if (issuedCurrencies.has(curr)) {
          const val = Number(amt.value);
          const dest = tx.Destination;
          if (!distributions.has(dest)) {
            distributions.set(dest, 0);
            receiveTime.set(dest, tx.date);
          }
          distributions.set(dest, distributions.get(dest) + val);
        }
      }
    }
  }
  return { distributions, receiveTime, createdAccts };
}

/* Buckets distribution amounts by order-of-magnitude + nearest 10%, keeping
   only groups of 3+ — the candidate "mirror groups" both the async
   common-funder pre-step and analyseIssuerConnections's confidence scoring
   operate on. */
function _bucketDistributionsByAmount(distributions) {
  const distEntries = [...distributions.entries()].sort((a, b) => b[1] - a[1]);
  const buckets = new Map();
  for (const [a2, amt] of distEntries) {
    if (amt <= 0) continue;
    const mag    = Math.pow(10, Math.floor(Math.log10(amt)));
    const bucket = Math.round(amt / mag / 0.1) * 0.1 * mag;
    const key    = bucket.toPrecision(2);
    if (!buckets.has(key)) buckets.set(key, []);
    buckets.get(key).push({ addr: a2, amt });
  }
  return [...buckets.values()].filter(group => group.length >= 3);
}

function analyseIssuerConnections(txList, addr, lines, gatewayBalances = null, commonFunderByAddr = new Map()) {
  // Extract true total supply from gateway_balances if available.
  // gateway_balances.obligations is { currency: totalAmount, ... }
  let _gatewayTotal = null;
  if (gatewayBalances?.obligations) {
    const vals = Object.values(gatewayBalances.obligations);
    if (vals.length === 1) {
      _gatewayTotal = Number(vals[0]) || null;
    } else if (vals.length > 1) {
      // Multiple currencies — can't sum across currencies, leave as null
      _gatewayTotal = null;
    }
  }
  const signals      = [];
  const { distributions, receiveTime, createdAccts } = _buildIssuerDistributionMap(txList, addr, lines);

  // ── Mirror wallet detection (accounts receiving similar amounts) ──────────
  // Confidence tiers, not a flat detected/not-detected flag: amount
  // similarity ALONE is a weak signal — round-number airdrops, fixed-price
  // sales, and independent users choosing common amounts all produce this
  // with zero coordination. Corroborating it with INDEPENDENT signals about
  // this SPECIFIC group of accounts (funded together in a narrow window;
  // directly created by the issuer itself; OR — the 4th family, backed by
  // real per-wallet AccountRoot creation evidence fetched just for this
  // group — sharing one common THIRD-PARTY funder when the issuer didn't
  // create them directly) raises confidence — the same "more independent
  // families agreeing = stronger evidence" corroboration model already used
  // for Spoofing elsewhere in this file. Timing here is computed PER GROUP
  // (only that group's own receive timestamps), not the old global "any 10
  // accounts funded within an hour" check, which could never actually tell
  // you WHICH group the timing applied to.
  const mirrorGroups = [];
  for (const group of _bucketDistributionsByAmount(distributions)) {
      const approxAmt   = group.reduce((s, g) => s + g.amt, 0) / group.length;
      const groupAddrs  = group.map(g => g.addr);

      const groupTimes  = groupAddrs.map(a2 => receiveTime.get(a2)).filter(t => t != null).sort((a, b) => a - b);
      const timingSpan   = groupTimes.length >= 2 ? groupTimes[groupTimes.length - 1] - groupTimes[0] : null;
      // Require most (not just two) of the group's members to fall inside
      // the narrow window — two coincidentally-close timestamps out of a
      // group of 20 shouldn't count as "this group was funded together."
      const timingCorrelated = timingSpan != null && timingSpan < 3600 && groupTimes.length / group.length >= 0.6;

      const createdCount = groupAddrs.filter(a2 => createdAccts.has(a2)).length;
      const issuerCreated = createdCount / group.length >= 0.6;

      // Common external funder: only meaningful for members the issuer did
      // NOT create directly (issuerCreated already covers those) — among
      // the rest, does one single funding account recur across a real
      // majority of the group? A lone pair sharing a funder out of a group
      // of 20 isn't "this group was commonly funded," so the same >=0.6-of-
      // group threshold as the other two families applies, scoped to the
      // non-issuer-created subset it's actually evaluating.
      const nonIssuerCreated = groupAddrs.filter(a2 => !createdAccts.has(a2));
      const funderCounts = new Map();
      for (const a2 of nonIssuerCreated) {
        const f = commonFunderByAddr.get(a2);
        if (f) funderCounts.set(f, (funderCounts.get(f) || 0) + 1);
      }
      const topFunder = [...funderCounts.entries()].sort((a, b) => b[1] - a[1])[0] || null;
      const commonFunded = !!topFunder && nonIssuerCreated.length > 0 && topFunder[1] / nonIssuerCreated.length >= 0.6 && topFunder[1] >= 2;

      const firedFamilies = [timingCorrelated, issuerCreated, commonFunded].filter(Boolean).length;
      const totalFamilies = 1 + firedFamilies; // amount similarity is always the base family
      const confidence = totalFamilies >= 3 ? 0.75 : totalFamilies === 2 ? 0.55 : 0.35;
      const tier = _evidenceStrength([{ sev: 'warn', confidence }]);

      mirrorGroups.push({ approxAmt, accounts: group, totalFamilies, timingCorrelated, issuerCreated, commonFunded, confidence, tier });

      const corroboration = [
        timingCorrelated ? `funded within ${Math.ceil(timingSpan / 60)} minute(s) of each other` : null,
        issuerCreated ? `${createdCount}/${group.length} directly created by this issuer` : null,
        commonFunded ? `${topFunder[1]}/${nonIssuerCreated.length} of the remaining accounts share the same external funding account` : null,
      ].filter(Boolean);

      signals.push(mkFinding({
        module: 'Issuer Connections', category: 'issuer',
        sev: totalFamilies >= 3 ? 'critical' : totalFamilies === 2 ? 'warn' : 'info',
        confidence,
        headline: `${group.length} accounts each received ~${fmt(approxAmt, 0)} tokens (${tier} evidence)`,
        detail: corroboration.length
          ? `Amount similarity plus ${corroboration.join(' and ')}.`
          : 'Amount similarity only — no timing, account-creation, or common-funder corroboration found for this specific group.',
        observed: [
          `${group.length} accounts, ~${fmt(approxAmt, 0)} tokens each`,
          timingCorrelated ? `${groupTimes.length}/${group.length} of these accounts were funded within ${Math.ceil(timingSpan / 60)} minute(s) of each other` : null,
          issuerCreated ? `${createdCount}/${group.length} of these specific accounts were created directly by the issuer` : null,
          commonFunded ? `${topFunder[1]}/${nonIssuerCreated.length} of the accounts NOT created directly by the issuer share one common external funding account (verified via each account's own AccountRoot creation evidence)` : null,
        ].filter(Boolean),
        alternativeExplanations: [
          'A round-number airdrop, fixed-price sale, or common purchase amount can all produce similar-amount clusters without any coordination',
          'Independent users choosing common round numbers is normal and not itself evidence of a single controller',
          commonFunded ? 'A common funder can be a legitimate shared source (an exchange, a faucet, a known distributor) rather than evidence the recipient wallets themselves are related' : null,
        ].filter(Boolean),
        classification: totalFamilies >= 3
          ? 'Multiple independent signals corroborate a likely single-controller cluster for THIS specific group — still not cryptographic proof of common ownership, but strong circumstantial evidence.'
          : totalFamilies === 2
            ? 'Two independent signals agree for this specific group — moderate evidence worth investigating further, not yet a strong conclusion.'
            : 'Amount similarity alone, with no timing, creation, or funding corroboration for this specific group — a weak signal by itself.',
      }));
  }

  // ── Account creation chains ───────────────────────────────────────────────
  if (createdAccts.size > 0) {
    signals.push({
      sev: createdAccts.size > 10 ? 'warn' : 'info',
      label: `${createdAccts.size} account(s) created by this address`,
      detail: 'This issuer funded the activation of these accounts. They may be controlled by the same entity.',
    });
  }

  // ── Token supply concentration (from trustlines) ──────────────────────────
  // IMPORTANT: account_lines returns at most 400 trustlines. For tokens with many
  // holders, this is a partial sample. All percentages are relative to the visible
  // sample unless gateway_balances provided the true total. We always caveat this.
  const issuedLines = lines.filter(l => Number(l.balance) < 0);

  // True total from gateway_balances if available; fall back to sample sum
  const trueTotal   = _gatewayTotal; // injected below from gatewayBalances
  const sampleTotal = issuedLines.reduce((s, l) => s + Math.abs(Number(l.balance)), 0);
  const totalIssued = trueTotal != null ? trueTotal : sampleTotal;
  const isSampleOnly = trueTotal == null && issuedLines.length > 0;
  const sampleCaveat = isSampleOnly
    ? ` (based on ${issuedLines.length} visible trustlines — actual total supply may be higher if there are more holders)`
    : '';

  const topHolders = issuedLines
    .map(l => ({ addr: l.account, balance: Math.abs(Number(l.balance)), currency: hexToAscii(l.currency) }))
    .sort((a, b) => b.balance - a.balance)
    .slice(0, 10);

  // Active/dormant: did this holder ever transact DIRECTLY with the issuer
  // (visible in the issuer's own fetched history)? This is a proxy, not a
  // true on-chain-activity check — a holder trading the token peer-to-peer
  // or via the DEX would never appear here even if very active elsewhere.
  // Still a real, distinct signal from total silence: it identifies who
  // has ever engaged with the issuer directly (redemptions, top-ups,
  // repeat distributions) versus who received tokens once and never
  // interacted with this account again.
  const directIssuerContactAddrs = new Set();
  for (const { tx } of txList) {
    if (tx.TransactionType !== 'Payment') continue;
    const amt = tx.Amount;
    if (typeof amt !== 'object' || !amt?.currency) continue;
    if (tx.Account === addr && tx.Destination) directIssuerContactAddrs.add(tx.Destination);
    if (tx.Destination === addr && tx.Account) directIssuerContactAddrs.add(tx.Account);
  }
  topHolders.forEach(h => { h.activeWithIssuer = directIssuerContactAddrs.has(h.addr); });
  const activeHolderCount = topHolders.filter(h => h.activeWithIssuer).length;
  if (topHolders.length >= 3) {
    signals.push(mkFinding({
      module: 'Issuer Connections', category: 'issuer', sev: 'info', confidence: 0.35,
      headline: `${activeHolderCount} of top ${topHolders.length} holders have transacted directly with the issuer`,
      detail: `${topHolders.length - activeHolderCount} show no direct payment activity with this issuer in the fetched history.`,
      observed: [`Direct-contact holders: ${activeHolderCount}/${topHolders.length}`, 'Measures direct issuer contact only — holders active via DEX trades or peer-to-peer transfers are not visible from this account\'s own history alone'],
      classification: 'This distinguishes holders who have engaged with the issuer directly from those who haven\'t — it is not a general on-chain activity/dormancy check.',
    }));
  }

  // Only flag concentration if we have a reliable denominator.
  // When sampleOnly, the top holders trivially sum near 100% of the sample —
  // that's an artifact of limited data, not evidence of concentration.
  const denominator = trueTotal != null ? trueTotal : sampleTotal;
  const canAssessConcentration = denominator > 0 && (trueTotal != null || issuedLines.length >= 50);

  if (topHolders.length >= 2 && canAssessConcentration) {
    const top1Pct = topHolders[0].balance / denominator * 100;
    const sourceNote = trueTotal != null ? '' : ' (of visible sample)';
    if (top1Pct > 50) {
      signals.push({ sev: 'critical',
        label: `Top holder controls ${top1Pct.toFixed(0)}%${sourceNote} of supply`,
        detail: `${shortAddr(topHolders[0].addr)} holds ${fmt(topHolders[0].balance, 0)} of ${fmt(denominator, 0)} total${sampleCaveat}. ` +
                (trueTotal != null ? 'Extreme dump risk — one wallet could sell everything.' : 'Check gateway_balances or a block explorer to confirm the full supply picture.') });
    } else if (top1Pct > 25) {
      signals.push({ sev: 'warn',
        label: `Top holder controls ${top1Pct.toFixed(0)}%${sourceNote} of supply`,
        detail: `Large single-holder concentration${sampleCaveat}. Monitor for coordinated sell events.` });
    }

    const top5     = topHolders.slice(0, 5).reduce((s, h) => s + h.balance, 0);
    const top5Pct  = top5 / denominator * 100;
    if (top5Pct > 75) {
      signals.push({ sev: 'warn',
        label: `Top 5 holders own ${top5Pct.toFixed(0)}%${sourceNote} of supply`,
        detail: `Supply heavily concentrated in a few wallets${sampleCaveat}. ` +
                'This pattern is common in pre-launch setups or tokens with limited real distribution.' });
    }
  } else if (issuedLines.length > 0 && !canAssessConcentration) {
    // We have some holders but not enough data to compute meaningful percentages
    signals.push({ sev: 'info',
      label: `${issuedLines.length} trustline holder(s) visible — supply data limited`,
      detail: `Only ${issuedLines.length} trustlines returned by account_lines. ` +
              `The true holder count and total supply cannot be determined from this data alone. ` +
              `Use a block explorer (XRPScan, Bithomp) for a complete holder distribution.` });
  }

  if (signals.length === 0 && totalIssued === 0) {
    signals.push({ sev: 'info', label: 'No token issuance detected', detail: 'This account does not appear to be an active token issuer.' });
  }

  return {
    signals,
    totalIssued,
    holderCount: issuedLines.length,
    topHolders,
    mirrorGroups,
    createdAccts: [...createdAccts],
    // 3rd element (first-received timestamp) is a backward-compatible
    // addition — existing [addr, amount] destructuring elsewhere just
    // ignores it — feeding the Market Setup Timeline's "distribution" stage
    // without needing a second pass over txList.
    distributions: [...distributions.entries()].sort((a, b) => b[1] - a[1]).slice(0, 10).map(([a, amt]) => [a, amt, receiveTime.get(a) ?? null]),
    isSampleOnly,
  };
}

/* ─────────────────────────────
   Distribution & Market Flow (on-demand)
   Traces an issuer's largest direct token recipients FORWARD: did they
   begin selling in a similar time window, and did their proceeds converge
   on a shared destination? This account's own txList only shows payments
   FROM the issuer — it says nothing about what recipients did afterward —
   so this genuinely needs each recipient's OWN transaction history, one
   extra RPC round-trip per cohort wallet. That's real, non-trivial cost
   compared to every other analysis pass in this file (which all operate on
   data already fetched for the single inspected account), so this is
   deliberately triggered on demand (a button) rather than run automatically
   as part of every inspection.

   Deliberately conservative on both ends:
   - Never labeled a "dump," "rug," or "insider" pattern — headline and all
     copy stay neutral ("Distribution-to-Market Sequence"), and severity is
     capped at 'warn' even when every signal fires, because the ledger can
     show WHAT happened but never WHY — common ownership and intent are
     never established by this data alone.
   - A large distribution share alone is NOT evidence of anything — every
     issuer distributes tokens to someone. Only actual coordinated BEHAVIOR
     (selling in sync, proceeds consolidating) drives a "worth reviewing"
     finding; materiality only raises confidence once a behavioral signal
     already exists, exactly mirroring how the pre-existing mirror-wallet
     clustering above never fires on amount-similarity alone without an
     independent corroborating signal.
──────────────────────────────── */
const DIST_MARKET_COHORT_SIZE          = 8;      // top N direct recipients by amount received
const DIST_MARKET_TX_PAGE              = 400;    // one page per recipient — not exhaustive history
const DIST_MARKET_TX_DELAY_MS          = 200;    // between sequential per-recipient fetches
const DIST_MARKET_SYNC_WINDOW_SEC      = 6 * 3600; // "began selling" clustering window
const DIST_MARKET_MIN_COHORT_SHARE_PCT = 10;     // materiality floor that can raise (never create) confidence

// Fetches ONE capped page of a cohort wallet's own transaction history and
// extracts exactly the two things this feature needs: when (if ever) it
// began placing sell-side orders for the issued currency, and where its
// XRP moved afterward. "Began selling" = a sell-side OfferCreate (TakerGets
// = the issued currency) — real intent to convert the token, cheap to
// detect from the tx itself. This does NOT confirm the order was ever
// FILLED (that needs parsing metadata for order-book consumption per
// transaction, materially more expensive to do for a whole cohort) — sell
// ORDERS PLACED, not confirmed executions, and every place this surfaces
// says so explicitly.
async function _fetchCohortWalletActivity(walletAddr, issuedCurrency) {
  const req = { command: 'account_tx', account: walletAddr, limit: DIST_MARKET_TX_PAGE, ledger_index_min: -1, ledger_index_max: -1, forward: false };
  const res = await wsSend(req).catch(() => null);
  if (res == null) return { addr: walletAddr, fetchFailed: true, sellOrderCount: 0, firstSellTs: null, proceedsPayments: [], hop2Recipients: [], txSampleSize: 0, ammDeposited: false, ammWithdrew: false };

  const txList = normaliseTxList(res?.result?.transactions || []);
  const sellOrders = txList.filter(({ tx }) =>
    tx.TransactionType === 'OfferCreate' && tx.Account === walletAddr &&
    typeof tx.TakerGets === 'object' && tx.TakerGets?.currency === issuedCurrency
  );
  const firstSellTs = sellOrders.length ? Math.min(...sellOrders.map(({ tx }) => tx.date ?? Infinity)) : null;

  // Proceeds candidates: outbound XRP payments at or after the first sell
  // order — a cheap, real economic-effect proxy for "money that left after
  // selling began" (this app has no per-cohort-wallet order-book-fill
  // reconstruction cheap enough to trace the EXACT XRP received per trade).
  const proceedsPayments = firstSellTs == null ? [] : txList
    .filter(({ tx }) => tx.TransactionType === 'Payment' && tx.Account === walletAddr &&
      typeof tx.Amount === 'string' && (tx.date ?? -Infinity) >= firstSellTs && tx.Destination && tx.Destination !== walletAddr)
    .map(({ tx }) => ({ dest: tx.Destination, xrp: amtNum(tx.Amount), date: tx.date }));

  // Hop-2 distribution: did this direct (hop-1) recipient ALSO forward the
  // SAME issued token onward to another wallet? Zero extra RPC calls — this
  // is the exact same page already fetched above for sell/proceeds
  // detection, just one more filter over it.
  const hop2Recipients = _extractHop2Recipients(txList, walletAddr, issuedCurrency);

  // Liquidity Setup / Liquidity Withdrawal (Potential Setup Analysis chain
  // steps) — reuses this exact same already-fetched page, zero extra RPC
  // calls. Deliberately not scoped to a specific pool: any AMM deposit or
  // withdrawal by this wallet is evidence it participates in liquidity
  // provision generally, which is what those chain steps actually ask.
  const ammDeposited = txList.some(({ tx }) => tx.TransactionType === 'AMMDeposit' && tx.Account === walletAddr);
  const ammWithdrew  = txList.some(({ tx }) => tx.TransactionType === 'AMMWithdraw' && tx.Account === walletAddr);

  return { addr: walletAddr, fetchFailed: false, sellOrderCount: sellOrders.length, firstSellTs, proceedsPayments, hop2Recipients, txSampleSize: txList.length, ammDeposited, ammWithdrew };
}

// Aggregated per destination since a wallet might forward to the same
// address more than once — extracted as its own pure function (rather than
// inlined in _fetchCohortWalletActivity, which always does a live RPC
// fetch) so it can be tested directly against a synthetic txList.
function _extractHop2Recipients(txList, walletAddr, issuedCurrency) {
  const hop2ByDest = new Map();
  for (const { tx } of txList) {
    if (tx.TransactionType !== 'Payment' || tx.Account !== walletAddr) continue;
    if (typeof tx.Amount !== 'object' || tx.Amount?.currency !== issuedCurrency) continue;
    if (!tx.Destination || tx.Destination === walletAddr) continue;
    const prior = hop2ByDest.get(tx.Destination) || { dest: tx.Destination, amount: 0, firstDate: tx.date };
    prior.amount += amtNum(tx.Amount) || 0;
    prior.firstDate = Math.min(prior.firstDate, tx.date ?? prior.firstDate);
    hop2ByDest.set(tx.Destination, prior);
  }
  return [...hop2ByDest.values()].sort((a, b) => b.amount - a.amount);
}

// Pairwise union-find over each cohort wallet's single firstSellTs value —
// simpler than _clusterVolumeActors above (which clusters SETS of
// timestamps per actor) since each wallet contributes exactly one "began
// selling" moment here. Same union-find helper, different comparison.
function _clusterSellTimings(cohort) {
  const withSell = cohort.filter(c => c.firstSellTs != null);
  const n = withSell.length;
  const { find, union } = _unionFind(n);
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      if (Math.abs(withSell[i].firstSellTs - withSell[j].firstSellTs) <= DIST_MARKET_SYNC_WINDOW_SEC) union(i, j);
    }
  }
  const groups = new Map();
  for (let i = 0; i < n; i++) {
    const root = find(i);
    if (!groups.has(root)) groups.set(root, []);
    groups.get(root).push(withSell[i]);
  }
  return [...groups.values()].filter(g => g.length >= 2).sort((a, b) => b.length - a.length);
}

// Aggregates every cohort wallet's post-sale XRP payments by destination —
// a destination is a "consolidation point" only if it received from 2+
// DIFFERENT cohort wallets (one wallet paying one destination repeatedly is
// unremarkable; several unrelated recipients converging on the same
// address is the actual signal, mirroring spec-style "proceeds
// consolidation" evidence).
function _findProceedsConsolidation(cohort) {
  const byDest = new Map();
  for (const c of cohort) {
    for (const p of c.proceedsPayments) {
      if (!byDest.has(p.dest)) byDest.set(p.dest, { dest: p.dest, totalXrp: 0, senders: new Set(), payments: [] });
      const d = byDest.get(p.dest);
      d.totalXrp += p.xrp || 0;
      d.senders.add(c.addr);
      d.payments.push({ from: c.addr, xrp: p.xrp, date: p.date });
    }
  }
  return [...byDest.values()].filter(d => d.senders.size >= 2).sort((a, b) => b.senders.size - a.senders.size);
}

function _buildDistMarketFlowFindings({ cohort, cohortSharePct, syncGroups, proceedsConsolidation }) {
  const biggestSyncGroup = syncGroups[0] || null;
  const biggestConsolidation = proceedsConsolidation[0] || null;
  const hasSync = !!biggestSyncGroup;
  const hasConsolidation = !!biggestConsolidation;
  const sellingCount = cohort.filter(c => c.firstSellTs != null).length;

  if (!hasSync && !hasConsolidation) {
    return [mkFinding({
      module: 'Distribution & Market Flow', category: 'market-integrity', sev: 'info', confidence: 0.3,
      headline: 'No distribution-to-market coordination pattern found',
      observed: [
        `Checked the top ${cohort.length} direct recipient(s) of this issuer's token.`,
        cohortSharePct != null ? `Combined, they received ${fmt(cohortSharePct, 1)}% of total issued supply.` : `Total issued supply could not be determined from the available data.`,
        `${sellingCount} of ${cohort.length} placed a sell-side order in the fetched (capped, most-recent) transaction sample.`,
      ],
      classification: 'Neither synchronized selling nor proceeds consolidation was observed for this cohort — the two behavioral signals this check actually looks for.',
    })];
  }

  // Materiality (cohort's share of total supply) never creates a finding on
  // its own — it only raises confidence once real coordinated BEHAVIOR
  // (sync and/or consolidation) already exists, same corroboration
  // discipline as the mirror-wallet clustering just above.
  const isMaterial = cohortSharePct != null && cohortSharePct >= DIST_MARKET_MIN_COHORT_SHARE_PCT;
  const behavioralSignalCount = (hasSync ? 1 : 0) + (hasConsolidation ? 1 : 0);
  const sev = behavioralSignalCount === 2 ? 'warn' : 'info'; // NEVER critical — intent is never established
  const confidence = behavioralSignalCount === 2 ? (isMaterial ? 0.75 : 0.55) : (isMaterial ? 0.45 : 0.35);

  const observed = [`Top ${cohort.length} direct recipient(s) of this issuer's token, combined ${cohortSharePct != null ? fmt(cohortSharePct, 1) + '%' : 'an undetermined share'} of total issued supply.`];
  if (hasSync) {
    const span = Math.max(...biggestSyncGroup.map(g => g.firstSellTs)) - Math.min(...biggestSyncGroup.map(g => g.firstSellTs));
    observed.push(`${biggestSyncGroup.length} of the cohort placed their first sell order within ${fmt(span / 60, 0)} minute(s) of each other.`);
  } else {
    observed.push(`No two cohort wallets began selling within the ${DIST_MARKET_SYNC_WINDOW_SEC / 3600}-hour comparison window used here (or too few placed sell orders to compare).`);
  }
  if (hasConsolidation) {
    observed.push(`${biggestConsolidation.senders.size} cohort wallets sent a combined ${fmt(biggestConsolidation.totalXrp, 2)} XRP in post-sale payments to the same destination (${shortAddr(biggestConsolidation.dest)}).`);
  } else {
    observed.push('No shared destination was found across cohort wallets\' post-sale XRP payments.');
  }

  return [mkFinding({
    module: 'Distribution & Market Flow', category: 'market-integrity', sev, confidence,
    headline: 'Distribution-to-Market Sequence',
    detail: 'Several of this issuer\'s largest direct token recipients show a pattern worth reviewing together — this describes what happened on-ledger, not why.',
    observed,
    calculated: cohortSharePct != null ? [`Cohort share of total issued supply: ${fmt(cohortSharePct, 1)}%`] : [],
    inferred: [
      hasSync ? 'Sell-order timing clustering this tightly across otherwise-unrelated wallets is less likely under fully independent, uncoordinated selling.' : null,
      hasConsolidation ? 'Multiple sellers\' proceeds reaching the same destination is more consistent with common control or a pre-arranged proceeds path than fully independent sellers.' : null,
    ].filter(Boolean),
    hypothesis: 'This may reflect coordinated distribution and market participation — for example a small group acting together, or a single controller behind multiple wallets.',
    classification: 'The ledger does not prove common ownership, project control, or manipulative intent — only that these on-chain events occurred in this sequence and timing.',
    alternativeExplanations: [
      'Designated market-making accounts operating on the issuer\'s behalf',
      'A disclosed treasury distribution or vesting release schedule',
      'A coordinated, publicly-announced liquidity program',
      'Coincidental timing among unrelated holders reacting to the same public market conditions',
    ],
    evidenceAgainstBenign: [
      hasSync ? `${biggestSyncGroup.length} independently-received wallets began selling within a ${DIST_MARKET_SYNC_WINDOW_SEC / 3600}-hour window of each other.` : null,
      hasConsolidation ? `${biggestConsolidation.senders.size} of those wallets' proceeds converged on one destination rather than dispersing.` : null,
    ].filter(Boolean),
  })];
}

// Pattern families (roadmap: cross-module corroboration) — grouping evidence
// this way, and counting at most ONE corroborating family regardless of how
// many individual signals fired within it, is what stops e.g. "amount
// similarity" and "issuer-created" (both really just restating "this IS a
// mirror group") from being double-counted as two independent agreements.
const SETUP_PATTERN_FAMILIES = {
  DISTRIBUTION: 'Distribution',
  FUNDING: 'Funding',
  LIQUIDITY: 'Liquidity',
  MARKET_EXECUTION: 'Market Execution',
  SELLING: 'Selling',
  PROCEEDS: 'Proceeds',
};

// Potential Setup Analysis (roadmap: cross-module corroboration — the spec's
// own stated "FINAL REQUIREMENT," chaining Issuer Distribution → Common
// Funding → Mirror Pattern → Liquidity → Market Activity → Selling →
// Proceeds Consolidation into ONE narrative) — reuses data this feature (and
// Issuer Connections / Holder Cohorts) already computed; the only genuinely
// new per-wallet signal is ammDeposited/ammWithdrew, read off the exact same
// page _fetchCohortWalletActivity already fetches for sell/proceeds
// detection, so this adds zero additional RPC calls beyond what Distribution
// & Market Flow already does. Returns null when fewer than 2 families have
// real evidence — a lone signal isn't a "potential setup," it's just one
// fact, matching this app's standing "no finding on a single uncorroborated
// signal" discipline used throughout Issuer Connections and Market
// Integrity.
function _buildPotentialSetupFinding({ cohort, syncGroups, proceedsConsolidation, mirrorGroup, lpHolderAddrSet = new Set(), sellerHolderAddrSet = new Set() }) {
  const cohortAddrSet = new Set(cohort.map(c => c.addr));
  const families = new Set();
  const chain = [];

  const hasMirror = !!mirrorGroup;
  chain.push({ step: 'Issuer Distribution', fired: true, note: `${cohort.length} wallet(s) received this token directly from the issuer` });
  if (hasMirror) families.add(SETUP_PATTERN_FAMILIES.DISTRIBUTION);
  chain.push({ step: 'Mirror Wallet Pattern', fired: hasMirror, note: hasMirror ? `${mirrorGroup.accounts.length} of these wallets received near-identical amounts (${mirrorGroup.tier} evidence)` : 'No identical-amount clustering found among this cohort' });

  const hasFunding = !!mirrorGroup?.commonFunded;
  if (hasFunding) families.add(SETUP_PATTERN_FAMILIES.FUNDING);
  chain.push({ step: 'Common Funding', fired: hasFunding, note: hasFunding ? 'Several non-issuer-created wallets in this group share one external funding account' : 'No shared external funding account found' });

  const lpSetupAddrs = cohort.filter(c => c.ammDeposited || lpHolderAddrSet.has(c.addr));
  const lpWithdrawAddrs = cohort.filter(c => c.ammWithdrew);
  const hasLiquidity = lpSetupAddrs.length > 0;
  if (hasLiquidity) families.add(SETUP_PATTERN_FAMILIES.LIQUIDITY);
  chain.push({ step: 'Liquidity Setup', fired: hasLiquidity, note: hasLiquidity ? `${lpSetupAddrs.length} cohort wallet(s) provided liquidity to an AMM pool` : 'No cohort wallet was found providing AMM liquidity' });
  chain.push({ step: 'Liquidity Withdrawal', fired: lpWithdrawAddrs.length > 0, note: lpWithdrawAddrs.length > 0 ? `${lpWithdrawAddrs.length} cohort wallet(s) later withdrew liquidity` : 'No cohort wallet was found withdrawing AMM liquidity' });

  const hasMarketActivity = !!mirrorGroup?.timingCorrelated || syncGroups.length > 0;
  if (hasMarketActivity) families.add(SETUP_PATTERN_FAMILIES.MARKET_EXECUTION);
  chain.push({ step: 'Market Activity', fired: hasMarketActivity, note: hasMarketActivity ? 'This group shows synchronized timing (funding, activation, or selling) rather than independent, spread-out activity' : 'No synchronized timing was found across this group' });

  const sellingAddrs = cohort.filter(c => c.firstSellTs != null || sellerHolderAddrSet.has(c.addr));
  const hasSelling = sellingAddrs.length > 0;
  if (hasSelling) families.add(SETUP_PATTERN_FAMILIES.SELLING);
  chain.push({ step: 'Net Selling', fired: hasSelling, note: hasSelling ? `${sellingAddrs.length} cohort wallet(s) placed sell-side orders or reduced their position` : 'No cohort wallet was found selling its position' });

  const hasProceeds = proceedsConsolidation.length > 0;
  if (hasProceeds) families.add(SETUP_PATTERN_FAMILIES.PROCEEDS);
  chain.push({ step: 'Proceeds Consolidation', fired: hasProceeds, note: hasProceeds ? `Proceeds from ${proceedsConsolidation[0].senders.size} cohort wallets converged on one destination` : 'No shared proceeds destination was found' });

  if (families.size < 2) return null;

  const familyCount = families.size;
  const sev = familyCount >= 4 ? 'warn' : 'info'; // never critical — intent is never established
  const confidence = familyCount >= 5 ? 0.7 : familyCount >= 4 ? 0.55 : 0.4;
  const tier = _evidenceStrength([{ sev: 'warn', confidence }]);

  return mkFinding({
    module: 'Potential Setup Analysis', category: 'issuer', sev, confidence,
    headline: `Potential Setup Analysis: ${familyCount} of ${Object.keys(SETUP_PATTERN_FAMILIES).length} independent pattern families corroborate (${tier} evidence)`,
    detail: 'Several independently-computed signals agree about THIS specific cohort — this describes a chain of on-ledger events, not who controls these wallets or why.',
    observed: chain.map(c => `${c.fired ? '✓' : '—'} ${c.step}: ${c.note}`),
    classification: 'Combines evidence Issuer Connections, Distribution & Market Flow, and Holder Cohorts each already computed independently — correlated signals from the SAME underlying fact (e.g. amount similarity and issuer-created both just restating "this is a mirror group") are grouped into one family rather than counted twice. Ownership identity: NOT ESTABLISHED. A possible related-wallet cluster executing a coordinated sequence is not proof of who controls it or what they intended.',
    alternativeExplanations: [
      'An issuer running a routine, transparent token launch (airdrop, sale, or liquidity bootstrap) produces many of these same steps without any coordination beyond the issuer\'s own public actions',
      'Early recipients independently choosing to provide liquidity and later sell is ordinary market behavior, not evidence of a single controller',
    ],
  });
}

// The orchestrator — awaited by the button handler, not called during the
// automatic runInspect() pass. issuedCurrency is the issuer's primary
// issued currency in RAW XRPL form (matching issuerMarketActivity's own
// convention, not hex-decoded) — an issuer with multiple issued currencies
// is scoped to just this one for now, stated explicitly wherever this
// result is rendered.
async function analyseDistributionMarketFlow(issuerConnAnalysis, issuedCurrency, holderCohorts = null) {
  // Prefer a qualifying mirror group (Moderate+ evidence: 2+ independent
  // families already agree per analyseIssuerConnections) as the cohort —
  // this directly seeds Issuer Distribution + Mirror Wallet Pattern +
  // (if present) Common Funding into the chain below from wallets already
  // flagged as related, rather than an arbitrary top-N-by-amount cohort
  // that may have nothing to do with each other. Falls back to the
  // original top-recipients cohort when no qualifying group exists.
  const bestMirrorGroup = (issuerConnAnalysis?.mirrorGroups || [])
    .filter(g => g.totalFamilies >= 2)
    .sort((a, b) => b.totalFamilies - a.totalFamilies)[0] || null;
  const distributionsMap = new Map((issuerConnAnalysis?.distributions || []).map(([a, amt, ts]) => [a, { amt, ts }]));
  const recipients = bestMirrorGroup
    ? bestMirrorGroup.accounts.slice(0, DIST_MARKET_COHORT_SIZE).map(({ addr, amt }) => [addr, amt, distributionsMap.get(addr)?.ts ?? null])
    : (issuerConnAnalysis?.distributions || []).slice(0, DIST_MARKET_COHORT_SIZE);
  if (!recipients.length) {
    return { applicable: false, reason: 'No direct token distribution from this issuer was found in the fetched history.' };
  }
  if (!issuedCurrency) {
    return { applicable: false, reason: 'Could not determine this issuer\'s primary issued currency.' };
  }

  const totalDistributed = recipients.reduce((s, [, amt]) => s + amt, 0);
  const cohort = [];
  for (let i = 0; i < recipients.length; i++) {
    const [recipAddr, amountReceived, receivedTs] = recipients[i];
    const activity = await _fetchCohortWalletActivity(recipAddr, issuedCurrency);
    cohort.push({ ...activity, amountReceived, receivedTs: receivedTs ?? null, sharePct: totalDistributed ? (amountReceived / totalDistributed) * 100 : null });
    if (i < recipients.length - 1) await new Promise(r => setTimeout(r, DIST_MARKET_TX_DELAY_MS));
  }

  const syncGroups = _clusterSellTimings(cohort);
  const proceedsConsolidation = _findProceedsConsolidation(cohort);
  const fetchFailures = cohort.filter(c => c.fetchFailed).length;
  const totalIssued = issuerConnAnalysis.totalIssued;
  const cohortSharePct = totalIssued ? (totalDistributed / totalIssued) * 100 : null;

  const findings = _buildDistMarketFlowFindings({ cohort, cohortSharePct, syncGroups, proceedsConsolidation });
  const potentialSetup = _buildPotentialSetupFinding({
    cohort, syncGroups, proceedsConsolidation, mirrorGroup: bestMirrorGroup,
    lpHolderAddrSet: new Set((holderCohorts?.lpHolders || []).map(h => h.addr)),
    sellerHolderAddrSet: new Set((holderCohorts?.sellerHolders || []).map(h => h.addr)),
  });
  if (potentialSetup) findings.push(potentialSetup);
  const timeline = _buildMarketSetupTimeline(cohort, proceedsConsolidation);

  return {
    applicable: true, cohort, totalDistributed, cohortSharePct,
    syncGroups, proceedsConsolidation, fetchFailures, findings, timeline,
    cohortSource: bestMirrorGroup ? 'mirror-group' : 'top-recipients', mirrorGroup: bestMirrorGroup,
  };
}

// ── Market Setup Timeline (phase 3) ──
// Chronological merge of every dated event Distribution & Market Flow
// already computed — distribution, hop-2 forwarding, selling, and proceeds
// — into one sorted list, matching the exact {date,icon,label,detail,
// module} shape buildImportantEventsTimeline/renderImportantEventsTimeline
// already established (reused for rendering, not reinvented). Genuinely
// zero extra cost: every date here already exists on the cohort/
// proceedsConsolidation objects Phase 1/2 built. Liquidity-event timing
// (AMM deposits) is NOT included — issuerAmmPool isn't threaded into this
// on-demand analysis, and adding it is a small enough gap to leave
// explicitly undone rather than fetching more data to close it here.
function _buildMarketSetupTimeline(cohort, proceedsConsolidation) {
  const events = [];
  for (const c of cohort) {
    if (c.receivedTs != null) {
      events.push({ date: c.receivedTs, icon: '📤', label: `Issuer distributed ${fmt(c.amountReceived, 0)} to ${shortAddr(c.addr)}`, detail: null, module: 'Distribution' });
    }
    for (const h of c.hop2Recipients || []) {
      events.push({ date: h.firstDate, icon: '🔀', label: `${shortAddr(c.addr)} forwarded ${fmt(h.amount, 0)} to ${shortAddr(h.dest)}`, detail: 'hop 2', module: 'Distribution' });
    }
    if (c.firstSellTs != null) {
      events.push({ date: c.firstSellTs, icon: '📉', label: `${shortAddr(c.addr)} began selling`, detail: `${c.sellOrderCount} sell order(s) in the fetched sample`, module: 'Selling' });
    }
  }
  for (const dest of proceedsConsolidation || []) {
    for (const p of dest.payments) {
      events.push({ date: p.date, icon: '💰', label: `${shortAddr(p.from)} sent ${fmt(p.xrp, 2)} XRP to ${shortAddr(dest.dest)}`, detail: 'proceeds consolidation', module: 'Proceeds' });
    }
  }
  return events.filter(e => e.date != null).sort((a, b) => a.date - b.date);
}

// ── Issuer Ecosystem multi-hop graph (phase 4) ──
// A genuine multi-hop graph — issuer -> ring 1 (direct recipients) -> ring 2
// (hop-2 forwards + proceeds destinations) — built entirely from data
// Phase 1/2/3 already fetched (zero new RPC calls). Deliberately scoped
// down from the full spec ask: no switchable layers (Distribution/Funding/
// Trading/Liquidity/Proceeds/All), no force-directed physics, no 3rd hop —
// a fixed 2-ring radial layout with 3 distinctly-colored edge types is a
// genuine, working multi-hop graph (today's single-hop network map can't do
// this at all), not the full "investigation workstation" visual the spec
// describes. Every edge drawn here is a real, observed on-ledger transfer
// (distribution/hop-2/proceeds) — this graph deliberately draws NO inferred/
// possible-relationship edges (that evidence already lives in the Overlap
// Matrix and the synchronized-selling finding, not as graph edges here),
// so there is no direct-vs-inferred distinction to visually equate or
// confuse — every line means the same thing: "a transfer happened."
const ECOSYSTEM_VIEWBOX = 400;
const ECOSYSTEM_RING1_RADIUS = 110;
const ECOSYSTEM_RING2_RADIUS = 185;
const ECOSYSTEM_EDGE_COLOR = { distribution: '#00d4ff', hop2: '#bd93f9', proceeds: '#ff79c6' };

function _buildIssuerEcosystemGraph(issuerAddr, result) {
  const CENTER = ECOSYSTEM_VIEWBOX / 2;
  const cohort = result.cohort || [];
  const n1 = cohort.length || 1;
  const ring1 = cohort.map((c, i) => {
    const angle = (i / n1) * 2 * Math.PI - Math.PI / 2; // start at 12 o'clock, clockwise
    return {
      addr: c.addr, amount: c.amountReceived, sharePct: c.sharePct,
      x: CENTER + ECOSYSTEM_RING1_RADIUS * Math.cos(angle),
      y: CENTER + ECOSYSTEM_RING1_RADIUS * Math.sin(angle),
    };
  });
  const ring1ByAddr = new Map(ring1.map(n => [n.addr, n]));

  // Ring 2 = union of hop-2 recipients and proceeds-consolidation
  // destinations, deduped by address (a wallet can legitimately be both).
  const ring2Map = new Map();
  const edges = [];
  for (const c of cohort) {
    edges.push({ from: issuerAddr, to: c.addr, kind: 'distribution', amount: c.amountReceived });
    for (const h of c.hop2Recipients || []) {
      if (ring1ByAddr.has(h.dest)) continue; // already drawn as a ring-1 node — don't duplicate
      if (!ring2Map.has(h.dest)) ring2Map.set(h.dest, { addr: h.dest, kinds: new Set() });
      ring2Map.get(h.dest).kinds.add('hop2');
      edges.push({ from: c.addr, to: h.dest, kind: 'hop2', amount: h.amount });
    }
  }
  for (const dest of result.proceedsConsolidation || []) {
    if (!ring1ByAddr.has(dest.dest)) {
      if (!ring2Map.has(dest.dest)) ring2Map.set(dest.dest, { addr: dest.dest, kinds: new Set() });
      ring2Map.get(dest.dest).kinds.add('proceeds');
    }
    for (const p of dest.payments) {
      edges.push({ from: p.from, to: dest.dest, kind: 'proceeds', amount: p.xrp });
    }
  }

  const ring2Arr = [...ring2Map.values()];
  const n2 = ring2Arr.length || 1;
  const ring2 = ring2Arr.map((r, i) => {
    const angle = (i / n2) * 2 * Math.PI - Math.PI / 2;
    return {
      addr: r.addr, kind: [...r.kinds].sort().join('+'),
      x: CENTER + ECOSYSTEM_RING2_RADIUS * Math.cos(angle),
      y: CENTER + ECOSYSTEM_RING2_RADIUS * Math.sin(angle),
    };
  });
  const ring2ByAddr = new Map(ring2.map(n => [n.addr, n]));

  return { center: { addr: issuerAddr, x: CENTER, y: CENTER }, ring1, ring2, edges, ring1ByAddr, ring2ByAddr };
}

function _renderIssuerEcosystemGraph(graph) {
  if (!graph?.ring1?.length) return '';
  const resolve = (addr) => addr === graph.center.addr ? graph.center : (graph.ring1ByAddr.get(addr) || graph.ring2ByAddr.get(addr));

  const edgeLines = graph.edges.map(e => {
    const from = resolve(e.from), to = resolve(e.to);
    if (!from || !to) return ''; // endpoint outside the drawn rings (e.g. a proceeds sender not in the cohort) — skip rather than draw a dangling/wrong line
    const color = ECOSYSTEM_EDGE_COLOR[e.kind] || '#888';
    return `<line x1="${from.x.toFixed(1)}" y1="${from.y.toFixed(1)}" x2="${to.x.toFixed(1)}" y2="${to.y.toFixed(1)}" stroke="${color}" stroke-width="1.3" opacity=".4" data-tooltip="${escHtml(`${e.kind}: ${fmt(e.amount, 2)}`)}"></line>`;
  }).join('');

  const centerNode = `
    <circle cx="${graph.center.x}" cy="${graph.center.y}" r="13" fill="#ffb86c" stroke="#0a0e16" stroke-width="1.5" data-tooltip="${escHtml(`Issuer: ${graph.center.addr}`)}"></circle>
    <text x="${graph.center.x}" y="${graph.center.y + 26}" text-anchor="middle" font-size="9" fill="rgba(255,255,255,.55)">Issuer</text>`;

  const ring1Nodes = graph.ring1.map(n => `
    <circle cx="${n.x.toFixed(1)}" cy="${n.y.toFixed(1)}" r="7.5" fill="${ECOSYSTEM_EDGE_COLOR.distribution}" stroke="#0a0e16" stroke-width="1" style="cursor:pointer" onclick="openRelationshipDrawer('${escHtml(n.addr)}')" data-tooltip="${escHtml(`${shortAddr(n.addr)}\n${fmt(n.amount, 0)} received${n.sharePct != null ? ` (${fmt(n.sharePct, 1)}% of cohort)` : ''}`)}"></circle>`).join('');

  const ring2Nodes = graph.ring2.map(n => `
    <circle cx="${n.x.toFixed(1)}" cy="${n.y.toFixed(1)}" r="5.5" fill="${n.kind.includes('proceeds') ? ECOSYSTEM_EDGE_COLOR.proceeds : ECOSYSTEM_EDGE_COLOR.hop2}" stroke="#0a0e16" stroke-width="1" style="cursor:pointer" onclick="openRelationshipDrawer('${escHtml(n.addr)}')" data-tooltip="${escHtml(`${shortAddr(n.addr)}\n${n.kind}`)}"></circle>`).join('');

  return `
    <div class="conn-section-h">🕸️ Issuer Ecosystem (${graph.ring1.length + graph.ring2.length + 1} wallets, ${graph.edges.length} edges)</div>
    <div class="ecosystem-graph-legend">
      <span><span class="ecosystem-legend-swatch" style="background:#ffb86c"></span>Issuer</span>
      <span><span class="ecosystem-legend-swatch" style="background:${ECOSYSTEM_EDGE_COLOR.distribution}"></span>Direct recipient</span>
      <span><span class="ecosystem-legend-swatch" style="background:${ECOSYSTEM_EDGE_COLOR.hop2}"></span>Hop-2 forward</span>
      <span><span class="ecosystem-legend-swatch" style="background:${ECOSYSTEM_EDGE_COLOR.proceeds}"></span>Proceeds destination</span>
    </div>
    <div class="ecosystem-graph-wrap">
      <svg viewBox="0 0 ${ECOSYSTEM_VIEWBOX} ${ECOSYSTEM_VIEWBOX}" class="ecosystem-graph-svg" preserveAspectRatio="xMidYMid meet">
        ${edgeLines}${ring1Nodes}${ring2Nodes}${centerNode}
      </svg>
    </div>
    <p class="widget-help" style="opacity:.55;font-size:.76rem;margin-top:6px">Every line is a real, observed on-ledger transfer (token distribution, hop-2 forward, or XRP proceeds) — not an inferred relationship. Click any wallet to open its relationship drawer.</p>`;
}

/* ─────────────────────────────
   Blackhole / Issuer Safety Helpers
   Prevent false positives for intentionally blackholed issuers
   (KNOWN_BLACKHOLE_ADDRESSES / isKnownBlackholeAddress now live in
   shared-analysis.js, imported above)
──────────────────────────────── */

/**
 * Heuristic: determine whether this account looks intentionally blackholed,
 * which is common for token issuers that permanently disable control.
 *
 * Recognizes BOTH conventions actually used in practice, not just the
 * hardcoded-address one — leaving master-disabled-with-no-regular-key-at-all
 * (arguably the more common of the two: simplest to do, and requires no
 * "known" address to recognize) unrecognized meant those accounts got no
 * reassuring "this is intentional, not a drain" signal at all, matching
 * deriveAccountControlState's own (separately maintained, already-correct)
 * BLACKHOLED criteria below rather than a narrower, drifted copy of it:
 * - master key disabled, AND EITHER
 *   - no regular key at all (nothing can ever sign for this account again), OR
 *   - regular key points to a known-unusable "burn" address
 * - no signer list retained (a signer list means the account IS still
 *   controllable, by quorum, regardless of the master/regular key state)
 *
 * This should NOT be treated as a drain pattern by default.
 */
function isIntentionalBlackhole(acct, flags, signerLists = [], txList = []) {
  const masterDisabled = !!(flags & FLAGS.lsfDisableMaster);
  const regularKey     = acct?.RegularKey || '';
  const hasSignerList  = Array.isArray(signerLists) && signerLists.length > 0;
  const knownBlackhole = isKnownBlackholeAddress(regularKey);

  if (masterDisabled && !hasSignerList && (!regularKey || knownBlackhole)) return true;

  return false;
}

/**
 * Heuristic: determine whether this account behaves like an issuer.
 * Used so we can raise caution wording about sending tokens back to a
 * blackholed issuer without mislabeling it as compromised.
 */
function looksLikeIssuer(acct, flags, txList = []) {
  const defaultRipple = !!(flags & FLAGS.lsfDefaultRipple);
  const requireAuth   = !!(flags & FLAGS.lsfRequireAuth);
  const globalFreeze  = !!(flags & FLAGS.lsfGlobalFreeze);
  const noFreeze      = !!(flags & FLAGS.lsfNoFreeze);

  const trustSetCount = txList.filter(({ tx }) => tx.TransactionType === 'TrustSet').length;
  const paymentTokenCount = txList.filter(({ tx }) =>
    tx.TransactionType === 'Payment' &&
    typeof tx.Amount === 'object' &&
    tx.Amount?.currency
  ).length;

  return defaultRipple || requireAuth || globalFreeze || noFreeze || trustSetCount >= 3 || paymentTokenCount >= 5;
}

/* ── Account Control State ──
   Replaces the old binary "master disabled → assume drain risk unless it
   matches a hardcoded blackhole address" read with an explicit state that
   distinguishes WHO can currently control the account and whether that's
   provably reversible — not just whether the master key happens to be off.
   Key distinction the old code collapsed: a disabled master key with an
   arbitrary (non-hardcoded) regular key is NOT irreversible — whoever
   holds that regular key can still sign, including potentially
   re-enabling the master key itself. Only the absence of ANY working key
   (or a regular key pointed at a provably-unusable address) is actually
   permanent. */
const ACCOUNT_CONTROL_STATES = {
  NORMAL: 'Normal',
  REGULAR_KEY: 'Regular-Key Controlled',
  MULTISIG: 'Multisig Controlled',
  BLACKHOLED: 'Blackholed',
  RECOVERABLE: 'Recoverable',
  MISCONFIGURED: 'Potentially Misconfigured',
  UNKNOWN: 'Unknown',
};
const ASF_DISABLE_MASTER = 4; // AccountSet SetFlag/ClearFlag numeric code, per the XRPL AccountSet spec

/* ── Blackhole / Issuer Immutability Classification ──
   A separate, narrower question from Account Control State above: not
   "who can currently control this account" but specifically "is it
   verifiably blackholed, and how sure are we." Kept as its own 4-way
   classification — rather than folded into the general control-state
   severity — because a verified blackhole is not itself a risk signal
   (see the 'info'/'ok' severities below and in analyseSecurityPosture's
   own BLACKHOLED handling): collapsing "is this immutable" into the same
   scale as "is this account a security concern" is exactly the false
   equivalence this classification exists to avoid. */
const BLACKHOLE_CLASSIFICATIONS = {
  VERIFIED: 'Verified Blackholed',
  NOT_BLACKHOLED: 'Not Blackholed',
  INCOMPLETE: 'Incomplete / Recoverable Blackhole Configuration',
  UNABLE_TO_VERIFY: 'Unable to Verify',
};
function deriveBlackholeClassification(controlState) {
  // Low confidence (e.g. incomplete transaction history behind the
  // control-state read) means we can't actually stand behind ANY
  // classification here, regardless of which state was derived.
  if (controlState.confidence < 0.5) return BLACKHOLE_CLASSIFICATIONS.UNABLE_TO_VERIFY;
  switch (controlState.state) {
    case ACCOUNT_CONTROL_STATES.BLACKHOLED:
      return BLACKHOLE_CLASSIFICATIONS.VERIFIED;
    case ACCOUNT_CONTROL_STATES.REGULAR_KEY:
      // Master disabled, but the regular key is NOT a known-unusable
      // address — someone attempted (or ended up in the shape of) a
      // blackhole, but a working key still exists. Genuinely incomplete.
    case ACCOUNT_CONTROL_STATES.RECOVERABLE:
      // Proven NOT permanently locked (master key has been re-enabled from
      // this exact state before) — grouped with "Incomplete" per spec,
      // since both describe "not a reliably verified blackhole," just for
      // different reasons (unproven vs. disproven).
      return BLACKHOLE_CLASSIFICATIONS.INCOMPLETE;
    case ACCOUNT_CONTROL_STATES.UNKNOWN:
      return BLACKHOLE_CLASSIFICATIONS.UNABLE_TO_VERIFY;
    default:
      // NORMAL, MULTISIG, MISCONFIGURED — master key active, or a signer
      // list (reachable or not) still formally exists. None of these are
      // the "disable master + burn the key" shape a blackhole requires.
      return BLACKHOLE_CLASSIFICATIONS.NOT_BLACKHOLED;
  }
}

function deriveAccountControlState(acct, flags, signerLists, txList, historyCoverage = {}) {
  const masterDisabled = !!(flags & FLAGS.lsfDisableMaster);
  const hasRegularKey  = !!acct.RegularKey;
  const hasSignerList  = signerLists.length > 0;
  const knownBlackholeKey = isKnownBlackholeAddress(acct.RegularKey);

  // Historical AccountSet reconstruction: has the master key EVER been
  // disabled then re-enabled? That's empirical proof of reversibility,
  // not just a theoretical possibility.
  const masterKeyHistory = txList
    .filter(({ tx }) => tx.TransactionType === 'AccountSet' && tx.Account === acct.Account && (tx.SetFlag === ASF_DISABLE_MASTER || tx.ClearFlag === ASF_DISABLE_MASTER))
    .map(({ tx }) => ({ date: tx.date, hash: tx.hash, action: tx.SetFlag === ASF_DISABLE_MASTER ? 'disabled' : 'enabled' }))
    .sort((a, b) => (a.date ?? 0) - (b.date ?? 0));
  const wasEverReenabled = masterKeyHistory.some((h, i) => h.action === 'enabled' && masterKeyHistory.slice(0, i).some(p => p.action === 'disabled'));

  // A signer list whose quorum exceeds the sum of all signer weights can
  // never actually reach quorum — a concrete, mechanically-checkable
  // misconfiguration, not a heuristic guess.
  const misconfiguredSignerLists = signerLists.filter(sl => {
    const entries = sl.SignerEntries || [];
    const totalWeight = entries.reduce((s, e) => s + Number(e.SignerEntry?.SignerWeight || 0), 0);
    return totalWeight < Number(sl.SignerQuorum || 1);
  });

  let state, reversibility, confidence;
  if (misconfiguredSignerLists.length) {
    state = ACCOUNT_CONTROL_STATES.MISCONFIGURED; reversibility = 'blocked — quorum exceeds total signer weight, unreachable as configured'; confidence = 0.9;
  } else if (hasSignerList) {
    state = ACCOUNT_CONTROL_STATES.MULTISIG; reversibility = 'controlled by signer quorum'; confidence = 0.85;
  } else if (masterDisabled && hasRegularKey && knownBlackholeKey) {
    state = ACCOUNT_CONTROL_STATES.BLACKHOLED; reversibility = 'none — regular key points to a provably unusable address'; confidence = 0.85;
  } else if (masterDisabled && !hasRegularKey) {
    state = ACCOUNT_CONTROL_STATES.BLACKHOLED; reversibility = 'none — no working key exists'; confidence = 0.75;
  } else if (masterDisabled && hasRegularKey && wasEverReenabled) {
    state = ACCOUNT_CONTROL_STATES.RECOVERABLE; reversibility = 'proven historically — master key has been re-enabled from this state before'; confidence = 0.7;
  } else if (masterDisabled && hasRegularKey) {
    state = ACCOUNT_CONTROL_STATES.REGULAR_KEY; reversibility = 'possible — whoever holds the regular key can re-enable the master key or act directly'; confidence = 0.6;
  } else if (!masterDisabled) {
    state = ACCOUNT_CONTROL_STATES.NORMAL; reversibility = 'full — master key is active'; confidence = 0.9;
  } else {
    state = ACCOUNT_CONTROL_STATES.UNKNOWN; reversibility = 'undetermined'; confidence = 0.3;
  }

  // Absence-of-evidence (e.g. "no SetRegularKey found") is weaker evidence
  // when the history behind it might be incomplete.
  if (historyCoverage?.fetchErrorOccurred && !historyCoverage?.newestToOldestComplete) {
    confidence = Math.min(confidence, 0.5);
  }

  return { state, reversibility, confidence, masterDisabled, hasRegularKey, hasSignerList, masterKeyHistory, wasEverReenabled, misconfiguredSignerListCount: misconfiguredSignerLists.length };
}

/* ═══════════════════════════════════════════════════
   ANALYSIS PASSES
═══════════════════════════════════════════════════ */

/* ── Security Posture ────────────────────────────── */
function analyseSecurityPosture(acct, flags, signerLists, txList, historyCoverage = {}, residualObjects = {}) {
  const findings = [];
  let score = 100; // start perfect, deduct

  const masterDisabled = !!(flags & FLAGS.lsfDisableMaster);
  const hasRegularKey  = !!acct.RegularKey;
  const hasSignerList  = signerLists.length > 0;
  const blackholed     = isIntentionalBlackhole(acct, flags, signerLists, txList);
  const issuerLike     = looksLikeIssuer(acct, flags, txList);
  const controlState   = deriveAccountControlState(acct, flags, signerLists, txList, historyCoverage);

  // 1. Account Control State — replaces the old critical/info/info 3-way
  // split with the explicit 7-state machine above. Only states that are
  // actually irreversible or unusable cost score points; Regular-Key
  // Controlled, Multisig Controlled, Recoverable, and Normal are all
  // legitimate configurations, not risk signals on their own.
  {
    const stateSevMap = {
      [ACCOUNT_CONTROL_STATES.BLACKHOLED]:     'info',
      [ACCOUNT_CONTROL_STATES.MISCONFIGURED]:  'critical',
      [ACCOUNT_CONTROL_STATES.REGULAR_KEY]:    'info',
      [ACCOUNT_CONTROL_STATES.MULTISIG]:       'info',
      [ACCOUNT_CONTROL_STATES.RECOVERABLE]:    'info',
      [ACCOUNT_CONTROL_STATES.NORMAL]:         'ok',
      [ACCOUNT_CONTROL_STATES.UNKNOWN]:        'warn',
    };
    // Residual pre-existing ledger objects (Open Offers / Escrows / Payment
    // Channels / Checks) can still complete or be claimed AFTER an account
    // is blackholed — signing authority being gone stops the account from
    // creating anything NEW, but doesn't retroactively cancel what already
    // existed. Purely informational on its own (it doesn't make the account
    // any less blackholed, or reversible), so this is surfaced as an
    // observed fact on the SAME info-severity finding, not a reason to
    // escalate severity.
    const residualCounts = blackholed ? {
      offers: (residualObjects.offers || []).length,
      escrows: (residualObjects.escrows || []).length,
      paychans: (residualObjects.paychans || []).length,
      checks: (residualObjects.checks || []).length,
    } : null;
    const residualTotal = residualCounts ? residualCounts.offers + residualCounts.escrows + residualCounts.paychans + residualCounts.checks : 0;
    findings.push({
      ...mkFinding({
        module: 'Security', category: 'security', sev: stateSevMap[controlState.state] || 'info', confidence: controlState.confidence,
        headline: `Account Control State: ${controlState.state}`,
        detail: `Reversibility: ${controlState.reversibility}`,
        observed: [
          `Master key: ${controlState.masterDisabled ? 'disabled' : 'active'}`,
          `Regular key: ${controlState.hasRegularKey ? acct.RegularKey : 'not set'}`,
          `Signer list: ${controlState.hasSignerList ? `${signerLists.length} list(s)` : 'none'}`,
          controlState.wasEverReenabled ? 'Master key has been re-enabled from a disabled state at least once in fetched history' : null,
          residualCounts ? (residualTotal > 0
            ? `Residual pre-existing ledger objects: present (${[
                residualCounts.offers && `${residualCounts.offers} open offer(s)`,
                residualCounts.escrows && `${residualCounts.escrows} escrow(s)`,
                residualCounts.paychans && `${residualCounts.paychans} payment channel(s)`,
                residualCounts.checks && `${residualCounts.checks} check(s)`,
              ].filter(Boolean).join(', ')}) — these were created before blackholing and may still complete or be claimed even though this account can no longer create anything new`
            : 'Residual pre-existing ledger objects: none found — no open offers, escrows, payment channels, or checks remain')
            : null,
        ].filter(Boolean),
        classification: controlState.state === ACCOUNT_CONTROL_STATES.MISCONFIGURED
          ? 'Signer quorum cannot be reached with the current signer weights as configured — this account may be functionally stuck regardless of anyone\'s intent.'
          : controlState.state === ACCOUNT_CONTROL_STATES.REGULAR_KEY
            ? 'A disabled master key with an active regular key is not the same as a locked/irreversible account — the regular key holder retains full control, including the ability to re-enable the master key.'
            : blackholed
              ? 'A verified blackhole is the safest possible state against future key compromise — no key exists for anyone to ever steal or misuse. It does mean this account (and, if it issues a token, that token\'s settings) can never change again.'
              : null,
      }),
      kind: 'current',
    });
    // BLACKHOLED does NOT cost score points, unlike MISCONFIGURED — a stale
    // holdover from before the 7-state model above existed, when "master key
    // disabled" was scored as inherently risky regardless of why. Being
    // blackholed (no working key exists, or the working key provably can't
    // sign) is the single SAFEST state against future key compromise: there
    // is no key left for an attacker to ever steal or misuse. It costs a
    // token issuer the ability to ever mint more / change settings — a
    // real, separate caution already surfaced below via "Blackholed issuer
    // caution" — but that is not the same claim as "this account's security
    // posture is worse," which a score deduction here would assert. Treated
    // the same as REGULAR_KEY/MULTISIG/RECOVERABLE/NORMAL: sev:'info', zero
    // point cost.
    if (controlState.state === ACCOUNT_CONTROL_STATES.MISCONFIGURED) score -= 30;

    if (blackholed && issuerLike) {
      // info, not warn — this is an educational fact about what happens if
      // YOU send tokens here, not evidence that THIS account has a security
      // problem. A "warn" here was driving a misleading "something worth
      // reviewing" plain-language summary for an account that is, per the
      // finding above, in the single safest control state there is.
      findings.push({
        sev: 'info',
        label: 'Blackholed issuer — tokens sent here become unrecoverable',
        detail: 'This account appears issuer-like and is intentionally blackholed. Sending issued tokens back here may make them unrecoverable or effectively burn them — informational for anyone transacting with this account, not a problem with the account itself.',
        kind: 'current',
      });
    }

    // Blackhole / Issuer Immutability — a separate, narrower classification
    // from Account Control State above (roadmap: NFT/issuer forensic
    // coverage §29-30). Always 'ok' or 'info' severity and never costs
    // score points, by design: whether an account is immutable is an
    // entirely different question from whether it's a risk, and answering
    // one must never read as answering the other.
    const blackholeClass = deriveBlackholeClassification(controlState);
    findings.push(mkFinding({
      module: 'Security', category: 'security',
      sev: blackholeClass === BLACKHOLE_CLASSIFICATIONS.VERIFIED ? 'ok' : 'info',
      confidence: controlState.confidence,
      headline: `Blackhole / Issuer Immutability: ${blackholeClass}`,
      detail: blackholeClass === BLACKHOLE_CLASSIFICATIONS.VERIFIED
        ? 'Master signing authority disabled, no remaining signer authority exists, and the regular key (if any) points to a provably unusable address — this account can no longer originate normal new transactions. This is an immutable ledger state, not a security concern.'
        : blackholeClass === BLACKHOLE_CLASSIFICATIONS.INCOMPLETE
          ? 'The master key is disabled, but a working key still exists (either an arbitrary regular key, or proof the master key has been re-enabled from this exact state before) — this account is NOT reliably immutable, regardless of how it may appear at first glance.'
          : blackholeClass === BLACKHOLE_CLASSIFICATIONS.UNABLE_TO_VERIFY
            ? 'Available data is insufficient to classify this account\'s immutability with confidence.'
            : 'This account retains working signing authority (an active master key, or a reachable signer quorum) — it is not blackholed.',
      observed: [
        `Master key: ${controlState.masterDisabled ? 'disabled' : 'active'}`,
        `Regular key: ${controlState.hasRegularKey ? acct.RegularKey : 'not set'}`,
        `Signer list: ${controlState.hasSignerList ? `${signerLists.length} list(s)` : 'none'}`,
      ],
      classification: 'Verified blackholing is immutable and permanent — it does not expire and cannot be reversed. It is also the single safest state against future key compromise, since no key remains for an attacker to ever steal or misuse. This classification says nothing about whether the account\'s PAST activity was legitimate.',
    }));
  }

  // 2. Regular key set — check if it changed recently
  if (hasRegularKey) {
    const setKeyTx = txList.find(({ tx }) => tx.TransactionType === 'SetRegularKey');
    const recentChange = setKeyTx &&
      (Date.now() / 1000 - getCloseTime(setKeyTx.tx)) < 86400 * 30;

    if (blackholed) {
      findings.push({
        sev: 'info',
        label: 'Regular key points to blackhole address',
        detail: acct.RegularKey,
        kind: 'current',
      });

    } else if (recentChange) {
      findings.push({
        sev: 'warn',
        label: 'Regular key set recently',
        detail: `Key: ${acct.RegularKey} — changed within 30 days. Verify you intended this.`,
        kind: 'change',
        hashes: setKeyTx.tx.hash ? [setKeyTx.tx.hash] : [],
      });
      score -= 15;

    } else {
      findings.push({
        sev: 'info',
        label: 'Regular key active',
        detail: acct.RegularKey,
        kind: 'current',
      });
    }
  }

  // 3. Signer list analysis
  signerLists.forEach(sl => {
    const entries = sl.SignerEntries || [];
    const quorum  = sl.SignerQuorum || 1;
    findings.push({
      sev: 'info',
      label: `Multisig: ${entries.length} signers, quorum ${quorum}`,
      detail: entries.map(e => shortAddr(e.SignerEntry?.Account || '')).join(', '),
      kind: 'current',
    });
  });

  // 4. Global freeze
  if (flags & FLAGS.lsfGlobalFreeze) {
    findings.push({
      sev: 'warn',
      label: 'Global Freeze active',
      detail: 'This issuer has frozen all token balances.',
      kind: 'current',
    });
    score -= 10;
  }

  // 5. Deposit auth
  if (flags & FLAGS.lsfDepositAuth) {
    findings.push({
      sev: 'ok',
      label: 'Deposit Authorization enabled',
      detail: 'Only pre-authorized senders can deposit.',
      kind: 'current',
    });
  }

  // 6. Default ripple
  if (flags & FLAGS.lsfDefaultRipple) {
    findings.push({
      sev: 'info',
      label: 'Default Ripple enabled',
      detail: 'Balances can ripple through this account (issuer behaviour).',
      kind: 'current',
    });
  }

  // 7. AccountDelete attempts
  const deleteTxs = txList.filter(({ tx }) => tx.TransactionType === 'AccountDelete');
  if (deleteTxs.length) {
    findings.push({
      sev: 'warn',
      label: `${deleteTxs.length} AccountDelete attempt(s)`,
      detail: 'Account deletion was attempted.',
      kind: 'change',
    });
    score -= 5;
  }

  // 8. The remaining lsf* flags — previously decoded to display pills only,
  // with no explanatory finding anywhere. All are neutral account
  // preferences, not risk signals, so these are informational only.
  if (flags & FLAGS.lsfRequireAuth) {
    findings.push({ sev: 'info', label: 'Require Auth enabled', detail: 'This account must individually approve each trustline before it can hold a balance — restricts who can hold what it issues.', kind: 'current' });
  }
  if (flags & FLAGS.lsfNoFreeze) {
    findings.push({ sev: 'info', label: 'No Freeze enabled', detail: 'This account has permanently given up the ability to freeze trustlines — an irreversible choice, typically made to reassure holders.', kind: 'current' });
  }
  if (flags & FLAGS.lsfRequireDestTag) {
    findings.push({ sev: 'info', label: 'Require Destination Tag enabled', detail: 'Payments to this account must include a destination tag — common for exchange/custodial deposit accounts.', kind: 'current' });
  }
  if (flags & FLAGS.lsfDisallowXRP) {
    findings.push({ sev: 'info', label: 'Disallow XRP flag set', detail: 'A client-side hint requesting senders avoid sending XRP to this account. Not enforced by the protocol — XRP can still be sent.', kind: 'current' });
  }
  if (flags & FLAGS.lsfPasswordSpent) {
    findings.push({ sev: 'info', label: 'Password Spent flag set', detail: 'This account has already used its one free SetRegularKey transaction; further regular-key changes will cost the standard transaction fee.', kind: 'current' });
  }

  // A default-configuration wallet (master key active, no regular key, no
  // signer list, no flags set, no delete attempts) trips none of the checks
  // above and used to leave `findings` empty — every sibling analyzer
  // (drain risk, wash trading, token issuer, AMM, ...) has an explicit
  // "nothing found" fallback except this one, so the Security Audit panel —
  // usually the first thing a reader looks at — rendered completely blank
  // for what's actually the most common case, reading as broken rather than
  // "checked, nothing to flag."
  if (findings.length === 0) {
    findings.push({
      sev: 'ok',
      label: 'No security issues detected',
      detail: 'Master key active, no regular key or signer list overrides, no risky flags set.',
      kind: 'current',
    });
  }

  return { findings, score: Math.max(0, score), controlState };
}

/* ── Drain Risk ──────────────────────────────────── */
/* ── Account Compromise Risk ──
   Permission/key-state signals only — "could someone ELSE drain this
   account because its access controls are compromised." Kept from the
   original analyseDrainRisk almost unchanged, minus the one check that was
   actually behavioral (large outflow after an auth change) — that's a
   specific case the new Asset Drain Behavior engine below now detects on
   its own merits (tagged triggeredByAuthChange), not a prerequisite for
   detecting a drain. */
function analyseAccountCompromiseRisk(acct, flags, signerLists, txList, paychans, escrows) {
  const signals = [];
  let riskLevel = 'low'; // low | medium | high | critical
  // Distinguishes WHY riskLevel left 'low' for the regular-key cases
  // specifically — 'self-set' (deliberate hardening) and 'unknown-setter'
  // (incomplete history, not evidence of anything) both land on the SAME
  // 'medium' riskLevel but describe very different realities. A plain-
  // language summary that only sees the level, not this reason, can end up
  // telling a security-conscious user who hardened their own account that
  // "this commonly appears in account takeovers" — alarming language that
  // contradicts the finding's own, more careful text one line away.
  let keyControlReason = null;

  const masterOff  = !!(flags & FLAGS.lsfDisableMaster);
  const blackholed = isIntentionalBlackhole(acct, flags, signerLists, txList);
  const issuerLike = looksLikeIssuer(acct, flags, txList);

  if (blackholed) {
    signals.push({
      sev: 'info',
      label: 'Intentional blackhole detected',
      detail: `Master key is disabled and regular key ${acct.RegularKey} is a known blackhole address. This is typical for a permanently locked issuer/account, not a classic drain setup.`
    });
    if (issuerLike) {
      signals.push({
        sev: 'warn',
        label: 'Caution: sending assets back may burn them',
        detail: 'Because this account appears to be an intentionally blackholed issuer, sending issued tokens back to it may strand or effectively burn those tokens.'
      });
    }
  } else if (masterOff && acct.RegularKey) {
    // Master-key-disabled + regular-key-controlled is NOT on its own
    // evidence of compromise — the identical on-chain state also describes
    // a well-known, recommended self-custody pattern (cold-store the
    // master seed, sign day-to-day with a regular key instead). A blanket
    // 'critical' here would tell every security-conscious user who's done
    // exactly that "classic drain setup detected," which is a real false
    // positive this account state cannot avoid producing on its own. The
    // one thing that actually discriminates compromise from deliberate
    // hardening is WHO set the currently-active regular key — check the
    // most recent SetRegularKey transaction visible in the fetched history.
    const regularKeyChanges = txList
      .filter(({ tx }) => tx.TransactionType === 'SetRegularKey')
      .sort((a, b) => (b.tx.date || 0) - (a.tx.date || 0));
    const latestChange = regularKeyChanges[0];
    const setByOwner = latestChange ? latestChange.tx.Account === acct.Account : null;

    // If the inspected address is one of THIS user's own signable wallets,
    // offer a direct link to that wallet's real Revoke action instead of
    // just describing the problem — the original ask behind this whole
    // check ("one-tap directly from Inspector finding"). Only meaningful
    // for a signable wallet (this app holds no seed for a watch-only one),
    // and offered regardless of setByOwner — revoking works the same way
    // either way, and the messaging above already makes clear how
    // concerning (or not) each case actually is.
    const ownWallet = getOwnSignableWallet(acct.Account);
    const revokeCta = ownWallet
      ? { label: '🛡 Open Security Actions for this wallet', onclick: `window.showProfile(); setTimeout(function(){ window.openSecurityActionsModal('${ownWallet.id}','revoke'); }, 300);` }
      : null;

    if (setByOwner === false) {
      signals.push({
        sev: 'critical',
        label: 'Classic drain setup detected — regular key was set by a DIFFERENT account',
        detail: `Master key disabled. The currently-active regular key ${acct.RegularKey} was set by ${latestChange.tx.Account}, not this account's own signature — meaning this account never authorized its own current signing key. If this wasn't you, funds are at serious risk.`,
        ...(revokeCta ? { actionCta: revokeCta } : {}),
      });
      riskLevel = 'critical';
      keyControlReason = 'different-account';
    } else if (setByOwner === true) {
      signals.push({
        sev: 'warn',
        label: 'Master key disabled — signing via a regular key this account set itself',
        detail: `Master key disabled. Regular key ${acct.RegularKey} was set by this account's own signature, consistent with deliberate self-custody hardening (cold-storing the master seed, signing day-to-day with a regular key instead) rather than a takeover. Only a genuine concern if you did not set this up yourself.`,
        ...(revokeCta ? { actionCta: revokeCta } : {}),
      });
      if (riskLevel === 'low') riskLevel = 'medium';
      keyControlReason = 'self-set';
    } else {
      signals.push({
        sev: 'warn',
        label: 'Master key disabled, regular key controls this account',
        detail: `Master key disabled. Regular key ${acct.RegularKey} controls the account, but the transaction that originally set it isn't in the fetched history, so who set it can't be confirmed here — could be deliberate self-custody hardening or a sign of compromise.`,
        ...(revokeCta ? { actionCta: revokeCta } : {}),
      });
      if (riskLevel === 'low') riskLevel = 'medium';
      keyControlReason = 'unknown-setter';
    }
  }

  const keyChanges = txList.filter(({ tx }) => tx.TransactionType === 'SetRegularKey' && tx.Account !== acct.Account);
  if (!blackholed && keyChanges.length) {
    const ownWallet2 = getOwnSignableWallet(acct.Account);
    signals.push({
      sev: 'critical',
      label: 'Regular key set by external account',
      detail: `${keyChanges.length} key change(s) where sender ≠ account owner. This is unusual.`,
      ...(ownWallet2 ? { actionCta: { label: '🛡 Open Security Actions for this wallet', onclick: `window.showProfile(); setTimeout(function(){ window.openSecurityActionsModal('${ownWallet2.id}','revoke'); }, 300);` } } : {}),
    });
    riskLevel = 'critical';
    keyControlReason = 'different-account';
  }

  if (paychans.length) {
    const totalLocked = paychans.reduce((acc, p) => acc + Number(p.Amount || 0) / 1e6, 0);
    signals.push({
      sev: 'warn',
      label: `${paychans.length} open payment channel(s) — ${fmt(totalLocked, 2)} XRP locked`,
      detail: `Destination(s): ${paychans.map(p => shortAddr(p.Destination)).join(', ')}`
    });
    if (riskLevel === 'low') riskLevel = 'medium';
  }

  if (escrows.length) {
    const totalEscrowed = escrows.reduce((acc, e) => acc + Number(e.Amount || 0) / 1e6, 0);
    signals.push({
      sev: 'info',
      label: `${escrows.length} open escrow(s) — ${fmt(totalEscrowed, 2)} XRP escrowed`,
      detail: `Escrow(s): ${escrows.map(e => e.Destination ? shortAddr(e.Destination) : 'self-escrow').join(', ')}`
    });
  }

  const authGrants = txList.filter(({ tx }) => tx.TransactionType === 'DepositPreauth' && tx.Authorize);
  if (authGrants.length > 5) {
    signals.push({
      sev: 'warn',
      label: `${authGrants.length} DepositPreauth grants issued`,
      detail: 'Account pre-authorized many senders. Review if all are trusted.'
    });
    if (riskLevel === 'low') riskLevel = 'medium';
  }

  if (signals.length === 0) {
    signals.push({ sev: 'ok', label: 'No compromise-risk patterns detected', detail: 'Auth structure looks intact.' });
  }

  return { signals, riskLevel, keyControlReason };
}

/* ── Asset Drain Behavior ──
   "Is value actually leaving abnormally" — independent of whether keys
   were ever touched. An account can have fully secure, untouched keys
   while its own authorized owner deliberately empties it; this engine
   catches that case too, which the old file's auth-change-gated check
   structurally could not. */
function analyseAssetDrainBehavior(txList, addr, currentBalXrp, historyCoverage = {}, isProjectAccount = false) {
  const balanceHistory = reconstructBalanceHistory(txList, addr, currentBalXrp);
  const rawEpisodes = findDrainEpisodes(balanceHistory, txList, addr, historyCoverage);
  const episodes = rawEpisodes.map(ep => _enrichDrainEpisode(ep, balanceHistory, txList, addr));

  const findings = [];
  let severity = 'none'; // none | low | medium | high | critical

  for (const ep of episodes) {
    const windowLabel = ep.windowSec === 86400 ? '24h' : `${Math.round(ep.windowSec / 86400)}d`;
    const incompleteData = ep.dataCompleteness !== 'complete';

    // Observed: facts read directly off the ledger — raw amounts, dates,
    // counts, and booleans. Nothing here required deriving a ratio.
    const observed = [
      `${fmt(ep.grossOutflowXrp, 2)} XRP gross outflow and ${fmt(ep.grossInflowXrp, 2)} XRP gross inflow within ${windowLabel} (opening balance ${fmt(ep.openingBalanceXrp, 2)} XRP, closing ${fmt(ep.closingBalanceXrp, 2)} XRP)`,
      ep.newRecipientPct != null ? `${ep.newDestCount} of ${ep.episodeDestCount} destinations were first-time recipients` : null,
      ep.trustlineLiquidations.length ? `${ep.trustlineLiquidations.length} token position(s) liquidated shortly before/during this window` : null,
      ep.dexConversionPrecedingWithdrawal ? 'A token→XRP conversion occurred in the 48h before this outflow began' : null,
      ep.triggeredByAuthChange ? 'A regular-key or signer-list change occurred immediately before this window' : null,
      !ep.baselineApplicable ? `This account has only ${ep.baselineSampleSize} prior outbound payment(s) — not enough history to establish a reliable "typical transfer size" baseline, so no size-anomaly comparison is made below` : null,
    ].filter(Boolean);

    // Calculated: deterministic metrics derived from the observed facts above.
    const calculated = [
      `Actual balance depletion: ${(ep.actualDepletionPct * 100).toFixed(1)}% (opening ${fmt(ep.openingBalanceXrp, 2)} → closing ${fmt(ep.closingBalanceXrp, 2)} XRP)`,
      `Gross turnover: ${(ep.grossTurnoverPct * 100).toFixed(0)}% of opening balance — this measures volume moved, not wealth lost, and can exceed 100% for a wallet that passes funds through`,
      ep.newRecipientPct != null ? `${(ep.newRecipientPct * 100).toFixed(0)}% of destinations were first-time recipients` : null,
      ep.topDestShare != null ? `${(ep.topDestShare * 100).toFixed(0)}% of the outflow went to a single destination` : null,
      ep.transferSizeAnomaly ? `Transfer sizes in this window are ${(ep.episodeMedianXrp / ep.historicalMedianXrp).toFixed(1)}x this account's own historical median transfer size (based on ${ep.baselineSampleSize} prior payments)` : null,
      ep.exceedsOwnP95 ? `This window's median transfer (${fmt(ep.episodeMedianXrp, 2)} XRP) exceeds this account's own 95th-percentile historical transfer size (${fmt(ep.baselineP95Xrp, 2)} XRP)` : null,
    ].filter(Boolean);

    // Whether anything BEYOND raw depletion percentage corroborates a
    // compromise-style read of this episode — computed once, before both
    // the hypothesis and severity below, so they can't drift apart on the
    // same underlying question. A raw percentage alone is exactly as
    // consistent with the owner's own deliberate transfer as with a real
    // drain; these are the specific signals that point away from that
    // ambiguity: mostly brand-new destinations, a liquidate-then-withdraw
    // sequence, or a transfer that breaks this account's own established
    // size pattern. Tracked as a named checklist (not just a count) so the
    // finding can show exactly which signals fired and which didn't,
    // rather than asking the reader to trust an opaque severity label.
    // Pass-through gets its own lead item ahead of the general checklist
    // below — this is the SPECIFIC reason a large-looking gross outflow
    // wasn't classified as a drain at all (as opposed to sweep/potential-
    // drain, which ARE net outflows and rely purely on the general
    // checklist to explain why they weren't escalated further).
    const passThroughItem = ep.classification === 'pass-through'
      ? [{ ok: true, fired: '', clear: `Inflow (${fmt(ep.grossInflowXrp, 2)} XRP) largely offset the outflow within this window — most of the value passed through rather than permanently leaving` }]
      : [];
    const corroborationChecklist = [
      ...passThroughItem,
      { ok: !ep.triggeredByAuthChange, fired: 'Authorization/security configuration changed shortly before this outflow', clear: 'No recent authorization or security configuration change' },
      { ok: !(ep.newRecipientPct != null && ep.newRecipientPct > 0.7), fired: `${((ep.newRecipientPct ?? 0) * 100).toFixed(0)}% of destinations were first-time recipients, not previously used`, clear: 'Destination(s) previously used, or too few destinations to judge' },
      { ok: !(ep.dexConversionPrecedingWithdrawal && ep.trustlineLiquidations.length > 0), fired: 'Assets were liquidated (converted to XRP) shortly before this outflow began', clear: 'No liquidate-then-withdraw sequence' },
      { ok: !(ep.transferSizeAnomaly && ep.exceedsOwnP95), fired: `Transfer size breaks this account's own established pattern (exceeds its 95th-percentile historical transfer)`, clear: 'Transfer size is within this account\'s own historical pattern' },
    ];
    const corroboratingSignals = corroborationChecklist.filter(c => !c.ok).length;
    const isCorroborated = corroboratingSignals > 0;
    const corroborationSummary = corroborationChecklist.map(c => c.ok ? `✓ ${c.clear}` : `⚠ ${c.fired}`);
    // Attached back onto the episode (not just used locally below) so other
    // modules that consume these same episodes — Memo-Drain Correlation, in
    // particular — can defer to this same corroboration gate instead of
    // re-deriving their own cruder one from `classification` alone, which
    // silently bypassed this requirement (see that function's own comment).
    ep.isCorroborated = isCorroborated;

    // Inferred: behavioral judgments relative to this account's own history
    // or established patterns — a step beyond the calculated numbers above.
    const inferred = [
      ep.transferSizeAnomaly ? 'This transfer pattern is unusual relative to this account\'s own established behavior, not just large in absolute terms' : null,
      ep.classification === 'sweep' ? 'The balance trajectory is consistent with an intentional consolidation of most available funds, not incidental turnover' : null,
      ep.classification === 'potential-drain' ? 'The balance trajectory is consistent with a substantial, non-recovered loss of previously-held funds' : null,
    ].filter(Boolean);

    // Hypothesis: an explicitly unproven possible explanation — kept
    // separate from `classification` (which stays a caveat about what the
    // finding can and can't establish). Only populated when there's an
    // actual auth-change precursor OR at least one independent
    // corroborating signal beyond raw percentage — naming an "unauthorized
    // depletion" hypothesis for a plain large transfer with nothing else
    // pointing toward compromise would overstate what the evidence shows.
    const hypothesis = (ep.triggeredByAuthChange || ((ep.classification === 'potential-drain' || ep.classification === 'sweep') && isCorroborated))
      ? (ep.triggeredByAuthChange
          ? 'This movement may represent unauthorized depletion following account-control changes.'
          : 'This movement may represent unauthorized depletion, though a deliberate self-directed transfer remains equally consistent with the same ledger evidence.')
      : null;

    const evidenceAgainstBenign = [];
    if (ep.classification === 'pass-through') evidenceAgainstBenign.push('Balance depletion is minimal — inflow within the window nearly offset the outflow, consistent with funds passing through rather than being lost');
    if (ep.newRecipientPct != null && ep.newRecipientPct > 0.7) evidenceAgainstBenign.push('Nearly all destinations are first-time recipients, not established counterparties');
    if (ep.triggeredByAuthChange) evidenceAgainstBenign.push('Outflow immediately follows an authorization change — the classic compromise-then-drain sequence');
    if (ep.dexConversionPrecedingWithdrawal && ep.trustlineLiquidations.length) evidenceAgainstBenign.push('Assets were converted to XRP shortly before leaving, consistent with liquidating a position specifically to withdraw everything');

    const destKnown = ep.destinations.some(d => d.entity);

    // Pure balance movement — however large a share of the opening balance
    // — is exactly as consistent with the account's own owner consolidating
    // funds as with an actual drain; nothing in this account's own history
    // can tell those apart on its own. For an ordinary personal/unknown-
    // role account, that ambiguity means a raw percentage shouldn't alone
    // earn more than an informational note (per the account-role review
    // this logic was built against: "do not treat spending one's own funds
    // as inherently dangerous"). It's promoted to 'warn' only when
    // isCorroborated (computed above, alongside hypothesis) is true.
    // `triggeredByAuthChange` remains the only signal that's actually
    // specific to compromise rather than equally explained by ordinary
    // asset movement, so it's the only thing that earns 'critical'.
    //
    // A detected token issuer gets different treatment, not softer
    // treatment: its own outflows are framed as treasury events (still
    // 'warn' at most without an auth-change precursor, per the same
    // compromise-ambiguity logic), since "drain" language implies personal
    // fund loss that doesn't fit an operational/issuer account's role.
    let sev;
    if (ep.classification === 'pass-through') sev = 'info';
    else if (ep.triggeredByAuthChange) sev = 'critical';
    else if (ep.classification === 'sweep' || ep.classification === 'potential-drain') {
      sev = (isProjectAccount || isCorroborated) ? 'warn' : 'info';
    }
    else sev = 'info';
    if (sev === 'critical') severity = 'critical';
    else if (sev === 'warn' && severity !== 'critical') severity = severity === 'none' || severity === 'low' ? 'high' : severity;

    const baseConfidence = ep.triggeredByAuthChange ? 0.75 : isCorroborated ? 0.55 : 0.35;
    const confidence = incompleteData ? baseConfidence * 0.6 : baseConfidence;

    const classificationLabel = {
      'sweep': isProjectAccount ? 'Treasury outflow — most of the opening balance left with little offsetting inflow.' : 'Large balance movement — most of the opening balance left with little offsetting inflow.',
      'pass-through': 'Pass-through — funds moved through the account; little of its own opening balance was actually lost.',
      'potential-drain': isProjectAccount ? 'Significant treasury outflow — a substantial share of the opening balance is genuinely gone by the end of this window.' : 'Large balance movement — a substantial share of the opening balance is genuinely gone by the end of this window.',
      'partial-outflow': 'Partial outflow — a moderate, ambiguous balance change.',
    }[ep.classification] || '';

    // Owner impact vs. ecosystem impact: the same transaction means
    // something different depending on whether other people/assets
    // depend on this account. A personal wallet's own outflow affects
    // only its owner; a detected issuer's outflow is at least worth
    // framing as potentially touching whatever that issuer supports —
    // though this app has no project-registry data to confirm that link,
    // so it's stated as a role-based possibility, not a verified fact.
    const impactNote = (ep.classification === 'sweep' || ep.classification === 'potential-drain')
      ? (isProjectAccount
          ? 'Ecosystem impact: this account is independently identified as a token issuer — outflows from it may affect token holders or liquidity it supports, though no project-registry data confirms that relationship. Owner impact: high (own reserve/holdings reduced).'
          : 'Owner impact: high (a large share of this account\'s own funds moved). Ecosystem impact: none identified — no issuer, treasury, or custodial role was found for this account, so this movement has no established effect beyond its own owner.')
      : null;

    // The corroboration checklist only makes sense to show for the two
    // classifications where it actually drove the severity decision above
    // (sweep/potential-drain) — surfaced as its own labeled block so the
    // reason a transfer was or wasn't escalated is visible directly,
    // rather than something the reader has to infer from a severity label.
    const showsChecklist = ep.classification === 'sweep' || ep.classification === 'potential-drain' || ep.classification === 'pass-through';
    const checklistHeader = showsChecklist
      ? (sev === 'critical' || sev === 'warn' ? 'Why this was flagged beyond an informational note:' : 'Why this wasn\'t flagged as a drain:')
      : null;
    const observedWithExtras = [
      ...observed,
      ...(impactNote ? [impactNote] : []),
      ...(showsChecklist ? [checklistHeader, ...corroborationSummary] : []),
    ];

    const episodeFinding = mkFinding({
      module: 'Asset Drain Behavior', category: 'security', sev, confidence,
      headline: `${classificationLabel.split(' — ')[0]}: ${fmt(ep.grossOutflowXrp, 2)} XRP gross outflow, ${(ep.actualDepletionPct * 100).toFixed(0)}% actual depletion within ${windowLabel}`,
      detail: `Sliding-window balance reconstruction (gross outflow, gross inflow, and opening-vs-closing balance tracked separately).${incompleteData ? ' Confidence reduced: transaction history for this period could not be fully verified as complete.' : ''}`,
      observed: observedWithExtras,
      calculated, inferred, hypothesis,
      alternativeExplanations: [
        isProjectAccount
          ? 'Routine treasury activity — operational spending, exchange liquidity funding, market-making allocation, or planned distribution'
          : 'A planned, deliberate transfer by the account\'s own owner (exchange withdrawal, consolidation, moving to a new wallet)',
        destKnown ? 'Destination is a known exchange or labeled entity, consistent with a routine cash-out' : 'Destination(s) not in the known-entity registry — inconclusive either way',
      ],
      evidenceAgainstBenign,
      classification: `${classificationLabel} ${ep.triggeredByAuthChange
        ? 'Outflow following an authorization change is a strong compromise-and-drain signal, but ledger data alone cannot distinguish an attacker from an owner who changed their own key and then withdrew funds themselves.'
        : isCorroborated
          ? 'This describes behavior, not intent — see Account Compromise Risk above for whether the account\'s access controls show separate signs of being compromised.'
          : 'No independent evidence of compromise was found (no authorization change, no liquidate-then-withdraw sequence, no break from this account\'s own established transfer pattern) — the available evidence is more consistent with ordinary, self-directed asset movement than a security event.'}`,
      hashes: ep.episodeHashes || [],
    });
    // mkFinding() only accepts a fixed, whitelisted set of fields — this
    // real per-episode destination breakdown (already computed above by
    // _enrichDrainEpisode, just never surfaced) is attached directly onto
    // the returned object afterward rather than widening that shared
    // function's signature for one call site.
    episodeFinding.episodeDestinations = ep.destinations;
    episodeFinding.episodeGrossOutflowXrp = ep.grossOutflowXrp;
    findings.push(episodeFinding);
  }

  if (!findings.length) {
    findings.push(mkFinding({ module: 'Asset Drain Behavior', category: 'security', sev: 'ok', headline: 'No abnormal depletion detected', detail: 'No window scanned showed a large, fast balance drop relative to this account\'s own history.' }));
  }

  return { episodes, findings, severity, balanceHistory };
}

const _DRAIN_SEVERITY_ORDER = { low: 0, medium: 1, high: 2, critical: 3, none: -1 };

/* ── Backward-compat combiner ──
   Keeps the function name and the fields computeOverallRisk/buildRiskBreakdown
   already read (`signals`, `riskLevel`) so this pass doesn't need to touch
   their signatures. riskLevel is now the max of both sub-analyses — the old
   auth-change-gated outflow check fed 'critical' into this same field, and
   the new engine catches strictly more drain patterns than that one check
   did, so this is a strict sensitivity improvement, not a regression. */
/** "Is This Normal?" — a standalone, beginner-facing comparison for this
 *  account's MOST RECENT outbound XRP transfer against its own PRIOR
 *  history, independent of whether that transfer was large enough to
 *  trigger a full Drain Risk episode (a >50%-of-balance-in-one-window
 *  threshold). Deliberately evaluates the most recent transfer, not the
 *  largest-ever one: comparing "the biggest transfer this account has
 *  ever made" against a baseline that necessarily INCLUDES that same
 *  transfer would trivially land at the 100th percentile every time (it
 *  is, by definition, >= everything else in its own sample) — a
 *  comparison that can never actually discriminate normal from unusual.
 *  The baseline here explicitly EXCLUDES the transfer being evaluated,
 *  matching the same exclusion principle _computeAccountBaseline already
 *  uses for Drain Risk's own per-episode baseline. */
function analyseIsThisNormal(txList, addr) {
  const payments = txList
    .filter(({ tx }) => tx.TransactionType === 'Payment' && tx.Account === addr && typeof tx.Amount === 'string')
    .map(({ tx }) => ({ date: tx.date, hash: tx.hash, xrp: Number(tx.Amount) / 1e6 }))
    .filter(p => p.xrp > 0 && p.date != null)
    .sort((a, b) => a.date - b.date);

  const BASELINE_MIN = 8;
  if (payments.length < BASELINE_MIN + 1) {
    return { applicable: false, reason: `Only ${payments.length} outbound payment(s) — not enough history for a percentile comparison`, sampleSize: payments.length };
  }

  const mostRecent = payments[payments.length - 1];
  const baseline = payments.slice(0, -1).map(p => p.xrp).sort((a, b) => a - b); // excludes the evaluated transfer itself
  const percentile = (baseline.filter(v => v <= mostRecent.xrp).length / baseline.length) * 100;

  const AUTH_CHANGE_TYPES = new Set(['SetRegularKey', 'SignerListSet']);
  const priorAuthChange = txList.some(({ tx }) =>
    AUTH_CHANGE_TYPES.has(tx.TransactionType) && tx.Account === addr && tx.date != null &&
    tx.date < mostRecent.date && mostRecent.date - tx.date <= 86400);

  const verdict = priorAuthChange ? 'unusual-with-auth-change' : percentile >= 95 ? 'unusual-size' : 'normal';
  const conclusion = priorAuthChange
    ? 'A security/authorization change occurred shortly before this transfer — worth reviewing alongside Account Compromise Risk above.'
    : percentile >= 95
      ? `This transfer is larger than ${percentile.toFixed(0)}% of this account's own prior transfers — unusually large for THIS account specifically, though ledger data alone cannot say why.`
      : 'No unusual compromise pattern detected — this transfer size fits this account\'s own historical pattern, and no authorization change preceded it.';

  return { applicable: true, evaluatedTransfer: mostRecent, percentile, sampleSize: baseline.length, priorAuthChange, verdict, conclusion };
}

function analyseDrainRisk(acct, flags, signerLists, txList, paychans, escrows, addr, currentBalXrp, historyCoverage, isProjectAccount = false) {
  const compromise = analyseAccountCompromiseRisk(acct, flags, signerLists, txList, paychans, escrows);
  const behavior    = analyseAssetDrainBehavior(txList, addr, currentBalXrp, historyCoverage, isProjectAccount);

  // 'high' must stay 'high', not be upgraded to 'critical' here — behavior
  // (raw balance-movement) severity only actually reaches 'critical' when a
  // specific episode was triggeredByAuthChange (see analyseAssetDrainBehavior);
  // 'high' means a large, fast depletion with no such confirmed compromise
  // signal, which is exactly as consistent with the owner's own deliberate
  // transfer as with a real drain. Collapsing that distinction back out here
  // would silently undo the point of that gate.
  const behaviorAsRiskLevel = behavior.severity === 'none' ? 'low' : behavior.severity;
  const riskLevel = _DRAIN_SEVERITY_ORDER[behaviorAsRiskLevel] > _DRAIN_SEVERITY_ORDER[compromise.riskLevel] ? behaviorAsRiskLevel : compromise.riskLevel;
  const isThisNormal = analyseIsThisNormal(txList, addr);

  return {
    signals: [...compromise.signals, ...behavior.findings],
    riskLevel,
    compromiseRiskLevel: compromise.riskLevel,
    keyControlReason: compromise.keyControlReason,
    assetDrainSeverity: behavior.severity,
    episodes: behavior.episodes,
    balanceHistory: behavior.balanceHistory,
    isThisNormal,
  };
}
// Minted NFTokenIDs from a NFTokenMint's own metadata — mirrors xrpl.js's
// extractMintedNftIds (that copy enriches the live dashboard's recent-tx
// feed; this one reads txList's own AffectedNodes, kept local rather than
// shared since the two files serve different enough shapes to not be worth
// a cross-file import for one small helper).
function _mintedNftIdsFromMeta(meta) {
  const out = new Set();
  const nodes = meta?.AffectedNodes || [];
  const idsFromTokens = (tokens) => (Array.isArray(tokens) ? tokens : [])
    .map(t => t?.NFToken?.NFTokenID || t?.NFTokenID).filter(Boolean);
  for (const wrap of nodes) {
    const node = wrap?.CreatedNode || wrap?.ModifiedNode;
    if (!node || node.LedgerEntryType !== 'NFTokenPage') continue;
    const newIds = idsFromTokens(node.NewFields?.NFTokens);
    if (newIds.length) { newIds.forEach(id => out.add(id)); continue; }
    const finalIds = new Set(idsFromTokens(node.FinalFields?.NFTokens));
    const prevIds = new Set(idsFromTokens(node.PreviousFields?.NFTokens));
    for (const id of finalIds) if (!prevIds.has(id)) out.add(id);
  }
  return out;
}

/* ── NFT Risk ────────────────────────────────────── */
function analyseNftRisk(nfts, txList, addr) {
  const flags   = [];
  const nftMap  = new Map(nfts.map(n => [n.NFTokenID, n]));

  // 1. Suspicious NFT offers created by this account with Amount=0 or very
  // low — but only SELL offers (tfSellNFToken): a low-amount BUY offer
  // costs the creator nothing and isn't a drain vector at all — it's just
  // an ordinary lowball purchase attempt, not "you gave something away."
  const TF_SELL_NFTOKEN = 0x00000001;
  const nftOfferCreates = txList.filter(({ tx }) =>
    tx.TransactionType === 'NFTokenCreateOffer' && tx.Account === addr && (Number(tx.Flags) & TF_SELL_NFTOKEN)
  );
  const zeroAmtOffers = nftOfferCreates.filter(({ tx }) => {
    const amt = tx.Amount;
    if (!amt) return true; // no amount = free transfer offer
    if (typeof amt === 'string') return Number(amt) < 1000000; // < 1 XRP
    return false;
  });
  // A Destination-restricted zero/near-zero sell offer can only ever be
  // accepted by that one specific address — this is the standard,
  // legitimate mechanism for gifting an NFT to a known recipient, not a
  // drain vector. An OPEN offer (no Destination) can be snatched by anyone,
  // including a bot the instant it's created — that's the genuinely
  // dangerous shape real NFT-drain scams rely on. Conflating the two and
  // calling every near-zero sell offer "a common drain vector" at CRITICAL
  // severity was a real false positive for anyone who has ever gifted an
  // NFT to a friend.
  const openZeroAmtOffers = zeroAmtOffers.filter(({ tx }) => !tx.Destination);
  const giftedZeroAmtOffers = zeroAmtOffers.filter(({ tx }) => tx.Destination);
  if (openZeroAmtOffers.length) {
    // Before escalating an open near-zero offer to a drain warning, check
    // the same context a real investigator would (roadmap: NFT offer
    // context checks) — an open near-zero price alone is the SHAPE a real
    // drain scam uses, but self-minted giveaways and NFT-project
    // distribution habits use that exact same shape legitimately and far
    // more often than actual theft does.
    const mintedIds = new Set();
    for (const { tx: mtx, meta } of txList) {
      if (mtx.TransactionType === 'NFTokenMint' && mtx.Account === addr) {
        for (const id of _mintedNftIdsFromMeta(meta)) mintedIds.add(id);
      }
    }
    const authChangeTimes = txList
      .filter(({ tx }) => ['SetRegularKey', 'SignerListSet'].includes(tx.TransactionType))
      .map(({ tx }) => tx.date).filter(t => t != null);
    const AUTH_WINDOW_SEC = 48 * 3600;
    const isRoutineDistribution = zeroAmtOffers.length >= 3;

    const annotated = openZeroAmtOffers.map(({ tx }) => ({
      tx,
      selfMinted: tx.NFTokenID ? mintedIds.has(tx.NFTokenID) : false,
      stillHeld: tx.NFTokenID ? nftMap.has(tx.NFTokenID) : null, // null = NFTokenID unknown, can't tell
      nearbyAuthChange: tx.date != null && authChangeTimes.some(t => t <= tx.date && tx.date - t <= AUTH_WINDOW_SEC),
    }));
    const concerning = annotated.filter(o => !o.selfMinted && o.stillHeld === false && (o.nearbyAuthChange || !isRoutineDistribution));
    const benign = annotated.filter(o => !concerning.includes(o));

    if (concerning.length) {
      flags.push({ sev: 'critical',
        label: `${concerning.length} NFT sell offer(s) created for ≤1 XRP, open to anyone, and no longer held by this account`,
        detail: `These weren't self-minted, aren't part of a routine distribution pattern, and the NFT has since left this account${concerning.some(o => o.nearbyAuthChange) ? ' — with an authorization change shortly beforehand' : ''}. This is a common NFT drain vector: attackers trick victims into listing their NFTs this way, then snatch them for free.` });
    }
    if (benign.length) {
      const reasons = [];
      if (benign.some(o => o.selfMinted)) reasons.push('self-minted (consistent with an intentional giveaway)');
      if (isRoutineDistribution) reasons.push(`part of a routine pattern (${zeroAmtOffers.length} near-zero sell offers total)`);
      if (benign.some(o => o.stillHeld === true)) reasons.push('the NFT is still held by this account — the offer was never taken');
      flags.push({ sev: 'warn',
        label: `${benign.length} NFT sell offer(s) created for ≤1 XRP, open to anyone — worth reviewing`,
        detail: `Open near-zero offers are the shape a drain scam uses, but here: ${reasons.length ? reasons.join('; ') : 'no corroborating signal (authorization change, confirmed taking) was found'}. Worth reviewing, not a confirmed drain.` });
    }
  }
  if (giftedZeroAmtOffers.length) {
    flags.push({ sev: 'info', label: `${giftedZeroAmtOffers.length} NFT sell offer(s) created for ≤1 XRP, restricted to one recipient`,
      detail: 'These near-zero-price sell offers each name a specific Destination address — only that address can accept them, which is the standard mechanism for gifting an NFT to a known recipient, not an open drain vector. Only a concern if that destination address wasn\'t actually someone you intended to give it to.' });
  }

  // 2. NFTs accepted from unknown sources (NFTokenAcceptOffer)
  const nftAccepts = txList.filter(({ tx }) =>
    tx.TransactionType === 'NFTokenAcceptOffer' && tx.Account === addr
  );
  if (nftAccepts.length) {
    flags.push({ sev: 'warn', label: `${nftAccepts.length} NFT offer(s) accepted`,
      detail: 'Review these transactions to confirm they were intentional sales/purchases.' });
  }

  // 3. NFTs received that were immediately burned or transferred out
  const nftBurns = txList.filter(({ tx }) =>
    tx.TransactionType === 'NFTokenBurn' && tx.Account === addr
  );
  if (nftBurns.length) {
    flags.push({ sev: 'warn', label: `${nftBurns.length} NFT(s) burned`,
      detail: 'Burned NFTs cannot be recovered. Confirm these were intentional.' });
  }

  // 4. NFT mint then rapid transfer (< 10 ledgers)
  const mints    = txList.filter(({ tx }) => tx.TransactionType === 'NFTokenMint' && tx.Account === addr);
  const transfers = txList.filter(({ tx }) =>
    tx.TransactionType === 'NFTokenCreateOffer' || tx.TransactionType === 'NFTokenAcceptOffer'
  );
  if (mints.length > 0 && transfers.length > 0) {
    flags.push({ sev: 'info', label: `${mints.length} NFT(s) minted · ${transfers.length} transfer event(s)`,
      detail: 'This account has minting activity.' });
  }

  // 5. NFTs with TransferFee (royalty check)
  const royaltyNfts = nfts.filter(n => n.TransferFee && n.TransferFee > 0);
  if (royaltyNfts.length) {
    const avgFee = royaltyNfts.reduce((a, n) => a + n.TransferFee, 0) / royaltyNfts.length;
    flags.push({ sev: 'info', label: `${royaltyNfts.length} NFT(s) carry transfer fees (avg ${(avgFee / 1000).toFixed(1)}%)`,
      detail: 'These NFTs pay royalties on each transfer.' });
  }

  // 6. NFTs from suspicious issuers (non-standard URI or empty)
  const noUriNfts = nfts.filter(n => !n.URI);
  if (noUriNfts.length > 2) {
    flags.push({ sev: 'warn', label: `${noUriNfts.length} NFT(s) have no URI / metadata`,
      detail: 'NFTs without a URI may be spam or placeholder tokens used in scams.' });
  }

  if (flags.length === 0 && nfts.length === 0) {
    flags.push({ sev: 'ok', label: 'No NFT activity detected', detail: 'This account holds no NFTs.' });
  } else if (flags.length === 0) {
    flags.push({ sev: 'ok', label: `${nfts.length} NFT(s) held — no risk signals`, detail: 'NFT posture looks normal.' });
  }

  return { flags, nftCount: nfts.length, mintCount: mints.length, acceptCount: nftAccepts.length };
}

/* ── Offer Lifecycle Engine ──────────────────────────
   Reconstructs what actually happened to each of `addr`'s own OfferCreate
   transactions — created amount, whether/how much crossed immediately,
   whether a resting remainder was later cancelled, consumed by a third
   party, partially filled over time, or expired unfunded. Replaces the old
   same-transaction "does this tx's own AffectedNodes contain any DeletedNode
   Offer" proxy, which only detected an immediate cross and said nothing
   about a resting offer's eventual fate.

   Feasibility note: rippled's account_tx returns every transaction that
   AFFECTED the account per its own metadata, not just transactions it sent
   — so a later transaction where a third party crosses this account's
   resting offer should already be present in the already-fetched txList,
   with no extra RPC calls. This is the load-bearing assumption behind the
   "consumed-later" detection below.
──────────────────────────────────────────────────── */
const OFFER_FLAGS = { tfPassive: 0x00010000, tfImmediateOrCancel: 0x00020000, tfFillOrKill: 0x00040000, tfSell: 0x00080000 };

function _findOwnOfferNode(meta, addr) {
  // The CreatedNode Offer (if any) belonging to `addr` in this tx's own
  // metadata — its presence is what tells us a resting remainder exists.
  for (const node of (meta?.AffectedNodes || [])) {
    const c = node.CreatedNode;
    if (c?.LedgerEntryType === 'Offer' && c.NewFields?.Account === addr) return c;
  }
  return null;
}

function buildOfferLifecycles(txList, addr, coverage = {}) {
  const byOfferId = new Map();
  const list = [];
  const dataCompleteness = _historyCompletenessLabel(coverage);

  // ── Create pass ──────────────────────────────────────────────────────
  txList.forEach((entry, idx) => {
    const { tx, meta } = entry;
    if (tx.TransactionType !== 'OfferCreate' || tx.Account !== addr) return;
    if (meta?.TransactionResult !== 'tesSUCCESS') return; // failed offers never touched the ledger

    const takerGetsOriginal = { currency: amtCurrency(tx.TakerGets), issuer: typeof tx.TakerGets === 'object' ? tx.TakerGets.issuer : null, value: amtNum(tx.TakerGets) };
    const takerPaysOriginal = { currency: amtCurrency(tx.TakerPays), issuer: typeof tx.TakerPays === 'object' ? tx.TakerPays.issuer : null, value: amtNum(tx.TakerPays) };

    const ownNode = _findOwnOfferNode(meta, addr);
    const restingAmount = ownNode
      ? { gets: amtNum(ownNode.NewFields?.TakerGets), pays: amtNum(ownNode.NewFields?.TakerPays) }
      : null;
    // Derived from this transaction's REAL balance delta, not from
    // "original minus resting" — that subtraction silently assumed 100%
    // fill whenever nothing was left resting, which is correct for an
    // ordinary offer that fully crossed but WRONG for a tfImmediateOrCancel
    // order with a partial or zero fill: IOC never leaves a resting Offer
    // object regardless of how much (if anything) actually crossed, so the
    // old logic counted every such order as fully filled. extractBalanceDeltas
    // reports what genuinely moved in THIS transaction, which is correct
    // for both cases without needing to special-case IOC/FOK here.
    const createDelta = extractBalanceDeltas(tx, meta, addr);
    const _crossedSideAmount = (side) => {
      if (!side.currency) return 0;
      if (side.currency === 'XRP') return Math.abs(createDelta.xrpDelta);
      const td = createDelta.tokenDeltas.find(t => t.currency === side.currency && t.issuer === side.issuer);
      return td ? Math.abs(td.delta) : 0;
    };
    const crossedAtCreation = {
      gets: _crossedSideAmount(takerGetsOriginal),
      pays: _crossedSideAmount(takerPaysOriginal),
    };

    // Split by whose offer actually got crossed: a Deleted/Modified Offer
    // node owned by a DIFFERENT account is a real external counterparty: one
    // owned by `addr` itself means this creation crossed the account's OWN
    // other resting offer — a genuine self-trade signature, kept separate
    // rather than silently dropped, since Market-Maker Automation's
    // external-fill check (buildOfferBehaviorProfile) needs to tell the two
    // apart.
    const counterpartiesAtCreation = [];
    const selfCounterpartiesAtCreation = [];
    for (const node of (meta.AffectedNodes || [])) {
      const n = node.DeletedNode || node.ModifiedNode;
      if (!n || n.LedgerEntryType !== 'Offer') continue;
      const account = n.FinalFields?.Account;
      if (!account) continue;
      const entry = { account, gets: amtNum(n.FinalFields?.TakerGets), pays: amtNum(n.FinalFields?.TakerPays) };
      if (account === addr) selfCounterpartiesAtCreation.push(entry);
      else counterpartiesAtCreation.push(entry);
    }

    const flagsNum = Number(tx.Flags || 0);
    const flags = {
      passive: !!(flagsNum & OFFER_FLAGS.tfPassive),
      immediateOrCancel: !!(flagsNum & OFFER_FLAGS.tfImmediateOrCancel),
      fillOrKill: !!(flagsNum & OFFER_FLAGS.tfFillOrKill),
      sell: !!(flagsNum & OFFER_FLAGS.tfSell),
    };
    // An IOC/FOK order never leaves a resting Offer object, regardless of
    // how much actually crossed — "no resting node" alone can't tell a
    // genuine 100%-fill-and-done apart from an IOC that crossed 30% (or
    // 0%) and had the remainder killed. crossedAtCreation (now delta-
    // based, not assumed) resolves that ambiguity directly. Ordinary
    // (non-IOC/FOK) orders keep the original binary resting/filled read —
    // this distinction only matters for orders that CAN legitimately
    // leave real size unfilled with no resting record at all.
    let initialStatus;
    if (ownNode) {
      initialStatus = 'resting';
    } else if ((flags.immediateOrCancel || flags.fillOrKill) && takerGetsOriginal.value && crossedAtCreation.gets < takerGetsOriginal.value * 0.999) {
      initialStatus = crossedAtCreation.gets > 0 ? 'killed-partial' : 'killed-unfilled';
    } else {
      initialStatus = 'filled-immediately';
    }
    const record = {
      offerId: `${addr}:${tx.Sequence}`,
      createHash: tx.hash, createDate: tx.date, createLedgerIndex: ownNode?.LedgerIndex || null,
      takerGetsOriginal, takerPaysOriginal,
      offerSequence: tx.Sequence, replacesOfferSeq: tx.OfferSequence || null,
      flags,
      expiration: tx.Expiration || null,
      crossedAtCreation, counterpartiesAtCreation, selfCounterpartiesAtCreation,
      route: createDelta.route || null,
      restingAmount,
      status: initialStatus,
      consumedEvents: [],
      cancelHash: null, cancelDate: null,
      timeRestingSeconds: null, realizedFillPct: null,
      expiryUncertain: false,
      dataCompleteness,
      _createIdx: idx, // internal — position in txList, for the resolution pass below
    };
    byOfferId.set(record.offerId, record);
    list.push(record);
  });

  // ── Resolution pass ──────────────────────────────────────────────────
  // Only records that left something resting on the ledger need resolving.
  for (const record of list) {
    if (!record.createLedgerIndex) continue; // filled immediately (or killed via IOC/FOK) — nothing rests to track further

    for (let i = record._createIdx + 1; i < txList.length; i++) {
      const { tx, meta } = txList[i];
      if (meta?.TransactionResult !== 'tesSUCCESS' && meta?.TransactionResult !== 'tecKILLED' && !meta?.AffectedNodes?.length) continue;

      let matched = null;
      for (const node of (meta?.AffectedNodes || [])) {
        const c = node.CreatedNode, m = node.ModifiedNode, d = node.DeletedNode;
        const n = c || m || d;
        if (!n || n.LedgerEntryType !== 'Offer') continue;
        if (n.LedgerIndex !== record.createLedgerIndex) continue;
        matched = { node: n, kind: d ? 'deleted' : m ? 'modified' : 'created' };
        break;
      }
      if (!matched) continue;

      if (matched.kind === 'deleted') {
        const isOwnCancel = tx.Account === addr && tx.TransactionType === 'OfferCancel' && tx.OfferSequence === record.offerSequence;
        const isOwnReplace = tx.Account === addr && tx.TransactionType === 'OfferCreate' && tx.OfferSequence === record.offerSequence;
        if (isOwnCancel || isOwnReplace) {
          record.status = 'cancelled';
          record.cancelHash = tx.hash; record.cancelDate = tx.date;
        } else {
          // Distinguish "actually consumed" from "swept away as stale/
          // unfunded while processing an unrelated transaction" — check
          // whether addr's own balance moved as a result of this tx.
          const delta = extractBalanceDeltas(tx, meta, addr);
          const consumed = delta.xrpDelta !== 0 || delta.tokenDeltas.some(d => d.delta !== 0);
          if (consumed) {
            record.status = 'consumed-later';
            record.consumedEvents.push({ hash: tx.hash, date: tx.date, counterpartyAccount: tx.Account !== addr ? tx.Account : null });
          } else {
            record.status = 'expired';
            record.expiryUncertain = true; // removed as stale, not via a clean cancel/expiration match
          }
        }
        record.timeRestingSeconds = (tx.date ?? record.createDate) - record.createDate;
        record.dataCompleteness = record.dataCompleteness; // unchanged — resolved within fetched window
        break;
      }

      if (matched.kind === 'modified') {
        const newGets = amtNum(matched.node.FinalFields?.TakerGets);
        const newPays = amtNum(matched.node.FinalFields?.TakerPays);
        record.consumedEvents.push({
          hash: tx.hash, date: tx.date, counterpartyAccount: tx.Account !== addr ? tx.Account : null,
          gets: Math.max(0, (record.restingAmount?.gets ?? 0) - (newGets ?? 0)),
          pays: Math.max(0, (record.restingAmount?.pays ?? 0) - (newPays ?? 0)),
        });
        record.restingAmount = { gets: newGets, pays: newPays };
        record.status = 'partially-filled-then-resting';
        // keep scanning — this offer may be touched again later
      }
    }

    if (record.status === 'resting' || record.status === 'partially-filled-then-resting') {
      // Never resolved within the fetched window.
      const nowSec = Math.floor(Date.now() / 1000) - XRPL_EPOCH;
      const lastSeenDate = txList[txList.length - 1]?.tx?.date ?? nowSec;
      if (record.expiration != null && record.expiration <= lastSeenDate) {
        record.status = 'expired';
        record.expiryUncertain = true; // XRPL only removes expired offers lazily when touched
      } else {
        record.status = 'unknown-open';
      }
      record.timeRestingSeconds = lastSeenDate - record.createDate;
      if (record.dataCompleteness === 'possibly-truncated') {
        // An unresolved offer against a truncated fetch window genuinely
        // might have been resolved by a transaction we never fetched —
        // don't let 'unknown-open' read as a confirmed-still-open fact.
      }
    }
  }

  // realizedFillPct (and the _createIdx cleanup) apply to EVERY record,
  // not just ones that left something resting to resolve — both used to
  // live inside the loop above, gated behind the same
  // `if (!record.createLedgerIndex) continue` that skips resolution
  // entirely for a filled-immediately (or, since the IOC/FOK fix,
  // killed-partial/killed-unfilled) order, so realizedFillPct silently
  // stayed null and _createIdx silently leaked onto every such record.
  for (const record of list) {
    const consumedGets = record.consumedEvents.reduce((s, e) => s + (e.gets || 0), 0);
    const totalFilledGets = record.crossedAtCreation.gets + consumedGets;
    record.realizedFillPct = record.takerGetsOriginal.value
      ? Math.min(100, (totalFilledGets / record.takerGetsOriginal.value) * 100)
      : null;
    delete record._createIdx;
  }

  const stats = {
    total: list.length,
    filledImmediately: list.filter(r => r.status === 'filled-immediately').length,
    cancelled: list.filter(r => r.status === 'cancelled').length,
    consumedLater: list.filter(r => r.status === 'consumed-later').length,
    partiallyFilled: list.filter(r => r.status === 'partially-filled-then-resting').length,
    expired: list.filter(r => r.status === 'expired').length,
    unknownOpen: list.filter(r => r.status === 'unknown-open').length,
    // IOC/FOK orders that crossed less than their full size and had the
    // remainder killed (never rested) — genuinely distinct from both a
    // full immediate fill and an intentional cancellation.
    killedPartial: list.filter(r => r.status === 'killed-partial').length,
    killedUnfilled: list.filter(r => r.status === 'killed-unfilled').length,
  };

  return { byOfferId, list, stats };
}

/* ── Offer Fill Rate ──────────────────────────────────
   Rebuilt on the Offer Lifecycle Engine's real per-offer resolution instead
   of the old same-transaction "does this create tx's own metadata contain
   any DeletedNode Offer" proxy, which could only ever detect an immediate
   cross at creation and said nothing about what happened to a resting
   remainder afterward.
──────────────────────────────────────────────────── */
function analyseOfferFillRate(offerLifecycles, addr) {
  const list = offerLifecycles.list;
  const createdCount        = list.length;
  const immediateFillCount  = list.filter(r => r.status === 'filled-immediately').length;
  const restingCount        = list.filter(r => r.status === 'resting' || r.status === 'partially-filled-then-resting' || r.status === 'unknown-open').length;
  const laterConsumedCount  = list.filter(r => r.status === 'consumed-later').length;
  const cancelledCount      = list.filter(r => r.status === 'cancelled').length;
  const expiredCount        = list.filter(r => r.status === 'expired').length;
  const unknownOpenCount    = list.filter(r => r.status === 'unknown-open').length;
  // IOC/FOK orders killed with partial or zero fill — genuinely distinct
  // from an intentional OfferCancel; never counted toward "cancelled".
  const killedPartialCount  = list.filter(r => r.status === 'killed-partial').length;
  const killedUnfilledCount = list.filter(r => r.status === 'killed-unfilled').length;

  const restTimes = list.map(r => r.timeRestingSeconds).filter(t => t != null);
  const avgTimeRestingSeconds = restTimes.length ? restTimes.reduce((a, b) => a + b, 0) / restTimes.length : null;
  const sortedRest = [...restTimes].sort((a, b) => a - b);
  const medianTimeRestingSeconds = sortedRest.length ? sortedRest[Math.floor(sortedRest.length / 2)] : null;

  const fillPcts = list.map(r => r.realizedFillPct).filter(p => p != null);
  const realizedFillPctOverall = fillPcts.length ? fillPcts.reduce((a, b) => a + b, 0) / fillPcts.length : null;

  const byPair = new Map();
  for (const r of list) {
    const pairKey = [r.takerGetsOriginal.currency || '?', r.takerPaysOriginal.currency || '?'].sort().join('↔');
    const bucket = byPair.get(pairKey) || { created: 0, filled: 0, cancelled: 0, fillPctSum: 0, fillPctCount: 0 };
    bucket.created++;
    if (r.status === 'filled-immediately' || r.status === 'consumed-later') bucket.filled++;
    if (r.status === 'cancelled') bucket.cancelled++;
    if (r.realizedFillPct != null) { bucket.fillPctSum += r.realizedFillPct; bucket.fillPctCount++; }
    byPair.set(pairKey, bucket);
  }
  for (const bucket of byPair.values()) bucket.avgFillPct = bucket.fillPctCount ? bucket.fillPctSum / bucket.fillPctCount : null;

  const findings = [];
  if (createdCount >= 10) {
    const cancelRatio = cancelledCount / createdCount;
    if (realizedFillPctOverall != null && realizedFillPctOverall < 5 && cancelRatio > 0.5) {
      findings.push(mkFinding({
        module: 'Offer Fill Rate', category: 'liquidity', sev: 'warn', confidence: 0.6,
        headline: `Low realized fill rate: ${realizedFillPctOverall.toFixed(1)}% across ${createdCount} offers`,
        detail: `${cancelledCount} of ${createdCount} offers were cancelled, most with minimal execution before cancellation.`,
        observed: [
          `${cancelledCount} cancelled (${(cancelRatio * 100).toFixed(0)}%)`,
          `${laterConsumedCount} consumed by a counterparty after resting`,
          `${expiredCount} expired/removed unfunded`,
          `${unknownOpenCount} still open as of the last analyzed transaction`,
          (killedPartialCount + killedUnfilledCount) ? `${killedPartialCount + killedUnfilledCount} IOC/FOK order(s) killed with partial or zero fill (not counted as cancellations)` : null,
          `Average time resting before resolution: ${avgTimeRestingSeconds != null ? avgTimeRestingSeconds.toFixed(0) + 's' : 'unknown'}`,
        ].filter(Boolean),
        alternativeExplanations: ['Active order management — repricing as the market moves', 'Automated market-making that requeues orders frequently'],
        evidenceAgainstBenign: realizedFillPctOverall < 1 ? ['Realized fill percentage is near zero, not just below average'] : [],
        classification: 'A low fill rate is observed. On its own this does not establish intent — see the Spoofing and Market-Maker Automation scores for further context.',
      }));
    } else {
      findings.push(mkFinding({
        module: 'Offer Fill Rate', category: 'liquidity', sev: 'ok', confidence: 0.7,
        headline: `${realizedFillPctOverall != null ? realizedFillPctOverall.toFixed(1) + '%' : 'Normal'} realized fill rate across ${createdCount} offers`,
        detail: `${immediateFillCount} filled immediately, ${laterConsumedCount} consumed after resting, ${cancelledCount} cancelled, ${expiredCount} expired.`,
      }));
    }
  } else {
    findings.push(mkFinding({
      module: 'Offer Fill Rate', category: 'liquidity', sev: 'info',
      headline: `Only ${createdCount} offer(s) placed — insufficient sample for fill-rate analysis`,
      detail: 'Need at least 10 OfferCreate transactions for a meaningful fill-rate read.',
    }));
  }

  return {
    createdCount, immediateFillCount, restingCount, laterConsumedCount, cancelledCount,
    expiredCount, unknownOpenCount, killedPartialCount, killedUnfilledCount,
    avgTimeRestingSeconds, medianTimeRestingSeconds,
    realizedFillPctOverall, byPair, findings,
  };
}

/* ── Wash Trading ────────────────────────────────── */
/* Shared statistics computed once from offerLifecycles + txList, so the
   three scorers below interpret/weight the same numbers instead of each
   re-deriving (and potentially drifting on) its own copy. */
function buildOfferBehaviorProfile(offerLifecycles, txList, addr) {
  const list = offerLifecycles.list;

  const times = list.map(r => r.createDate).filter(t => t != null).sort((a, b) => a - b);
  const burstWindow = (windowSec) => {
    if (!times.length) return 0;
    let max = 1;
    for (let i = 0; i < times.length; i++) {
      let c = 1;
      for (let j = i + 1; j < times.length && times[j] - times[i] <= windowSec; j++) c++;
      max = Math.max(max, c);
    }
    return max;
  };
  const burstWindows = { thirtySec: burstWindow(30), oneHour: burstWindow(3600) };

  const sizes = list.map(r => r.takerGetsOriginal.value).filter(v => v != null && v > 0);
  let sizeCV = null;
  if (sizes.length >= WASH_MIN_TX) {
    const mu  = sizes.reduce((a, b) => a + b, 0) / sizes.length;
    const sig = Math.sqrt(sizes.reduce((a, v) => a + (v - mu) ** 2, 0) / sizes.length);
    sizeCV = mu > 0 ? sig / mu : null;
  }

  const roundMagn = [100, 1_000, 10_000, 100_000];
  const roundCount = sizes.filter(v => roundMagn.some(m => Math.abs(v % m) < 1e-6 && v / m >= 1)).length;
  const roundNumberPct = sizes.length ? roundCount / sizes.length : 0;

  const pairCounts = new Map();
  list.forEach(r => {
    const pair = [r.takerGetsOriginal.currency || '?', r.takerPaysOriginal.currency || '?'].sort().join('↔');
    pairCounts.set(pair, (pairCounts.get(pair) || 0) + 1);
  });
  const dominantPair = [...pairCounts.entries()].sort((a, b) => b[1] - a[1])[0] || null;
  const pairConcentration = dominantPair && list.length ? dominantPair[1] / list.length : 0;

  const cancelRatio = list.length ? list.filter(r => r.status === 'cancelled').length / list.length : 0;
  const restingTimes = list.map(r => r.timeRestingSeconds).filter(t => t != null);

  // ── Market-making alternative-explanation signals ──
  // These exist to let Market-Maker Automation (below) actually test the
  // claim it makes, instead of inferring "automated market-making" from
  // order-shape alone (cancel ratio / size uniformity / burst timing), which
  // a layering or spoofing scheme dressed up with uniform sizing can mimic
  // just as easily. Each one answers a question real market-making — but
  // not spoofing — should satisfy.

  // Broad counterparties: a real market-maker provides liquidity to many
  // distinct participants; repeatedly trading against the same one or two
  // accounts looks more like a private arrangement than open quoting.
  const counterpartySet = new Set();
  list.forEach(r => {
    (r.counterpartiesAtCreation || []).forEach(c => c.account && counterpartySet.add(c.account));
    (r.consumedEvents || []).forEach(e => e.counterpartyAccount && counterpartySet.add(e.counterpartyAccount));
  });
  const distinctCounterpartyCount = counterpartySet.size;

  // External vs. self fills: a fill is "self" only when the transaction that
  // consumed it was sent by this same account (it crossed its OWN other
  // resting offer) — AMM-routed creation crosses have no Offer counterparty
  // node at all (an AMM position isn't an Offer ledger object), so those are
  // counted as external liquidity rather than left ambiguous.
  let externalFillEvents = 0, selfFillEvents = 0;
  list.forEach(r => {
    if (r.crossedAtCreation?.gets > 0) {
      if ((r.counterpartiesAtCreation || []).length) externalFillEvents++;
      else if ((r.selfCounterpartiesAtCreation || []).length) selfFillEvents++;
      else if (r.route === 'AMM' || r.route === 'HYBRID') externalFillEvents++;
      // else: unresolvable from available metadata — not counted either way
    }
    (r.consumedEvents || []).forEach(e => (e.counterpartyAccount ? externalFillEvents++ : selfFillEvents++));
  });
  const externalFillTotal = externalFillEvents + selfFillEvents;
  const externalFillPct = externalFillTotal ? (externalFillEvents / externalFillTotal) * 100 : null;

  // Two-sided quoting + inventory management, both scoped to the dominant
  // pair (the pair this account actually trades, not a hypothetical one).
  let twoSidedRatio = null;
  let inventory = null;
  if (dominantPair) {
    const [sideA] = dominantPair[0].split('↔');
    const dominantOffers = list.filter(r => [r.takerGetsOriginal.currency || '?', r.takerPaysOriginal.currency || '?'].sort().join('↔') === dominantPair[0]);
    const sideACount = dominantOffers.filter(r => r.takerGetsOriginal.currency === sideA).length;
    const sideBCount = dominantOffers.length - sideACount;
    twoSidedRatio = dominantOffers.length ? Math.min(sideACount, sideBCount) / dominantOffers.length : null;

    // Cumulative signed position in `sideA`, in creation order: selling
    // sideA decreases it, buying sideA (selling the other side) increases
    // it. A managed inventory oscillates around a working level; an
    // unmanaged one drifts ever further from zero with no reversal.
    const ordered = [...dominantOffers].sort((a, b) => (a.createDate ?? 0) - (b.createDate ?? 0));
    let running = 0, maxAbs = 0, reversions = 0, lastSign = 0;
    const sizesInA = [];
    for (const r of ordered) {
      const sellsA = r.takerGetsOriginal.currency === sideA;
      const amountA = sellsA ? r.takerGetsOriginal.value : r.takerPaysOriginal.value;
      if (amountA == null) continue;
      sizesInA.push(amountA);
      running += sellsA ? -amountA : amountA;
      maxAbs = Math.max(maxAbs, Math.abs(running));
      const sign = Math.sign(running);
      if (sign !== 0 && lastSign !== 0 && sign !== lastSign) reversions++;
      if (sign !== 0) lastSign = sign;
    }
    const avgSizeA = sizesInA.length ? sizesInA.reduce((a, b) => a + b, 0) / sizesInA.length : 0;
    inventory = { maxAbsPosition: maxAbs, finalPosition: running, reversions, driftRatio: avgSizeA > 0 ? maxAbs / avgSizeA : null };
  }

  return {
    burstWindows, sizeCV, roundNumberPct, pairConcentration, dominantPair, cancelRatio, restingTimes, createdCount: list.length,
    distinctCounterpartyCount, externalFillPct, twoSidedRatio, inventory,
  };
}

/* ── Wash Execution Score ──
   Requires actual executions. Direct round-trip payments and self-trades
   are the two patterns reliably detectable from a single account's own
   transaction history. True multi-hop circular flow (A→B→C→A across
   separate accounts) would require those OTHER accounts' own transaction
   histories, which aren't available here — so this does not claim to
   detect that; it's flagged as a real gap rather than faked with a partial
   heuristic dressed up as a graph search. What it can honestly add beyond
   the old file's direct-round-trip check: cross-referencing payment
   round-trip partners against DEX trading counterparties, and reciprocal-
   quantity matching using the Offer Lifecycle Engine's consumed-event data. */
/** Per-counterparty round-trip quality: pairs each outbound payment to `a`
 *  with the next unmatched inbound payment from `a` (FIFO), then scores the
 *  relationship on three independent signals — how often it happened, how
 *  closely the amounts matched, and how quickly the funds came back. A
 *  single reciprocal payment 80 days apart and 47 near-instant round-trips
 *  at 99% amount similarity both satisfy "recipient also sent something
 *  back," but they are not remotely the same strength of evidence. */
function _roundTripQuality(addr, counterparty, payments) {
  // XRP-leg only, matching this function's existing scope (token round-trip
  // pairing isn't attempted here). Amount comes from the shared
  // _extractPaymentAmount helper (meta.delivered_amount preferred over
  // tx.Amount) rather than re-parsing tx.Amount directly, same fix applied
  // to Fund Flow/Inbound Flow/the Relationship Drawer.
  const outbound = payments.filter(({ tx }) => tx.Account === addr && tx.Destination === counterparty)
    .map(({ tx, meta }) => ({ amtXrp: _extractPaymentAmount(tx, meta).amtXrp, ts: getCloseTime(tx), hash: tx.hash })).filter(e => e.amtXrp > 0 && e.ts != null).sort((a, b) => a.ts - b.ts);
  const inbound = payments.filter(({ tx }) => tx.Destination === addr && tx.Account === counterparty)
    .map(({ tx, meta }) => ({ amtXrp: _extractPaymentAmount(tx, meta).amtXrp, ts: getCloseTime(tx), hash: tx.hash })).filter(e => e.amtXrp > 0 && e.ts != null).sort((a, b) => a.ts - b.ts);

  const pairs = [];
  let ii = 0;
  for (const o of outbound) {
    while (ii < inbound.length && inbound[ii].ts < o.ts) ii++; // skip inbound events that predate this outbound leg
    if (ii >= inbound.length) break;
    const inb = inbound[ii];
    const similarity = 1 - Math.abs(o.amtXrp - inb.amtXrp) / Math.max(o.amtXrp, inb.amtXrp);
    pairs.push({ sentXrp: o.amtXrp, returnedXrp: inb.amtXrp, elapsedSec: Math.max(0, inb.ts - o.ts), similarity: Math.max(0, similarity), hashes: [o.hash, inb.hash].filter(Boolean) });
    ii++; // each inbound leg consumed by at most one pair
  }
  if (!pairs.length) return null;

  const median = arr => { const s = [...arr].sort((a, b) => a - b); return s[Math.floor(s.length / 2)]; };
  const medianElapsedSec = median(pairs.map(p => p.elapsedSec));
  const medianSimilarity = median(pairs.map(p => p.similarity));
  const occurrenceFactor = Math.min(1, pairs.length / 5);
  const speedFactor = 1 / (1 + medianElapsedSec / 86400); // ~1 at seconds/minutes, 0.5 at 1 day, ~0.01 at 83 days
  const qualityScore = (occurrenceFactor + medianSimilarity + speedFactor) / 3;

  return { counterparty, occurrences: pairs.length, medianElapsedSec, medianSimilarity, qualityScore, hashes: pairs.flatMap(p => p.hashes) };
}

function analyseWashExecution(profile, offerLifecycles, txList, addr, isProjectAccount = false, executionLedger = null) {
  const findings = [];
  let score = 0;
  let topRelationships = [];

  const payments = txList.filter(({ tx }) => tx.TransactionType === 'Payment');
  // Self-payments (Account === Destination === addr) are excluded here —
  // they're a real but structurally different signal, handled by their own
  // dedicated finding below. Without this exclusion, a self-payment makes
  // `addr` appear in both sets and therefore in `roundTrip` itself, i.e.
  // this account gets listed as its own "round-trip counterparty" — a bug
  // that was invisible while only a count was ever shown, but became a
  // glaring wrong entry the moment topRelationships started naming real
  // addresses in the Relationships Worth Reviewing list.
  const outboundRecipients = new Set(payments.filter(({ tx }) => tx.Account === addr && tx.Destination && tx.Destination !== addr).map(({ tx }) => tx.Destination));
  const inboundSenders     = new Set(payments.filter(({ tx }) => tx.Destination === addr && tx.Account && tx.Account !== addr).map(({ tx }) => tx.Account));
  const roundTrip = [...outboundRecipients].filter(a => inboundSenders.has(a));

  if (roundTrip.length > 0 && payments.length >= WASH_MIN_TX) {
    const rtRatio = roundTrip.length / outboundRecipients.size;

    // Reciprocal-quantity check: do any round-trip partners also appear
    // as DEX counterparties with near-equal-and-opposite traded amounts?
    // Computed unconditionally (not gated on rtRatio) — "Relationships
    // Worth Reviewing" should surface every round-trip partner scored
    // above, not only the subset that also clears the bar for a full
    // Wash Execution finding to fire.
    const dexPartners = new Set();
    for (const r of offerLifecycles.list) {
      for (const c of r.counterpartiesAtCreation) dexPartners.add(c.account);
      for (const e of r.consumedEvents) if (e.counterpartyAccount) dexPartners.add(e.counterpartyAccount);
    }
    // Score every round-trip partner on occurrence/similarity/speed —
    // "Relationships Worth Reviewing" (topRelationships) always gets the
    // FULL ranked list; only whether a FINDING fires (and which relationship
    // headlines it) is gated on rtRatio below.
    const qualities = roundTrip.map(a => _roundTripQuality(addr, a, payments)).filter(Boolean).sort((a, b) => b.qualityScore - a.qualityScore);
    topRelationships = qualities.map(q => ({ ...q, alsoTradedOnDex: dexPartners.has(q.counterparty) }));

    if (rtRatio > WASH_SELF_RATIO) {
      const alsoTradedWith = roundTrip.filter(a => dexPartners.has(a));
      const best = qualities[0] || null;
      const strongPartners = qualities.filter(q => q.qualityScore >= 0.6);

      const sev = best && best.qualityScore >= 0.6 ? 'warn' : 'info';
      const baseConfidence = alsoTradedWith.length ? 0.55 : 0.4;
      const confidence = best ? Math.max(0.15, baseConfidence * (0.4 + 0.6 * best.qualityScore)) : baseConfidence * 0.5;

      findings.push(mkFinding({
        module: 'Wash Execution', category: 'market-integrity', sev, confidence,
        headline: best
          ? `${roundTrip.length} round-trip payment counterpart(s); strongest: ${best.occurrences} cycle(s), ${(best.medianSimilarity * 100).toFixed(0)}% amount match, ${fmt(best.medianElapsedSec / 60, 1)} min median turnaround`
          : `${roundTrip.length} round-trip payment counterpart(s) detected`,
        detail: `${(rtRatio * 100).toFixed(1)}% of payment recipients also sent back to this account.`,
        observed: [
          `${roundTrip.length} of ${outboundRecipients.size} outbound recipients also sent payments back`,
          strongPartners.length ? `${strongPartners.length} partner(s) show a strong pattern: frequent, closely-matched, fast-turnaround round-trips` : 'No partner shows a strong frequent/matched/fast round-trip pattern — evidence is weak even where a round-trip exists',
          alsoTradedWith.length ? `${alsoTradedWith.length} of those also traded directly on the DEX with this account` : 'No overlap found with DEX trading counterparties',
        ],
        alternativeExplanations: ['Ordinary reciprocal business/personal payments', 'Exchange deposit/withdrawal cycling through the same account'],
        evidenceAgainstBenign: [
          ...(alsoTradedWith.length ? ['Payment round-trip AND direct DEX trading with the same counterparty(ies)'] : []),
          ...(strongPartners.length ? [`${strongPartners.length} counterpart(y/ies) show frequent, near-identical-amount, fast round-trips — closer to a scripted cycle than an isolated reciprocal payment`] : []),
        ],
        classification: strongPartners.length
          ? 'Frequent, closely-matched, fast round-trips are meaningfully stronger evidence than a single reciprocal payment — still cannot confirm circular multi-account flow (A→B→C→A) from this account\'s history alone, which would require the counterparties\' own transaction histories.'
          : 'A round-trip relationship exists but is infrequent, loosely amount-matched, and/or slow to return — this is weak evidence on its own and commonly reflects ordinary reciprocal payments rather than wash execution.',
        ownerImpact: 'Minimal — funds returning to the same account net out; transaction fees are the only real cost regardless of intent.',
        externalImpact: alsoTradedWith.length || strongPartners.length
          ? 'If this reflects wash trading rather than ordinary reciprocal payments, other market participants could be misled about real trading activity between these addresses — not established here.'
          : 'Low, given how weak this specific evidence is — an infrequent, loosely-matched round-trip is unlikely to meaningfully mislead other market participants either way.',
        hashes: best?.hashes || [],
      }));
      score += (alsoTradedWith.length ? 25 : 15) * (best ? Math.max(0.3, best.qualityScore) : 0.5);
    }
  }

  const selfTrades = payments.filter(({ tx }) => tx.Account === addr && tx.Destination === addr);
  if (selfTrades.length > 0) {
    // "Wash trading" is a market-manipulation concept — it means faking
    // trading activity to mislead other market participants about supply,
    // demand, or liquidity. A plain XRP Payment to yourself never touches
    // any market at all: it creates no Offer, enters no order book, and
    // isn't visible to anyone as "trading volume" for any asset. Calling
    // that "Wash Execution" at high confidence was a category error, not
    // just a missing account-type caveat — there is no market here for a
    // personal account with no DEX history to be manipulating. It only
    // becomes market-relevant when it (a) involves an issued token/IOU,
    // whose recorded transfer volume other people might actually look at,
    // or (b) coexists with real DEX activity this account could plausibly
    // be trying to support the appearance of.
    const tokenSelfTrades = selfTrades.filter(({ tx }) => typeof tx.Amount === 'object' && tx.Amount);
    const xrpSelfTrades = selfTrades.filter(({ tx }) => typeof tx.Amount === 'string');
    // An account that trades exclusively through an AMM pool (zero
    // OfferCreate history) still has real market/DEX activity —
    // offerLifecycles alone can't see that, since AMM swaps never create an
    // Offer ledger object. executionLedger (route-classified from ledger
    // metadata) catches this case too.
    const ammTradeCount = executionLedger?.stats?.total ? (executionLedger.stats.amm + executionLedger.stats.hybrid) : 0;
    const hasDexActivity = (offerLifecycles?.list?.length || 0) > 0 || ammTradeCount > 0;
    const xrpAmounts = xrpSelfTrades.map(({ tx }) => Number(tx.Amount) / 1e6).filter(v => v > 0);
    const medianXrpAmount = xrpAmounts.length ? xrpAmounts.slice().sort((a, b) => a - b)[Math.floor(xrpAmounts.length / 2)] : 0;
    // A trivial/negligible amount (sequence-bumping, "ping" activity,
    // testing a memo/path) is a real, common, and functionally different
    // pattern from repeatedly moving meaningful value to yourself.
    const isNegligibleAmount = xrpAmounts.length > 0 && medianXrpAmount < 1;
    const noMarketContext = tokenSelfTrades.length === 0 && !hasDexActivity;

    let sev, confidence, primaryExplanation, classification, ownerImpact, externalImpact, applicability = null;
    if (noMarketContext) {
      // No token involved, no DEX history anywhere in this account — there
      // is no market for this to be "washing." This is the common case for
      // an ordinary personal wallet and should read as informational, not
      // a market-integrity risk.
      sev = 'info';
      confidence = isNegligibleAmount ? 0.15 : 0.25;
      primaryExplanation = isNegligibleAmount
        ? 'Negligible-amount self-payments, consistent with sequence-bumping, keeping an account "active," or testing a memo/path — not moving meaningful value'
        : 'A no-op or self-directed transaction (e.g. marking an account active, testing a memo/path, or a wallet/exchange UI quirk) — this account has no DEX trading history and these payments involve no issued token, so there is no market for this to affect';
      classification = 'This account shows no DEX/market activity and these self-payments involve no issued token — a wash-trading interpretation does not apply, since there is no market here to manipulate. This is a real, recorded transaction pattern worth noting, not a market-integrity risk.';
      applicability = { applicable: false, reason: 'Wash trading requires an actual market to manipulate — this account has no issued-token transfers and no DEX trading history, so a same-currency self-payment touches no market at all.' };
      ownerImpact = 'None beyond the transaction fee — moving XRP to your own address has no net effect on your own holdings.';
      externalImpact = 'None — with no market involved, no other participant could be misled by this activity.';
    } else if (isProjectAccount) {
      // A detected token issuer routinely does internal accounting or
      // consolidation payments to itself — for that account type, MORE
      // repeats is the expected pattern for routine automation, not
      // stronger evidence of wash trading.
      sev = 'warn'; confidence = 0.4;
      primaryExplanation = 'This account shows signs of being a token issuer (see Account Type above) — internal treasury or accounting consolidation payments to itself are routine for that account type';
      classification = 'Confirmed self-payment — a real, recorded transaction, but this account is independently identified as a token issuer, where repeated self-payments commonly reflect routine internal accounting rather than wash trading. Treated as weaker evidence accordingly.';
      ownerImpact = 'Minimal — transaction fees only; no net transfer of the account\'s own funds.';
      externalImpact = 'If this were confirmed wash trading rather than routine treasury activity, other holders/traders of this issuer\'s token could be misled about real trading volume or liquidity — not established here.';
    } else {
      // Token-denominated self-payments and/or coexisting real DEX
      // activity is the one combination where a market-relevance concern
      // is actually plausible — kept at meaningful severity, but still
      // short of the old blanket 85%-confidence default.
      sev = 'warn'; confidence = 0.55;
      primaryExplanation = 'A no-op transaction used to mark an account active, or to test a memo/path';
      classification = `Confirmed self-payment${tokenSelfTrades.length ? ', including issued-token transfers whose recorded volume could be visible to others' : ', alongside this account\'s own real DEX trading history'} — creates recorded activity with zero net economic transfer, but ledger data alone cannot establish intent.`;
      ownerImpact = 'Minimal — transaction fees only; no net transfer of the account\'s own funds.';
      externalImpact = 'If this were confirmed wash trading, other market participants viewing this token\'s recorded volume or this account\'s DEX activity could be misled about real trading volume or liquidity — not established here.';
    }

    findings.push(mkFinding({
      module: 'Wash Execution', category: 'market-integrity', sev, confidence,
      headline: `${selfTrades.length} self-payment(s): sender = receiver`,
      detail: 'Payments where origin and destination are the same address.',
      observed: [
        `${selfTrades.length} Payment transaction(s) with Account === Destination (${xrpSelfTrades.length} XRP, ${tokenSelfTrades.length} issued-token)`,
        hasDexActivity
          ? `This account has ${offerLifecycles.list.length} DEX offer(s)${ammTradeCount ? ` and ${ammTradeCount} AMM-routed trade(s)` : ''} in its history`
          : 'This account has no DEX/Offer or AMM trading history at all',
        xrpAmounts.length ? `Median XRP self-payment amount: ${fmt(medianXrpAmount, 6)} XRP` : null,
      ].filter(Boolean),
      alternativeExplanations: isProjectAccount
        ? [primaryExplanation, 'A no-op transaction used to mark an account active, or to test a memo/path']
        : [primaryExplanation],
      evidenceAgainstBenign: (selfTrades.length > 2 && !isProjectAccount && !noMarketContext) ? ['Repeated, not a single isolated instance'] : [],
      classification, applicability, ownerImpact, externalImpact,
    }));
    score += noMarketContext ? 3 : isProjectAccount ? 10 : 20;
  }

  if (!findings.length) {
    findings.push(mkFinding({
      module: 'Wash Execution', category: 'market-integrity', sev: 'ok',
      headline: 'No wash-execution signals', detail: `${offerLifecycles.list.length} offers, ${selfTrades.length} self-payments — patterns look normal.`,
    }));
  }

  // Value circulation (XRP-denominated only — see valueCirculation.note):
  // how much of this account's own tracked payment volume moved with its
  // round-trip partners specifically ("internal"), versus everyone else
  // ("external"), and within that internal slice, how much of the gross
  // back-and-forth actually netted out to a real position change. Answers
  // "a lot of volume happened, but did anything really change?" without
  // any new RPC calls — every number here comes from `payments`, already
  // fetched for this account. XRP-only because payments in different
  // issued currencies aren't summable into one meaningful total; token
  // amounts are simply excluded rather than blended into a false XRP
  // figure (the same "don't fabricate a blended value" rule AMM and Fund
  // Flow already follow).
  let valueCirculation = null;
  const xrpOutAmt = ({ tx }) => tx.Account === addr && typeof tx.Amount === 'string' ? Number(tx.Amount) / 1e6 : 0;
  const xrpInAmt  = ({ tx }) => tx.Destination === addr && typeof tx.Amount === 'string' ? Number(tx.Amount) / 1e6 : 0;
  const totalOutXrp = payments.reduce((s, p) => s + xrpOutAmt(p), 0);
  const totalInXrp  = payments.reduce((s, p) => s + xrpInAmt(p), 0);
  const totalXrpVolume = totalOutXrp + totalInXrp;
  if (roundTrip.length > 0 && totalXrpVolume > 0) {
    const rtSet = new Set(roundTrip);
    const internalOutXrp = payments.filter(p => rtSet.has(p.tx.Destination)).reduce((s, p) => s + xrpOutAmt(p), 0);
    const internalInXrp  = payments.filter(p => rtSet.has(p.tx.Account)).reduce((s, p) => s + xrpInAmt(p), 0);
    const grossXrp = internalOutXrp + internalInXrp;
    const netXrp = Math.abs(internalOutXrp - internalInXrp);
    valueCirculation = {
      grossXrp, netXrp,
      internalPct: (grossXrp / totalXrpVolume) * 100,
      externalPct: 100 - (grossXrp / totalXrpVolume) * 100,
      note: 'XRP-denominated payments only — issued-token amounts are excluded rather than blended into a false combined total.',
    };
  }

  return { score: Math.min(100, score), findings, stats: { roundTrip: roundTrip.length, selfTrades: selfTrades.length }, valueCirculation, topRelationships };
}

/* ── Flow Motifs ──────────────────────────────────────────────────────────
   Flow Intelligence spec §27-28: surface REPEATED, RECOGNIZABLE flow
   patterns from this account's own transaction history as a neutral,
   descriptive index — never automatically framed as malicious (the spec's
   own explicit instruction). Deliberately carries NO findings/signals of
   its own and contributes NOTHING to risk scoring: the same round-trip
   pattern is already scored by Wash Execution (market-integrity), and
   double-counting the same evidence under a second heading would inflate
   the category risk score for no new information. This is an index/cross-
   reference layer, pointing to the modules that actually interpret each
   pattern.
   Three motif types are genuinely derivable from a single account's own
   history: A<->B round-trip payments (reuses _roundTripQuality wholesale
   — the exact same scoring Wash Execution uses, just presented neutrally
   here), A->AMM->A (deposited into a pool, later withdrew), and
   A->Exchange->A (a known exchange address appears as both a payment
   source and destination). True multi-hop circular flow across OTHER
   accounts (A->B->C->A) is explicitly NOT attempted — this app has no
   visibility into B's or C's own transaction history from a single-
   account inspection, a real architectural ceiling already documented on
   analyseWashExecution above. */
function detectFlowMotifs(txList, addr) {
  const motifs = [];
  const payments = txList.filter(({ tx }) => tx.TransactionType === 'Payment');

  // Self-payments excluded — see the identical exclusion (and its rationale)
  // in analyseWashExecution's own outboundRecipients/inboundSenders; without
  // it, a self-payment makes this account its own "round-trip partner" and
  // would render a nonsensical "X → X → X" motif.
  const outboundRecipients = new Set(payments.filter(({ tx }) => tx.Account === addr && tx.Destination && tx.Destination !== addr).map(({ tx }) => tx.Destination));
  const inboundSenders     = new Set(payments.filter(({ tx }) => tx.Destination === addr && tx.Account && tx.Account !== addr).map(({ tx }) => tx.Account));
  const roundTripPartners  = [...outboundRecipients].filter(a => inboundSenders.has(a));

  // Motif: A <-> B round-trip payments. Known-exchange partners are routed
  // through the more specific EXCHANGE_ROUND_TRIP motif below instead, so
  // the same relationship never appears twice under two different labels.
  for (const partner of roundTripPartners) {
    if (getEntity(partner)?.type === 'exchange') continue;
    const q = _roundTripQuality(addr, partner, payments);
    if (!q) continue;
    motifs.push({
      type: 'ROUND_TRIP', icon: '🔁',
      label: `${shortAddr(addr)} → ${shortAddr(partner)} → ${shortAddr(addr)}`,
      counterparty: partner,
      detail: `${q.occurrences} cycle(s) · ${(q.medianSimilarity * 100).toFixed(0)}% amount match · ${fmt(q.medianElapsedSec / 60, 1)} min median turnaround`,
      occurrences: q.occurrences,
    });
  }

  // Motif: A -> AMM pool -> A (deposited, later withdrew from the SAME pool).
  const ammDeposits  = txList.filter(({ tx }) => tx.TransactionType === 'AMMDeposit');
  const ammWithdraws = txList.filter(({ tx }) => tx.TransactionType === 'AMMWithdraw');
  if (ammDeposits.length && ammWithdraws.length) {
    const byCurrency = new Map(); // lp currency -> { deposits: [], withdrawals: [] }
    for (const { tx, meta } of ammDeposits) {
      const delta = extractBalanceDeltas(tx, meta, addr);
      for (const lp of delta.lpDeltas) {
        if (!byCurrency.has(lp.currency)) byCurrency.set(lp.currency, { deposits: [], withdrawals: [] });
        byCurrency.get(lp.currency).deposits.push({ date: tx.date, xrpDelta: delta.xrpDelta });
      }
    }
    for (const { tx, meta } of ammWithdraws) {
      const delta = extractBalanceDeltas(tx, meta, addr);
      for (const lp of delta.lpDeltas) {
        if (!byCurrency.has(lp.currency)) byCurrency.set(lp.currency, { deposits: [], withdrawals: [] });
        byCurrency.get(lp.currency).withdrawals.push({ date: tx.date, xrpDelta: delta.xrpDelta });
      }
    }
    for (const [currency, ev] of byCurrency.entries()) {
      if (!ev.deposits.length || !ev.withdrawals.length) continue;
      const totalDeposited = ev.deposits.reduce((s, d) => s + Math.max(0, -d.xrpDelta), 0);
      const totalWithdrawn = ev.withdrawals.reduce((s, w) => s + Math.max(0, w.xrpDelta), 0);
      // Net XRP change — same gross-vs-net framing as Value Circulation:
      // how much of the deposit+withdrawal round-trip represents a real,
      // lasting change in this account's XRP position vs. a wash of money
      // going in and coming back out of the SAME pool. Scoped to the XRP
      // leg only (the token-side leg can't be reliably isolated from the
      // LP token's own synthetic currency without a more fragile lookup),
      // matching this app's own "don't fabricate a number the data can't
      // cleanly support" rule.
      const grossXrp = totalDeposited + totalWithdrawn;
      const netXrpPct = grossXrp > 0 ? (Math.abs(totalWithdrawn - totalDeposited) / grossXrp) * 100 : null;
      motifs.push({
        type: 'AMM_ROUND_TRIP', icon: '💧',
        label: `${shortAddr(addr)} → ${hexToAscii(currency)} Pool → ${shortAddr(addr)}`,
        detail: `${ev.deposits.length} deposit(s) totaling ${fmt(totalDeposited, 2)} XRP · ${ev.withdrawals.length} withdrawal(s) totaling ${fmt(totalWithdrawn, 2)} XRP${netXrpPct != null ? ` · net XRP change ${netXrpPct.toFixed(1)}%` : ''}`,
        occurrences: ev.deposits.length + ev.withdrawals.length,
        grossXrp, totalDeposited, totalWithdrawn, netXrpPct,
      });
    }
  }

  // Motif: A -> known Exchange -> A (funds sent to AND received from the
  // same known exchange address).
  const exchangeSrcs  = new Set(payments.filter(({ tx }) => tx.Destination === addr && tx.Account && getEntity(tx.Account)?.type === 'exchange').map(({ tx }) => tx.Account));
  const exchangeDests = new Set(payments.filter(({ tx }) => tx.Account === addr && tx.Destination && getEntity(tx.Destination)?.type === 'exchange').map(({ tx }) => tx.Destination));
  for (const exch of exchangeSrcs) {
    if (!exchangeDests.has(exch)) continue;
    const q = _roundTripQuality(addr, exch, payments);
    motifs.push({
      type: 'EXCHANGE_ROUND_TRIP', icon: '🏦',
      label: `${shortAddr(addr)} → ${getEntity(exch)?.name || shortAddr(exch)} → ${shortAddr(addr)}`,
      counterparty: exch,
      detail: q ? `${q.occurrences} cycle(s) · ${(q.medianSimilarity * 100).toFixed(0)}% amount match` : 'Funds sent to and received from the same known exchange address',
      occurrences: q?.occurrences ?? 1,
    });
  }

  motifs.sort((a, b) => b.occurrences - a.occurrences);
  return { applicable: motifs.length > 0, motifs };
}

/* ── Spoofing Score ──
   Scoped to what's honestly buildable without historical order-book state
   (public XRPL nodes generally only serve CURRENT book depth — historical
   book_offers is an archive-node capability this app doesn't have access
   to). Covers: the existing live-snapshot wall check, replacement-pattern
   detection from the lifecycle engine's cancel-and-recreate chains (fully
   buildable from already-fetched data), and the old own-history-percentile
   large-order-cancel check, explicitly relabeled as a proxy rather than
   presented as book-depth-relative. Deliberately does NOT add a price-
   distance-from-historical-mid or market-moved-toward-order check. */
/** Evidence family E (Layering-Like Behavior): multiple of this account's
 *  OWN offers resting SIMULTANEOUSLY in the same pair and direction, at
 *  meaningfully different price levels. Built entirely from this
 *  account's own already-resolved offer lifecycle records — a real,
 *  historically-verifiable pattern requiring no live book state, unlike
 *  proximity-to-market/price-approach-cancellation signals (evidence
 *  families B/C/D) which need book state at a past moment this app has
 *  no way to reconstruct on public XRPL nodes and honestly cannot claim. */
function _detectLayeringPattern(list) {
  const bySide = new Map();
  for (const r of list) {
    if (!r.takerGetsOriginal.value || !r.takerPaysOriginal.value) continue;
    const price = r.takerPaysOriginal.value / r.takerGetsOriginal.value;
    if (!Number.isFinite(price) || price <= 0) continue;
    const key = `${r.takerGetsOriginal.currency}.${r.takerGetsOriginal.issuer}→${r.takerPaysOriginal.currency}.${r.takerPaysOriginal.issuer}`;
    const end = r.cancelDate ?? r.consumedEvents[r.consumedEvents.length - 1]?.date ?? (r.createDate + (r.timeRestingSeconds || 0));
    if (!bySide.has(key)) bySide.set(key, []);
    bySide.get(key).push({ start: r.createDate, end, price, offerId: r.offerId });
  }

  let maxConcurrentLevels = 0;
  let instancesWithLayering = 0;
  const groupsInvolved = new Set();
  for (const [key, offers] of bySide) {
    if (offers.length < 3) continue; // need at least 3 offers in this pair/direction to even ask the question
    for (const o of offers) {
      const overlapping = offers.filter(other =>
        other !== o && other.start <= o.end && other.end >= o.start && Math.abs(other.price - o.price) / o.price > 0.005);
      const levels = 1 + overlapping.length; // this offer's own level plus distinct concurrent ones
      if (levels >= 3) {
        instancesWithLayering++;
        groupsInvolved.add(key);
        if (levels > maxConcurrentLevels) maxConcurrentLevels = levels;
      }
    }
  }

  return { detected: instancesWithLayering >= 3, instancesWithLayering, maxConcurrentLevels, pairCount: groupsInvolved.size };
}

/** Evidence family F (Opposite-Side Execution): while one of this
 *  account's own offers was resting and displayed (not instantly filled),
 *  did the SAME account also genuinely execute in the OPPOSITE direction
 *  of the same pair? Distinct from Wash Execution's general round-trip
 *  check — this is specifically time-windowed to "while the wall was up,"
 *  which is the spoofing-relevant question, not just "did a round-trip
 *  happen eventually." */
function _detectOppositeSideExecution(list) {
  const eventsByKey = new Map();
  for (const r of list) {
    const key = `${r.takerGetsOriginal.currency}.${r.takerGetsOriginal.issuer}→${r.takerPaysOriginal.currency}.${r.takerPaysOriginal.issuer}`;
    const times = [];
    if (r.crossedAtCreation.gets > 0) times.push(r.createDate);
    for (const e of r.consumedEvents) if (e.date != null) times.push(e.date);
    if (times.length) {
      if (!eventsByKey.has(key)) eventsByKey.set(key, []);
      eventsByKey.get(key).push(...times);
    }
  }

  let flaggedCount = 0;
  let totalCandidates = 0;
  const MIN_DISPLAY_SECONDS = 30; // must have actually rested for a nontrivial time, not an instant cross
  for (const r of list) {
    if (r.timeRestingSeconds == null || r.timeRestingSeconds < MIN_DISPLAY_SECONDS) continue;
    totalCandidates++;
    const reverseKey = `${r.takerPaysOriginal.currency}.${r.takerPaysOriginal.issuer}→${r.takerGetsOriginal.currency}.${r.takerGetsOriginal.issuer}`;
    const reverseTimes = eventsByKey.get(reverseKey) || [];
    const windowEnd = r.cancelDate ?? (r.createDate + r.timeRestingSeconds);
    if (reverseTimes.some(t => t >= r.createDate && t <= windowEnd)) flaggedCount++;
  }

  return { flaggedCount, totalCandidates, detected: totalCandidates >= 5 && flaggedCount >= 3 };
}

/** Evidence family I (AMM Activity During Display): while one of this
 *  account's own CLOB offers was resting and displayed, did the same
 *  account ALSO execute a trade against an AMM pool? A displayed CLOB
 *  wall should be interpreted against the account's own total executable
 *  activity across BOTH venues, not the order book in isolation — this
 *  reuses the execution ledger's already-classified CLOB/AMM/HYBRID
 *  routes (built for Execution Routing) rather than re-deriving route
 *  classification here. */
function _detectAmmActivityDuringDisplay(list, executionLedger) {
  const executions = executionLedger?.executions || [];
  if (!executions.length) return { flaggedCount: 0, totalCandidates: 0, detected: false };

  const ammTimes = executions.filter(e => e.route === 'AMM' || e.route === 'HYBRID').map(e => e.date).filter(d => d != null);
  if (!ammTimes.length) return { flaggedCount: 0, totalCandidates: 0, detected: false };

  let flaggedCount = 0, totalCandidates = 0;
  const MIN_DISPLAY_SECONDS = 30;
  for (const r of list) {
    if (r.timeRestingSeconds == null || r.timeRestingSeconds < MIN_DISPLAY_SECONDS) continue;
    totalCandidates++;
    const windowEnd = r.cancelDate ?? (r.createDate + r.timeRestingSeconds);
    if (ammTimes.some(t => t >= r.createDate && t <= windowEnd)) flaggedCount++;
  }
  return { flaggedCount, totalCandidates, detected: totalCandidates >= 5 && flaggedCount >= 3 };
}

function analyseSpoofingScore(profile, offerLifecycles, txList, addr, liveBookAnalysis, executionLedger = null, auctionGroupCurrencies = null) {
  const findings = [];
  let score = 0;
  const list = offerLifecycles.list;

  // Evidence families E + F + I — see helper doc comments above.
  // Corroboration between independent families matters more than any one
  // alone (spec: "Do not let one family generate a high-confidence
  // spoofing conclusion"), so confidence and severity scale with how many
  // independently-fired families corroborate each other, not just whether
  // any single one crossed its own threshold.
  const layering = _detectLayeringPattern(list);
  const oppositeSide = _detectOppositeSideExecution(list);
  const ammDuringDisplay = _detectAmmActivityDuringDisplay(list, executionLedger);

  // Evidence family J (Auction-Group Relationship): when AMM-during-
  // display activity is flagged, note whether this account ALSO
  // currently holds or is authorized for the discounted-fee auction slot
  // in one of the SAME currencies — real, relevant context (a discounted
  // fee makes frequent CLOB/AMM cycling more economically viable to
  // repeat). Per spec, this is context to weigh, never independent
  // evidence of intent by itself — it does not add to the family count
  // or the score, only enriches the finding when one is already firing.
  let auctionGroupNote = null;
  if (ammDuringDisplay.detected && auctionGroupCurrencies && auctionGroupCurrencies.size) {
    const pairCurrencies = new Set();
    for (const r of list) { pairCurrencies.add(r.takerGetsOriginal.currency); pairCurrencies.add(r.takerPaysOriginal.currency); }
    if ([...auctionGroupCurrencies].some(c => pairCurrencies.has(c))) {
      auctionGroupNote = 'This account also currently holds or is authorized for this pool\'s discounted-fee auction slot — AMM trades during this window may have executed at a reduced fee, which can make frequent CLOB/AMM cycling more economically viable to repeat. This is relevant context, not independent evidence of intent.';
    }
  }

  const firedFamilies = [
    layering.detected && { key: 'layering', label: 'layering-like order pattern' },
    oppositeSide.detected && { key: 'opposite', label: 'opposite-side execution while displayed' },
    ammDuringDisplay.detected && { key: 'amm', label: 'AMM activity during CLOB display' },
  ].filter(Boolean);
  if (firedFamilies.length > 0) {
    const n = firedFamilies.length;
    const observed = [
      layering.detected ? `${layering.instancesWithLayering} instance(s) of ${layering.maxConcurrentLevels}+ of this account's own offers resting simultaneously at different price levels, across ${layering.pairCount} pair/direction(s)` : null,
      oppositeSide.detected ? `${oppositeSide.flaggedCount} of ${oppositeSide.totalCandidates} displayed offers (resting 30s or more) had a genuine opposite-direction execution by this same account while still displayed` : null,
      ammDuringDisplay.detected ? `${ammDuringDisplay.flaggedCount} of ${ammDuringDisplay.totalCandidates} displayed CLOB offers (resting 30s or more) coincided with an AMM-routed execution by this same account while still displayed` : null,
      auctionGroupNote,
    ].filter(Boolean);
    findings.push(mkFinding({
      module: 'Spoofing', category: 'market-integrity', sev: 'warn', confidence: n === 1 ? 0.35 : n === 2 ? 0.5 : 0.6,
      headline: n >= 2
        ? `${n} independent evidence families corroborate each other: ${firedFamilies.map(f => f.label).join(', ')}`
        : layering.detected
          ? `Layering-like pattern: up to ${layering.maxConcurrentLevels} of this account's own offers rested simultaneously at different prices`
          : oppositeSide.detected
            ? `Opposite-side execution: this account traded the opposite direction while its own order was still displayed, in ${oppositeSide.flaggedCount} case(s)`
            : `AMM activity during CLOB display: this account executed AMM-routed trades while its own CLOB order was still displayed, in ${ammDuringDisplay.flaggedCount} case(s)`,
      detail: 'Reconstructed entirely from this account\'s own resolved offer lifecycle and classified execution history — real order timing/prices and real route classification, not a live-book snapshot or an assumption about historical depth.',
      observed,
      alternativeExplanations: [
        'Genuine multi-level market-making — professional market makers routinely quote several price levels on both sides simultaneously',
        'Independent trading decisions that happened to fall in the opposite direction of a resting order, with no relationship between the two',
        'Portfolio rebalancing or hedging that legitimately trades both directions of the same pair over time',
        'Arbitrage between the CLOB and an AMM pool — routing volume through whichever venue is cheaper at the moment is the intended, efficient use of having both, not evidence of manipulation',
      ],
      evidenceAgainstBenign: n >= 2 ? [`${n} independent evidence families (${firedFamilies.map(f => f.label).join('; ')}) all fired for this account, which is more than any one alone would suggest`] : [],
      classification: 'Behavioral pattern only — this describes what the order book and execution history show, not intent. See Market-Maker Automation for whether this account\'s overall order behavior otherwise looks like legitimate automated market-making (tight sizing, high fill rate, two-sided quoting), and Execution Routing for whether AMM/CLOB usage looks like ordinary arbitrage.',
      ownerImpact: 'Low direct cost — mainly transaction fees from order placement/cancellation.',
      externalImpact: 'If confirmed as spoofing/layering, this primarily harms OTHER market participants by presenting a misleading picture of book depth or intent — not established here, and equally consistent with legitimate multi-level market-making or cross-venue arbitrage.',
    }));
    score += n === 1 ? 15 : n === 2 ? 25 : 35;
  }

  // Replacement-pattern: cancel-then-recreate at a similar price, chained
  // via replacesOfferSeq — a real quote-management signal buildable purely
  // from this account's own already-fetched offer history.
  const byOfferId = offerLifecycles.byOfferId;
  let replacementChains = 0, replacementSamePriceCount = 0;
  for (const r of list) {
    if (!r.replacesOfferSeq) continue;
    const prior = byOfferId.get(`${addr}:${r.replacesOfferSeq}`);
    if (!prior) continue;
    replacementChains++;
    const priorPrice = prior.takerPaysOriginal.value && prior.takerGetsOriginal.value ? prior.takerPaysOriginal.value / prior.takerGetsOriginal.value : null;
    const newPrice    = r.takerPaysOriginal.value && r.takerGetsOriginal.value ? r.takerPaysOriginal.value / r.takerGetsOriginal.value : null;
    if (priorPrice && newPrice && Math.abs(newPrice - priorPrice) / priorPrice < 0.02) replacementSamePriceCount++;
  }
  if (replacementChains >= 5 && replacementSamePriceCount / replacementChains > 0.6) {
    findings.push(mkFinding({
      module: 'Spoofing', category: 'market-integrity', sev: 'warn', confidence: 0.45,
      headline: `${replacementSamePriceCount} of ${replacementChains} order replacements kept nearly the same price`,
      detail: 'Cancel-and-immediately-recreate at a near-identical price, repeated — a quote-management pattern worth a closer look.',
      observed: [`${replacementChains} create-and-replace chains found`, `${replacementSamePriceCount} replaced within 2% of the prior price`],
      alternativeExplanations: ['Routine order refresh/repricing by an active trader or market maker', 'Bumping sequence to avoid an unrelated conflict'],
      classification: 'Replacement pattern observed. On its own this is common in both legitimate quote maintenance and layering — see Market-Maker Automation for the explanatory read.',
      ownerImpact: 'Low direct cost — mainly transaction fees from frequent cancel/replace cycles.',
      externalImpact: 'Spoofing/layering, if confirmed, primarily harms OTHER market participants by presenting a false picture of book depth or intent — not established here, and equally consistent with routine quote maintenance.',
    }));
    score += 15;
  }

  // Own-history-percentile large-order check — kept from the old file, but
  // explicitly relabeled: this is NOT relative to book depth or pair-wide
  // norms (that data isn't reliably available after the fact), only to
  // this same wallet's own order-size history.
  if (list.length >= 10) {
    const xrpSized = list.filter(r => r.takerGetsOriginal.currency === 'XRP' && r.takerGetsOriginal.value != null);
    if (xrpSized.length >= 10) {
      const sizes = xrpSized.map(r => r.takerGetsOriginal.value).sort((a, b) => b - a);
      const p95 = sizes[Math.floor(sizes.length * 0.05)] || 0;
      const largeOrders = xrpSized.filter(r => r.takerGetsOriginal.value >= p95);
      const largeCancelledOrExpired = largeOrders.filter(r => r.status === 'cancelled' || r.status === 'expired');
      const proxyRatio = largeOrders.length >= 5 ? largeCancelledOrExpired.length / largeOrders.length : 0;
      if (proxyRatio >= 0.95) {
        findings.push(mkFinding({
          module: 'Spoofing', category: 'market-integrity', sev: 'warn', confidence: 0.3,
          headline: `${(proxyRatio * 100).toFixed(0)}% of this wallet's largest orders were cancelled without meaningful fill (own-history proxy)`,
          detail: `${largeCancelledOrExpired.length} of ${largeOrders.length} top-5%-by-this-wallet's-own-size orders cancelled or expired.`,
          observed: [`Sizing is relative to this wallet's own order history, not current book depth`, `${largeCancelledOrExpired.length}/${largeOrders.length} cancelled or expired without fill`],
          alternativeExplanations: ['A large order sized appropriately for a genuinely deep, liquid market', 'Cancelled for unrelated reasons (funding change, strategy shift)'],
          classification: 'Own-history size proxy only — true book-depth-relative sizing and price-distance-from-executable checks need historical order-book state this app cannot reliably obtain from public XRPL nodes. Treat as a weaker signal than a book-relative measurement would be.',
          ownerImpact: 'Low direct cost — mainly transaction fees from placing and cancelling orders.',
          externalImpact: 'Spoofing, if confirmed, primarily harms OTHER market participants by presenting a false picture of available liquidity — this own-history proxy cannot confirm intent or actual book impact.',
        }));
        score += 10; // lower weight than the old file's +30 — this is explicitly a weaker proxy now, not book-relative evidence
      }
    }
  }

  // Live snapshot wall check — reused as the present-tense signal, but ONLY
  // the 'critical' case (the inspected wallet's OWN order dominating the
  // book right now — analyseLiveOrderBook gates that on topOffer.Account
  // === addr). Its 'warn'-tier sibling is a completely unrelated third
  // party's current order in the same market — real false positive,
  // confirmed live: this used to feed straight into this wallet's own
  // Spoofing score purely because of who else happens to be trading the
  // same pair right now, something this account has no control over.
  // These come from analyseLiveOrderBook as plain {sev,label,detail}
  // objects with no module of their own; tag them as Spoofing here so
  // anything that groups findings by module (e.g. the Market Integrity
  // sub-panels) places them correctly instead of leaving them unattributed.
  if (liveBookAnalysis?.signals?.length) {
    for (const s of liveBookAnalysis.signals) {
      if (s.sev === 'critical') { findings.push({ ...s, module: 'Spoofing' }); score += 20; }
    }
  }

  if (!findings.length) {
    findings.push(mkFinding({ module: 'Spoofing', category: 'market-integrity', sev: 'ok', headline: 'No spoofing signals', detail: 'No large-order cancel pattern, replacement pattern, or live book wall detected.' }));
  }

  return { score: Math.min(100, score), findings };
}

/* ── Market-Maker Automation Score ──
   Explanatory, not accusatory by default: high-cancel/high-frequency/tight-
   size-variance behavior is exactly what legitimate automated market
   making looks like. This surfaces that context explicitly rather than
   letting burst/CV signals stack silently into an unexplained total. */
function analyseMarketMakerAutomation(profile, offerLifecycles, txList, addr, fillRateAnalysis) {
  const findings = [];
  let automationLikely = false;

  const highCancel = profile.cancelRatio > WASH_CANCEL_RATIO;
  const tightSizing = profile.sizeCV != null && profile.sizeCV < 0.2;
  const bursty = profile.burstWindows.thirtySec >= 8 || profile.burstWindows.oneHour > 100;
  const decentFillRate = fillRateAnalysis?.realizedFillPctOverall != null && fillRateAnalysis.realizedFillPctOverall >= 5;

  if (profile.createdCount >= WASH_MIN_TX && highCancel && (tightSizing || bursty)) {
    automationLikely = true;

    // Each of these tests one dimension a genuine market-maker should
    // satisfy that a spoofing/layering scheme dressed up with uniform
    // sizing generally won't. Tri-state (true/false/null) so "we couldn't
    // tell" is never silently conflated with "it failed the test."
    // Counterparty identities only come from the same fill events
    // externalFillPct is built from — with zero identifiable fills, a
    // distinctCounterpartyCount of 0 means "unknown," not "fails the test."
    const broadCounterparties = profile.externalFillPct != null ? profile.distinctCounterpartyCount >= 5 : null;
    const twoSidedQuoting = profile.twoSidedRatio != null ? profile.twoSidedRatio >= 0.25 : null;
    const mostlyExternalFills = profile.externalFillPct != null ? profile.externalFillPct >= 70 : null;
    const managedInventory = profile.inventory != null
      ? (profile.inventory.driftRatio == null || profile.inventory.driftRatio < 10 || profile.inventory.reversions >= 2)
      : null;
    const corroborating = [broadCounterparties, twoSidedQuoting, mostlyExternalFills, managedInventory].filter(v => v === true).length;
    const contradicting = [broadCounterparties, twoSidedQuoting, mostlyExternalFills, managedInventory].filter(v => v === false).length;

    let confidence = decentFillRate ? 0.6 : 0.4;
    confidence = Math.max(0.2, Math.min(0.85, confidence + 0.05 * corroborating - 0.08 * contradicting));

    const evidenceAgainstBenign = [];
    if (!decentFillRate) evidenceAgainstBenign.push('Fill rate is low despite the high order volume — automation alone does not explain that combination');
    if (broadCounterparties === false) evidenceAgainstBenign.push(`Trades against only ${profile.distinctCounterpartyCount} distinct counterpart${profile.distinctCounterpartyCount === 1 ? 'y' : 'ies'} — more consistent with a private arrangement than open market-making`);
    if (twoSidedQuoting === false) evidenceAgainstBenign.push('Only ever trades one direction of its dominant pair — not genuine two-sided quoting');
    if (mostlyExternalFills === false) evidenceAgainstBenign.push(`Only ${profile.externalFillPct.toFixed(0)}% of identifiable fills are against external accounts or AMM liquidity — most are against its own other offers`);
    if (managedInventory === false) evidenceAgainstBenign.push(`Inventory in its dominant pair keeps drifting in one direction with no reversal (peak ${profile.inventory.driftRatio?.toFixed(1)}x its own typical order size)`);

    findings.push(mkFinding({
      module: 'Market-Maker Automation', category: 'automation', sev: 'info', confidence,
      headline: 'Behavior consistent with automated market-making / quote maintenance',
      detail: `${(profile.cancelRatio * 100).toFixed(0)}% cancel ratio, ${profile.sizeCV != null ? 'CV ' + profile.sizeCV.toFixed(2) : 'no size-uniformity read'}, max ${profile.burstWindows.thirtySec} offers/30s.`,
      observed: [
        `Cancel ratio: ${(profile.cancelRatio * 100).toFixed(0)}%`,
        profile.sizeCV != null ? `Order-size coefficient of variation: ${profile.sizeCV.toFixed(2)}` : null,
        `Burst: up to ${profile.burstWindows.thirtySec} offers in 30s, ${profile.burstWindows.oneHour} in 1h`,
        decentFillRate ? `Realized fill rate: ${fillRateAnalysis.realizedFillPctOverall.toFixed(1)}% — not zero, consistent with a working market-making strategy` : 'Realized fill rate is low or unknown',
        broadCounterparties != null ? `Traded against ${profile.distinctCounterpartyCount} distinct counterpart${profile.distinctCounterpartyCount === 1 ? 'y' : 'ies'}` : null,
        twoSidedQuoting != null ? (twoSidedQuoting ? `Quotes both sides of its dominant pair (${(profile.twoSidedRatio * 100).toFixed(0)}% on the smaller side)` : 'Only trades one direction of its dominant pair') : null,
        mostlyExternalFills != null ? `${profile.externalFillPct.toFixed(0)}% of identifiable fills were against external accounts or AMM liquidity, not its own other offers` : null,
        managedInventory != null ? (managedInventory ? `Inventory in its dominant pair returns toward flat (${profile.inventory.reversions} reversal${profile.inventory.reversions === 1 ? '' : 's'} observed)` : 'Inventory in its dominant pair has drifted substantially with no reversal') : null,
      ].filter(Boolean),
      alternativeExplanations: ['Spoofing/layering dressed up with uniform sizing to look automated'],
      evidenceAgainstBenign,
      classification: decentFillRate
        ? `High cancel/burst/uniformity plus a non-trivial realized fill rate is the expected signature of legitimate automated market-making (${corroborating} of up to 4 additional market-making signals corroborate this). This explanation should reduce confidence in Wash Execution and Spoofing findings above, not add to them.`
        : 'High cancel/burst/uniformity WITHOUT meaningful fills is less consistent with genuine market-making — weigh the Spoofing and Wash Execution findings above accordingly.',
    }));
  } else {
    findings.push(mkFinding({ module: 'Market-Maker Automation', category: 'automation', sev: 'ok', headline: 'No strong automation signature', detail: 'Order behavior does not show the high-cancel/tight-sizing/burst pattern typical of automated market-making.' }));
  }

  return { automationLikely, findings };
}

/* ── Backward-compat combiner ──
   Keeps the function name and call-site signature `computeOverallRisk`/
   `buildRiskBreakdown` already expect, so this pass doesn't need to touch
   their signatures — splitting the underlying scoring/weights into
   separate risk-score buckets is deferred to a later Risk Score phase. */
function analyseWashTrading(txList, addr, lines, offerLifecycles, fillRateAnalysis, liveBookAnalysis, isProjectAccount = false, executionLedger = null, auctionGroupCurrencies = null) {
  const profile = buildOfferBehaviorProfile(offerLifecycles, txList, addr);
  const execRouting = analyseExecutionRouting(executionLedger || { stats: { total: 0 } });
  const execution   = analyseWashExecution(profile, offerLifecycles, txList, addr, isProjectAccount, executionLedger);
  const spoofing    = analyseSpoofingScore(profile, offerLifecycles, txList, addr, liveBookAnalysis, executionLedger, auctionGroupCurrencies);
  const automation  = analyseMarketMakerAutomation(profile, offerLifecycles, txList, addr, fillRateAnalysis);

  const signals = [
    ...execRouting.findings, ...execution.findings, ...spoofing.findings, ...automation.findings,
    ...(fillRateAnalysis?.findings || []),
  ];

  // Legacy verdict banding preserved for computeOverallRisk's existing
  // formula — now derived from execution+spoofing only (automation is
  // explanatory, not accusatory, so it doesn't add to the combined score).
  const score = Math.min(100, execution.score + spoofing.score);
  const verdict = score === 0 ? 'clean' : score < 25 ? 'low-risk' : score < 50 ? 'suspicious' : 'high-risk';

  return {
    signals, score, verdict,
    executionScore: execution.score, spoofingScore: spoofing.score, automationLikely: automation.automationLikely,
    valueCirculation: execution.valueCirculation,
    topRelationships: execution.topRelationships,
    stats: {
      creates: offerLifecycles.list.length,
      cancels: offerLifecycles.list.filter(r => r.status === 'cancelled').length,
      fills: fillRateAnalysis?.immediateFillCount ?? 0,
      payments: txList.filter(({ tx }) => tx.TransactionType === 'Payment').length,
      roundTrip: execution.stats.roundTrip, selfTrades: execution.stats.selfTrades,
      execRoute: execRouting.stats,
    },
  };
}

/* ── Benford's Law Analysis ─────────────────────────
   Tests first digits of all monetary amounts.
   Natural data follows log10(1 + 1/d) distribution.
   Large chi-squared = fabricated / bot data.
──────────────────────────────────────────────────── */
// Expected Benford probabilities (digits 1–9)
const _BENFORD_EXPECTED = [0, 0.301, 0.176, 0.125, 0.097, 0.079, 0.067, 0.058, 0.051, 0.046];

/** Groups candidate amounts by currency AND broad transaction class —
 *  running Benford on one pool that mixes XRP Payments with an IOU's
 *  OfferCreate amounts tests a meaningless blended distribution neither
 *  represents. */
function _collectBenfordGroups(txList) {
  const groups = new Map();
  for (const { tx } of txList) {
    const txClass = tx.TransactionType === 'Payment' ? 'Payment'
      : (tx.TransactionType === 'OfferCreate' || tx.TransactionType === 'OfferCancel') ? 'Offer' : null;
    if (!txClass) continue;
    const candidates = [tx.Amount, tx.TakerGets, tx.TakerPays, tx.SendMax, tx.DeliverMin];
    for (const c of candidates) {
      const currency = amtCurrency(c);
      const v = amtNum(c);
      if (v == null || v <= 0 || !Number.isFinite(v) || !currency) continue;
      const key = `${currency}|${txClass}`;
      if (!groups.has(key)) groups.set(key, { currency, txClass, values: [] });
      groups.get(key).values.push(v);
    }
  }
  return groups;
}

/** Eligibility gate, run BEFORE trusting a chi-square result: Benford only
 *  means something on datasets with enough observations, a wide magnitude
 *  spread, and values that aren't mechanically constrained to a tick-size/
 *  round-number grid (fixed lot sizes, decimal conventions, and algorithmic
 *  strategy parameters all mechanically skew leading digits for reasons
 *  that have nothing to do with fabrication). */
function _computeBenfordApplicability(values) {
  const n = values.length;
  const reasons = [];
  if (n < 50) return { level: 'LOW', reasons: [`Only ${n} observations in this group (need ≥50)`], n };

  const sorted = [...values].sort((a, b) => a - b);
  const min = sorted[0], max = sorted[sorted.length - 1];
  const magnitudeSpread = min > 0 ? Math.log10(max / min) : 0;

  const roundMagn = [100, 1_000, 10_000, 100_000];
  const roundCount = values.filter(v => roundMagn.some(m => Math.abs(v % m) < 1e-6 && v / m >= 1)).length;
  const roundPct = roundCount / n;

  let level = 'HIGH';
  if (magnitudeSpread < 1) { level = 'LOW'; reasons.push(`Values span only ${magnitudeSpread.toFixed(1)} orders of magnitude — Benford needs a wide spread to be meaningful`); }
  else if (magnitudeSpread < 2) { level = 'MEDIUM'; reasons.push(`Narrow magnitude spread (${magnitudeSpread.toFixed(1)} orders of magnitude)`); }

  if (roundPct > 0.5) { level = 'LOW'; reasons.push(`${(roundPct * 100).toFixed(0)}% round-number amounts — suggests fixed lot sizes or tick constraints, not organically-generated values`); }
  else if (roundPct > 0.25 && level === 'HIGH') { level = 'MEDIUM'; reasons.push(`${(roundPct * 100).toFixed(0)}% round-number amounts`); }

  if (n < 100 && level === 'HIGH') { level = 'MEDIUM'; reasons.push(`Sample size (${n}) clears the minimum but is still modest`); }
  if (!reasons.length) reasons.push('Sufficient sample size, wide magnitude spread, low round-number concentration');

  return { level, reasons, magnitudeSpread, roundPct, n };
}

function _computeBenfordChiSquare(values) {
  const n = values.length;
  const observed = new Array(10).fill(0);
  for (const v of values) {
    const s = v.toFixed(6).replace(/^0+\.?0*/, '');
    const d = parseInt(s[0], 10);
    if (d >= 1 && d <= 9) observed[d]++;
  }
  let chiSq = 0;
  const digitBreakdown = [];
  for (let d = 1; d <= 9; d++) {
    const obs = observed[d] / n;
    const exp = _BENFORD_EXPECTED[d];
    chiSq += n * Math.pow(obs - exp, 2) / exp;
    digitBreakdown.push({ digit: d, obs: (obs * 100).toFixed(1), exp: (exp * 100).toFixed(1), delta: ((obs - exp) * 100).toFixed(1) });
  }
  return { chiSq, digitBreakdown, n };
}

/** Continuous, applicability-discounted score contribution — used by both
 *  computeOverallRisk and buildRiskBreakdown so the two can't drift apart
 *  the way the old tiered +10/+5/+0 logic did across its two copies. */
function benfordScoreContribution(benfords) {
  if (benfords?.chiSq == null) return 0;
  const multiplier = { HIGH: 1, MEDIUM: 0.5, LOW: 0.15 }[benfords.overallApplicability] ?? 0.15;
  return Math.min(10, (benfords.chiSq / 20.09) * 10) * multiplier;
}

function analyseBenfordsLaw(txList) {
  const groups = _collectBenfordGroups(txList);
  const results = [];
  for (const [key, g] of groups) {
    if (g.values.length < 50) continue;
    const applicability = _computeBenfordApplicability(g.values);
    const chi = _computeBenfordChiSquare(g.values);
    results.push({ key, currency: g.currency, txClass: g.txClass, ...chi, applicability });
  }
  results.sort((a, b) => b.n - a.n);

  if (!results.length) {
    return {
      signals: [{ sev: 'info', label: "Insufficient data for Benford's Law",
        detail: 'No single currency/transaction-class group reached the 50-observation minimum — amounts are too fragmented across assets to test any one distribution meaningfully.' }],
      results: [], overallApplicability: 'LOW', chiSq: null, verdict: 'insufficient', digitBreakdown: [], sampleSize: 0,
    };
  }

  const signals = results.map(r => mkFinding({
    module: "Benford's Law", category: 'market-integrity',
    sev: r.applicability.level === 'LOW' ? 'info' : (r.chiSq > 20.09 ? 'warn' : 'ok'),
    confidence: { HIGH: 0.7, MEDIUM: 0.4, LOW: 0.15 }[r.applicability.level],
    headline: `${r.currency === 'XRP' ? 'XRP' : shortAddr(r.currency)} ${r.txClass} amounts: χ²=${r.chiSq.toFixed(1)}, Applicability ${r.applicability.level}`,
    detail: `n=${r.n} observations`,
    observed: [
      `Benford Applicability: ${r.applicability.level}`,
      ...r.applicability.reasons,
      `Chi-square statistic: ${r.chiSq.toFixed(2)} (critical values: 15.51 at p<0.05, 20.09 at p<0.01)`,
    ],
    classification: r.applicability.level === 'LOW'
      ? "Benford's Law is not reliably applicable to this group (narrow magnitude spread and/or high round-number concentration) — a deviation here says nothing about whether amounts were fabricated."
      : (r.chiSq > 20.09
        ? 'Amount-generation pattern is non-natural under this model. This describes the shape of the distribution, not a conclusion about intent — fixed pricing tiers, algorithmic strategies, and token denomination conventions are common legitimate causes of Benford deviation.'
        : 'First-digit distribution is consistent with organic, unconstrained amount generation.'),
  }));

  const primary = results[0];
  const overallApplicability = results.some(r => r.applicability.level === 'HIGH') ? 'HIGH'
    : results.some(r => r.applicability.level === 'MEDIUM') ? 'MEDIUM' : 'LOW';

  return {
    signals, results, overallApplicability,
    chiSq: primary.chiSq,
    verdict: primary.chiSq > 20.09 ? 'high-deviation' : primary.chiSq > 15.51 ? 'moderate-deviation' : 'normal',
    digitBreakdown: primary.digitBreakdown, sampleSize: primary.n,
  };
}

/* ═══════════════════════════════════════════════════
   FORENSIC ANALYTICS SUITE
   Four independent quantitative engines that complement
   Benford's Law to form a 5-pillar fraud detection framework.
   Each engine produces signals, a numeric score, and a
   layman verdict. All five feed the combined Forensic Report.
═══════════════════════════════════════════════════ */

/* ── [1] Shannon's Entropy ────────────────────────────
   Measures information randomness in transaction amounts,
   counterparty diversity, time-of-day spread, and tx types.

   THEORY: Organic financial activity has medium entropy —
   not too uniform (bots repeat amounts) and not maximally
   random (artificially shuffled data). Entropy outside the
   natural band is a structural signal of non-organic behavior.

   H = −Σ p(x) · log₂(p(x))

   Organic range for XRPL wallets: ~2.4–3.8 bits (amount bins)
   Bot-generated: < 1.8 (repeating) or > 4.2 (pure random)
──────────────────────────────────────────────────── */
function analyseShannonsEntropy(txList, addr) {
  const MIN_TX = 30;
  const signals = [];
  // Low entropy — repetitive amounts, concentrated counterparties, fixed
  // operating hours — is exactly what a high-volume, automated custodial
  // system looks like, and a known exchange running one is not remotely
  // suspicious on its own; it's the expected shape of the job. Confirmed
  // live: Bitstamp's hot wallet showed H=0.01 bits amount entropy, which
  // this module unconditionally called "a bot or scripted actor" at 'warn'
  // — technically true (it IS automated) but a real false positive in
  // effect, since the accusatory framing implies concealment/manipulation
  // rather than ordinary exchange operations.
  const isKnownExchange = getEntity(addr)?.type === 'exchange';

  // ── 1. Amount magnitude entropy ──────────────────
  const amounts = [];
  for (const { tx } of txList) {
    const candidates = [tx.Amount, tx.TakerGets, tx.TakerPays];
    for (const c of candidates) {
      const v = typeof c === 'string' ? Number(c) / 1e6
              : (c?.value ? Number(c.value) : null);
      if (v && v > 0 && Number.isFinite(v)) amounts.push(v);
    }
  }

  const amountEntropy = amounts.length >= MIN_TX ? (() => {
    // Bucket into 12 magnitude bins (log scale)
    const bins = new Array(12).fill(0);
    for (const v of amounts) {
      const bin = Math.min(11, Math.max(0, Math.floor(Math.log10(v + 1) * 2)));
      bins[bin]++;
    }
    return _shannonH(bins);
  })() : null;

  // ── 2. Counterparty address entropy ───────────────
  const cpCounts = {};
  for (const { tx } of txList) {
    const cp = tx.Account === addr ? tx.Destination : tx.Account;
    if (cp && cp !== addr) cpCounts[cp] = (cpCounts[cp] || 0) + 1;
  }
  const cpFreqs = Object.values(cpCounts);
  const counterpartyEntropy = cpFreqs.length >= 3 ? _shannonH(cpFreqs) : null;

  // ── 3. Time-of-day distribution entropy ──────────
  const hourBins = new Array(24).fill(0);
  let hasTimes = false;
  for (const { tx } of txList) {
    if (tx.date) {
      const rippleEpoch = 946684800; // Ripple epoch offset from Unix
      const hour = new Date((tx.date + rippleEpoch) * 1000).getUTCHours();
      hourBins[hour]++;
      hasTimes = true;
    }
  }
  const timeEntropy = hasTimes && txList.length >= MIN_TX ? _shannonH(hourBins) : null;

  // ── 4. Transaction type entropy ───────────────────
  const typeCounts = {};
  for (const { tx } of txList) {
    typeCounts[tx.TransactionType] = (typeCounts[tx.TransactionType] || 0) + 1;
  }
  const typeEntropy = _shannonH(Object.values(typeCounts));

  // ── 5. Verdict construction ───────────────────────
  let verdict = 'normal';
  let riskPenalty = 0;

  // Low amount entropy: bot repeating the same amounts — expected, not
  // suspicious, for a known exchange's high-volume custodial system.
  if (amountEntropy !== null) {
    if (amountEntropy < 1.5 && isKnownExchange) {
      signals.push({ sev: 'info',
        label: `Amount entropy low (H=${amountEntropy.toFixed(2)} bits) — expected for a known exchange`,
        detail: `Transaction amounts are highly repetitive, but this address is a known exchange — a high-volume custodial system processing many standard-sized deposits/withdrawals routinely shows exactly this pattern. Not treated as evidence of concealment or manipulation.` });
    } else if (amountEntropy < 1.5) {
      verdict = 'low-entropy';
      riskPenalty += 18;
      signals.push({ sev: 'warn',
        label: `Amount entropy critically low (H=${amountEntropy.toFixed(2)} bits)`,
        detail: `Transaction amounts are highly repetitive. A bot or scripted actor tends to reuse the same values. Organic wallets show entropy ≥2.4 bits across amount magnitudes.` });
    } else if (amountEntropy < 2.2) {
      riskPenalty += 8;
      signals.push({ sev: 'info',
        label: `Amount entropy below natural range (H=${amountEntropy.toFixed(2)} bits)`,
        detail: `Some amount repetition detected. Could indicate automated activity mixed with organic transactions.` });
    } else if (amountEntropy > 4.5) {
      riskPenalty += 10;
      signals.push({ sev: 'info',
        label: `Amount entropy abnormally high (H=${amountEntropy.toFixed(2)} bits)`,
        detail: `Transaction amounts are maximally varied — more than organic activity typically shows. This can indicate amounts were artificially randomized to evade Benford detection.` });
    } else {
      signals.push({ sev: 'ok',
        label: `Amount entropy normal (H=${amountEntropy.toFixed(2)} bits)`,
        detail: `Transaction amount diversity is consistent with organic financial activity.` });
    }
  }

  // Low counterparty entropy: concentrated interactions (wash ring signal)
  if (counterpartyEntropy !== null) {
    if (counterpartyEntropy < 1.0 && cpFreqs.length < 4) {
      riskPenalty += 14;
      signals.push({ sev: 'warn',
        label: `Counterparty entropy very low (H=${counterpartyEntropy.toFixed(2)} bits)`,
        detail: `This wallet transacts with very few unique addresses and with high repetition — a structural signature of round-trip wash trading rings.` });
    } else if (counterpartyEntropy < 2.0) {
      riskPenalty += 5;
      signals.push({ sev: 'info',
        label: `Counterparty entropy low (H=${counterpartyEntropy.toFixed(2)} bits)`,
        detail: `Most interactions are concentrated among a small set of counterparties.` });
    } else {
      signals.push({ sev: 'ok',
        label: `Counterparty diversity healthy (H=${counterpartyEntropy.toFixed(2)} bits)`,
        detail: `Counterparty distribution reflects diverse interaction patterns.` });
    }
  }

  // Time-of-day concentration: bot at exact hours
  if (timeEntropy !== null) {
    const maxPossible = Math.log2(24);
    const relEntropy = timeEntropy / maxPossible;
    if (relEntropy < 0.45) {
      riskPenalty += 10;
      signals.push({ sev: 'warn',
        label: `Time-of-day entropy low (H=${timeEntropy.toFixed(2)} bits, ${(relEntropy*100).toFixed(0)}% of max)`,
        detail: `Transactions cluster heavily in a few hours of the day. Bots typically run at fixed UTC hours; organic users spread activity across the day.` });
    } else {
      signals.push({ sev: 'ok',
        label: `Time-of-day distribution natural (H=${timeEntropy.toFixed(2)} bits)`,
        detail: `Transaction timing is distributed across hours in a pattern consistent with human activity.` });
    }
  }

  // Captured BEFORE the insufficient-data finding is pushed below, which
  // would otherwise make signals.length >= 1 unconditionally and hide the
  // true "nothing could be computed" case from the verdict itself — the
  // same N/A-vs-Normal distinction already applied to Spoofing/Market-
  // Making: a wallet too new/thin for any of the 4 sub-metrics to compute
  // must read as insufficient, not silently default to 'normal'.
  const hadNoComputableSignal = !signals.length;
  if (hadNoComputableSignal) {
    signals.push({ sev: 'info', label: 'Insufficient data for entropy analysis',
      detail: `Need ≥${MIN_TX} transactions. Found ${txList.length}.` });
  }

  if (hadNoComputableSignal) verdict = 'insufficient';
  else if (riskPenalty >= 18) verdict = 'anomalous';
  else if (riskPenalty >= 8)  verdict = 'elevated';

  return {
    signals, verdict, riskPenalty,
    amountEntropy, counterpartyEntropy, timeEntropy, typeEntropy,
    uniqueCounterparties: cpFreqs.length, sampleSize: txList.length,
  };
}

function _shannonH(counts) {
  const total = counts.reduce((a, b) => a + b, 0);
  if (!total) return 0;
  return -counts.reduce((h, c) => {
    if (!c) return h;
    const p = c / total;
    return h + p * Math.log2(p);
  }, 0);
}

/* ── [2] Zipf's Law Analysis ──────────────────────────
   THEORY: In natural systems — language, city populations,
   internet traffic, organic financial networks — the nth
   most frequent item has frequency ∝ 1/nˢ where s ≈ 1.

   For XRPL: rank counterparties by interaction frequency.
   Organic wallets follow Zipf (s ≈ 0.8–1.3).
   Wash-trading rings show flat distributions (s < 0.4)
   or hyper-concentrated (s > 2.2).

   Method: OLS regression of log(rank) vs log(frequency).
   The slope is the Zipf exponent.
──────────────────────────────────────────────────── */
function analyseZipfsLaw(txList, addr) {
  const MIN_CP = 8; // need enough counterparties
  const signals = [];

  // Build counterparty frequency map
  const cpMap = {};
  for (const { tx } of txList) {
    const cp = tx.Account === addr ? tx.Destination : tx.Account;
    if (cp && cp !== addr) cpMap[cp] = (cpMap[cp] || 0) + 1;
  }
  const freqs = Object.values(cpMap).sort((a, b) => b - a);

  if (freqs.length < MIN_CP) {
    return {
      signals: [{ sev: 'info',
        label: `Insufficient counterparties for Zipf's Law (need ≥${MIN_CP}, found ${freqs.length})`,
        detail: 'Zipf analysis becomes meaningful with a broader counterparty network.' }],
      verdict: 'insufficient', zipfExponent: null, riskPenalty: 0,
      freqTable: [], uniqueCounterparties: freqs.length,
    };
  }

  // OLS regression: log(rank) vs log(frequency)
  const n = freqs.length;
  let sumX = 0, sumY = 0, sumXY = 0, sumX2 = 0;
  const logPairs = freqs.map((f, i) => ({ rank: i + 1, freq: f,
    lx: Math.log(i + 1), ly: Math.log(f) }));

  for (const { lx, ly } of logPairs) {
    sumX += lx; sumY += ly; sumXY += lx * ly; sumX2 += lx * lx;
  }
  const denom = n * sumX2 - sumX * sumX;
  const slope = denom !== 0 ? (n * sumXY - sumX * sumY) / denom : null;
  const zipfExponent = slope !== null ? Math.abs(slope) : null;

  // R² for fit quality
  const meanY = sumY / n;
  let ssTot = 0, ssRes = 0;
  const b = (sumY - slope * sumX) / n;
  for (const { lx, ly } of logPairs) {
    ssTot += Math.pow(ly - meanY, 2);
    ssRes += Math.pow(ly - (slope * lx + b), 2);
  }
  const rSquared = ssTot > 0 ? 1 - ssRes / ssTot : 0;

  let verdict = 'normal';
  let riskPenalty = 0;

  if (zipfExponent !== null) {
    if (rSquared < 0.55) {
      // Poor Zipf fit — artificial structure
      riskPenalty += 12;
      signals.push({ sev: 'warn',
        label: `Counterparty distribution doesn't follow Zipf's Law (R²=${rSquared.toFixed(2)})`,
        detail: `Natural networks follow a power-law rank-frequency relationship. This wallet's counterparty network has poor Zipf fit (R²=${rSquared.toFixed(2)}), suggesting artificial or script-driven interaction structure.` });
      verdict = 'anomalous';
    } else if (zipfExponent < 0.4) {
      // Too flat: unusually uniform usage of counterparties (wash ring)
      riskPenalty += 15;
      signals.push({ sev: 'warn',
        label: `Zipf exponent too flat (s=${zipfExponent.toFixed(2)}, expected 0.8–1.3)`,
        detail: `A very flat Zipf exponent means counterparties are used with surprisingly equal frequency. In organic networks, you transact far more often with a few key addresses. Flat distribution is consistent with round-trip wash trading rings.` });
      verdict = 'anomalous';
    } else if (zipfExponent > 2.2) {
      // Too steep: hyper-concentration
      riskPenalty += 10;
      signals.push({ sev: 'warn',
        label: `Zipf exponent hyper-concentrated (s=${zipfExponent.toFixed(2)}, expected 0.8–1.3)`,
        detail: `Extreme concentration on one or two counterparties with steep dropoff. While not unusual for simple wallets, combined with other signals this suggests coordinated narrow-ring activity.` });
      verdict = 'elevated';
    } else {
      signals.push({ sev: 'ok',
        label: `Counterparty network follows Zipf's Law (s=${zipfExponent.toFixed(2)}, R²=${rSquared.toFixed(2)})`,
        detail: `The rank-frequency distribution of counterparties follows the expected natural power-law pattern. This is consistent with organic wallet activity.` });
    }
  }

  // Also check amount Zipf (round-number concentration)
  const amtBins = {};
  for (const { tx } of txList) {
    const v = typeof tx.Amount === 'string' ? Math.round(Number(tx.Amount) / 1e4) * 10 : null;
    if (v && v > 0) amtBins[v] = (amtBins[v] || 0) + 1;
  }
  const amtFreqs = Object.values(amtBins).sort((a, b) => b - a);
  const topAmtShare = amtFreqs.length ? amtFreqs[0] / amtFreqs.reduce((a,b)=>a+b,0) : 0;
  if (topAmtShare > 0.45 && getEntity(addr)?.type === 'exchange') {
    // Same false positive already found and fixed in analyseShannonsEntropy:
    // a known exchange repeating one standard deposit/withdrawal amount
    // across most of its transactions is the ordinary, expected shape of a
    // high-volume custodial system, not "a hallmark of... wash-trading
    // activity." Confirmed live: Bitstamp's hot wallet showed one amount
    // dominating 86% of transactions.
    signals.push({ sev: 'info',
      label: `Single amount dominates ${(topAmtShare*100).toFixed(0)}% of transactions — expected for a known exchange`,
      detail: `One transaction amount accounts for most payments, but this address is a known exchange — a high-volume custodial system repeating a standard deposit/withdrawal denomination routinely shows exactly this pattern. Not treated as evidence of scripted manipulation.` });
  } else if (topAmtShare > 0.45) {
    riskPenalty += 8;
    signals.push({ sev: 'warn',
      label: `Single amount dominates ${(topAmtShare*100).toFixed(0)}% of transactions`,
      detail: `One transaction amount value accounts for nearly half of all payments. Round-number dominance is a hallmark of scripted or wash-trading activity.` });
  }

  if (!signals.length) {
    signals.push({ sev: 'info', label: 'Zipf analysis: no anomalies detected', detail: 'Counterparty distribution consistent with natural activity.' });
  }

  return {
    signals, verdict, riskPenalty,
    zipfExponent, rSquared, freqTable: freqs.slice(0, 12),
    uniqueCounterparties: freqs.length,
  };
}

/* ── [3] Time Series Analysis ─────────────────────────
   THEORY: Human financial activity is irregular and
   bursty. Bots are periodic and mechanically spaced.

   We measure:
   1. Inter-transaction interval CV (coefficient of variation)
      Bot CV ≈ 0–0.3 (too regular)
      Human CV ≈ 0.8–3.0 (irregular)
   2. Autocorrelation at lag-1 and lag-7 days (periodicity)
   3. Volume burst score (sudden spikes vs baseline)
   4. Day-of-week entropy (bots often skip weekends or run 24/7)
──────────────────────────────────────────────────── */
function analyseTimeSeries(txList) {
  const MIN_TX = 20;
  const RIPPLE_EPOCH = 946684800;

  if (txList.length < MIN_TX) {
    return {
      signals: [{ sev: 'info',
        label: `Insufficient transactions for time series analysis (need ≥${MIN_TX}, found ${txList.length})`,
        detail: 'Time series analysis requires a longer transaction history.' }],
      verdict: 'insufficient', riskPenalty: 0, intervalCV: null,
      autocorrelation: null, burstScore: null, periodicityScore: null,
    };
  }

  // ── 1. Collect timestamps ───────────────────────
  const timestamps = txList
    .filter(({ tx }) => tx.date != null)
    .map(({ tx }) => (tx.date + RIPPLE_EPOCH) * 1000)
    .sort((a, b) => a - b);

  if (timestamps.length < MIN_TX) {
    return { signals: [{ sev: 'info', label: 'No timestamp data available', detail: 'Time series requires date-stamped transactions.' }],
      verdict: 'insufficient', riskPenalty: 0, intervalCV: null, autocorrelation: null, burstScore: null, periodicityScore: null };
  }

  // ── 2. Inter-transaction intervals ──────────────
  const intervals = [];
  for (let i = 1; i < timestamps.length; i++) {
    const d = (timestamps[i] - timestamps[i-1]) / 1000; // seconds
    if (d > 0 && d < 86400 * 30) intervals.push(d); // exclude gaps > 30 days
  }

  let intervalCV = null;
  if (intervals.length >= 5) {
    const mean = intervals.reduce((a,b) => a+b, 0) / intervals.length;
    const std = Math.sqrt(intervals.reduce((s, v) => s + Math.pow(v - mean, 2), 0) / intervals.length);
    intervalCV = mean > 0 ? std / mean : null;
  }

  // ── 3. Daily volume buckets ──────────────────────
  const dayBuckets = {};
  for (const t of timestamps) {
    const day = new Date(t).toISOString().slice(0, 10);
    dayBuckets[day] = (dayBuckets[day] || 0) + 1;
  }
  const dailyVols = Object.values(dayBuckets);

  // ── 4. Burst score ───────────────────────────────
  let burstScore = 0;
  if (dailyVols.length >= 4) {
    const mean = dailyVols.reduce((a,b)=>a+b,0)/dailyVols.length;
    const std  = Math.sqrt(dailyVols.reduce((s,v)=>s+Math.pow(v-mean,2),0)/dailyVols.length);
    const maxVol = Math.max(...dailyVols);
    burstScore = std > 0 ? (maxVol - mean) / std : 0; // z-score of peak day
  }

  // ── 5. Lag-1 autocorrelation ─────────────────────
  let autocorrelation = null;
  if (dailyVols.length >= 6) {
    const mean = dailyVols.reduce((a,b)=>a+b,0)/dailyVols.length;
    const centered = dailyVols.map(v => v - mean);
    const denom = centered.reduce((s,v)=>s+v*v,0);
    if (denom > 0) {
      const lag1 = centered.slice(0,-1).reduce((s,v,i)=>s+v*centered[i+1],0) / denom;
      autocorrelation = lag1;
    }
  }

  // ── 6. Day-of-week entropy ───────────────────────
  const dowBins = new Array(7).fill(0);
  for (const t of timestamps) dowBins[new Date(t).getUTCDay()]++;
  const dowEntropy = _shannonH(dowBins);
  const maxDowH = Math.log2(7);

  // ── 7. Periodicity detection (FFT-lite: look for dominant period) ────
  let periodicityScore = 0;
  if (intervals.length >= 10) {
    // Count how many intervals are within ±20% of the median
    const sorted = [...intervals].sort((a,b)=>a-b);
    const median = sorted[Math.floor(sorted.length/2)];
    const nearMedian = intervals.filter(v => Math.abs(v - median) / median < 0.2).length;
    periodicityScore = nearMedian / intervals.length;
  }

  // ── 8. Regime change: does this account's daily transaction rate shift
  // significantly partway through its history? A simple split-half rate
  // comparison — not a formal changepoint algorithm (PELT, Bayesian, etc.),
  // labeled honestly as such — but real signal a single blended CV/
  // periodicity score across the WHOLE history can miss entirely (e.g. a
  // wallet that was quiet for months then became active every 5 minutes).
  const dayEntries = Object.entries(dayBuckets).sort((a, b) => a[0].localeCompare(b[0]));
  let regimeChange = null;
  if (dayEntries.length >= 8) {
    const mid = Math.floor(dayEntries.length / 2);
    const firstHalf = dayEntries.slice(0, mid), secondHalf = dayEntries.slice(mid);
    const rate = arr => arr.reduce((s, [, v]) => s + v, 0) / arr.length;
    const r1 = rate(firstHalf), r2 = rate(secondHalf);
    const ratio = r1 > 0 && r2 > 0 ? Math.max(r1, r2) / Math.min(r1, r2) : null;
    if (ratio != null && ratio >= 3) {
      regimeChange = { transitionDate: secondHalf[0][0], beforeRate: r1, afterRate: r2, ratio, direction: r2 > r1 ? 'increase' : 'decrease' };
    }
  }

  // ── 9. Automation Probability — replaces the old binary "bot-pattern"
  // verdict. Predictable timing is a DESCRIPTION, not an accusation: a bot
  // firing every 5 minutes isn't risky merely for being predictable. This
  // is reported as a probability with an explicit non-risk framing, always
  // 'info' severity — never contributes bare pattern-matching to a risk
  // score's warn/critical tier on its own.
  let automationProbability = 0;
  if (intervalCV !== null) automationProbability += Math.max(0, (0.6 - intervalCV) / 0.6) * 60;
  automationProbability += periodicityScore * 40;
  automationProbability = Math.min(100, Math.round(automationProbability));

  const signals = [];
  let verdict = 'normal';
  let riskPenalty = 0;

  if (automationProbability >= 60) {
    signals.push({ sev: 'info',
      label: `Automation Probability: ${automationProbability}% (interval CV=${intervalCV != null ? intervalCV.toFixed(2) : '—'}, periodicity=${(periodicityScore*100).toFixed(0)}%)`,
      detail: `Transaction timing is consistent with scripted/automated execution. This describes HOW the account operates, not whether it's risky — automation alone is common and legitimate (market makers, subscription payments, scheduled treasury operations).` });
    riskPenalty += 6; // small, not the old 20-point "bot-pattern" penalty — predictability alone shouldn't dominate a risk score
  } else if (automationProbability >= 30) {
    signals.push({ sev: 'ok',
      label: `Automation Probability: ${automationProbability}%`,
      detail: 'Some timing regularity, within a range common to both scheduled tools and habitual human usage.' });
  } else {
    signals.push({ sev: 'ok',
      label: `Automation Probability: ${automationProbability}%`,
      detail: 'Transaction timing shows natural, human-like variance.' });
  }

  if (regimeChange) {
    riskPenalty += 4;
    signals.push({ sev: 'info',
      label: `Regime Change detected around ${regimeChange.transitionDate}`,
      detail: `Daily transaction rate ${regimeChange.direction}d roughly ${regimeChange.ratio.toFixed(1)}x (${regimeChange.beforeRate.toFixed(1)} → ${regimeChange.afterRate.toFixed(1)} tx/day). A simple split-half comparison, not a formal changepoint test — treat the transition date as approximate.` });
  }

  if (burstScore > 3.5) {
    const peakDay = dayEntries.length ? dayEntries.reduce((a, b) => (b[1] > a[1] ? b : a))[0] : null;
    signals.push({ sev: 'info',
      label: `Burst Event: peak day z-score ${burstScore.toFixed(1)}${peakDay ? ` (${peakDay})` : ''}`,
      detail: `One day had extreme transaction volume relative to this account's own baseline. Consistent with a coordinated event, an account-recovery sweep, or simply a busy day — timing and other signals (Fund Flow, Fee Spikes) provide the context this alone can't.` });
  }

  if (autocorrelation !== null && autocorrelation > 0.6) {
    riskPenalty += 4;
    signals.push({ sev: 'info',
      label: `Volume Autocorrelation: HIGH (ρ=${autocorrelation.toFixed(2)})`,
      detail: `Day-to-day transaction volume is strongly self-correlated — consistent with a routine that maintains a steady pace, not inherently risky on its own.` });
  }

  const dowRel = dowEntropy / maxDowH;
  if (dowRel < 0.7 && timestamps.length > 30) {
    signals.push({ sev: 'info',
      label: `Unusual Relative to Account Baseline: day-of-week activity concentrated (${(dowRel*100).toFixed(0)}% of max entropy)`,
      detail: `Transactions cluster on specific days of the week relative to this account's own history. Both maximally-flat (every day) and business-hours-only patterns can produce this — direction matters more than the raw number.` });
  }

  if (signals.length <= 1 && automationProbability < 30) {
    signals.push({ sev: 'ok', label: 'No temporal anomalies detected',
      detail: 'Transaction timing patterns are consistent with organic human activity.' });
  }
  if (riskPenalty >= 10) verdict = 'elevated';

  const span = timestamps.length >= 2
    ? Math.round((timestamps[timestamps.length-1] - timestamps[0]) / 86400000)
    : null;

  return {
    signals, verdict, riskPenalty, intervalCV, autocorrelation,
    burstScore, periodicityScore, automationProbability, regimeChange, dowEntropy, dowBins,
    dailyVolume: Object.entries(dayBuckets).slice(-30),
    activeSpanDays: span, totalTimestamped: timestamps.length,
  };
}

/* ── [4] Offer/Flow Coupling (Cross-Correlation) ─
   NOT Granger causality, deliberately. Granger causality tests whether
   PAST values of X improve prediction of FUTURE values of Y — that needs
   an autoregressive model of Y on its own lags, a restricted-vs-
   unrestricted model comparison, and a significance test. What this
   engine actually computes is a Pearson cross-correlation coefficient at
   scanned lags (0-4 windows) — real lead-lag information when the lag is
   nonzero, but a coefficient, not a causal test, and a lag-0 result is
   contemporaneous correlation, not a lead-lag relationship at all. Every
   user-facing label below says "Coupling" or "Contemporaneous
   Correlation," never "causes"/"causality," and confidence is capped low
   (≤0.4) accordingly.

   XRPL applications:
   A. Offer-creation / cancellation coupling (wash-trading-shaped pattern)
   B. Inflow / outflow coupling (pass-through/round-trip-shaped pattern)
   C. NFT listing / acceptance coupling (trap-offer-shaped pattern)

   Method: Pearson cross-correlation at lags 0..5 windows (12h/window).
──────────────────────────────────────────────────── */
function analyseGrangerCausality(txList, addr) {
  const MIN_TX = 20;
  const signals = [];
  const RIPPLE_EPOCH = 946684800;

  if (txList.length < MIN_TX) {
    return {
      signals: [{ sev: 'info',
        label: `Insufficient data for offer/flow coupling analysis (need ≥${MIN_TX}, found ${txList.length})`,
        detail: 'Testing for lead-lag correlation requires enough temporal observations.' }],
      verdict: 'insufficient', riskPenalty: 0,
      offerCancelCausality: null, inflowOutflowCausality: null,
    };
  }

  // ── Bucket transactions into 12-hour windows ──────
  const WINDOW_MS = 12 * 3600 * 1000;
  const bucketOf = tx => {
    if (!tx.date) return null;
    return Math.floor(((tx.date + RIPPLE_EPOCH) * 1000) / WINDOW_MS);
  };

  const buckets = {};
  const ensureBucket = b => {
    if (!buckets[b]) buckets[b] = { offerCreate: 0, offerCancel: 0, inflow: 0, outflow: 0, nftList: 0, nftAccept: 0 };
  };

  for (const { tx, meta } of txList) {
    const b = bucketOf(tx);
    if (b === null) continue;
    ensureBucket(b);
    const d = buckets[b];
    const t = tx.TransactionType;

    if (t === 'OfferCreate') d.offerCreate++;
    else if (t === 'OfferCancel') d.offerCancel++;

    if (t === 'NFTokenCreateOffer') d.nftList++;
    else if (t === 'NFTokenAcceptOffer') d.nftAccept++;

    // Inflow/outflow
    const delivered = meta?.delivered_amount || tx.Amount;
    const xrpAmt = typeof delivered === 'string' ? Number(delivered) / 1e6 : 0;
    if (xrpAmt > 0) {
      if (tx.Destination === addr) d.inflow += xrpAmt;
      else if (tx.Account === addr) d.outflow += xrpAmt;
    }
  }

  const sortedKeys = Object.keys(buckets).map(Number).sort((a,b)=>a-b);
  if (sortedKeys.length < 6) {
    return {
      signals: [{ sev: 'info', label: 'Insufficient temporal windows for coupling analysis',
        detail: 'Need activity spread across multiple time windows.' }],
      verdict: 'insufficient', riskPenalty: 0,
      offerCancelCausality: null, inflowOutflowCausality: null,
    };
  }

  const seriesX = (key) => sortedKeys.map(k => buckets[k][key] || 0);

  // Cross-correlation at lags 0..4 windows
  const crossCorr = (X, Y, maxLag = 4) => {
    const n = X.length;
    const mx = X.reduce((a,b)=>a+b,0)/n, my = Y.reduce((a,b)=>a+b,0)/n;
    const Xc = X.map(x=>x-mx), Yc = Y.map(y=>y-my);
    const sdX = Math.sqrt(Xc.reduce((s,x)=>s+x*x,0)/n);
    const sdY = Math.sqrt(Yc.reduce((s,y)=>s+y*y,0)/n);
    if (!sdX || !sdY) return Array(maxLag+1).fill(0);
    return Array.from({ length: maxLag+1 }, (_, lag) => {
      let sum = 0, cnt = 0;
      for (let i = 0; i + lag < n; i++) { sum += Xc[i] * Yc[i+lag]; cnt++; }
      return cnt > 0 ? sum / (cnt * sdX * sdY) : 0;
    });
  };

  let verdict = 'normal';
  let riskPenalty = 0;

  // Every finding below is a Pearson cross-correlation coefficient at a
  // scanned lag — real lead-lag information (better than a single zero-lag
  // reading), but NOT Granger causality: there's no autoregressive model
  // of the target series on its own past, no restricted-vs-unrestricted
  // model comparison, and no significance test. "Causes"/"causality" language
  // is retired from every user-facing string below. A lag-0 result is
  // contemporaneous correlation specifically — not a lead-lag relationship
  // at all — and is labeled that way, not folded into the coupling language
  // used for genuine lag>0 results.

  // ── A. OfferCreate / OfferCancel coupling ─────────
  const ocSeries  = seriesX('offerCreate');
  const canSeries = seriesX('offerCancel');
  const ocCCF     = crossCorr(ocSeries, canSeries);
  const maxOCLag  = ocCCF.indexOf(Math.max(...ocCCF));
  const maxOCCorr = Math.max(...ocCCF);
  const offerCancelCausality = { ccf: ocCCF, maxCorr: maxOCCorr, maxLag: maxOCLag };

  if (maxOCCorr > 0.55 && maxOCLag <= 2) {
    riskPenalty += 18;
    verdict = 'strong-coupling';
    signals.push(mkFinding({
      module: 'Offer Coupling', category: 'market-integrity', sev: 'warn', confidence: 0.4,
      headline: `Offer Creation/Cancellation Coupling: HIGH (ρ=${maxOCCorr.toFixed(2)}, lag=${maxOCLag} window${maxOCLag === 1 ? '' : 's'})`,
      detail: `Offer creation and cancellation are strongly correlated ${maxOCLag} window(s) apart (${maxOCLag * 12}h).`,
      observed: [`Cross-correlation ρ=${maxOCCorr.toFixed(2)} at a ${maxOCLag}-window lag`, 'Correlation, not a causality test — no autoregressive model or significance test was run'],
      alternativeExplanations: ['Active order management/repricing that naturally pairs creates with cancels', 'A market maker\'s normal quote-refresh cycle'],
      classification: 'Statistical coupling observed between offer creation and cancellation timing. This is the kind of pattern wash trading can produce, but correlation at a lag is not proof of it — see Wash Execution and Spoofing for behavior-level evidence.',
    }));
  } else if (maxOCCorr > 0.35) {
    riskPenalty += 6;
    signals.push(mkFinding({
      module: 'Offer Coupling', category: 'market-integrity', sev: 'info', confidence: 0.25,
      headline: `Offer Creation/Cancellation Coupling: MODERATE (ρ=${maxOCCorr.toFixed(2)}, lag=${maxOCLag})`,
      detail: 'A mild temporal link between creating and cancelling offers.',
    }));
  } else {
    signals.push({ sev: 'ok', label: 'Offer Creation/Cancellation Coupling: LOW',
      detail: 'Offer creation and cancellation timing appear independent.' });
  }

  // ── B. Inflow / Outflow coupling ──────────────────
  const inSeries  = seriesX('inflow');
  const outSeries = seriesX('outflow');
  const ioCCF     = crossCorr(inSeries, outSeries);
  const maxIOLag  = ioCCF.indexOf(Math.max(...ioCCF));
  const maxIOCorr = Math.max(...ioCCF);
  const inflowOutflowCausality = { ccf: ioCCF, maxCorr: maxIOCorr, maxLag: maxIOLag };

  if (maxIOCorr > 0.65 && maxIOLag === 0) {
    riskPenalty += 12;
    signals.push(mkFinding({
      module: 'Offer Coupling', category: 'market-integrity', sev: 'warn', confidence: 0.4,
      headline: `Inflow/Outflow Contemporaneous Correlation: HIGH (ρ=${maxIOCorr.toFixed(2)})`,
      detail: 'Funds entering and leaving the wallet in the same 12h window are strongly correlated.',
      observed: [`Zero-lag correlation ρ=${maxIOCorr.toFixed(2)} — same-window co-movement, not a lead-lag relationship`, 'A lag-0 result cannot show which direction (if either) leads the other'],
      alternativeExplanations: ['Pass-through/consolidation behavior (an intermediary account by design)', 'Routine deposit-then-forward operational pattern'],
      classification: 'Same-window co-movement between inflow and outflow, not a demonstrated lead-lag pattern. Consistent with pass-through/round-trip activity, but zero lag means the data alone cannot establish which value moved first.',
    }));
  } else if (maxIOCorr > 0.55 && maxIOLag <= 1) {
    riskPenalty += 8;
    signals.push(mkFinding({
      module: 'Offer Coupling', category: 'market-integrity', sev: 'info', confidence: 0.3,
      headline: `Inflow/Outflow Coupling: MODERATE (ρ=${maxIOCorr.toFixed(2)}, lag=${maxIOLag})`,
      detail: 'Incoming funds are correlated with outgoing funds at a short lag.',
    }));
  } else {
    signals.push({ sev: 'ok', label: 'Inflow/Outflow Coupling: LOW',
      detail: 'Inflow and outflow timing are not predictably linked.' });
  }

  // ── C. NFT listing / acceptance coupling ──────────
  const nftL = seriesX('nftList');
  const nftA = seriesX('nftAccept');
  const totalNftList = nftL.reduce((a,b)=>a+b,0);
  const totalNftAccept = nftA.reduce((a,b)=>a+b,0);
  if (totalNftList > 3 && totalNftAccept > 3) {
    const nftCCF = crossCorr(nftL, nftA);
    const maxNFTCorr = Math.max(...nftCCF);
    const maxNFTLag  = nftCCF.indexOf(maxNFTCorr);
    if (maxNFTCorr > 0.6 && maxNFTLag <= 1) {
      riskPenalty += 8;
      signals.push(mkFinding({
        module: 'Offer Coupling', category: 'market-integrity', sev: 'warn', confidence: 0.3,
        headline: `NFT Listing/Acceptance Coupling: HIGH (ρ=${maxNFTCorr.toFixed(2)}, lag=${maxNFTLag})`,
        detail: 'NFT sell-offer creation is closely correlated with acceptance timing.',
        alternativeExplanations: ['A pre-arranged legitimate sale between known parties'],
        classification: 'Timing coupling only — combined with the NFT trap detection module\'s own evidence, this can support (but does not by itself prove) a coordinated-acceptance pattern.',
      }));
    }
  }

  if (!signals.some(s => s.sev === 'warn' || s.sev === 'critical')) {
    if (!signals.length) signals.push({ sev: 'ok', label: 'No coupling anomalies detected',
      detail: 'Temporal relationships between transaction types show no notable lead-lag or contemporaneous correlation.' });
  }

  if (riskPenalty >= 18) verdict = 'strong-coupling';
  else if (riskPenalty >= 8) verdict = 'elevated';

  return {
    signals, verdict, riskPenalty,
    offerCancelCausality, inflowOutflowCausality,
    windowCount: sortedKeys.length,
  };
}

/* ── Volume Concentration (token-focused) ────────────
   Measures how many unique accounts are generating
   volume for each IOU/token. <5 unique actors is
   a strong wash-trading signal.
──────────────────────────────────────────────────── */
function _decodeMemoText(raw) {
  if (!raw) return '';
  try {
    let ascii = '';
    for (let i = 0; i < raw.length; i += 2) {
      const c = parseInt(raw.slice(i, i + 2), 16);
      if (c >= 32 && c < 127) ascii += String.fromCharCode(c);
    }
    return ascii.length > 4 ? ascii.toLowerCase().trim() : '';
  } catch { return ''; }
}

function _unionFind(n) {
  const parent = Array.from({ length: n }, (_, i) => i);
  const find = x => (parent[x] === x ? x : (parent[x] = find(parent[x])));
  const union = (a, b) => { const ra = find(a), rb = find(b); if (ra !== rb) parent[ra] = rb; };
  return { find, union };
}

/** Best-effort clustering of raw addresses into likely-same-controller
 *  "economic actors" — the two signals honestly buildable from data this
 *  account's own txList already has, no extra RPC calls: sharing an
 *  identical memo string, or repeatedly transacting within a tight time
 *  window of each other. Cannot detect shared funding source or off-chain
 *  relationships — that would need each counterparty's own transaction
 *  history, which isn't available here. Explicitly not exhaustive. */
function _clusterVolumeActors(senderEntries) {
  const n = senderEntries.length;
  const { find, union } = _unionFind(n);
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      const a = senderEntries[i], b = senderEntries[j];
      const sharedMemo = a.memos.size && [...a.memos].some(m => b.memos.has(m));
      if (sharedMemo) { union(i, j); continue; }
      let syncCount = 0;
      for (const ta of a.timestamps) for (const tb of b.timestamps) if (Math.abs(ta - tb) <= 30) syncCount++;
      const minTx = Math.min(a.timestamps.length, b.timestamps.length);
      if (syncCount >= 3 && syncCount >= minTx * 0.5) union(i, j);
    }
  }
  const groups = new Map();
  for (let i = 0; i < n; i++) {
    const root = find(i);
    if (!groups.has(root)) groups.set(root, []);
    groups.get(root).push(senderEntries[i]);
  }
  return [...groups.values()];
}

/** HHI (standard antitrust concentration index, 0-10000) and Gini
 *  coefficient (0-1 inequality measure) computed on CLUSTER volumes, not
 *  raw per-address volumes — the whole point of clustering first. */
function _computeConcentrationStats(clusterVolumes) {
  const total = clusterVolumes.reduce((a, b) => a + b, 0);
  if (total <= 0 || !clusterVolumes.length) return null;
  const shares = clusterVolumes.map(v => v / total).sort((a, b) => b - a);
  const hhi = shares.reduce((s, x) => s + x * x, 0) * 10000;

  const sortedAsc = [...clusterVolumes].sort((a, b) => a - b);
  const n = sortedAsc.length;
  let giniNumerator = 0;
  sortedAsc.forEach((x, i) => { giniNumerator += (i + 1) * x; });
  const gini = n > 1 && total > 0 ? Math.max(0, (2 * giniNumerator) / (n * total) - (n + 1) / n) : 0;

  return {
    hhi, gini,
    top1Share: shares[0] || 0,
    top5Share: shares.slice(0, 5).reduce((a, b) => a + b, 0),
    top10Share: shares.slice(0, 10).reduce((a, b) => a + b, 0),
    effectiveParticipants: hhi > 0 ? 10000 / hhi : n,
    shares, // sorted descending, one per cluster — used to draw a real per-cluster share bar
  };
}

/** Plain-language lead sentence for a concentration reading — the DOJ/FTC
 *  HHI merger-guideline bands already cited in the whitepaper (< 1500
 *  unconcentrated, 1500-2500 moderate, > 2500 highly concentrated), spoken
 *  in ordinary language before the HHI/Gini numbers themselves. Same
 *  "plain language first, real numbers for analysts" pattern used
 *  throughout the Inspector. */
function _volConcPlainLabel(hhi) {
  if (hhi >= 2500) return 'Trading activity is extremely concentrated: a small number of participants account for most of the observed volume.';
  if (hhi >= 1500) return 'Trading activity is moderately concentrated among a limited set of participants.';
  return 'Trading activity is broadly distributed across many participants — no small group dominates the volume.';
}

const VOLCONC_CLUSTER_CAP = 200; // skip O(n²) clustering above this many senders per currency
// Below this trade count, severity is capped at 'warn' regardless of HHI —
// a 2-actor/9-trade market can mathematically produce the same extreme HHI
// as a well-sampled, genuinely concentrated one, but confidence being low
// for the small sample doesn't stop the severity BADGE itself from reading
// as CRITICAL unless it's gated too. Distinct from the trades<8 "too few to
// compute at all" gate above — this is "enough to compute, not enough to
// trust the most severe label."
const VOLCONC_SEVERITY_SAMPLE_MIN = 50;
// Below this many DISTINCT participants, HHI concentration is mathematically
// guaranteed to read as extreme regardless of trade count — a 2-address
// market is 100% "concentrated" by construction, not by manipulation. See
// the severity-gating comment below for why this is a separate check from
// the trade-count gate above (a market can clear that gate on volume alone
// while still only ever having had a handful of total participants).
const VOLCONC_MIN_ACTORS_FOR_CRITICAL = 5;

function analyseVolumeConcentration(txList, addr) {
  // Aggregate per-sender volume, memos, and timestamps, per currency —
  // clustering needs each sender's own memo/timing fingerprint, not just a
  // running total.
  const tokenData = new Map(); // currency → { senderMap: Map<sender, {sender, vol, memos, timestamps}>, vol, trades }

  for (const { tx } of txList) {
    const candidates = [tx.TakerGets, tx.Amount];
    const memos = (tx.Memos || []).map(m => _decodeMemoText(m.Memo?.MemoData || '')).filter(Boolean);
    for (const amt of candidates) {
      if (!amt || typeof amt !== 'object') continue; // skip XRP strings
      const currency = amt.currency;
      const value    = Number(amt.value || 0);
      const sender   = tx.Account;
      if (!currency || !sender || value <= 0 || !Number.isFinite(value)) continue;

      if (!tokenData.has(currency)) tokenData.set(currency, { senderMap: new Map(), vol: 0, trades: 0 });
      const d = tokenData.get(currency);
      d.vol += value; d.trades++;

      if (!d.senderMap.has(sender)) d.senderMap.set(sender, { sender, vol: 0, memos: new Set(), timestamps: [] });
      const s = d.senderMap.get(sender);
      s.vol += value;
      s.timestamps.push(getCloseTime(tx));
      for (const m of memos) s.memos.add(m);
    }
  }

  const signals = [];
  const concentrations = [];

  for (const [currency, d] of tokenData.entries()) {
    if (d.trades < 8) continue; // too few trades to be meaningful
    const senderEntries = [...d.senderMap.values()];
    const rawActorCount = senderEntries.length;
    const clusteringSkipped = rawActorCount > VOLCONC_CLUSTER_CAP;
    const clusters = clusteringSkipped ? senderEntries.map(s => [s]) : _clusterVolumeActors(senderEntries);
    const clusterVolumes = clusters.map(c => c.reduce((s, e) => s + e.vol, 0));
    const stats = _computeConcentrationStats(clusterVolumes);
    if (!stats) continue;
    const mergedCount = rawActorCount - clusters.length;

    concentrations.push({ currency, rawActorCount, estimatedActorClusters: clusters.length, vol: d.vol, trades: d.trades, ...stats });

    if (stats.hhi > 1500) {
      const sampleLimited = d.trades < VOLCONC_SEVERITY_SAMPLE_MIN;
      // A market with only a handful of DISTINCT participants will always
      // show extreme HHI mathematically, no matter how many trades happened
      // between them — 2 people trading back and forth 200 times is not
      // evidence of a few actors dominating a market that should have many,
      // it's the mechanical result of there only ever being 2 participants
      // in this account's observed history. The trade-count gate above
      // catches "too few trades to trust the math" but doesn't catch this —
      // a high trade count between a tiny handful of addresses cleared that
      // gate while still being exactly the "genuinely thin, low-participation
      // market" case the sample-size cap was designed to catch.
      //
      // Gated on the CLUSTERED estimate, not the raw address count: raw
      // addresses only ever overstate the number of real actors (clustering
      // merges same-controller wallets together, never splits one address
      // into several), so a market with e.g. 6 raw addresses that clusters
      // down to 3 real actors is exactly the "too few actors" case this gate
      // exists to catch — checking the pre-clustering count let it slip
      // through uncapped, a real false positive confirmed live against SOLO
      // (BITx/PLX/USDC all cleared the raw-count floor at 5+ addresses while
      // the tool's own clustering concluded only 2-4 real participants).
      const tooFewActors = clusters.length < VOLCONC_MIN_ACTORS_FOR_CRITICAL;
      const rawSev = stats.hhi > 2500 ? 'critical' : 'warn';
      const sev = (sampleLimited || tooFewActors) ? (rawSev === 'critical' ? 'warn' : 'info') : rawSev;
      const currencyLabel = hexToAscii(currency) || currency;
      signals.push(mkFinding({
        module: 'Volume Concentration', category: 'market-integrity',
        sev,
        confidence: clusteringSkipped ? 0.3 : (mergedCount > 0 ? 0.45 : 0.3),
        headline: `${currencyLabel}: ~${clusters.length} estimated economic actor(s) (${rawActorCount} raw addresses), HHI ${Math.round(stats.hhi)}`,
        detail: `${d.trades} trades totalling ${fmt(d.vol, 2)} ${currencyLabel}.`,
        observed: [
          `Raw distinct addresses: ${rawActorCount}`,
          clusteringSkipped ? `Address count exceeded the clustering cap (${VOLCONC_CLUSTER_CAP}) for this pass — shown as raw addresses, not clustered` :
            (mergedCount > 0 ? `${mergedCount} address(es) merged into fewer likely-same-controller clusters via shared memo text or synchronized timing` : 'No clustering signal found — each address treated as a separate actor'),
          `HHI: ${Math.round(stats.hhi)} (${stats.hhi > 2500 ? 'highly concentrated' : 'moderately concentrated'} by standard antitrust bands: <1500 unconcentrated, 1500-2500 moderate, >2500 high)`,
          `Gini coefficient: ${stats.gini.toFixed(2)}`,
          `Top-1 actor share: ${(stats.top1Share * 100).toFixed(0)}% · Top-5: ${(stats.top5Share * 100).toFixed(0)}%`,
          `Effective participant count (10000/HHI): ${stats.effectiveParticipants.toFixed(1)}`,
          sampleLimited ? `Severity capped: only ${d.trades} trades observed (below the ${VOLCONC_SEVERITY_SAMPLE_MIN}-trade bar for trusting an extreme severity label) — a tiny illiquid market can mathematically produce the same HHI as a well-sampled, genuinely concentrated one` : null,
          (tooFewActors && !sampleLimited) ? `Severity capped: only ~${clusters.length} estimated distinct economic actor(s) (${rawActorCount} raw address(es)) ever participated (below the ${VOLCONC_MIN_ACTORS_FOR_CRITICAL}-actor bar) — a market this small is mathematically concentrated by construction, regardless of trade volume` : null,
        ].filter(Boolean),
        alternativeExplanations: mergedCount > 0
          ? ['One legitimate market participant operating multiple wallets for ordinary reasons (custody segregation, accounting)']
          : tooFewActors
            ? ['This account trading with a small, fixed set of counterparties (e.g. personal wallets, a friend, an OTC arrangement) rather than participating in a broader market at all']
            : ['A genuinely thin, low-participation market rather than coordinated activity'],
        classification: sampleLimited
          ? `Concentration is mathematically ${stats.hhi > 2500 ? 'EXTREME' : 'moderate-to-high'} by HHI, but the sample (${d.trades} trades) is too small to distinguish coordinated activity from a simply illiquid, thinly-traded market — manipulation evidence is INSUFFICIENT at this sample size, not confirmed.`
          : tooFewActors
            ? `Concentration is mathematically ${stats.hhi > 2500 ? 'EXTREME' : 'moderate-to-high'} by HHI, but only ~${clusters.length} estimated distinct economic actor(s) (${rawActorCount} raw address(es)) were ever observed in this currency's activity — with this few total participants, high concentration is a mechanical certainty, not evidence of a few actors dominating a market that should otherwise have many.`
            : 'Clustering here is best-effort — shared memo text or tightly synchronized timing only. It cannot detect a shared funding source or off-chain relationships between addresses, so the true number of distinct economic actors may be lower than shown, not higher.',
      }));
    }
  }

  if (!concentrations.length) {
    signals.push({ sev: 'info', label: 'No IOU/token volume data',
      detail: 'No token-denominated transactions found in history (XRP-only activity).' });
  } else if (!signals.length) {
    signals.push({ sev: 'ok', label: 'Volume concentration normal',
      detail: `${concentrations.length} token(s) analysed — all show broad, unconcentrated participation (HHI < 1500).` });
  }

  return { signals, concentrations };
}

/* ── Token Issuer Analysis ───────────────────────── */
function analyseTokenIssuer(acct, lines, flags, txList) {
  const signals = [];
  const isIssuer = !!(flags & FLAGS.lsfDefaultRipple) || lines.some(l => l.account === acct.Account);

  // Obligations: lines where account is the "account" field = they issued those tokens
  const obligations = lines.filter(l => Number(l.balance) < 0); // negative = we owe to holders
  const totalObligated = obligations.reduce((a, l) => a + Math.abs(Number(l.balance)), 0);

  if (obligations.length > 0) {
    signals.push({ sev: 'info', label: `Token issuer: ${obligations.length} outstanding currency lines`,
      detail: `Total outstanding: ${fmt(totalObligated, 2)} across ${obligations.length} holder(s).` });
  }

  // Freeze checks
  const frozenLines = lines.filter(l => l.freeze);
  const frozenByIssuer = lines.filter(l => l.freeze_peer);
  if (frozenLines.length) {
    signals.push({ sev: 'warn', label: `${frozenLines.length} trustline(s) frozen by this account`,
      detail: 'This account has frozen specific trustlines.' });
  }
  if (frozenByIssuer.length) {
    signals.push({ sev: 'critical', label: `${frozenByIssuer.length} of your trustline(s) frozen by issuer`,
      detail: `Frozen currencies: ${frozenByIssuer.map(l => l.currency).join(', ')}. You cannot transfer these tokens.` });
  }

  // Global freeze
  if (flags & FLAGS.lsfGlobalFreeze) {
    signals.push({ sev: 'critical', label: 'Global Freeze — all token transfers suspended',
      detail: 'No holders can transfer tokens issued by this account.' });
  }

  // No-freeze flag (cannot freeze in future — good for holders)
  if (flags & FLAGS.lsfNoFreeze) {
    signals.push({ sev: 'ok', label: 'NoFreeze flag set — issuer cannot freeze balances',
      detail: 'Token holders are protected against future freeze actions.' });
  }

  // Historical AccountSet reconstruction — the CURRENT flag state (checked
  // above) only shows where things stand right now. An issuer that has
  // toggled Global Freeze on and off repeatedly has demonstrated a
  // willingness to actually exercise that control, which is a materially
  // different trust signal than simply holding the theoretical capability
  // and never using it.
  const ASF = { requireAuth: 2, noFreeze: 6, globalFreeze: 7, defaultRipple: 8, depositAuth: 9 };
  const issuerFlagHistory = txList
    .filter(({ tx }) => tx.TransactionType === 'AccountSet' && tx.Account === acct.Account && (tx.SetFlag != null || tx.ClearFlag != null))
    .map(({ tx }) => ({ date: tx.date, hash: tx.hash, setFlag: tx.SetFlag ?? null, clearFlag: tx.ClearFlag ?? null }))
    .sort((a, b) => (a.date ?? 0) - (b.date ?? 0));

  const toggleCount = code => issuerFlagHistory.filter(h => h.setFlag === code || h.clearFlag === code).length;
  const globalFreezeToggles = toggleCount(ASF.globalFreeze);
  const requireAuthToggles  = toggleCount(ASF.requireAuth);

  if (globalFreezeToggles > 0) {
    const lastToggle = issuerFlagHistory.filter(h => h.setFlag === ASF.globalFreeze || h.clearFlag === ASF.globalFreeze).slice(-1)[0];
    signals.push(mkFinding({
      module: 'Token Issuer', category: 'issuer', sev: globalFreezeToggles > 1 ? 'warn' : 'info', confidence: 0.5,
      headline: `Global Freeze toggled ${globalFreezeToggles} time(s) in fetched history`,
      detail: `Most recent change: ${lastToggle.setFlag != null ? 'frozen' : 'unfrozen'}.`,
      observed: [`${globalFreezeToggles} AccountSet transaction(s) setting or clearing Global Freeze`],
      alternativeExplanations: ['A brief, disclosed freeze for a migration, exploit response, or contract upgrade'],
      classification: globalFreezeToggles > 1
        ? 'Repeated freeze/unfreeze cycles show the issuer actively exercises this control, not just holds it theoretically — worth understanding why, from the project\'s own communications.'
        : 'A single freeze event in this account\'s history — check whether it was disclosed and time-bound.',
    }));
  }
  if (requireAuthToggles > 0) {
    signals.push({ sev: 'info', label: `Require Auth toggled ${requireAuthToggles} time(s) in fetched history`,
      detail: 'The issuer has changed whether new trustlines require its approval at least once.' });
  }

  // Black hole check (issuer account deleted / no access = stranded tokens)
  const acctBalance = Number(acct.Balance || 0) / 1e6;
  const reserve = 10 + Number(acct.OwnerCount || 0) * 2;
  if (obligations.length > 0 && acctBalance < reserve + 1) {
    signals.push({ sev: 'warn', label: 'Issuer balance near reserve — possible black hole',
      detail: 'Issuer with outstanding tokens has almost no XRP above reserve. Tokens may be stranded.' });
  }

  // Note: detailed supply concentration analysis is in the Issuer Connections panel,
  // which correctly accounts for sample size and uses gateway_balances when available.

  if (signals.length === 0) {
    signals.push({ sev: 'ok', label: 'No token issuer flags', detail: 'This account does not appear to be a token issuer.' });
  }

  return { signals, isIssuer, obligationCount: obligations.length, issuerFlagHistory };
}

/* ── Account Role Evidence Model ────────────────────
   Separate from behavioral risk scoring entirely — this asks "what kind of
   account is this," not "what did it do." Each role carries its own state
   (VERIFIED = real on-ledger evidence that doesn't require guessing;
   BEHAVIORAL = a pattern consistent with a role, explicitly not identity)
   and a confidence, rather than collapsing everything into a single
   role name the way a first pass at this might.

   Deliberately does NOT attempt project/treasury/exchange/market-maker
   IDENTITY, LP-pool-share-of-project framing, or any role requiring
   external registries or peer-group data this app doesn't have — see
   getKnownAccountRole() below, a stub interface for exactly that, kept
   separate so a real registry can be plugged in later without touching
   any of this file's actual detection logic. Guessing those roles from
   weak on-ledger correlation would just relocate the false-positive
   problem this whole model exists to fix, not solve it. */
const ROLE_STATE = Object.freeze({
  VERIFIED: 'verified_on_ledger',
  BEHAVIORAL: 'behavioral_inference',
});

/** Stub for a future project/registry lookup — see design note above.
 *  Always returns "unknown" today; no project addresses are hard-coded
 *  into detector logic anywhere in this file. Exists so a real registry,
 *  manual verification list, or relationship graph can be wired in later
 *  by changing only this one function. */
function getKnownAccountRole(address) {
  return { state: 'unknown', projectId: null, confidence: null, evidence: [] };
}

/** Evidence-based role signals for one account — NOT a single "identity."
 *  An account can carry zero, one, or several of these at once (a token
 *  issuer can also mint NFTs and provide liquidity); the caller decides
 *  how to summarize them, this just reports what's actually observable. */
function analyseAccountRoles(lines, txList, addr, issuerAnalysis, nftAnalysis) {
  const roles = [];

  if (issuerAnalysis.isIssuer) {
    roles.push({
      role: 'token_issuer', label: 'Token Issuer', state: ROLE_STATE.VERIFIED, confidence: 1,
      evidence: [`${issuerAnalysis.obligationCount} outstanding currency line(s), verified via gateway_balances`],
    });
  }

  // NFT roles are kept as separate, independently-verified facts rather
  // than collapsed into one "NFT account" label — holding NFTs, trading
  // them, and minting them are three different, directly observable
  // behaviors, and none of them establishes this account IS a specific
  // NFT project, its team, or its issuer in any organizational sense.
  if (nftAnalysis.nftCount > 0) {
    roles.push({
      role: 'nft_holder', label: 'NFT Holder', state: ROLE_STATE.VERIFIED, confidence: 1,
      evidence: [`${nftAnalysis.nftCount} NFT(s) currently held`],
      caveat: 'Holding NFTs does not indicate this account is affiliated with any NFT project or collection as a team member, issuer, or minter.',
    });
  }
  if (nftAnalysis.acceptCount > 0) {
    roles.push({
      role: 'nft_trader', label: 'NFT Trader', state: ROLE_STATE.VERIFIED, confidence: 1,
      evidence: [`${nftAnalysis.acceptCount} NFTokenAcceptOffer transaction(s)`],
      caveat: 'Buying/selling NFTs does not indicate this account mints, issues, or is affiliated with any specific collection.',
    });
  }
  // NFT Minter, not "NFT project issuer" — minting is directly observable
  // on-ledger; which project (if any) an account's NFTs belong to is not,
  // without external data this app doesn't have. Also distinct from NFT
  // Issuer: XRPL lets one account (via the NFTokenMinter setting) mint on
  // behalf of a different issuing account — Nalu does not currently
  // reconstruct that delegation, so "Minter" here always means "the
  // account that submitted the NFTokenMint transaction," not necessarily
  // the account NFTs are issued under.
  if (nftAnalysis.mintCount > 0) {
    roles.push({
      role: 'nft_minter', label: 'NFT Minter', state: ROLE_STATE.VERIFIED, confidence: 1,
      evidence: [`${nftAnalysis.mintCount} NFTokenMint transaction(s)`],
      caveat: 'Distinct from "NFT project issuer" — no evidence links this account to a specific project, team, or organization.',
    });
  }

  // Liquidity Participant — LP token holdings and/or AMM transaction
  // history, both directly observable. Explicitly not "project liquidity
  // wallet": providing liquidity for a token doesn't establish a
  // relationship with whoever issues it.
  const lpLines = lines.filter(l => l.currency && Number(l.balance) !== 0 && l.currency.startsWith('03') && l.currency.length === 40);
  const ammTxCount = txList.filter(({ tx }) => tx.TransactionType === 'AMMDeposit' || tx.TransactionType === 'AMMWithdraw' || tx.TransactionType === 'AMMCreate').length;
  if (lpLines.length > 0 || ammTxCount > 0) {
    roles.push({
      role: 'liquidity_participant', label: 'Liquidity Participant', state: ROLE_STATE.VERIFIED, confidence: 1,
      evidence: [
        lpLines.length ? `${lpLines.length} active LP position(s)` : null,
        ammTxCount ? `${ammTxCount} AMM deposit/withdraw/create transaction(s)` : null,
      ].filter(Boolean),
      caveat: 'Providing liquidity for a token does not establish a relationship with that token\'s issuer or project.',
    });
  }

  // DEX Market-Making-Like Activity — a BEHAVIOR PROFILE, not an identity
  // claim. High-volume, high-cancel-rate offer activity is consistent with
  // market making but is inferred from behavior, not verified from a
  // declared role, so it's explicitly lower-confidence and framed as such.
  const offerCreates = txList.filter(({ tx }) => tx.TransactionType === 'OfferCreate').length;
  const offerCancels = txList.filter(({ tx }) => tx.TransactionType === 'OfferCancel').length;
  const MARKET_MAKING_MIN_OFFERS = 200; // avoid tagging an ordinary active trader
  if (offerCreates >= MARKET_MAKING_MIN_OFFERS) {
    const cancelRatio = offerCreates ? offerCancels / offerCreates : 0;
    roles.push({
      role: 'market_making_behavior', label: 'DEX Market-Making-Like Activity', state: ROLE_STATE.BEHAVIORAL,
      confidence: Math.min(0.9, 0.5 + Math.min(0.4, offerCreates / 2500) + (cancelRatio > 0.5 ? 0.1 : 0)),
      evidence: [
        `${offerCreates} OfferCreate transaction(s)`,
        offerCancels ? `${offerCancels} OfferCancel transaction(s) (${(cancelRatio * 100).toFixed(0)}% of creates)` : null,
      ].filter(Boolean),
      caveat: 'A behavioral pattern, not a verified identity — high DEX activity alone does not confirm this account operates as a market maker.',
    });
  }

  return roles;
}

/* ── Account Behavior Explorer ─────────────────────────
   A plain-language "what does this account actually do" summary, built
   entirely from analyses already computed elsewhere (accountRoles,
   issuerAnalysis, ammAnalysis, nftAnalysis, washAnalysis, offerLifecycles)
   — no new data engineering, no risk framing. Deliberately rendered BEFORE
   the risk-score banner: this describes behavior, not danger. A bullet is
   only shown when there's real evidence behind it — never a fabricated
   "this account might also..." line. */
function buildAccountBehaviorProfile(addr, txList, lines, accountRoles, issuerAnalysis, ammAnalysis, nftAnalysis, washAnalysis, offerLifecycles, walletAgeDays, historyCoverage, securityAudit) {
  const sentCount     = txList.filter(({ tx }) => tx.TransactionType === 'Payment' && tx.Account === addr).length;
  const receivedCount = txList.filter(({ tx }) => tx.TransactionType === 'Payment' && tx.Destination === addr).length;

  const behaviors = [];
  behaviors.push({ icon: '●', text: lines.length ? 'Holds XRP and tokens' : 'Holds XRP' });
  if (sentCount > 0 && receivedCount > 0) behaviors.push({ icon: '●', text: `Sends and receives payments (${sentCount} sent, ${receivedCount} received)` });
  else if (sentCount > 0) behaviors.push({ icon: '●', text: `Sends payments (${sentCount})` });
  else if (receivedCount > 0) behaviors.push({ icon: '●', text: `Receives payments (${receivedCount})` });

  if (ammAnalysis.positions.length > 0) {
    behaviors.push({ icon: '●', text: `Provides liquidity to ${ammAnalysis.positions.length} AMM pool${ammAnalysis.positions.length === 1 ? '' : 's'}` });
  } else if (ammAnalysis.deposits + ammAnalysis.withdrawals > 0) {
    // Fully withdrawn — no CURRENT position, but real historical AMM
    // activity exists and would otherwise vanish from this summary
    // entirely (a real gap: the "dominant activity" story text below can
    // legitimately call AMM activity the account's main focus while the
    // bullet list said nothing about AMM at all).
    behaviors.push({ icon: '●', text: 'Has provided AMM liquidity in the past (no active position currently)' });
  }
  if (offerLifecycles.list.length > 0) behaviors.push({ icon: '●', text: `Trades on the XRPL DEX (${offerLifecycles.list.length} order${offerLifecycles.list.length === 1 ? '' : 's'} placed)` });

  behaviors.push({ icon: '●', text: issuerAnalysis.isIssuer ? 'Issues a fungible token' : 'Does not issue a fungible token' });

  if (nftAnalysis.mintCount > 0) behaviors.push({ icon: '●', text: `Has minted ${nftAnalysis.mintCount} NFT${nftAnalysis.mintCount === 1 ? '' : 's'}` });
  else if (nftAnalysis.nftCount > 0) behaviors.push({ icon: '●', text: `Holds ${nftAnalysis.nftCount} NFT${nftAnalysis.nftCount === 1 ? '' : 's'}` });

  if (washAnalysis.automationLikely) behaviors.push({ icon: '●', text: 'Shows behavior consistent with automated trading activity' });

  // Ledger footprint — scale/character of the account at a glance.
  const distinctAssets = new Set(lines.filter(l => l.currency).map(l => l.currency));
  const dexPairs = new Set();
  for (const { tx } of txList) {
    if (tx.TransactionType !== 'OfferCreate' || tx.Account !== addr) continue;
    const gk = typeof tx.TakerGets === 'object' ? `${tx.TakerGets.currency}.${tx.TakerGets.issuer}` : 'XRP';
    const pk = typeof tx.TakerPays === 'object' ? `${tx.TakerPays.currency}.${tx.TakerPays.issuer}` : 'XRP';
    dexPairs.add([gk, pk].sort().join('/'));
  }
  const counterpartyCount = _buildCounterpartyData(txList, addr).size;
  const issuedCurrencyCount = new Set(lines.filter(l => Number(l.balance) < 0).map(l => l.currency)).size;

  const footprint = {
    daysActive: walletAgeDays,
    txCount: txList.length,
    txCountCapped: !!historyCoverage?.hitTxCap,
    counterpartyCount,
    assetsTouched: distinctAssets.size + 1, // +1 for XRP itself
    dexMarkets: dexPairs.size,
    ammPools: ammAnalysis.positions.length,
    ammPoolsHistorical: ammAnalysis.closedPositions?.length || 0,
    nftCount: nftAnalysis.nftCount,
    issuedCurrencyCount,
  };

  // Plain-language story — built from the same real numbers above, not
  // generic filler. Only claims a compromise-pattern absence when the
  // Security module's own "change" findings (not baseline config state)
  // support it, and explicitly redirects to Security when they don't.
  const verifiedRoles = accountRoles.filter(r => r.state === ROLE_STATE.VERIFIED);
  const primaryLabel = verifiedRoles.length ? verifiedRoles.map(r => r.label).join(' + ') : null;
  const ageText = walletAgeDays != null
    ? (walletAgeDays >= 365 ? `approximately ${(walletAgeDays / 365).toFixed(1)} years` : `${walletAgeDays} day${walletAgeDays === 1 ? '' : 's'}`)
    : 'an unconfirmed length of time';

  const activityCounts = [
    ['DEX trading', offerLifecycles.list.length],
    ['AMM liquidity provision', ammAnalysis.deposits + ammAnalysis.withdrawals],
    ['XRP payments', sentCount + receivedCount],
    ['NFT activity', nftAnalysis.nftCount + nftAnalysis.mintCount + (nftAnalysis.acceptCount || 0)],
  ].sort((a, b) => b[1] - a[1]);
  const dominant = activityCounts[0][1] > 0 ? activityCounts[0][0] : null;

  const noCompromiseSignal = !(securityAudit?.signals || []).some(s => s.kind === 'change' && (s.sev === 'critical' || s.sev === 'warn'));

  const storyParts = [
    `This account has been active for ${ageText}${footprint.txCountCapped ? ' (based on a capped sample of its transaction history)' : ''}.`,
    dominant ? `Its activity is primarily focused on ${dominant.toLowerCase()}.` : 'It has limited on-ledger activity so far.',
    primaryLabel ? `It is a verified ${primaryLabel}.` : '',
    noCompromiseSignal
      ? 'No recent account-control changes associated with a compromise pattern were detected.'
      : 'Recent account-control changes were detected — see the Security section below for detail.',
  ].filter(Boolean);

  return { behaviors, footprint, story: storyParts.join(' ') };
}

/** Account Journey (beginner-UX spec §41) — a plain-language timeline of
 *  real, verifiable "first occurrence" milestones, built from a single
 *  chronological scan of already-fetched txList. Deliberately limited to
 *  genuine firsts (first payment, first DEX offer, first AMM deposit,
 *  etc.) rather than the spec's own more interpretive examples ("becomes
 *  major LP," "high-frequency market activity begins") — those require a
 *  threshold judgment call this function isn't in a position to make
 *  responsibly, so only unambiguous, directly-observable facts are
 *  included. Requires txList sorted chronologically ascending (the
 *  convention already established everywhere else in this file). */
function buildAccountJourney(txList, addr, walletCreatedTs, walletAgeVerified, walletActivationEvidence = null) {
  const events = [];
  if (walletCreatedTs != null) {
    // walletCreatedTs is a Unix-epoch MILLISECONDS timestamp (ready for
    // `new Date(...)` directly) — every other date in this function is a
    // raw Ripple-epoch-seconds value like tx.date, and the shared render
    // path applies `(date + XRPL_EPOCH) * 1000` to convert to Unix ms.
    // Pushing walletCreatedTs in as-is would double-convert it through
    // that same path, producing a nonsense date. Convert to the same
    // Ripple-epoch-seconds unit as everything else in `events` instead.
    const walletCreatedRippleSec = Math.floor(walletCreatedTs / 1000) - XRPL_EPOCH;
    // Same provenance language as Account Overview's header (renderHeader)
    // — one canonical wallet-age computation feeds both, so the wording
    // must agree rather than independently re-describing the same fact.
    const detail = walletActivationEvidence
      ? `Verified via AccountRoot creation (ledger ${walletActivationEvidence.ledgerIndex ?? 'unknown'})`
      : walletAgeVerified
        ? 'Verified from complete fetched history'
        : 'Lower bound only — earliest verified activity, true activation date unconfirmed';
    events.push({ date: walletCreatedRippleSec, label: 'Account activated', detail });
  }

  const firstOfType = (predicate) => {
    for (const { tx } of txList) {
      if (tx.date == null) continue;
      if (predicate(tx)) return tx.date;
    }
    return null;
  };

  const milestones = [
    { predicate: tx => tx.TransactionType === 'Payment' && tx.Account === addr, label: 'First outbound payment' },
    { predicate: tx => tx.TransactionType === 'Payment' && tx.Destination === addr, label: 'First received payment' },
    { predicate: tx => tx.TransactionType === 'TrustSet' && tx.Account === addr, label: 'First token trust line established' },
    { predicate: tx => tx.TransactionType === 'OfferCreate' && tx.Account === addr, label: 'First DEX offer placed' },
    { predicate: tx => tx.TransactionType === 'AMMDeposit' && tx.Account === addr, label: 'First AMM liquidity deposit' },
    { predicate: tx => tx.TransactionType === 'AMMBid' && tx.Account === addr, label: 'First AMM auction slot bid' },
    { predicate: tx => tx.TransactionType === 'NFTokenMint' && tx.Account === addr, label: 'First NFT minted' },
    { predicate: tx => (tx.TransactionType === 'SetRegularKey' || tx.TransactionType === 'SignerListSet') && tx.Account === addr, label: 'First account security configuration change' },
  ];
  for (const m of milestones) {
    const date = firstOfType(m.predicate);
    if (date != null) events.push({ date, label: m.label });
  }

  // Largest-ever outbound transfer is a genuine, unambiguous fact (unlike
  // "Is This Normal?", which deliberately compares the MOST RECENT
  // transfer against prior history — here we're recording a real
  // milestone in the account's timeline, not judging normalcy).
  const outbound = txList
    .filter(({ tx }) => tx.TransactionType === 'Payment' && tx.Account === addr && typeof tx.Amount === 'string')
    .map(({ tx }) => ({ date: tx.date, xrp: Number(tx.Amount) / 1e6 }))
    .filter(p => p.xrp > 0 && p.date != null);
  if (outbound.length > 0) {
    const largest = outbound.reduce((max, cur) => (cur.xrp > max.xrp ? cur : max));
    events.push({ date: largest.date, label: 'Largest recorded outbound transfer', detail: `${fmt(largest.xrp, 2)} XRP` });
  }

  events.sort((a, b) => (a.date ?? 0) - (b.date ?? 0));
  return { applicable: events.length > 0, events };
}

function _renderAccountJourney(journey) {
  if (!journey?.applicable) return '';
  return `
    <div style="padding-top:10px;margin-top:10px;border-top:1px solid rgba(255,255,255,.06)">
      <div style="font-size:.65rem;font-weight:800;letter-spacing:.08em;color:rgba(255,255,255,.35);text-transform:uppercase;margin-bottom:8px">Account Journey — verified first-occurrence milestones</div>
      <div class="security-timeline">
        ${journey.events.map(ev => `
          <div class="security-timeline-item">
            <div class="security-timeline-dot">📍</div>
            <div class="security-timeline-body">
              <div class="security-timeline-date">${ev.date != null ? new Date((ev.date + XRPL_EPOCH) * 1000).toLocaleDateString() : 'Unknown date'}</div>
              <div class="security-timeline-label">${escHtml(ev.label)}</div>
              ${ev.detail ? `<div class="security-timeline-detail">${escHtml(ev.detail)}</div>` : ''}
            </div>
          </div>`).join('')}
      </div>
    </div>`;
}

/* ── Follow the Money ─────────────────────────────────────────────────────
   Beginner-UX spec §17-18: a chronological, plain-English story of where
   this account's funds came from and where they went. Deliberately does
   NOT run any new analysis or RPC calls — it's a narrative composition
   layer over data Fund Flow, Inbound Flow, and Drain Risk already
   computed, the same "synthesize what's already known" approach used by
   the Account Behavior story and the Account Journey timeline. Multi-hop
   tracing (following funds past this account's own counterparties) is
   explicitly out of scope — this app is single-account-scoped by design;
   see the AMM Control Surface note elsewhere in this file on staying
   inside that ceiling. */
function buildFollowTheMoneyNarrative(fundFlow, inboundFlow, drainEpisodes, addr) {
  const hasInbound  = (inboundFlow?.totalIn  || 0) > 0;
  const hasOutbound = (fundFlow?.totalOut || 0) > 0;
  if (!hasInbound && !hasOutbound) return { applicable: false };

  const chapters = [];

  if (hasInbound) {
    const top   = inboundFlow.topSources[0];
    const label = top.entity?.name || shortAddr(top.addr);
    const share = inboundFlow.totalIn > 0 ? top.totalXrp / inboundFlow.totalIn : null;
    chapters.push({
      icon: '💰', title: 'Where the funds came from',
      text: inboundFlow.uniqueSources === 1
        ? `All tracked inbound funds (${fmt(inboundFlow.totalIn, 2)} XRP) came from a single source: ${label}.`
        : `${fmt(inboundFlow.totalIn, 2)} XRP was received from ${inboundFlow.uniqueSources} source(s) in the analysed history. The largest was ${label}, contributing ${fmt(top.totalXrp, 2)} XRP${share != null ? ` (${fmt(share * 100, 0)}% of tracked inflow)` : ''}.`,
    });
  } else {
    chapters.push({ icon: '💰', title: 'Where the funds came from', text: 'No inbound Payment transactions were found in the analysed history — this account may have been funded via DEX trading, AMM activity, or in ledgers outside the fetched range.' });
  }

  if (hasOutbound) {
    const top   = fundFlow.destinations[0];
    const label = top.entity?.name || shortAddr(top.addr);
    const share = fundFlow.totalOut > 0 ? top.totalXrp / fundFlow.totalOut : null;
    chapters.push({
      icon: '📤', title: 'Where the funds went',
      text: fundFlow.uniqueDests === 1
        ? `All tracked outbound funds (${fmt(fundFlow.totalOut, 2)} XRP) were sent to a single destination: ${label}.`
        : `${fmt(fundFlow.totalOut, 2)} XRP was sent out to ${fundFlow.uniqueDests} destination(s). The largest recipient was ${label}, receiving ${fmt(top.totalXrp, 2)} XRP${share != null ? ` (${fmt(share * 100, 0)}% of tracked outflow)` : ''}.`,
    });
  } else {
    chapters.push({ icon: '📤', title: 'Where the funds went', text: 'No outbound Payment transactions were found in the analysed history — funds received have not been moved out via a Payment transaction (they may still be held, or moved via DEX/AMM activity instead).' });
  }

  if (drainEpisodes?.length) {
    const worst = [...drainEpisodes].sort((a, b) => b.actualDepletionPct - a.actualDepletionPct)[0];
    const dateLabel = d => d != null ? new Date((d + XRPL_EPOCH) * 1000).toLocaleDateString() : 'an unknown date';
    const classLabel = { sweep: 'a rapid sweep', 'pass-through': 'a pass-through movement', 'potential-drain': 'a potential drain', 'partial-outflow': 'a partial outflow' }[worst.classification] || worst.classification;
    chapters.push({
      icon: '⚡', title: 'A notable movement window',
      text: `Between ${dateLabel(worst.startDate)} and ${dateLabel(worst.endDate)}, this account moved ${fmt(worst.grossOutflowXrp, 2)} XRP out in a short window — classified as ${classLabel} (${fmt(worst.actualDepletionPct * 100, 0)}% actual balance depletion vs. ${fmt(worst.grossTurnoverPct * 100, 0)}% gross turnover). See Drain Risk below for the full evidence breakdown.`,
    });
  }

  if (hasInbound && hasOutbound) {
    const net = inboundFlow.totalIn - fundFlow.totalOut;
    chapters.push({
      icon: net >= 0 ? '📈' : '📉', title: 'Net position (tracked history)',
      text: `Across the analysed history, this account received ${fmt(inboundFlow.totalIn, 2)} XRP and sent out ${fmt(fundFlow.totalOut, 2)} XRP — a net ${net >= 0 ? 'inflow' : 'outflow'} of ${fmt(Math.abs(net), 2)} XRP. This covers tracked Payment transactions only; DEX trades, AMM activity, and reserve changes are not included (see the Market & DEX and AMM sections for those).`,
    });
  }

  return { applicable: true, chapters };
}

function _renderFollowTheMoneyNarrative(narrative) {
  if (!narrative?.applicable) return '';
  return `
    <div style="padding-top:10px;margin-top:10px;border-top:1px solid rgba(255,255,255,.06)">
      <div style="font-size:.65rem;font-weight:800;letter-spacing:.08em;color:rgba(255,255,255,.35);text-transform:uppercase;margin-bottom:8px">Follow the Money — where funds came from and went</div>
      <div class="security-timeline">
        ${narrative.chapters.map(c => `
          <div class="security-timeline-item">
            <div class="security-timeline-dot">${c.icon}</div>
            <div class="security-timeline-body">
              <div class="security-timeline-label">${escHtml(c.title)}</div>
              <div class="security-timeline-detail">${escHtml(c.text)}</div>
            </div>
          </div>`).join('')}
      </div>
    </div>`;
}

function renderAccountBehaviorExplorer(profile, journey = null, followTheMoney = null) {
  const el = document.getElementById('account-behavior-body');
  if (!el) return;
  const f = profile.footprint;

  const footprintItems = [
    f.daysActive != null ? [String(f.daysActive), 'days active'] : null,
    [f.txCount.toLocaleString() + (f.txCountCapped ? '+' : ''), 'transactions'],
    [f.counterpartyCount.toLocaleString(), 'counterparties'],
    [f.assetsTouched.toLocaleString(), 'assets touched'],
    f.dexMarkets > 0 ? [String(f.dexMarkets), 'DEX markets'] : null,
    f.ammPools > 0 ? [String(f.ammPools), `AMM pool${f.ammPools === 1 ? '' : 's'}`] : null,
    f.nftCount > 0 ? [String(f.nftCount), 'NFTs held'] : null,
    f.issuedCurrencyCount > 0 ? [String(f.issuedCurrencyCount), `issued currenc${f.issuedCurrencyCount === 1 ? 'y' : 'ies'}`] : null,
  ].filter(Boolean);

  el.innerHTML = `
    <div style="font-size:.65rem;font-weight:800;letter-spacing:.08em;color:rgba(255,255,255,.35);text-transform:uppercase;margin-bottom:8px">Account Behavior — what this account actually does</div>
    <div style="font-size:.86rem;color:rgba(255,255,255,.8);line-height:1.6;margin-bottom:12px">${escHtml(profile.story)}</div>
    <div style="display:flex;flex-direction:column;gap:4px;margin-bottom:12px">
      ${profile.behaviors.map(b => `<div style="font-size:.82rem;color:rgba(255,255,255,.7)">${b.icon} ${escHtml(b.text)}</div>`).join('')}
    </div>
    <div style="display:flex;flex-wrap:wrap;gap:14px;padding-top:10px;border-top:1px solid rgba(255,255,255,.06)">
      ${footprintItems.map(([val, label]) => `
        <div style="min-width:78px">
          <div class="mono" style="font-size:1.05rem;font-weight:800;color:var(--accent-primary,#00d4ff)">${escHtml(val)}</div>
          <div style="font-size:.62rem;color:rgba(255,255,255,.4);text-transform:uppercase;letter-spacing:.05em">${escHtml(label)}</div>
        </div>`).join('')}
    </div>
    ${_renderAccountJourney(journey)}
    ${_renderFollowTheMoneyNarrative(followTheMoney)}`;
}

/* ── Ledger Interaction Map ────────────────────────────
   "How this account uses XRPL" — a categorized activity breakdown shown
   two ways from the SAME underlying data: a clickable branch diagram (hub
   = the ledger, branches = activity categories) and a horizontal bar
   breakdown. Supports two weighting metrics — By Transaction Count and By
   XRP Value — since transaction count alone can be misleading (e.g. one
   huge DEX trade vs a thousand tiny payments). Deliberately does NOT
   attempt a blended cross-currency "economic value" number: token deltas
   in a currency other than XRP aren't converted to XRP without a price
   feed this app doesn't have for arbitrary tokens, so the Value metric is
   XRP-denominated activity only, with an explicit caveat shown rather than
   a fabricated blended total. */
const LEDGER_MAP_CATEGORIES = [
  { key: 'payments', label: 'Payments', icon: '💸', sectionId: 'fundflow', types: new Set(['Payment']) },
  { key: 'dex', label: 'DEX Trading', icon: '📊', sectionId: 'wash', types: new Set(['OfferCreate', 'OfferCancel']) },
  { key: 'amm', label: 'AMM / Liquidity', icon: '💧', sectionId: 'amm', types: new Set(['AMMDeposit', 'AMMWithdraw', 'AMMCreate', 'AMMVote', 'AMMBid']) },
  { key: 'nft', label: 'NFT Activity', icon: '🖼️', sectionId: 'nft', types: new Set(['NFTokenMint', 'NFTokenBurn', 'NFTokenCreateOffer', 'NFTokenCancelOffer', 'NFTokenAcceptOffer']) },
  { key: 'settings', label: 'Account Settings', icon: '⚙️', sectionId: 'security', types: new Set(['SetRegularKey', 'SignerListSet', 'AccountSet', 'TrustSet', 'DepositPreauth']) },
];

function buildLedgerInteractionBreakdown(txList, addr, extra = {}) {
  const buckets = new Map(LEDGER_MAP_CATEGORIES.map(c => [c.key, { count: 0, xrpValue: 0 }]));
  let otherCount = 0, otherXrpValue = 0;

  for (const { tx, meta } of txList) {
    const cat = LEDGER_MAP_CATEGORIES.find(c => c.types.has(tx.TransactionType));
    const xrpAbs = Math.abs(extractBalanceDeltas(tx, meta, addr).xrpDelta);
    if (cat) {
      const b = buckets.get(cat.key);
      b.count++;
      b.xrpValue += xrpAbs;
    } else {
      otherCount++;
      otherXrpValue += xrpAbs;
    }
  }

  const totalCount = txList.length;
  const totalXrpValue = [...buckets.values()].reduce((s, b) => s + b.xrpValue, 0) + otherXrpValue;

  const paymentCps = new Set();
  for (const { tx } of txList) {
    if (tx.TransactionType !== 'Payment') continue;
    const cp = tx.Account === addr ? tx.Destination : tx.Account;
    if (cp && cp !== addr) paymentCps.add(cp);
  }

  const subStats = {
    payments: paymentCps.size ? `${paymentCps.size} counterpart${paymentCps.size === 1 ? 'y' : 'ies'}` : null,
    dex: extra.dexMarkets > 0 ? `${extra.dexMarkets} market${extra.dexMarkets === 1 ? '' : 's'}` : null,
    amm: extra.ammPools > 0 ? `${extra.ammPools} active pool${extra.ammPools === 1 ? '' : 's'}`
      : extra.ammPoolsHistorical > 0 ? `${extra.ammPoolsHistorical} pool${extra.ammPoolsHistorical === 1 ? '' : 's'} (past)` : null,
    nft: extra.nftMintCount > 0 ? `${extra.nftMintCount} minted` : extra.nftCount > 0 ? `${extra.nftCount} held` : null,
    settings: null,
  };

  const categories = LEDGER_MAP_CATEGORIES.map(c => {
    const b = buckets.get(c.key);
    return {
      key: c.key, label: c.label, icon: c.icon, sectionId: c.sectionId,
      count: b.count, xrpValue: b.xrpValue,
      countPct: totalCount ? (b.count / totalCount) * 100 : 0,
      valuePct: totalXrpValue ? (b.xrpValue / totalXrpValue) * 100 : 0,
      subStat: subStats[c.key],
    };
  }).filter(c => c.count > 0);

  if (otherCount > 0) {
    categories.push({
      key: 'other', label: 'Other', icon: '◽', sectionId: null,
      count: otherCount, xrpValue: otherXrpValue,
      countPct: totalCount ? (otherCount / totalCount) * 100 : 0,
      valuePct: totalXrpValue ? (otherXrpValue / totalXrpValue) * 100 : 0,
      subStat: null,
    });
  }

  categories.sort((a, b) => b.countPct - a.countPct);

  return { categories, totalCount, totalXrpValue, hasXrpValue: totalXrpValue > 0 };
}

let _ledgerMapMetric = 'count';
let _lastLedgerMapBreakdown = null;

window._setLedgerMapMetric = function(metric) {
  _ledgerMapMetric = metric;
  if (_lastLedgerMapBreakdown) renderLedgerInteractionMap(_lastLedgerMapBreakdown);
};

function renderLedgerInteractionMap(breakdown) {
  const el = document.getElementById('inspect-ledger-map');
  if (!el) return;
  _lastLedgerMapBreakdown = breakdown;
  if (!breakdown.categories.length) { el.innerHTML = ''; return; }

  const byValue = _ledgerMapMetric === 'value' && breakdown.hasXrpValue;
  const pctKey = byValue ? 'valuePct' : 'countPct';
  const maxPct = Math.max(...breakdown.categories.map(c => c[pctKey]), 1);

  const branchCards = breakdown.categories.map(c => `
    <div class="ledgermap-branch" ${c.sectionId ? `onclick="_jumpToInspectorSection('${c.sectionId}')" style="cursor:pointer"` : ''}
      ${c.sectionId ? `title="Click to jump to this section"` : ''}>
      <div class="ledgermap-branch-icon">${c.icon}</div>
      <div class="ledgermap-branch-label">${escHtml(c.label)}</div>
      <div class="ledgermap-branch-pct">${c[pctKey] < 1 && c[pctKey] > 0 ? '<1' : c[pctKey].toFixed(0)}%</div>
      ${c.subStat ? `<div class="ledgermap-branch-substat">${escHtml(c.subStat)}</div>` : ''}
    </div>`).join('');

  const barRows = breakdown.categories.map(c => `
    <div class="ledgermap-bar-row">
      <span class="ledgermap-bar-label">${c.icon} ${escHtml(c.label)}</span>
      <div class="ledgermap-bar-track"><div class="ledgermap-bar-fill" style="width:${Math.max(1.5, (c[pctKey] / maxPct) * 100).toFixed(1)}%"></div></div>
      <span class="ledgermap-bar-pct mono">${c[pctKey] < 1 && c[pctKey] > 0 ? '<1' : c[pctKey].toFixed(0)}%</span>
    </div>`).join('');

  // Radial donut for the dominant category (roadmap: Inspector 2.0) — a
  // quick-glance visual anchor alongside the existing branch cards/bars,
  // reusing categories[0] (already sorted desc by the active metric) and
  // zero new computation. A single-arc donut, not a full multi-segment pie
  // — this is a "what does it mainly do" glance, not a precise breakdown
  // (the bars below already give the precise per-category numbers).
  const topCat = breakdown.categories[0];
  const topPct = Math.min(100, Math.max(0, topCat[pctKey]));
  const R = 70, CIRC = 2 * Math.PI * R;
  const donut = topCat ? `
    <div class="ledgermap-donut">
      <svg viewBox="0 0 180 180" style="width:140px;height:140px;transform:rotate(-90deg)">
        <circle cx="90" cy="90" r="${R}" fill="none" stroke="rgba(255,255,255,.06)" stroke-width="20"/>
        <circle cx="90" cy="90" r="${R}" fill="none" stroke="var(--accent,#00d4ff)" stroke-width="20"
          stroke-dasharray="${(CIRC * topPct / 100).toFixed(1)} ${CIRC.toFixed(1)}" stroke-linecap="round"/>
      </svg>
      <div class="ledgermap-donut-center">
        <div class="ledgermap-donut-pct mono">${topPct < 1 && topPct > 0 ? '<1' : topPct.toFixed(0)}%</div>
        <div class="ledgermap-donut-label">${escHtml(topCat.label)}</div>
      </div>
    </div>` : '';

  el.innerHTML = `
    <div class="ledgermap-header">
      <span class="ledgermap-title">How This Account Uses XRPL</span>
      <div class="netmap-size-toggle">
        <button type="button" class="netmap-size-btn${byValue ? '' : ' active'}" onclick="_setLedgerMapMetric('count')">By Tx Count</button>
        <button type="button" class="netmap-size-btn${byValue ? ' active' : ''}" onclick="_setLedgerMapMetric('value')" ${breakdown.hasXrpValue ? '' : 'disabled title="No XRP-denominated activity to compare"'}>By XRP Value</button>
      </div>
    </div>
    ${byValue ? '<div class="ledgermap-caveat">Value comparison uses XRP amounts only — activity with no XRP leg (e.g. trading two non-XRP tokens) isn\'t reflected in this view.</div>' : ''}
    <div class="ledgermap-top-row">
      ${donut}
      <div class="ledgermap-top-row-main">
        <div class="ledgermap-hub"><div class="ledgermap-hub-label">XRP LEDGER</div></div>
        <div class="ledgermap-branches">${branchCards}</div>
      </div>
    </div>
    <div class="ledgermap-bars">${barRows}</div>
  `;
}

/* ── AMM Positions ───────────────────────────────── */
function analyseAmmPositions(lines, txList, objects, ammInfoMap = new Map(), addr = null) {
  const signals  = [];
  const positions = [];

  // AND, not OR, and excludes zero-balance lines — see the matching fetch-
  // site fix above for why: the old OR-based, no-balance-check filter both
  // false-positived on ordinary 40-hex-char custom tokens and counted
  // closed/fully-withdrawn positions as if they were still active.
  const lpLines = lines.filter(l => l.currency && Number(l.balance) !== 0 && isLpCurrency(l.currency));

  // AMM transactions
  const ammDeposits  = txList.filter(({ tx }) => tx.TransactionType === 'AMMDeposit');
  const ammWithdraws = txList.filter(({ tx }) => tx.TransactionType === 'AMMWithdraw');
  const ammCreates   = txList.filter(({ tx }) => tx.TransactionType === 'AMMCreate');
  const ammVotes     = txList.filter(({ tx }) => tx.TransactionType === 'AMMVote');
  const ammBids      = txList.filter(({ tx }) => tx.TransactionType === 'AMMBid');

  lpLines.forEach(l => {
    const balance = Number(l.balance);
    const limit   = Number(l.limit);
    positions.push({
      currency: l.currency,
      issuer:   l.account,
      balance:  balance,
      limit:    limit,
    });
  });
  const currentCurrencies = new Set(positions.map(p => p.currency));

  // Entry-basis via the Balance Change Engine: the same AMMDeposit/
  // AMMWithdraw transaction's metadata carries both the LP-token delta and
  // the contributed/withdrawn XRP+token delta simultaneously, giving a real
  // per-event cost basis. Net-contributed approximation, not FIFO lot
  // accounting — and deliberately no impermanent-loss number, since that
  // needs historical price data for both pool legs this app doesn't have.
  //
  // This same pass also finds every LP currency this account's history
  // ever touched, not just the ones it currently holds a balance in — a
  // pool it deposited into and later fully withdrew from is a real,
  // distinct fact ("closed position") from one it never touched at all,
  // and from one it's still actively in ("current position"). All of this
  // comes from data already fetched (txList/meta), no extra RPC calls.
  const closedByCurrency = new Map(); // currency -> { depositEvents, withdrawEvents, costBasisXrp }
  if (addr) {
    for (const { tx, meta } of [...ammDeposits, ...ammWithdraws]) {
      const delta = extractBalanceDeltas(tx, meta, addr);
      for (const lpDelta of delta.lpDeltas) {
        const cur = lpDelta.currency;
        const p = positions.find(x => x.currency === cur);
        const entry = { hash: tx.hash, date: tx.date, lpTokenDelta: lpDelta.delta, xrpDelta: delta.xrpDelta, tokenDeltas: delta.tokenDeltas };
        const isDeposit = tx.TransactionType === 'AMMDeposit';
        if (p) {
          // Belongs to a currently-active position.
          p.depositEvents ??= []; p.withdrawEvents ??= []; p.costBasisXrp ??= 0;
          (isDeposit ? p.depositEvents : p.withdrawEvents).push(entry);
          p.costBasisXrp += isDeposit ? -delta.xrpDelta : delta.xrpDelta;
        } else if (!currentCurrencies.has(cur)) {
          // No current balance for this currency — a closed/fully-exited
          // position, tracked separately below.
          if (!closedByCurrency.has(cur)) closedByCurrency.set(cur, { depositEvents: [], withdrawEvents: [], netXrp: 0 });
          const c = closedByCurrency.get(cur);
          (isDeposit ? c.depositEvents : c.withdrawEvents).push(entry);
          c.netXrp += isDeposit ? -delta.xrpDelta : delta.xrpDelta;
        }
      }
    }
    for (const p of positions) {
      if (p.costBasisXrp != null) p.costBasisXrp = p.costBasisXrp > 0 ? p.costBasisXrp : null;
    }
  }

  if (positions.length) {
    signals.push({ sev: 'info', label: `${positions.length} current LP token position(s)`,
      detail: `Active liquidity provider in ${positions.length} AMM pool(s) right now.` });
    // Enrich with amm_info data if available
    for (const p of positions) {
      const ammData = ammInfoMap.get(p.currency);
      if (ammData) {
        p.tvl     = ammData.amount  ? Number(ammData.amount) / 1e6     : null;
        p.tvl2    = ammData.amount2?.value ? Number(ammData.amount2.value) : null;
        p.feeRate = ammData.trading_fee != null ? ammData.trading_fee / 1000 : null; // basis points → %
        p.lpSupply = ammData.lp_token?.value ? Number(ammData.lp_token.value) : null;
        // Ownership share: our LP balance / total LP supply
        if (p.lpSupply && p.balance) {
          const ownerPct = (Math.abs(p.balance) / p.lpSupply) * 100;
          p.ownerPct = ownerPct;
          if (ownerPct > 50) {
            // Owner impact vs. market/ecosystem impact are kept as two
            // separate statements — this size of a position is a real fact
            // about pool concentration, not evidence of intent. A pool
            // with very few LPs will mechanically produce a high
            // percentage for any one of them; this does not by itself
            // suggest anything about why the position was built.
            signals.push({ sev: 'warn',
              label: `Concentrated AMM position: ${ownerPct.toFixed(0)}% of pool`,
              detail: `Owner impact: this position represents ${ownerPct.toFixed(0)}% of this account's LP holdings in this pool. ` +
                      `Market/ecosystem impact: a full withdrawal today would remove roughly ${ownerPct.toFixed(0)}% of this pool's current total liquidity, ` +
                      `which would affect anyone trading against it at the time. This describes pool concentration, not intent — a pool with few ` +
                      `liquidity providers will mechanically produce a high percentage for any one of them.` });
          }
        }
        if (p.tvl != null) {
          signals.push({ sev: 'info',
            label: `Pool TVL: ${fmt(p.tvl, 2)} XRP${p.tvl2 ? ` + ${fmt(p.tvl2, 2)} tokens` : ''} · Fee: ${p.feeRate?.toFixed(2) ?? '?'}%`,
            detail: `Actual pool context from amm_info. Your LP position represents ${ p.ownerPct != null ? p.ownerPct.toFixed(1) + '% of the pool.' : 'an unknown share of the pool.'}` });
        }
        // Current-vs-historical composition precision: tvl/tvl2/ownerPct
        // above are always a CURRENT snapshot from amm_info. Presenting
        // them without qualification silently assumes the pool's XRP:token
        // ratio hasn't moved since this account deposited — trading flow,
        // other LPs' activity, or price movement in the non-XRP asset can
        // all violate that. Compare the pool's CURRENT ratio against the
        // ratio implied by this account's OWN two-asset deposit event(s)
        // (both sides contributed together, so the ratio is a real,
        // dimensionless fact — no price feed needed for either leg) and
        // flag it when the assumption doesn't hold, rather than letting a
        // single current-snapshot number stand in for the whole position's
        // history unqualified.
        if (p.tvl2 != null && p.depositEvents?.length) {
          // Both legs of a genuine two-asset deposit decrease the
          // depositor's own balance (tokens leave the account into the
          // pool) — same sign convention as xrpDelta above, which
          // p.costBasisXrp's existing, proven-correct calc already
          // relies on (`isDeposit ? -delta.xrpDelta : delta.xrpDelta`).
          const twoAssetDeposits = p.depositEvents.filter(e => e.xrpDelta < 0 && e.tokenDeltas?.[0]?.delta < 0);
          const depositedXrp   = twoAssetDeposits.reduce((s, e) => s - e.xrpDelta, 0);
          const depositedToken = twoAssetDeposits.reduce((s, e) => s - e.tokenDeltas[0].delta, 0);
          if (twoAssetDeposits.length && depositedToken > 0 && p.tvl2 > 0) {
            const depositRatio = depositedXrp / depositedToken;
            const currentRatio = p.tvl / p.tvl2;
            const shiftPct = Math.abs(currentRatio - depositRatio) / depositRatio * 100;
            p.compositionShiftPct = shiftPct;
            p.currentXrpSideValue = p.ownerPct != null ? p.tvl * (p.ownerPct / 100) : null;
            if (shiftPct >= 20) {
              signals.push(mkFinding({
                module: 'AMM', category: 'liquidity', sev: 'info', confidence: 0.6,
                headline: `Pool composition has shifted ~${shiftPct.toFixed(0)}% since this account's deposit`,
                detail: 'The current TVL/ownership numbers above reflect today\'s pool composition, not the composition at deposit time.',
                observed: [
                  `At deposit: ~${fmt(depositRatio, 6)} XRP per token contributed (from ${twoAssetDeposits.length} two-asset deposit event(s))`,
                  `Currently: ~${fmt(currentRatio, 6)} XRP per token in the pool`,
                ],
                alternativeExplanations: ['Normal trading flow through the pool, other LPs depositing/withdrawing in a different ratio, or price movement in the non-XRP asset can all shift pool composition without anything unusual happening'],
                classification: 'This flags that a current-snapshot number (TVL/ownership share) may not directly reflect this position\'s economics at deposit time — it is not an impermanent-loss or profit/loss calculation, which would need price data for the non-XRP leg this app doesn\'t have.',
              }));
            }
          }
        }
        // Liquidity Impact: how much of this account's OWN contributed
        // capital has it already taken back out, versus what's still
        // deployed — the account's own capital movement, not a claim
        // about the pool's history (which needs point-in-time snapshots
        // this app doesn't have).
        if (p.withdrawEvents?.length) {
          const totalWithdrawnXrp = p.withdrawEvents.reduce((s, e) => s + Math.max(0, e.xrpDelta), 0);
          const totalDepositedXrp = (p.depositEvents || []).reduce((s, e) => s + Math.max(0, -e.xrpDelta), 0);
          const pctOfOwnCapitalReturned = totalDepositedXrp > 0 ? (totalWithdrawnXrp / totalDepositedXrp) * 100 : null;
          signals.push({ sev: 'info',
            label: `Liquidity impact: ${p.withdrawEvents.length} withdrawal(s) from this position`,
            detail: `Owner impact: ${pctOfOwnCapitalReturned != null ? `approximately ${pctOfOwnCapitalReturned.toFixed(0)}% of this account's own contributed XRP has been withdrawn back out of this pool` : 'partial capital has been withdrawn from this position'}. ` +
                    `This reflects the account managing its own capital, not a claim about the pool's health.` });
        }
      }
    }
  }

  if (closedByCurrency.size) {
    const closedList = [...closedByCurrency.entries()];
    const totalClosedEvents = closedList.reduce((s, [, c]) => s + c.depositEvents.length + c.withdrawEvents.length, 0);
    signals.push({ sev: 'info', label: `${closedByCurrency.size} closed/fully-exited LP position(s)`,
      detail: `This account previously provided liquidity to ${closedByCurrency.size} pool(s) it no longer holds a balance in (${totalClosedEvents} deposit/withdraw event(s) total). ` +
              `A closed position is a distinct fact from a current one — it does not indicate anything about why the account exited.` });
  }

  if (ammCreates.length) {
    signals.push({ sev: 'info', label: `Created ${ammCreates.length} AMM pool(s)`,
      detail: 'This account bootstrapped one or more liquidity pools.' });
  }

  if (ammDeposits.length || ammWithdraws.length) {
    signals.push({ sev: 'info', label: `${ammDeposits.length} deposit(s) · ${ammWithdraws.length} withdrawal(s)`,
      detail: 'LP activity history, across both current and closed positions.' });
  }

  if (ammVotes.length) {
    signals.push({ sev: 'info', label: `${ammVotes.length} AMM fee vote(s)`,
      detail: 'This account has voted on AMM trading fee parameters.' });
  }

  if (ammBids.length) {
    signals.push({ sev: 'info', label: `${ammBids.length} continuous auction bid(s)`,
      detail: 'Bid for the AMM auction slot (reduced fee trading window).' });
  }

  // Impermanent-loss exposure, sized relative to the pool (ownerPct) where
  // that's available, rather than an absolute LP-token count — 1000 LP
  // tokens is a meaningless threshold on its own since LP token
  // denomination is pool-specific; a position that's genuinely large
  // relative to its own pool is a more honest signal of real exposure.
  const largePositions = positions.filter(p => (p.ownerPct != null ? p.ownerPct > 10 : Math.abs(p.balance) > 1000));
  if (largePositions.length) {
    signals.push({ sev: 'warn', label: 'Meaningful LP exposure — impermanent-loss risk applies to the account itself',
      detail: 'Significant liquidity positions carry exposure to price divergence between pool assets. This is a risk to the account\'s own capital, not a risk this account poses to others.' });
  }

  if (signals.length === 0) {
    signals.push({ sev: 'ok', label: 'No AMM positions', detail: 'This account is not a liquidity provider.' });
  }

  return { signals, positions, closedPositions: [...closedByCurrency.keys()], deposits: ammDeposits.length, withdrawals: ammWithdraws.length };
}

/* ── AMM Governance: Fee Voting + Auction Slot ──────────
   Correctly models two SEPARATE XRPL mechanisms that are easy to
   conflate: AMMVote is LP-weighted governance over the pool's NORMAL
   trading fee; AMMBid is a bid of LP tokens for a TEMPORARY discounted-
   fee auction slot (up to 24h), a completely different mechanism with a
   different economic purpose (arbitrage efficiency). Both are read
   directly from amm_info's `vote_slots`/`auction_slot` fields — data
   already fetched for every AMM position/pool this app looks at (via
   ammInfoMap for the inspected account's own LP positions, or
   issuerAmmPool for a confirmed issuer's paired pool) and simply never
   read until now. Zero new RPC calls. */
function analyseAmmGovernance(pool, addr) {
  if (!pool) return { applicable: false };

  const normalFeePct = (pool.trading_fee || 0) / 1000;

  // ── Fee Voting (AMMVote) — vote_weight is normalized by rippled so all
  // active votes on a pool sum to 100,000; dividing by the actual sum
  // (not a hardcoded 100000) is defensive against any partial-data edge
  // case without changing the result for the normal case.
  const voteSlots = pool.vote_slots || [];
  const totalWeight = voteSlots.reduce((s, v) => s + (v.vote_weight || 0), 0);
  const voters = voteSlots.map(v => ({
    account: v.account,
    feeVotedPct: (v.trading_fee || 0) / 1000,
    weightPct: totalWeight > 0 ? (v.vote_weight / totalWeight) * 100 : 0,
  })).sort((a, b) => b.weightPct - a.weightPct);
  const top1WeightPct = voters[0]?.weightPct || 0;
  const top3WeightPct = voters.slice(0, 3).reduce((s, v) => s + v.weightPct, 0);
  const ownVote = voters.find(v => v.account === addr) || null;

  // ── Auction Slot (AMMBid) — rippled omits `auction_slot` entirely once
  // NO BID HAS EVER BEEN MADE on the pool, so its absence here can mean
  // "no active slot" — but presence does NOT reliably mean "active."
  // Confirmed live against a real pool (SOLO/XRP): once a slot has ever
  // been won, rippled keeps serving that LAST bid's auction_slot object
  // indefinitely if nobody re-bids after it lapses — a real pool was
  // observed still reporting a slot whose `expiration` was over a year in
  // the past. Without this check, every downstream consumer of
  // `auctionSlot.applicable` (the governance finding itself, Auction-
  // Window Market, Auction Economics, AMM Control Surface) would treat a
  // long-dead slot as currently owned and currently discounted.
  const slot = pool.auction_slot || null;
  const slotExpirationMs = slot?.expiration ? Date.parse(slot.expiration) : NaN;
  const slotIsCurrentlyActive = slot != null && !Number.isNaN(slotExpirationMs) && slotExpirationMs > Date.now();
  let auctionSlot = { applicable: false };
  if (slotIsCurrentlyActive) {
    const discountedFeePct = (slot.discounted_fee ?? 0) / 1000;
    const feeReductionPct = normalFeePct > 0 ? ((normalFeePct - discountedFeePct) / normalFeePct) * 100 : null;
    const authAccounts = (slot.auth_accounts || []).map(a => a.account);
    auctionSlot = {
      applicable: true,
      slotOwner: slot.account,
      authAccounts,
      isOwner: slot.account === addr,
      isAuthorized: authAccounts.includes(addr),
      normalFeePct, discountedFeePct, feeReductionPct,
      lpTokensPaid: slot.price?.value != null ? Number(slot.price.value) : null,
      expiration: slot.expiration || null,
      timeIntervalPct: slot.time_interval ?? null,
    };
  }

  return { applicable: true, normalFeePct, voting: { voters, voterCount: voters.length, top1WeightPct, top3WeightPct, ownVote }, auctionSlot };
}

/** Descriptive findings only — fee-vote concentration and auction-slot
 *  ownership/authorization are legitimate, verified protocol mechanisms,
 *  never framed as risk. See spec: "Interpretation: Fee governance is
 *  concentrated. NOT: Manipulation detected." */
function buildAmmGovernanceFindings(gov, addr, currencyLabel) {
  if (!gov.applicable) return [];
  const findings = [];
  const v = gov.voting;
  if (v.voterCount >= 2 && v.top1WeightPct > 50) {
    findings.push(mkFinding({
      module: 'AMM Fee Governance', category: 'liquidity', sev: 'info', confidence: 0.7,
      headline: `Fee governance for ${currencyLabel}/XRP is concentrated — top voter holds ${v.top1WeightPct.toFixed(0)}% of vote weight`,
      detail: 'AMM fee-vote weight is proportional to LP token ownership — a large liquidity provider naturally carries large voting influence over the pool\'s normal trading fee.',
      observed: [
        `${v.voterCount} active fee vote(s) currently on this pool`,
        `Top voter weight: ${v.top1WeightPct.toFixed(1)}%`,
        `Top 3 voter weight: ${v.top3WeightPct.toFixed(1)}%`,
      ],
      alternativeExplanations: ['A single dominant LP is common for smaller or newer pools and is normal AMM governance, not evidence of manipulation'],
      classification: 'This describes fee-governance concentration, not manipulation — AMMVote is a legitimate, LP-weighted governance mechanism built into the AMM protocol itself.',
    }));
  }
  const a = gov.auctionSlot;
  if (a.applicable && (a.isOwner || a.isAuthorized)) {
    findings.push(mkFinding({
      module: 'AMM Auction Slot', category: 'liquidity', sev: 'info', confidence: 0.9,
      headline: a.isOwner
        ? `This account currently holds the ${currencyLabel}/XRP auction slot (${a.discountedFeePct.toFixed(3)}% fee vs. ${a.normalFeePct.toFixed(3)}% normal)`
        : `This account is authorized to use another account's ${currencyLabel}/XRP auction slot`,
      detail: 'The AMM auction slot is a separate mechanism from fee voting: a bidder pays LP tokens for a temporary discounted trading fee (up to 24h) and may authorize other accounts to also trade at that discounted fee.',
      observed: [
        `Slot owner: ${shortAddr(a.slotOwner)}`,
        `${a.authAccounts.length} account(s) authorized to use the discounted fee`,
        a.feeReductionPct != null ? `Fee reduction: ${a.feeReductionPct.toFixed(0)}%` : null,
      ].filter(Boolean),
      alternativeExplanations: ['Winning the auction slot is commonly used by arbitrageurs and market makers to trade more efficiently — it does not by itself indicate coordinated or wash-like activity'],
      classification: 'Auction-slot ownership and authorization are verified on-ledger protocol relationships, not evidence of common ownership, coordination, or manipulation by themselves.',
    }));
  }
  return findings;
}

/* ── AMM Auction Bid History ────────────────────────────
   The CURRENT auction-slot state (analyseAmmGovernance, above) only shows
   who holds the slot right now — it says nothing about how this account
   itself has used the mechanism over time. This reconstructs that
   directly from the account's own already-fetched AMMBid transactions:
   zero new RPC calls. LP tokens actually spent are read from the bid
   transaction's own real balance delta (extractBalanceDeltas' lpDeltas),
   not from a field that has to be guessed — the same "trust the ledger
   delta over an assumption" principle the IOC/FOK fill fix relied on. */
function analyseAmmBidHistory(txList, addr) {
  const bids = [];
  for (const { tx, meta } of txList) {
    if (tx.TransactionType !== 'AMMBid' || tx.Account !== addr) continue;
    if (meta?.TransactionResult !== 'tesSUCCESS') continue;
    const delta = extractBalanceDeltas(tx, meta, addr);
    const lpSpent = delta.lpDeltas.reduce((s, d) => s + (d.delta < 0 ? -d.delta : 0), 0);
    const authAccounts = (tx.AuthAccounts || []).map(a => a.AuthAccount?.Account).filter(Boolean);
    bids.push({
      hash: tx.hash, date: tx.date,
      assetCurrency: typeof tx.Asset === 'object' ? tx.Asset.currency : 'XRP',
      asset2Currency: typeof tx.Asset2 === 'object' ? tx.Asset2.currency : 'XRP',
      lpTokensBid: lpSpent > 0 ? lpSpent : null,
      bidMin: tx.BidMin != null ? amtNum(tx.BidMin) : null,
      bidMax: tx.BidMax != null ? amtNum(tx.BidMax) : null,
      authAccounts,
    });
  }
  bids.sort((a, b) => (b.date ?? 0) - (a.date ?? 0));

  const findings = [];
  if (bids.length > 0) {
    const totalLpSpent = bids.reduce((s, b) => s + (b.lpTokensBid || 0), 0);
    const distinctAuthed = new Set(bids.flatMap(b => b.authAccounts));
    findings.push(mkFinding({
      module: 'AMM Auction Slot', category: 'liquidity', sev: 'info', confidence: 0.85,
      headline: `This account has placed ${bids.length} AMM auction bid${bids.length === 1 ? '' : 's'} in its fetched history`,
      detail: 'AMMBid pays LP tokens for a temporary discounted trading fee on a pool — this is the account\'s own bidding history, reconstructed from its own transactions, not a claim about every bid ever placed on any pool.',
      observed: [
        totalLpSpent > 0 ? `${fmt(totalLpSpent, 4)} LP token(s) spent across all bids (real balance delta, not a fabricated estimate)` : null,
        distinctAuthed.size ? `${distinctAuthed.size} distinct account(s) authorized across these bids` : 'No additional accounts authorized in these bids',
      ].filter(Boolean),
      alternativeExplanations: ['Bidding for the auction slot is a normal, intentional use of a protocol feature primarily aimed at making arbitrage more fee-efficient'],
      classification: 'A bidding history describes protocol usage, not intent — see Execution Routing and Wash Execution for whether the resulting discounted-fee trading shows any wash-like pattern.',
    }));
  }

  return { applicable: bids.length > 0, bids, bidCount: bids.length, findings };
}

function _parseIsoToRippleSec(iso) {
  if (!iso) return null;
  const ms = Date.parse(iso);
  if (Number.isNaN(ms)) return null;
  return Math.floor(ms / 1000) - XRPL_EPOCH;
}

/* ── Auction-Window Market Analysis ─────────────────────
   Answers §11-14/§46 of the auction spec: how much of a pool's REAL
   trading volume, during the current auction slot, came from the slot
   owner, the accounts they authorized, or genuinely external
   participants — split by CLOB/AMM/HYBRID route. Built from a bounded,
   targeted fetch of the POOL's own account_tx (see the fetch site for
   why that reliably contains every execution against it), classified
   into before/during/after the slot window using the slot's real
   expiration timestamp and XRPL's fixed 24h slot duration.
   Deliberately does NOT claim to know anything before the fetched
   window's boundary — `dataCompleteness` reflects that honestly rather
   than presenting a truncated "before" bucket as the pool's full history. */
function analyseAuctionWindowMarket(poolTxData, poolAccount, auctionSlot) {
  if (!auctionSlot?.applicable || !poolTxData?.txList?.length) return { applicable: false, findings: [] };
  const expiration = _parseIsoToRippleSec(auctionSlot.expiration);
  if (expiration == null) return { applicable: false, findings: [] };
  const slotStart = expiration - 24 * 3600; // XRPL auction slots run a fixed max 24h from when won

  const authSet = new Set(auctionSlot.authAccounts);
  const buckets = { before: [], during: [], after: [] };

  for (const { tx, meta } of poolTxData.txList) {
    if (meta?.TransactionResult !== 'tesSUCCESS') continue;
    if (tx.TransactionType !== 'OfferCreate' && tx.TransactionType !== 'Payment') continue;
    if (tx.date == null) continue;
    const delta = extractBalanceDeltas(tx, meta, poolAccount);
    if (delta.xrpDelta === 0 && !delta.tokenDeltas.length) continue; // no real economic effect on the pool itself
    const period = tx.date < slotStart ? 'before' : tx.date <= expiration ? 'during' : 'after';
    const touchesAmm = _txTouchesAmm(meta);
    const touchesOffer = _txTouchesOfferNode(meta);
    const route = _classifyExecutionRoute(touchesAmm, touchesOffer);
    const counterparty = tx.Account;
    const group = counterparty === auctionSlot.slotOwner ? 'owner' : authSet.has(counterparty) ? 'authorized' : 'external';
    buckets[period].push({ hash: tx.hash, date: tx.date, xrpVolume: Math.abs(delta.xrpDelta), route, group });
  }

  const summarize = (arr) => {
    const totalXrp = arr.reduce((s, e) => s + e.xrpVolume, 0);
    const byGroup = { owner: 0, authorized: 0, external: 0 };
    for (const e of arr) byGroup[e.group] += e.xrpVolume;
    const byRoute = { CLOB: 0, AMM: 0, HYBRID: 0, UNKNOWN: 0 };
    for (const e of arr) byRoute[e.route]++;
    return {
      count: arr.length, totalXrpVolume: totalXrp,
      ownerPct: totalXrp ? (byGroup.owner / totalXrp) * 100 : 0,
      authorizedPct: totalXrp ? (byGroup.authorized / totalXrp) * 100 : 0,
      externalPct: totalXrp ? (byGroup.external / totalXrp) * 100 : 0,
      clobCount: byRoute.CLOB, ammCount: byRoute.AMM, hybridCount: byRoute.HYBRID,
    };
  };

  const during = summarize(buckets.during);
  const findings = [];
  if (during.count > 0) {
    const authGroupPct = during.ownerPct + during.authorizedPct;
    findings.push(mkFinding({
      module: 'AMM Auction Window', category: 'market-integrity', sev: 'info', confidence: poolTxData.truncated ? 0.5 : 0.75,
      headline: `During the current auction window, the slot owner + authorized accounts represent ${authGroupPct.toFixed(0)}% of this pool's real trading volume`,
      detail: `${during.count} settled trade(s) against this pool during the current ~24h auction window: ${during.ammCount} AMM, ${during.clobCount} CLOB, ${during.hybridCount} hybrid.`,
      observed: [
        `Slot owner: ${during.ownerPct.toFixed(0)}% of volume`,
        `Authorized accounts: ${during.authorizedPct.toFixed(0)}% of volume`,
        `External participants: ${during.externalPct.toFixed(0)}% of volume`,
        buckets.before.length ? `${summarize(buckets.before).count} trade(s) found in the fetched pre-slot window for comparison` : 'No pre-slot trades found in the fetched window',
        poolTxData.truncated ? 'Pool transaction history fetch was capped — this may not cover the pool\'s complete trading activity' : 'Based on the pool\'s available fetched transaction history',
      ],
      alternativeExplanations: [
        'A high auction-group share is consistent with legitimate arbitrage — the auction slot exists specifically to make arbitrage more fee-efficient',
        'Genuine two-sided market-making by the slot owner, which naturally generates high self-attributed volume without implying wash trading',
      ],
      classification: 'This describes WHO traded during the window, not WHY — see Wash Execution and Execution Routing for whether this specific activity shows genuine position change (consistent with arbitrage/market-making) or position-neutral round-tripping (a wash-like pattern).',
    }));
  }

  return {
    applicable: true, slotStart, expiration,
    before: summarize(buckets.before), during, after: summarize(buckets.after),
    dataCompleteness: poolTxData.truncated ? 'possibly-truncated' : 'complete',
    findings,
  };
}

/* ── Auction Dominance (Outbid Events) ──────────────────
   Reconstructs the actual sequence of who has WON the pool's auction
   slot over time — not just the current owner — from every successful
   AMMBid transaction found in the pool's own fetched tx history. A
   successful AMMBid immediately takes the slot over from whoever held it
   before (refunding them pro-rata), so consecutive bids in the pool's own
   history directly reconstruct the real outbid sequence: who won, when,
   and for how long, before the next bid displaced them. Reuses the same
   bounded pool-tx fetch already gathered for Auction-Window Market
   Analysis — zero additional RPC calls. */
function analyseAuctionDominance(poolTxData) {
  if (!poolTxData?.txList?.length) return { applicable: false, findings: [] };

  const bids = [];
  for (const { tx, meta } of poolTxData.txList) {
    if (tx.TransactionType !== 'AMMBid' || meta?.TransactionResult !== 'tesSUCCESS') continue;
    const delta = extractBalanceDeltas(tx, meta, tx.Account);
    const lpSpent = delta.lpDeltas.reduce((s, d) => s + (d.delta < 0 ? -d.delta : 0), 0);
    bids.push({ account: tx.Account, date: tx.date, hash: tx.hash, lpTokensBid: lpSpent > 0 ? lpSpent : null });
  }
  bids.sort((a, b) => (a.date ?? 0) - (b.date ?? 0));
  // Each successful bid immediately displaces the previous owner — the
  // prior entry's ownership period ends exactly when the next bid wins.
  const periods = bids.map((b, i) => ({ ...b, periodEnd: bids[i + 1]?.date ?? null }));

  const winsByAccount = new Map();
  for (const p of periods) {
    if (!winsByAccount.has(p.account)) winsByAccount.set(p.account, { account: p.account, winCount: 0, totalLpBid: 0 });
    const entry = winsByAccount.get(p.account);
    entry.winCount++;
    entry.totalLpBid += p.lpTokensBid || 0;
  }
  const ranked = [...winsByAccount.values()].sort((a, b) => b.winCount - a.winCount);
  const totalWins = periods.length;
  const topWinnerSharePct = ranked[0] && totalWins ? (ranked[0].winCount / totalWins) * 100 : 0;
  const dataCompleteness = poolTxData.truncated ? 'possibly-truncated' : 'complete';

  const findings = [];
  if (totalWins >= 3) {
    findings.push(mkFinding({
      module: 'AMM Auction Dominance', category: 'liquidity', sev: 'info', confidence: dataCompleteness === 'complete' ? 0.75 : 0.5,
      headline: `${shortAddr(ranked[0].account)} has won ${ranked[0].winCount} of ${totalWins} auction slot(s) seen in the pool's fetched history (${topWinnerSharePct.toFixed(0)}%)`,
      detail: 'Reconstructed from every successful AMMBid transaction found in the pool\'s own fetched transaction history — each one immediately takes over the auction slot from whoever held it before.',
      observed: [
        `${totalWins} successful AMMBid transaction(s) found`,
        `${winsByAccount.size} distinct account(s) have won this slot`,
        dataCompleteness === 'complete' ? 'Based on the pool\'s available fetched transaction history' : 'Pool transaction history fetch was capped — earlier auction activity may exist outside this window',
      ],
      alternativeExplanations: ['A dominant bidder is often a dedicated arbitrageur or market maker whose strategy depends on continuously holding the discounted-fee slot — a normal, intended use of the mechanism, not evidence of manipulation'],
      classification: 'Describes market structural influence — who controls the discounted-fee slot most often — not manipulation. See Auction-Window Market Analysis for what actually happened during their ownership periods.',
    }));
  }

  return { applicable: true, bids: periods, winsByAccount: ranked, totalWins, topWinnerSharePct, dataCompleteness, findings };
}

/* ── Auction Economics ───────────────────────────────────
   The discounted fee is not free — the slot owner paid real LP tokens to
   win it (already known from amm_info's auction_slot.price, no extra
   fetch). This compares that real cost against fee savings ESTIMATED
   from the account's own observed trading volume during the current
   window (from Auction-Window Market Analysis, when available) —
   deliberately never presented as exact profit: this app has no reliable
   price feed to convert LP tokens or a non-XRP pool asset into a common
   unit, so only real, already-known quantities are ever combined. */
function analyseAuctionEconomics(gov, auctionWindow) {
  const a = gov.auctionSlot;
  if (!a?.applicable || !a.isOwner) return { applicable: false, findings: [] };

  const bidCostLp = a.lpTokensPaid;
  let ownerVolumeDuring = null, estimatedFeeSavingsXrp = null;
  if (auctionWindow?.applicable && auctionWindow.during.count > 0) {
    ownerVolumeDuring = auctionWindow.during.totalXrpVolume * (auctionWindow.during.ownerPct / 100);
    estimatedFeeSavingsXrp = ownerVolumeDuring * ((a.normalFeePct - a.discountedFeePct) / 100);
  }

  const findings = [];
  if (estimatedFeeSavingsXrp != null) {
    findings.push(mkFinding({
      module: 'AMM Auction Economics', category: 'liquidity', sev: 'info', confidence: 0.55,
      headline: `Estimated ${fmt(estimatedFeeSavingsXrp, 2)} XRP in trading-fee savings so far this window${bidCostLp != null ? `, against a bid cost of ${fmt(bidCostLp, 4)} LP token(s)` : ''}`,
      detail: 'The auction slot is not a free discount — the owner paid LP tokens to win it. This compares that real cost against fee savings estimated purely from this account\'s own observed trading volume during the current window.',
      observed: [
        bidCostLp != null ? `${fmt(bidCostLp, 4)} LP token(s) paid to win the current slot` : null,
        `Normal fee: ${a.normalFeePct.toFixed(3)}% · Discounted fee: ${a.discountedFeePct.toFixed(3)}%`,
        `${fmt(ownerVolumeDuring, 2)} XRP of this account's own volume observed during the current window`,
      ].filter(Boolean),
      alternativeExplanations: ['LP tokens are not spent or lost — they remain a claim on pool assets, so the real "cost" is more precisely opportunity cost (foregone LP yield/voting weight) and the risk of being outbid before recouping it, not a cash expense'],
      classification: 'A directional cost/benefit comparison using only real, already-known quantities (LP tokens paid, fee percentages, observed XRP volume) — not a profit calculation. This app has no reliable price feed to convert LP tokens or the pool\'s non-XRP asset into a common unit.',
    }));
  }

  return { applicable: true, bidCostLp, ownerVolumeDuring, estimatedFeeSavingsXrp, findings };
}

/* ── AMM Control Surface (Concentration of AMM Influence) ────
   Combines four dimensions already computed elsewhere — LP ownership
   (Holder Cohorts), fee-vote weight (AMM Governance), auction-slot win
   share (Auction Dominance), and trading-volume share (LP/Trader
   Overlap) — into ONE view per account, with zero new data fetching.
   These dimensions are naturally correlated (a large LP position drives
   voting weight, often funds auction bids, and frequently correlates
   with trading activity for a dedicated market maker), so showing them
   together is genuinely informative, but per spec is deliberately NEVER
   labeled "control of the AMM" — only "concentration of influence,"
   since correlation across these dimensions doesn't by itself establish
   control or coordination. */
function analyseAmmControlSurface(gov, holderCohorts, auctionDominance, lpTraderOverlap) {
  if (!gov?.applicable) return { applicable: false, findings: [] };

  const profiles = new Map();
  const ensure = (acct) => {
    if (!profiles.has(acct)) profiles.set(acct, { account: acct, lpSharePct: 0, feeVoteWeightPct: 0, auctionWinSharePct: 0, volumeSharePct: 0 });
    return profiles.get(acct);
  };

  for (const v of gov.voting?.voters || []) ensure(v.account).feeVoteWeightPct = v.weightPct;
  for (const h of holderCohorts?.lpHolders || []) ensure(h.addr).lpSharePct = h.sharePct;
  if (auctionDominance?.applicable && auctionDominance.totalWins) {
    for (const w of auctionDominance.winsByAccount) ensure(w.account).auctionWinSharePct = (w.winCount / auctionDominance.totalWins) * 100;
  }
  if (lpTraderOverlap?.applicable && lpTraderOverlap.volumeByHolder) {
    const totalVolume = Object.values(lpTraderOverlap.volumeByHolder).reduce((s, v) => s + v, 0);
    if (totalVolume > 0) {
      for (const [acct, vol] of Object.entries(lpTraderOverlap.volumeByHolder)) ensure(acct).volumeSharePct = (vol / totalVolume) * 100;
    }
  }

  // Ranking-only average across whichever dimensions actually have real
  // data for that account — never shown as a single "score," only used
  // to sort. Requires signal in at least 2 independent dimensions to
  // even appear: a single-dimension entry (e.g. just an LP holder with
  // no vote/auction/trading activity) isn't a "control surface" finding.
  const profileList = [...profiles.values()]
    .map(p => {
      const dims = [p.lpSharePct, p.feeVoteWeightPct, p.auctionWinSharePct, p.volumeSharePct].filter(v => v > 0);
      return { ...p, dimensionsPresent: dims.length, avgInfluence: dims.length ? dims.reduce((a, b) => a + b, 0) / dims.length : 0 };
    })
    .filter(p => p.dimensionsPresent >= 2)
    .sort((a, b) => b.avgInfluence - a.avgInfluence);

  const findings = [];
  const top = profileList[0];
  if (top && top.dimensionsPresent >= 3) {
    findings.push(mkFinding({
      module: 'AMM Control Surface', category: 'liquidity', sev: 'info', confidence: 0.5,
      headline: `${shortAddr(top.account)} shows concentrated AMM influence across ${top.dimensionsPresent} of 4 dimensions (LP ownership, fee voting, auction wins, trading volume)`,
      detail: 'Combines LP ownership, fee-vote weight, auction-slot win share, and trading-volume share into one view — these dimensions are naturally correlated for a dedicated liquidity provider, not independent evidence of coordination.',
      observed: [
        top.lpSharePct > 0 ? `LP ownership: ${top.lpSharePct.toFixed(1)}%` : null,
        top.feeVoteWeightPct > 0 ? `Fee vote weight: ${top.feeVoteWeightPct.toFixed(1)}%` : null,
        top.auctionWinSharePct > 0 ? `Auction win share: ${top.auctionWinSharePct.toFixed(0)}%` : null,
        top.volumeSharePct > 0 ? `Trading volume share: ${top.volumeSharePct.toFixed(1)}%` : null,
      ].filter(Boolean),
      alternativeExplanations: ['A large, active liquidity provider naturally shows up across all of these dimensions at once — this is the expected shape of a dedicated market maker or project-affiliated LP, not evidence of coordination or manipulation'],
      classification: 'Describes concentration of AMM influence across governance/liquidity/auction/trading dimensions — deliberately NOT "control of the AMM," since that conclusion is not established by this data alone.',
    }));
  }

  return { applicable: true, profiles: profileList, findings };
}

/* ── Fee Spike Detection ────────────────────────────────────────────────────
   Detects elevated fees that often accompany coordinated manipulation events.
   When bots pay 10-100x the base fee to ensure same-ledger execution, a
   distinct spike pattern emerges that organic wallets rarely produce.
────────────────────────────────────────────────────────────────────────── */
function analyseFeeSpikePattern(txList) {
  const signals = [];
  const BASE_FEE_DROPS = 12;
  const feeTxs = txList.filter(({tx}) => tx.Fee && Number(tx.Fee) > 0);

  if (feeTxs.length < 10) {
    return { signals: [], verdict: 'insufficient', riskPenalty: 0,
             avgFeeMultiplier: null, spikeCount: 0, topFeeHashes: [] };
  }

  const multipliers = feeTxs.map(({tx}) => Number(tx.Fee) / BASE_FEE_DROPS);
  const avgMult = multipliers.reduce((a,b) => a+b, 0) / multipliers.length;
  const highFeeTxs = feeTxs.filter(({tx}) => Number(tx.Fee) / BASE_FEE_DROPS > 100);
  const spikeCount = highFeeTxs.length;
  const spikeRate  = spikeCount / feeTxs.length;

  let riskPenalty = 0;
  let verdict = 'normal';

  // Collect top-3 high-fee hashes for the report
  const topFeeHashes = [...feeTxs]
    .sort((a,b) => Number(b.tx.Fee) - Number(a.tx.Fee))
    .slice(0, 5)
    .map(({tx}) => ({ hash: tx.hash, mult: (Number(tx.Fee) / BASE_FEE_DROPS).toFixed(0), fee: Number(tx.Fee), date: tx.date }));

  if (spikeRate > 0.15 && spikeCount >= 5) {
    riskPenalty = 10;
    verdict = 'elevated';
    signals.push({ sev: 'warn',
      label: `Fee spike pattern: ${spikeCount} txs paid >100x base fee (${(spikeRate*100).toFixed(0)}% of history)`,
      detail: `Average fee multiplier: ${avgMult.toFixed(0)}x. In XRPL, bots often pay elevated fees to guarantee ` +
              `same-ledger execution as a counterparty — a technique used in coordinated wash trading and sandwich attacks. ` +
              `Organic users rarely pay more than 2–5x the base fee. Top hashes: ${topFeeHashes.slice(0,3).map(h => shortAddr(h.hash)).join(', ')}.`,
      hashes: topFeeHashes.map(h => h.hash),
    });
  } else if (avgMult > 20) {
    riskPenalty = 4;
    signals.push({ sev: 'info',
      label: `Elevated average fee (${avgMult.toFixed(0)}x base fee)`,
      detail: `This wallet consistently pays above-average fees. Could indicate priority execution requirements or automated trading.` });
  } else {
    signals.push({ sev: 'ok',
      label: `Fee levels normal (avg ${avgMult.toFixed(1)}x base fee)`,
      detail: `Transaction fees are within typical organic ranges.` });
  }

  return { signals, verdict, riskPenalty, avgFeeMultiplier: +avgMult.toFixed(2), spikeCount, topFeeHashes };
}

/* ── Destination Tag Analysis ───────────────────────────────────────────────
   DestinationTag identifies the recipient sub-account at an exchange or service.
   The same tag repeating across many payments = one account being funded repeatedly.
   Wildly diverse tags to one exchange = a service (or wash ring) using many accounts.
   This is computed entirely from existing txList — no new API calls needed.
────────────────────────────────────────────────────────────────────────── */
function analyseDestTagPatterns(txList, addr) {
  const signals   = [];
  const tagsByDest = new Map(); // dest → Set of tags used

  for (const { tx } of txList) {
    if (tx.TransactionType !== 'Payment') continue;
    if (tx.Account !== addr) continue;  // outbound only
    const dest = tx.Destination;
    const tag  = tx.DestinationTag;
    if (!dest) continue;
    if (!tagsByDest.has(dest)) tagsByDest.set(dest, new Set());
    if (tag != null) tagsByDest.get(dest).add(tag);
  }

  const exchangeDests = [...tagsByDest.entries()].filter(([d]) => {
    const ent = getEntity(d);
    return ent?.type === 'exchange';
  });

  // Service-Behavior Analysis: destination-tag usage is mainly useful for
  // identifying exchange/custodial service patterns — NOT as a general
  // trust signal for ordinary wallets, which have no reason to use tags at
  // all. Every check below is gated to known exchanges, or to an unlabeled
  // destination whose OWN tag-usage shape looks custodial (many distinct
  // tags across many payments) — never a bare "no tag" flag on an
  // ordinary-looking destination.
  const totalOutbound = txList.filter(({ tx }) => tx.TransactionType === 'Payment' && tx.Account === addr && tx.Destination).length;
  const totalTagged = txList.filter(({ tx }) => tx.TransactionType === 'Payment' && tx.Account === addr && tx.Destination && tx.DestinationTag != null).length;
  const tagUsagePct = totalOutbound > 0 ? totalTagged / totalOutbound * 100 : null;

  let riskPenalty = 0;
  const tagProfiles = [];

  for (const [dest, tags] of tagsByDest.entries()) {
    const ent  = getEntity(dest);
    const name = ent?.name || shortAddr(dest);
    const uniqueTags = tags.size;
    const txCount = txList.filter(({tx}) => tx.Account === addr && tx.Destination === dest).length;
    // Custodial-shaped even without a name in the known-entity registry:
    // many distinct tags across many payments is the signature of a
    // service routing to per-customer sub-accounts, whoever it is.
    const looksCustodial = !ent && uniqueTags >= 8 && txCount >= 10;

    tagProfiles.push({ dest, name, uniqueTags, txCount, looksCustodial, tags: [...tags].slice(0, 10) });

    // Single tag used many times = probably the same person's exchange account
    if (uniqueTags === 1 && txCount >= 5 && ent?.type === 'exchange') {
      signals.push({ sev: 'info',
        label: `${name}: ${txCount} payments all using tag ${[...tags][0]}`,
        detail: `Single destination tag used across all ${txCount} payments to ${name}. ` +
                `This is the normal pattern for one person funding their own exchange account.` });
    }
    // Many different tags = possibly funding many different accounts
    else if (uniqueTags > 10 && ent?.type === 'exchange') {
      riskPenalty = Math.max(riskPenalty, 8);
      signals.push({ sev: 'warn',
        label: `${name}: ${uniqueTags} different destination tags used`,
        detail: `${txCount} payments to ${name} used ${uniqueTags} different tags — ` +
                `each tag typically identifies a different customer account. Funding many exchange ` +
                `sub-accounts can indicate either a service (legitimate) or coordinated deposit layering ` +
                `where funds are spread across many exchange wallets to avoid detection.` });
    }
    // Zero tags to exchange = may not reach intended recipient
    else if (uniqueTags === 0 && txCount >= 2 && ent?.type === 'exchange') {
      signals.push({ sev: 'warn',
        label: `${name}: ${txCount} payments with no destination tag`,
        detail: `Payments to exchange addresses without a destination tag may not be credited. ` +
                `Most exchanges require a tag to identify which customer account receives the funds.` });
    }
    else if (looksCustodial) {
      signals.push(mkFinding({
        module: 'Destination Tags', category: 'counterparty', sev: 'info', confidence: 0.4,
        headline: `${shortAddr(dest)}: unlabeled destination behaves like a custodial service (${uniqueTags} distinct tags, ${txCount} payments)`,
        detail: 'Not in the known-entity registry, but its tag-usage pattern matches an exchange/custodial routing scheme.',
        observed: [`${uniqueTags} distinct destination tags across ${txCount} payments`, 'Pattern matches per-customer sub-account routing, whoever operates it'],
        alternativeExplanations: ['An exchange or custodial service not yet in this app\'s known-entity registry', 'A payment processor or merchant service using tags as invoice/order references'],
        classification: 'Behavioral inference from tag-usage shape only — not a confirmed entity identification.',
      }));
    }
  }

  if (tagUsagePct != null && totalOutbound >= 10) {
    signals.push({ sev: 'ok',
      label: `Destination Tag usage: ${tagUsagePct.toFixed(0)}% of outbound payments (${totalTagged}/${totalOutbound})`,
      detail: 'Overall tag-usage rate across all outbound payments — context for the per-destination findings above, not a signal on its own.' });
  }

  if (signals.length === 0 && tagsByDest.size > 0) {
    signals.push({ sev: 'ok',
      label: 'Destination tag patterns normal',
      detail: `Payment routing tags are consistent with regular outbound payments.` });
  } else if (tagsByDest.size === 0) {
    signals.push({ sev: 'info',
      label: 'No outbound payments to analyse for destination tags',
      detail: 'No outbound Payment transactions found in history.' });
  }

  return { signals, riskPenalty, tagProfiles };
}

/* ── Path Payment Depth Analysis ────────────────────────────────────────────
   Deep analysis of path payments: suspicious patterns include:
   - XRP→IOU→XRP round-trips (circular routing for wash volume)
   - Hops through obscure/illiquid issuers (obfuscation)
   - Same source and destination after multi-hop path (value round-trip)
   This uses tx.Paths already in txList — no new API calls.
────────────────────────────────────────────────────────────────────────── */
function analysePathPaymentDepth(txList, addr) {
  const signals = [];
  const pathPayments = txList.filter(({tx}) =>
    tx.TransactionType === 'Payment' && tx.Account === addr &&
    (Array.isArray(tx.Paths) && tx.Paths.length > 0 || tx.SendMax != null)
  );

  if (pathPayments.length === 0) {
    return { signals: [], riskPenalty: 0, roundTripCount: 0, deepHopCount: 0, selfRoutedCount: 0, noData: true };
  }

  // Show what we found even with small counts — just caveat statistical power
  const lowSampleNote = pathPayments.length < 5 ? ` (small sample: ${pathPayments.length} path payments found — patterns may not be statistically significant)` : '';

  // Detect XRP→IOU→XRP round-trips (SendMax in XRP drops, Amount in XRP drops)
  // — a real round trip requires the payment to come BACK to this account,
  // i.e. Destination === addr. Without that check, an ordinary payment to a
  // DIFFERENT recipient — one where SendMax happens to be set (a common
  // defensive default some wallets attach even for plain XRP payments) and
  // the path-finder routed through an IOU order book for best execution —
  // would be labeled "the classic cross-currency wash-trading arb pattern"
  // even though funds went to someone else entirely and nothing round-
  // tripped back to the sender.
  const xrpRoundTrips = pathPayments.filter(({tx}) => {
    const amtIsXrp    = typeof tx.Amount  === 'string';
    const smaxIsXrp   = typeof tx.SendMax === 'string';
    return amtIsXrp && smaxIsXrp && tx.Destination === addr;  // paying XRP to RECEIVE XRP = routing through IOU pairs
  });

  // Detect hops ≥ 3 (deep chains often used to obscure fund origin)
  const deepHops = pathPayments.filter(({tx}) => {
    if (!Array.isArray(tx.Paths)) return false;
    return tx.Paths.some(path => Array.isArray(path) && path.length >= 3);
  });

  // Detect self-routing (dest === source, fund goes out and comes back)
  const selfRouted = pathPayments.filter(({tx}) =>
    tx.Destination === addr
  );

  // XRPL has no dedicated "swap" transaction type — an in-wallet currency
  // conversion feature ("convert my token A to XRP/token B") is natively
  // implemented as exactly this shape: pay yourself in the target currency,
  // sourcing from the origin currency via SendMax, routed through the DEX.
  // That's mechanically identical to a deliberate wash-trading self-route,
  // but the underlying intent is opposite — the distinguishing signal is
  // pair diversity: repeatedly self-routing the SAME currency pair inflates
  // that pair's apparent activity (suspicious); self-routing many DIFFERENT,
  // unrelated pairs is the signature of ordinary portfolio swaps.
  const pairKeyOf = ({ tx }) => {
    const a = typeof tx.Amount === 'string' ? 'XRP' : (tx.Amount?.currency || '?');
    const b = typeof tx.SendMax === 'string' ? 'XRP' : (tx.SendMax?.currency || '?');
    return [a, b].sort().join('/');
  };
  const selfRoutePairCounts = new Map();
  for (const t of selfRouted) { const k = pairKeyOf(t); selfRoutePairCounts.set(k, (selfRoutePairCounts.get(k) || 0) + 1); }
  const distinctSelfRoutePairs = selfRoutePairCounts.size;
  const maxPairCount = selfRoutePairCounts.size ? Math.max(...selfRoutePairCounts.values()) : 0;
  const dominantPairShare = selfRouted.length ? maxPairCount / selfRouted.length : 0;
  // Diverse pairs, no single one dominating => consistent with swap/convert
  // usage across a varied portfolio, not repeated manipulation of one pair.
  const looksLikeDiverseSwaps = distinctSelfRoutePairs >= 3 && dominantPairShare < 0.5;

  let riskPenalty = 0;

  if (xrpRoundTrips.length >= 1) {  // flag even 1 confirmed round-trip
    riskPenalty += 12;
    signals.push({ sev: 'warn',
      label: `${xrpRoundTrips.length} XRP→IOU→XRP round-trip path payments`,
      detail: `Sending XRP and receiving XRP via intermediate token pairs means the payment ` +
              `routes through the DEX and creates trading volume without changing economic position. ` +
              `${xrpRoundTrips.length} occurrences suggests this is deliberate. ` +
              `This is the classic cross-currency wash-trading arb pattern on XRPL. ` +
              `Example hash: ${xrpRoundTrips[0]?.tx?.hash ? shortAddr(xrpRoundTrips[0].tx.hash) : 'N/A'}.`,
      hashes: xrpRoundTrips.slice(0,5).map(({tx}) => tx.hash).filter(Boolean),
    });
  }

  if (deepHops.length >= 1) {  // flag even single deep-hop payment
    riskPenalty += 6;
    signals.push({ sev: 'info',
      label: `${deepHops.length} path payments with ≥3 intermediate hops`,
      detail: `Deep routing chains (3+ hops) can indicate: legitimate arbitrage, ` +
              `liquidity optimization, or deliberate obfuscation of fund origin. ` +
              `Check each transaction for the intermediate issuers in the path.` });
  }

  if (selfRouted.length > 0) {
    if (looksLikeDiverseSwaps) {
      // XRPL has no dedicated swap transaction type, so an in-wallet
      // "convert my token to XRP/another token" feature is natively
      // implemented as exactly this shape — this account touched
      // ${distinctSelfRoutePairs} different, unrelated currency pairs with
      // no single one dominating, which is the signature of ordinary
      // portfolio conversions, not repeated manipulation of one pair.
      riskPenalty += 2;
      signals.push({ sev: 'info',
        label: `${selfRouted.length} self-routed path payment(s) across ${distinctSelfRoutePairs} different currency pairs`,
        detail: `Money routed to your own address via the DEX order book, converting between currencies (e.g. token→XRP). ` +
                `This is how many wallets implement in-wallet currency conversion on XRPL, which has no separate swap transaction type — ` +
                `${distinctSelfRoutePairs} distinct currency pairs with no single pair dominating (largest: ${(dominantPairShare * 100).toFixed(0)}% of these payments) is consistent with ordinary portfolio conversions across different assets, not deliberate manipulation of one token's apparent volume. ` +
                `Hashes: ${selfRouted.slice(0,3).map(({tx}) => shortAddr(tx.hash||'')).join(', ')}.`,
        hashes: selfRouted.slice(0,5).map(({tx}) => tx.hash).filter(Boolean),
      });
    } else {
      // Concentrated on one (or very few) currency pair(s) — this is the
      // pattern actually consistent with deliberately inflating that
      // specific pair's apparent trading activity, not ordinary swap usage.
      riskPenalty += 15;
      signals.push({ sev: 'warn',
        label: `${selfRouted.length} path payment(s) where sender = destination`,
        detail: `Money sent to your own address via a multi-hop path creates DEX trading volume ` +
                `with no net change in balance. Repeatedly self-routing the same currency pair (largest single pair: ${(dominantPairShare * 100).toFixed(0)}% of these payments) is more consistent with deliberately inflating that pair's apparent activity than with ordinary currency conversion, though this cannot be confirmed from ledger data alone. ` +
                `Hashes: ${selfRouted.slice(0,3).map(({tx}) => shortAddr(tx.hash||'')).join(', ')}.`,
        hashes: selfRouted.slice(0,5).map(({tx}) => tx.hash).filter(Boolean),
      });
    }
  }

  if (signals.length === 0) {
    signals.push({ sev: 'ok',
      label: `${pathPayments.length} path payment(s) — no suspicious routing patterns${lowSampleNote}`,
      detail: `No circular routing (XRP→IOU→XRP), self-routing, or unusual deep hop chains detected.` });
  }

  return { signals, riskPenalty, roundTripCount: xrpRoundTrips.length,
           deepHopCount: deepHops.length, selfRoutedCount: selfRouted.length,
           selfRoutedLooksLikeSwaps: selfRouted.length > 0 && looksLikeDiverseSwaps };
}


/* ── Inbound Flow Analysis ───────────────────────────────────────────────────
   Mirrors analyseFundFlow but for incoming payments. Answers:
   who funded this wallet, from how many sources, from known exchanges,
   and whether funding looks structured (many small equal payments).
────────────────────────────────────────────────────────────────────────── */
function analyseInboundFlow(txList, addr) {
  const sources    = new Map();
  const inboundSeq = [];

  for (const { tx, meta } of txList) {
    if (tx.TransactionType !== 'Payment') continue;
    if (tx.Destination !== addr) continue;  // inbound only
    const src = tx.Account;
    if (!src || src === addr) continue;

    const { amtXrp, amtToken } = _extractPaymentAmount(tx, meta);

    const ts = getCloseTime(tx);
    inboundSeq.push({ src, amtXrp, amtToken, ts, hash: tx.hash || '', destTag: tx.DestinationTag });

    if (!sources.has(src)) {
      sources.set(src, { addr: src, totalXrp: 0, txCount: 0, firstSeen: ts, lastSeen: ts, entity: getEntity(src) || null, hasUnknownAmount: false });
    }
    const s = sources.get(src);
    // See _extractPaymentAmount's comment — amtXrp is explicitly null (not
    // 0/NaN) for an undeterminable delivered amount, excluded from the sum
    // rather than poisoning it.
    if (amtXrp != null) s.totalXrp += amtXrp; else s.hasUnknownAmount = true;
    s.txCount++;
    s.lastSeen  = Math.max(s.lastSeen,  ts);
    s.firstSeen = Math.min(s.firstSeen, ts);
  }

  const topSources = [...sources.values()]
    .sort((a,b) => b.totalXrp - a.totalXrp || b.txCount - a.txCount)
    .slice(0, 10);

  const totalIn      = topSources.reduce((s,d) => s + d.totalXrp, 0);
  const unknownAmountCount = [...sources.values()].filter(s => s.hasUnknownAmount).length;
  const exchangeSrcs = topSources.filter(s => s.entity?.type === 'exchange');

  // Structured funding: many payments of near-equal amounts from different
  // sources. Economic-materiality gate: a cluster of near-identical DUST
  // payments (spam/phishing campaigns commonly send negligible amounts to
  // thousands of addresses) buckets exactly the same way a genuine
  // structured-deposit pattern does — the count/ratio check alone can't
  // tell them apart. MATERIALITY_MIN_XRP requires the clustered amount
  // itself to be economically meaningful before "layering" is even
  // considered; below that, the same clustering is dust/spam, not
  // structuring, regardless of how many payments or what fraction of
  // inbound activity they represent.
  const MATERIALITY_MIN_XRP = 1;
  // Distinct-sender floor: "structuring/layering" specifically means
  // splitting funds across multiple sources to evade detection — a single
  // sender repeatedly paying the same round amount (a salary, a
  // subscription, a recurring DCA-style transfer) buckets identically but
  // is an entirely mundane, extremely common pattern with nothing to do
  // with layering. Without this, a wallet with one recurring payer would
  // get "Structured inbound pattern... can indicate layering" purely from
  // its own routine, single-source income.
  const STRUCTURING_MIN_SENDERS = 3;
  const amtBuckets = {};
  for (const r of inboundSeq) {
    if (r.amtXrp <= 0) continue;
    const bucket = Math.round(r.amtXrp / 10) * 10;  // group to nearest 10 XRP
    if (!amtBuckets[bucket]) amtBuckets[bucket] = { count: 0, senders: new Set() };
    amtBuckets[bucket].count++;
    amtBuckets[bucket].senders.add(r.src);
  }
  const topBucketEntry = Object.entries(amtBuckets).sort((a, b) => b[1].count - a[1].count)[0];
  const topBucket = topBucketEntry ? [topBucketEntry[0], topBucketEntry[1].count] : null;
  const topBucketSenderCount = topBucketEntry ? topBucketEntry[1].senders.size : 0;
  const clusterDetected = topBucket && topBucket[1] >= 5 && topBucket[1] / inboundSeq.length > 0.4;
  const singleSourceRecurring = clusterDetected && topBucketSenderCount < STRUCTURING_MIN_SENDERS;
  const materialityGate = clusterDetected ? (Number(topBucket[0]) >= MATERIALITY_MIN_XRP) : null;
  const structuredFlag = clusterDetected && materialityGate === true && !singleSourceRecurring;
  const dustClusterFlag = clusterDetected && materialityGate === false && !singleSourceRecurring;
  const recurringSingleSourceFlag = clusterDetected && singleSourceRecurring;

  const signals = [];
  if (exchangeSrcs.length) {
    const names = [...new Set(exchangeSrcs.map(s => s.entity.name))].join(', ');
    signals.push({ sev: 'info',
      label: `Funding from ${exchangeSrcs.length} known exchange(s): ${names}`,
      detail: `${fmt(exchangeSrcs.reduce((s,d)=>s+d.totalXrp,0),2)} XRP received from exchange withdrawals — typical for a personal trading wallet.` });
  }
  if (structuredFlag) {
    signals.push({ sev: 'warn',
      label: `Structured inbound pattern: ${topBucket[1]} payments near ~${topBucket[0]} XRP`,
      detail: `Over 40% of inbound payments cluster around the same amount (~${topBucket[0]} XRP), and that amount is economically meaningful. Structured deposits can indicate layering — deliberately splitting large amounts into smaller equal transfers to avoid detection.` });
  }
  if (dustClusterFlag) {
    signals.push({ sev: 'info',
      label: `Dust/spam cluster: ${topBucket[1]} negligible-value payments near ~${topBucket[0]} XRP`,
      detail: `${topBucket[1]} inbound payments cluster around the same negligible amount (~${topBucket[0]} XRP, below the ${MATERIALITY_MIN_XRP} XRP materiality threshold) — economically too small to represent structured/layered funds. Classified as a dust or spam campaign rather than possible layering; see Memo Analysis for any accompanying phishing-style text.` });
  }
  if (recurringSingleSourceFlag) {
    signals.push({ sev: 'info',
      label: `Recurring payment pattern: ${topBucket[1]} payments near ~${topBucket[0]} XRP from ${topBucketSenderCount} source(s)`,
      detail: `${topBucket[1]} inbound payments cluster around the same amount (~${topBucket[0]} XRP), but from only ${topBucketSenderCount} distinct sender(s) — consistent with a recurring payment (salary, subscription, scheduled transfer) rather than structuring, which specifically means splitting funds ACROSS multiple sources to evade detection. A single repeating payer sending the same amount is not that pattern.` });
  }
  if (sources.size === 1 && inboundSeq.length >= 5) {
    const sole = topSources[0];
    signals.push({ sev: 'info',
      label: `Single funding source: all ${inboundSeq.length} inbound payments from one address`,
      detail: `${sole.entity?.name || shortAddr(sole.addr)} is the sole funding source. This is normal for a personal wallet but notable for a wallet claiming broad community usage.` });
  }
  if (!signals.length && inboundSeq.length > 0) {
    signals.push({ sev: 'ok', label: `${inboundSeq.length} inbound payment(s) from ${sources.size} source(s)`, detail: `Total received: ${fmt(totalIn,2)} XRP. No unusual inbound patterns.` });
  }
  if (inboundSeq.length === 0) {
    signals.push({ sev: 'info', label: 'No inbound payments found in analysed history', detail: 'Wallet may be funded via DEX activity or in ledgers outside the analysed range.' });
  }

  // Recurring vs. one-time funders, and the overall first/last funding
  // dates — computed from the FULL source set (not just the top-10 slice)
  // so the count is accurate even for wallets with many small funders.
  const allSources = [...sources.values()];
  const recurringCount = allSources.filter(s => s.txCount > 1).length;
  const oneTimeCount = allSources.filter(s => s.txCount === 1).length;
  const firstFundedTs = inboundSeq.length ? Math.min(...inboundSeq.map(r => r.ts)) : null;
  const lastFundedTs = inboundSeq.length ? Math.max(...inboundSeq.map(r => r.ts)) : null;
  const topSourceSharePct = totalIn > 0 && topSources.length ? (topSources[0].totalXrp / totalIn) * 100 : null;

  return {
    signals, topSources, totalIn, uniqueSources: sources.size, timeline: inboundSeq.slice(-20).reverse(), exchangeSrcs,
    structuredFlag: !!structuredFlag, dustClusterFlag: !!dustClusterFlag, recurringSingleSourceFlag: !!recurringSingleSourceFlag, materialityGate,
    recurringCount, oneTimeCount, firstFundedTs, lastFundedTs, topSourceSharePct, unknownAmountCount,
  };
}

/* ── Memo Analysis ────────────────────────────────────────────────────────────
   Scans all Memo fields in the transaction history.
   Memos can contain: exchange deposit references, scam coordination text,
   payout codes, hex-encoded data, or repeated pattern signals.
────────────────────────────────────────────────────────────────────────── */
function analyseMemos(txList, addr) {
  const signals  = [];
  const allMemos = [];

  // Known scam / suspicious memo patterns
  const SCAM_PATTERNS = [
    /airdrop/i, /claim.*reward/i, /free.*xrp/i, /verify.*wallet/i,
    /support.*team/i, /urgent/i, /suspended/i, /confirm.*seed/i,
    /your.*account.*hold/i, /unlock/i,
  ];

  for (const { tx } of txList) {
    if (!tx.Memos?.length) continue;
    for (const m of tx.Memos) {
      const raw = m.Memo?.MemoData || '';
      if (!raw) continue;
      let text = '';
      try { text = decodeURIComponent(raw.replace(/../g, h => '%' + h)); } catch { text = raw; }
      // Also try plain hex→ASCII
      if (!text || text === raw) {
        try {
          let ascii = '';
          for (let i = 0; i < raw.length; i += 2) {
            const c = parseInt(raw.slice(i,i+2), 16);
            if (c >= 32 && c < 127) ascii += String.fromCharCode(c);
          }
          if (ascii.length > 4) text = ascii;
        } catch {}
      }
      const counterparty = tx.Account === addr ? tx.Destination : tx.Account;
      allMemos.push({ tx: tx.hash || '', type: tx.TransactionType, sender: tx.Account, counterparty, date: tx.date, text: text.slice(0, 200), raw });
    }
  }

  if (allMemos.length === 0) {
    return { signals: [], allMemos: [], scamMemos: [], repeatedMemos: [], fingerprints: [] };
  }

  // Check for scam patterns — split by direction. An INBOUND suspicious
  // memo means someone targeted this account (evidence about the sender,
  // an exposure signal); an OUTBOUND one means this account sent it
  // (evidence about this account's own behavior). Conflating the two would
  // penalize a wallet simply for having been targeted by a phishing
  // campaign it never engaged with.
  const scamMemos = allMemos.filter(m => SCAM_PATTERNS.some(p => p.test(m.text)));
  const outboundScamMemos = scamMemos.filter(m => m.sender === addr);
  const inboundScamMemos  = scamMemos.filter(m => m.sender !== addr);
  if (outboundScamMemos.length) {
    signals.push(mkFinding({
      module: 'Memo Analysis', category: 'security', sev: 'critical',
      headline: `${outboundScamMemos.length} outbound memo(s) match known scam patterns`,
      detail: `This account SENT payments containing phrases like "airdrop", "claim reward", "verify wallet", or "urgent" — patterns used in social engineering attacks. Examples: ${outboundScamMemos.slice(0,2).map(m => '"'+m.text.slice(0,40)+'"').join(', ')}`,
      observed: [`${outboundScamMemos.length} outbound scam-pattern memo(s)`, `Sent to ${new Set(outboundScamMemos.map(m => m.counterparty)).size} distinct recipient(s)`],
      classification: 'Outbound scam-pattern memos are evidence about this account\'s own behavior — sending phishing/spam-style payments to others.',
    }));
  }
  if (inboundScamMemos.length) {
    signals.push(mkFinding({
      module: 'Memo Analysis', category: 'external-exposure', sev: 'warn',
      headline: `${inboundScamMemos.length} inbound memo(s) match known scam patterns`,
      detail: `This account RECEIVED payments containing phrases like "airdrop", "claim reward", "verify wallet", or "urgent" — this account was targeted, not the source. Examples: ${inboundScamMemos.slice(0,2).map(m => '"'+m.text.slice(0,40)+'"').join(', ')}`,
      observed: [`${inboundScamMemos.length} inbound scam-pattern memo(s)`, `Sent from ${new Set(inboundScamMemos.map(m => m.sender)).size} distinct sender(s)`],
      evidenceAgainstBenign: [],
      classification: 'This account was the target of a phishing/spam campaign, not its source — this reflects exposure, not this account\'s own behavior, and should not inflate its own risk score.',
    }));
  }

  // Fingerprint clustering — a repeated memo is treated as a signature of
  // shared tooling (a bot's build tag, exchange withdrawal software, issuer
  // distribution scripts), not automatically suspicious. Cluster by exact
  // text, then look at what transaction types and counterparties share
  // that fingerprint, and whether the SAME text was sent by more than one
  // sender — txList includes both outbound and inbound transactions, so an
  // inbound Payment carrying an identical memo from another account is a
  // real (if partial) cross-account signal, not just wishful thinking.
  const memoGroups = new Map();
  for (const m of allMemos) {
    const key = m.text.slice(0, 50).trim().toLowerCase();
    if (key.length <= 3) continue;
    if (!memoGroups.has(key)) memoGroups.set(key, []);
    memoGroups.get(key).push(m);
  }
  const fingerprints = [...memoGroups.entries()]
    .filter(([, occ]) => occ.length >= 3)
    .map(([text, occ]) => {
      const types = [...new Set(occ.map(o => o.type))];
      const counterparties = new Set(occ.map(o => o.counterparty).filter(Boolean));
      const senders = new Set(occ.map(o => o.sender));
      return { text, count: occ.length, types, counterpartyCount: counterparties.size, senderCount: senders.size, crossAccount: senders.size > 1, occurrences: occ };
    })
    .sort((a, b) => b.count - a.count);

  for (const fp of fingerprints.slice(0, 5)) {
    const confidence = Math.min(0.9, 0.3 + fp.count * 0.05 + (fp.crossAccount ? 0.15 : 0));
    signals.push(mkFinding({
      module: 'Memo Analysis', category: 'automation', sev: 'info', confidence,
      headline: `Automation Fingerprint Detected: "${fp.text.slice(0, 40)}" — ${Math.round(confidence * 100)}% confidence`,
      detail: `Appears ${fp.count} time(s) across ${fp.counterpartyCount} counterpart(y/ies) and ${fp.types.length} transaction type(s).`,
      observed: [
        `${fp.count} occurrences`,
        `Transaction types: ${fp.types.join(', ')}`,
        `Distinct counterparties: ${fp.counterpartyCount}`,
        fp.crossAccount
          ? `Sent by ${fp.senderCount} different accounts, not just this one — likely shared tooling/infrastructure rather than something unique to this wallet`
          : 'Only sent by this account in the fetched history',
      ],
      alternativeExplanations: ['Standard software/bot signature (exchange withdrawal tooling, a trading bot\'s build tag, issuer distribution tooling)', 'A recurring invoice or reference code used for ordinary bookkeeping'],
      classification: 'Repeated identical memo text is a fingerprint of shared tooling or a scripted process, not inherently suspicious on its own — useful for identifying infrastructure, bots, or coordinated actors, but needs other evidence to say which.',
    }));
  }

  // Version-tag detection: distinct memo strings matching a version-number
  // shape (e.g. "rm-1.2.4") observed over time suggest a tool being
  // updated, not repetition — genuinely different from the fingerprint
  // case above, which is about the SAME string recurring.
  const versionLike = [...new Set(allMemos.filter(m => /\bv?\d+\.\d+(\.\d+)?\b/i.test(m.text)).map(m => m.text))];
  if (versionLike.length >= 2) {
    signals.push({ sev: 'info', label: `${versionLike.length} distinct version-like memo tag(s) observed`,
      detail: `Tags: ${versionLike.slice(0, 5).join(', ')}. Consistent with an automated tool's memo tag being bumped across software versions over time.` });
  }

  if (!signals.length) {
    signals.push({ sev: 'ok',
      label: `${allMemos.length} memo(s) found — no suspicious patterns`,
      detail: `Memo content looks normal.` });
  }

  return { signals, allMemos, scamMemos, repeatedMemos: fingerprints.slice(0, 5).map(fp => [fp.text, fp.count]), fingerprints };
}

/** Cross-references inbound scam-pattern memos against Drain Risk episodes.
 *  These two modules run independently and, until now, rendered as two
 *  disconnected observations even when one plausibly explains the other —
 *  a phishing-style message followed within a short window by a real
 *  balance-movement episode is a specific, time-ordered sequence, not just
 *  two coincidentally-bad signals on the same account.
 *
 *  Severity here MUST defer to analyseAssetDrainBehavior's own corroboration
 *  gate (ep.isCorroborated) rather than re-deriving a fresh one from
 *  `classification` alone — a real false positive, confirmed live: an active
 *  DEX trader's ordinary large transfers (already correctly capped at 'warn'
 *  by Drain Risk itself, for lack of corroboration) got re-escalated to
 *  'critical' here purely because a scam memo — a common, near-routine
 *  occurrence on XRPL, not a rare signal — happened to land within the
 *  72-hour window, which for a busy account is a coincidence with a
 *  meaningfully high base rate on its own. This module may surface that
 *  coincidence as context, but must never let a memo alone escalate an
 *  episode past what the module that actually specializes in judging it
 *  already concluded. */
const MEMO_DRAIN_CORRELATION_WINDOW_SEC = 72 * 3600;
function analyseMemoDrainCorrelation(memoAnalysis, drainAnalysis, addr, isProjectAccount = false) {
  const signals = [];
  const inboundScamMemos = (memoAnalysis?.scamMemos || []).filter(m => m.sender !== addr && m.date != null);
  const episodes = drainAnalysis?.episodes || [];
  if (!inboundScamMemos.length || !episodes.length) return { signals };

  for (const ep of episodes) {
    if (ep.classification === 'pass-through') continue; // no real depletion — nothing here to link to
    const precedingMemos = inboundScamMemos
      .filter(m => m.date <= ep.startDate && ep.startDate - m.date <= MEMO_DRAIN_CORRELATION_WINDOW_SEC)
      .sort((a, b) => b.date - a.date);
    if (!precedingMemos.length) continue;

    const hoursBefore = Math.max(0, Math.round((ep.startDate - precedingMemos[0].date) / 3600 * 10) / 10);
    const windowLabel = ep.windowSec === 86400 ? '24h' : `${Math.round(ep.windowSec / 86400)}d`;
    const senderCount = new Set(precedingMemos.map(m => m.sender)).size;
    // Mirrors analyseAssetDrainBehavior's own escalation rule exactly — see
    // this function's doc comment above for why re-deriving severity purely
    // from `classification` (ignoring corroboration) was a real bug.
    const episodeAlreadyEscalated = ep.triggeredByAuthChange || isProjectAccount || ep.isCorroborated;
    const rawSev = (ep.classification === 'sweep' || ep.classification === 'potential-drain') ? 'critical' : 'warn';
    const sev = episodeAlreadyEscalated ? rawSev : (rawSev === 'critical' ? 'warn' : 'info');
    signals.push(mkFinding({
      module: 'Memo-Drain Correlation', category: 'security',
      sev,
      confidence: 0.55,
      headline: `Scam-pattern memo received ${hoursBefore}h before a balance-movement episode`,
      detail: `${precedingMemos.length} inbound memo(s) matching known scam/phishing patterns arrived shortly before a ${windowLabel} window in which ${fmt(ep.grossOutflowXrp, 2)} XRP moved out (${(ep.actualDepletionPct * 100).toFixed(1)}% actual depletion, classified "${ep.classification}"). This links two otherwise-separate findings into one time-ordered sequence.`,
      observed: [
        `${precedingMemos.length} inbound scam-pattern memo(s) from ${senderCount} sender(s), most recent ${hoursBefore}h before the outflow window began`,
        `Balance-movement episode: ${fmt(ep.grossOutflowXrp, 2)} XRP gross outflow, ${(ep.actualDepletionPct * 100).toFixed(1)}% actual depletion`,
        !episodeAlreadyEscalated ? `Severity capped: Drain Risk's own analysis of this specific episode found no independent corroboration (no auth-change precursor, no first-time-recipient spike, no liquidate-then-withdraw sequence, no transfer-size anomaly) — a coincidentally-timed memo alone is not enough to override that` : null,
      ].filter(Boolean),
      alternativeExplanations: [
        'Coincidental timing — this account may have made an unrelated, already-planned transfer around the same time',
        'The scam memo may have been ignored entirely, with the outflow being genuinely unrelated activity',
        'Inbound scam/phishing memos are common on XRPL generally — an active account receiving one within 72 hours of any balance movement has a meaningful chance of pure coincidence',
      ],
      evidenceAgainstBenign: [
        'Temporal proximity: the outflow began within the correlation window after a phishing-pattern message was received',
      ],
      classification: 'This does not prove the memo caused the outflow — only that the two are close enough in time to be worth weighing together rather than reading each finding in isolation. See Drain Risk above for the full evidence on this specific episode.',
    }));
  }
  return { signals };
}

/* ── Escrow Depth Analysis ────────────────────────────────────────────────────
   Goes beyond counting escrows to understand who created them, when they mature,
   and whether third-party escrows (created by external accounts) are present.
────────────────────────────────────────────────────────────────────────── */
function analyseEscrowDepth(objects, txList, addr) {
  const escrows = objects.filter(o => o.LedgerEntryType === 'Escrow');
  if (!escrows.length) return { signals: [], escrows: [], hasThirdParty: false };

  const signals   = [];
  const now       = Math.floor(Date.now() / 1000);
  const RIPPLE_EPOCH = 946684800;

  const details = escrows.map(e => {
    const creator     = e.Account || null;
    const dest        = e.Destination || null;
    const amtXrp      = Number(e.Amount || 0) / 1e6;
    const finishAfter = e.FinishAfter ? e.FinishAfter + RIPPLE_EPOCH : null;
    const cancelAfter = e.CancelAfter ? e.CancelAfter + RIPPLE_EPOCH : null;
    const isThirdParty = creator && creator !== addr && dest === addr;
    const isSelfEscrow = creator === addr && dest === addr;
    const daysToFinish = finishAfter ? Math.ceil((finishAfter - now) / 86400) : null;
    return { creator, dest, amtXrp, finishAfter, cancelAfter, isThirdParty, isSelfEscrow, daysToFinish, conditional: !!e.Condition };
  });

  const thirdParty = details.filter(e => e.isThirdParty);
  const totalLocked = details.reduce((s,e) => s+e.amtXrp, 0);

  if (thirdParty.length) {
    signals.push({ sev: 'warn',
      label: `${thirdParty.length} escrow(s) created by external account(s) — funds locked to this address`,
      detail: `${fmt(thirdParty.reduce((s,e)=>s+e.amtXrp,0),2)} XRP in escrows that an outside party controls. The creator sets the conditions. ` +
              `Escrows created by attackers just before a drain attempt have been observed in some compromise patterns — verify who created these.` });
  }

  // Look for escrows maturing soon (within 7 days)
  const soonMature = details.filter(e => e.daysToFinish != null && e.daysToFinish >= 0 && e.daysToFinish <= 7);
  if (soonMature.length) {
    signals.push({ sev: 'info',
      label: `${soonMature.length} escrow(s) mature within 7 days`,
      detail: `${fmt(soonMature.reduce((s,e)=>s+e.amtXrp,0),2)} XRP will become claimable soon. ` +
              `If these are third-party escrows, the creator can claim funds once the condition is met.` });
  }

  if (!signals.length) {
    signals.push({ sev: 'ok',
      label: `${escrows.length} self-escrow(s) — ${fmt(totalLocked,2)} XRP locked`,
      detail: `All escrows appear to be self-controlled time-locks. No third-party escrow risk.` });
  }

  return { signals, escrows: details, hasThirdParty: thirdParty.length > 0, totalLocked };
}

/* ── Check Object Analysis ────────────────────────────────────────────────────
   XRPL Checks are deferred payments — like a paper check, must be cashed by recipient.
   An uncashed check for a large amount sitting open for months is unusual.
────────────────────────────────────────────────────────────────────────── */
function analyseChecks(objects) {
  const checks = objects.filter(o => o.LedgerEntryType === 'Check');
  if (!checks.length) return { signals: [], checks: [] };

  const signals = [];
  const RIPPLE_EPOCH = 946684800;
  const now     = Math.floor(Date.now() / 1000);

  const details = checks.map(c => {
    const amtXrp   = typeof c.SendMax === 'string' ? Number(c.SendMax) / 1e6 : null;
    const amtToken = typeof c.SendMax === 'object' ? c.SendMax : null;
    const expiry   = c.Expiration ? c.Expiration + RIPPLE_EPOCH : null;
    const agesDays = c.ledger_index ? null : null;  // would need ledger close time to compute
    const expired  = expiry && expiry < now;
    return { sender: c.Account, dest: c.Destination, amtXrp, amtToken, expiry, expired, id: c.index || '' };
  });

  const largeChecks = details.filter(c => c.amtXrp && c.amtXrp > 100);
  const expiredChecks = details.filter(c => c.expired);

  if (largeChecks.length) {
    signals.push({ sev: 'info',
      label: `${largeChecks.length} large uncashed check(s) — ${fmt(largeChecks.reduce((s,c)=>s+(c.amtXrp||0),0),2)} XRP pending`,
      detail: `Open checks can be cashed by the recipient at any time before expiry. Large uncashed checks represent a future outflow commitment.` });
  }
  if (expiredChecks.length) {
    signals.push({ sev: 'info',
      label: `${expiredChecks.length} expired check(s) — should be cancelled to reclaim reserve`,
      detail: `Expired checks still occupy owner reserve slots (2 XRP each). Cancelling them returns the reserved XRP.` });
  }
  if (!signals.length) {
    signals.push({ sev: 'ok',
      label: `${checks.length} check(s) found — no unusual patterns`,
      detail: `Check amounts are within normal range.` });
  }

  return { signals, checks: details };
}

/* ── Live Order Book Analysis ─────────────────────────────────────────────────
   Fetches the current live order book for the wallet's most-traded pair.
   Looks for: wall orders (very large single orders dominating depth),
   suspicious size patterns (orders too uniform in size — bot-placed),
   and whether this wallet's open offers match the book.
────────────────────────────────────────────────────────────────────────── */
function analyseLiveOrderBook(liveOrderBook, addr) {
  if (!liveOrderBook || !liveOrderBook.offers?.length) {
    return { signals: [], hasData: false };
  }

  const { pair, offers } = liveOrderBook;
  const signals = [];

  // Total book depth by account
  const accountDepth = new Map();
  for (const o of offers) {
    const acct = o.Account;
    const gets = typeof o.TakerGets === 'string' ? Number(o.TakerGets)/1e6 : Number(o.TakerGets?.value||0);
    accountDepth.set(acct, (accountDepth.get(acct)||0) + gets);
  }
  const totalDepth = [...accountDepth.values()].reduce((s,v)=>s+v,0);

  // Our wallet's share of the book
  const ourDepth = accountDepth.get(addr) || 0;
  const ourShare = totalDepth > 0 ? ourDepth / totalDepth : 0;

  // Wall detection: top order is >40% of total book depth
  const sortedBySize = [...offers].sort((a,b) => {
    const ga = typeof a.TakerGets === 'string' ? Number(a.TakerGets)/1e6 : Number(a.TakerGets?.value||0);
    const gb = typeof b.TakerGets === 'string' ? Number(b.TakerGets)/1e6 : Number(b.TakerGets?.value||0);
    return gb - ga;
  });
  const topOffer = sortedBySize[0];
  const topGets  = typeof topOffer?.TakerGets === 'string' ? Number(topOffer.TakerGets)/1e6 : Number(topOffer?.TakerGets?.value||0);
  const wallShare = totalDepth > 0 ? topGets / totalDepth : 0;

  if (wallShare > 0.4 && topOffer?.Account === addr) {
    signals.push({ sev: 'critical',
      label: `Active wall order: this wallet controls ${(wallShare*100).toFixed(0)}% of current book depth`,
      detail: `A single order from this address represents ${(wallShare*100).toFixed(0)}% of the visible order book depth on pair ${pair}. ` +
              `Large orders placed to make a market look deeper than it is — without intent to fill — is spoofing. ` +
              `This order is live right now.` });
  } else if (wallShare > 0.4) {
    // Confirmed real false positive: this branch fires for a wall order
    // belonging to ANY address, not the inspected wallet — a completely
    // unrelated third party's current large limit order in the same
    // market. Rendered as 'warn' inside THIS wallet's own report (and, via
    // analyseSpoofingScore's live-snapshot injection below, previously fed
    // straight into THIS wallet's own Spoofing score), it read as evidence
    // about this account's conduct when it's really just ambient market
    // state this account has no control over — confirmed live across
    // several unrelated real accounts that happened to trade the same pair
    // as some other large trader. Kept as 'info' market context (still
    // useful for interpreting liquidity depth) and explicitly excluded from
    // Spoofing scoring, which must only ever reflect the inspected
    // wallet's own orders.
    signals.push({ sev: 'info', aboutInspectedWallet: false,
      label: `Third-party wall order in this market: ${(wallShare*100).toFixed(0)}% of book depth`,
      detail: `A single OTHER address (not this wallet) currently controls ${(wallShare*100).toFixed(0)}% of the order book for pair ${pair}. ` +
              `Shown as context for interpreting book depth — this is someone else's order, not this wallet's own activity, and is not counted as evidence about this account.` });
  }

  if (ourShare > 0.25) {
    signals.push({ sev: 'info',
      label: `This wallet controls ${(ourShare*100).toFixed(0)}% of current order book depth`,
      detail: `${fmt(ourDepth,2)} of ${fmt(totalDepth,2)} total book volume on pair ${pair}.` });
  }

  if (!signals.length) {
    signals.push({ sev: 'ok',
      label: `Live order book looks normal (${offers.length} orders, pair: ${pair.split('↔').map(p=>p.split('+')[0]).join('↔')})`,
      detail: `No wall orders or unusual depth concentration detected in the current order book.` });
  }

  return { signals, hasData: true, pair, offerCount: offers.length, ourShare, wallShare };
}

/* ── Risk Score Breakdown ─────────────────────────────────────────────────────
   Returns a structured breakdown of what drove the overall score.
   Used by the visual breakdown bar in the header.
────────────────────────────────────────────────────────────────────────── */
function buildRiskBreakdown(riskScore, security, drain, nft, wash, benfords, volConc,
    entropy, zipf, timeSeries, granger, fee, inbound, memo) {
  const components = [
    { label: 'Security',       pts: Math.round((100 - security.score) * 0.4),   max: 40,  color: '#ff5555', icon: '🔐' },
    { label: 'Drain Risk',     pts: { low:0, medium:10, high:25, critical:35 }[drain.riskLevel] || 0, max: 35, color: '#ff5555', icon: '⚠️' },
    { label: 'Wash Trading',   pts: _washRiskScoreContribution(wash), max: 15, color: '#ffb86c', icon: '📊' },
    { label: 'NFT Risk',       pts: Math.min(15, (nft.flags.filter(f=>f.sev==='critical').length)*8 + (nft.flags.filter(f=>f.sev==='warn').length)*3), max: 15, color: '#bd93f9', icon: '🎨' },
    { label: "Benford's",      pts: Math.round(benfordScoreContribution(benfords)), max: 10, color: '#f1fa8c', icon: '📐' },
    { label: 'Forensic Suite', pts: Math.min(20,
        Math.min(8,Math.round((entropy?.riskPenalty||0)*0.35)) +
        Math.min(8,Math.round((zipf?.riskPenalty||0)*0.4)) +
        Math.min(8,Math.round((timeSeries?.riskPenalty||0)*0.35)) +
        Math.min(8,Math.round((granger?.riskPenalty||0)*0.35))), max: 20, color: '#00d4ff', icon: '🧬' },
    { label: 'Vol Conc',       pts: Math.min(10, (volConc?.signals?.filter(s=>s.sev==='critical').length||0)*6 + (volConc?.signals?.filter(s=>s.sev==='warn').length||0)*3), max: 10, color: '#ffb86c', icon: '🫧' },
    { label: 'Fee Spikes',     pts: Math.min(5, fee?.riskPenalty||0), max: 5, color: '#ffb86c', icon: '💸' },
  ].filter(c => c.pts > 0);
  return components;
}

/* ─────────────────────────────
   Overall Risk Score
──────────────────────────────── */
/* ── Risk Score Evidence Model ──
   The single overall risk number below (computeOverallRisk) collapses
   everything into one figure — useful as a headline, but it hides which
   KIND of risk is actually present. A blackholed issuer scores near-zero
   on Security while scoring high on Market Integrity; folding those into
   one number erases exactly the distinction a reader needs. This computes
   a SEPARATE score per category using Severity × Confidence: a finding
   with 20% confidence contributes a fifth as much as one at 100%, so a
   single low-confidence critical can no longer outweigh several solid
   medium-confidence findings the way a flat severity sum would allow.
   Findings from modules not yet upgraded to mkFinding have no .category/
   .confidence — MODULE_DEFAULT_CATEGORY assigns them a reasonable bucket
   by module name, and a neutral 0.5 confidence, so every module is
   represented here, not just the ones already carrying real evidence-
   model data. */
const RISK_CATEGORIES = ['security', 'market-integrity', 'counterparty', 'issuer', 'liquidity', 'automation', 'external-exposure'];
const RISK_CATEGORY_LABELS = {
  security: 'Security Risk', 'market-integrity': 'Market Integrity Risk', counterparty: 'Counterparty Risk',
  issuer: 'Issuer Risk', liquidity: 'Liquidity Risk', automation: 'Automation Probability',
  // Deliberately separate from the account's own behavioral categories above:
  // this measures things done TO the account (inbound phishing/spam memos),
  // not by it — a wallet being targeted shouldn't inflate its own risk score.
  'external-exposure': 'External Exposure',
};
const MODULE_DEFAULT_CATEGORY = {
  'Security': 'security', 'Drain Risk': 'security', 'NFT': 'security',
  'Wash Trading': 'market-integrity', "Benford's Law": 'market-integrity', 'Offer/Flow Coupling': 'market-integrity',
  'Volume Concentration': 'market-integrity', "Shannon's Entropy": 'market-integrity', "Zipf's Law": 'market-integrity',
  'Time Series': 'market-integrity', 'Live Order Book': 'market-integrity',
  'Token Issuer': 'issuer', 'Issuer Connections': 'issuer',
  'AMM': 'liquidity',
  'Fund Flow': 'counterparty', 'Destination Tags': 'counterparty', 'Path Payments': 'counterparty',
  'Inbound Flow': 'counterparty', 'Escrow Depth': 'counterparty',
  'Fee Spikes': 'automation', 'Memo Analysis': 'automation',
};
const _RISK_SEV_WEIGHT = { critical: 40, warn: 15, info: 3, ok: 0 };

function computeCategoryRiskScores(allFindings) {
  const byCategory = {};
  for (const cat of RISK_CATEGORIES) byCategory[cat] = { score: 0, findings: [] };

  for (const f of allFindings) {
    if (f.sev === 'ok' || !f.sev) continue;
    const cat = f.category || MODULE_DEFAULT_CATEGORY[f.module] || 'security';
    if (!byCategory[cat]) continue;
    const confidence = f.confidence ?? 0.5; // neutral default for pre-evidence-model findings
    byCategory[cat].score += (_RISK_SEV_WEIGHT[f.sev] ?? 0) * confidence;
    byCategory[cat].findings.push(f);
  }

  for (const cat of RISK_CATEGORIES) byCategory[cat].score = Math.round(Math.min(100, byCategory[cat].score));
  return byCategory;
}

function computeOverallRisk(security, drain, nft, wash, benfords, volConc, entropy, zipf, timeSeries, granger, fee = null) {
  let score = 0;

  // Security posture (0–40 pts)
  score += Math.round((100 - security.score) * 0.4);

  // Drain risk (0–35 pts)
  const drainPts = { low: 0, medium: 10, high: 25, critical: 35 };
  score += drainPts[drain.riskLevel] || 0;

  // NFT (0–15 pts)
  const criticalNft = nft.flags.filter(f => f.sev === 'critical').length;
  const warnNft     = nft.flags.filter(f => f.sev === 'warn').length;
  score += Math.min(15, criticalNft * 8 + warnNft * 3);

  // Wash trading (0–15 pts) — see _washRiskScoreContribution.
  score += _washRiskScoreContribution(wash);

  // Benford's Law deviation (0–10 pts) — continuous, discounted by
  // applicability rather than a tiered on/off bonus, and shared with
  // buildRiskBreakdown's display copy so the two can't drift apart.
  score += benfordScoreContribution(benfords);

  // Volume concentration (0–10 pts)
  if (volConc?.signals) {
    const crit = volConc.signals.filter(s => s.sev === 'critical').length;
    const warn = volConc.signals.filter(s => s.sev === 'warn').length;
    score += Math.min(10, crit * 6 + warn * 3);
  }

  // ── Forensic Suite (capped at 20 pts total, scaled) ──
  // Shannon Entropy penalty (0–8)
  if (entropy?.riskPenalty) score += Math.min(8, Math.round(entropy.riskPenalty * 0.35));
  // Zipf's Law penalty (0–8)
  if (zipf?.riskPenalty) score += Math.min(8, Math.round(zipf.riskPenalty * 0.4));
  // Time Series penalty (0–8)
  if (timeSeries?.riskPenalty) score += Math.min(8, Math.round(timeSeries.riskPenalty * 0.35));
  // Offer/Flow Coupling penalty (0–8)
  if (granger?.riskPenalty) score += Math.min(8, Math.round(granger.riskPenalty * 0.35));

  // Fee spike penalty (coordinated fee elevation = possible orchestrated activity)
  if (fee?.riskPenalty) score += Math.min(5, fee.riskPenalty);

  return Math.round(Math.min(100, score));
}

/* ═══════════════════════════════════════════════════
   RENDER SECTIONS
═══════════════════════════════════════════════════ */

/* ── Benford's Law Panel ────────────────────────── */
function renderBenfordsPanel(analysis) {
  const body = document.getElementById('inspect-benfords-body');
  if (!body) return;

  const sigRows = analysis.signals.map(findingRow).join('');

  // Digit bar chart (show expected vs observed)
  const bars = analysis.digitBreakdown?.length ? `
    <div class="benford-grid">
      <div class="benford-grid-h">Digit</div>
      <div class="benford-grid-h">Observed</div>
      <div class="benford-grid-h">Expected</div>
      <div class="benford-grid-h">Bar</div>
      ${analysis.digitBreakdown.map(d => {
        const obsN = parseFloat(d.obs), expN = parseFloat(d.exp);
        const delta = obsN - expN;
        const color = Math.abs(delta) > 5 ? '#ff5555' : Math.abs(delta) > 2.5 ? '#ffb86c' : '#50fa7b';
        const bar = `<div style="height:6px;border-radius:3px;background:rgba(255,255,255,.08);overflow:hidden">
          <div style="height:100%;width:${Math.min(100, obsN * 3.3).toFixed(0)}%;background:${color};border-radius:3px"></div>
        </div>`;
        return `<div class="mono" style="text-align:center">${d.digit}</div>
                <div class="mono" style="color:${color}">${d.obs}%</div>
                <div class="mono" style="opacity:.6">${d.exp}%</div>
                <div>${bar}</div>`;
      }).join('')}
    </div>` : '';

  const meta = analysis.chiSq != null
    ? `<div class="wash-stat-row" style="margin-top:8px">
        <span>Sample size</span><span class="mono">${analysis.sampleSize}</span>
       </div>
       <div class="wash-stat-row">
        <span>Chi-squared (χ²)</span>
        <span class="mono ${analysis.chiSq > 20.09 ? 'risk-text-high' : analysis.chiSq > 15.51 ? 'risk-text-med' : ''}">${analysis.chiSq.toFixed(2)}</span>
       </div>
       <div class="wash-stat-row">
        <span>Critical values</span><span class="mono" style="opacity:.6">p&lt;0.05: 15.51 · p&lt;0.01: 20.09</span>
       </div>`
    : '';

  // ── Layman explainer block (always shown) ───────────────────────────────
  const verdict      = analysis.verdict;
  const chiSq        = analysis.chiSq;
  const sampleSize   = analysis.sampleSize;

  let explainIcon  = '📊';
  let explainTitle = "What is Benford\u2019s Law?";
  let explainIntro = "In nature — population sizes, river lengths, stock prices, real financial transactions — the leading (first) digit of numbers is NOT random. The number 1 appears as the first digit about 30% of the time. The number 9 appears only 4.6% of the time. This predictable pattern is Benford's Law.";
  let explainResult = '';
  let explainColor  = 'rgba(255,255,255,.08)';
  let explainBorderColor = 'rgba(255,255,255,.10)';

  if (verdict === 'insufficient') {
    explainResult = `<p class="benford-explain-result">Not enough data yet — we need at least 50 transaction amounts to run this test. This account has ${sampleSize} so far. The more activity, the more reliable the analysis.</p>`;
  } else if (verdict === 'high-deviation') {
    explainIcon  = '🚨';
    explainColor = 'rgba(255,85,85,.06)';
    explainBorderColor = 'rgba(255,85,85,.22)';
    explainResult = `<p class="benford-explain-result">
      <strong style="color:#ff5555">What this means for this account:</strong>
      The transaction amounts here deviate strongly from what you'd expect in real organic activity
      (χ²&nbsp;=&nbsp;${chiSq?.toFixed(1)}, which is above the suspicious threshold of 20.09 at 99% confidence).
    </p>
    <p class="benford-explain-result">
      In plain terms: the mix of numbers being used feels <em>too calculated</em>.
      Real human spending is messy — you buy things for $7.43, $312.50, $1,200 — and the leading digits
      naturally follow Benford's pattern. When a bot or script generates amounts, it tends to use
      suspiciously round numbers, repeat the same values, or avoid certain digits — and that breaks
      the pattern.
    </p>
    <p class="benford-explain-result" style="color:#ffb86c">
      <strong>What this does NOT prove:</strong> Legitimate algorithmic or automated trading — a market maker
      quoting round-numbered sizes, a bot placing fixed-increment orders, or programmatic pricing — can
      ALSO naturally violate Benford's Law with no wrongdoing at all. This is a supporting signal, not
      proof of fraud on its own. Cross-reference with the Wash Trading and Volume Concentration sections
      for a fuller picture.
    </p>`;
  } else if (verdict === 'moderate-deviation') {
    explainIcon  = '⚠';
    explainColor = 'rgba(255,184,108,.05)';
    explainBorderColor = 'rgba(255,184,108,.20)';
    explainResult = `<p class="benford-explain-result">
      <strong style="color:#ffb86c">What this means for this account:</strong>
      There's a moderate mismatch from natural patterns (χ²&nbsp;=&nbsp;${chiSq?.toFixed(1)}).
      This could mean some automated or repeated transactions are mixed in with genuine activity.
      It isn't alarming on its own but is worth watching — especially if other sections also show signals.
    </p>`;
  } else if (verdict === 'normal') {
    explainIcon  = '✅';
    explainColor = 'rgba(80,250,123,.04)';
    explainBorderColor = 'rgba(80,250,123,.15)';
    explainResult = `<p class="benford-explain-result">
      <strong style="color:#50fa7b">What this means for this account:</strong>
      The transaction amounts follow the natural Benford's pattern closely (χ²&nbsp;=&nbsp;${chiSq?.toFixed(1)}).
      This is what you'd expect from organic, real-world financial activity.
      No statistical red flags here.
    </p>`;
  }

  const explainerBlock = `
    <div class="benford-explainer" style="background:${explainColor};border-color:${explainBorderColor}">
      <div class="benford-explainer-head">
        <span class="benford-explainer-icon">${explainIcon}</span>
        <span class="benford-explainer-title">${explainTitle}</span>
      </div>
      <p class="benford-explain-text">
        ${explainIntro}
      </p>
      <div class="benford-explain-visual">
        <div class="benford-visual-row">
          <span class="benford-digit-ex">Digit 1</span>
          <div class="benford-visual-bar" style="width:30.1%;background:rgba(80,250,123,.55)"></div>
          <span class="benford-visual-pct">30.1%</span>
          <span class="benford-visual-note">most common</span>
        </div>
        <div class="benford-visual-row">
          <span class="benford-digit-ex">Digit 5</span>
          <div class="benford-visual-bar" style="width:7.9%;background:rgba(255,184,108,.55)"></div>
          <span class="benford-visual-pct">7.9%</span>
          <span class="benford-visual-note"></span>
        </div>
        <div class="benford-visual-row">
          <span class="benford-digit-ex">Digit 9</span>
          <div class="benford-visual-bar" style="width:4.6%;background:rgba(255,85,85,.55)"></div>
          <span class="benford-visual-pct">4.6%</span>
          <span class="benford-visual-note">least common</span>
        </div>
      </div>
      <p class="benford-explain-text" style="margin-top:6px;opacity:.75">
        When real money moves — payments, trades, escrows — these proportions hold up remarkably well.
        When amounts are <em>generated by a script</em> or deliberately faked, they don't.
        That's why forensic accountants use Benford's Law to detect fraud in financial records.
      </p>
      ${explainResult}
    </div>
  `;

  body.innerHTML = sigRows + meta + bars + explainerBlock;
  _setForensicEngineBadge('badge-benfords', analysis.verdict);
}

/* ── Volume Concentration Panel ──────────────────── */
// Distinct, non-alarming palette for concentration-share segments — color
// here encodes RANK (which cluster), not severity (that's already conveyed
// by the HHI/Gini stats and the findings above), so it deliberately avoids
// the red/amber/green severity language used elsewhere in this file.
const _VOLCONC_SEGMENT_COLORS = ['#00d4ff', '#bd93f9', '#50fa7b', '#ffb86c', '#8be9fd', '#ff79c6', '#f1fa8c', '#6272a4'];
const VOLCONC_SEGMENT_CAP = 8;

/** Real per-cluster share bar + HHI/Gini/effective-participant stats,
 *  replacing a fallback table that referenced a field (`uniqueActors`)
 *  which no longer exists on this analysis object since the clustering
 *  rework — it silently always rendered "✓ OK" regardless of the real
 *  concentration. */
function renderVolConcPanel(analysis) {
  const body = document.getElementById('inspect-volconc-body');
  if (!body) return;

  const sigRows = analysis.signals.map(findingRow).join('');

  const cards = (analysis.concentrations || []).filter(c => c.shares?.length).map(c => {
    const top = c.shares.slice(0, VOLCONC_SEGMENT_CAP);
    const otherShare = c.shares.slice(VOLCONC_SEGMENT_CAP).reduce((a, b) => a + b, 0);
    const segments = [
      ...top.map((s, i) => ({ pct: s * 100, color: _VOLCONC_SEGMENT_COLORS[i % _VOLCONC_SEGMENT_COLORS.length], label: `Cluster #${i + 1}` })),
      ...(otherShare > 0.0001 ? [{ pct: otherShare * 100, color: 'rgba(255,255,255,.12)', label: `Other (${c.shares.length - top.length} cluster(s))` }] : []),
    ];
    const bar = segments.map(seg =>
      `<div class="volconc-seg" style="width:${seg.pct.toFixed(2)}%;background:${seg.color}" data-tooltip="${escHtml(`${seg.label}: ${seg.pct.toFixed(1)}% of volume`)}"></div>`
    ).join('');

    return `
      <div class="volconc-card">
        <div class="volconc-card-hdr">
          <span class="mono">${escHtml((hexToAscii(c.currency) || c.currency).slice(0, 12))}</span>
          <span class="volconc-card-meta">${c.trades} trades · ~${c.estimatedActorClusters} estimated actor(s) (${c.rawActorCount} raw)</span>
        </div>
        <div class="volconc-bar">${bar}</div>
        <div class="volconc-plain">${escHtml(_volConcPlainLabel(c.hhi))}</div>
        <div class="advanced-only">
          <div class="wash-stat-row"><span>Top-1 / Top-5 / Top-10 share</span><span class="mono">${(c.top1Share * 100).toFixed(0)}% / ${(c.top5Share * 100).toFixed(0)}% / ${(c.top10Share * 100).toFixed(0)}%</span></div>
          <div class="wash-stat-row"><span>HHI <span style="opacity:.5;font-weight:400">(analyst metric)</span></span><span class="mono">${Math.round(c.hhi)}</span></div>
          <div class="wash-stat-row"><span>Gini coefficient <span style="opacity:.5;font-weight:400">(analyst metric)</span></span><span class="mono">${c.gini.toFixed(2)}</span></div>
          <div class="wash-stat-row"><span>Effective participants (10000/HHI)</span><span class="mono">${c.effectiveParticipants.toFixed(1)}</span></div>
        </div>
      </div>`;
  }).join('');

  const simpleTeaser = analysis.signals.length ? `
    <div class="simple-only" style="font-size:.76rem;color:rgba(255,255,255,.4);padding:8px 2px;margin-bottom:6px">
      ${analysis.signals.length} underlying finding${analysis.signals.length === 1 ? '' : 's'} — switch to <strong>⚗ Advanced</strong> (top of page) to see the full evidence and per-currency statistics.
    </div>` : '';

  body.innerHTML = simpleTeaser + `<div class="advanced-only">${sigRows}</div>` + cards;
}

/* ═══════════════════════════════════════════════════
   FORENSIC ANALYTICS SUITE — INDIVIDUAL PANELS
═══════════════════════════════════════════════════ */

function _renderForensicPanel(bodyId, analysis, metaRows, fourLayer) {
  const body = document.getElementById(bodyId);
  if (!body) return;
  const sigRows = analysis.signals.map(findingRow).join('');
  body.innerHTML = (fourLayer ? _renderForensicFourLayer(fourLayer) : '') + sigRows + (metaRows || '');
}

/** Shared plain-language layer for every Forensic Analytics Suite engine —
 *  What it checks / What Nalu found / Why it matters / What it does NOT
 *  prove — so all five engines (Benford, Entropy, Zipf, Time Series,
 *  Offer/Flow Coupling) speak the same language instead of five
 *  independently-invented explanations, and so the densest, most
 *  statistical corner of the Inspector gets the same "supporting
 *  evidence, not proof" framing already established elsewhere. `checks`/
 *  `matters`/`doesNotProve` are static per engine; `found` is the one
 *  dynamic layer, built from that engine's own real verdict/stats. */
function _renderForensicFourLayer({ checks, found, matters, doesNotProve }) {
  return `
    <div class="forensic-4layer">
      <div class="forensic-4layer-row"><span class="forensic-4layer-label">What it checks</span><div class="forensic-4layer-text">${escHtml(checks)}</div></div>
      <div class="forensic-4layer-row"><span class="forensic-4layer-label">What Nalu found</span><div class="forensic-4layer-text">${escHtml(found)}</div></div>
      <div class="forensic-4layer-row"><span class="forensic-4layer-label">Why it matters</span><div class="forensic-4layer-text">${escHtml(matters)}</div></div>
      <div class="forensic-4layer-row forensic-4layer-row--caveat"><span class="forensic-4layer-label">What it does NOT prove</span><div class="forensic-4layer-text">${escHtml(doesNotProve)}</div></div>
    </div>`;
}

/** Standardized state vocabulary (Inspector-wide roadmap item #8) for each
 *  Forensic Suite engine's own accordion badge — previously these 5
 *  badges (badge-benfords/entropy/zipf/timeseries/granger) were never
 *  populated by any code at all, permanently blank regardless of what the
 *  engine actually found. "Insufficient Data" is deliberately its own
 *  distinct label, never "Normal" — the same N/A-vs-Normal distinction
 *  already applied to Spoofing/Market-Making: a verdict of 'insufficient'
 *  means the engine had too little history to run at all, not that it ran
 *  and found nothing. */
function _setForensicEngineBadge(badgeId, verdict) {
  const el = document.getElementById(badgeId);
  if (!el) return;
  const map = {
    insufficient:        ['Insufficient Data', 'neutral'],
    normal:               ['Normal', 'ok'],
    elevated:             ['Elevated', 'warn'],
    anomalous:            ['Anomalous', 'crit'],
    'strong-coupling':    ['Strong Coupling', 'crit'],
    'high-deviation':     ['High Deviation', 'crit'],
    'moderate-deviation': ['Moderate', 'warn'],
  };
  const [label, tone] = map[verdict] || ['—', 'neutral'];
  el.textContent = label;
  el.className = 'section-badge section-badge--' + tone;
}

function _forensicMeta(rows) {
  return `<div class="wash-stat-row" style="margin-top:10px;opacity:.5;font-size:.78rem">
    ${rows.map(([k,v,cls]) => `<span>${k}</span><span class="mono ${cls||''}">${v}</span>`).join('')}
  </div>` + rows.map(([k,v,cls]) => `
    <div class="wash-stat-row">
      <span>${k}</span><span class="mono ${cls||''}">${v}</span>
    </div>`).join('');
}

function renderEntropyPanel(a) {
  const rows = [
    ['Sample size', a.sampleSize],
    ['Amount entropy', a.amountEntropy != null ? a.amountEntropy.toFixed(2) + ' bits' : '—',
      a.amountEntropy != null && a.amountEntropy < 2.0 ? 'risk-text-high' : ''],
    ['Counterparty entropy', a.counterpartyEntropy != null ? a.counterpartyEntropy.toFixed(2) + ' bits' : '—'],
    ['Time-of-day entropy', a.timeEntropy != null ? a.timeEntropy.toFixed(2) + ' bits' : '—'],
    ['Unique counterparties', a.uniqueCounterparties],
    ['Verdict', a.verdict,
      a.verdict === 'anomalous' ? 'risk-text-high' : a.verdict === 'elevated' ? 'risk-text-med' : ''],
  ];
  const parts = [];
  if (a.amountEntropy != null) parts.push(`amount entropy ${a.amountEntropy.toFixed(2)} bits (natural range ~2.4–4.2)`);
  if (a.counterpartyEntropy != null) parts.push(`counterparty entropy ${a.counterpartyEntropy.toFixed(2)} bits`);
  if (a.timeEntropy != null) parts.push(`time-of-day entropy ${a.timeEntropy.toFixed(2)} bits`);
  const found = parts.length
    ? `${parts.join(', ')}. Overall verdict: ${a.verdict}.`
    : `Not enough transactions yet to measure entropy reliably (needs 30+).`;

  _renderForensicPanel('inspect-entropy-body', a,
    `<div class="wash-stat-row" style="margin-top:10px"><span>Metric</span><span class="mono" style="opacity:.45">Value</span></div>` +
    rows.map(([k,v,cls]) => `<div class="wash-stat-row"><span>${k}</span><span class="mono ${cls||''}">${v}</span></div>`).join(''),
    {
      checks: 'How random/unpredictable this account\'s transaction amounts, counterparties, and timing are, measured in bits of entropy.',
      found,
      matters: 'Very low entropy (little variation) in amounts, counterparties, or timing can indicate scripted, repetitive, or bot-driven activity rather than organic human decision-making.',
      doesNotProve: 'A business with a fixed, repeated payment schedule (subscriptions, payroll, or a market maker\'s standard order size) will also show low entropy — this measures predictability, not intent, and is a supporting signal only.',
    });
  _setForensicEngineBadge('badge-entropy', a.verdict);
}

function renderZipfPanel(a) {
  const rows = [
    ['Unique counterparties', a.uniqueCounterparties],
    ['Zipf exponent (s)', a.zipfExponent != null ? a.zipfExponent.toFixed(3) : '—',
      a.zipfExponent != null && (a.zipfExponent < 0.4 || a.zipfExponent > 2.2) ? 'risk-text-high' : ''],
    ['Fit quality (R²)', a.rSquared != null ? a.rSquared.toFixed(3) : '—',
      a.rSquared != null && a.rSquared < 0.55 ? 'risk-text-high' : ''],
    ['Natural range', 's ≈ 0.8–1.3, R² > 0.55'],
    ['Verdict', a.verdict,
      a.verdict === 'anomalous' ? 'risk-text-high' : a.verdict === 'elevated' ? 'risk-text-med' : ''],
  ];

  // Rank-frequency mini chart
  const chartRows = a.freqTable?.slice(0, 10).map((f, i) => {
    const maxF = a.freqTable[0] || 1;
    const pct  = (f / maxF * 100).toFixed(0);
    const zipfExpected = a.freqTable[0] ? (a.freqTable[0] / Math.pow(i+1, a.zipfExponent||1)).toFixed(1) : 0;
    return `<div class="wash-stat-row">
      <span class="mono" style="min-width:28px">Rank ${i+1}</span>
      <div style="flex:1;height:6px;background:rgba(255,255,255,.06);border-radius:3px;overflow:hidden;margin:0 8px">
        <div style="height:100%;width:${pct}%;background:var(--accent);border-radius:3px"></div>
      </div>
      <span class="mono" style="opacity:.6">${f}</span>
    </div>`;
  }).join('') || '';

  const found = a.zipfExponent != null
    ? `Zipf exponent ${a.zipfExponent.toFixed(3)} (natural range ~0.8–1.3), fit quality R²=${a.rSquared?.toFixed(3) ?? '—'} across ${a.uniqueCounterparties} counterparties. Verdict: ${a.verdict}.`
    : `Not enough distinct counterparties yet to fit this pattern reliably.`;

  _renderForensicPanel('inspect-zipf-body', a,
    rows.map(([k,v,cls]) => `<div class="wash-stat-row" style="margin-top:${k==='Unique counterparties'?10:0}px"><span>${k}</span><span class="mono ${cls||''}">${v}</span></div>`).join('') +
    (chartRows ? `<div style="margin-top:14px;opacity:.75;font-size:.72rem;letter-spacing:.08em;color:rgba(255,255,255,.45);margin-bottom:6px">COUNTERPARTY RANK–FREQUENCY</div>${chartRows}` : ''),
    {
      checks: 'Whether this account\'s transaction volume across its counterparties follows the natural rank-frequency pattern (Zipf\'s Law) real organic networks show — a few big relationships, many small ones.',
      found,
      matters: 'A distribution far outside the natural range can indicate an artificially engineered counterparty network — volume concentrated more (or spread more evenly) than an organic network would produce.',
      doesNotProve: 'A poor fit (low R²) most often just means there isn\'t enough counterparty data for the pattern to emerge either way — it is inconclusive, not evidence of a problem. A young or small-network account naturally fits this test poorly.',
    });
  _setForensicEngineBadge('badge-zipf', a.verdict);
}

function renderTimeSeriesPanel(a) {
  const rows = [
    ['Transactions timed', a.totalTimestamped || '—'],
    ['Active span', a.activeSpanDays != null ? a.activeSpanDays + ' days' : '—'],
    ['Interval CV', a.intervalCV != null ? a.intervalCV.toFixed(3) : '—',
      a.intervalCV != null && a.intervalCV < 0.5 ? 'risk-text-high' : ''],
    ['Periodicity score', a.periodicityScore != null ? (a.periodicityScore*100).toFixed(0)+'%' : '—',
      a.periodicityScore > 0.55 ? 'risk-text-high' : ''],
    ['Burst score (z)', a.burstScore != null ? a.burstScore.toFixed(2) : '—'],
    ['Lag-1 autocorrelation', a.autocorrelation != null ? a.autocorrelation.toFixed(3) : '—',
      a.autocorrelation > 0.6 ? 'risk-text-med' : ''],
    ['Day-of-week entropy', a.dowEntropy != null ? a.dowEntropy.toFixed(2)+' bits' : '—'],
    ['Verdict', a.verdict,
      a.verdict === 'elevated' ? 'risk-text-med' : ''],
  ];

  // Day-of-week mini chart
  const days = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
  const maxDow = a.dowBins ? Math.max(...a.dowBins, 1) : 1;
  const dowChart = a.dowBins ? `
    <div style="margin-top:14px;opacity:.75;font-size:.72rem;letter-spacing:.08em;color:rgba(255,255,255,.45);margin-bottom:6px">DAY-OF-WEEK DISTRIBUTION</div>
    <div style="display:flex;gap:5px;align-items:flex-end;height:42px">
      ${a.dowBins.map((v, i) => `
        <div style="flex:1;display:flex;flex-direction:column;align-items:center;gap:3px">
          <div style="width:100%;height:${(v/maxDow*36).toFixed(0)}px;background:rgba(0,212,255,.35);border-radius:2px 2px 0 0;min-height:2px"></div>
          <div style="font-size:.6rem;opacity:.5">${days[i]}</div>
        </div>`).join('')}
    </div>` : '';

  const found = a.intervalCV != null
    ? `Interval CV ${a.intervalCV.toFixed(3)} (bot-level below 0.25), periodicity ${(a.periodicityScore*100).toFixed(0)}%, burst score ${a.burstScore?.toFixed(2) ?? '—'}. Verdict: ${a.verdict}.`
    : `Not enough timestamped transactions yet to measure timing regularity reliably.`;

  _renderForensicPanel('inspect-timeseries-body', a,
    rows.map(([k,v,cls]) => `<div class="wash-stat-row" style="margin-top:${k==='Transactions timed'?10:0}px"><span>${k}</span><span class="mono ${cls||''}">${v}</span></div>`).join('') +
    dowChart,
    {
      checks: 'Whether this account\'s transaction timing shows natural human irregularity, or the tight, repeating rhythm typical of automation.',
      found,
      matters: 'Extremely regular timing (very low interval variability, strong periodicity) is one of the clearest behavioral signatures of an automated script rather than a person manually initiating each transaction.',
      doesNotProve: 'Automation is not itself wrongdoing — legitimate bots, market makers, and scheduled payment systems are timing-regular by design. This establishes "likely automated," never "malicious." Cross-reference with Wash Trading\'s own Market-Making read.',
    });
  _setForensicEngineBadge('badge-timeseries', a.verdict);
}

function renderGrangerPanel(a) {
  const oc = a.offerCancelCausality;
  const io = a.inflowOutflowCausality;

  const ccfBars = (ccf, label) => {
    if (!ccf?.length) return '';
    const maxV = Math.max(0.01, ...ccf.map(Math.abs));
    return `<div style="margin-top:12px;opacity:.75;font-size:.72rem;letter-spacing:.08em;color:rgba(255,255,255,.45);margin-bottom:6px">${label}</div>
    <div style="display:flex;gap:4px;align-items:flex-end;height:40px">
      ${ccf.map((v, lag) => {
        const h = (Math.abs(v)/maxV*36).toFixed(0);
        const c = v > 0.5 ? 'rgba(255,85,85,.7)' : v > 0.3 ? 'rgba(255,184,108,.6)' : 'rgba(0,212,255,.3)';
        return `<div style="flex:1;display:flex;flex-direction:column;align-items:center;gap:3px">
          <div style="width:100%;height:${h}px;background:${c};border-radius:2px 2px 0 0;min-height:2px"></div>
          <div style="font-size:.6rem;opacity:.5">L${lag}</div>
        </div>`;
      }).join('')}
    </div>`;
  };

  const rows = [
    ['Time windows', a.windowCount || '—'],
    ['OfferCreate↔Cancel ρ', oc ? oc.maxCorr.toFixed(3) : '—', oc && oc.maxCorr > 0.55 ? 'risk-text-high' : ''],
    ['OC lag', oc ? `${oc.maxLag} window${oc.maxLag===1?'':'s'} (${oc.maxLag*12}h)` : '—'],
    ['Inflow↔Outflow ρ', io ? io.maxCorr.toFixed(3) : '—', io && io.maxCorr > 0.65 ? 'risk-text-high' : ''],
    ['IO lag', io ? `${io.maxLag} window${io.maxLag===1?'':'s'}` : '—'],
    ['Verdict', a.verdict, a.verdict === 'strong-coupling' ? 'risk-text-high' : a.verdict === 'elevated' ? 'risk-text-med' : ''],
  ];

  const found = (oc || io)
    ? `${oc ? `Offer-create↔cancel correlation ${oc.maxCorr.toFixed(3)} at lag ${oc.maxLag} window(s). ` : ''}${io ? `Inflow↔outflow correlation ${io.maxCorr.toFixed(3)} at lag ${io.maxLag} window(s). ` : ''}Verdict: ${a.verdict}.`
    : `Not enough time-windowed activity yet to test for coupling.`;

  _renderForensicPanel('inspect-granger-body', a,
    rows.map(([k,v,cls]) => `<div class="wash-stat-row" style="margin-top:${k==='Time windows'?10:0}px"><span>${k}</span><span class="mono ${cls||''}">${v}</span></div>`).join('') +
    ccfBars(oc?.ccf, 'OFFER-CREATE ↔ CANCEL CROSS-CORRELATION') +
    ccfBars(io?.ccf, 'INFLOW ↔ OUTFLOW CROSS-CORRELATION'),
    {
      checks: 'Whether this account\'s offer-creation/cancellation activity and its inbound/outbound value flow move together in a statistically coupled way over time.',
      found,
      matters: 'Strong coupling between order behavior and value flow can indicate coordinated activity — e.g., placing and cancelling orders in a rhythm tied to when funds move, consistent with orchestrated trading rather than independent decisions.',
      doesNotProve: 'This is a co-movement/coupling signal, not a formal causality test (despite the module\'s informal name) — correlation is not causation. Ordinary trading naturally correlates order activity with fund movement; this alone does not establish coordination or intent.',
    });
  _setForensicEngineBadge('badge-granger', a.verdict);
}

/* ── Forensic Analytics Suite — Combined Report ──── */
function renderForensicSuitePanel(benfords, entropy, zipf, timeSeries, granger) {
  const body = document.getElementById('inspect-forensic-suite-body');
  if (!body) return;

  const score = (a, max = 25) => {
    if (!a || a.verdict === 'insufficient') return null;
    // normalize riskPenalty (or chiSq for Benford) to 0-max
    if (a.chiSq != null) {
      // Benford
      if (a.verdict === 'high-deviation') return { val: max, cls: 'risk-text-high', label: 'HIGH DEVIATION' };
      if (a.verdict === 'moderate-deviation') return { val: Math.round(max * 0.5), cls: 'risk-text-med', label: 'MODERATE' };
      return { val: 0, cls: '', label: 'NORMAL' };
    }
    const v = a.riskPenalty || 0;
    if (v >= 18) return { val: max, cls: 'risk-text-high', label: 'ANOMALOUS' };
    if (v >= 8)  return { val: Math.round(max * 0.5), cls: 'risk-text-med', label: 'ELEVATED' };
    return { val: 0, cls: '', label: 'NORMAL' };
  };

  const engines = [
    { name: "Benford's Law",     icon: '📐', desc: 'First-digit digit distribution vs log-uniform expected',                      s: score(benfords)      },
    { name: "Shannon's Entropy", icon: '🔀', desc: 'Randomness of amounts, counterparties, time-of-day, tx types',               s: score(entropy)       },
    { name: "Zipf's Law",        icon: '📈', desc: 'Counterparty rank-frequency power-law fit',                                   s: score(zipf)          },
    { name: "Time Series",       icon: '🕐', desc: 'Interval regularity, periodicity, burst detection, autocorrelation',          s: score(timeSeries)    },
    { name: "Offer/Flow Coupling", icon: '🔗', desc: 'Cross-correlation, not causality: offer create↔cancel, inflow↔outflow',    s: score(granger)       },
  ];

  const anySignal   = engines.some(e => e.s && e.s.val > 0);
  const highCount   = engines.filter(e => e.s?.cls === 'risk-text-high').length;
  const medCount    = engines.filter(e => e.s?.cls === 'risk-text-med').length;
  const missingData = engines.filter(e => !e.s).length;

  // ── Overall verdict ────────────────────────────────
  let suiteVerdict, suiteColor, suiteIcon;
  if (highCount >= 3) {
    suiteVerdict = 'STRONG MANIPULATION SIGNALS — Multiple independent engines converging on anomalous patterns.';
    suiteColor = '#ff5555'; suiteIcon = '🚨';
  } else if (highCount >= 2 || (highCount >= 1 && medCount >= 2)) {
    suiteVerdict = 'SIGNIFICANT ANOMALIES — At least two engines detect non-organic behavior. Cross-reference with Wash Trading and Drain Risk.';
    suiteColor = '#ff5555'; suiteIcon = '⚠️';
  } else if (highCount >= 1 || medCount >= 2) {
    suiteVerdict = 'ELEVATED RISK — One or more engines flag behavioral anomalies. Investigate the specific modules for detail.';
    suiteColor = '#ffb86c'; suiteIcon = '⚠️';
  } else if (!anySignal && missingData < 3) {
    suiteVerdict = 'NO ANOMALIES — All five engines return results consistent with organic financial activity.';
    suiteColor = '#50fa7b'; suiteIcon = '✅';
  } else {
    suiteVerdict = 'INSUFFICIENT DATA — More transaction history needed for a reliable multi-engine assessment.';
    suiteColor = 'rgba(255,255,255,.4)'; suiteIcon = '📊';
  }

  // ── Engine score cards ─────────────────────────────
  const engineCards = engines.map(e => {
    const noData = !e.s;
    const color  = noData ? 'rgba(255,255,255,.25)' : e.s.val === 0 ? '#50fa7b' : e.s.cls === 'risk-text-high' ? '#ff5555' : '#ffb86c';
    const label  = noData ? 'NO DATA' : e.s.label;
    const barPct = noData ? 0 : e.s.val === 0 ? 4 : e.s.cls === 'risk-text-high' ? 100 : 55;
    return `<div style="background:rgba(255,255,255,.025);border:1px solid rgba(255,255,255,.07);border-radius:12px;padding:14px 14px 12px">
      <div style="display:flex;align-items:center;gap:8px;margin-bottom:8px">
        <span style="font-size:1.05rem">${e.icon}</span>
        <div style="flex:1">
          <div style="font-size:.82rem;font-weight:700;color:rgba(255,255,255,.85)">${e.name}</div>
          <div style="font-size:.7rem;color:rgba(255,255,255,.35);margin-top:1px;line-height:1.4">${e.desc}</div>
        </div>
      </div>
      <div style="display:flex;align-items:center;gap:8px">
        <div style="flex:1;height:5px;background:rgba(255,255,255,.08);border-radius:3px;overflow:hidden">
          <div style="height:100%;width:${barPct}%;background:${color};border-radius:3px;transition:width .6s ease"></div>
        </div>
        <span style="font-size:.65rem;font-weight:800;color:${color};min-width:80px;text-align:right;letter-spacing:.06em">${label}</span>
      </div>
    </div>`;
  }).join('');

  // ── Convergence narrative ──────────────────────────
  const convergingEngines = engines.filter(e => e.s && e.s.val > 0);
  let narrative = '';
  if (convergingEngines.length >= 2) {
    narrative = `<div style="background:rgba(255,184,108,.05);border:1px solid rgba(255,184,108,.2);border-radius:12px;padding:14px 16px;margin-top:14px">
      <div style="font-size:.68rem;font-weight:900;color:#ffb86c;letter-spacing:.12em;text-transform:uppercase;margin-bottom:8px">⚡ Convergence Analysis</div>
      <p style="font-size:.84rem;color:rgba(255,255,255,.65);line-height:1.7;margin:0">
        ${convergingEngines.map(e => e.name).join(' and ')} are all flagging behavioral anomalies.
        When multiple independent statistical methods converge on the same conclusion — each using
        different mathematical principles — the combined signal is substantially stronger than any
        single engine alone. This convergence reduces the probability that the findings are false positives
        from sample-specific artifacts or edge cases.
        ${highCount >= 2 ? ' The strength and breadth of these signals warrants serious investigation.' : ' Monitor alongside the Wash Trading and Security modules for a complete picture.'}
      </p>
    </div>`;
  } else if (anySignal) {
    narrative = `<div style="background:rgba(0,212,255,.04);border:1px solid rgba(0,212,255,.12);border-radius:12px;padding:14px 16px;margin-top:14px">
      <p style="font-size:.84rem;color:rgba(255,255,255,.55);line-height:1.7;margin:0">
        Only one engine is currently flagging anomalies. A single-engine signal is a hypothesis, not a conclusion.
        Cross-reference with Wash Trading, Benford's Law, and Drain Risk modules to determine whether
        the pattern is isolated or part of a broader behavioral signature.
      </p>
    </div>`;
  } else {
    narrative = `<div style="background:rgba(80,250,123,.04);border:1px solid rgba(80,250,123,.12);border-radius:12px;padding:14px 16px;margin-top:14px">
      <p style="font-size:.84rem;color:rgba(255,255,255,.55);line-height:1.7;margin:0">
        No engine in the forensic suite has flagged this account.
        The five methods use independent mathematical frameworks —
        digit distribution (Benford), information theory (entropy), power laws (Zipf),
        temporal statistics (time series), and cross-correlation (offer/flow coupling).
        Agreement across all five is a strong indicator of organic activity.
      </p>
    </div>`;
  }

  body.innerHTML = `
    <div style="background:rgba(${suiteColor==='#ff5555'?'255,85,85':'255,255,255'},.04);border:1px solid rgba(${suiteColor==='#ff5555'?'255,85,85':'255,255,255'},.15);border-radius:12px;padding:14px 16px;margin-bottom:14px;display:flex;align-items:flex-start;gap:12px">
      <span style="font-size:1.4rem;flex-shrink:0;margin-top:2px">${suiteIcon}</span>
      <div>
        <div style="font-size:.68rem;font-weight:900;letter-spacing:.12em;text-transform:uppercase;color:${suiteColor};margin-bottom:5px">FORENSIC SUITE VERDICT</div>
        <p style="font-size:.88rem;color:rgba(255,255,255,.7);line-height:1.65;margin:0">${suiteVerdict}</p>
      </div>
    </div>
    <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:10px">
      ${engineCards}
    </div>
    ${narrative}`;
    // A static "How to read this suite" box used to sit here, restating the
    // same single/two/three-engine threshold logic the narrative above
    // already explains — contextually, for whichever case actually
    // occurred — plus repeating the "not legal proof" disclaimer this
    // report already states once, up top. Removed rather than reworded:
    // there was nothing left to say that the narrative above didn't
    // already cover better.
}

/* ── Header / Overview ───────────────────────────── */
function renderHeader(addr, acct, balXrp, reserve, ownerCnt, sequence, riskScore, walletAgeDays = null, walletCreatedTs = null, walletAgeVerified = false, walletActivationEvidence = null, accountLifetimeHistory = null) {
  // Address badge: display shortened, full addr in title + dataset for copy
  const badge = $('inspect-addr-badge');
  if (badge) {
    badge.textContent = addr.length > 20 ? addr.slice(0,10) + '…' + addr.slice(-8) : addr;
    badge.title = addr;
    badge.dataset.fullAddr = addr;
  }

  // Risk score
  const scoreEl = $('inspect-risk-score');
  if (scoreEl) {
    scoreEl.textContent = riskScore;
    scoreEl.className = 'irb-score-val ' + riskScoreClass(riskScore);
  }
  const scoreLabelEl = $('inspect-risk-label');
  if (scoreLabelEl) {
    scoreLabelEl.textContent = riskScore < 20 ? 'Low Risk'
      : riskScore < 45 ? 'Moderate'
      : riskScore < 70 ? 'High Risk'
      : 'Critical';
    scoreLabelEl.className = 'irb-score-label ' + riskScoreClass(riskScore);
  }

  // Account grid
  const grid = $('inspect-acct-grid');
  if (!grid) return;

  const spendable = Math.max(0, balXrp - reserve);
  const flags = Number(acct.Flags || 0);
  // An AMM pool's own AccountRoot always carries an AMMID field — ordinary
  // human-wallet age interpretation ("⚠ New wallet") doesn't apply: a pool
  // is created the moment its AMM is, which says nothing about risk the
  // way a brand-new personal wallet receiving funds would. (Newer rippled
  // versions also return a sibling top-level `pseudo_account` field on
  // account_info, but `acct` here is bound to just `result.account_data` —
  // AMMID alone, which DOES live inside account_data, is the reliable
  // signal with the data already in hand.)
  const isAmmPseudoAccount = !!acct.AMMID;

  // Wallet age string — "At least X" rather than a bare number whenever the
  // figure is only a lower bound (pagination/genesis-event not confirmed).
  // A precise "1 day old" must only ever come from real verified evidence —
  // see _findAccountRootCreationEvidence; this is what stops an unconfirmed
  // oldest-fetched-tx estimate from reading as a confident, false claim.
  const ageStr = walletAgeDays == null ? '—'
    : walletAgeVerified
      ? (walletAgeDays === 0 ? 'Created today'
        : walletAgeDays === 1 ? '1 day old'
        : walletAgeDays < 30  ? `${walletAgeDays} days old`
        : walletAgeDays < 365 ? `${Math.floor(walletAgeDays / 30)} months old`
        : `${(walletAgeDays / 365).toFixed(1)} years old`)
      : (walletAgeDays < 1 ? 'Unknown'
        : walletAgeDays === 1 ? 'At least 1 day'
        : walletAgeDays < 30  ? `At least ${walletAgeDays} days`
        : walletAgeDays < 365 ? `At least ${Math.floor(walletAgeDays / 30)} months`
        : `At least ${(walletAgeDays / 365).toFixed(1)} years`);

  const createdStr = walletCreatedTs
    ? new Date(walletCreatedTs).toLocaleDateString('en-US', { year:'numeric', month:'short', day:'numeric' })
    : null;
  // Oldest-fetched-transaction age is only as good as whether pagination
  // actually reached this account's genesis transaction — flag it plainly
  // when that wasn't confirmed, rather than presenting an estimate as fact.
  // This is what catches a "0-day-old wallet, 5,200 transactions analyzed"
  // read that's actually a truncated fetch, not a genuinely brand-new account.
  // A deleted-and-recreated address needs its own framing per spec: the
  // current AccountRoot's age must never be conflated with the address's
  // full historical existence — someone funding a previously-deleted
  // address today is operating a genuinely different account in substance,
  // sharing only the address string with whatever existed there before.
  const deletedAndRecreated = !!accountLifetimeHistory?.deletedAndRecreated;
  const earliestKnown = accountLifetimeHistory?.earliestKnownHistory;
  const earliestKnownStr = earliestKnown?.createdAt != null
    ? new Date((earliestKnown.createdAt + 946684800) * 1000).toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' })
    : null;

  // Terminology precision (roadmap: first-seen disambiguation): "Account
  // Activated" (real AccountRoot creation evidence or fully-verified
  // pagination) is a materially different claim from "Known Active Since"
  // (a lower bound — the earliest activity we happened to fetch, with no
  // confirmation it reaches the account's true start). The previous wording
  // here ("Earliest verified activity... unconfirmed") called the SAME date
  // both verified and unconfirmed in one sentence — confusing on its own
  // terms, not just imprecise relative to the spec.
  const ageNote = createdStr
    ? walletAgeVerified
      ? (walletActivationEvidence
          ? (deletedAndRecreated ? `Current AccountRoot recreated ${createdStr} — verified` : `Activated ${createdStr} — verified via AccountRoot creation`)
          : `Created ${createdStr}`)
      : `Known active since ${createdStr} — true activation date unconfirmed`
    : null;
  const recreationNote = deletedAndRecreated && earliestKnownStr
    ? `ℹ This address was previously deleted and later recreated. Earlier address history first observed ${earliestKnownStr} (not part of the current account's age).`
    : null;
  // Full evidence chain for the real-verification case — hover tooltip
  // rather than a new expandable widget, matching this grid's existing
  // "note" line as the only secondary-detail surface it has.
  const ageTitle = walletActivationEvidence
    ? [
        deletedAndRecreated ? 'Current AccountRoot creation verified from ledger metadata (address was previously deleted and recreated)' : 'AccountRoot creation verified from ledger metadata',
        walletActivationEvidence.ledgerIndex != null ? `Ledger: ${walletActivationEvidence.ledgerIndex}` : null,
        walletActivationEvidence.transactionHash ? `Transaction: ${walletActivationEvidence.transactionHash}` : null,
        walletActivationEvidence.fundingAccount ? `Funded by: ${walletActivationEvidence.fundingAccount}` : null,
        walletActivationEvidence.initialBalanceDrops != null ? `Initial funding: ${fmt(Number(walletActivationEvidence.initialBalanceDrops) / 1e6, 6)} XRP` : null,
        deletedAndRecreated && earliestKnownStr ? `Earlier address history first observed: ${earliestKnownStr}` : null,
      ].filter(Boolean).join('\n')
    : null;

  const usdBalance   = _usd(balXrp);
  const usdSpendable = _usd(spendable);

  // Mirror into the Command Bar's compact state group (desktop shell) —
  // same already-computed balXrp/ageStr as the grid cells below, never
  // recomputed, so the two can never drift out of sync.
  const irbBalance = $('irb-balance');
  if (irbBalance) irbBalance.textContent = `${fmt(balXrp, 2)} XRP`;
  const irbAge = $('irb-age');
  if (irbAge) irbAge.textContent = ageStr;

  const cells = [
    { label: 'XRP Balance',  value: `${fmt(balXrp, 6)} XRP${usdBalance}`,   mono: true,
      detail: `Spendable: ${fmt(spendable, 6)} XRP${usdSpendable} · ${reserve} XRP held as this account's ledger reserve (not spendable).` },
    { label: 'Spendable',    value: `${fmt(spendable, 6)} XRP${usdSpendable}`, mono: true, note: `${reserve} XRP reserved`,
      detail: `Total balance minus the ${reserve} XRP base + owner-count reserve the XRP Ledger requires this account to hold at all times.` },
    { label: 'Wallet Age',   value: ageStr,
      note: [ageNote, recreationNote].filter(Boolean).join(' '),
      title: ageTitle,
      detail: ageTitle || (walletAgeVerified ? 'Confirmed from complete fetched transaction history.' : 'A lower bound only — the connected server\'s history may not reach this account\'s true genesis.'),
      // Gated on walletAgeVerified too — an unconfirmed low day-count (e.g.
      // pagination never reached genesis) must never render the same scare
      // badge as a cryptographically-proven brand-new account. Unverified
      // age is a lower bound, not evidence of newness.
      highlight: !isAmmPseudoAccount && walletAgeVerified && walletAgeDays != null && walletAgeDays < 7 ? 'new' : null },
    { label: 'Owner Count',  value: ownerCnt,                                  note: `${ownerCnt * 2} XRP tied up`,
      detail: `Each ledger object this account owns (trustlines, offers, signer lists, etc.) locks ${ownerCnt * 2} XRP total out of this account's spendable balance.` },
    { label: 'Sequence',     value: sequence,                                  mono: true,
      detail: 'The next transaction this account submits must use exactly this Sequence number — a lower bound on how many transactions it has ever sent.' },
    { label: 'Regular Key',  value: acct.RegularKey ? shortAddr(acct.RegularKey) : 'None',
      warn: !!acct.RegularKey, mono: true,
      detail: acct.RegularKey ? 'An alternate signing key for this account — see Account Compromise Risk below for whether its setter is confirmed.' : 'No alternate signing key is configured — only the master key can sign for this account.' },
    { label: 'Master Key',   value: (flags & FLAGS.lsfDisableMaster) ? 'Disabled' : 'Active',
      warn: !!(flags & FLAGS.lsfDisableMaster),
      detail: (flags & FLAGS.lsfDisableMaster)
        ? 'Not itself a risk signal — a disabled master key paired with an active Regular Key is a recognized self-custody hardening pattern.'
        : 'The account\'s original signing key is active and can authorize any transaction directly.' },
  ];

  grid.innerHTML = cells.map(c => `
    <div class="acct-cell ${c.warn ? 'acct-cell--warn' : ''} ${c.highlight === 'new' ? 'acct-cell--new' : ''}" ${c.detail ? 'tabindex="0"' : ''} ${c.title ? `title="${escHtml(c.title)}"` : ''}>
      <div class="acct-cell-label">${escHtml(c.label)}</div>
      <div class="acct-cell-value ${c.mono ? 'mono' : ''}">${escHtml(String(c.value))}</div>
      ${c.note ? `<div class="acct-cell-note">${escHtml(c.note)}</div>` : ''}
      ${c.detail ? `<div class="acct-cell-detail"><div class="acct-cell-detail-inner">${escHtml(c.detail)}</div></div>` : ''}
      ${c.highlight === 'new' ? '<div class="acct-cell-new-badge">⚠ New wallet</div>' : ''}
    </div>`).join('');
}

/* ── Security Audit ──────────────────────────────── */
// A sequence of events reads very differently from the same events shown
// as separate, unordered findings — "RegularKey changed, then 85% XRP
// moved 7 minutes later" is a materially stronger statement than either
// fact alone, and previously this exact narrative only existed as prose
// embedded inside the Drain Risk module's own findings. This builds it as
// its own artifact: every auth/key-structure change this account's history
// contains (SetRegularKey, SignerListSet, master-key disable/enable,
// AccountDelete attempts), cross-referenced against drain episodes already
// computed elsewhere in the pipeline — no new RPC calls — to note when a
// balance-movement episode began shortly after. Returns [] (rendering
// nothing) for the common case of an account whose auth structure has
// never changed, rather than manufacturing a timeline out of nothing.
function buildSecurityTimeline(controlState, txList, addr, drainEpisodes = []) {
  const events = [];

  for (const { tx } of txList) {
    if (tx.TransactionType === 'SetRegularKey') {
      events.push({
        date: tx.date, hash: tx.hash, icon: '🔑',
        label: tx.RegularKey ? `Regular key set to ${shortAddr(tx.RegularKey)}` : 'Regular key removed',
        detail: tx.Account === addr ? 'Submitted by this account itself.' : `Submitted by ${shortAddr(tx.Account)} — not this account.`,
      });
    } else if (tx.TransactionType === 'SignerListSet') {
      events.push({
        date: tx.date, hash: tx.hash, icon: '👥',
        label: tx.SignerQuorum ? `Signer list configured (quorum ${tx.SignerQuorum})` : 'Signer list removed',
        detail: null,
      });
    } else if (tx.TransactionType === 'AccountDelete') {
      events.push({ date: tx.date, hash: tx.hash, icon: '⚠', label: 'AccountDelete attempted', detail: null });
    }
  }
  for (const h of controlState.masterKeyHistory || []) {
    events.push({
      date: h.date, hash: h.hash, icon: h.action === 'disabled' ? '🔒' : '🔓',
      label: `Master key ${h.action}`, detail: null,
    });
  }

  if (!events.length) return [];

  // Cross-reference: did a drain episode start within 24h after this event?
  const FOLLOWUP_WINDOW_SEC = 86400;
  for (const ev of events) {
    if (ev.date == null) continue;
    const followEp = (drainEpisodes || []).find(ep => ep.startDate >= ev.date && ep.startDate - ev.date <= FOLLOWUP_WINDOW_SEC);
    if (followEp) {
      const mins = Math.round((followEp.startDate - ev.date) / 60);
      ev.followedBy = `${mins < 120 ? `${mins} minute(s)` : `${(mins / 60).toFixed(1)} hour(s)`} later: a ${followEp.classification} episode moved ${fmt(followEp.grossOutflowXrp, 2)} XRP (${(followEp.actualDepletionPct * 100).toFixed(0)}% of balance depleted).`;
    }
  }

  return events.filter(e => e.date != null).sort((a, b) => a.date - b.date);
}

/** Canonical "Important Events" timeline (Inspector-wide roadmap item #7)
 *  — merges already-computed dated events from Security (auth/key
 *  changes), Drain Risk (episodes), and Fee Analysis (fee spikes) into ONE
 *  chronological list, each entry linking back to the section that
 *  actually explains it (via the existing _jumpToInspectorSection, no new
 *  navigation mechanism). Reuses buildSecurityTimeline's own output
 *  wholesale rather than re-deriving security events a second time — zero
 *  new analysis, zero new RPC calls. Deliberately scoped to these three
 *  sources for this pass: NFT/Memo/Volume-Concentration findings are
 *  pattern-level aggregates, not cleanly single-dated events, and folding
 *  them in would mean fabricating a date for something that isn't really
 *  one moment in time. */
function buildImportantEventsTimeline(securityTimeline, drainEpisodes, feeAnalysis) {
  const events = [];
  const FOLLOWUP_WINDOW_SEC = 86400;

  for (const ev of securityTimeline || []) {
    // "Related evidence" (roadmap item #18) — buildSecurityTimeline already
    // computes whether a drain episode started shortly after this event
    // (ev.followedBy); surface that as a chip too, not just prose.
    const related = ev.followedBy ? ['1 drain episode'] : [];
    events.push({ date: ev.date, hash: ev.hash, icon: ev.icon, label: ev.label, detail: ev.followedBy || ev.detail, module: 'Security', jumpTo: 'security', related });
  }

  for (const ep of (drainEpisodes || [])) {
    if (ep.startDate == null) continue;
    const kind = ep.classification === 'potential-drain' ? 'Potential drain' : ep.classification === 'sweep' ? 'Balance sweep' : 'Balance movement';
    // Related evidence: the destination breakdown Drain Risk already
    // computes for this exact episode, plus the reverse of the security
    // "followedBy" lookup above — was there an auth/key change shortly
    // BEFORE this episode started?
    const related = [];
    if (ep.destinations?.length) related.push(`${ep.destinations.length} destination${ep.destinations.length === 1 ? '' : 's'}`);
    const precedingSecurityEvent = (securityTimeline || []).find(sev => sev.date != null && sev.date <= ep.startDate && ep.startDate - sev.date <= FOLLOWUP_WINDOW_SEC);
    if (precedingSecurityEvent) related.push('1 security event nearby');
    events.push({
      date: ep.startDate, hash: null, icon: '🌊',
      label: `${kind}: ${fmt(ep.grossOutflowXrp, 2)} XRP moved`,
      detail: `${(ep.actualDepletionPct * 100).toFixed(0)}% of opening balance depleted`,
      module: 'Drain Risk', jumpTo: 'drain', related,
    });
  }

  // Only genuine spikes (>100x base fee) — topFeeHashes is a top-5-by-raw-
  // fee list, not all of which necessarily cleared the spike threshold.
  for (const h of (feeAnalysis?.topFeeHashes || [])) {
    if (h.date == null || Number(h.mult) < 100) continue;
    const overlappingEpisode = (drainEpisodes || []).find(ep => ep.startDate != null && ep.endDate != null && h.date >= ep.startDate && h.date <= ep.endDate);
    const related = overlappingEpisode ? ['1 drain episode'] : [];
    events.push({ date: h.date, hash: h.hash, icon: '💸', label: `Fee spike: ${h.mult}x base fee`, detail: null, module: 'Fee Analysis', jumpTo: 'fee-analysis', related });
  }

  return events.filter(e => e.date != null).sort((a, b) => a.date - b.date);
}

function renderImportantEventsTimeline(events) {
  const el = document.getElementById('inspect-events-body');
  const badge = document.getElementById('badge-events');
  if (!el) return;

  if (!events.length) {
    el.innerHTML = `<div class="inspect-empty-note">No dated events (security changes, drain episodes, or fee spikes) found in this account's analysed history.</div>`;
    if (badge) { badge.textContent = 'None'; badge.className = 'section-badge section-badge--ok'; }
    return;
  }

  el.innerHTML = `
    <div class="events-timeline">
      ${events.map(ev => `
        <div class="events-timeline-item" onclick="_jumpToInspectorSection('${ev.jumpTo}')" title="Jump to ${escHtml(ev.module)}">
          <div class="events-timeline-dot">${ev.icon}</div>
          <div class="events-timeline-body">
            <div class="events-timeline-date">${new Date((ev.date + XRPL_EPOCH) * 1000).toLocaleString()}</div>
            <div class="events-timeline-label">${escHtml(ev.label)}</div>
            ${ev.detail ? `<div class="events-timeline-detail">${escHtml(ev.detail)}</div>` : ''}
            ${ev.related?.length ? `<div class="events-timeline-related">Related: ${escHtml(ev.related.join(' · '))}</div>` : ''}
            <div class="events-timeline-module">${escHtml(ev.module)} →</div>
          </div>
        </div>`).join('')}
    </div>`;
  if (badge) { badge.textContent = `${events.length} event${events.length === 1 ? '' : 's'}`; badge.className = 'section-badge section-badge--neutral'; }
}

/** Security Audit's "In plain terms" summary (Inspector-wide roadmap item
 *  #10 — Simple/Explain/Analyst contract) — reuses the same
 *  _renderPlainSummaryBox shared renderer as Drain Risk/Wash Trading/
 *  Inbound Flow, and the same worst-severity-across-findings logic as
 *  every other section's Simple-mode reading. No new analysis. */
function buildSecurityPlainSummary(audit, cs) {
  const hasCrit = (audit?.findings || []).some(f => f.sev === 'critical');
  const hasWarn = (audit?.findings || []).some(f => f.sev === 'warn');
  const tone = hasCrit ? 'crit' : hasWarn ? 'warn' : 'ok';
  let text = hasCrit
    ? `This account's security configuration shows a critical concern — see the details below for exactly what changed.`
    : hasWarn
      ? `This account's security configuration shows something worth reviewing, though not necessarily alarming on its own.`
      : `Nothing about this account's current signing/authorization setup looks unusual.`;
  if (cs?.state && cs.state !== ACCOUNT_CONTROL_STATES.NORMAL) text += ` Its current control state is "${cs.state}."`;
  return { tone, text };
}

function renderSecurityAudit(audit, acct, flags, signerLists, depositAuths, txList = [], addr = null, drainEpisodes = [], historyCoverage = {}) {
  const el = $('inspect-security-body');
  if (!el) return;

  const decodedFlags = Object.entries(FLAGS)
    .filter(([, bit]) => flags & bit)
    .map(([name]) => name.replace('lsf', ''));

  const cs = audit.controlState;
  const stateColorMap = {
    Normal: '#50fa7b', 'Regular-Key Controlled': 'rgba(255,255,255,.7)', 'Multisig Controlled': 'rgba(255,255,255,.7)',
    Blackholed: 'rgba(255,255,255,.7)', Recoverable: 'rgba(255,255,255,.7)', 'Potentially Misconfigured': '#ff5555', Unknown: '#ffb86c',
  };
  const stateColor = cs ? (stateColorMap[cs.state] || 'rgba(255,255,255,.7)') : 'rgba(255,255,255,.7)';

  // Current configuration (static facts about how the account is set up
  // right now) vs. recent security changes (events) are different in kind —
  // a normal, unchanged configuration and a change to that configuration
  // carry different forensic weight even when the resulting state looks
  // identical. Anything without an explicit kind defaults to 'current' for
  // backward compatibility.
  const currentFindings = audit.findings.filter(f => (f.kind || 'current') === 'current');
  const changeFindings  = audit.findings.filter(f => f.kind === 'change');
  const timeline = buildSecurityTimeline(cs || {}, txList, addr, drainEpisodes);
  // An empty timeline on an account whose CURRENT state isn't the default
  // (blackholed, regular-key-controlled, multisig, ...) with incomplete
  // history is a real gap worth naming — the change that produced this
  // state may simply be older than the fetched window, not something that
  // never happened. Only worth the note when both conditions hold; a
  // Normal-state account or one with complete history needs no caveat.
  const historyLikelyIncomplete = !historyCoverage?.newestToOldestComplete && historyCoverage?.hitTxCap;
  const stateIsNonDefault = cs && cs.state !== ACCOUNT_CONTROL_STATES.NORMAL;
  const showTimelineGapNote = !timeline.length && stateIsNonDefault && historyLikelyIncomplete;
  const plainSummary = buildSecurityPlainSummary(audit, cs);

  el.innerHTML = `
    ${cs ? `
    <div class="drain-level" style="border-color:${stateColor}44;margin-bottom:10px" title="${escHtml(cs.reversibility)}">
      <span class="drain-level-icon" style="color:${stateColor}">●</span>
      <span class="drain-level-text">Account Control State: <strong style="color:${stateColor}">${escHtml(cs.state)}</strong></span>
    </div>` : ''}
    ${_renderPlainSummaryBox(plainSummary)}
    <div class="simple-only" style="font-size:.76rem;color:rgba(255,255,255,.4);padding:8px 2px;margin-bottom:6px">
      ${audit.findings.length} underlying finding${audit.findings.length === 1 ? '' : 's'} back the summary above — switch to <strong>⚗ Advanced</strong> (top of page) to see the full evidence for each.
    </div>
    <div class="advanced-only">
    ${changeFindings.length ? `
    <div class="wash-subpanel" style="margin-top:0;padding-top:0;border-top:none">
      <div class="wash-subpanel-header">
        <span class="wash-subpanel-title">🕒 Recent Security Changes</span>
        ${_miniBadgeHtml(changeFindings)}
      </div>
      <div class="wash-subpanel-blurb">Events, not static configuration — a change carries different forensic weight than the same resulting state having always been true.</div>
      <div class="audit-items">${changeFindings.map(f => auditRow(f)).join('')}</div>
    </div>` : ''}
    ${timeline.length ? `
    <div class="wash-subpanel">
      <div class="wash-subpanel-header"><span class="wash-subpanel-title">📜 Security Timeline</span></div>
      <div class="wash-subpanel-blurb">Every auth/key-structure change in this account's fetched history, in order — cross-referenced against Drain Risk episodes below when one began shortly after.</div>
      <div class="security-timeline">
        ${timeline.map(ev => `
          <div class="security-timeline-item">
            <div class="security-timeline-dot">${ev.icon}</div>
            <div class="security-timeline-body">
              <div class="security-timeline-date">${ev.date != null ? new Date((ev.date + 946684800) * 1000).toLocaleString() : 'Unknown date'}</div>
              <div class="security-timeline-label">${escHtml(ev.label)}</div>
              ${ev.detail ? `<div class="security-timeline-detail">${escHtml(ev.detail)}</div>` : ''}
              ${ev.followedBy ? `<div class="security-timeline-followup">⚠ ${escHtml(ev.followedBy)}</div>` : ''}
            </div>
          </div>`).join('')}
      </div>
    </div>` : ''}
    ${showTimelineGapNote ? `
    <div class="audit-applicability" style="background:rgba(255,255,255,.03);color:rgba(255,255,255,.4);border:1px dashed rgba(255,255,255,.15);margin-bottom:12px">
      <span class="audit-applicability-tag">Incomplete</span> This account's history hit the transaction fetch cap, so the change that produced its current "${escHtml(cs.state)}" state may be older than the fetched window — its absence from the timeline below is a data-coverage gap, not evidence the account has always been this way.
    </div>` : ''}
    <div class="wash-subpanel" style="${changeFindings.length || timeline.length ? '' : 'margin-top:0;padding-top:0;border-top:none'}">
      <div class="wash-subpanel-header"><span class="wash-subpanel-title">⚙ Current Configuration</span></div>
      <div class="audit-items">
        ${currentFindings.map(f => auditRow(f)).join('')}
      </div>
    </div>
    ${decodedFlags.length ? `
    <div class="audit-flags">
      <div class="audit-flags-label">Active Flags</div>
      <div class="audit-flags-pills">
        ${decodedFlags.map(f => `<span class="flag-pill">${escHtml(f)}</span>`).join('')}
      </div>
    </div>` : ''}
    ${signerLists.length ? `
    <div class="signer-list-block">
      <div class="signer-list-title">Signer List (Multisig)</div>
      ${signerLists.map(sl => `
        <div class="signer-entries">
          ${(sl.SignerEntries || []).map(e => `
            <div class="signer-entry">
              <span class="signer-addr mono">${escHtml(e.SignerEntry?.Account || '—')}</span>
              <span class="signer-weight">weight ${e.SignerEntry?.SignerWeight || 1}</span>
            </div>`).join('')}
          <div class="signer-quorum">Quorum: ${sl.SignerQuorum}</div>
        </div>`).join('')}
    </div>` : ''}
    ${depositAuths.length ? `
    <div class="audit-note">
      <span class="audit-note-label">DepositPreauth grants:</span>
      ${depositAuths.slice(0, 8).map(d => `<span class="mono">${shortAddr(d.Authorize || '')}</span>`).join(', ')}
      ${depositAuths.length > 8 ? `+${depositAuths.length - 8} more` : ''}
    </div>` : ''}
    </div>
  `;
  _setBadge('badge-security', audit.findings);
}

/* ── Drain Analysis ──────────────────────────────── */
/** Episode classification -> chart color, matching the severity language
 *  already established for these classifications in analyseAssetDrainBehavior
 *  (potential-drain reads as the most severe, pass-through as benign). */
const _DRAIN_CLASS_COLOR = {
  'potential-drain': 'rgba(255,85,85,.22)',
  'sweep': 'rgba(255,184,108,.20)',
  'pass-through': 'rgba(139,233,253,.14)',
  'partial-outflow': 'rgba(255,255,255,.10)',
};

/** Balance-over-time line chart with each drain episode's window shaded
 *  behind the line, colored by its classification — the reconstructed
 *  opening/peak/closing balance numbers already computed by
 *  analyseAssetDrainBehavior were previously only ever shown as text. */
function renderBalanceChart(balanceHistory, episodes, targetId) {
  const el = document.getElementById(targetId);
  if (!el) return;
  const points = (balanceHistory || []).filter(p => p.date != null).sort((a, b) => a.date - b.date);
  if (points.length < 2) { el.innerHTML = ''; return; }

  const RIPPLE_EPOCH = 946684800;
  const W = 720, H = 150, padL = 4, padR = 4, padT = 10, padB = 4;
  const minDate = points[0].date, maxDate = points[points.length - 1].date;
  const dateSpan = Math.max(1, maxDate - minDate);
  const balances = points.map(p => p.balanceAfter);
  const minBal = Math.min(0, ...balances), maxBal = Math.max(...balances, 1);
  const balSpan = Math.max(1, maxBal - minBal);

  const xOf = d => padL + ((d - minDate) / dateSpan) * (W - padL - padR);
  const yOf = b => padT + (1 - (b - minBal) / balSpan) * (H - padT - padB);
  const fmtDate = d => new Date((d + RIPPLE_EPOCH) * 1000).toISOString().slice(0, 10);

  const linePoints = points.map(p => `${xOf(p.date).toFixed(1)},${yOf(p.balanceAfter).toFixed(1)}`).join(' ');

  // Shade each episode's time window behind the line, colored by classification.
  const episodeRects = (episodes || []).map(ep => {
    const x1 = xOf(ep.startDate), x2 = xOf(ep.endDate);
    const color = _DRAIN_CLASS_COLOR[ep.classification] || _DRAIN_CLASS_COLOR['partial-outflow'];
    return `<rect x="${Math.min(x1, x2).toFixed(1)}" y="${padT}" width="${Math.max(2, Math.abs(x2 - x1)).toFixed(1)}" height="${H - padT - padB}" fill="${color}">
      <title>${escHtml(ep.classification)} — ${fmtDate(ep.startDate)} to ${fmtDate(ep.endDate)}</title></rect>`;
  }).join('');

  // Cap hoverable point markers for very long histories (thousands of
  // transactions) — the full-resolution line still draws, only the dense
  // per-point hover targets are sampled down, keeping the SVG light.
  const MAX_MARKERS = 150;
  const step = Math.max(1, Math.ceil(points.length / MAX_MARKERS));
  const markers = points.filter((_, i) => i % step === 0 || i === points.length - 1).map(p => {
    const tip = `${fmtDate(p.date)}\n${fmt(p.balanceAfter, 2)} XRP\n${p.type || ''}`;
    return `<circle cx="${xOf(p.date).toFixed(1)}" cy="${yOf(p.balanceAfter).toFixed(1)}" r="2.2" fill="#00d4ff" opacity=".55" data-tooltip="${escHtml(tip)}" style="cursor:pointer"></circle>`;
  }).join('');

  const legend = Object.keys(_DRAIN_CLASS_COLOR).some(cls => (episodes || []).some(ep => ep.classification === cls))
    ? `<div class="balance-chart-legend">${Object.entries(_DRAIN_CLASS_COLOR).filter(([cls]) => (episodes || []).some(ep => ep.classification === cls))
        .map(([cls, color]) => `<span class="balance-chart-legend-item"><span class="balance-chart-legend-swatch" style="background:${color}"></span>${escHtml(cls)}</span>`).join('')}</div>`
    : '';

  el.innerHTML = `
    <div style="font-size:.65rem;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:.08em;margin-bottom:6px">
      Balance Reconstruction — ${fmtDate(minDate)} to ${fmtDate(maxDate)} · peak ${fmt(maxBal, 2)} XRP
    </div>
    <div style="overflow-x:auto;touch-action:pan-x">
      <svg class="balchart-svg" viewBox="0 0 ${W} ${H}" width="100%" height="${H}" style="display:block;min-width:320px">
        ${episodeRects}
        <polyline points="${linePoints}" fill="none" stroke="#00d4ff" stroke-width="1.5" opacity=".85"></polyline>
        ${markers}
        <line class="balchart-crosshair" x1="0" y1="${padT}" x2="0" y2="${H - padB}" stroke="rgba(255,255,255,.22)" stroke-width="1" style="pointer-events:none;opacity:0"></line>
        <circle class="balchart-hover-dot" r="3.5" fill="#00d4ff" stroke="#0a0e16" stroke-width="1.5" style="pointer-events:none;opacity:0"></circle>
        <rect class="balchart-hover-capture" x="0" y="0" width="${W}" height="${H}" fill="transparent" style="cursor:crosshair"></rect>
      </svg>
    </div>
    ${legend}`;

  // Continuous hover-scrub: as the pointer moves anywhere over the chart
  // (not just the sampled marker dots), snap a crosshair + dot to the
  // nearest real data point and drive the shared chart tooltip with its
  // exact date/balance/type — makes the richest visual data in the
  // Inspector actually explorable, not just a static picture.
  const svg = el.querySelector('.balchart-svg');
  const capture = el.querySelector('.balchart-hover-capture');
  const crosshair = el.querySelector('.balchart-crosshair');
  const hoverDot = el.querySelector('.balchart-hover-dot');
  if (svg && capture && crosshair && hoverDot) {
    const nearestIdx = svgX => {
      const d = minDate + ((svgX - padL) / (W - padL - padR)) * dateSpan;
      let lo = 0, hi = points.length - 1;
      while (lo < hi) {
        const mid = (lo + hi) >> 1;
        if (points[mid].date < d) lo = mid + 1; else hi = mid;
      }
      if (lo > 0 && Math.abs(points[lo - 1].date - d) < Math.abs(points[lo].date - d)) lo -= 1;
      return lo;
    };
    capture.addEventListener('mousemove', e => {
      const box = svg.getBoundingClientRect();
      if (!box.width) return;
      const svgX = ((e.clientX - box.left) / box.width) * W;
      const p = points[nearestIdx(svgX)];
      const px = xOf(p.date), py = yOf(p.balanceAfter);
      crosshair.setAttribute('x1', px.toFixed(1));
      crosshair.setAttribute('x2', px.toFixed(1));
      crosshair.style.opacity = '1';
      hoverDot.setAttribute('cx', px.toFixed(1));
      hoverDot.setAttribute('cy', py.toFixed(1));
      hoverDot.style.opacity = '1';
      capture.dataset.tooltip = `${fmtDate(p.date)}\n${fmt(p.balanceAfter, 2)} XRP${p.type ? '\n' + p.type : ''}`;
    });
    capture.addEventListener('mouseleave', () => {
      crosshair.style.opacity = '0';
      hoverDot.style.opacity = '0';
      delete capture.dataset.tooltip;
      document.getElementById('chartTooltip')?.classList.remove('chart-tooltip--visible');
    });
  }
}

/** "Is This Normal?" — beginner-facing card comparing this account's
 *  single largest outbound transfer against its own historical pattern,
 *  independent of whether it was large enough to trigger a full Drain
 *  Risk episode. A quiet "normal" verdict is exactly as informative here
 *  as a flagged one — this exists specifically to answer the question
 *  even when nothing else fired. */
function _renderIsThisNormalCard(itn) {
  if (!itn) return '';
  if (!itn.applicable) {
    return `<div class="drain-sub-section"><div class="drain-sub-title">Is This Normal?</div><div class="inspect-empty-note">${escHtml(itn.reason)}</div></div>`;
  }
  const verdictColor = itn.verdict === 'normal' ? '#50fa7b' : '#ffb86c';
  const verdictLabel = itn.verdict === 'normal' ? 'Normal' : itn.verdict === 'unusual-size' ? 'Unusually Large' : 'Needs Review';
  return `
    <div class="drain-sub-section">
      <div class="drain-sub-title">Is This Normal? — this account's most recent transfer</div>
      <div class="wash-stat-row"><span>Most recent outbound transfer</span><span class="mono">${fmt(itn.evaluatedTransfer.xrp, 2)} XRP</span></div>
      <div class="wash-stat-row"><span>Compared with this account's prior history</span><span class="mono" style="cursor:help;border-bottom:1px dotted rgba(255,255,255,.35)" title="Methodology: this transfer (${fmt(itn.evaluatedTransfer.xrp, 2)} XRP) ranks at the ${itn.percentile.toFixed(0)}th percentile among this account's own ${itn.sampleSize} most-recent prior outbound payments — i.e. ${itn.percentile.toFixed(0)}% of this account's own payment history was smaller than this one. Compared against THIS account's own established pattern, never an external/industry benchmark.">${itn.percentile.toFixed(0)}th percentile of ${itn.sampleSize} prior payment(s)</span></div>
      <div class="wash-stat-row"><span>Security changes beforehand</span><span class="mono">${itn.priorAuthChange ? 'Yes — within 24h' : 'None'}</span></div>
      <div class="wash-stat-row"><span>Conclusion</span><span class="mono" style="color:${verdictColor};font-weight:800">${verdictLabel}</span></div>
      <div class="govauction-auth">${escHtml(itn.conclusion)}</div>
    </div>`;
}

/** A single plain-English lead sentence for Drain Risk, synthesizing the
 *  two technical risk levels plus "Is This Normal?" into ONE beginner-
 *  facing takeaway — the same "synthesize what's already computed, add
 *  zero new analysis" approach as Account Behavior/Follow the Money/Who
 *  Is Connected. The detailed evidence below is unchanged; this is a
 *  reading aid sitting above it, not a replacement for it. */
function buildDrainPlainSummary(compromiseLevel, behaviorLevel, isThisNormal, keyControlReason = null) {
  const compromiseOk = compromiseLevel === 'low';
  const behaviorOk = behaviorLevel === 'none' || behaviorLevel === 'low';
  const authChangePreceded = isThisNormal?.applicable && isThisNormal.verdict === 'unusual-with-auth-change';

  if (authChangePreceded) {
    return { tone: 'crit', text: 'A large transfer happened shortly after this account\'s security settings changed — that combination is a classic warning sign, even where the key/permission checks alone did not trigger an alert on their own.' };
  }
  if (!compromiseOk) {
    // 'self-set' and 'unknown-setter' both land on compromiseLevel:'medium'
    // (same as the old blanket branch below), but describe very different
    // realities — a self-set regular key is deliberate hardening with real
    // supporting evidence, not "signs of a takeover," and an unknown setter
    // is a DATA COVERAGE gap (the setting transaction isn't in the fetched
    // history), not evidence of anything. Collapsing both into "shows signs
    // that control may have changed hands... commonly appears in account
    // takeovers" contradicted the finding's own, more careful text one
    // line away — confirmed live on a 13-year-old account whose original
    // SetRegularKey transaction simply predates its capped history window.
    if (keyControlReason === 'self-set') {
      return { tone: 'ok', text: 'This account signs via a regular key it set itself (master key disabled) — a recognized self-custody hardening pattern, not a sign of compromise. See "Account Compromise Risk" below for the supporting evidence.' };
    }
    if (keyControlReason === 'unknown-setter') {
      return { tone: 'warn', text: 'This account signs via a regular key (master key disabled), but the transaction that originally set it predates the analysed transaction history, so whether it was self-set or set by someone else can\'t be confirmed here. See "Account Compromise Risk" below.' };
    }
    return { tone: compromiseLevel === 'critical' ? 'crit' : 'warn', text: 'This account shows signs that control may have changed hands — its signing keys or authorization settings were set up or altered in a way that commonly appears in account takeovers. See "Account Compromise Risk" below for exactly what changed.' };
  }
  if (!behaviorOk) {
    return { tone: behaviorLevel === 'critical' ? 'crit' : 'warn', text: 'A larger-than-usual amount of value has moved out of this account recently. This can be a real drain, or simply a big one-time transfer the owner made on purpose — see the movements below for the specifics before drawing a conclusion.' };
  }
  if (isThisNormal?.applicable && isThisNormal.verdict === 'unusual-size') {
    return { tone: 'warn', text: 'The most recent transfer out of this account was noticeably larger than what this account has typically sent before. On its own, that is not necessarily a problem — see "Is This Normal?" below.' };
  }
  return { tone: 'ok', text: 'Nothing here suggests this account has been taken over by someone else, and its recent activity looks in line with its own history.' };
}

/** Combined "In plain terms" summary for the merged Drain Risk & Fund Flow
 *  section — one sentence covering both halves instead of two separate
 *  boxes each saying "In plain terms" back to back, which read as
 *  redundant once the sections became visually one. Reuses
 *  buildDrainPlainSummary/buildFundFlowPlainSummary's own text and tone
 *  logic internally rather than re-deriving it, so neither half's
 *  behavior can drift from its own dedicated (and separately tested)
 *  function — this only decides how to splice the two together. */
function buildCombinedDrainFundFlowSummary(compromiseLevel, behaviorLevel, isThisNormal, flow, keyControlReason = null) {
  const drain = buildDrainPlainSummary(compromiseLevel, behaviorLevel, isThisNormal, keyControlReason);
  const flowSummary = buildFundFlowPlainSummary(flow);
  if (!flowSummary) return drain;

  const toneRank = { ok: 0, warn: 1, crit: 2 };
  const tone = toneRank[flowSummary.tone] > toneRank[drain.tone] ? flowSummary.tone : drain.tone;
  return { tone, text: `${drain.text} ${flowSummary.text}` };
}

/** Shared "In plain terms" callout box — a single beginner-facing lead
 *  sentence synthesizing data a section already computed, sitting above
 *  its detailed evidence rather than replacing it. Used by Drain Risk and
 *  Fund Flow Tracer; kept as one shared renderer so both stay visually
 *  and tonally consistent rather than drifting into two near-duplicate
 *  box styles. */
function _renderPlainSummaryBox(summary) {
  if (!summary) return '';
  const toneColor = { ok: '#50fa7b', warn: '#ffb86c', crit: '#ff5555' }[summary.tone] || '#50fa7b';
  const toneIcon  = { ok: '✓', warn: '⚠', crit: '⛔' }[summary.tone] || '✓';
  return `
    <div style="display:flex;gap:10px;align-items:flex-start;padding:12px 14px;margin-bottom:10px;border-radius:10px;background:${toneColor}0d;border:1px solid ${toneColor}33">
      <span style="font-size:1rem;color:${toneColor};flex-shrink:0;line-height:1.3">${toneIcon}</span>
      <div style="font-size:.85rem;color:rgba(255,255,255,.82);line-height:1.55"><strong style="color:${toneColor}">In plain terms:</strong> ${escHtml(summary.text)}</div>
    </div>`;
}

/** Flow Intelligence spec §16 — a compact Before/During/After balance
 *  snapshot for the single most notable drain episode (highest actual
 *  depletion — the same real numbers already computed by
 *  findDrainEpisodes/_enrichDrainEpisode, just never shown as a plain
 *  3-number strip). Deliberately shows only ONE episode, not all of
 *  them — a quick visual anchor for the biggest event, not a duplicate of
 *  the full per-episode evidence list below it. */
function _renderBeforeDuringAfter(ep) {
  if (!ep) return '';
  const fmtDate = d => d != null ? new Date((d + XRPL_EPOCH) * 1000).toLocaleDateString() : '—';
  return `
    <div style="margin-bottom:10px">
      <div style="font-size:.65rem;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:.08em;margin-bottom:6px">Most Notable Movement — Before / During / After</div>
      <div style="display:flex;border-radius:10px;overflow:hidden;border:1px solid rgba(255,255,255,.08)">
        <div style="flex:1;padding:10px 12px;background:rgba(255,255,255,.02);text-align:center">
          <div style="font-size:.62rem;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:.06em;margin-bottom:4px">Before</div>
          <div class="mono" style="font-size:1rem;font-weight:800;color:rgba(255,255,255,.85)">${fmt(ep.openingBalanceXrp, 2)} XRP</div>
          <div style="font-size:.64rem;color:rgba(255,255,255,.3);margin-top:2px">${fmtDate(ep.startDate)}</div>
        </div>
        <div style="flex:1;padding:10px 12px;background:rgba(255,184,108,.05);text-align:center;border-left:1px solid rgba(255,255,255,.06);border-right:1px solid rgba(255,255,255,.06)">
          <div style="font-size:.62rem;color:rgba(255,184,108,.6);text-transform:uppercase;letter-spacing:.06em;margin-bottom:4px">During</div>
          <div class="mono" style="font-size:1rem;font-weight:800;color:#ffb86c">${fmt(ep.grossOutflowXrp, 2)} XRP moved</div>
          <div style="font-size:.64rem;color:rgba(255,255,255,.3);margin-top:2px">peak ${fmt(ep.peakBalanceXrp, 2)} XRP</div>
        </div>
        <div style="flex:1;padding:10px 12px;background:rgba(255,255,255,.02);text-align:center">
          <div style="font-size:.62rem;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:.06em;margin-bottom:4px">After</div>
          <div class="mono" style="font-size:1rem;font-weight:800;color:rgba(255,255,255,.85)">${fmt(ep.closingBalanceXrp, 2)} XRP</div>
          <div style="font-size:.64rem;color:rgba(255,255,255,.3);margin-top:2px">${fmtDate(ep.endDate)}</div>
        </div>
      </div>
    </div>`;
}

/** Renders the REAL per-episode destination breakdown _enrichDrainEpisode
 *  already computes (top 5 destinations by XRP received during that
 *  specific window) — previously only used internally to derive text like
 *  "70% went to a single destination," never actually shown. Answers
 *  "where did the money go during THIS movement," distinct from Fund
 *  Flow's lifetime-aggregate destination list below. `lifetimeTopAddrs`
 *  (optional) cross-references each address against Fund Flow's own
 *  top-10 lifetime destinations — a real, already-computed overlap check,
 *  not a new relationship inference — so a reader doesn't have to notice
 *  by hand that this episode's recipient is also a recurring destination. */
function _renderEpisodeDestinations(destinations, grossOutflowXrp, lifetimeTopAddrs = null) {
  if (!destinations?.length) return '';
  const rows = destinations.map(d => {
    const pct = grossOutflowXrp > 0 ? (d.xrp / grossOutflowXrp * 100) : 0;
    const entityBadge = d.entity ? `<span class="flow-entity-badge flow-entity--${d.entity.type}">${escHtml(d.entity.name)}</span>` : '';
    const topDestBadge = lifetimeTopAddrs?.has(d.addr)
      ? `<span style="font-size:.62rem;color:#8be9fd;border:1px solid rgba(139,233,253,.3);border-radius:999px;padding:1px 7px;white-space:nowrap">also a top lifetime destination</span>`
      : '';
    return `
      <div style="display:flex;align-items:center;gap:8px;padding:4px 0;flex-wrap:wrap">
        <button class="addr-link mono cut" data-addr="${escHtml(d.addr)}" title="${escHtml(d.addr)}" style="font-size:.76rem">${escHtml(shortAddr(d.addr))}</button>
        ${entityBadge}${topDestBadge}
        <span class="mono" style="margin-left:auto;font-size:.76rem;color:rgba(255,255,255,.7);white-space:nowrap">${fmt(d.xrp, 2)} XRP${grossOutflowXrp > 0 ? ` (${pct.toFixed(0)}%)` : ''}</span>
      </div>`;
  }).join('');
  return `
    <div style="margin:8px 0 4px;padding:8px 10px;background:rgba(255,255,255,.02);border-radius:8px;border:1px solid rgba(255,255,255,.05)">
      <div style="font-size:.68rem;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:.06em;margin-bottom:4px">📍 Where this movement's funds went</div>
      ${rows}
    </div>`;
}

function renderDrainAnalysis(drain, paychans, escrows, checks, flow = null) {
  const el = $('inspect-drain-body');
  if (!el) return;

  const levelColors = { low: '#50fa7b', medium: '#ffb86c', high: '#ff8c42', critical: '#ff5555', none: '#50fa7b' };
  const levelIcons  = { low: '✓', medium: '⚠', high: '⚠', critical: '⛔', none: '✓' };
  const compromiseLevel = drain.compromiseRiskLevel ?? drain.riskLevel;
  const behaviorLevel   = drain.assetDrainSeverity ?? 'none';

  // One combined summary for the whole merged section — flow is optional
  // (this function has no other callers today, but keeping it optional
  // avoids a hard crash if that ever changes) and falls back to the
  // drain-only reading when absent.
  const plainSummary = flow
    ? buildCombinedDrainFundFlowSummary(compromiseLevel, behaviorLevel, drain.isThisNormal, flow, drain.keyControlReason)
    : buildDrainPlainSummary(compromiseLevel, behaviorLevel, drain.isThisNormal, drain.keyControlReason);

  // Single most notable episode (highest real depletion) for the Before/
  // During/After strip — a quick visual anchor, not a duplicate of the
  // full per-episode evidence list further down.
  const worstEpisode = (drain.episodes || []).length
    ? [...drain.episodes].sort((a, b) => b.actualDepletionPct - a.actualDepletionPct)[0]
    : null;

  // Cross-reference: which addresses are ALSO one of Fund Flow's own
  // top-10 lifetime destinations — a real overlap check over data both
  // halves of this now-combined section already compute, not a new
  // relationship inference.
  const lifetimeTopAddrs = flow?.destinations?.length ? new Set(flow.destinations.map(d => d.addr)) : null;

  el.innerHTML = `
    ${_renderPlainSummaryBox(plainSummary)}
    ${_renderBeforeDuringAfter(worstEpisode)}
    <div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:10px">
      <div class="drain-level drain-level--${compromiseLevel}" style="flex:1;min-width:220px;align-items:flex-start">
        <span class="drain-level-icon" style="margin-top:1px">${levelIcons[compromiseLevel]}</span>
        <div>
          <div class="drain-level-text">Account Compromise Risk: <strong>${compromiseLevel.toUpperCase()}</strong></div>
          <div style="font-size:.72rem;font-weight:500;opacity:.65;margin-top:2px">Could someone else have taken control of this account?</div>
        </div>
      </div>
      <div class="drain-level drain-level--${behaviorLevel === 'none' ? 'low' : behaviorLevel}" style="flex:1;min-width:220px;align-items:flex-start">
        <span class="drain-level-icon" style="margin-top:1px">${levelIcons[behaviorLevel]}</span>
        <div>
          <div class="drain-level-text">Asset Drain Behavior: <strong>${behaviorLevel === 'none' ? 'NONE OBSERVED' : behaviorLevel.toUpperCase()}</strong></div>
          <div style="font-size:.72rem;font-weight:500;opacity:.65;margin-top:2px">Is money actually leaving in an unusual way?</div>
        </div>
      </div>
    </div>
    ${_renderIsThisNormalCard(drain.isThisNormal)}
    <div id="inspect-drain-chart" style="margin-bottom:12px"></div>
    <div class="simple-only" style="font-size:.76rem;color:rgba(255,255,255,.4);padding:8px 2px;margin-bottom:6px">
      ${drain.signals.length} underlying finding${drain.signals.length === 1 ? '' : 's'} back the summary above — switch to <strong>⚗ Advanced</strong> (top of page) to see the full evidence for each.
    </div>
    <div class="audit-items advanced-only">
      ${(() => {
        // Account Compromise Risk signals (key/signer-state checks — few,
        // and generally the most important) always render in full.
        // Asset Drain Behavior episode findings can legitimately number in
        // the dozens for a long-lived, active account even after the
        // duplicate-episode fix — each one renders the full evidence model
        // (observed/calculated/inferred/hypothesis/alternatives), which is
        // genuinely long content, not padding. Unconditionally rendering
        // all of them made this one section 10,000+ px tall on a mobile
        // viewport by itself — roughly 12 phone screens for one section
        // out of 23 on the page. Show the most notable ones (worst
        // severity/confidence first) inline; the rest are one tap away,
        // not gone. The whole block is also .advanced-only — Simple mode
        // gets the plain summary + level badges + chart above, which is
        // the actual answer a beginner needs; this per-episode evidence
        // dump is what an analyst wants to verify that answer against.
        const DRAIN_EPISODES_SHOWN = 4;
        const other = drain.signals.filter(s => s.module !== 'Asset Drain Behavior');
        const episodes = drain.signals.filter(s => s.module === 'Asset Drain Behavior')
          .slice().sort((a, b) => (_RISK_SEV_WEIGHT[b.sev] ?? 0) * (b.confidence ?? 0.5) - (_RISK_SEV_WEIGHT[a.sev] ?? 0) * (a.confidence ?? 0.5));
        const shown = episodes.slice(0, DRAIN_EPISODES_SHOWN);
        const rest = episodes.slice(DRAIN_EPISODES_SHOWN);
        const withDest = s => auditRow(s) + _renderEpisodeDestinations(s.episodeDestinations, s.episodeGrossOutflowXrp, lifetimeTopAddrs);
        const otherHtml = other.map(withDest).join('');
        const shownHtml = shown.map(withDest).join('');
        const restHtml = rest.length
          ? `<details class="drain-episodes-more">
               <summary>Show ${rest.length} more balance-movement episode${rest.length === 1 ? '' : 's'}</summary>
               ${rest.map(withDest).join('')}
             </details>`
          : '';
        return otherHtml + shownHtml + restHtml;
      })()}
    </div>
    ${paychans.length ? `
    <div class="drain-sub-section">
      <div class="drain-sub-title">Open Payment Channels</div>
      ${paychans.map(p => `
        <div class="drain-channel-row">
          <span class="mono">${shortAddr(p.Destination)}</span>
          <span>${fmt(Number(p.Amount || 0) / 1e6, 2)} XRP allocated</span>
          <span>${fmt(Number(p.Balance || 0) / 1e6, 2)} XRP claimed</span>
        </div>`).join('')}
    </div>` : ''}
    ${escrows.length ? `
    <div class="drain-sub-section">
      <div class="drain-sub-title">Open Escrows</div>
      ${escrows.slice(0, 5).map(e => `
        <div class="drain-channel-row">
          <span>${e.Destination ? shortAddr(e.Destination) : 'self'}</span>
          <span>${fmt(Number(e.Amount || 0) / 1e6, 2)} XRP</span>
          <span class="mono">${e.Condition ? 'conditional' : e.FinishAfter ? 'time-locked' : ''}</span>
        </div>`).join('')}
    </div>` : ''}
    <div class="wash-subpanel">
      <div class="wash-subpanel-header">
        <span class="wash-subpanel-title">🌊 Where the Funds Went</span>
        <span class="section-badge" id="badge-fundflow"></span>
      </div>
      <div class="wash-subpanel-blurb">
        Every outgoing XRP payment, ranked by amount — with a note when it reached a known
        exchange or an address the network can't send funds back from. "Path payment" below
        just means the network needed more than one hop to route that specific transfer.
      </div>
      <div id="inspect-fundflow-body"></div>
    </div>
  `;
  renderBalanceChart(drain.balanceHistory, drain.episodes, 'inspect-drain-chart');
  _setBadgeDrainLevel('badge-drain', drain.riskLevel);
}

/* ── NFT Panel ───────────────────────────────────── */
/** NFT Analysis's "In plain terms" summary (Inspector-wide roadmap item
 *  #10) — reuses NFT count + worst flag severity already computed. */
function buildNftPlainSummary(nftAnalysis, nfts) {
  if (!nfts.length) return { tone: 'ok', text: `This account does not currently hold any NFTs.` };
  const hasCrit = nftAnalysis.flags.some(f => f.sev === 'critical');
  const hasWarn = nftAnalysis.flags.some(f => f.sev === 'warn');
  const tone = hasCrit ? 'crit' : hasWarn ? 'warn' : 'ok';
  let text = `This account holds ${nfts.length} NFT${nfts.length === 1 ? '' : 's'}.`;
  text += (hasCrit || hasWarn) ? ' See below for the specific pattern flagged for review.' : ' No unusual pattern was found.';
  return { tone, text };
}

function renderNftPanel(nftAnalysis, nfts) {
  const el = $('inspect-nft-body');
  if (!el) return;

  el.innerHTML = `
    ${_renderPlainSummaryBox(buildNftPlainSummary(nftAnalysis, nfts))}
    <div class="simple-only" style="font-size:.76rem;color:rgba(255,255,255,.4);padding:8px 2px;margin-bottom:6px">
      Switch to <strong>⚗ Advanced</strong> (top of page) to see the full NFT gallery and evidence.
    </div>
    <div class="advanced-only">
    <div class="audit-items">
      ${nftAnalysis.flags.map(f => auditRow(f)).join('')}
    </div>
    ${nfts.length ? `
    <div class="nft-grid">
      ${nfts.slice(0, 12).map(n => nftCard(n)).join('')}
    </div>
    ${nfts.length > 12 ? `<div class="nft-more">+${nfts.length - 12} more NFTs</div>` : ''}
    ` : ''}
    </div>
  `;
  _setBadge('badge-nft', nftAnalysis.flags);
}

function nftCard(n) {
  const flags = Number(n.Flags || 0);
  const transferable = !!(flags & NFT_FLAGS.lsfTransferable);
  const burnable     = !!(flags & NFT_FLAGS.lsfBurnable);
  const taxon = n.NFTokenTaxon || 0;
  const fee   = n.TransferFee  ? `${(n.TransferFee / 1000).toFixed(1)}%` : '0%';
  return `
    <div class="nft-card">
      <div class="nft-id mono">${n.NFTokenID ? shortAddr(n.NFTokenID) : '—'}</div>
      <div class="nft-meta">
        <span class="nft-badge ${transferable ? 'nft-badge--ok' : 'nft-badge--warn'}">
          ${transferable ? 'Transferable' : 'Non-transferable'}
        </span>
        ${burnable ? '<span class="nft-badge nft-badge--info">Burnable</span>' : ''}
      </div>
      <div class="nft-details">
        <span>Taxon: ${taxon}</span>
        <span>Fee: ${fee}</span>
      </div>
      ${n.Issuer && n.Issuer !== n.Account ? `<div class="nft-issuer mono">Issuer: <button type="button" class="lp-addr-btn mono" onclick="openRelationshipDrawer('${escHtml(n.Issuer)}')" title="Examine this account's relationship with the inspected account">${shortAddr(n.Issuer)}</button></div>` : ''}
    </div>`;
}

/* ── Wash Trading Panel ──────────────────────────── */
// Market Integrity sub-panels: Offer Lifecycle, Wash Execution, Spoofing,
// and Automation are computed as genuinely distinct detectors (each with
// its own mkFinding()-assigned module), but used to render as one
// interleaved list under a single combined score — indistinguishable to a
// reader whether a given line came from execution evidence or a spoofing
// pattern. Grouping by the module each finding already carries (no new
// analysis, purely a render-layer fix) lets each stand on its own with its
// own mini-badge, matching how the rest of the report treats these as
// separate concepts (analyseWashExecution/analyseSpoofingScore/
// analyseMarketMakerAutomation are three independent functions).
const WASH_SUBPANELS = [
  { module: 'Offer Fill Rate',        label: 'Offer Lifecycle',   icon: '📋', blurb: 'How offers this account placed were ultimately resolved — filled, cancelled, or left unfilled.' },
  { module: 'Execution Routing',      label: 'Execution Routing', icon: '🔀', blurb: 'Which venue each executed trade actually matched against — the order book, an AMM pool, or both in one transaction.' },
  { module: 'Wash Execution',         label: 'Wash Execution',    icon: '🔁', blurb: 'Executed trades where this account may have been on both sides of the same economic exchange.' },
  { module: 'Spoofing',               label: 'Spoofing',          icon: '👻', blurb: 'Large resting orders cancelled or replaced in a pattern consistent with never intending execution.' },
  { module: 'Market-Maker Automation', label: 'Automation',       icon: '🤖', blurb: 'Whether order timing/sizing looks programmatic — a behavioral observation, not itself a risk finding.' },
];

/* ── Independent verdict cards: Wash / Spoofing / Market-Making ──────
   These three questions are genuinely independent — an account can show
   elevated wash-execution evidence AND high-probability legitimate
   automation AND low spoofing evidence, all at once. Collapsing them into
   one combined score (the legacy wash.score/verdict, kept below for
   backward compatibility) hides that. Severity color is deliberately NOT
   applied to the Market-Making card: automated/programmatic behavior is a
   characteristic, not an accusation, so it never defaults to red. */
/** `applicable = false` means the detector had nothing meaningful to check
 *  (e.g. zero order-book offers for a spoofing check) — this must render as
 *  N/A, never NORMAL. "Normal" is itself a conclusion ("we looked and found
 *  nothing"); N/A is the absence of a basis to conclude anything at all. */
function _severityVerdictLabel(findings, applicable = true) {
  if (!applicable) return ['N/A', 'neutral'];
  const rank = { critical: 3, warn: 2, info: 1, ok: 0 };
  const worst = findings.reduce((w, f) => (rank[f.sev] ?? 0) > (rank[w] ?? 0) ? f.sev : w, 'ok');
  return { critical: ['ELEVATED', 'crit'], warn: ['WATCH', 'warn'], info: ['LOW EVIDENCE', 'neutral'], ok: ['NORMAL', 'ok'] }[worst];
}

/** Same N/A-vs-conclusion distinction as _severityVerdictLabel: below
 *  WASH_MIN_TX offers, analyseMarketMakerAutomation's own gate never even
 *  runs its cancel/burst/uniformity check (see that function) — "not
 *  detected" would misreport that absence as a considered, negative
 *  finding rather than an unassessable one. */
function _marketMakingVerdictLabel(wash) {
  if ((wash.stats?.creates ?? 0) < WASH_MIN_TX) return ['NOT ENOUGH DATA', 'neutral'];
  if (!wash.automationLikely) return ['NOT DETECTED', 'neutral'];
  const conf = wash.signals.find(s => s.module === 'Market-Maker Automation')?.confidence ?? 0;
  return conf >= 0.6 ? ['HIGH PROBABILITY', 'mm'] : ['AMBIGUOUS', 'mm'];
}

/** Single source of truth for "how bad is Market Integrity, overall" —
 *  reused by the section badge (which the jump-nav status dot and the
 *  smart-collapse default both read off of) AND the Full Report's own
 *  wash-trading narrative/stats/recommendations, so all of them always
 *  agree with the panel's own independent verdict cards instead of each
 *  separately re-deriving severity from the deprecated combined
 *  wash.score/wash.verdict. Market-Making never contributes to the tone —
 *  it's explanatory, not accusatory, by design (see _marketMakingVerdictLabel). */
function _washSectionSeverity(wash) {
  const spoofingApplicable = (wash.stats?.creates || 0) > 0;
  const execPair = _severityVerdictLabel(wash.signals.filter(s => s.module === 'Wash Execution'));
  const spoofPair = _severityVerdictLabel(wash.signals.filter(s => s.module === 'Spoofing'), spoofingApplicable);
  const tone = (execPair[1] === 'crit' || spoofPair[1] === 'crit') ? 'crit'
    : (execPair[1] === 'warn' || spoofPair[1] === 'warn') ? 'warn'
    : 'ok';
  const label = tone === 'ok' ? execPair[0] : (execPair[1] === tone ? execPair[0] : spoofPair[0]);
  return { tone, label, execPair, spoofPair, spoofingApplicable };
}

// Wash Trading's 0-15pt Risk Score contribution — derived from the same
// _washSectionSeverity tone the section badge/nav dot/smart-collapse/Full
// Report already agree on, rather than the deprecated combined wash.score
// (which is still computed and still shown as its own legacy bar inside the
// Wash panel, kept for continuity, but no longer feeds the headline number).
// Shared by computeOverallRisk and buildRiskBreakdown so they can't drift.
function _washRiskScoreContribution(wash) {
  return { crit: 15, warn: 7, ok: 0 }[_washSectionSeverity(wash).tone] || 0;
}

function _verdictCardHtml(title, [label, tone], blurb) {
  return `
    <div class="mi-verdict-card mi-verdict-card--${tone}">
      <div class="mi-verdict-title">${escHtml(title)}</div>
      <div class="mi-verdict-label">${escHtml(label)}</div>
      <div class="mi-verdict-blurb">${escHtml(blurb)}</div>
    </div>`;
}

function _miniBadgeHtml(findings, applicable = true) {
  if (!applicable) return `<span class="section-badge section-badge--neutral">N/A</span>`;
  const crits = findings.filter(f => f.sev === 'critical').length;
  const warns = findings.filter(f => f.sev === 'warn').length;
  if (crits) return `<span class="section-badge section-badge--crit">${crits} critical</span>`;
  if (warns) return `<span class="section-badge section-badge--warn">${warns} warn</span>`;
  return `<span class="section-badge section-badge--ok">OK</span>`;
}

/** Market Integrity's "What Nalu Sees" lead paragraph — synthesizes the
 *  three independent verdicts (Wash Execution / Spoofing / Market-Making)
 *  into one plain-English read, the same "reuse what's already computed,
 *  add zero new analysis" approach as Drain Risk's plain summary. N/A
 *  cases get their own honest clause rather than being silently folded
 *  into "normal" or "not detected." */
function buildMarketIntegrityPlainSummary(wash, spoofingApplicable, marketMakingApplicable) {
  const toneRank = { crit: 2, warn: 1, neutral: 0, ok: 0 };
  const [execLabel, execTone] = _severityVerdictLabel(wash.signals.filter(s => s.module === 'Wash Execution'));
  const [spoofLabel, spoofTone] = _severityVerdictLabel(wash.signals.filter(s => s.module === 'Spoofing'), spoofingApplicable);

  let execClause;
  if (execLabel === 'ELEVATED') execClause = 'This account shows meaningful evidence of wash-like execution — repeated, closely-matched value moving back and forth between the same accounts.';
  else if (execLabel === 'WATCH') execClause = 'Some repeated value movement exists here, but current evidence for coordinated wash trading is weak.';
  else if (execLabel === 'LOW EVIDENCE') execClause = 'A pattern that could resemble wash trading exists here, but the evidence for it is weak.';
  else execClause = 'Nothing here suggests coordinated wash-like trading.';

  let spoofClause;
  if (!spoofingApplicable) spoofClause = 'Spoofing could not be assessed — this account placed no exchange orders to analyze.';
  else if (spoofLabel === 'ELEVATED' || spoofLabel === 'WATCH') spoofClause = 'Its order-placement behavior also shows signs consistent with spoofing.';
  else spoofClause = 'Its order-placement behavior shows no sign of spoofing.';

  let mmClause = '';
  if (!marketMakingApplicable) mmClause = 'There is not enough order activity to assess whether this looks like automated market-making.';
  else if (wash.automationLikely) mmClause = 'Its order behavior is also consistent with automated market-making, which can produce high turnover and frequent cancellations without indicating manipulation.';

  const worst = Math.max(toneRank[execTone] ?? 0, spoofingApplicable ? (toneRank[spoofTone] ?? 0) : 0);
  const tone = worst >= 2 ? 'crit' : worst === 1 ? 'warn' : 'ok';
  return { tone, text: `${execClause} ${spoofClause}${mmClause ? ' ' + mmClause : ''}` };
}

/** "Why This Is Flagged" / "What Reduces Concern" — pulled straight from
 *  the observed/evidenceAgainstBenign (argue FOR concern) and
 *  alternativeExplanations (benign readings that REDUCE concern) fields
 *  every Wash Execution and Spoofing finding already carries via
 *  mkFinding's evidence model. Renders nothing new — only reorganizes
 *  what's already on elevated findings into the two questions a reader
 *  actually wants answered, matching evidence tiers already established
 *  for Drain Risk's "In plain terms" treatment. */
function _renderMarketIntegrityWhyFlagged(wash) {
  const relevant = wash.signals.filter(s => (s.module === 'Wash Execution' || s.module === 'Spoofing') && (s.sev === 'warn' || s.sev === 'critical'));
  if (!relevant.length) return '';

  const forConcern = [], reducesConcern = [];
  for (const f of relevant) {
    for (const o of (f.observed || [])) forConcern.push(o);
    for (const e of (f.evidenceAgainstBenign || [])) forConcern.push(e);
    for (const a of (f.alternativeExplanations || [])) reducesConcern.push(a);
  }
  const uniq = arr => [...new Set(arr)];
  const forList = uniq(forConcern), reduceList = uniq(reducesConcern);
  if (!forList.length && !reduceList.length) return '';

  return `
    <div class="mi-why-flagged">
      ${forList.length ? `
      <div class="mi-why-col mi-why-col--for">
        <div class="mi-why-title">Why this is flagged</div>
        <ul>${forList.map(t => `<li>${escHtml(t)}</li>`).join('')}</ul>
      </div>` : ''}
      ${reduceList.length ? `
      <div class="mi-why-col mi-why-col--against">
        <div class="mi-why-title">What reduces concern</div>
        <ul>${reduceList.map(t => `<li>${escHtml(t)}</li>`).join('')}</ul>
      </div>` : ''}
    </div>`;
}

/** Value Circulation — "a lot of trading happened, how much of it actually
 *  changed anything?" Renders analyseWashExecution's own valueCirculation
 *  field (gross vs. net XRP moved with round-trip partners, and what share
 *  of this account's total XRP payment volume that represents) as two
 *  proportional bars — reuses data already computed, adds no new analysis.
 *  Returns '' when there's no round-trip relationship to circulate value
 *  with, never a fabricated all-zero panel. */
function _renderValueCirculation(vc) {
  if (!vc) return '';
  const netPct = vc.grossXrp > 0 ? Math.max(2, (vc.netXrp / vc.grossXrp) * 100) : 0;
  const mostlyChurn = vc.grossXrp > 0 && vc.netXrp < vc.grossXrp * 0.3;
  return `
    <div class="mi-valuecirc">
      <div class="mi-valuecirc-title">Value Circulation — Round-Trip Partners</div>
      <div class="mi-valuecirc-row">
        <span class="mi-valuecirc-label">Gross activity</span>
        <div class="mi-valuecirc-bar-wrap"><div class="mi-valuecirc-bar mi-valuecirc-bar--gross" style="width:100%"></div></div>
        <span class="mi-valuecirc-val">${fmt(vc.grossXrp, 0)} XRP</span>
      </div>
      <div class="mi-valuecirc-row">
        <span class="mi-valuecirc-label">Net position change</span>
        <div class="mi-valuecirc-bar-wrap"><div class="mi-valuecirc-bar mi-valuecirc-bar--net" style="width:${netPct.toFixed(1)}%"></div></div>
        <span class="mi-valuecirc-val">${fmt(vc.netXrp, 0)} XRP</span>
      </div>
      <div class="mi-valuecirc-blurb">${mostlyChurn
        ? 'A meaningful amount of value moved back and forth with this account\'s round-trip partners, but comparatively little of it represents a real, lasting change in position. This can occur in wash-like activity, but also in legitimate market-making or routine reciprocal payments.'
        : 'Value moved with this account\'s round-trip partners, and a substantial share of it represents a real net position change rather than pure back-and-forth.'}</div>
      <div class="mi-valuecirc-split">
        <div class="mi-valuecirc-split-bar"><div class="mi-valuecirc-split-internal" style="width:${vc.internalPct.toFixed(1)}%"></div></div>
        <div class="mi-valuecirc-split-labels">
          <span>Round-trip partners: ${vc.internalPct.toFixed(0)}%</span>
          <span>Everyone else: ${vc.externalPct.toFixed(0)}%</span>
        </div>
      </div>
      <div class="mi-valuecirc-note">${escHtml(vc.note)}</div>
    </div>`;
}

/** "Where Trades Happened" — converts Execution Routing's existing
 *  percent-in-a-sentence finding ("61% CLOB, 4% AMM...") into a bar chart.
 *  Same data (wash.stats.execRoute, already computed by
 *  analyseExecutionRouting), no new analysis. Plain-language labels first
 *  (Liquidity Pools / Order Book / Mixed Route), technical terms folded
 *  into a small parenthetical, matching this session's established
 *  "plain language first, jargon in a tooltip/parenthetical" convention. */
function _renderWhereTradesHappened(stats) {
  if (!stats || !stats.total) return '';
  const rows = [
    { label: 'Liquidity Pools', tech: 'AMM', count: stats.amm, color: '#8be9fd' },
    { label: 'Order Book', tech: 'CLOB', count: stats.clob, color: '#50fa7b' },
    { label: 'Mixed Route', tech: 'hybrid', count: stats.hybrid, color: '#ffb86c' },
    { label: 'Unresolved', tech: null, count: stats.unknown, color: 'rgba(255,255,255,.3)' },
  ].filter(r => r.count > 0);
  if (!rows.length) return '';
  const max = Math.max(...rows.map(r => r.count), 1);
  const dominant = rows.slice().sort((a, b) => b.count - a.count)[0];

  return `
    <div class="mi-routing">
      <div class="mi-routing-title">Where Trades Happened</div>
      ${rows.map(r => `
        <div class="mi-routing-row">
          <span class="mi-routing-label">${escHtml(r.label)}${r.tech ? ` <span class="mi-routing-tech">(${r.tech})</span>` : ''}</span>
          <div class="mi-routing-bar-wrap"><div class="mi-routing-bar" style="width:${(r.count / max * 100).toFixed(1)}%;background:${r.color}"></div></div>
          <span class="mi-routing-count">${r.count}</span>
        </div>`).join('')}
      <div class="mi-routing-blurb">${dominant.label === 'Unresolved'
        ? `Most of this account's ${stats.total} trade execution(s) could not be classified from available ledger metadata.`
        : `Most reconstructed trading occurred through ${escHtml(dominant.label.toLowerCase())}${dominant.tech ? ` (${dominant.tech})` : ''}.`
      }${stats.amm > 0 ? ' Liquidity-pool trades match against pooled reserves contributed by many unrelated providers — no single counterparty is on the other side, so an AMM trade never implies a direct relationship with another trader.' : ''}</div>
    </div>`;
}

/** "Relationships Worth Reviewing" — ranks EVERY round-trip counterparty
 *  (analyseWashExecution's own topRelationships, already scored by
 *  _roundTripQuality) instead of only ever showing the single strongest
 *  one in the Wash Execution finding text, so a reader doesn't have to
 *  inspect each address by hand to find the ones worth a second look.
 *  Each card's "Examine" button opens the same Trading Relationship
 *  drawer the Network Map's edges already open — one shared detail view,
 *  reached two ways. */
function _renderRelationshipsWorthReviewing(topRelationships) {
  if (!topRelationships || !topRelationships.length) return '';
  const top = topRelationships.slice(0, 5);
  const evidenceLabel = q => q.qualityScore >= 0.6 ? 'Strong' : q.qualityScore >= 0.3 ? 'Moderate' : 'Weak';
  const evidenceColor = { Strong: '#ff5555', Moderate: '#ffb86c', Weak: 'rgba(255,255,255,.4)' };

  return `
    <div class="mi-relationships">
      <div class="mi-relationships-title">Relationships Worth Reviewing</div>
      ${top.map((q, i) => {
        const ent = getEntity(q.counterparty);
        const label = evidenceLabel(q);
        return `
        <div class="mi-rel-card">
          <div class="mi-rel-rank">${i + 1}</div>
          <div class="mi-rel-body">
            <div class="mi-rel-partner mono">${escHtml(ent?.name || shortAddr(q.counterparty))}</div>
            <div class="mi-rel-stats">${q.occurrences} execution(s) · ${(q.medianSimilarity * 100).toFixed(0)}% amount match · ${fmt(q.medianElapsedSec / 60, 1)} min median reversal${q.alsoTradedOnDex ? ' · also traded on DEX' : ''}</div>
          </div>
          <div class="mi-rel-evidence" style="color:${evidenceColor[label]}">${label}</div>
          <button type="button" class="mi-rel-examine" onclick="openRelationshipDrawer('${escHtml(q.counterparty)}')">Examine</button>
        </div>`;
      }).join('')}
    </div>`;
}

function renderWashPanel(wash) {
  const el = $('inspect-wash-body');
  if (!el) return;
  window._lastWashAnalysis = wash;

  const verdictColor = wash.verdict === 'clean'    ? '#50fa7b'
    : wash.verdict === 'low-risk'   ? '#50fa7b'
    : wash.verdict === 'suspicious' ? '#ffb86c'
    : '#ff5555';

  const grouped = WASH_SUBPANELS.map(sp => ({ ...sp, findings: wash.signals.filter(s => s.module === sp.module) }));
  const ungrouped = wash.signals.filter(s => !WASH_SUBPANELS.some(sp => sp.module === s.module));

  const washExecutionFindings = wash.signals.filter(s => s.module === 'Wash Execution');
  const spoofingFindings = wash.signals.filter(s => s.module === 'Spoofing');

  // No offers at all means Spoofing/Market-Making had nothing to check —
  // that must render as N/A / NOT ENOUGH DATA, never NORMAL / NOT DETECTED
  // (a considered "nothing found" reads very differently from "couldn't
  // assess"). WASH_MIN_TX is the same threshold analyseMarketMakerAutomation
  // itself requires before its detection logic even runs.
  const spoofingApplicable = (wash.stats.creates || 0) > 0;
  const marketMakingApplicable = (wash.stats.creates || 0) >= WASH_MIN_TX;
  const plainSummary = buildMarketIntegrityPlainSummary(wash, spoofingApplicable, marketMakingApplicable);
  const whyFlaggedHtml = _renderMarketIntegrityWhyFlagged(wash);

  el.innerHTML = `
    <div class="mi-verdict-row">
      ${_verdictCardHtml('Wash Execution', _severityVerdictLabel(washExecutionFindings), 'Possible same-actor round-trip trading')}
      ${_verdictCardHtml('Spoofing', _severityVerdictLabel(spoofingFindings, spoofingApplicable), 'Orders cancelled in a never-intended-to-fill pattern')}
      ${_verdictCardHtml('Market-Making', _marketMakingVerdictLabel(wash), 'Programmatic quoting behavior — not itself a risk')}
    </div>
    <div class="mi-verdict-note">These are independent questions and can disagree — e.g. elevated wash-execution evidence alongside a high probability of legitimate automated market-making.</div>
    ${_renderPlainSummaryBox(plainSummary)}
    ${whyFlaggedHtml}
    ${_renderValueCirculation(wash.valueCirculation)}
    ${_renderRelationshipsWorthReviewing(wash.topRelationships)}
    <div class="wash-header">
      <div class="wash-score-wrap">
        <div class="wash-score-bar">
          <div class="wash-score-fill" style="width:${wash.score}%;background:${verdictColor}"></div>
        </div>
        <div class="wash-score-labels">
          <span>Clean</span>
          <span style="color:${verdictColor};font-weight:900">${wash.verdict.replace('-', ' ').toUpperCase()} (${wash.score}/100)</span>
          <span>Certain</span>
        </div>
      </div>
      <div class="wash-header-note">Legacy combined score — Wash Execution + Spoofing only. Prefer the independent verdicts above; this number is kept for continuity.</div>
    </div>
    <div class="wash-stats">
      ${washStat('Offer Creates', wash.stats.creates)}
      ${washStat('Offer Cancels', wash.stats.cancels)}
      ${washStat('Filled Offers', wash.stats.fills)}
      ${washStat('Payments', wash.stats.payments)}
      ${washStat('Round-trip Counterparties', wash.stats.roundTrip)}
    </div>
    ${grouped.filter(g => g.findings.length).map(g => `
      <div class="wash-subpanel">
        <div class="wash-subpanel-header">
          <span class="wash-subpanel-title">${g.icon} ${escHtml(g.label)}</span>
          ${_miniBadgeHtml(g.findings, g.module !== 'Offer Fill Rate' || spoofingApplicable)}
        </div>
        <div class="wash-subpanel-blurb">${escHtml(g.blurb)}</div>
        ${g.module === 'Execution Routing' ? _renderWhereTradesHappened(wash.stats.execRoute) : ''}
        <div class="audit-items">${g.findings.map(s => auditRow(s)).join('')}</div>
      </div>`).join('')}
    ${ungrouped.length ? `<div class="audit-items">${ungrouped.map(s => auditRow(s)).join('')}</div>` : ''}
  `;
  const wb = $('badge-wash');
  if (wb) {
    const { tone, label } = _washSectionSeverity(wash);
    wb.textContent = label;
    wb.className = 'section-badge section-badge--' + tone;
  }
}

function washStat(label, val) {
  return `<div class="wash-stat"><span class="wash-stat-label">${escHtml(label)}</span><span class="wash-stat-val">${val}</span></div>`;
}

/** LP Participant Table — who provides liquidity to this issuer's AMM pool,
 *  their share, and their current underlying position (computed from the
 *  pool's own reserves × share — no price feed needed, this is the
 *  literal underlying-asset entitlement, not a USD valuation). Also flags
 *  cohort overlap (Top/Early Holder) and own trading volume when the LP is
 *  also a trader, using data Holder Cohorts and Issuer Market Activity
 *  already computed — no new fetches. */
function _renderLpParticipantTable(holderCohorts, issuerAmmPool) {
  if (!holderCohorts?.lpHolders?.length || !issuerAmmPool) return '';
  const reserves = _ammReserves(issuerAmmPool.pool);
  const topSet = new Set((holderCohorts.topHolders || []).map(h => h.addr));
  const earlySet = new Set((holderCohorts.earlyHolders || []).map(h => h.addr));
  const currencyLabel = hexToAscii(issuerAmmPool.currency);

  const rows = holderCohorts.lpHolders.slice(0, 15).map(h => {
    const xrpPos = reserves?.xrpAmount != null ? (h.sharePct / 100) * reserves.xrpAmount : null;
    const tokenPos = reserves?.tokenAmount != null ? (h.sharePct / 100) * reserves.tokenAmount : null;
    const tags = [];
    if (topSet.has(h.addr)) tags.push('<span class="lp-tag lp-tag--top">Top Holder</span>');
    if (earlySet.has(h.addr)) tags.push('<span class="lp-tag lp-tag--early">Early Holder</span>');
    return `
      <div class="lp-participant-row">
        <button type="button" class="lp-participant-addr lp-addr-btn mono" onclick="openRelationshipDrawer('${escHtml(h.addr)}')" title="Examine this account's relationship with the inspected account">${shortAddr(h.addr)}</button>
        <span class="lp-participant-share mono">${h.sharePct.toFixed(2)}%</span>
        <span class="lp-participant-position mono">${xrpPos != null ? fmt(xrpPos, 2) + ' XRP' : '—'} / ${tokenPos != null ? fmt(tokenPos, 2) + ' ' + escHtml(currencyLabel) : '—'}</span>
        <span class="lp-participant-tags">${tags.join('') || '<span class="lp-tag lp-tag--none">—</span>'}</span>
      </div>`;
  }).join('');

  return `
    <div class="lp-participant-table">
      <div class="lp-participant-header">
        <span>Address</span><span>Pool Share</span><span>Current Position</span><span>Cohort</span>
      </div>
      ${rows}
      ${holderCohorts.lpHolders.length > 15 ? `<div class="trustline-more">+${holderCohorts.lpHolders.length - 15} more LP holder(s)</div>` : ''}
      ${issuerAmmPool.lpLinesTruncated ? '<div class="lp-participant-caveat">LP holder list may be incomplete — the pool has more than 400 current LP trustlines.</div>' : ''}
    </div>`;
}

/** Overlap Matrix — every wallet belonging to 2+ of the Early/Top/LP/Seller
 *  cohorts at once (holderCohorts.overlapMatrix, already computed and
 *  pre-filtered to cohortCount >= 2). Deliberately does not editorialize —
 *  no "suspicious" language here — this is a checkable fact table, not a
 *  finding; the accompanying Holder Cohorts finding above already carries
 *  the "overlap alone is not evidence of coordination" caveat. */
function _renderOverlapMatrix(holderCohorts) {
  if (!holderCohorts?.overlapMatrix?.length) return '';
  const check = (on) => `<span class="overlap-check ${on ? 'overlap-check--on' : ''}">${on ? '✓' : ''}</span>`;
  const rows = holderCohorts.overlapMatrix.slice(0, 20).map(r => `
    <div class="overlap-matrix-row">
      <button type="button" class="overlap-matrix-addr lp-addr-btn mono" onclick="openRelationshipDrawer('${escHtml(r.addr)}')" title="Examine this account's relationship with the inspected account">${shortAddr(r.addr)}</button>
      ${check(r.early)}${check(r.top)}${check(r.lp)}${check(r.seller)}
    </div>`).join('');
  return `
    <div class="overlap-matrix">
      <div class="overlap-matrix-header overlap-matrix-row">
        <span>Address</span><span>Early</span><span>Top</span><span>LP</span><span>Seller</span>
      </div>
      ${rows}
      ${holderCohorts.overlapMatrix.length > 20 ? `<div class="trustline-more">+${holderCohorts.overlapMatrix.length - 20} more wallet(s) in 2+ cohorts</div>` : ''}
    </div>`;
}

/** Seller Holders table — the top sellers by gross amount sold, identified
 *  from issuerMarketActivity's own per-holder gross-sold tally, zero extra
 *  RPC calls. "Gross sold" is an ECONOMIC-EFFECT number (a real decrease in
 *  position at some point), not a claim about WHY, and deliberately not a
 *  running net total (a holder who received a large distribution and later
 *  sold only part of it would still show a net INCREASE overall — see the
 *  computation site for the full reasoning) — see the Holder Cohorts
 *  finding for the alternative-explanations caveat (ordinary portfolio
 *  trimming, etc). */
function _renderSellerCohortTable(holderCohorts) {
  if (!holderCohorts?.sellerHolders?.length) return '';
  const topSet = new Set((holderCohorts.topHolders || []).map(h => h.addr));
  const earlySet = new Set((holderCohorts.earlyHolders || []).map(h => h.addr));
  const rows = holderCohorts.sellerHolders.slice(0, 15).map(h => {
    const tags = [];
    if (topSet.has(h.addr)) tags.push('<span class="lp-tag lp-tag--top">Top Holder</span>');
    if (earlySet.has(h.addr)) tags.push('<span class="lp-tag lp-tag--early">Early Holder</span>');
    return `
      <div class="lp-participant-row">
        <button type="button" class="lp-participant-addr lp-addr-btn mono" onclick="openRelationshipDrawer('${escHtml(h.addr)}')" title="Examine this account's relationship with the inspected account">${shortAddr(h.addr)}</button>
        <span class="lp-participant-share mono">${fmt(h.grossSold, 0)}</span>
        <span class="lp-participant-tags">${tags.join('') || '<span class="lp-tag lp-tag--none">—</span>'}</span>
      </div>`;
  }).join('');
  return `
    <div class="lp-participant-table lp-participant-table--sellers">
      <div class="lp-participant-header">
        <span>Address</span><span>Gross Sold</span><span>Cohort</span>
      </div>
      ${rows}
      ${holderCohorts.sellerHolders.length > 15 ? `<div class="trustline-more">+${holderCohorts.sellerHolders.length - 15} more seller(s)</div>` : ''}
    </div>`;
}

/* ── Token Issuer Panel ──────────────────────────── */
/** Token Issuer's "In plain terms" summary (Inspector-wide roadmap item
 *  #10) — reuses issuer status + worst signal severity already computed.
 *  Deliberately keeps "project affiliation unknown" explicit rather than
 *  implying verification this app cannot provide. */
function buildIssuerPlainSummary(issuer, tokenLineCount) {
  if (!issuer.isIssuer) return { tone: 'ok', text: `This account does not issue any fungible token — it holds ${tokenLineCount} trustline${tokenLineCount === 1 ? '' : 's'} to other issuers.` };
  const hasCrit = issuer.signals.some(s => s.sev === 'critical');
  const hasWarn = issuer.signals.some(s => s.sev === 'warn');
  const tone = hasCrit ? 'crit' : hasWarn ? 'warn' : 'ok';
  let text = `This account issues at least one fungible token, with ${tokenLineCount} known trustline${tokenLineCount === 1 ? '' : 's'} against it.`;
  text += (hasCrit || hasWarn) ? ' See below for the specific distribution or control pattern flagged for review.' : ' No unusual distribution or control pattern was found.';
  text += ' Project affiliation (team, DAO, individual) is not independently verified by this tool.';
  return { tone, text };
}

function renderIssuerPanel(issuer, lines, holderCohorts = null, issuerAmmPool = null) {
  const el = $('inspect-issuer-body');
  if (!el) return;

  const tokenLines = lines.filter(l => l.currency && (l.currency.length === 3 || l.currency.length === 40));
  const lpTableHtml = _renderLpParticipantTable(holderCohorts, issuerAmmPool);
  const sellerTableHtml = _renderSellerCohortTable(holderCohorts);
  const overlapMatrixHtml = _renderOverlapMatrix(holderCohorts);

  el.innerHTML = `
    ${_renderPlainSummaryBox(buildIssuerPlainSummary(issuer, tokenLines.length))}
    <div class="simple-only" style="font-size:.76rem;color:rgba(255,255,255,.4);padding:8px 2px;margin-bottom:6px">
      Switch to <strong>⚗ Advanced</strong> (top of page) to see the full trustline/LP breakdown and evidence.
    </div>
    <div class="advanced-only">
    <div class="audit-items">
      ${issuer.signals.map(s => auditRow(s)).join('')}
    </div>
    ${tokenLines.length ? `
    <div class="trustline-list">
      ${tokenLines.slice(0, 10).map(l => `
        <div class="trustline-row">
          <span class="trustline-currency">${escHtml(hexToAscii(l.currency))}</span>
          <span class="trustline-issuer mono">${shortAddr(l.account)}</span>
          <span class="trustline-balance ${Number(l.balance) < 0 ? 'trustline-owed' : ''} mono">
            ${Number(l.balance) < 0 ? '▼ ' : ''}${fmt(Math.abs(Number(l.balance)), 2)}
            ${l.freeze ? '<span class="trustline-frozen">FROZEN</span>' : ''}
            ${l.freeze_peer ? '<span class="trustline-frozen trustline-frozen--peer">FROZEN BY ISSUER</span>' : ''}
          </span>
        </div>`).join('')}
      ${tokenLines.length > 10 ? `<div class="trustline-more">+${tokenLines.length - 10} more trustlines</div>` : ''}
    </div>` : ''}
    ${lpTableHtml ? `<div class="wash-subpanel-title" style="margin-top:16px">💧 AMM LP Participants</div>${lpTableHtml}` : ''}
    ${sellerTableHtml ? `<div class="wash-subpanel-title" style="margin-top:16px">📉 Net Sellers</div>${sellerTableHtml}` : ''}
    ${overlapMatrixHtml ? `<div class="wash-subpanel-title" style="margin-top:16px">🔎 Cohort Overlap</div><p class="widget-help" style="opacity:.55;font-size:.8rem;margin-bottom:6px">Wallets appearing in 2 or more cohorts below — overlap alone is not evidence of coordination (see the Holder Cohorts finding above).</p>${overlapMatrixHtml}` : ''}
    </div>
  `;
  _setBadge('badge-issuer', issuer.signals);
}

/* ── AMM Panel ───────────────────────────────────── */
/** Pool composition (reserve split) + ownership-share visual for each LP
 *  position, using data analyseAmmPositions already computes (tvl/tvl2/
 *  ownerPct/feeRate/costBasisXrp) but previously only showed as plain text.
 *  Deliberately does NOT compute or show a "current value"/P&L number —
 *  that needs a price feed for the non-XRP pool leg this app doesn't have,
 *  so only costBasisXrp (a real, computable number) is shown as a stat,
 *  never a fabricated comparison against it. */
function _renderAmmPositionVisual(p) {
  const hasReserves = p.tvl != null && p.tvl2 != null;
  const reserveBar = hasReserves ? `
    <div class="amm-reserve-bar">
      <div class="amm-reserve-seg amm-reserve-seg--xrp" style="width:50%" data-tooltip="${escHtml(`XRP side: ${fmt(p.tvl, 2)} XRP`)}"></div>
      <div class="amm-reserve-seg amm-reserve-seg--token" style="width:50%" data-tooltip="${escHtml(`Token side: ${fmt(p.tvl2, 2)} (own units, not XRP-equivalent)`)}"></div>
    </div>
    <div class="amm-reserve-labels"><span>${fmt(p.tvl, 2)} XRP</span><span>${fmt(p.tvl2, 2)} tokens</span></div>` : '';

  const ownerGauge = p.ownerPct != null ? `
    <div class="amm-owner-gauge-row">
      <span class="amm-owner-gauge-label">This account's share of pool</span>
      <span class="mono">${p.ownerPct.toFixed(2)}%</span>
    </div>
    <div class="amm-owner-gauge"><div class="amm-owner-gauge-fill" style="width:${Math.min(100, p.ownerPct).toFixed(2)}%"></div></div>` : '';

  const extraStats = [
    p.feeRate != null ? `<div class="wash-stat-row"><span>Trading fee</span><span class="mono">${p.feeRate.toFixed(2)}%</span></div>` : '',
    p.costBasisXrp != null ? `<div class="wash-stat-row"><span>Net contributed (cost basis)</span><span class="mono">${fmt(p.costBasisXrp, 2)} XRP</span></div>` : '',
    // XRP-side of the position ONLY, at today's pool state — deliberately
    // never combined with the token side into a claimed "total value,"
    // since that needs a price feed this app doesn't have for the
    // non-XRP leg (see the composition-shift note below when it applies).
    p.currentXrpSideValue != null ? `<div class="wash-stat-row"><span>Current XRP-side value <span style="opacity:.55;font-weight:400">(XRP leg only, not total)</span></span><span class="mono">${fmt(p.currentXrpSideValue, 2)} XRP</span></div>` : '',
  ].join('');

  const compositionNote = p.compositionShiftPct != null && p.compositionShiftPct >= 20
    ? `<div class="amm-composition-note">⚠ Pool composition has shifted ~${p.compositionShiftPct.toFixed(0)}% since this account's deposit — the numbers above reflect today's pool, not deposit-time. See the finding below for what can cause this.</div>`
    : '';

  return (reserveBar || ownerGauge || extraStats || compositionNote) ? `<div class="amm-position-visual">${reserveBar}${ownerGauge}${extraStats}${compositionNote}</div>` : '';
}

/** Fee Voting (AMMVote) and Auction Slot (AMMBid) — rendered as two
 *  visually distinct sub-blocks per spec's own explicit instruction not to
 *  conflate them: a fee vote changes the pool's NORMAL trading fee; the
 *  auction slot is a completely separate, TEMPORARY discounted-fee
 *  mechanism won by bidding LP tokens. */
/** Volume-share bar for the current auction window — owner / authorized /
 *  external, stacked. Only rendered when the targeted pool-tx fetch
 *  actually found settled trades in the window; an active slot with zero
 *  observed trades renders as an explicit empty note instead, never a
 *  fabricated 0/0/0 bar. */
function _renderAuctionWindowBlock(aw) {
  if (!aw?.applicable) return '';
  if (!aw.during.count) {
    return `<div class="govauction-block"><div class="ammgov-subtitle">📊 Auction Window Market Activity</div><div class="inspect-empty-note">No settled trades against this pool found in the fetched window during the current auction slot.</div></div>`;
  }
  const d = aw.during;
  const seg = (pct, cls) => pct > 0 ? `<div class="ledgermap-bar-fill ${cls}" style="width:${pct.toFixed(1)}%"></div>` : '';
  return `
    <div class="govauction-block">
      <div class="ammgov-subtitle">📊 Auction Window Market Activity ${aw.dataCompleteness === 'possibly-truncated' ? '<span class="lp-tag lp-tag--none">history capped</span>' : ''}</div>
      <div class="wash-stat-row"><span>Settled trades during window</span><span class="mono">${d.count} (${d.ammCount} AMM, ${d.clobCount} CLOB, ${d.hybridCount} hybrid)</span></div>
      <div class="ledgermap-bar-track" style="height:14px;display:flex;overflow:hidden;border-radius:4px">
        ${seg(d.ownerPct, 'auctionwin-seg--owner')}${seg(d.authorizedPct, 'auctionwin-seg--auth')}${seg(d.externalPct, 'auctionwin-seg--ext')}
      </div>
      <div class="govauction-auth">
        <span class="auctionwin-legend auctionwin-legend--owner">■ Owner ${d.ownerPct.toFixed(0)}%</span>
        <span class="auctionwin-legend auctionwin-legend--auth">■ Authorized ${d.authorizedPct.toFixed(0)}%</span>
        <span class="auctionwin-legend auctionwin-legend--ext">■ External ${d.externalPct.toFixed(0)}%</span>
      </div>
    </div>`;
}

/** Outbid history — who has actually WON this pool's auction slot over
 *  time, not just who holds it right now. Reconstructed from every
 *  successful AMMBid transaction in the pool's own fetched tx history. */
function _renderAuctionDominanceBlock(ad) {
  if (!ad?.applicable || !ad.totalWins) return '';
  const rows = ad.winsByAccount.slice(0, 6).map(w => `
    <div class="govvote-row">
      <span class="mono">${shortAddr(w.account)}</span>
      <span>${w.winCount} win${w.winCount === 1 ? '' : 's'}</span>
      <span class="mono">${((w.winCount / ad.totalWins) * 100).toFixed(0)}%</span>
    </div>`).join('');
  return `
    <div class="govauction-block">
      <div class="ammgov-subtitle">🏆 Auction Dominance (${ad.totalWins} bid${ad.totalWins === 1 ? '' : 's'} seen, ${ad.winsByAccount.length} distinct winner${ad.winsByAccount.length === 1 ? '' : 's'}) ${ad.dataCompleteness === 'possibly-truncated' ? '<span class="lp-tag lp-tag--none">history capped</span>' : ''}</div>
      ${rows}
    </div>`;
}

/** Auction Economics — real bid cost vs. estimated fee savings so far,
 *  only rendered when there's an actual comparison to show (i.e. the
 *  account both owns the slot AND has observed trading volume during the
 *  window) — otherwise this stays silent rather than showing a bare cost
 *  with no benefit side to compare it against. */
function _renderAuctionEconomicsBlock(ae) {
  if (!ae?.applicable || ae.estimatedFeeSavingsXrp == null) return '';
  return `
    <div class="govauction-block">
      <div class="ammgov-subtitle">💰 Auction Economics</div>
      ${ae.bidCostLp != null ? `<div class="wash-stat-row"><span>LP tokens paid for this slot</span><span class="mono">${fmt(ae.bidCostLp, 4)}</span></div>` : ''}
      <div class="wash-stat-row"><span>This account's volume during window</span><span class="mono">${fmt(ae.ownerVolumeDuring, 2)} XRP</span></div>
      <div class="wash-stat-row"><span>Estimated fee savings so far</span><span class="mono">${fmt(ae.estimatedFeeSavingsXrp, 2)} XRP</span></div>
      <div class="govauction-auth">Directional comparison only — LP tokens aren't a cash cost, and this isn't a profit figure (no price feed to convert LP tokens or the pool's non-XRP asset to a common unit).</div>
    </div>`;
}

/** Concentration of AMM Influence — LP ownership + fee-vote weight +
 *  auction-win share + trading-volume share for the top-ranked account
 *  across at least 2 of those 4 dimensions. Deliberately never labeled
 *  "control of the AMM" (per spec) — the four numbers are shown
 *  side by side so the reader draws their own conclusion about whether
 *  the correlation is meaningful, not an opaque composite score. */
function _renderAmmControlSurfaceBlock(cs) {
  if (!cs?.applicable || !cs.profiles.length) return '';
  // Round to whole percent for display, but only show a dimension when it
  // still reads as nonzero AFTER rounding — a genuine-but-tiny 0.3% share
  // would otherwise print as the misleading "0%", implying no presence
  // at all rather than a small one.
  const pct = v => Math.round(v);
  const rows = cs.profiles.slice(0, 5).map(p => `
    <div class="govvote-row">
      <span class="mono">${shortAddr(p.account)}</span>
      <span>${pct(p.lpSharePct) > 0 ? `LP ${pct(p.lpSharePct)}%` : ''}</span>
      <span>${pct(p.feeVoteWeightPct) > 0 ? `Vote ${pct(p.feeVoteWeightPct)}%` : ''}</span>
      <span>${pct(p.auctionWinSharePct) > 0 ? `Auction ${pct(p.auctionWinSharePct)}%` : ''}</span>
      <span>${pct(p.volumeSharePct) > 0 ? `Volume ${pct(p.volumeSharePct)}%` : ''}</span>
    </div>`).join('');
  return `
    <div class="govauction-block">
      <div class="ammgov-subtitle">🕸️ Concentration of AMM Influence</div>
      <div class="govauction-auth" style="margin-top:0;margin-bottom:6px">LP ownership, fee-vote weight, auction-win share, and trading-volume share shown side by side — never combined into a single "control" score.</div>
      ${rows}
    </div>`;
}

function _renderAmmGovernanceCard(entry) {
  const { currency, gov, auctionWindow, auctionDominance, auctionEconomics, controlSurface } = entry;
  if (!gov.applicable) return '';
  const currencyLabel = hexToAscii(currency);
  const v = gov.voting;
  const a = gov.auctionSlot;

  const voteRows = v.voters.slice(0, 8).map(voter => `
    <div class="govvote-row">
      <span class="mono">${shortAddr(voter.account)}</span>
      <span>${voter.feeVotedPct.toFixed(3)}% proposed</span>
      <span class="mono">${voter.weightPct.toFixed(1)}% weight</span>
    </div>`).join('');

  const auctionBlock = a.applicable ? `
    <div class="govauction-block">
      <div class="ammgov-subtitle">💺 Auction Slot ${a.isOwner ? '<span class="lp-tag lp-tag--top">This account owns it</span>' : a.isAuthorized ? '<span class="lp-tag lp-tag--early">This account is authorized</span>' : ''}</div>
      <div class="wash-stat-row"><span>Slot owner</span><span class="mono">${shortAddr(a.slotOwner)}</span></div>
      <div class="wash-stat-row"><span>Discounted fee</span><span class="mono">${a.discountedFeePct.toFixed(3)}%${a.feeReductionPct != null ? ` (${a.feeReductionPct.toFixed(0)}% reduction vs. normal)` : ''}</span></div>
      ${a.lpTokensPaid != null ? `<div class="wash-stat-row"><span>LP tokens bid</span><span class="mono">${fmt(a.lpTokensPaid, 4)}</span></div>` : ''}
      <div class="govauction-auth">${a.authAccounts.length ? `Authorized accounts (${a.authAccounts.length}): ${a.authAccounts.map(acc => `<span class="mono">${shortAddr(acc)}</span>`).join(', ')}` : 'No additional authorized accounts'}</div>
      ${a.expiration ? `<div class="wash-stat-row"><span>Expires</span><span class="mono">${escHtml(String(a.expiration))}</span></div>` : ''}
    </div>
    ${_renderAuctionWindowBlock(auctionWindow)}
    ${_renderAuctionDominanceBlock(auctionDominance)}
    ${_renderAuctionEconomicsBlock(auctionEconomics)}
    ${_renderAmmControlSurfaceBlock(controlSurface)}` : `
    <div class="govauction-block">
      <div class="ammgov-subtitle">💺 Auction Slot</div>
      <div class="inspect-empty-note">No account currently holds this pool's discounted-fee auction slot.</div>
    </div>`;

  return `
    <div class="ammgov-card">
      <div class="ammgov-title">⚖️ ${escHtml(currencyLabel)}/XRP — AMM Governance</div>
      <div class="wash-stat-row"><span>Current pool trading fee (AMMVote result)</span><span class="mono">${gov.normalFeePct.toFixed(3)}%</span></div>
      <div class="govvote-block">
        <div class="ammgov-subtitle">🗳️ Fee Voting${v.voterCount ? ` (${v.voterCount} voter${v.voterCount === 1 ? '' : 's'})` : ''}</div>
        ${v.voterCount ? `
          <div class="wash-stat-row"><span>Top voter weight</span><span class="mono">${v.top1WeightPct.toFixed(1)}%</span></div>
          <div class="wash-stat-row"><span>Top 3 voter weight</span><span class="mono">${v.top3WeightPct.toFixed(1)}%</span></div>
          ${voteRows}` : '<div class="inspect-empty-note">No active fee votes on this pool.</div>'}
      </div>
      ${auctionBlock}
    </div>`;
}

/** This account's own AMMBid history — not the pool's current auction
 *  state (that's the governance card above), but a record of how THIS
 *  account has used the mechanism over time: how many bids, how much LP
 *  value spent, who was authorized each time. */
function _renderAmmBidHistory(bidHistory) {
  if (!bidHistory?.applicable) return '';
  const rows = bidHistory.bids.slice(0, 10).map(b => `
    <div class="govvote-row">
      <span>${b.date != null ? new Date((b.date + XRPL_EPOCH) * 1000).toLocaleDateString() : '—'}</span>
      <span>${escHtml(hexToAscii(b.assetCurrency))}/${escHtml(hexToAscii(b.asset2Currency))}</span>
      <span class="mono">${b.lpTokensBid != null ? fmt(b.lpTokensBid, 4) + ' LP' : '—'}</span>
      <span>${b.authAccounts.length ? `${b.authAccounts.length} authorized` : 'none authorized'}</span>
    </div>`).join('');
  return `
    <div class="ammgov-card">
      <div class="ammgov-title">📜 This Account's Auction Bid History (${bidHistory.bidCount})</div>
      ${rows}
      ${bidHistory.bids.length > 10 ? `<div class="trustline-more">+${bidHistory.bids.length - 10} more bid(s)</div>` : ''}
    </div>`;
}

/** AMM/Liquidity's "In plain terms" summary (Inspector-wide roadmap item
 *  #10) — reuses position count + worst signal severity already computed.
 *  No new analysis. */
function buildAmmPlainSummary(amm) {
  if (!amm.positions.length) return { tone: 'ok', text: `This account does not currently hold a position in any AMM liquidity pool.` };
  const hasCrit = amm.signals.some(s => s.sev === 'critical');
  const hasWarn = amm.signals.some(s => s.sev === 'warn');
  const tone = hasCrit ? 'crit' : hasWarn ? 'warn' : 'ok';
  const n = amm.positions.length;
  let text = `This account actively provides liquidity to ${n} pool${n === 1 ? '' : 's'}.`;
  text += (hasCrit || hasWarn) ? ' See below for the specific governance or liquidity pattern flagged for review.' : ' No unusual governance or liquidity pattern was found.';
  return { tone, text };
}

function renderAmmPanel(amm, lines, ammGovernanceByPool = [], ammBidHistory = null) {
  const el = $('inspect-amm-body');
  if (!el) return;

  const dense = `
    <div class="audit-items">
      ${amm.signals.map(s => auditRow(s)).join('')}
    </div>
    ${ammGovernanceByPool.map(g => _renderAmmGovernanceCard(g)).join('')}
    ${_renderAmmBidHistory(ammBidHistory)}`;

  el.innerHTML = `
    ${_renderPlainSummaryBox(buildAmmPlainSummary(amm))}
    ${amm.positions.length ? `
    <div class="amm-positions">
      ${amm.positions.map(p => `
        <div class="amm-position-card">
          <div class="amm-position-currency mono">${shortAddr(p.currency)}</div>
          <div class="amm-position-meta">
            <span>Pool: ${shortAddr(p.issuer)}</span>
            <span class="amm-position-balance">${fmt(Math.abs(p.balance), 4)} LP tokens</span>
          </div>
          ${_renderAmmPositionVisual(p)}
        </div>`).join('')}
    </div>` : ''}
    <div class="simple-only" style="font-size:.76rem;color:rgba(255,255,255,.4);padding:8px 2px;margin-bottom:6px">
      Switch to <strong>⚗ Advanced</strong> (top of page) to see governance, bid history, and the full evidence.
    </div>
    <div class="advanced-only">${dense}</div>
  `;
  _setBadge('badge-amm', amm.signals);
}

/* ── Trustlines ──────────────────────────────────── */
function renderTrustlines(lines) {
  const badge = $('trust-count-badge');
  if (badge) badge.textContent = lines.length;

  const tbody = $('inspect-trust-body');
  if (!tbody) return;

  if (!lines.length) { tbody.innerHTML = `<div class="inspect-empty-note">No trustlines found.</div>`; return; }

  // Trustlines is pure reference data with no risk/finding model of its
  // own (unlike every other upgraded section) — the Simple-mode summary
  // here is a plain count, not a severity reading that would fabricate a
  // risk tone this raw list genuinely doesn't have.
  const frozenCount = lines.filter(l => l.freeze || l.freeze_peer).length;
  const rows = lines.map(l => {
    const frozen   = l.freeze        ? '<span class="trustline-frozen">Frozen</span>' : '';
    const peerFrz  = l.freeze_peer   ? '<span class="trustline-frozen trustline-frozen--peer">Issuer Frozen</span>' : '';
    const noRipple = l.no_ripple     ? '<span class="trustline-norip">NoRipple</span>' : '';
    return `
      <div class="trustline-row">
        <span class="trustline-currency">${escHtml(hexToAscii(l.currency))}</span>
        <span class="trustline-issuer mono">${shortAddr(l.account)}</span>
        <span class="trustline-balance mono">${escHtml(l.balance)} / ${escHtml(l.limit)}</span>
        <span class="trustline-flags">${frozen}${peerFrz}${noRipple}</span>
      </div>`;
  }).join('');

  tbody.innerHTML = `
    ${_renderPlainSummaryBox({
      tone: frozenCount ? 'warn' : 'ok',
      text: `This account holds ${lines.length} trustline${lines.length === 1 ? '' : 's'}.${frozenCount ? ` ${frozenCount} of them ${frozenCount === 1 ? 'is' : 'are'} frozen.` : ''}`,
    })}
    <div class="simple-only" style="font-size:.76rem;color:rgba(255,255,255,.4);padding:8px 2px;margin-bottom:6px">
      Switch to <strong>⚗ Advanced</strong> (top of page) to see every trustline individually.
    </div>
    <div class="advanced-only">${rows}</div>`;
}

/* ── Transaction Timeline ────────────────────────── */
/** Transaction History's "behavior fingerprint" (Inspector-wide roadmap
 *  item #10/#15) — a plain tally of transaction types, computed directly
 *  from txList (no new analysis, just counting what's already fetched),
 *  so the raw 60-row timeline becomes evidence for a conclusion Simple
 *  mode already gave, rather than the only thing Simple mode sees. */
function _computeTxTypeFingerprint(txList) {
  const counts = {};
  for (const { tx } of txList) {
    const t = tx.TransactionType || 'Unknown';
    counts[t] = (counts[t] || 0) + 1;
  }
  const total = txList.length;
  return Object.entries(counts)
    .map(([type, count]) => ({ type, count, pct: total > 0 ? (count / total) * 100 : 0 }))
    .sort((a, b) => b.count - a.count);
}

function _renderTxTypeFingerprint(fingerprint) {
  if (!fingerprint.length) return '';
  const top = fingerprint.slice(0, 5);
  const otherPct = fingerprint.slice(5).reduce((s, f) => s + f.pct, 0);
  const segments = [...top, ...(otherPct > 0.5 ? [{ type: 'Other', pct: otherPct }] : [])];
  return `
    <div class="tx-fingerprint">
      <div class="tx-fingerprint-title">Transaction Type Breakdown</div>
      <div class="tx-fingerprint-bar">${segments.map((s, i) => `<div class="tx-fingerprint-seg" style="width:${s.pct.toFixed(1)}%;background:${_VOLCONC_SEGMENT_COLORS[i % _VOLCONC_SEGMENT_COLORS.length]}" data-tooltip="${escHtml(`${s.type}: ${s.pct.toFixed(0)}%`)}"></div>`).join('')}</div>
      <div class="tx-fingerprint-legend">${segments.map((s, i) => `<span class="tx-fingerprint-legend-item"><span class="tx-fingerprint-swatch" style="background:${_VOLCONC_SEGMENT_COLORS[i % _VOLCONC_SEGMENT_COLORS.length]}"></span>${escHtml(s.type)} ${s.pct.toFixed(0)}%</span>`).join('')}</div>
      <p class="widget-help" style="opacity:.5;font-size:.76rem;margin-top:6px">
        Counts every transaction touching this account — as sender OR counterparty (e.g. a trustline held
        by this account being traded by someone else's OfferCreate, or an inbound Payment this account never
        sent) — not just transactions this account itself initiated. See Wash Trading's own Offer Creates /
        Offer Cancels counts below for orders this specific account placed.
      </p>
    </div>`;
}

// Pagination/filter state for the transaction timeline — module-level so
// _applyTxTimelineFilter/_loadMoreTxTimeline (fired from the filter <select>
// / Load More button) can re-render without threading state through every
// call site. Reset whenever the inspected address changes, not on every
// re-render (an unrelated re-render mid-session must not silently reset a
// filter/page the user already set — same discipline as this file's other
// documented render-state-persistence fixes).
let _txTimelineAddr = null;
let _txTimelineShown = 60;
let _txTimelineTypeFilter = 'all';
let _txTimelineDirFilter = 'all';

window._applyTxTimelineFilter = function() {
  _txTimelineTypeFilter = document.getElementById('tx-filter-type')?.value || 'all';
  _txTimelineDirFilter = document.getElementById('tx-filter-dir')?.value || 'all';
  _txTimelineShown = 60;
  renderTxTimeline(window._lastTxList || [], _txTimelineAddr);
};
window._loadMoreTxTimeline = function() {
  _txTimelineShown += 60;
  renderTxTimeline(window._lastTxList || [], _txTimelineAddr);
};

function renderTxTimeline(txList, addr) {
  const el = $('inspect-tx-timeline');
  if (!el) return;
  if (addr !== _txTimelineAddr) {
    _txTimelineAddr = addr;
    _txTimelineShown = 60;
    _txTimelineTypeFilter = 'all';
    _txTimelineDirFilter = 'all';
  }

  // The type-breakdown fingerprint always describes the FULL fetched
  // history — an overview stat, not something that should shrink/lie just
  // because a filter below happens to be narrowed to one type/direction.
  const fingerprintHtml = _renderTxTypeFingerprint(_computeTxTypeFingerprint(txList));

  const txBadgeEl = $('badge-tx');
  if (txBadgeEl) {
    const cap = window._inspectMaxTx || 5000;
    const atCap = txList.length >= cap;
    txBadgeEl.textContent = txList.length.toLocaleString() + ' tx' + (atCap ? ' (cap reached)' : '');
    txBadgeEl.className = 'section-badge section-badge--neutral';
    if (atCap) txBadgeEl.title = `Fetched ${txList.length.toLocaleString()} transactions — cap of ${cap.toLocaleString()} reached. Set window._inspectMaxTx = 20000 in console to go deeper.`;
  }

  const types = [...new Set(txList.map(({ tx }) => tx.TransactionType || 'Unknown'))].sort();
  const filterBar = `
    <div style="display:flex;gap:8px;margin-bottom:10px;flex-wrap:wrap">
      <select id="tx-filter-type" class="xrpl-input" style="width:auto;font-size:.78rem;padding:6px 10px" onchange="_applyTxTimelineFilter()">
        <option value="all">All types</option>
        ${types.map(t => `<option value="${escHtml(t)}" ${_txTimelineTypeFilter === t ? 'selected' : ''}>${escHtml(t)}</option>`).join('')}
      </select>
      <select id="tx-filter-dir" class="xrpl-input" style="width:auto;font-size:.78rem;padding:6px 10px" onchange="_applyTxTimelineFilter()">
        <option value="all">All directions</option>
        <option value="out" ${_txTimelineDirFilter === 'out' ? 'selected' : ''}>Outbound</option>
        <option value="in" ${_txTimelineDirFilter === 'in' ? 'selected' : ''}>Inbound</option>
        <option value="self" ${_txTimelineDirFilter === 'self' ? 'selected' : ''}>Self</option>
      </select>
    </div>`;

  // "Direction" only cleanly applies to Account/Destination-shaped
  // transactions (Payment and similar) — a non-Payment type with no
  // Destination at all (e.g. a plain OfferCreate) still counts as
  // "Outbound" when this account is the one that submitted it, since
  // that's the closest honest read of "which side is this account on."
  const filtered = txList.filter(({ tx }) => {
    if (_txTimelineTypeFilter !== 'all' && (tx.TransactionType || 'Unknown') !== _txTimelineTypeFilter) return false;
    if (_txTimelineDirFilter !== 'all') {
      const isSelf = tx.Account === addr && tx.Destination === addr;
      const isOut  = tx.Account === addr && !isSelf;
      const isIn   = tx.Destination === addr && tx.Account !== addr;
      if (_txTimelineDirFilter === 'out' && !isOut) return false;
      if (_txTimelineDirFilter === 'in' && !isIn) return false;
      if (_txTimelineDirFilter === 'self' && !isSelf) return false;
    }
    return true;
  });

  const items = filtered.slice(0, _txTimelineShown);
  const rowsHtml = items.length
    ? items.map(({ tx, meta }) => {
        const type    = tx.TransactionType || 'Unknown';
        const success = meta?.TransactionResult === 'tesSUCCESS';
        const risk    = txRiskLevel(tx, meta, addr);
        const ts      = getCloseTime(tx);
        const timeStr = ts ? new Date(ts * 1000).toLocaleString() : '—';
        const brief   = txBrief(tx, addr);

        const explorerUrl = tx.hash ? `https://livenet.xrpl.org/transactions/${tx.hash}` : null;
        const xrpscanUrl  = tx.hash ? `https://xrpscan.com/tx/${tx.hash}` : null;
        return `
          <div class="tx-row tx-row--${risk}">
            <span class="tx-type-badge tx-type-badge--${typeBadgeClass(type)}">${escHtml(type)}</span>
            <span class="tx-brief">${brief}</span>
            <span class="tx-result ${success ? 'tx-ok' : 'tx-fail'}">${success ? '✓' : '✗'}</span>
            <span class="tx-time">${timeStr}</span>
            <span class="tx-links">
              ${tx.hash ? `<a href="javascript:void(0)" onclick="openTxDetailDrawer('${escHtml(tx.hash)}')" class="tx-explorer-link" title="Inspect this transaction">🔬</a>` : ''}
              ${explorerUrl ? `<a href="${explorerUrl}" target="_blank" rel="noopener" class="tx-explorer-link" title="View on XRPL Livenet">🔗</a>` : ''}
              ${xrpscanUrl ? `<a href="${xrpscanUrl}" target="_blank" rel="noopener" class="tx-explorer-link" title="View on XRPScan">🔍</a>` : ''}
            </span>
          </div>`;
      }).join('')
    : `<div class="inspect-empty-note">No transactions match the current filter${filtered.length !== txList.length ? '' : 'ing'}.</div>`;

  el.innerHTML = `
    ${fingerprintHtml}
    <div class="simple-only" style="font-size:.76rem;color:rgba(255,255,255,.4);padding:8px 2px;margin-bottom:6px">
      Switch to <strong>⚗ Advanced</strong> (top of page) to see the transaction-by-transaction timeline.
    </div>
    <div class="advanced-only">
      ${filterBar}
      ${rowsHtml}
      ${filtered.length > items.length
        ? `<button class="tx-more" onclick="_loadMoreTxTimeline()" style="cursor:pointer;width:100%;background:rgba(0,212,255,.08);border:1px solid rgba(0,212,255,.25);border-radius:8px;padding:10px;color:var(--accent);font-size:.82rem;font-family:inherit">Load more — showing ${items.length} of ${filtered.length}${filtered.length !== txList.length ? ' matching' : ''}</button>`
        : (filtered.length ? `<div class="tx-more">Showing all ${filtered.length}${filtered.length !== txList.length ? ' matching' : ''} transaction${filtered.length === 1 ? '' : 's'}</div>` : '')}
    </div>`;
}


/** Horizontal "Total In vs Total Out vs Current Balance" bar, with the
 *  outbound bar segmented by destination category (black hole / exchange /
 *  new wallet / other) — the one analysis category (fund flow) that was
 *  otherwise only ever described in prose, with nothing to look at. Returns
 *  an HTML string rather than mounting itself, since it's reused in both the
 *  Fund Flow panel and the Full Report. */
function buildFundFlowSummaryBar(balXrp, fundFlow, inboundFlow) {
  const totalIn  = Number(inboundFlow?.totalIn || 0);
  const totalOut = Number(fundFlow?.totalOut || 0);
  const balance  = Number(balXrp || 0);
  if (totalIn <= 0 && totalOut <= 0) return '<div class="inspect-empty-note">No inbound or outbound XRP flow found in the analysed transaction history.</div>';

  // Priority order avoids double-counting a destination that could match
  // more than one bucket (e.g. a freshly-created exchange deposit address).
  const blackholeAddrs = new Set((fundFlow?.blackHoleDests || []).map(d => d.addr));
  const exchangeAddrs  = new Set((fundFlow?.exchangeDests  || []).map(d => d.addr));
  const newWalletAddrs = new Set((fundFlow?.newWalletDests || []).map(d => d.addr));
  let blackholeXrp = 0, exchangeXrp = 0, newWalletXrp = 0, otherXrp = 0;
  for (const d of (fundFlow?.destinations || [])) {
    if (blackholeAddrs.has(d.addr))      blackholeXrp += d.totalXrp;
    else if (exchangeAddrs.has(d.addr))  exchangeXrp  += d.totalXrp;
    else if (newWalletAddrs.has(d.addr)) newWalletXrp += d.totalXrp;
    else                                 otherXrp     += d.totalXrp;
  }

  const maxVal = Math.max(totalIn, totalOut, balance, 1);
  const pct = v => (v > 0 ? Math.max(1.5, (v / maxVal) * 100) : 0).toFixed(1);

  const outSegments = [
    { label: 'Black hole', xrp: blackholeXrp, color: CP_CATEGORY_COLOR.blackhole },
    { label: 'Exchange',   xrp: exchangeXrp,  color: CP_CATEGORY_COLOR.exchange },
    { label: 'New wallet', xrp: newWalletXrp, color: CP_CATEGORY_COLOR.newWallet },
    { label: 'Other',      xrp: otherXrp,     color: CP_CATEGORY_COLOR.other },
  ].filter(s => s.xrp > 0);

  const outBarWidth = totalOut > 0 ? Math.max(1.5, (totalOut / maxVal) * 100) : 0;
  const outBarSegments = outSegments.map(s => {
    const segPct = totalOut > 0 ? (s.xrp / totalOut) * 100 : 0;
    return `<div style="width:${segPct.toFixed(1)}%;background:${s.color};height:100%" title="${escHtml(s.label)}: ${fmt(s.xrp,2)} XRP"></div>`;
  }).join('');

  const row = (label, valueXrp, widthPct, barInner, color) => `
    <div style="display:flex;align-items:center;gap:10px;margin-bottom:8px">
      <div style="width:84px;font-size:.72rem;color:rgba(255,255,255,.55);flex-shrink:0">${label}</div>
      <div style="flex:1;height:16px;border-radius:5px;overflow:hidden;background:rgba(255,255,255,.05)">
        <div style="width:${widthPct}%;height:100%;display:flex">${barInner || `<div style="width:100%;height:100%;background:${color}"></div>`}</div>
      </div>
      <div class="mono" style="width:92px;text-align:right;font-size:.75rem;color:rgba(255,255,255,.75);flex-shrink:0">${fmt(valueXrp,2)} XRP</div>
    </div>`;

  const legend = outSegments.map(s => `<span style="font-size:.66rem;color:${s.color};margin-right:12px">● ${escHtml(s.label)} ${fmt(s.xrp,0)}</span>`).join('');

  return `
    <div style="margin-bottom:16px">
      <div style="font-size:.65rem;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:.08em;margin-bottom:8px">
        Fund Flow — Inbound vs Outbound vs Current Balance
      </div>
      ${row('Total In',    totalIn,  pct(totalIn),  null, '#50fa7b')}
      ${row('Total Out',   totalOut, outBarWidth,   outSegments.length ? outBarSegments : null, 'rgba(255,255,255,.3)')}
      ${row('Balance Now', balance,  pct(balance),  null, '#00d4ff')}
      ${outSegments.length ? `<div style="margin-top:2px">${legend}</div>` : ''}
    </div>`;
}

/* ── Fund Flow Panel ─────────────────────────────── */
/** "In plain terms" lead sentence for Fund Flow Tracer — same shared box
 *  as Drain Risk, same "synthesize what's already computed" approach as
 *  Follow the Money (a separate, higher-level narrative in Account
 *  Behavior); this one speaks specifically to what THIS section's own
 *  ranked destination list shows, for a reader who opened this section
 *  directly. */
function buildFundFlowPlainSummary(flow) {
  if (!flow.destinations.length) return null;
  const top = flow.destinations[0];
  const pct = flow.totalOut > 0 ? (top.totalXrp / flow.totalOut * 100) : 0;
  const label = top.entity?.name || shortAddr(top.addr);
  const destNote = top.entity?.type === 'blackhole'
    ? ' — a black hole address, meaning those funds can never be recovered'
    : top.entity?.type === 'exchange' ? ' — a known exchange' : '';

  let tone = 'ok';
  if (top.entity?.type === 'blackhole') tone = 'crit';
  else if (flow.newWalletDests?.length) tone = 'warn';

  const text = flow.uniqueDests === 1
    ? `All of this account's tracked outbound XRP (${fmt(flow.totalOut, 2)} XRP) went to a single destination: ${label}${destNote}.`
    : `The largest share of this account's outbound XRP — ${fmt(top.totalXrp, 2)} XRP, ${pct.toFixed(0)}% of everything sent out — went to ${label}${destNote}. The rest was split across ${flow.uniqueDests - 1} other destination${flow.uniqueDests - 1 === 1 ? '' : 's'}.`;

  return { tone, text };
}

function renderFundFlowPanel(flow, balXrp, inboundFlow) {
  const el = $('inspect-fundflow-body');
  if (!el) return;

  const badge = $('badge-fundflow');

  if (!flow.timeline.length && !flow.destinations.length) {
    el.innerHTML = `<div class="audit-row audit-row--ok"><span class="audit-icon">✓</span><div class="audit-text"><div class="audit-label">No outbound payments found in analysed transaction history</div></div></div>`;
    if (badge) { badge.textContent = 'Clear'; badge.className = 'section-badge section-badge--ok'; }
    return;
  }

  const unknownAmountNote = flow.unknownAmountCount
    ? `<div class="inspect-empty-note" style="margin-bottom:8px">⚠ ${flow.unknownAmountCount} destination(s) include at least one payment whose exact delivered amount this ledger didn't record (a known XRPL limitation for some pre-2014 partial payments) — totals below may understate what was actually sent.</div>`
    : '';
  const exchangeAlert = flow.exchangeDests.length
    ? `<div class="flow-alert flow-alert--exchange">💱 Funds reached ${flow.exchangeDests.length} known exchange(s): ${flow.exchangeDests.map(d => d.entity.name).join(', ')}</div>`
    : '';
  const blackholeAlert = flow.blackHoleDests.length
    ? `<div class="flow-alert flow-alert--blackhole">🕳 Funds sent to black hole address — irrecoverable!</div>`
    : '';
  const newWalletAlert = flow.newWalletDests?.length
    ? `<div class="flow-alert" style="background:rgba(255,85,85,.06);border:1px solid rgba(255,85,85,.25);color:#ff5555;border-radius:8px;padding:10px 14px;margin-bottom:8px">
        ⚠️ <strong>${flow.newWalletDests.length} destination(s) are brand-new wallets</strong> (Sequence &lt; 10) receiving large XRP amounts.
        New wallets receiving large transfers shortly after creation are a common pattern in drain attacks — the attacker creates a disposable wallet and drains funds there.
       </div>`
    : '';

  el.innerHTML = `
    ${buildFundFlowSummaryBar(balXrp, flow, inboundFlow)}
    ${unknownAmountNote}
    ${newWalletAlert}${exchangeAlert}${blackholeAlert}
    <div class="flow-summary">
      <div class="flow-stat"><span>Unique destinations</span><b>${flow.uniqueDests}</b></div>
      <div class="flow-stat"><span>Path payments</span><b>${flow.totalPathPay}</b></div>
      <div class="flow-stat"><span>Exchange dests</span><b>${flow.exchangeDests.length}</b></div>
    </div>

    <div class="flow-section-h">📍 Top Destinations</div>
    <div class="flow-dest-list">
      ${flow.destinations.map((d, i) => {
        const pct = flow.totalOut > 0 ? (d.totalXrp / flow.totalOut * 100) : 0;
        const entityBadge = d.entity
          ? `<span class="flow-entity-badge flow-entity--${d.entity.type}">${escHtml(d.entity.name)}</span>`
          : '';
        const pathBadge = d.pathCount > 0
          ? `<span class="flow-path-badge">${d.maxHops}-hop path ×${d.pathCount}</span>`
          : '';
        const tokenChips = d.tokens.slice(0,2).map(t => `<span class="flow-token-chip">${escHtml(t.k.split('.')[0])}</span>`).join('');
        return `
          <div class="flow-dest-row">
            <div class="flow-dest-rank ${d.entity?.type === 'exchange' ? 'flow-rank--exchange' : d.entity?.type === 'blackhole' ? 'flow-rank--blackhole' : ''}">${i+1}</div>
            <div class="flow-dest-info">
              <div class="flow-dest-top">
                <button class="addr-link mono cut flow-dest-addr" data-addr="${escHtml(d.addr)}" title="${escHtml(d.addr)}">${escHtml(shortAddr(d.addr))}</button>
                <a href="https://xrpscan.com/account/${escHtml(d.addr)}" target="_blank" rel="noopener" class="tx-explorer-link" title="View on XRPScan">🔍</a>
                ${entityBadge}${pathBadge}${tokenChips}
              </div>
              <div class="flow-bar-row">
                <div class="flow-dest-bar"><div class="flow-dest-fill" style="width:${Math.min(100,pct).toFixed(1)}%;background:${d.entity?.type === 'exchange' ? '#00d4ff' : d.entity?.type === 'blackhole' ? '#ff5555' : 'rgba(80,250,123,.7)'}"></div></div>
                <span class="mono flow-dest-pct">${pct.toFixed(0)}%</span>
              </div>
              <div class="flow-dest-meta">
                <span class="mono">${fmt(d.totalXrp, 2)} XRP</span>
                <span class="flow-dest-cnt">${d.txCount} tx</span>
                ${d.txCount > 1 ? `<span class="flow-dest-span">${_fmtDateRange(d.firstSeen, d.lastSeen)}</span>` : ''}
              </div>
            </div>
          </div>`;
      }).join('')}
    </div>

    <div class="simple-only" style="font-size:.76rem;color:rgba(255,255,255,.4);padding:8px 2px;margin-top:10px">
      Want the full transaction-by-transaction timeline of every payment above? Switch to <strong>⚗ Advanced</strong> (top of page).
    </div>
    <div class="advanced-only">
    <div class="flow-section-h" style="margin-top:18px">⏱ Outflow Timeline</div>
    <div class="flow-timeline">
      ${flow.timeline.map(o => {
        const date  = new Date((o.ts) * 1000).toLocaleDateString();
        const time  = new Date((o.ts) * 1000).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
        const amt   = o.amtXrp > 0 ? `${fmt(o.amtXrp, 2)} XRP` : (o.amtToken ? `${fmt(o.amtToken.value, 2)} ${o.amtToken.currency}` : '—');
        const ent   = getEntity(o.dest);
        const entityTag = ent ? `<span class="flow-entity-badge flow-entity--${ent.type}" style="font-size:.65rem">${escHtml(ent.name)}</span>` : '';
        return `
          <div class="flow-tx-row">
            <span class="flow-tx-date">${date} ${time}</span>
            <button class="addr-link mono cut flow-tx-dest" data-addr="${escHtml(o.dest)}" title="${escHtml(o.dest)}">${escHtml(shortAddr(o.dest))}</button>
            ${entityTag}
            <span class="flow-tx-amt mono">${amt}</span>
            ${o.isPathPay ? `<span class="flow-path-tag">${o.hopCount}-hop</span>` : ''}
          </div>`;
      }).join('')}
    </div>
    </div>
  `;

  if (badge) {
    const hasCritical = flow.blackHoleDests.length || flow.exchangeDests.length > 2;
    badge.textContent = `${flow.uniqueDests} dests`;
    badge.className = `section-badge section-badge--${hasCritical ? 'crit' : flow.uniqueDests > 0 ? 'warn' : 'ok'}`;
  }
}

function renderFlowMotifsPanel(motifs) {
  const el = document.getElementById('inspect-flowmotifs-body');
  const badge = document.getElementById('badge-flowmotifs');
  if (!el) return;

  if (!motifs?.applicable) {
    el.innerHTML = `<div class="audit-row audit-row--ok"><span class="audit-icon">✓</span><div class="audit-text"><div class="audit-label">No repeated flow patterns found</div><div class="audit-detail">No round-trip payments, AMM deposit/withdrawal cycles, or exchange round-trips detected in the analysed history.</div></div></div>`;
    if (badge) { badge.textContent = 'Clear'; badge.className = 'section-badge section-badge--ok'; }
    return;
  }

  if (badge) {
    badge.textContent = `${motifs.motifs.length} pattern${motifs.motifs.length === 1 ? '' : 's'}`;
    badge.className = 'section-badge section-badge--neutral';
  }

  el.innerHTML = `
    <div class="flowmotif-caveat">A pattern existing here does not by itself mean anything improper — see Wash Execution and AMM / Liquidity above for interpretation and evidence.</div>
    ${motifs.motifs.map(m => `
      <div class="flowmotif-card">
        <div class="flowmotif-icon">${m.icon}</div>
        <div class="flowmotif-body">
          <div class="flowmotif-label mono">${escHtml(m.label)}</div>
          <div class="flowmotif-detail">${escHtml(m.detail)}</div>
        </div>
        ${m.counterparty ? `<button class="flowmotif-inspect" onclick="inspectorLoadAddr('${m.counterparty}')" title="Inspect this counterparty">Inspect →</button>` : ''}
      </div>`).join('')}
    <div class="flowmotif-caveat" style="margin-top:8px">True multi-hop circular flow across OTHER accounts (A → B → C → A) can't be detected from this account's own transaction history alone — those accounts' own history would be needed.</div>
  `;
}

function _fmtDateRange(firstTs, lastTs) {
  if (!firstTs || !lastTs) return '';
  const d1 = new Date(firstTs * 1000).toLocaleDateString();
  const d2 = new Date(lastTs * 1000).toLocaleDateString();
  return d1 === d2 ? d1 : `${d1} – ${d2}`;
}

/* ── Issuer Connections Panel ────────────────────── */
/** Issuer Connections' "In plain terms" summary (Inspector-wide roadmap
 *  item #10) — reuses holder count, top-holder concentration, and mirror-
 *  cluster count already computed. Mirror clusters are explicitly named
 *  as inferred, never verified common ownership, matching the same
 *  caveat used everywhere else this signal appears. */
function buildIssuerConnectionsPlainSummary(data) {
  if (data.totalIssued <= 0) return { tone: 'ok', text: `This account does not issue any token — there is no supply distribution to analyze.` };
  const hasCrit = data.signals.some(s => s.sev === 'critical');
  const hasWarn = data.signals.some(s => s.sev === 'warn');
  const tone = hasCrit ? 'crit' : hasWarn ? 'warn' : 'ok';
  const topPct = data.topHolders.length ? (data.topHolders[0].balance / data.totalIssued) * 100 : null;
  let text = `This issuer's token has ${data.holderCount} trustline holder${data.holderCount === 1 ? '' : 's'}`;
  if (topPct != null) text += `, with the top holder controlling ${topPct.toFixed(0)}% of supply`;
  text += '.';
  if (data.mirrorGroups.length) text += ` ${data.mirrorGroups.length} possible mirror-wallet cluster(s) were found — inferred, not verified common ownership.`;
  text += (hasCrit || hasWarn) ? ' See below for the specific concentration or cluster pattern flagged.' : '';
  return { tone, text };
}

function renderIssuerConnectionsPanel(data, lines) {
  const el = $('inspect-issuer-connections-body');
  if (!el) return;

  const totalIssued = data.totalIssued;
  const badge = $('badge-issuer-connections');

  el.innerHTML = `
    ${_renderPlainSummaryBox(buildIssuerConnectionsPlainSummary(data))}
    <div class="simple-only" style="font-size:.76rem;color:rgba(255,255,255,.4);padding:8px 2px;margin-bottom:6px">
      Switch to <strong>⚗ Advanced</strong> (top of page) to see the full holder/distribution breakdown and evidence.
    </div>
    <div class="advanced-only">
    <div class="audit-items">
      ${data.signals.map(s => auditRow(s)).join('')}
    </div>

    ${totalIssued > 0 ? `
    <div class="conn-stats">
      <div class="conn-stat"><span>Total Supply</span><b class="mono">${fmt(totalIssued, 0)}</b></div>
      <div class="conn-stat"><span>Trustline Holders</span><b>${data.holderCount}</b></div>
      <div class="conn-stat"><span>Accts Created</span><b>${data.createdAccts.length}</b></div>
      <div class="conn-stat"><span>Distribution txs</span><b>${data.distributions.length}</b></div>
    </div>

    ${data.topHolders.length ? `
    <div class="conn-section-h">🏆 Supply Distribution — Top Holders</div>
    <div class="conn-holders">
      ${data.topHolders.map((h, i) => {
        const pct = totalIssued > 0 ? h.balance / totalIssued * 100 : 0;
        const fillColor = pct > 50 ? '#ff5555' : pct > 25 ? '#ffb86c' : pct > 10 ? '#f1fa8c' : '#50fa7b';
        return `
          <div class="conn-holder-row">
            <span class="conn-holder-rank">${i+1}</span>
            <button class="addr-link mono cut conn-holder-addr" onclick="openRelationshipDrawer('${escHtml(h.addr)}')" title="${escHtml(h.addr)}">${escHtml(shortAddr(h.addr))}</button>
            <div class="conn-holder-bar-wrap">
              <div class="conn-holder-bar">
                <div class="conn-holder-fill" style="width:${Math.min(100, pct).toFixed(1)}%;background:${fillColor}"></div>
              </div>
              <span class="mono conn-holder-pct">${pct.toFixed(1)}%</span>
            </div>
            <span class="mono conn-holder-amt">${fmt(h.balance, 0)} ${escHtml(h.currency.slice(0,8))}</span>
          </div>`;
      }).join('')}
    </div>` : ''}

    ${data.createdAccts.length ? `
    <div class="conn-section-h">🆕 Accounts Created by This Issuer</div>
    <div class="conn-created-list">
      ${data.createdAccts.slice(0, 12).map(a => `
        <button class="addr-chip mono" data-addr="${escHtml(a)}" title="${escHtml(a)}">${escHtml(shortAddr(a))}</button>
      `).join('')}
      ${data.createdAccts.length > 12 ? `<span style="opacity:.65;font-size:.78rem">+${data.createdAccts.length - 12} more</span>` : ''}
    </div>` : ''}

    ` : ''}

    ${data.mirrorGroups.length ? `
    <div class="conn-section-h">🔁 Mirror Wallet Clusters</div>
    <div class="conn-mirror-list">
      ${data.mirrorGroups.map(g => `
        <div class="conn-mirror-group">
          <div class="conn-mirror-h">
            <span>~${fmt(g.approxAmt, 0)} tokens · ${g.accounts.length} wallets</span>
            <span class="conn-mirror-tier conn-mirror-tier--${g.tier?.toLowerCase()}" title="${g.totalFamilies} independent signal(s): amount similarity${g.timingCorrelated ? ' + funding timing' : ''}${g.issuerCreated ? ' + issuer-created' : ''}">${g.tier} evidence</span>
          </div>
          <div class="conn-mirror-addrs">
            ${g.accounts.slice(0, 8).map(a => `
              <button class="addr-chip mono" data-addr="${escHtml(a.addr)}" title="${escHtml(a.addr)}">${escHtml(shortAddr(a.addr))}</button>
            `).join('')}
            ${g.accounts.length > 8 ? `<span class="conn-mirror-more">+${g.accounts.length - 8} more</span>` : ''}
          </div>
        </div>
      `).join('')}
    </div>` : ''}
    </div>
  `;

  if (badge) {
    const sev = data.signals.some(s => s.sev === 'critical') ? 'crit'
      : data.signals.some(s => s.sev === 'warn') ? 'warn'
      : data.signals.some(s => s.sev === 'info') ? 'neutral'
      : 'ok';
    badge.className = `section-badge section-badge--${sev}`;
    badge.textContent = totalIssued > 0 ? `${data.holderCount} holders` : 'No issuance';
  }
}

/* ── Distribution & Market Flow Panel (on-demand) ──
   State lives here (not threaded through render args) because it survives
   across the button click → loading → result sequence, which is triggered
   independently of the rest of the report re-rendering. Reset on every
   fresh inspection by renderDistMarketFlowPanel, exactly like _dom is reset
   by _warmDOMCache on remount. */
let _distMarketFlowState = { forAddr: null, issuerConnAnalysis: null, issuedCurrency: null, holderCohorts: null, loading: false, error: null, result: null };

function buildDistMarketFlowPlainSummary(result) {
  if (!result) return null;
  if (!result.applicable) return { tone: 'ok', text: result.reason };
  const f = result.findings[0];
  if (!f || f.sev === 'info' && !result.syncGroups.length && !result.proceedsConsolidation.length) {
    return { tone: 'ok', text: `Checked the top ${result.cohort.length} direct recipient(s) of this issuer's token for synchronized selling and proceeds consolidation — neither was found.` };
  }
  const tone = f.sev === 'warn' ? 'warn' : 'ok';
  return { tone, text: `${result.cohort.length} top recipients checked — ${result.syncGroups.length ? 'synchronized selling' : ''}${result.syncGroups.length && result.proceedsConsolidation.length ? ' and ' : ''}${result.proceedsConsolidation.length ? 'proceeds consolidation' : ''} observed. This describes what happened on-ledger, not why — see below.` };
}

function renderDistMarketFlowPanel(issuerAnalysis, issuerConnAnalysis, issuerMarketActivity, holderCohorts = null) {
  const el = $('inspect-dist-market-flow-body');
  if (!el) return;
  _distMarketFlowState = {
    forAddr: _currentAddr,
    issuerConnAnalysis,
    issuedCurrency: issuerMarketActivity?.issuedCurrencies?.[0] || null,
    holderCohorts,
    isIssuer: !!issuerAnalysis?.isIssuer,
    loading: false, error: null, result: null,
  };
  _renderDistMarketFlowBody();
}

// Reuses the exact visual language of Important Events Timeline
// (.events-timeline*, defined for that section) rather than inventing a
// second timeline style — not clickable/jump-linked like that one, since
// these events describe OTHER wallets' activity, not sections within this
// account's own report.
function _renderMarketSetupTimeline(timeline) {
  if (!timeline?.length) return '';
  const moduleColor = { Distribution: '#8be9fd', Selling: '#ffb86c', Proceeds: '#ff79c6' };
  return `
    <div class="conn-section-h">🕓 Market Setup Timeline</div>
    <div class="events-timeline">
      ${timeline.map(ev => `
        <div class="events-timeline-item" style="cursor:default">
          <div class="events-timeline-dot">${ev.icon}</div>
          <div class="events-timeline-body">
            <div class="events-timeline-date">${new Date((ev.date + XRPL_EPOCH) * 1000).toLocaleString()}</div>
            <div class="events-timeline-label">${escHtml(ev.label)}</div>
            ${ev.detail ? `<div class="events-timeline-detail">${escHtml(ev.detail)}</div>` : ''}
            <div class="events-timeline-module" style="color:${moduleColor[ev.module] || 'inherit'}">${escHtml(ev.module)}</div>
          </div>
        </div>`).join('')}
    </div>`;
}

function _renderDistMarketFlowBody() {
  const el = $('inspect-dist-market-flow-body');
  if (!el) return;
  const st = _distMarketFlowState;
  const badge = $('badge-dist-market-flow');

  if (!st.isIssuer || !(st.issuerConnAnalysis?.distributions || []).length) {
    el.innerHTML = `<div class="inspect-empty-note">${!st.isIssuer ? 'This account does not issue a token — there is no distribution to trace.' : 'No direct token distribution from this account was found in the fetched history.'}</div>`;
    if (badge) { badge.className = 'section-badge section-badge--neutral'; badge.textContent = 'N/A'; }
    return;
  }

  if (st.loading) {
    el.innerHTML = `<div class="inspect-loading-state" style="display:flex"><div class="inspect-spinner"></div><span>Fetching each recipient wallet's transaction history — one extra lookup per wallet, this can take several seconds…</span></div>`;
    return;
  }

  if (st.error) {
    el.innerHTML = `<div class="alert-err">⚠️ ${escHtml(st.error)}</div>
      <button class="xrpl-btn btn-inspect" style="margin-top:10px" onclick="runDistMarketFlowAnalysis()">Retry</button>`;
    if (badge) { badge.className = 'section-badge section-badge--neutral'; badge.textContent = 'Error'; }
    return;
  }

  if (!st.result) {
    el.innerHTML = `
      <p class="widget-help" style="opacity:.6;font-size:.84rem">
        Traces this issuer's top ${Math.min(DIST_MARKET_COHORT_SIZE, st.issuerConnAnalysis.distributions.length)} direct recipients forward: did they
        begin selling in a similar time window, and did their proceeds converge on a shared destination?
        Fetches each recipient's own transaction history live — one extra round-trip per wallet, so this
        runs on demand rather than automatically with the rest of this report.
      </p>
      <button class="xrpl-btn btn-inspect" onclick="runDistMarketFlowAnalysis()">🔍 Analyze Distribution &amp; Market Flow</button>`;
    if (badge) { badge.className = 'section-badge section-badge--neutral'; badge.textContent = 'Not run'; }
    return;
  }

  const r = st.result;
  if (!r.applicable) {
    el.innerHTML = `<div class="inspect-empty-note">${escHtml(r.reason)}</div>`;
    if (badge) { badge.className = 'section-badge section-badge--neutral'; badge.textContent = 'N/A'; }
    return;
  }

  const currencyLabel = hexToAscii(st.issuedCurrency || '') || st.issuedCurrency || '?';
  el.innerHTML = `
    ${_renderPlainSummaryBox(buildDistMarketFlowPlainSummary(r))}
    <p class="widget-help" style="opacity:.55;font-size:.78rem">
      Scoped to this issuer's primary issued currency, <strong>${escHtml(currencyLabel)}</strong>. "Sell" means a
      sell-side order was PLACED (TakerGets = this currency) — not a confirmed fill. Each recipient's own history
      is one capped page (${DIST_MARKET_TX_PAGE} most-recent transactions), not their full record.
    </p>
    <div class="audit-items">${r.findings.map(f => auditRow(f)).join('')}</div>
    ${_renderMarketSetupTimeline(r.timeline)}
    <div class="conn-section-h">📇 Cohort — Top Direct Recipients</div>
    <div class="conn-holders">
      ${r.cohort.map((c, i) => `
        <div class="conn-holder-row">
          <span class="conn-holder-rank">${i + 1}</span>
          <button class="addr-link mono cut conn-holder-addr" onclick="openRelationshipDrawer('${escHtml(c.addr)}')" title="${escHtml(c.addr)}">${escHtml(shortAddr(c.addr))}</button>
          <span class="mono" style="font-size:.78rem;opacity:.7;flex-shrink:0">${fmt(c.amountReceived, 0)}${c.sharePct != null ? ` (${fmt(c.sharePct, 1)}%)` : ''}</span>
          <span class="mono" style="font-size:.74rem;flex-shrink:0;color:${c.fetchFailed ? 'var(--err, #ff5555)' : c.firstSellTs ? '#ffb86c' : 'rgba(255,255,255,.35)'}">${c.fetchFailed ? 'fetch failed' : c.firstSellTs ? `selling since ${new Date((c.firstSellTs + XRPL_EPOCH) * 1000).toLocaleDateString()}` : 'no sell orders seen'}</span>
        </div>
        ${c.hop2Recipients?.length ? `<div class="conn-holder-hop2" style="padding:2px 0 6px 34px;font-size:.72rem;opacity:.55">↳ hop 2: forwarded this token to ${c.hop2Recipients.length} wallet${c.hop2Recipients.length === 1 ? '' : 's'} (largest: ${fmt(c.hop2Recipients[0].amount, 0)} to ${shortAddr(c.hop2Recipients[0].dest)})</div>` : ''}`).join('')}
    </div>
    ${r.fetchFailures ? `<div class="alert-err" style="margin-top:10px">⚠️ ${r.fetchFailures} of ${r.cohort.length} recipient wallet lookups failed — results reflect only the remaining ${r.cohort.length - r.fetchFailures}.</div>` : ''}
    ${_renderIssuerEcosystemGraph(_buildIssuerEcosystemGraph(st.forAddr, r))}
    <button class="xrpl-btn" style="margin-top:12px" onclick="runDistMarketFlowAnalysis()">↻ Re-analyze</button>
  `;

  if (badge) {
    const worstSev = r.findings.reduce((w, f) => f.sev === 'warn' ? 'warn' : w, 'ok');
    badge.className = `section-badge section-badge--${worstSev === 'warn' ? 'warn' : 'ok'}`;
    badge.textContent = worstSev === 'warn' ? 'Review' : 'Checked';
  }
}

async function runDistMarketFlowAnalysis() {
  const st = _distMarketFlowState;
  if (st.forAddr !== _currentAddr) return; // stale — a new inspection has since started
  if (state.connectionState !== 'connected') { st.error = 'Not connected to an XRPL node.'; _renderDistMarketFlowBody(); return; }
  st.loading = true; st.error = null;
  _renderDistMarketFlowBody();
  try {
    const result = await analyseDistributionMarketFlow(st.issuerConnAnalysis, st.issuedCurrency, st.holderCohorts);
    if (_distMarketFlowState.forAddr !== _currentAddr) return; // inspection changed mid-fetch
    _distMarketFlowState.result = result;
  } catch (err) {
    if (_distMarketFlowState.forAddr !== _currentAddr) return;
    _distMarketFlowState.error = err?.message || 'Could not complete this analysis.';
  } finally {
    if (_distMarketFlowState.forAddr === _currentAddr) {
      _distMarketFlowState.loading = false;
      _renderDistMarketFlowBody();
    }
  }
}

/* ── Fee Analysis Panel ──────────────────────────── */
/** Fee Analysis's "In plain terms" summary (Inspector-wide roadmap item
 *  #10) — reuses avgFeeMultiplier/spikeCount already computed. */
function buildFeeAnalysisPlainSummary(a) {
  const hasWarn = (a.signals || []).some(s => s.sev === 'warn' || s.sev === 'critical');
  if (a.avgFeeMultiplier == null) return { tone: 'ok', text: `Not enough fee-paying transactions to assess fee behavior.` };
  let text = `This account pays fees at an average of ${a.avgFeeMultiplier}x the base rate`;
  text += a.spikeCount > 0 ? `, with ${a.spikeCount} transaction(s) paying over 100x base.` : ', within normal ranges.';
  text += hasWarn ? ' Bots sometimes overpay fees to guarantee same-ledger execution alongside a counterparty — see below for the specific pattern flagged.' : '';
  return { tone: hasWarn ? 'warn' : 'ok', text };
}

function renderFeeAnalysisPanel(a) {
  const body = document.getElementById('inspect-fee-analysis-body');
  if (!body || !a) return;
  const sigs = (a.signals || []).map(findingRow).join('');
  const stats = a.avgFeeMultiplier != null ? `
    <div class="wash-stat-row" style="margin-top:10px">
      <span>Average fee multiplier</span><span class="mono">${a.avgFeeMultiplier}x base (12 drops)</span>
    </div>
    <div class="wash-stat-row">
      <span>High-fee transactions (>100x)</span><span class="mono ${a.spikeCount > 5 ? 'risk-text-high' : ''}">${a.spikeCount}</span>
    </div>` : '';
  // Top fee table
  const topTable = a.topFeeHashes?.length ? `
    <div style="margin-top:12px;font-size:.72rem;color:rgba(255,255,255,.4);text-transform:uppercase;letter-spacing:.08em;margin-bottom:6px">TOP FEE TRANSACTIONS</div>
    ${a.topFeeHashes.map(h => `
      <div class="wash-stat-row">
        <a href="https://livenet.xrpl.org/transactions/${escHtml(h.hash)}" target="_blank" rel="noopener"
           class="mono" style="font-size:.75rem;color:var(--accent);text-decoration:none">${shortAddr(h.hash)}</a>
        <span class="mono" style="color:#ffb86c">${h.mult}x base fee</span>
      </div>`).join('')}` : '';
  const section = document.getElementById('section-fee-analysis');
  const hasWarn = (a.signals||[]).some(s => s.sev === 'warn' || s.sev === 'critical');
  // Used to hide the whole section for the (most common) "fees are normal"
  // case — but that reads as broken/skipped, not as "checked, found nothing
  // notable," and every sibling panel that runs the equivalent check (Drain
  // Risk, Token Issuer, AMM, ...) stays visible with an explicit clean-state
  // row instead. Always show; fall back to that row when there's no signal.
  if (section) section.style.display = '';
  const okRow = !hasWarn ? `
    <div class="finding finding--ok">
      <span class="finding-sev sev-ok">OK</span>
      <div class="finding-body">
        <div class="finding-label">No elevated fees detected</div>
        <div class="finding-detail">Transaction fees across this account's history are within normal ranges.</div>
      </div>
    </div>` : '';
  body.innerHTML = `
    ${_renderPlainSummaryBox(buildFeeAnalysisPlainSummary(a))}
    <div class="simple-only" style="font-size:.76rem;color:rgba(255,255,255,.4);padding:8px 2px;margin-bottom:6px">
      Switch to <strong>⚗ Advanced</strong> (top of page) to see the full fee breakdown and evidence.
    </div>
    <div class="advanced-only">${okRow}${sigs}${stats}${topTable}</div>`;
  const badge = document.getElementById('badge-fee-analysis');
  if (badge) {
    badge.textContent = hasWarn ? 'Elevated' : 'OK';
    badge.className = `section-badge section-badge--${hasWarn ? 'warn' : 'ok'}`;
  }
}

/* ── Destination Tag Panel ───────────────────────── */
/** Destination Tags' "In plain terms" summary (Inspector-wide roadmap item
 *  #10) — deliberately neutral-first framing ("how this account uses
 *  tags," not "risk found"): destination tags are ordinary
 *  service/accounting behavior for exchanges and payment processors, and
 *  should only read as concerning when a specific independent signal
 *  actually fired. Reuses tagProfiles/signals already computed — no new
 *  analysis. */
function buildDestTagPlainSummary(a) {
  const hasWarn = (a.signals || []).some(s => s.sev === 'warn' || s.sev === 'critical');
  const hasProfiles = a.tagProfiles?.length > 0;
  if (!hasProfiles) return { tone: 'ok', text: `No exchange payments with destination tags were found in this account's history.` };
  const totalTx = a.tagProfiles.reduce((s, p) => s + p.txCount, 0);
  const custodialCount = a.tagProfiles.filter(p => p.looksCustodial).length;
  let text = `This account uses destination tags across ${a.tagProfiles.length} destination${a.tagProfiles.length === 1 ? '' : 's'}, covering ${totalTx} tagged payment${totalTx === 1 ? '' : 's'}.`;
  if (custodialCount) text += ` ${custodialCount} of those look like service/custodial accounts routing to many sub-accounts — common for exchanges and payment processors, not inherently suspicious.`;
  if (hasWarn) text += ' See below for the specific pattern that was flagged for review.';
  return { tone: hasWarn ? 'warn' : 'ok', text };
}

function renderDestTagPanel(a) {
  const body = document.getElementById('inspect-desttag-body');
  if (!body || !a) return;
  const sigs = (a.signals || []).map(findingRow).join('');
  const profileTable = a.tagProfiles?.length ? `
    <div style="margin-top:12px;font-size:.72rem;color:rgba(255,255,255,.4);text-transform:uppercase;letter-spacing:.08em;margin-bottom:6px">DESTINATION TAG SUMMARY</div>
    ${a.tagProfiles.slice(0,8).map(p => `
      <div class="wash-stat-row">
        <button type="button" class="lp-addr-btn" onclick="openRelationshipDrawer('${escHtml(p.dest)}')" title="Examine this account's relationship with the inspected account">${escHtml(p.name)}</button>
        <span class="mono" style="opacity:.65">${p.txCount} tx · ${p.uniqueTags} unique tag${p.uniqueTags!==1?'s':''}</span>
      </div>`).join('')}` : '';
  const section = document.getElementById('section-desttag');
  const hasWarn = (a.signals||[]).some(s => s.sev === 'warn' || s.sev === 'critical');
  const hasProfiles = a.tagProfiles?.length > 0;
  if (section) section.style.display = '';
  const okRow = (!hasWarn && !hasProfiles) ? `
    <div class="finding finding--ok">
      <span class="finding-sev sev-ok">OK</span>
      <div class="finding-body">
        <div class="finding-label">No destination tag patterns to report</div>
        <div class="finding-detail">No exchange payments with destination tags were found in this account's history.</div>
      </div>
    </div>` : '';
  body.innerHTML = `
    ${_renderPlainSummaryBox(buildDestTagPlainSummary(a))}
    ${(sigs || profileTable) ? `
    <div class="simple-only" style="font-size:.76rem;color:rgba(255,255,255,.4);padding:8px 2px;margin-bottom:6px">
      Switch to <strong>⚗ Advanced</strong> (top of page) to see the full tag-by-tag breakdown.
    </div>
    <div class="advanced-only">${okRow}${sigs}${profileTable}</div>` : ''}`;
  const badge = document.getElementById('badge-desttag');
  if (badge) {
    badge.textContent = hasWarn ? 'Check' : 'OK';
    badge.className = `section-badge section-badge--${hasWarn ? 'warn' : 'ok'}`;
  }
}

/* ── Path Payment Depth Panel ────────────────────── */
/** Path Payment Depth's "In plain terms" summary (Inspector-wide roadmap
 *  item #10) — reuses the same worst-severity-across-signals logic every
 *  other upgraded section uses. No new analysis. */
function buildPathDepthPlainSummary(a) {
  const hasCrit = a.signals.some(s => s.sev === 'critical');
  const hasWarn = a.signals.some(s => s.sev === 'warn');
  const tone = hasCrit ? 'crit' : hasWarn ? 'warn' : 'ok';
  const parts = [];
  if (a.selfRoutedCount) parts.push(`${a.selfRoutedCount} payment(s) routed through the DEX back to itself`);
  if (a.roundTripCount) parts.push(`${a.roundTripCount} XRP→IOU→XRP round-trip(s)`);
  if (a.deepHopCount) parts.push(`${a.deepHopCount} deep hop chain(s) of 3+ hops`);
  const text = parts.length
    ? `This account's payment routing shows ${parts.join(', ')}. Multiple hops through the DEX are common and often benign — see below for whether this specific pattern looks like ordinary conversion or deliberate volume inflation.`
    : `This account's payment routing looks ordinary — no round-trip, self-routed, or unusually deep multi-hop patterns found.`;
  return { tone, text };
}

function renderPathDepthPanel(a) {
  const section = document.getElementById('section-pathdepth');
  const body    = document.getElementById('inspect-pathdepth-body');
  const badge   = document.getElementById('badge-pathdepth');
  if (section) section.style.display = '';
  if (!body) return;

  // No path payments at all — used to collapse the whole section, which
  // read as "this check didn't run" rather than "ran, found nothing" (the
  // same section-hiding inconsistency as the Fee/DestTag panels above).
  if (!a || a.noData || !a.signals?.length) {
    body.innerHTML = '<div class="inspect-empty-note">No path payments found.</div>';
    if (badge) { badge.textContent = 'None'; badge.className = 'section-badge section-badge--neutral'; }
    return;
  }

  const sigs = a.signals.map(findingRow).join('');

  // Stats row
  const stats = `
    <div class="wash-stat-row" style="margin-top:10px">
      <span>Total path payments</span><span class="mono">${a.roundTripCount + a.deepHopCount + (a.selfRoutedCount||0) + (a.signals.filter(s=>s.sev==='ok').length > 0 ? 1 : 0)}</span>
    </div>
    ${a.roundTripCount ? `<div class="wash-stat-row"><span>XRP→IOU→XRP round-trips</span><span class="mono ${a.roundTripCount >= 3 ? 'risk-text-high' : 'risk-text-med'}">${a.roundTripCount}</span></div>` : ''}
    ${a.deepHopCount   ? `<div class="wash-stat-row"><span>Deep hop chains (≥3 hops)</span><span class="mono">${a.deepHopCount}</span></div>` : ''}
    ${a.selfRoutedCount? `<div class="wash-stat-row"><span>Self-routed payments</span><span class="mono risk-text-high">${a.selfRoutedCount}</span></div>` : ''}`;

  body.innerHTML = `
    ${_renderPlainSummaryBox(buildPathDepthPlainSummary(a))}
    <div class="simple-only" style="font-size:.76rem;color:rgba(255,255,255,.4);padding:8px 2px;margin-bottom:6px">
      ${a.signals.length} underlying finding${a.signals.length === 1 ? '' : 's'} back the summary above — switch to <strong>⚗ Advanced</strong> (top of page) to see the full evidence.
    </div>
    <div class="advanced-only">${sigs}${stats}</div>`;

  if (badge) {
    const hasCrit = a.signals.some(s => s.sev === 'critical');
    const hasWarn = a.signals.some(s => s.sev === 'warn');
    badge.textContent = hasCrit ? 'Critical' : hasWarn ? 'Check' : 'OK';
    badge.className = `section-badge section-badge--${hasCrit ? 'crit' : hasWarn ? 'warn' : 'ok'}`;
  }
}


/* ── Inbound Flow Panel ──────────────────────────── */
/** Inbound Flow's "In plain terms" summary — mirrors buildFundFlowPlainSummary's
 *  own tone/text pattern for the outbound side, so Inbound Flow gets the
 *  same plain-language treatment instead of being the one flow-direction
 *  section that never got it. Reuses fields analyseInboundFlow already
 *  computes — no new analysis. */
function buildInboundFlowPlainSummary(flow) {
  if (!flow || !flow.topSources?.length) return null;
  const top = flow.topSources[0];
  const name = top.entity?.name || shortAddr(top.addr);
  const concentrationClause = flow.topSourceSharePct != null
    ? `${flow.topSourceSharePct.toFixed(0)}% of this account's tracked XRP funding (${fmt(top.totalXrp, 2)} XRP) came from a single source, ${name}.`
    : `This account's tracked XRP funding is spread across ${flow.uniqueSources} source(s).`;
  const recurClause = (flow.recurringCount || flow.oneTimeCount)
    ? ` ${flow.recurringCount} funding source(s) sent more than once; ${flow.oneTimeCount} sent exactly once.`
    : '';
  const structuredClause = flow.structuredFlag
    ? ' A cluster of similarly-sized inbound payments was also found — see the structured-funding note below.'
    : '';
  return { tone: flow.structuredFlag ? 'warn' : 'ok', text: `${concentrationClause}${recurClause}${structuredClause}` };
}

function renderInboundFlowPanel(flow) {
  const el = $('inspect-inbound-body');
  if (!el) return;
  const sigs = (flow.signals||[]).map(findingRow).join('');
  const plainSummary = buildInboundFlowPlainSummary(flow);

  // firstFundedTs/lastFundedTs come from getCloseTime(tx), which already
  // returns real Unix-epoch seconds (it adds XRPL_EPOCH internally) — no
  // second epoch adjustment here, unlike the raw ripple-epoch-seconds
  // fields other parts of this file format directly.
  const fmtDate = ts => ts != null ? new Date(ts * 1000).toLocaleDateString() : '—';
  const stats = `
    <div class="flow-summary" style="margin-top:10px">
      <div class="flow-stat"><span>Inbound payments</span><b>${flow.timeline?.length || 0}</b></div>
      <div class="flow-stat"><span>Unique sources</span><b>${flow.uniqueSources}</b></div>
      <div class="flow-stat"><span>Total XRP received</span><b class="mono">${fmt(flow.totalIn,2)}</b></div>
      <div class="flow-stat"><span>Exchange sources</span><b>${flow.exchangeSrcs?.length||0}</b></div>
      <div class="flow-stat"><span>Recurring / one-time funders</span><b>${flow.recurringCount||0} / ${flow.oneTimeCount||0}</b></div>
      <div class="flow-stat"><span>First / last funding</span><b class="mono" style="font-size:.72rem">${fmtDate(flow.firstFundedTs)} – ${fmtDate(flow.lastFundedTs)}</b></div>
    </div>`;

  const topList = flow.topSources?.length ? `
    <div class="flow-section-h" style="margin-top:14px">📥 Top Funding Sources</div>
    <div class="flow-dest-list">
      ${flow.topSources.map((s,i) => {
        const pct = flow.totalIn > 0 ? (s.totalXrp/flow.totalIn*100).toFixed(0) : 0;
        const ent = s.entity;
        const savedLabel = getAddrBookLabel(s.addr);
        const badge = ent ? `<span class="flow-entity-badge flow-entity--${ent.type}">${escHtml(ent.name)}</span>` : '';
        const savedBadge = savedLabel ? `<span class="flow-entity-badge" style="background:rgba(189,147,249,.12);color:#bd93f9;border-color:rgba(189,147,249,.3)" title="Saved to your address book">🏷 ${escHtml(savedLabel)}</span>` : '';
        return `<div class="flow-dest-row">
          <div class="flow-dest-rank">${i+1}</div>
          <div class="flow-dest-info">
            <div class="flow-dest-top">
              <a href="https://xrpscan.com/account/${escHtml(s.addr)}" target="_blank" rel="noopener" class="addr-link mono cut">${escHtml(shortAddr(s.addr))}</a>
              ${savedBadge}
              ${badge}
              <button type="button" class="mi-rel-examine" style="margin-left:auto" onclick="openRelationshipDrawer('${escHtml(s.addr)}')">Examine</button>
            </div>
            <div class="flow-bar-row">
              <div class="flow-dest-bar"><div class="flow-dest-fill" style="width:${Math.min(100,pct)}%;background:${ent?.type==='exchange'?'#00d4ff':'rgba(80,250,123,.7)'}"></div></div>
              <span class="mono flow-dest-pct">${pct}%</span>
            </div>
            <div class="flow-dest-meta">
              <span class="mono">${fmt(s.totalXrp,2)} XRP${_usd(s.totalXrp)}</span>
              <span class="flow-dest-cnt">${s.txCount} tx${s.txCount > 1 ? ' · recurring' : ' · one-time'}</span>
            </div>
          </div>
        </div>`;
      }).join('')}
    </div>` : '';

  el.innerHTML = _renderPlainSummaryBox(plainSummary) + sigs + stats + topList;
  const badge = $('badge-inbound');
  if (badge) {
    const hasWarn = (flow.signals||[]).some(s=>s.sev==='warn'||s.sev==='critical');
    badge.textContent = `${flow.uniqueSources} src${flow.uniqueSources!==1?'s':''}`;
    badge.className = `section-badge section-badge--${hasWarn?'warn':'neutral'}`;
  }
}

/* ── Memo Analysis Panel ─────────────────────────── */
function renderMemoPanel(a) {
  const section = $('section-memos');
  const body    = $('inspect-memos-body');
  if (section) section.style.display = '';
  if (!body) return;
  if (!a || !a.allMemos?.length) {
    body.innerHTML = '<div class="inspect-empty-note">No memos found.</div>';
    const b = $('badge-memos');
    if (b) { b.textContent = 'None'; b.className = 'section-badge section-badge--neutral'; }
    return;
  }
  const sigs = (a.signals||[]).map(findingRow).join('');
  const memoList = a.allMemos.slice(0,10).map(m => `
    <div class="wash-stat-row" style="flex-direction:column;align-items:flex-start;gap:2px;padding:6px 0;border-bottom:1px solid rgba(255,255,255,.05)">
      <div style="font-size:.72rem;color:rgba(255,255,255,.35)">${escHtml(m.type)} · <a href="https://livenet.xrpl.org/transactions/${escHtml(m.tx)}" target="_blank" rel="noopener" style="color:var(--accent);text-decoration:none">${shortAddr(m.tx)}</a></div>
      <div style="font-size:.82rem;word-break:break-all;color:rgba(255,255,255,.75)">${escHtml(m.text.slice(0,120))}${m.text.length>120?'…':''}</div>
    </div>`).join('');
  const hasCrit = (a.signals||[]).some(s=>s.sev==='critical');
  const hasWarn = (a.signals||[]).some(s=>s.sev==='warn');
  const plainSummary = {
    tone: hasCrit ? 'crit' : hasWarn ? 'warn' : 'ok',
    text: hasCrit
      ? `This account's memos contain text patterns consistent with scam/phishing attempts — see below for the specific messages.`
      : hasWarn
        ? `This account's memos show a repeated or coordinated pattern worth reviewing — see below.`
        : `${a.allMemos.length} memo(s) found in this account's history, with no scam or coordination pattern detected.`,
  };
  body.innerHTML = `
    ${_renderPlainSummaryBox(plainSummary)}
    <div class="simple-only" style="font-size:.76rem;color:rgba(255,255,255,.4);padding:8px 2px;margin-bottom:6px">
      Switch to <strong>⚗ Advanced</strong> (top of page) to read the memo contents.
    </div>
    <div class="advanced-only">
      ${sigs}
      <div style="margin-top:10px;font-size:.72rem;color:rgba(255,255,255,.4);text-transform:uppercase;letter-spacing:.08em;margin-bottom:4px">MEMO CONTENTS (${a.allMemos.length} found)</div>
      ${memoList}
    </div>`;
  const badge = $('badge-memos');
  if (badge) {
    badge.textContent = hasCrit?'Scam text':hasWarn?'Patterns':'OK';
    badge.className = `section-badge section-badge--${hasCrit?'crit':hasWarn?'warn':'ok'}`;
  }
}

/* ── Escrow Depth Panel ──────────────────────────── */
function renderEscrowDepthPanel(a) {
  const section = $('section-escrow-depth');
  const body    = $('inspect-escrow-depth-body');
  if (section) section.style.display = '';
  if (!body) return;
  if (!a || !a.escrows?.length) {
    body.innerHTML = '<div class="inspect-empty-note">No escrows found.</div>';
    const b = $('badge-escrow-depth');
    if (b) { b.textContent = 'None'; b.className = 'section-badge section-badge--neutral'; }
    return;
  }
  const sigs = (a.signals||[]).map(findingRow).join('');
  const EPOCH = 946684800;
  const rows = a.escrows.map(e => `
    <div class="wash-stat-row">
      <span>${e.isSelfEscrow?'Self-escrow':e.isThirdParty?'<span style="color:#ff5555">Third-party →</span>':shortAddr(e.dest||'')}</span>
      <span class="mono">${fmt(e.amtXrp,2)} XRP${_usd(e.amtXrp)}</span>
      <span style="font-size:.72rem;opacity:.55">${e.daysToFinish!=null?(e.daysToFinish<0?'matured':e.daysToFinish+'d'):e.conditional?'conditional':'—'}</span>
    </div>`).join('');
  const hasThirdPartyWarn = a.hasThirdParty;
  const plainSummary = {
    tone: hasThirdPartyWarn ? 'warn' : 'ok',
    text: hasThirdPartyWarn
      ? `This account has ${a.escrows.length} open escrow(s), including at least one created by a third party — a third-party escrow can lock funds with conditions the wallet owner didn't set.`
      : `This account has ${a.escrows.length} open escrow${a.escrows.length===1?'':'s'}, all self-created or from expected counterparties.`,
  };
  body.innerHTML = `
    ${_renderPlainSummaryBox(plainSummary)}
    <div class="simple-only" style="font-size:.76rem;color:rgba(255,255,255,.4);padding:8px 2px;margin-bottom:6px">
      Switch to <strong>⚗ Advanced</strong> (top of page) to see each escrow individually.
    </div>
    <div class="advanced-only">${sigs}<div style="margin-top:10px">${rows}</div></div>`;
  const badge = $('badge-escrow-depth');
  if (badge) {
    badge.textContent = `${a.escrows.length} escrow${a.escrows.length!==1?'s':''}`;
    badge.className = `section-badge section-badge--${hasThirdPartyWarn?'warn':'neutral'}`;
  }
}

/* ── Check Panel ─────────────────────────────────── */
function renderCheckPanel(a) {
  const section = $('section-checks');
  const body    = $('inspect-checks-body');
  if (section) section.style.display = '';
  if (!body) return;
  if (!a || !a.checks?.length) {
    body.innerHTML = '<div class="inspect-empty-note">No open Checks found.</div>';
    const b = $('badge-checks');
    if (b) { b.textContent = 'None'; b.className = 'section-badge section-badge--neutral'; }
    return;
  }
  const sigs = (a.signals||[]).map(findingRow).join('');
  const rows = a.checks.map(c => `
    <div class="wash-stat-row">
      <span class="mono">${shortAddr(c.sender)} → ${shortAddr(c.dest||'')}</span>
      <span class="mono">${c.amtXrp!=null?fmt(c.amtXrp,2)+' XRP'+_usd(c.amtXrp):(c.amtToken?.value||'?')+' '+c.amtToken?.currency}</span>
      <span style="font-size:.72rem;${c.expired?'color:#ff5555':'opacity:.55'}">${c.expired?'Expired':'Open'}</span>
    </div>`).join('');
  const expiredCount = a.checks.filter(c => c.expired).length;
  const plainSummary = {
    tone: 'ok',
    text: `This account has ${a.checks.length} open check${a.checks.length===1?'':'s'} — deferred payments the recipient can cash at any time.${expiredCount ? ` ${expiredCount} of them have expired, wasting a reserve slot.` : ''}`,
  };
  body.innerHTML = `
    ${_renderPlainSummaryBox(plainSummary)}
    <div class="simple-only" style="font-size:.76rem;color:rgba(255,255,255,.4);padding:8px 2px;margin-bottom:6px">
      Switch to <strong>⚗ Advanced</strong> (top of page) to see each check individually.
    </div>
    <div class="advanced-only">${sigs}<div style="margin-top:10px">${rows}</div></div>`;
  const badge = $('badge-checks');
  if (badge) {
    badge.textContent = `${a.checks.length} check${a.checks.length!==1?'s':''}`;
    badge.className = 'section-badge section-badge--neutral';
  }
}

/* ── Live Order Book Panel ───────────────────────── */
function renderLiveBookPanel(a) {
  const section = $('section-livebook');
  const body    = $('inspect-livebook-body');
  if (section) section.style.display = '';
  if (!body) return;
  if (!a?.hasData) {
    body.innerHTML = '<div class="inspect-empty-note">No live order book activity found for this wallet.</div>';
    const b = $('badge-livebook');
    if (b) { b.textContent = 'None'; b.className = 'section-badge section-badge--neutral'; }
    return;
  }
  const sigs = (a.signals||[]).map(findingRow).join('');
  const stats = `
    <div class="wash-stat-row" style="margin-top:10px">
      <span>Pair</span><span class="mono">${escHtml(a.pair.split('↔').map(p=>p.split('+')[0]).join(' ↔ '))}</span>
    </div>
    <div class="wash-stat-row">
      <span>Live orders in book</span><span class="mono">${a.offerCount}</span>
    </div>
    ${a.ourShare>0?`<div class="wash-stat-row"><span>This wallet's book share</span><span class="mono ${a.ourShare>0.25?'risk-text-high':''}">${(a.ourShare*100).toFixed(1)}%</span></div>`:''}
    ${a.wallShare>0.3?`<div class="wash-stat-row"><span>Largest single order share</span><span class="mono ${a.wallShare>0.4?'risk-text-high':'risk-text-med'}">${(a.wallShare*100).toFixed(1)}%</span></div>`:''}`;
  body.innerHTML = sigs + stats;
  const badge = $('badge-livebook');
  if (badge) {
    const hasCrit = (a.signals||[]).some(s=>s.sev==='critical');
    const hasWarn = (a.signals||[]).some(s=>s.sev==='warn');
    badge.textContent = hasCrit?'Wall order':hasWarn?'Check':'OK';
    badge.className = `section-badge section-badge--${hasCrit?'crit':hasWarn?'warn':'ok'}`;
  }
}

/* ── Risk Score Breakdown Bar ────────────────────── */
function renderRiskBreakdown(riskScore, ...analysisArgs) {
  const body = $('inspect-risk-breakdown');
  if (!body) return;
  const components = buildRiskBreakdown(riskScore, ...analysisArgs);
  if (!components.length) { body.innerHTML = ''; return; }
  const total = Math.max(1, components.reduce((s,c)=>s+c.pts,0));
  body.innerHTML = `
    <div class="risk-breakdown-card">
      <div class="risk-breakdown-title">Score Breakdown</div>
      <div class="risk-breakdown-bar">
        ${components.map(c=>`<div class="risk-breakdown-seg" style="flex:${c.pts};background:${c.color}" title="${escHtml(c.label)}: ${c.pts} pts"></div>`).join('')}
      </div>
      <div class="risk-breakdown-legend">
        ${components.map(c=>`<span class="risk-breakdown-chip" style="--chip-color:${c.color}">${c.icon} ${escHtml(c.label)} ${c.pts}pts</span>`).join('')}
      </div>
    </div>`;
}

/* ═══════════════════════════════════════════════════
   HELPERS
═══════════════════════════════════════════════════ */

/* Renders the legacy {sev,label,detail} shape unchanged, but when a
   finding carries the evidence-model fields (confidence, observed,
   alternativeExplanations, evidenceAgainstBenign, classification —
   see mkFinding) it shows those too: what was actually observed, what
   could legitimately explain it, what argues against that benign
   explanation, and an explicit statement that ledger behavior alone
   can't prove intent. This is the "Observed / Alternative explanations /
   Evidence against benign / Classification" format, applied wherever a
   module has been upgraded to produce it. */
/** Shared epistemic-tier rendering for auditRow/findingRow: ● OBSERVED (a
 *  fact directly read off the ledger), ◆ CALCULATED (a deterministic metric
 *  derived from it), ▲ INFERRED (a behavioral judgment relative to
 *  history/context), ◇ HYPOTHESIS (an explicitly unproven possible
 *  explanation — rendered visually softer/dashed since it's the weakest
 *  epistemic tier). Optional and additive — a finding with none of these
 *  set (every finding built before this split existed) renders exactly as
 *  it did before. */
function _epistemicBlocks(observed, calculated, inferred, hypothesis) {
  const tier = (modifier, icon, title, items) => (items && items.length)
    ? `<div class="audit-evidence-group audit-epistemic-group audit-epistemic--${modifier}">
         <div class="audit-evidence-title"><span class="audit-epistemic-icon">${icon}</span> ${escHtml(title)}</div>
         <ul class="audit-evidence-list">${items.map(i => `<li>${escHtml(i)}</li>`).join('')}</ul>
       </div>` : '';
  return [
    tier('observed', '●', 'Observed', observed),
    tier('calculated', '◆', 'Calculated', calculated),
    tier('inferred', '▲', 'Inferred', inferred),
    hypothesis ? `<div class="audit-evidence-group audit-epistemic-group audit-epistemic--hypothesis">
         <div class="audit-evidence-title"><span class="audit-epistemic-icon">◇</span> Hypothesis</div>
         <div class="audit-hypothesis-text">${escHtml(hypothesis)}</div>
       </div>` : '',
  ].join('');
}

// Shared by auditRow/findingRow: applicability{} and owner/external impact
// render the same way regardless of which of the two card layouts wraps
// them, matching how _epistemicBlocks() is already shared between them.
function _applicabilityAndImpactBlocks(applicability, ownerImpact, externalImpact) {
  const naBlock = applicability && applicability.applicable === false
    ? `<div class="audit-applicability audit-applicability--na">
         <span class="audit-applicability-tag">N/A</span> ${escHtml(applicability.reason || 'This analysis does not apply to this account.')}
       </div>` : '';
  const impactRows = [
    ownerImpact ? `<div class="audit-impact-row"><span class="audit-impact-label">Owner impact</span><span>${escHtml(ownerImpact)}</span></div>` : '',
    externalImpact ? `<div class="audit-impact-row"><span class="audit-impact-label">External / ecosystem impact</span><span>${escHtml(externalImpact)}</span></div>` : '',
  ].join('');
  return naBlock + (impactRows ? `<div class="audit-impact-block">${impactRows}</div>` : '');
}

// Shared by auditRow/findingRow — renders each cited transaction hash as a
// clickable chip opening the real Transaction Detail Drawer, so a finding is
// never a dead-end UI card with no path back to the ledger evidence behind
// it. Hidden entirely when a finding cites none (most don't yet).
function _evidenceHashChips(hashes) {
  if (!hashes || !hashes.length) return '';
  return `<div class="audit-evidence-group">
    <div class="audit-evidence-title">View transaction evidence</div>
    <div class="audit-hash-chips">
      ${hashes.map(h => `<button type="button" class="audit-hash-chip mono" onclick="openTxEvidence('${escHtml(h)}')" title="${escHtml(h)}">🔗 ${escHtml(shortAddr(h))}</button>`).join('')}
    </div>
  </div>`;
}

function auditRow({ sev, label, detail, confidence, observed, calculated, inferred, hypothesis, alternativeExplanations, evidenceAgainstBenign, classification, applicability, ownerImpact, externalImpact, actionCta, hashes }) {
  const icons = { ok: '✓', info: 'ℹ', warn: '⚠', critical: '⛔' };
  const bulletList = (title, items) => (items && items.length)
    ? `<div class="audit-evidence-group">
         <div class="audit-evidence-title">${escHtml(title)}</div>
         <ul class="audit-evidence-list">${items.map(i => `<li>${escHtml(i)}</li>`).join('')}</ul>
       </div>` : '';

  return `
    <div class="audit-row audit-row--${sev}">
      <span class="audit-icon">${icons[sev] || 'ℹ'}</span>
      <div class="audit-text">
        <div class="audit-label">${escHtml(label)}${confidence != null ? ` <span class="audit-confidence analyst-only-inline">confidence ${Math.round(confidence * 100)}%</span>` : ''}</div>
        ${detail ? `<div class="audit-detail">${escHtml(detail)}</div>` : ''}
        ${(calculated?.length || inferred?.length || hypothesis) ? _epistemicBlocks(observed, calculated, inferred, hypothesis) : bulletList('Observed', observed)}
        ${bulletList('Alternative explanations', alternativeExplanations)}
        ${bulletList('Evidence against benign explanation', evidenceAgainstBenign)}
        ${_applicabilityAndImpactBlocks(applicability, ownerImpact, externalImpact)}
        ${classification ? `<div class="audit-classification">${escHtml(classification)}</div>` : ''}
        <div class="analyst-only-block">${_evidenceHashChips(hashes)}</div>
        ${actionCta ? `<button class="audit-action-cta" onclick="${escHtml(actionCta.onclick)}">${escHtml(actionCta.label)}</button>` : ''}
      </div>
    </div>`;
}

/* The other half of the app's finding-rendering split: ~12 panels use a
   denser `.finding`/`.finding-sev`/`.finding-body` layout (a full-width
   severity chip) instead of auditRow's `.audit-row` (compact icon-led
   layout) — a real, deliberate visual difference between the two, not
   duplication to collapse. What WAS pure duplication is that every one of
   those 12 render functions re-typed its own near-identical template with
   no evidence-model fields, even after the modules feeding some of them
   started producing observed/alternativeExplanations/classification data.
   This is the evidence-aware version of that shared template, reusing the
   same .audit-evidence-* bullet/classification atoms auditRow already
   established rather than inventing a second set. */
function findingRow(s) {
  const clsBySev = { critical: 'sev-critical', warn: 'sev-warn', info: 'sev-info', ok: 'sev-ok' };
  const bulletList = (title, items) => (items && items.length)
    ? `<div class="audit-evidence-group">
         <div class="audit-evidence-title">${escHtml(title)}</div>
         <ul class="audit-evidence-list">${items.map(i => `<li>${escHtml(i)}</li>`).join('')}</ul>
       </div>` : '';

  return `
    <div class="finding finding--${s.sev}">
      <span class="finding-sev ${clsBySev[s.sev] || ''}">${(s.sev || '').toUpperCase()}</span>
      <div class="finding-body">
        <div class="finding-label">${escHtml(s.label)}${s.confidence != null ? ` <span class="audit-confidence">confidence ${Math.round(s.confidence * 100)}%</span>` : ''}</div>
        ${s.detail ? `<div class="finding-detail">${escHtml(s.detail)}</div>` : ''}
        ${(s.calculated?.length || s.inferred?.length || s.hypothesis) ? _epistemicBlocks(s.observed, s.calculated, s.inferred, s.hypothesis) : bulletList('Observed', s.observed)}
        ${bulletList('Alternative explanations', s.alternativeExplanations)}
        ${bulletList('Evidence against benign explanation', s.evidenceAgainstBenign)}
        ${_applicabilityAndImpactBlocks(s.applicability, s.ownerImpact, s.externalImpact)}
        ${s.classification ? `<div class="audit-classification">${escHtml(s.classification)}</div>` : ''}
        ${_evidenceHashChips(s.hashes)}
      </div>
    </div>`;
}

function riskScoreClass(score) {
  return score < 20 ? 'risk-ok' : score < 45 ? 'risk-medium' : score < 70 ? 'risk-high' : 'risk-critical';
}

function txRiskLevel(tx, meta, addr) {
  if (DRAIN_TX_TYPES.has(tx.TransactionType)) return 'warn';
  if (tx.TransactionType === 'NFTokenCreateOffer') {
    const amt = tx.Amount;
    if (!amt || (typeof amt === 'string' && Number(amt) < 1000000)) return 'critical';
  }
  if (meta?.TransactionResult && meta.TransactionResult !== 'tesSUCCESS') return 'fail';
  return 'normal';
}

function txBrief(tx, addr) {
  const type = tx.TransactionType;
  if (type === 'Payment') {
    const dir = tx.Account === addr ? `→ ${shortAddr(tx.Destination)}` : `← ${shortAddr(tx.Account)}`;
    const amt = typeof tx.Amount === 'string'
      ? `${fmt(Number(tx.Amount) / 1e6, 2)} XRP`
      : (tx.Amount?.value ? `${fmt(Number(tx.Amount.value), 2)} ${tx.Amount.currency}` : '');
    return escHtml(`${amt} ${dir}`);
  }
  if (type === 'OfferCreate') {
    const pays = typeof tx.TakerPays === 'string'
      ? `${fmt(Number(tx.TakerPays) / 1e6, 2)} XRP`
      : `${fmt(Number(tx.TakerPays?.value), 2)} ${tx.TakerPays?.currency}`;
    const gets = typeof tx.TakerGets === 'string'
      ? `${fmt(Number(tx.TakerGets) / 1e6, 2)} XRP`
      : `${fmt(Number(tx.TakerGets?.value), 2)} ${tx.TakerGets?.currency}`;
    return escHtml(`${pays} for ${gets}`);
  }
  if (type === 'SetRegularKey')   return escHtml(`Key: ${tx.RegularKey ? shortAddr(tx.RegularKey) : 'REMOVED'}`);
  if (type === 'NFTokenMint')     return escHtml(`Taxon: ${tx.NFTokenTaxon ?? '—'}`);
  if (type === 'NFTokenBurn')     return escHtml(`Token: ${tx.NFTokenID ? shortAddr(tx.NFTokenID) : '—'}`);
  if (type === 'AMMDeposit')      return escHtml(`Pool deposit`);
  if (type === 'AMMWithdraw')     return escHtml(`LP withdrawal`);
  if (type === 'EscrowCreate')    return escHtml(`${fmt(Number(tx.Amount || 0) / 1e6, 2)} XRP → ${shortAddr(tx.Destination)}`);
  return '';
}

function typeBadgeClass(type) {
  const map = {
    Payment: 'payment', OfferCreate: 'offer', OfferCancel: 'offer',
    NFTokenMint: 'nft', NFTokenBurn: 'nft', NFTokenCreateOffer: 'nft', NFTokenAcceptOffer: 'nft',
    SetRegularKey: 'auth', SignerListSet: 'auth', AccountSet: 'auth', AccountDelete: 'auth',
    TrustSet: 'trust',
    AMMCreate: 'amm', AMMDeposit: 'amm', AMMWithdraw: 'amm', AMMVote: 'amm', AMMBid: 'amm',
    EscrowCreate: 'escrow', EscrowFinish: 'escrow', EscrowCancel: 'escrow',
    PaymentChannelCreate: 'channel', PaymentChannelFund: 'channel', PaymentChannelClaim: 'channel',
  };
  return map[type] || 'other';
}

function getCloseTime(tx) {
  const t = tx?.date || tx?.close_time || tx?.ledger_close_time;
  if (!t) return 0;
  return Number(t) + XRPL_EPOCH;
}

function hexToAscii(hex) {
  if (!hex || hex.length !== 40) return hex || '';
  // Try to decode as ASCII currency code
  try {
    let str = '';
    for (let i = 0; i < hex.length; i += 2) {
      const code = parseInt(hex.slice(i, i + 2), 16);
      if (code === 0) continue;
      if (code < 32 || code > 126) return hex; // not printable ASCII
      str += String.fromCharCode(code);
    }
    return str || hex;
  } catch {
    return hex;
  }
}


/* ═══════════════════════════════════════════════════
   FULL INVESTIGATION REPORT
═══════════════════════════════════════════════════ */

function generateFullReport(addr, acct, balXrp, riskScore,
  securityAudit, drainAnalysis, nftAnalysis, washAnalysis,
  benfordsAnalysis, volConcAnalysis, issuerAnalysis,
  ammAnalysis, fundFlowAnalysis, issuerConnAnalysis, txList,
  entropyAnalysis, zipfAnalysis, timeSeriesAnalysis, grangerAnalysis,
  extra = {}) {

  const {
    feeAnalysis = null, destTagAnalysis = null, pathDepthAnalysis = null, gatewayBalances = null,
    inboundFlowAnalysis = null, memoAnalysis = null, escrowDepthAnalysis = null,
    checkAnalysis = null, liveBookAnalysis = null, walletAgeDays = null, walletCreatedTs = null,
    walletAgeVerified = false, walletActivationEvidence = null, historyCoverage = null,
  } = extra;
  const RIPPLE_EPOCH = 946684800;

  const ts        = new Date().toLocaleString();
  const addrShort = addr.slice(0, 10) + '…' + addr.slice(-8);
  const riskWord  = riskScore < 20 ? 'LOW' : riskScore < 45 ? 'MODERATE' : riskScore < 70 ? 'HIGH' : 'CRITICAL';
  const riskColor = riskScore < 20 ? '#50fa7b' : riskScore < 45 ? '#ffb86c' : riskScore < 70 ? '#ff8c42' : '#ff5555';

  // ── Data coverage ────────────────────────────────────────────────────────
  const datedTxs = txList.filter(({tx}) => tx.date != null);
  let coverageStr = txList.length.toLocaleString() + ' transactions';
  let coverageDateStr = '';
  let coverageSpanDays = 0;
  if (datedTxs.length >= 2) {
    const oldest = datedTxs[0].tx.date + RIPPLE_EPOCH;
    const newest = datedTxs[datedTxs.length - 1].tx.date + RIPPLE_EPOCH;
    coverageSpanDays = Math.round((newest - oldest) / 86400);
    const oldD = new Date(oldest * 1000).toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' });
    const newD = new Date(newest * 1000).toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' });
    coverageDateStr = `${oldD} – ${newD} (${coverageSpanDays} days)`;
    coverageStr = `${txList.length.toLocaleString()} transactions from ${coverageDateStr}`;
  }

  // ── Collect all findings ─────────────────────────────────────────────────
  const allFindings = [];
  // `extra` lets newer/rebuilt modules pass an mkFinding()-shaped object
  // (which already carries these exact field names) as a 6th arg to thread
  // category/confidence/evidence-model fields through without touching any
  // of the existing positional call sites below.
  const push = (module, sev, headline, detail, hashes, extra = {}) =>
    allFindings.push({
      // Prefer the finding's own mkFinding-assigned module (more specific,
      // e.g. 'Asset Drain Behavior' vs the call site's umbrella 'Drain
      // Risk') — old-shape findings without their own .module fall back to
      // the call site's label exactly as before.
      module: extra.module || module,
      sev, headline, detail: detail || '', hashes: hashes || [],
      category: extra.category ?? null,
      confidence: extra.confidence ?? null,
      observed: extra.observed ?? [],
      calculated: extra.calculated ?? [],
      inferred: extra.inferred ?? [],
      hypothesis: extra.hypothesis ?? null,
      alternativeExplanations: extra.alternativeExplanations ?? [],
      evidenceAgainstBenign: extra.evidenceAgainstBenign ?? [],
      classification: extra.classification ?? null,
      applicability: extra.applicability ?? null,
      ownerImpact: extra.ownerImpact ?? null,
      externalImpact: extra.externalImpact ?? null,
    });

  for (const f of securityAudit.findings || []) push('Security', f.sev, f.label, f.detail, f.hashes, f);
  // 'high' is a real, distinct level from 'critical' in this scale (see
  // _DRAIN_SEVERITY_ORDER) — a large/fast depletion with no confirmed
  // compromise signal (no auth-change precursor, no attacker-style key
  // setup) is exactly as consistent with the account's own owner moving
  // their own funds as with an actual drain, and shouldn't render with the
  // same alarm level as a confirmed compromise indicator. Only 'critical'
  // (an actual auth-change/attacker-key-setup signal from either
  // sub-analysis) maps to the critical badge; 'high' maps to warn.
  push('Drain Risk',
    drainAnalysis.riskLevel === 'low' ? 'ok' : drainAnalysis.riskLevel === 'critical' ? 'critical' : 'warn',
    'Drain Risk Level: ' + drainAnalysis.riskLevel.toUpperCase(), null);
  for (const s of drainAnalysis.signals  || []) if (s.sev !== 'ok') push('Drain Risk',          s.sev, s.label, s.detail, s.hashes, s);
  for (const f of nftAnalysis.flags      || []) if (f.sev !== 'ok') push('NFT',                  f.sev, f.label, f.detail, f.hashes, f);
  // No separate legacy "Wash score X/100" summary finding here — the loop
  // below already pushes every real Wash Execution/Spoofing/Automation
  // finding (the same independent verdicts the Inspector panel itself now
  // leads with), so a second line re-deriving severity from the deprecated
  // combined score would just be duplicate, inconsistent-vocabulary noise.
  for (const s of washAnalysis.signals   || []) if (s.sev !== 'ok') push('Wash Trading',         s.sev, s.label, s.detail, s.hashes, s);
  for (const s of benfordsAnalysis.signals||[]) if (s.sev !== 'ok') push("Benford's Law",         s.sev, s.label, s.detail, s.hashes, s);
  for (const s of volConcAnalysis.signals|| []) if (s.sev !== 'ok') push('Volume Concentration',  s.sev, s.label, s.detail, s.hashes, s);
  for (const s of entropyAnalysis?.signals  || []) if (s.sev !== 'ok') push("Shannon's Entropy",  s.sev, s.label, s.detail, s.hashes, s);
  for (const s of zipfAnalysis?.signals     || []) if (s.sev !== 'ok') push("Zipf's Law",         s.sev, s.label, s.detail, s.hashes, s);
  for (const s of timeSeriesAnalysis?.signals||[]) if (s.sev !== 'ok') push('Time Series',        s.sev, s.label, s.detail, s.hashes, s);
  for (const s of grangerAnalysis?.signals  || []) if (s.sev !== 'ok') push('Offer/Flow Coupling', s.sev, s.label, s.detail, s.hashes, s);
  for (const s of issuerAnalysis.signals || []) if (s.sev !== 'ok') push('Token Issuer',          s.sev, s.label, s.detail, s.hashes, s);
  for (const s of ammAnalysis.signals    || []) if (s.sev !== 'ok') push('AMM',                   s.sev, s.label, s.detail, s.hashes, s);
  for (const s of fundFlowAnalysis.signals || []) push('Fund Flow', s.sev, s.headline, s.detail, s.hashes, s);
  for (const s of issuerConnAnalysis.signals||[]) if (s.sev !== 'ok') push('Issuer Connections',  s.sev, s.label, s.detail, s.hashes, s);
  for (const s of feeAnalysis?.signals      ||[]) if (s.sev !== 'ok') push('Fee Spikes',          s.sev, s.label, s.detail, s.hashes, s);
  for (const s of destTagAnalysis?.signals  ||[]) if (s.sev !== 'ok') push('Destination Tags',    s.sev, s.label, s.detail, s.hashes, s);
  for (const s of pathDepthAnalysis?.signals||[])   if (s.sev !== 'ok') push('Path Payments',    s.sev, s.label, s.detail, s.hashes, s);
  for (const s of inboundFlowAnalysis?.signals||[]) if (s.sev !== 'ok') push('Inbound Flow',     s.sev, s.label, s.detail, s.hashes, s);
  for (const s of memoAnalysis?.signals||[])         if (s.sev !== 'ok') push('Memo Analysis',   s.sev, s.label, s.detail, s.hashes, s);
  for (const s of escrowDepthAnalysis?.signals||[])  if (s.sev !== 'ok') push('Escrow Depth',    s.sev, s.label, s.detail, s.hashes, s);
  for (const s of liveBookAnalysis?.signals||[])     if (s.sev !== 'ok') push('Live Order Book', s.sev, s.label, s.detail, s.hashes, s);

  const criticals = allFindings.filter(f => f.sev === 'critical');
  const warnings  = allFindings.filter(f => f.sev === 'warn');
  // Cache for change detection (accessed by post-render hooks in runInspect)
  window._lastAllFindings = allFindings;
  // Per-category risk breakdown — cached here since allFindings only
  // exists from this point on in the render pipeline.
  window._lastCategoryRisk = computeCategoryRiskScores(allFindings);

  // ── Helper: severity badge ────────────────────────────────────────────────
  const sevBadge = sev => {
    const map = {
      critical: 'background:rgba(255,85,85,.15);border:1px solid rgba(255,85,85,.35);color:#ff5555',
      warn:     'background:rgba(255,184,108,.10);border:1px solid rgba(255,184,108,.30);color:#ffb86c',
      info:     'background:rgba(120,180,255,.08);border:1px solid rgba(120,180,255,.18);color:rgba(120,180,255,.9)',
      ok:       'background:rgba(80,250,123,.08);border:1px solid rgba(80,250,123,.22);color:#50fa7b',
    };
    return `<span style="padding:2px 8px;border-radius:999px;font-size:.68rem;font-weight:900;letter-spacing:.3px;text-transform:uppercase;${map[sev]||map.info}">${sev.toUpperCase()}</span>`;
  };

  // ── Plain-English narrative ──────────────────────────────────────────────
  function buildNarrative() {
    const parts = [];

    // Opening — always includes actual data coverage
    parts.push(
      `<strong>Address ${addrShort}</strong> was inspected on ${ts}. ` +
      `The account holds <strong>${fmt(balXrp, 4)} XRP</strong>. ` +
      `This report analyzed <strong>${coverageStr}</strong>, ` +
      `plus all open on-chain objects (escrows, payment channels, trustlines, NFTs, AMM positions). ` +
      `The overall risk score is <strong style="color:${riskColor}">${riskScore}/100 — ${riskWord}</strong>. ` +
      `<em style="opacity:.7">Risk scores reflect statistical patterns — not legal proof. ` +
      `A high score means unusual patterns were detected. Always verify before drawing conclusions.</em>`
    );

    if (criticals.length) {
      parts.push(`⚠️ The scan found <strong>${criticals.length} critical issue${criticals.length > 1 ? 's' : ''}</strong> and <strong>${warnings.length} warning${warnings.length !== 1 ? 's' : ''}</strong> — explained in plain English below.`);
    }

    // ── Synthesis — how the findings connect ────────────────────────────────
    // Everything below this point is one paragraph per analysis module,
    // written independently of every other module. Read top to bottom that
    // reads as a checklist being filled in, not an analyst's read of THIS
    // account — and it's the main way this report ends up feeling
    // templated. This stitches the specific combinations that actually mean
    // something together into one lead sentence before the checklist starts,
    // the same way a person summarizing the case out loud would.
    {
      const hasDrainSignal  = drainAnalysis.riskLevel === 'critical' || drainAnalysis.riskLevel === 'high';
      const hasNewWallet    = fundFlowAnalysis.newWalletDests?.length > 0;
      const hasBlackHole    = fundFlowAnalysis.blackHoleDests?.length > 0;
      const washSeverity    = _washSectionSeverity(washAnalysis);
      const hasWashSignal   = washSeverity.tone !== 'ok';
      const hasFeeSpike     = feeAnalysis?.verdict === 'elevated';
      const hasStatForensic = [
        benfordsAnalysis.verdict === 'high-deviation',
        entropyAnalysis?.verdict === 'anomalous',
        zipfAnalysis?.verdict === 'anomalous' || zipfAnalysis?.verdict === 'elevated',
        timeSeriesAnalysis?.verdict === 'elevated',
        grangerAnalysis?.verdict === 'strong-coupling',
      ].filter(Boolean).length >= 2;

      let storyline = null;
      if (hasDrainSignal && hasNewWallet) {
        storyline = `The key change and the transfers to freshly-created wallets aren't separate concerns — together they're the specific sequence a drain follows: take control of signing, then move funds somewhere that isn't the attacker's known address.`;
      } else if (hasDrainSignal && hasBlackHole) {
        storyline = `A compromised-looking key change followed by funds reaching an address nobody controls is consistent with a drain where the funds are gone rather than just moved.`;
      } else if (hasWashSignal && hasFeeSpike) {
        storyline = `The order-cancellation pattern and the fee spikes reinforce each other: overpaying fees to guarantee same-ledger execution is how the cancel-before-fill pattern gets coordinated with a counterparty.`;
      } else if (hasWashSignal && hasStatForensic) {
        storyline = `This isn't just one statistical test disagreeing with the others — the wash-trading signal from actual order behavior and the independent mathematical tests are pointing at the same conclusion from two different directions.`;
      } else if (criticals.length + warnings.length >= 3) {
        const modules = [...new Set(criticals.concat(warnings).map(f => f.module))];
        storyline = `${modules.length} different analysis categories flagged this account (${modules.slice(0, 4).join(', ')}${modules.length > 4 ? ', …' : ''}) — any one alone could be circumstantial, but that many independent methods agreeing is the stronger signal here.`;
      }
      if (storyline) parts.push(`<strong>🧩 How these findings fit together:</strong> ${storyline}`);
    }

    // ── Drain / Security ──────────────────────────────────────────────────
    if (drainAnalysis.riskLevel === 'critical') {
      parts.push(
        `<span style="color:#ff5555"><strong>🚨 WALLET DRAIN RISK — CRITICAL</strong></span><br>` +
        `<strong>What was found:</strong> The account's security structure matches a known attack pattern — ` +
        `the master signing key has been disabled and replaced with a different key.<br>` +
        `<strong>What it means in plain English:</strong> If you did not personally do this, your wallet may have been taken over. ` +
        `An attacker who controls the replacement key can drain every XRP and token from the account.<br>` +
        `<strong>What to do right now:</strong> Stop sending any funds to this address. If it's your wallet, contact a security professional immediately.`
      );
    } else if (drainAnalysis.riskLevel === 'high') {
      parts.push(`<strong>⚠️ Elevated Drain Risk:</strong> Unusual security patterns found — possibly a key change followed by large outflows. See the Drain Risk section for exact transactions.`);
    }

    // ── New wallet alert ──────────────────────────────────────────────────
    if (fundFlowAnalysis.newWalletDests?.length) {
      parts.push(
        `<strong>🆕 Brand-New Receiving Wallets:</strong> ` +
        `${fundFlowAnalysis.newWalletDests.length} of the top destinations are freshly-created wallets (fewer than 10 lifetime transactions) that received significant XRP. ` +
        `Creating a new disposable wallet to receive drained funds — then disappearing — is the most common drain attack pattern on XRPL.`
      );
    }

    // ── Fund flow ─────────────────────────────────────────────────────────
    if (fundFlowAnalysis.blackHoleDests?.length) {
      parts.push(`<span style="color:#ff5555"><strong>🕳 Funds Sent to Uncontrolled Address:</strong></span> Some XRP reached a "black hole" — an address nobody controls. <strong>These funds cannot be recovered by anyone.</strong>`);
    }
    if (fundFlowAnalysis.exchangeDests?.length) {
      const exchNames = [...new Set(fundFlowAnalysis.exchangeDests.map(d => d.entity.name))].join(', ');
      parts.push(
        `<strong>💱 Exchange Activity:</strong> Funds reached known exchange(s): <strong>${exchNames}</strong>. ` +
        `Total outflow tracked: ${fmt(fundFlowAnalysis.totalOut, 2)} XRP to ${fundFlowAnalysis.uniqueDests} destination(s). ` +
        `This is often normal — people cash out to exchanges. It becomes a concern when combined with the security or timing signals above.`
      );
    } else if (fundFlowAnalysis.totalOut > 0) {
      parts.push(`<strong>Outbound payments:</strong> ${fmt(fundFlowAnalysis.totalOut, 2)} XRP sent to ${fundFlowAnalysis.uniqueDests} destination(s). None matched known exchange addresses.`);
    }

    // ── Wash trading (Market Integrity) — same independent-verdict tone
    // the Inspector panel itself leads with, never the deprecated combined
    // score, so the report and the live UI never disagree. ─────────────
    {
    const { tone: washTone, label: washLabel, spoofingApplicable } = _washSectionSeverity(washAnalysis);
    if (washTone === 'crit' || washTone === 'warn') {
      const s = washAnalysis.stats;
      const cancelRate = s.creates > 0 ? ((s.cancels / s.creates) * 100).toFixed(0) : 0;
      parts.push(
        `<strong>📊 Market Integrity — ${escHtml(washLabel)}:</strong><br>` +
        `<strong>What was found:</strong> Out of ${s.creates} DEX offers placed, ${s.cancels} (${cancelRate}%) were cancelled before filling. ` +
        `Only ${s.fills} actually filled.` +
        (s.selfTrades > 0 ? ` ${s.selfTrades} payment(s) were sent from and back to the same address.` : '') + `<br>` +
        `<strong>What it means:</strong> Placing orders and cancelling them before they fill inflates a token's visible trading activity without any real buying or selling. ` +
        `It makes a thin market look active to attract other traders.<br>` +
        `<strong>Caveat:</strong> Legitimate market makers do cancel many orders as prices move. ` +
        `This finding is strongest when combined with the self-trade and fee-spike signals.`
      );
    } else if (!spoofingApplicable && (washAnalysis.stats?.creates || 0) === 0) {
      parts.push(`<strong>Market Integrity:</strong> This account placed no exchange orders, so wash-execution and spoofing patterns could not be assessed from order behavior. See the Wash Trading section for what was checked from payment history alone.`);
    } else {
      parts.push(`<strong>✅ DEX activity looks normal</strong> — cancel ratios, fill rates, and trade sizes are within organic ranges.`);
    }
    }

    // ── Path payments ─────────────────────────────────────────────────────
    if (pathDepthAnalysis?.selfRoutedCount > 0) {
      parts.push(pathDepthAnalysis.selfRoutedLooksLikeSwaps
        ? `<strong>🔄 Self-Routed Currency Conversions:</strong> ${pathDepthAnalysis.selfRoutedCount} payment(s) where the sender and destination are the same address, spread across several different currency pairs with no single pair dominating — consistent with using an in-wallet swap/conversion feature (XRPL has no dedicated swap transaction type; this is how one is natively implemented), not deliberate manipulation of any one pair's apparent activity.`
        : `<strong>🔄 Self-Routing Path Payments:</strong> ${pathDepthAnalysis.selfRoutedCount} payment(s) where the sender and destination are the same address, concentrated on the same currency pair(s). ` +
          `Routing through the DEX back to yourself creates trading volume on that pair with no net economic transfer — this pattern is more consistent with deliberately inflating that pair's apparent activity than with ordinary currency conversion, though ledger data alone cannot confirm intent.`
      );
    }
    if (pathDepthAnalysis?.roundTripCount >= 3) {
      parts.push(`<strong>XRP→IOU→XRP round-trips:</strong> ${pathDepthAnalysis.roundTripCount} path payments paid and received XRP through intermediate token pairs — generating DEX volume without changing economic position.`);
    }

    // ── Fee spikes ────────────────────────────────────────────────────────
    if (feeAnalysis?.verdict === 'elevated') {
      parts.push(
        `<strong>💸 Fee Spike Pattern:</strong> ${feeAnalysis.spikeCount} transaction(s) paid more than 100× the normal fee. ` +
        `Bots often overpay fees to guarantee same-ledger execution alongside a counterparty — ` +
        `a coordination technique used in wash trading and front-running. Organic users almost never need fees this high.`
      );
    }

    // ── Statistical forensics ─────────────────────────────────────────────
    const forensicFlags = [
      benfordsAnalysis.verdict === 'high-deviation',
      entropyAnalysis?.verdict === 'anomalous',
      zipfAnalysis?.verdict === 'anomalous' || zipfAnalysis?.verdict === 'elevated',
      timeSeriesAnalysis?.verdict === 'bot-pattern',
      grangerAnalysis?.verdict === 'strong-coupling',
    ].filter(Boolean).length;

    if (forensicFlags >= 3) {
      parts.push(
        `<strong>🔬 Statistical Analysis — Multiple Engines Agree:</strong><br>` +
        `${forensicFlags} out of 5 independent mathematical tests found patterns inconsistent with human organic activity. ` +
        `These tests each use different mathematical approaches (number patterns, information theory, power laws, timing, causality) ` +
        `so they can't all be false alarms from the same data artifact.<br>` +
        `<strong>What it means:</strong> When unrelated statistical methods all flag the same account, ` +
        `the probability that all findings are coincidental false positives drops dramatically. ` +
        `This strongly suggests automated or coordinated activity, though it's not proof of fraud.`
      );
    } else if (forensicFlags >= 2) {
      parts.push(`<strong>Statistical analysis:</strong> ${forensicFlags}/5 tests flagged unusual patterns. Multiple independent tests agreeing is a meaningful signal — see the Forensic Suite section.`);
    } else if (forensicFlags === 1) {
      parts.push(`<strong>Statistical analysis:</strong> 1/5 tests flagged an unusual pattern. A single flag is a hypothesis to investigate further, not a conclusion.`);
    } else if (txList.length >= 30) {
      parts.push(`<strong>✅ All statistical tests normal:</strong> Benford's Law, entropy, Zipf's Law, time series, and offer/flow coupling all returned results consistent with organic activity across ${txList.length} transactions.`);
    }

    // ── Benford detail ────────────────────────────────────────────────────
    if (benfordsAnalysis.verdict === 'high-deviation' && benfordsAnalysis.chiSq != null) {
      parts.push(
        `<strong>Benford's Law detail (χ²=${benfordsAnalysis.chiSq.toFixed(1)}):</strong> ` +
        `In real financial data, "1" appears as the first digit ~30% of the time and "9" only ~4.6%. ` +
        `Computer-generated amounts break this pattern. This wallet's amounts deviate significantly ` +
        `(χ²=${benfordsAnalysis.chiSq.toFixed(1)} exceeds the 99% confidence threshold of 20.09).`
      );
    }

    // ── Token issuance ────────────────────────────────────────────────────
    if (issuerConnAnalysis.totalIssued > 0) {
      const top    = issuerConnAnalysis.topHolders?.[0];
      const topPct = top ? (top.balance / issuerConnAnalysis.totalIssued * 100).toFixed(0) : null;
      // Use gateway_balances for a more accurate supply figure if available
      const trueSupply = gatewayBalances?.result?.obligations
        ? Object.values(gatewayBalances.result.obligations).reduce((s, v) => s + Number(v), 0)
        : null;
      const supplyNote = trueSupply ? ` (verified via gateway_balances: ${fmt(trueSupply, 0)} total obligations)` : '';
      parts.push(
        `<strong>🪙 Token Issuance:</strong> This account has issued tokens — ` +
        `<strong>${fmt(issuerConnAnalysis.totalIssued, 0)} outstanding</strong> across ${issuerConnAnalysis.holderCount} holder(s)${supplyNote}. ` +
        (topPct ? `The largest single holder controls <strong>${topPct}% of supply</strong>. ` : '') +
        (topPct && Number(topPct) > 50 ? `Holding more than half the supply means one wallet could dump and collapse the token price. ` : '') +
        (issuerConnAnalysis.mirrorGroups?.length ? `<strong>${issuerConnAnalysis.mirrorGroups.length} cluster(s)</strong> of wallets each received identical token amounts — possible coordinated/insider wallets. ` : '') +
        (issuerConnAnalysis.createdAccts?.length ? `This issuer also created ${issuerConnAnalysis.createdAccts.length} wallet(s) — they may be controlled by the same entity. ` : '')
      );
    }

    // ── NFT ───────────────────────────────────────────────────────────────
    const critNft = (nftAnalysis.flags || []).filter(f => f.sev === 'critical');
    if (critNft.length) {
      parts.push(
        `<strong>🎨 NFT Risk:</strong> ${critNft.length} critical NFT issue(s) — most commonly a zero-price sell offer. ` +
        `The most common XRPL NFT scam: a malicious dApp tricks the wallet owner into signing a transaction ` +
        `that creates a sell offer for 0 XRP, making the NFT free for anyone to take.`
      );
    }

    // ── Inbound flow narrative ───────────────────────────────────────────
    if (inboundFlowAnalysis?.structuredFlag) {
      parts.push(
        `<strong>📥 Structured Inbound Pattern:</strong> ` +
        `${inboundFlowAnalysis.uniqueSources} source(s) funded this wallet — many payments arrive at near-identical amounts. ` +
        `Structured deposits deliberately break large transfers into smaller equal amounts to reduce traceability.`
      );
    } else if (inboundFlowAnalysis?.exchangeSrcs?.length) {
      const names = [...new Set(inboundFlowAnalysis.exchangeSrcs.map(s=>s.entity.name))].join(', ');
      parts.push(`<strong>📥 Funding Sources:</strong> Wallet received funds from ${inboundFlowAnalysis.uniqueSources} source(s) — ${names} among them. Total inbound: ${fmt(inboundFlowAnalysis.totalIn,2)} XRP.`);
    }

    // ── Memo narrative ────────────────────────────────────────────────────
    if (memoAnalysis?.scamMemos?.length) {
      parts.push(
        `<strong>📝 Scam Memo Content Detected:</strong> ` +
        `${memoAnalysis.scamMemos.length} transaction memo(s) contain text matching known scam patterns ` +
        `(airdrop claims, wallet verification requests, urgency language). ` +
        `These payments were likely sent by attackers attempting social engineering.`
      );
    }

    // ── Live book narrative ───────────────────────────────────────────────
    if (liveBookAnalysis?.signals?.some(s=>s.sev==='critical')) {
      parts.push(
        `<strong>📖 Active Spoofing Detected Right Now:</strong> ` +
        `This wallet currently has an order that controls over 40% of the visible order book depth. ` +
        `Large orders placed without intent to fill — then quickly cancelled when approached — is spoofing. ` +
        `This is happening in the live order book at time of inspection.`
      );
    }

    // ── Dest tag anomalies ────────────────────────────────────────────────
    if (destTagAnalysis?.riskPenalty > 0) {
      parts.push(`<strong>🏷 Destination Tag Pattern:</strong> Payments to exchanges used an unusually wide variety of destination tags — each tag identifies a different customer account. This can indicate a service routing payments to many accounts, or deliberate spread of deposits across exchange accounts to reduce traceability.`);
    }

    // ── Clean bill ────────────────────────────────────────────────────────
    if (criticals.length === 0 && warnings.length === 0) {
      parts.push(
        `<span style="color:#50fa7b"><strong>✅ No Elevated Signals Found</strong></span><br>` +
        `All checks returned results within normal ranges across ${coverageStr}. ` +
        `This does not guarantee the account is trustworthy — it means no identifiable red flags were found ` +
        `in the data analyzed.`
      );
    }

    // ── Coverage caveat ───────────────────────────────────────────────────
    // Deliberately doesn't repeat "pattern-based, not legal proof" — that's
    // already stated once, up top, and saying it twice in the same report is
    // exactly the kind of padding that makes a report feel automated instead
    // of read. Only add what the opening line doesn't already cover: whether
    // there's enough data for the statistical tests to mean much.
    if (txList.length < 100) {
      parts.push(
        `<em style="opacity:.6;font-size:.86em">` +
        `Data coverage: ${coverageStr}. Fewer than 100 transactions means some statistical tests above may not reach reliable conclusions — treat those specifically as weaker signal.</em>`
      );
    }

    return parts;
  }

  // ── Module groups ────────────────────────────────────────────────────────
  const MODULE_META = {
    'Security':             { icon: '🔐', desc: 'Keys, flags, multisig, auth changes' },
    'Drain Risk':           { icon: '⚠️', desc: 'Auth changes → large outflows, external key injection' },
    'Fund Flow':            { icon: '🌊', desc: 'Exchange flows, black holes, new-wallet recipients, path routing' },
    'NFT':                  { icon: '🎨', desc: 'Zero-value offers, no-metadata tokens, burns' },
    'Wash Trading':         { icon: '📊', desc: 'Cancel ratios, self-trades, order uniformity, burst patterns' },
    "Benford's Law":        { icon: '📐', desc: 'First-digit natural distribution test on all amounts' },
    'Volume Concentration': { icon: '🫧', desc: 'How many wallets drive token trading volume' },
    "Shannon's Entropy":    { icon: '🔀', desc: 'Randomness of amounts, counterparties, timing, tx types' },
    "Zipf's Law":           { icon: '📈', desc: 'Counterparty frequency power-law distribution' },
    'Time Series':          { icon: '🕐', desc: 'Interval regularity, periodicity — bot vs human timing' },
    'Offer/Flow Coupling':  { icon: '🔗', desc: 'Cross-correlation (not causality): create↔cancel, inflow↔outflow' },
    'Token Issuer':         { icon: '🪙', desc: 'Supply, freeze state, concentration' },
    'AMM':                  { icon: '💧', desc: 'LP positions, pool TVL, ownership share' },
    'Issuer Connections':   { icon: '🕸', desc: 'Distribution patterns, mirror wallets, account creation chains' },
    'Fee Spikes':           { icon: '💸', desc: 'Elevated fee transactions — coordination signal' },
    'Destination Tags':     { icon: '🏷', desc: 'Exchange sub-account routing patterns' },
    'Path Payments':        { icon: '🔄', desc: 'Circular routing, self-routing, deep-hop obfuscation' },
    'Inbound Flow':         { icon: '📥', desc: 'Funding sources, exchange deposits, structured inbound patterns' },
    'Memo Analysis':        { icon: '📝', desc: 'Scam patterns, coordination text, hex-decoded memo data' },
    'Escrow Depth':         { icon: '🔒', desc: 'Third-party escrows, maturity dates, conditional locks' },
    'Live Order Book':      { icon: '📖', desc: 'Current spoofing detection — wall orders, book depth concentration' },
  };

  const moduleOrder = ['Security','Drain Risk','Fund Flow','NFT','Wash Trading',
    "Benford's Law",'Volume Concentration',"Shannon's Entropy","Zipf's Law",
    'Time Series','Offer/Flow Coupling','Token Issuer','AMM','Issuer Connections',
    'Fee Spikes','Destination Tags','Path Payments'];

  const byModule = {};
  for (const m of moduleOrder)
    byModule[m] = allFindings.filter(f => f.module === m && f.sev !== 'ok' && f.sev !== 'info');

  const findingRows = moduleOrder
    .filter(m => byModule[m].length > 0)
    .map(m => {
      const meta = MODULE_META[m] || { icon: '📋', desc: '' };
      const rows = byModule[m].map(f => {
        // Build clickable hash links for findings that include transaction hashes
        const hashLinks = f.hashes?.length ? `
          <div style="margin-top:6px;display:flex;flex-wrap:wrap;gap:6px">
            ${f.hashes.slice(0,5).map(h => `
              <a href="https://livenet.xrpl.org/transactions/${escHtml(h)}" target="_blank" rel="noopener"
                 style="font-size:.7rem;font-family:monospace;color:var(--accent);text-decoration:none;
                        background:rgba(0,212,255,.06);border:1px solid rgba(0,212,255,.2);
                        border-radius:4px;padding:2px 6px" title="${escHtml(h)}">
                ${h.slice(0,8)}…${h.slice(-4)} 🔗
              </a>`).join('')}
          </div>` : '';
        return `
          <div class="report-finding-row">
            <div class="report-finding-top">
              ${sevBadge(f.sev)}
              <span class="report-finding-headline">${escHtml(f.headline)}</span>
            </div>
            ${f.detail ? `<div class="report-finding-detail">${escHtml(f.detail)}</div>` : ''}
            ${hashLinks}
          </div>`;
      }).join('');
      return `
        <div class="report-module">
          <div class="report-module-h">
            <span style="margin-right:6px">${meta.icon}</span>${escHtml(m)}
            <span style="font-size:.72rem;font-weight:400;opacity:.45;margin-left:8px">${escHtml(meta.desc)}</span>
          </div>
          ${rows}
        </div>`;
    }).join('');

  // ── Stats table ──────────────────────────────────────────────────────────
  const statRows = [
    { k: 'Address',                          v: addr,                                        mono: true },
    { k: 'Balance',                          v: fmt(balXrp, 4) + ' XRP' + _usd(balXrp),     mono: true },
    // Same three-state phrasing as Account Overview's header (renderHeader)
    // — this used to be a bare day-count with zero verification caveat,
    // which could show the exact same misleading "1 day" the header's own
    // bug fix addressed, just in a different part of the report.
    { k: 'Wallet Age',                       v: walletAgeDays == null ? '—'
        : (walletAgeVerified
            ? (walletAgeDays < 1 ? 'Created today' : walletAgeDays + ' days')
            : `At least ${walletAgeDays} day${walletAgeDays === 1 ? '' : 's'}`)
          + (walletCreatedTs ? ` — ${walletAgeVerified ? (walletActivationEvidence ? 'verified AccountRoot creation' : 'created') : 'earliest verified activity'} ` + new Date(walletCreatedTs).toLocaleDateString('en-US',{year:'numeric',month:'short',day:'numeric'}) : '') },
    { k: 'Risk Score',                       v: riskScore + '/100 — ' + riskWord,             color: riskColor },
    { k: 'Transactions Analyzed',            v: txList.length + (coverageDateStr ? ' · ' + coverageDateStr : '') },
    { k: 'Activity Span',                    v: coverageSpanDays > 0 ? coverageSpanDays + ' days' : 'unknown' },
    { k: 'Outbound Destinations',            v: fundFlowAnalysis.uniqueDests + ' addresses received funds' },
    { k: 'Total XRP Sent Out',               v: fmt(fundFlowAnalysis.totalOut, 2) + ' XRP',  mono: true },
    { k: 'New-Wallet Recipients',            v: (fundFlowAnalysis.newWalletDests?.length || 0) + (fundFlowAnalysis.newWalletDests?.length ? ' ⚠' : ' — none'), color: fundFlowAnalysis.newWalletDests?.length ? '#ff5555' : null },
    { k: 'Market Integrity (Wash / Spoofing)', v: `${_washSectionSeverity(washAnalysis).execPair[0]} / ${_washSectionSeverity(washAnalysis).spoofPair[0]}` },
    { k: 'Fee Spike Count (>100× base)',     v: (feeAnalysis?.spikeCount ?? 'N/A') + (feeAnalysis?.spikeCount > 5 ? ' ⚠' : ''), mono: true },
    { k: "Benford χ² (normal ≤ 15.5)",       v: benfordsAnalysis.chiSq != null ? benfordsAnalysis.chiSq.toFixed(2) + ' — ' + benfordsAnalysis.verdict.replace('-',' ') : 'insufficient data', mono: true },
    { k: 'Amount Entropy (natural 2.4–4.2)', v: entropyAnalysis?.amountEntropy != null ? entropyAnalysis.amountEntropy.toFixed(2) + ' bits' : 'N/A', mono: true },
    { k: 'Zipf Exponent (natural 0.8–1.3)',  v: zipfAnalysis?.zipfExponent != null ? zipfAnalysis.zipfExponent.toFixed(3) + '  R²=' + zipfAnalysis.rSquared?.toFixed(2) : 'N/A', mono: true },
    { k: 'Timing Regularity CV (bot < 0.25)',v: timeSeriesAnalysis?.intervalCV != null ? timeSeriesAnalysis.intervalCV.toFixed(3) + (timeSeriesAnalysis.intervalCV < 0.25 ? ' ⚠ bot-level' : ' ✓') : 'N/A', mono: true },
    { k: 'Offer Create↔Cancel Correlation',  v: grangerAnalysis?.offerCancelCausality?.maxCorr != null ? grangerAnalysis.offerCancelCausality.maxCorr.toFixed(3) + (grangerAnalysis.offerCancelCausality.maxCorr > 0.55 ? ' ⚠' : ' ✓') : 'N/A', mono: true },
    { k: 'XRP→IOU→XRP Round-Trips',         v: (pathDepthAnalysis?.roundTripCount ?? 0) + (pathDepthAnalysis?.roundTripCount >= 3 ? ' ⚠' : ''), mono: true },
    { k: 'Token Holders',                    v: issuerConnAnalysis.holderCount > 0 ? issuerConnAnalysis.holderCount + ' wallets hold tokens from this issuer' : 'Not a token issuer' },
    { k: 'Critical Findings',               v: criticals.length + (criticals.length === 0 ? ' — none' : ''), color: criticals.length > 0 ? '#ff5555' : '#50fa7b' },
    { k: 'Warnings',                         v: warnings.length  + (warnings.length  === 0 ? ' — none' : ''), color: warnings.length  > 0 ? '#ffb86c' : '#50fa7b' },
  ].map(r => `
    <div class="report-stat-row">
      <span class="report-stat-k">${escHtml(r.k)}</span>
      <span class="report-stat-v ${r.mono ? 'mono' : ''}" style="${r.color ? 'color:' + r.color : ''}">${escHtml(String(r.v))}</span>
    </div>`).join('');

  // ── Recommendations ──────────────────────────────────────────────────────
  const recColors   = { critical:'rgba(255,85,85,.08)',  warn:'rgba(255,184,108,.06)', info:'rgba(120,180,255,.05)', ok:'rgba(80,250,123,.05)' };
  const recBorders  = { critical:'rgba(255,85,85,.25)',  warn:'rgba(255,184,108,.20)', info:'rgba(120,180,255,.15)', ok:'rgba(80,250,123,.15)' };

  const recs = [];
  if (drainAnalysis.riskLevel === 'critical' || drainAnalysis.riskLevel === 'high')
    recs.push({ icon:'🔴', sev:'critical', text: 'If this is your wallet: stop sending funds here immediately. The account\'s security keys match a known drain attack pattern. Contact a security professional or the XRPL community before taking any action.' });
  if (fundFlowAnalysis.newWalletDests?.length)
    recs.push({ icon:'⚠️', sev:'critical', text: `${fundFlowAnalysis.newWalletDests.length} brand-new wallet(s) received large XRP transfers. This is a classic drain pattern. If this was unexpected, the funds have likely already been moved further down the chain.` });
  if (fundFlowAnalysis.blackHoleDests?.length)
    recs.push({ icon:'⛔', sev:'critical', text: 'Funds sent to black hole addresses are gone permanently. No exchange, no support team, and no legal action can retrieve them.' });
  if (fundFlowAnalysis.exchangeDests?.length)
    recs.push({ icon:'💱', sev:'warn', text: `If this was a drain: contact ${[...new Set(fundFlowAnalysis.exchangeDests.map(d => d.entity.name))].join(', ')} exchange support immediately with the transaction hashes from the Fund Flow section. Act within hours — exchanges can sometimes freeze funds quickly but not after they've been withdrawn.` });
  if (_washSectionSeverity(washAnalysis).tone !== 'ok')
    recs.push({ icon:'📊', sev:'warn', text: 'Wash-execution or spoofing signals detected. If you\'re a market maker: high cancel ratios are normal for your role — review the self-trade and self-routing signals specifically. If you\'re a token holder or researcher: this pattern suggests the token\'s apparent volume may be artificial.' });
  if (pathDepthAnalysis?.selfRoutedCount > 0 && !pathDepthAnalysis.selfRoutedLooksLikeSwaps)
    recs.push({ icon:'🔄', sev:'warn', text: `${pathDepthAnalysis.selfRoutedCount} path payment(s) routed through the DEX back to the same address, concentrated on the same currency pair(s). Check the Path Payments section for specific transaction hashes.` });
  if (issuerConnAnalysis.mirrorGroups?.length)
    recs.push({ icon:'🕸', sev:'warn', text: 'Mirror wallet clusters found. If you are the issuer, determine whether these are genuine holders or insider accounts used to create the appearance of broader distribution. These wallets could coordinate a sell-off.' });
  if (nftAnalysis.flags?.some(f => f.sev === 'critical'))
    recs.push({ icon:'🎨', sev:'critical', text: 'Zero-value NFT offer detected. If you didn\'t intentionally list your NFT for free: identify what website or app you used around the time this transaction was signed, and revoke any approvals it has.' });
  if (feeAnalysis?.verdict === 'elevated')
    recs.push({ icon:'💸', sev:'info', text: `${feeAnalysis.spikeCount} transactions paid >100× normal fees. Check the Fee Spikes section to see if these align with moments of concentrated trading — elevated fees often mark coordinated activity windows.` });
  if (recs.length === 0)
    recs.push({ icon:'✅', sev:'ok', text: 'No immediate actions required. The account shows no identifiable red flags. Continue monitoring as activity grows — some patterns only become statistically significant with more data.' });

  const recsHtml = recs.map(r => `
    <div style="background:${recColors[r.sev]||recColors.info};border:1px solid ${recBorders[r.sev]||recBorders.info};border-radius:10px;padding:12px 14px;margin-bottom:8px;display:flex;gap:12px;align-items:flex-start">
      <span style="font-size:1.15rem;flex-shrink:0;margin-top:1px">${r.icon}</span>
      <span style="font-size:.85rem;line-height:1.65;color:rgba(255,255,255,.78)">${r.text}</span>
    </div>`).join('');

  // ── Glossary ─────────────────────────────────────────────────────────────
  const glossaryTerms = [
    ["Benford's Law",      "In organic financial data, amounts starting with '1' appear ~30% of the time. Computer-generated amounts often break this law."],
    ["Shannon's Entropy",  "Measures how 'predictable' transaction amounts and partners are. Bots repeat the same amounts; humans don't."],
    ["Zipf's Law",         "Natural networks have a few heavy relationships and many light ones. Wash rings show unnaturally equal relationships."],
    ["Time Series CV",     "Coefficient of Variation of gaps between transactions. Humans: >0.8 (irregular). Bots: <0.3 (clock-like)."],
    ["Offer/Flow Coupling", "Cross-correlation between two event series at a time lag — e.g., offer creation and cancellation moving together. A correlation, not a causality test; it can't show which one actually drives the other."],
    ["Interval CV",        "The regularity of timing between transactions. Very low = mechanical/automated. Very high = erratic/bursty."],
    ["Gateway Balances",   "The XRPL API command that returns the true outstanding obligations of a token issuer — more accurate than just reading trustlines."],
    ["Destination Tag",    "A number attached to a payment that identifies the recipient sub-account at an exchange. Like a bank account reference number."],
    ["Path Payment",       "An XRPL payment that routes through intermediate DEX pairs. Can create trading volume on pairs the sender never intended to trade."],
    ["XRP Round-Trip",     "A path payment that starts and ends in XRP, routed through IOU pairs. Creates DEX volume with no net economic transfer."],
    ["Fee Multiplier",     "XRPL's base transaction fee is 12 drops (~$0.000001). Paying 100× means paying 1,200 drops — bots do this for guaranteed same-ledger execution."],
  ];

  const glossaryHtml = `
    <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:8px;margin-top:10px">
      ${glossaryTerms.map(([term, def]) => `
        <div style="background:rgba(255,255,255,.03);border-radius:8px;padding:10px 12px;border:1px solid rgba(255,255,255,.05)">
          <div style="font-size:.78rem;font-weight:700;color:rgba(255,255,255,.75);margin-bottom:4px">${escHtml(term)}</div>
          <div style="font-size:.74rem;color:rgba(255,255,255,.42);line-height:1.5">${escHtml(def)}</div>
        </div>`).join('')}
    </div>`;

  const narrativeParts = buildNarrative();

  return `
    <div class="report-wrap">

      <!-- ── Cover ── -->
      <div class="report-cover">
        <div class="report-cover-left">
          <div class="report-logo">⚡ NaluXRP</div>
          <h2 class="report-title">Account Investigation Report</h2>
          <div class="report-addr mono">${escHtml(addr)}</div>
          <div class="report-ts">Generated ${ts}</div>
          <div style="font-size:.75rem;color:rgba(255,255,255,.38);margin-top:4px">Coverage: ${escHtml(coverageStr)}</div>
        </div>
        <div class="report-score-circle" style="--score-color:${riskColor}">
          <div class="report-score-num" style="color:${riskColor}">${riskScore}</div>
          <div class="report-score-den">/100</div>
          <div class="report-score-word" style="color:${riskColor}">${riskWord}</div>
        </div>
      </div>

      <!-- ── Executive Summary ── -->
      <div class="report-section">
        <h3 class="report-section-h">📋 Executive Summary</h3>
        <div class="report-narrative">
          ${narrativeParts.map(p => `<p style="margin-bottom:12px;line-height:1.7">${p}</p>`).join('')}
        </div>
      </div>

      <!-- ── Copy Analysis for AI ──
           Deliberately its own section, clearly separate from the
           deterministic Executive Summary above. Rather than the app making
           its own API call (which needs a key, a proxy, or a multi-GB local
           model download), this formats every finding into one clean block
           the user copies and pastes into whatever AI model they already
           use — same idea as Project Intelligence's "Copy for AI" button. -->
      <div class="report-section">
        <h3 class="report-section-h">📋 Copy Analysis for AI</h3>
        <div id="ai-explanation-body">
          <p style="font-size:.82rem;color:rgba(255,255,255,.45);margin-bottom:12px;line-height:1.6">
            Copy every finding from this inspection as plain text, ready to paste into ChatGPT, Claude, or any model
            you already use, for a plain-language read of what this account's activity suggests.
          </p>
          <button class="settings-btn settings-btn--primary" onclick="copyInspectorAnalysisForAi()">📋 Copy for AI</button>
        </div>
      </div>

      <!-- ── Account Activity & Interactions ──
           Activity timeline reuses the same chart built for the Account
           Overview section up top (renderActivityTimeline targets this
           element id as a second mount point). The counterparty breakdown
           deliberately does NOT reuse the radial network map here — that
           map is good for clicking around and exploring, which fits Account
           Overview, but a report is read top-to-bottom, so who-transacts-
           with-whom is shown as a ranked, volume-sorted list instead: easier
           to scan, and prints/exports cleanly. Same underlying data either way. -->
      <div class="report-section">
        <h3 class="report-section-h">🗺️ Account Activity &amp; Interactions</h3>
        <p style="font-size:.8rem;color:rgba(255,255,255,.4);margin-bottom:10px;line-height:1.6">
          Transaction volume over time, who this account actually transacts with — ranked by volume,
          colored by category (exchange, black hole, issuer, other) — and how much moved in versus out
          relative to the current balance.
        </p>
        <div id="inspect-report-activity-chart" style="margin-bottom:14px"></div>
        <div style="margin-bottom:16px">${buildRankedCounterpartyList(txList, addr)}</div>
        ${buildFundFlowSummaryBar(balXrp, fundFlowAnalysis, inboundFlowAnalysis)}
      </div>

      <!-- ── Stats Snapshot ── -->
      <div class="report-section">
        <h3 class="report-section-h">📐 Account Snapshot
          <button onclick="exportTxCSV(window._lastTxList)" title="Export all transactions to CSV"
            style="margin-left:12px;background:rgba(0,212,255,.10);border:1px solid rgba(0,212,255,.25);
                   color:var(--accent);border-radius:6px;padding:3px 10px;font-size:.7rem;cursor:pointer">
            ⬇ Export CSV
          </button>
        </h3>
        <div class="report-stats-grid">${statRows}</div>
      </div>

      <!-- ── Findings by Module ── -->
      ${findingRows ? `
      <div class="report-section">
        <h3 class="report-section-h">🔬 Findings by Module
          <span class="report-counts">
            <span class="report-count report-count--crit">${criticals.length} Critical</span>
            <span class="report-count report-count--warn">${warnings.length} Warnings</span>
          </span>
        </h3>
        <p style="font-size:.8rem;color:rgba(255,255,255,.4);margin-bottom:14px;line-height:1.6">
          Each module below used a different method to analyse the account.
          Findings include clickable transaction hash links so you can verify everything on-chain.
        </p>
        <div class="report-findings">${findingRows}</div>
      </div>` : `
      <div class="report-section">
        <h3 class="report-section-h">🔬 Findings</h3>
        <div class="report-clean-note">✅ No elevated findings across all ${moduleOrder.length} analysis modules.</div>
      </div>`}

      <!-- ── Recommendations ── -->
      <div class="report-section">
        <h3 class="report-section-h">💡 Recommended Actions</h3>
        ${recsHtml}
      </div>

      <!-- ── Glossary ── -->
      <div class="report-section">
        <h3 class="report-section-h">📖 Understanding This Report</h3>
        <p style="font-size:.82rem;color:rgba(255,255,255,.45);line-height:1.65;margin-bottom:10px">
          Plain-English definitions for every technical term used in this report.
        </p>
        ${glossaryHtml}
      </div>

      <!-- ── Disclaimer ── -->
      <div class="report-disclaimer">
        <strong>Important:</strong> This report is generated automatically from public on-chain data using
        statistical pattern analysis. Signals are not proof. Legitimate market makers, bots, and active
        users can trigger individual flags. Always cross-reference with additional evidence before making
        legal, financial, or reputational decisions. NaluXRP Inspector is a transparency and research tool —
        not a legal or forensic authority.
      </div>

    </div>
  `;
}

function renderFullReport(container, ...args) {
  container.innerHTML = generateFullReport(...args);
}

/* ═══════════════════════════════════════════════════
   HTML SELF-MOUNT
═══════════════════════════════════════════════════ */
function _mountInspectorHTML() {
  const panel = document.getElementById('tab-inspector');
  // Force-replace whenever our version marker is absent
  if (!panel) return;
  if (panel.querySelector('[data-inspector-v2]')) return;

  panel.innerHTML = `
    <style>
      /* ── Depth mode visibility (Simple / Explain / Analyst) ──
         .simple-only / .advanced-only are unchanged from the original
         binary mode — "advanced" here means "Explain or higher," so every
         existing section wired to these two classes keeps working exactly
         as before with zero changes at each of its ~20+ call sites.
         .analyst-only-block / .analyst-only-inline are NEW, narrower tiers
         nested *inside* .advanced-only content — visible only in the full
         Analyst tier (raw confidence %, transaction hash chips, and other
         "raw metric" content the Explain tier intentionally omits). */
      #inspect-result.mode-simple  .advanced-only { display: none !important; }
      #inspect-result.mode-advanced .advanced-only { /* inherit display */ }
      #inspect-result.mode-advanced .simple-only  { display: none !important; }
      #inspect-result.mode-simple  .simple-only   { /* inherit display */ }
      .analyst-only-block  { display: none; }
      .analyst-only-inline { display: none; }
      #inspect-result.depth-analyst .analyst-only-block  { display: block; }
      #inspect-result.depth-analyst .analyst-only-inline { display: inline; }
      .depth-mode-btn--active { background: rgba(0,212,255,.18) !important; color: #00d4ff !important; }
      /* Advanced-only sections that default hidden */
      #inspect-result.mode-simple  #section-volconc,
      #inspect-result.mode-simple  #section-issuer,
      #inspect-result.mode-simple  #section-issuer-connections,
      #inspect-result.mode-simple  #section-dist-market-flow,
      #inspect-result.mode-simple  #section-amm,
      #inspect-result.mode-simple  #section-fee-analysis,
      #inspect-result.mode-simple  #section-desttag,
      #inspect-result.mode-simple  #section-pathdepth,
      #inspect-result.mode-simple  #section-memos,
      #inspect-result.mode-simple  #section-escrow-depth,
      #inspect-result.mode-simple  #section-checks,
      #inspect-result.mode-simple  #section-livebook,
      #inspect-result.mode-simple  #section-trustlines { display: none !important; }
      /* These 3 group headers have EVERY member section in the hide-list
         above — Counterparties & Relationships (issuer-connections, dist-
         market-flow, desttag), Liquidity / AMM (amm alone), and Issuer
         Intelligence (issuer alone). Without hiding the header too, Simple
         mode showed a bare, empty-looking group label with nothing under
         it before the next group's own header — a real "is this broken?"
         moment reported live. Market & DEX Activity is NOT in this list:
         its own Wash Trading section stays visible in Simple mode, so that
         group correctly still shows something. */
      #inspect-result.mode-simple  #group-counterparties,
      #inspect-result.mode-simple  #group-liquidity,
      #inspect-result.mode-simple  #group-issuer { display: none !important; }
      /* Forensic engine tabs styling */
      .forensic-engine-tabs { }
      .forensic-sub-section { border-radius: 8px; overflow: hidden; }
      .forensic-tab-btn {
        background: rgba(0,212,255,.05); border: 1px solid rgba(0,212,255,.12);
        color: rgba(255,255,255,.65); border-radius: 8px; padding: 8px 12px;
        font-size: .78rem; cursor: pointer; display: flex; align-items: center; gap: 6px;
        width: 100%; text-align: left; transition: background .15s;
      }
      .forensic-tab-btn:hover { background: rgba(0,212,255,.10); color: rgba(255,255,255,.9); }
      .forensic-tab-body { background: rgba(0,212,255,.02); border: 1px solid rgba(0,212,255,.08); border-top: none; border-radius: 0 0 8px 8px; padding: 0 12px; }
      /* New wallet badge in header */
      .acct-cell--new { border-color: rgba(255,184,108,.4) !important; }
      .acct-cell-new-badge { font-size: .65rem; color: #ffb86c; margin-top: 2px; font-weight: 700; }
    </style>
    <div class="inspector-wrap" data-inspector-v2="1">

      <div class="inspector-page-header">
        <div class="inspector-title-row">
          <h1 class="inspector-page-title">🔍 Account Inspector</h1>
          <button class="inspector-howto-btn" onclick="showInspectorHowTo()">
            <span>?</span> How to use
          </button>
        </div>
        <p class="inspector-sub">
          Deep-dive any XRPL address — security posture, drain risk, NFT exposure,
          wash-trading signals, token issuer status and AMM liquidity positions.
        </p>
      </div>

      <div class="search-row">
        <input id="inspect-addr" class="xrpl-input" type="text"
          placeholder="rXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX"
          autocomplete="off" spellcheck="false"
          aria-label="XRPL address to inspect" />
        <button class="xrpl-btn btn-inspect" onclick="runInspect()">Inspect →</button>
      </div>

      <div id="inspect-warn"    class="alert-warn"    style="display:none" role="alert">⚡ Not connected — connect to an XRPL node first.</div>
      <div id="inspect-err"     class="alert-err"     style="display:none" role="alert"></div>
      <!-- One large, centered brand icon + real stage status — deliberately
           NOT paired with the skeleton-shimmer placeholder this used to show
           alongside it (a large loader plus a stack of shimmering bars reads
           as busy, not calm). The address and stage message are set by
           runInspect() itself via the same real, state-tied _setMsg
           mechanism already in place — no fake percentages, no timer-driven
           stages. -->
      <div id="inspect-loading" class="inspect-loading-full" style="display:none" role="status" aria-live="polite">
        <img class="inspect-shield-spinner" src="${escHtml(document.querySelector('.brand-glyph')?.getAttribute('src') || 'NaluLF/images/NLF-Shield-blue.jpg')}" alt="" decoding="async" />
        <div class="inspect-loading-title">Inspecting Account</div>
        <div id="inspect-loading-addr" class="inspect-loading-addr mono"></div>
        <div id="inspect-loading-msg" class="inspect-loading-status">Analyzing…</div>
      </div>

      <!-- ══ Initial State Dashboard ══ -->
      <div id="inspect-empty">

        <!-- ── Network health strip ── -->
        <div class="isd-net-strip">

          <!-- Status pill -->
          <div class="isd-conn-pill" id="isd-conn-pill">
            <span class="isd-conn-dot" id="isd-conn-dot"></span>
            <span id="isd-conn-label">Connecting…</span>
          </div>

          <!-- Live metrics -->
          <div class="isd-metrics-row">

            <div class="isd-metric-card">
              <div class="isd-metric-label">Ledger</div>
              <div class="isd-metric-val mono" id="isd-ledger-idx">—</div>
              <div class="isd-metric-sub" id="isd-ledger-age">—</div>
            </div>

            <div class="isd-metric-card">
              <div class="isd-metric-label">TPS</div>
              <div class="isd-metric-val" id="isd-tps">—</div>
              <div class="isd-metric-sub" id="isd-tps-trend">waiting…</div>
            </div>

            <div class="isd-metric-card">
              <div class="isd-metric-label">Avg Fee</div>
              <div class="isd-metric-val mono" id="isd-fee">—</div>
              <div class="isd-metric-sub" id="isd-fee-level">—</div>
            </div>

            <div class="isd-metric-card">
              <div class="isd-metric-label">Close Time</div>
              <div class="isd-metric-val" id="isd-close-time">—</div>
              <div class="isd-metric-sub">secs / ledger</div>
            </div>

            <div class="isd-metric-card">
              <div class="isd-metric-label">Reserve</div>
              <div class="isd-metric-val mono" id="isd-reserve">10 XRP</div>
              <div class="isd-metric-sub">+2 per object</div>
            </div>

            <div class="isd-metric-card">
              <div class="isd-metric-label">Dominant TX</div>
              <div class="isd-metric-val" id="isd-dom-tx">—</div>
              <div class="isd-metric-sub" id="isd-dom-pct">—</div>
            </div>

          </div>

          <!-- Fee pressure bar -->
          <div class="isd-fee-bar-wrap">
            <span class="isd-fee-bar-label">Fee Pressure</span>
            <div class="isd-fee-bar-track">
              <div class="isd-fee-bar-fill" id="isd-fee-bar"></div>
            </div>
            <span class="isd-fee-bar-level" id="isd-fee-bar-label">Low</span>
          </div>

        </div>

        <!-- ── My Wallets ── -->
        <div class="isd-section" id="isd-wallets-section" style="display:none">
          <div class="isd-section-hdr">
            <div class="isd-section-left">
              <span class="isd-section-icon">💼</span>
              <h2 class="isd-section-title">My Wallets</h2>
            </div>
            <span class="isd-section-hint">tap to inspect</span>
          </div>
          <div class="isd-wallet-grid" id="isd-wallet-list"></div>
        </div>

        <!-- ── Recent Inspections ── -->
        <div class="isd-section" id="isd-recent-section" style="display:none">
          <div class="isd-section-hdr">
            <div class="isd-section-left">
              <span class="isd-section-icon">🕐</span>
              <h2 class="isd-section-title">Recent Inspections</h2>
            </div>
            <button class="isd-text-btn" onclick="inspectorClearHistory()">Clear all</button>
          </div>
          <div class="isd-recent-list" id="isd-recent-list"></div>
        </div>

        <!-- ── Watchlist ── -->
        <div class="isd-section" id="isd-watchlist-section" style="display:none">
          <div class="isd-section-hdr">
            <div class="isd-section-left">
              <span class="isd-section-icon">★</span>
              <h2 class="isd-section-title">Watchlist</h2>
            </div>
            <button class="isd-text-btn" onclick="inspectorClearWatchlist()">Clear</button>
          </div>
          <div class="isd-recent-list" id="isd-watchlist-list"></div>
        </div>

        <!-- ── Notable Addresses ── -->
        <div class="isd-section">
          <div class="isd-section-hdr">
            <div class="isd-section-left">
              <span class="isd-section-icon">🌐</span>
              <h2 class="isd-section-title">Notable XRPL Addresses</h2>
            </div>
            <span class="isd-section-hint">tap to explore</span>
          </div>
          <div class="isd-notable-grid" id="isd-notable-grid"></div>
        </div>

        <!-- ── What We Detect ── -->
        <div class="isd-section">
          <div class="isd-section-hdr">
            <div class="isd-section-left">
              <span class="isd-section-icon">🛡</span>
              <h2 class="isd-section-title">What The Inspector Detects</h2>
            </div>
          </div>
          <div class="isd-cap-grid" id="isd-cap-grid"></div>
        </div>

      </div>

      <div id="inspect-result" style="display:none">

        <div class="inspect-risk-banner">
          <div class="irb-left">
            <button class="irb-back-btn" onclick="inspectorGoBack()" title="Back to search">← Back</button>
            <div class="irb-addr-group">
              <span class="irb-addr mono" id="inspect-addr-badge">—</span>
              <button class="irb-copy-btn" onclick="inspectorCopyAddr()" title="Copy address" aria-label="Copy address">📋</button>
              <button id="watchlist-btn" class="irb-copy-btn" title="Add to watchlist" aria-label="Add to watchlist">☆<span class="irb-btn-label"> Watch</span></button>
              <button class="irb-copy-btn" onclick="openCompareModal()" title="Compare against another account" aria-label="Compare against another account">⚖️<span class="irb-btn-label"> Compare</span></button>
            </div>
          </div>
          <!-- Desktop-only compact account state (Phase 1: Investigation
               Shell). Mirrors values renderHeader() already computes for
               #inspect-acct-grid — never recomputed here, just also written
               to these two spans so the persistent Command Bar carries the
               one or two numbers worth seeing without scrolling, instead of
               leading with the full 7-cell card wall. Hidden by default;
               shown only at the desktop shell breakpoint (inspector.css). -->
          <div class="irb-state-group">
            <div class="irb-state-item"><span class="irb-state-val mono" id="irb-balance">—</span><span class="irb-state-label">Balance</span></div>
            <div class="irb-state-item"><span class="irb-state-val" id="irb-age">—</span><span class="irb-state-label">Age</span></div>
          </div>
          <div style="display:flex;align-items:center;gap:8px">
            <div id="depth-mode-group" role="group" aria-label="Report detail level" style="display:flex;gap:2px;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.12);border-radius:6px;padding:2px">
              ${[['simple', '👁 Simple'], ['explain', '💡 Explain'], ['analyst', '⚗ Analyst']].map(([mode, label]) => `
                <button type="button" class="depth-mode-btn" data-depth="${mode}" onclick="setDepthMode('${mode}')" aria-pressed="${mode === 'simple'}"
                  title="${mode === 'simple' ? 'What happened, what matters' : mode === 'explain' ? 'Adds why Nalu noticed it, supporting/counter evidence, alternative explanations' : 'Adds raw metrics, confidence values, and transaction evidence'}"
                  style="background:none;border:none;color:rgba(255,255,255,.6);border-radius:4px;padding:4px 8px;font-size:.72rem;cursor:pointer">${label}</button>`).join('')}
            </div>
            <div class="irb-score-group">
              <div class="irb-score-val" id="inspect-risk-score">—</div>
              <div class="irb-score-label" id="inspect-risk-label">Risk Score</div>
            </div>
          </div>
        </div>

        <!-- Data Quality / Analysis Coverage strip — persistent, compact,
             near the top so a polished chart never implies more certainty
             than the underlying fetch actually supports. -->
        <div id="inspect-dataquality-strip"></div>

        <!-- Change detection banner (hidden until 2nd+ inspection of same addr) -->
        <div id="change-banner"></div>

        <!-- Account Behavior — plain-language "what does this account do"
             summary. Deliberately placed BEFORE the risk-score banner:
             begin with behavior, not a risk number. -->
        <div id="account-behavior" class="inspector-glass-panel" style="margin-bottom:10px">
          <div id="account-behavior-body" style="opacity:.5;font-size:.82rem" role="status" aria-live="polite">Analysing…</div>
        </div>

        <!-- Quick Verdict (3-line summary, always first thing you see) -->
        <div id="quick-verdict" class="inspector-glass-panel" style="margin-bottom:10px">
          <div id="quick-verdict-body" style="opacity:.5;font-size:.82rem" role="status" aria-live="polite">Analysing…</div>
        </div>

        <div class="inspector-group-header" id="group-overview"><span class="inspector-group-title">Account Overview</span></div>
        <section class="widget-card inspector-section" id="section-overview">
          <header class="widget-header section-header" tabindex="0" role="button" aria-expanded="true">
            <h2 class="widget-title">📊 Account Overview</h2>
            <button onclick="exportInspectorJSON()" title="Export full analysis as JSON"
              style="margin-left:auto;background:rgba(0,212,255,.07);border:1px solid rgba(0,212,255,.18);
                     color:var(--accent);border-radius:6px;padding:3px 9px;font-size:.68rem;cursor:pointer">⬇ JSON</button>
            <span class="section-chevron">▾</span>
          </header>
          <div class="section-body account-grid" id="inspect-acct-grid"></div>
          <div id="inspect-risk-breakdown" style="padding:0 12px 8px"></div>
          <div class="inspector-subpanel-group">
            <div id="inspect-risk-trend"></div>
            <div id="inspect-activity-chart"></div>
          </div>
          <div class="inspector-subpanel-group">
            <div id="inspect-who-connected"></div>
            <div id="inspect-relationship-landscape"></div>
          </div>
          <div id="inspect-ledger-map" style="padding:0 12px 12px"></div>
        </section>

        <section class="widget-card inspector-section" id="section-events">
          <header class="widget-header section-header" tabindex="0" role="button" aria-expanded="true">
            <h2 class="widget-title">🕐 Important Events</h2>
            <span class="section-badge" id="badge-events"></span>
            <span class="section-chevron">▾</span>
          </header>
          <div class="section-body" id="inspect-events-body">
            <p class="widget-help" style="opacity:.55;font-size:.84rem">
              Security changes, drain episodes, and fee spikes from across this account's history, merged into one
              chronological list. Click any event to jump straight to the section that explains it.
            </p>
          </div>
        </section>

        <div class="inspector-group-header" id="group-security"><span class="inspector-group-title">Security</span></div>
        <section class="widget-card inspector-section" id="section-security">
          <header class="widget-header section-header" tabindex="0" role="button" aria-expanded="true">
            <h2 class="widget-title">🔐 Security Audit</h2>
            <span class="section-badge" id="badge-security"></span>
            <span class="section-chevron">▾</span>
          </header>
          <div class="section-body" id="inspect-security-body"></div>
        </section>

        <div class="inspector-group-header" id="group-balance"><span class="inspector-group-title">Balance &amp; Asset Activity</span></div>
        <section class="widget-card inspector-section" id="section-drain">
          <header class="widget-header section-header" tabindex="0" role="button" aria-expanded="true">
            <h2 class="widget-title">⚠🌊 Drain Risk &amp; Fund Flow</h2>
            <span class="section-badge" id="badge-drain"></span>
            <span class="section-chevron">▾</span>
          </header>
          <div class="section-body" id="inspect-drain-body">
            <p class="widget-help" style="opacity:.6;font-size:.84rem">
              Answers three related questions together: has this account been taken over by
              someone else, is money actually leaving it in an unusual way, and — either way —
              where did the money actually go? An account can have one problem without the others.
            </p>
          </div>
        </section>

        <section class="widget-card inspector-section" id="section-flowmotifs">
          <header class="widget-header section-header" tabindex="0" role="button" aria-expanded="true">
            <h2 class="widget-title">🔁 Flow Motifs</h2>
            <span class="section-badge" id="badge-flowmotifs"></span>
            <span class="section-chevron">▾</span>
          </header>
          <div class="section-body" id="inspect-flowmotifs-body">
            <p class="widget-help" style="opacity:.55;font-size:.84rem">
              Repeated flow patterns found in this account's own transaction history — round-trip
              payments, AMM deposit/withdrawal cycles, and exchange round-trips. A pattern existing
              here does not by itself mean anything improper; see Wash Execution and AMM / Liquidity
              for interpretation.
            </p>
          </div>
        </section>

        <section class="widget-card inspector-section" id="section-inbound">
          <header class="widget-header section-header" tabindex="0" role="button" aria-expanded="true">
            <h2 class="widget-title">📥 Inbound Flow Analysis</h2>
            <span class="section-badge" id="badge-inbound"></span>
            <span class="section-chevron">▾</span>
          </header>
          <div class="section-body" id="inspect-inbound-body">
            <p class="widget-help" style="opacity:.55;font-size:.84rem">
              Who funded this wallet — top sources, exchange withdrawals, structured deposit patterns,
              and single-source concentration. Pairs with Fund Flow for a complete in/out picture.
            </p>
          </div>
        </section>

        <section class="widget-card inspector-section" id="section-trustlines">
          <header class="widget-header section-header" tabindex="0" role="button" aria-expanded="true">
            <h2 class="widget-title">🔗 Trustlines</h2>
            <span class="section-badge section-badge--neutral" id="trust-count-badge">0</span>
            <span class="section-chevron">▾</span>
          </header>
          <div class="section-body" id="inspect-trust-body"></div>
        </section>

        <div class="inspector-group-header" id="group-txbehavior"><span class="inspector-group-title">Transaction Behavior</span></div>
        <section class="widget-card inspector-section" id="section-tx">
          <header class="widget-header section-header" tabindex="0" role="button" aria-expanded="true">
            <h2 class="widget-title">📜 Transaction History</h2>
            <span class="section-badge section-badge--neutral" id="badge-tx">—</span>
            <span class="section-chevron">▾</span>
          </header>
          <div class="section-body" id="inspect-tx-timeline"></div>
        </section>

        <section class="widget-card inspector-section" id="section-pathdepth">
          <header class="widget-header section-header" tabindex="0" role="button" aria-expanded="true">
            <h2 class="widget-title">🔄 Path Payment Depth</h2>
            <span class="section-badge" id="badge-pathdepth"></span>
            <span class="section-chevron">▾</span>
          </header>
          <div class="section-body" id="inspect-pathdepth-body">
            <p class="widget-help" style="opacity:.55;font-size:.84rem">
              Analyses multi-hop path payments for circular routing (XRP→IOU→XRP round-trips),
              self-routing (paying yourself through the DEX to generate artificial volume),
              and deep hop chains that may obscure fund origin.
            </p>
          </div>
        </section>

        <div class="inspector-group-header" id="group-counterparties"><span class="inspector-group-title">Counterparties &amp; Relationships</span></div>
        <section class="widget-card inspector-section" id="section-issuer-connections">
          <header class="widget-header section-header" tabindex="0" role="button" aria-expanded="true">
            <h2 class="widget-title">🕸 Issuer Connection Graph</h2>
            <span class="section-badge" id="badge-issuer-connections"></span>
            <span class="section-chevron">▾</span>
          </header>
          <div class="section-body" id="inspect-issuer-connections-body">
            <p class="widget-help" style="opacity:.6;font-size:.84rem">
              Token supply distribution, holder concentration, accounts created by this issuer,
              and mirror-wallet clusters (accounts receiving identical amounts — possible sybil rings).
            </p>
          </div>
        </section>

        <section class="widget-card inspector-section" id="section-dist-market-flow">
          <header class="widget-header section-header" tabindex="0" role="button" aria-expanded="true">
            <h2 class="widget-title">📊 Distribution &amp; Market Flow</h2>
            <span class="section-badge" id="badge-dist-market-flow"></span>
            <span class="section-chevron">▾</span>
          </header>
          <div class="section-body" id="inspect-dist-market-flow-body">
            <p class="widget-help" style="opacity:.6;font-size:.84rem">
              Traces this issuer's largest direct token recipients forward: did they begin
              selling in a similar time window, and did their proceeds converge on a shared
              destination? Requires extra live lookups per recipient wallet, so this runs
              on demand rather than automatically.
            </p>
          </div>
        </section>

        <section class="widget-card inspector-section" id="section-desttag">
          <header class="widget-header section-header" tabindex="0" role="button" aria-expanded="true">
            <h2 class="widget-title">🏷 Destination Tag Patterns</h2>
            <span class="section-badge" id="badge-desttag"></span>
            <span class="section-chevron">▾</span>
          </header>
          <div class="section-body" id="inspect-desttag-body">
            <p class="widget-help" style="opacity:.55;font-size:.84rem">
              Analyses destination tags used in exchange payments. The same tag repeated = one person's exchange account.
              Many different tags = a service routing to many accounts, or deliberate deposit spreading.
            </p>
          </div>
        </section>

        <div class="inspector-group-header" id="group-market"><span class="inspector-group-title">Market &amp; DEX Activity</span></div>
        <section class="widget-card inspector-section" id="section-wash">
          <header class="widget-header section-header" tabindex="0" role="button" aria-expanded="true">
            <h2 class="widget-title">📊 Wash Trading</h2>
            <span class="section-badge" id="badge-wash"></span>
            <span class="section-chevron">▾</span>
          </header>
          <div class="section-body" id="inspect-wash-body"></div>
        </section>

        <section class="widget-card inspector-section" id="section-volconc">
          <header class="widget-header section-header" tabindex="0" role="button" aria-expanded="true">
            <h2 class="widget-title">🫧 Volume Concentration</h2>
            <span class="section-badge" id="badge-volconc"></span>
            <span class="section-chevron">▾</span>
          </header>
          <div class="section-body" id="inspect-volconc-body"></div>
        </section>

        <section class="widget-card inspector-section" id="section-livebook" style="display:none">
          <header class="widget-header section-header" tabindex="0" role="button" aria-expanded="true">
            <h2 class="widget-title">📖 Live Order Book</h2>
            <span class="section-badge" id="badge-livebook"></span>
            <span class="section-chevron">▾</span>
          </header>
          <div class="section-body" id="inspect-livebook-body">
            <p class="widget-help" style="opacity:.55;font-size:.84rem">
              Current live order book for this wallet's most-traded pair.
              Detects wall orders (one address dominating book depth), uniform bot-placed sizes,
              and whether this wallet's open offers make up an unusual share of visible liquidity.
            </p>
          </div>
        </section>

        <div class="inspector-group-header" id="group-liquidity"><span class="inspector-group-title">Liquidity / AMM</span></div>
        <section class="widget-card inspector-section" id="section-amm">
          <header class="widget-header section-header" tabindex="0" role="button" aria-expanded="true">
            <h2 class="widget-title">💧 AMM / Liquidity</h2>
            <span class="section-badge" id="badge-amm"></span>
            <span class="section-chevron">▾</span>
          </header>
          <div class="section-body" id="inspect-amm-body"></div>
        </section>

        <div class="inspector-group-header" id="group-issuer"><span class="inspector-group-title">Issuer Intelligence</span></div>
        <section class="widget-card inspector-section" id="section-issuer">
          <header class="widget-header section-header" tabindex="0" role="button" aria-expanded="true">
            <h2 class="widget-title">🪙 Token Issuer</h2>
            <span class="section-badge" id="badge-issuer"></span>
            <span class="section-chevron">▾</span>
          </header>
          <div class="section-body" id="inspect-issuer-body"></div>
        </section>

        <div class="inspector-group-header" id="group-nft"><span class="inspector-group-title">NFT Activity</span></div>
        <section class="widget-card inspector-section" id="section-nft">
          <header class="widget-header section-header" tabindex="0" role="button" aria-expanded="true">
            <h2 class="widget-title">🎨 NFT Analysis</h2>
            <span class="section-badge" id="badge-nft"></span>
            <span class="section-chevron">▾</span>
          </header>
          <div class="section-body" id="inspect-nft-body"></div>
        </section>

        <div class="inspector-group-header" id="group-forensic"><span class="inspector-group-title">Forensic Findings</span></div>
        <section class="widget-card inspector-section" id="section-evidence-matrix">
          <header class="widget-header section-header" tabindex="0" role="button" aria-expanded="true">
            <h2 class="widget-title">🗂 Evidence Matrix</h2>
            <span class="section-badge section-badge--neutral" id="badge-evidence-matrix">—</span>
            <span class="section-chevron">▾</span>
          </header>
          <div class="section-body" id="inspect-evidence-matrix-body"></div>
        </section>

        <section class="widget-card inspector-section" id="section-forensic-suite" style="border-color:rgba(0,212,255,.2)">
          <header class="widget-header section-header" style="background:rgba(0,212,255,.03)" tabindex="0" role="button" aria-expanded="true">
            <h2 class="widget-title">🧬 Forensic Analytics Suite</h2>
            <span class="section-badge" id="badge-forensic-suite" style="background:rgba(0,212,255,.12);color:var(--accent);border-color:rgba(0,212,255,.3)">5 Engines</span>
            <span class="section-chevron">▾</span>
          </header>
          <div class="section-body" id="inspect-forensic-suite-body"></div>

          <!-- Engine detail panels — always visible, collapsed by default, expandable -->
          <div class="forensic-engine-tabs" style="border-top:1px solid rgba(0,212,255,.1);margin-top:4px;padding:8px 12px 4px">
            <div style="font-size:.65rem;color:rgba(0,212,255,.5);text-transform:uppercase;letter-spacing:.1em;margin-bottom:8px">
              Individual Engine Details — click any to expand
            </div>

            <div id="section-benfords" class="forensic-sub-section">
              <button id="ftab-btn-benfords" class="forensic-tab-btn" onclick="_toggleForensicTab('benfords')" aria-expanded="false" aria-controls="forensic-tab-benfords" style="width:100%;justify-content:space-between">
                <span>📐 Benford's Law</span>
                <span style="display:flex;align-items:center;gap:8px"><span class="section-badge" id="badge-benfords"></span><span id="ftab-chevron-benfords" style="opacity:.5">▾</span></span>
              </button>
              <div id="forensic-tab-benfords" class="forensic-tab-body" style="display:none"><div id="inspect-benfords-body" style="padding:8px 0"></div></div>
            </div>

            <div id="section-entropy" class="forensic-sub-section" style="margin-top:4px">
              <button id="ftab-btn-entropy" class="forensic-tab-btn" onclick="_toggleForensicTab('entropy')" aria-expanded="false" aria-controls="forensic-tab-entropy" style="width:100%;justify-content:space-between">
                <span>🔀 Shannon's Entropy</span>
                <span style="display:flex;align-items:center;gap:8px"><span class="section-badge" id="badge-entropy"></span><span id="ftab-chevron-entropy" style="opacity:.5">▾</span></span>
              </button>
              <div id="forensic-tab-entropy" class="forensic-tab-body" style="display:none"><div id="inspect-entropy-body" style="padding:8px 0"></div></div>
            </div>

            <div id="section-zipf" class="forensic-sub-section" style="margin-top:4px">
              <button id="ftab-btn-zipf" class="forensic-tab-btn" onclick="_toggleForensicTab('zipf')" aria-expanded="false" aria-controls="forensic-tab-zipf" style="width:100%;justify-content:space-between">
                <span>📈 Zipf's Law</span>
                <span style="display:flex;align-items:center;gap:8px"><span class="section-badge" id="badge-zipf"></span><span id="ftab-chevron-zipf" style="opacity:.5">▾</span></span>
              </button>
              <div id="forensic-tab-zipf" class="forensic-tab-body" style="display:none"><div id="inspect-zipf-body" style="padding:8px 0"></div></div>
            </div>

            <div id="section-timeseries" class="forensic-sub-section" style="margin-top:4px">
              <button id="ftab-btn-timeseries" class="forensic-tab-btn" onclick="_toggleForensicTab('timeseries')" aria-expanded="false" aria-controls="forensic-tab-timeseries" style="width:100%;justify-content:space-between">
                <span>🕐 Time Series Analysis</span>
                <span style="display:flex;align-items:center;gap:8px"><span class="section-badge" id="badge-timeseries"></span><span id="ftab-chevron-timeseries" style="opacity:.5">▾</span></span>
              </button>
              <div id="forensic-tab-timeseries" class="forensic-tab-body" style="display:none"><div id="inspect-timeseries-body" style="padding:8px 0"></div></div>
            </div>

            <div id="section-granger" class="forensic-sub-section" style="margin-top:4px">
              <button id="ftab-btn-granger" class="forensic-tab-btn" onclick="_toggleForensicTab('granger')" aria-expanded="false" aria-controls="forensic-tab-granger" style="width:100%;justify-content:space-between">
                <span>🔗 Offer/Flow Coupling</span>
                <span style="display:flex;align-items:center;gap:8px"><span class="section-badge" id="badge-granger"></span><span id="ftab-chevron-granger" style="opacity:.5">▾</span></span>
              </button>
              <div id="forensic-tab-granger" class="forensic-tab-body" style="display:none"><div id="inspect-granger-body" style="padding:8px 0"></div></div>
            </div>
          </div>
        </section>

        <section class="widget-card inspector-section" id="section-fee-analysis">
          <header class="widget-header section-header" tabindex="0" role="button" aria-expanded="true">
            <h2 class="widget-title">💸 Fee Spike Analysis</h2>
            <span class="section-badge" id="badge-fee-analysis"></span>
            <span class="section-chevron">▾</span>
          </header>
          <div class="section-body" id="inspect-fee-analysis-body">
            <p class="widget-help" style="opacity:.55;font-size:.84rem">
              Detects transactions where fees were paid at 100× or more above the base rate.
              Bots overpay fees to guarantee same-ledger execution alongside a counterparty —
              a coordination technique used in wash trading and front-running.
            </p>
          </div>
        </section>

        <section class="widget-card inspector-section" id="section-memos" style="display:none">
          <header class="widget-header section-header" tabindex="0" role="button" aria-expanded="true">
            <h2 class="widget-title">📝 Memo Analysis</h2>
            <span class="section-badge" id="badge-memos"></span>
            <span class="section-chevron">▾</span>
          </header>
          <div class="section-body" id="inspect-memos-body">
            <p class="widget-help" style="opacity:.55;font-size:.84rem">
              Scans all memo fields for scam patterns, repeated coordination text, and hex-encoded data.
              Memos are a vector for social engineering — attackers embed instructions inside payments.
            </p>
          </div>
        </section>

        <div class="inspector-group-header" id="group-advanced"><span class="inspector-group-title">Advanced / Raw Ledger Data</span></div>
        <section class="widget-card inspector-section" id="section-escrow-depth" style="display:none">
          <header class="widget-header section-header" tabindex="0" role="button" aria-expanded="true">
            <h2 class="widget-title">🔒 Escrow Depth</h2>
            <span class="section-badge" id="badge-escrow-depth"></span>
            <span class="section-chevron">▾</span>
          </header>
          <div class="section-body" id="inspect-escrow-depth-body">
            <p class="widget-help" style="opacity:.55;font-size:.84rem">
              Identifies third-party escrows (created by external accounts), maturity dates,
              and conditional escrows. Third-party escrows can lock funds with conditions the wallet owner didn't set.
            </p>
          </div>
        </section>

        <section class="widget-card inspector-section" id="section-checks" style="display:none">
          <header class="widget-header section-header" tabindex="0" role="button" aria-expanded="true">
            <h2 class="widget-title">🧾 Open Checks</h2>
            <span class="section-badge" id="badge-checks"></span>
            <span class="section-chevron">▾</span>
          </header>
          <div class="section-body" id="inspect-checks-body">
            <p class="widget-help" style="opacity:.55;font-size:.84rem">
              XRPL Checks are deferred payments — like a paper check, the recipient can cash them at any time.
              Open checks represent future outflow commitments. Expired checks waste reserve slots.
            </p>
          </div>
        </section>

        <section class="widget-card inspector-section report-card" id="section-report">
          <header class="widget-header section-header" tabindex="0" role="button" aria-expanded="true">
            <h2 class="widget-title">📄 Full Investigation Report</h2>
            <span class="section-badge section-badge--neutral" id="badge-report">Auto-generated</span>
            <button class="report-export-btn" id="report-export-btn" onclick="exportInspectorReport()" title="Copy report to clipboard">📋 Copy</button>
            <button class="report-export-btn" onclick="printInspectorReport()" title="Print or save as PDF" style="margin-left:4px">🖨 Print / PDF</button>
            <button class="report-export-btn" onclick="shareInspectionLink()" title="Copy a link that reopens this exact inspection" style="margin-left:4px">🔗 Share Link</button>
            <button class="report-export-btn" onclick="exportInspectorReportCSV()" title="Export every finding as a CSV file" style="margin-left:4px">⬇ Export CSV</button>
            <span class="section-chevron">▾</span>
          </header>
          <div class="section-body" id="inspect-report-body">
            <p class="widget-help" style="opacity:.55;font-size:.84rem">
              A plain-English summary of every finding, recommended actions, and a full data snapshot.
              Generates automatically after each inspection.
            </p>
          </div>
        </section>

      </div>
    </div>
  `;
}

/* ═══════════════════════════════════════════════════
   INVESTIGATION NAVIGATOR — Phase 2 (Inspector 6.1)
   Single source of truth for the global nav's grouping — the nav markup,
   click-to-jump targets, active-section highlighting, status-dot
   aggregation, and scrollspy order are ALL derived from these two lists,
   so they can never drift out of sync with each other again (this file
   already fixed that exact drift once before, when 'fundflow' was merged
   into 'drain' but the scrollspy array wasn't updated to match).
   Each workspace/tool's sections[0] is its click-to-jump target; the rest
   are members that light the SAME nav button up (via the reverse lookup
   below) when scrolled into view, and contribute to its aggregated
   status dot — consolidating the prior 30 individual jump-targets down
   to 11 top-level buttons (7 workspaces + 4 tools).
═══════════════════════════════════════════════════ */
const INSPECTOR_WORKSPACES = [
  { key: 'overview',    label: 'Overview',    icon: '📊', sections: ['overview', 'events'] },
  { key: 'flow',        label: 'Flow',        icon: '🌊', sections: ['drain', 'flowmotifs', 'inbound'] },
  { key: 'connections', label: 'Connections', icon: '🕸', sections: ['issuer-connections', 'dist-market-flow', 'desttag'] },
  { key: 'market',      label: 'Market',      icon: '📊', sections: ['wash', 'volconc', 'livebook'] },
  { key: 'assets',      label: 'Assets',      icon: '💰', sections: ['trustlines', 'amm', 'issuer', 'nft'] },
  { key: 'security',    label: 'Security',    icon: '🔐', sections: ['security'] },
  { key: 'forensics',   label: 'Forensics',   icon: '🧬', sections: ['forensic-suite', 'benfords', 'entropy', 'zipf', 'timeseries', 'granger', 'fee-analysis', 'memos', 'pathdepth'] },
];
// "Raw Ledger" maps to Escrow Depth + Open Checks — the closest existing
// raw-ledger-object content — until a dedicated raw-JSON viewer exists;
// an honest best fit for a name the spec asks for, not a fabricated section.
const INSPECTOR_TOOLS = [
  { key: 'transactions', label: 'Transactions', icon: '📜', sections: ['tx'] },
  { key: 'evidence',     label: 'Evidence',     icon: '🗂', sections: ['evidence-matrix'] },
  { key: 'report',       label: 'Report',       icon: '📄', sections: ['report'] },
  { key: 'raw',          label: 'Raw Ledger',   icon: '🔒', sections: ['escrow-depth', 'checks'] },
];
const _sectionToNavKey = new Map();
[...INSPECTOR_WORKSPACES, ...INSPECTOR_TOOLS].forEach(w => w.sections.forEach(s => _sectionToNavKey.set(s, w.key)));

/* ═══════════════════════════════════════════════════
   BOTTOM NAV
═══════════════════════════════════════════════════ */
function _mountInspectorNav() {
  if (document.getElementById('inspector-nav')) return;

  const nav = document.createElement('nav');
  nav.id = 'inspector-nav';
  nav.setAttribute('aria-label', 'Inspector navigation');
  // Phase 2 of the Inspector 6.1 redesign: the global rail now shows 7
  // investigative workspaces + a Tools group (30 individual per-detector
  // buttons consolidated down to 11 total) — see INSPECTOR_WORKSPACES/
  // INSPECTOR_TOOLS below, the single source of truth this markup, the
  // scrollspy order, and the status-dot aggregation are all derived from.
  // Detectors that used to have their own global button (Benford, AMM,
  // Issuer, NFT, etc.) are reached by scrolling within their workspace,
  // same as any other content on the page — not removed, just no longer
  // separate global nav entries, per spec: "Keep the global rail simple."
  // Forensics and Report keep the same special accent classes their old,
  // separate buttons had (cyan glow / teal border) — purely cosmetic
  // continuity, not required for the consolidation itself.
  const ACCENT_CLASS = { forensics: ' in-btn--suite', report: ' in-btn--report' };
  const btnHtml = w => `<button class="in-btn${ACCENT_CLASS[w.key] || ''}" data-jump="${w.sections[0]}" data-jump-key="${w.key}" data-jump-sections="${w.sections.join(',')}"><span class="in-icon">${w.icon}</span><span class="in-label">${w.label}</span></button>`;
  const groupHtml = (label, items) => `
      <div class="nav-group">
        <div class="nav-group-label">${label}</div>
        <div class="nav-group-btns">
          ${items.map(btnHtml).join('')}
        </div>
      </div>`;
  nav.innerHTML = `
    <button type="button" class="nav-collapse-toggle" onclick="toggleInspectorNavCollapse()" aria-label="Collapse navigation" title="Collapse navigation">«</button>
    <div class="inspector-nav-track">
      ${groupHtml('Investigate', INSPECTOR_WORKSPACES)}
      <div class="nav-group-divider"></div>
      ${groupHtml('Tools', INSPECTOR_TOOLS)}
      <div class="nav-group-divider"></div>
      <div class="nav-group">
        <div class="nav-group-btns">
          <button class="in-btn in-btn--guide" onclick="showInspectorHowTo()"><span class="in-icon">?</span><span class="in-label">Guide</span></button>
        </div>
      </div>
    </div>
  `;

  // inspector.css hides .in-label (the visible text) at <=480px so the nav
  // fits on a phone screen, leaving each button as a bare emoji with no
  // accessible name — several icons (e.g. 📊) are reused across multiple
  // unrelated sections, so a screen reader can't even guess from the glyph.
  // aria-label lives on the button itself, not the hidden child span, so it
  // survives that collapse; deriving it from .in-label's own text (rather
  // than hardcoding ~30 near-duplicate strings) keeps the two permanently in
  // sync if a label is ever renamed.
  nav.querySelectorAll('.in-btn').forEach(btn => {
    const label = btn.querySelector('.in-label')?.textContent?.trim();
    if (label) { btn.setAttribute('aria-label', label); btn.title = label; } // title doubles as the collapsed rail's icon-only tooltip
  });

  const panel = document.getElementById('tab-inspector');
  if (panel) panel.appendChild(nav);
  _applyInspectorShellCollapseState();
}

// Collapsible desktop investigation shell (Phase: Relationship Intelligence
// 5.0's "retractable sidebars" — canvas width previously lost to two
// permanently-reserved fixed rails is now reclaimable). Persisted so a
// returning user's preference survives reload, same pattern already used
// elsewhere in this app (theme, reduced-motion, etc.) — see motion.js.
function _applyInspectorShellCollapseState() {
  const navCollapsed = localStorage.getItem('nalulf_nav_collapsed') === '1';
  const intelCollapsed = localStorage.getItem('nalulf_intel_collapsed') === '1';
  document.body.classList.toggle('nav-collapsed', navCollapsed);
  document.body.classList.toggle('intel-collapsed', intelCollapsed);
  const navToggle = document.querySelector('.nav-collapse-toggle');
  if (navToggle) { navToggle.textContent = navCollapsed ? '»' : '«'; navToggle.title = navCollapsed ? 'Expand navigation' : 'Collapse navigation'; }
}
window.toggleInspectorNavCollapse = function() {
  const collapsed = !document.body.classList.contains('nav-collapsed');
  localStorage.setItem('nalulf_nav_collapsed', collapsed ? '1' : '0');
  _applyInspectorShellCollapseState();
};
window.toggleIntelPanelCollapse = function() {
  const collapsed = !document.body.classList.contains('intel-collapsed');
  localStorage.setItem('nalulf_intel_collapsed', collapsed ? '1' : '0');
  _applyInspectorShellCollapseState();
};

/* ═══════════════════════════════════════════════════
   INTELLIGENCE PANEL (Phase 1: Investigation Shell)
   Desktop-only persistent right rail. Deliberately minimal for now — it
   has nothing to react to until the shared-selection-state interaction
   model (a later phase) exists, so it honestly shows coverage (mirrored
   from the Data Quality strip's already-computed values, never
   recomputed) and says what will land here next, rather than faking
   interactivity it doesn't have yet. Hidden on mobile/tablet entirely
   (see inspector.css) — same show/hide lifecycle as #inspector-nav.
═══════════════════════════════════════════════════ */
function _mountInspectorIntelPanel() {
  if (document.getElementById('inspector-intel-panel')) return;

  const panel = document.createElement('aside');
  panel.id = 'inspector-intel-panel';
  panel.setAttribute('aria-label', 'Intelligence panel');
  panel.innerHTML = `
    <button type="button" class="intel-collapse-toggle" onclick="toggleIntelPanelCollapse()" aria-label="Collapse Intelligence panel" title="Collapse Intelligence panel">»</button>
    <div class="intel-panel-content">
      <div class="intel-panel-label">Intelligence Panel</div>
      <div class="intel-panel-placeholder">Context, evidence, and counterevidence for whatever you select will appear here in a later phase.</div>
      <div class="intel-panel-divider"></div>
      <div class="intel-panel-label">Coverage</div>
      <div class="intel-coverage-row"><span class="intel-coverage-label">History</span><span class="intel-coverage-val" id="intel-coverage-history">—</span></div>
      <div class="intel-coverage-row"><span class="intel-coverage-label">Analysis</span><span class="intel-coverage-val mono" id="intel-coverage-version">—</span></div>
    </div>
    <button type="button" class="intel-collapsed-tab" onclick="toggleIntelPanelCollapse()" aria-label="Expand Intelligence panel" title="Expand Intelligence panel">INTELLIGENCE</button>
  `;

  const host = document.getElementById('tab-inspector');
  if (host) host.appendChild(panel);
  _applyInspectorShellCollapseState();
}

/* ═══════════════════════════════════════════════════
   HOW-TO OVERLAY
═══════════════════════════════════════════════════ */
function _mountHowToOverlay() {
  if (document.getElementById('inspector-howto')) return;

  const overlay = document.createElement('div');
  overlay.id = 'inspector-howto';
  overlay.className = 'howto-overlay';
  overlay.style.display = 'none';
  overlay.innerHTML = `
    <div class="howto-modal">
      <button class="howto-close" onclick="hideInspectorHowTo()" aria-label="Close guide">✕</button>

      <div class="howto-head">
        <div class="howto-head-icon">🔍</div>
        <h2 class="howto-title">Inspector Guide</h2>
        <p class="howto-subtitle">What each section tells you and what to watch for</p>
      </div>

      <div class="howto-items">

        <div class="howto-item">
          <div class="howto-item-icon">🔐</div>
          <div class="howto-item-body">
            <div class="howto-item-title">Security Audit</div>
            <div class="howto-item-desc">Decodes every account flag, checks master key status, regular key age, and multisig signer lists.
              <strong class="howto-red">Red flag:</strong> master key disabled with no regular key and no signer list = funds permanently inaccessible.</div>
          </div>
        </div>

        <div class="howto-item howto-item--warn">
          <div class="howto-item-icon">⚠</div>
          <div class="howto-item-body">
            <div class="howto-item-title">Drain Risk</div>
            <div class="howto-item-desc">Detects classic wallet-drain patterns. A drained account typically has master key disabled and a new regular key set by the attacker.
              We also detect large outflows within 48h of an auth change, open payment channels, and external key injections (a 3rd party setting your key).</div>
          </div>
        </div>

        <div class="howto-item">
          <div class="howto-item-icon">🎨</div>
          <div class="howto-item-body">
            <div class="howto-item-title">NFT Analysis</div>
            <div class="howto-item-desc">Catches the most common NFT scam: creating a sell offer for 0 XRP or ≤1 XRP — the victim thinks they're signing something else but listed their NFT for free.
              Also flags NFTs with no metadata URI (common in fake-offer scams) and unexpected burns.</div>
          </div>
        </div>

        <div class="howto-item">
          <div class="howto-item-icon">📊</div>
          <div class="howto-item-body">
            <div class="howto-item-title">Wash Trading</div>
            <div class="howto-item-desc">Scores 0–100 across five signals: cancel ratio &gt;55%, round-trip counterparties, single-pair concentration &gt;70%, fill rate &lt;5%, and 8+ offers in 30 seconds.
              Score above 50 warrants review — market makers may score moderately without manipulation intent.</div>
          </div>
        </div>

        <div class="howto-item">
          <div class="howto-item-icon">🪙</div>
          <div class="howto-item-body">
            <div class="howto-item-title">Token Issuer</div>
            <div class="howto-item-desc">Shows outstanding token obligations (negative balances = tokens issued). Checks individual line freezes, global freeze, and the NoFreeze flag —
              the most important trust signal for token holders since it permanently prevents issuer freeze actions.</div>
          </div>
        </div>

        <div class="howto-item">
          <div class="howto-item-icon">💧</div>
          <div class="howto-item-body">
            <div class="howto-item-title">AMM / Liquidity</div>
            <div class="howto-item-desc">Detects LP token positions (03… currency prefix), deposit/withdrawal history, fee votes, and auction slot bids.
              Large positions carry impermanent loss risk when pool asset prices diverge.</div>
          </div>
        </div>

        <div class="howto-item">
          <div class="howto-item-icon">🔗</div>
          <div class="howto-item-body">
            <div class="howto-item-title">Trustlines</div>
            <div class="howto-item-desc"><span class="howto-red">Frozen by issuer</span> = you cannot transfer that token.
              NoRipple is normal and protective. Negative balance = this account owes that amount to the counterparty.
              Limit=0 with negative balance is common for DEX issuers.</div>
          </div>
        </div>

        <div class="howto-item">
          <div class="howto-item-icon">📜</div>
          <div class="howto-item-body">
            <div class="howto-item-title">Transaction History</div>
            <div class="howto-item-desc">Up to 5,000 transactions fetched via deep sequential pagination (configurable via <code>window._inspectMaxTx</code>) — color-coded by risk.
              <span class="howto-amber">Amber border</span> = auth-changing tx (key changes, signer lists).
              <span class="howto-red">Red border</span> = high risk (free NFT offers). Faded = failed tx.
              Click the 🔗 or 🔍 icon on any row to open it on XRPL Livenet or XRPScan.</div>
          </div>
        </div>

        <div class="howto-item">
          <div class="howto-item-icon">💸</div>
          <div class="howto-item-body">
            <div class="howto-item-title">Fee Spike Analysis</div>
            <div class="howto-item-desc">Bots often pay 100–500× the normal fee to guarantee their transaction lands in the same ledger as a counterparty's.
              Organic users almost never pay more than 2–5×.
              This section flags bursts of elevated fees and links the specific transaction hashes.</div>
          </div>
        </div>

        <div class="howto-item">
          <div class="howto-item-icon">🏷</div>
          <div class="howto-item-body">
            <div class="howto-item-title">Destination Tag Patterns</div>
            <div class="howto-item-desc">Exchanges use destination tags to identify which customer account receives a deposit — like a bank reference number.
              One tag used repeatedly = the same person's exchange account. Many different tags to one exchange = a service routing to multiple customer accounts, or deliberate deposit spreading.</div>
          </div>
        </div>

        <div class="howto-item">
          <div class="howto-item-icon">🔄</div>
          <div class="howto-item-body">
            <div class="howto-item-title">Path Payment Depth</div>
            <div class="howto-item-desc">Path payments route through intermediate DEX pairs.
              <strong class="howto-red">XRP→IOU→XRP round-trips</strong> pay and receive XRP via token pairs — generating DEX volume with no economic transfer.
              <strong class="howto-red">Self-routing</strong> (destination = source) is pure wash volume.
              Deep hop chains (3+ intermediaries) can obscure fund origin.</div>
          </div>
        </div>

        <div class="howto-item">
          <div class="howto-item-icon">🕸</div>
          <div class="howto-item-body">
            <div class="howto-item-title">Issuer Connection Graph</div>
            <div class="howto-item-desc">Shows token supply distribution across holders, accounts the issuer funded/created, and mirror-wallet clusters —
              groups of wallets that all received nearly identical token amounts. Mirror clusters often indicate sybil rings or insider pre-allocations.
              <strong>Note:</strong> supply percentages are only reliable when gateway_balances data is available; otherwise a "visible sample" caveat is shown.</div>
          </div>
        </div>

        <div class="howto-tip">
          <span class="howto-tip-icon">💡</span>
          <span><strong>Pro tips:</strong> Connect your wallet in Profile to auto-populate your address here.
            Click any address in the live stream to inspect it instantly.
            Paste an address — inspection runs automatically.
            Use the ⬇ Export CSV button in the report to take transaction data into Excel or Python.</span>
        </div>

      </div>
    </div>
  `;

  overlay.addEventListener('click', e => { if (e.target === overlay) _hideHowTo(); });
  document.addEventListener('keydown', e => {
    if (e.key === 'Escape' && overlay.style.display !== 'none') _hideHowTo();
  });
  document.body.appendChild(overlay);
}

/* ═══════════════════════════════════════════════════
   NAV + BADGE + UX HELPERS
═══════════════════════════════════════════════════ */
function _navSetActive(key) {
  $$('#inspector-nav .in-btn[data-jump-key]').forEach(b =>
    b.classList.toggle('in-btn--active', b.dataset.jumpKey === key)
  );
}

// NOT derived from INSPECTOR_WORKSPACES/INSPECTOR_TOOLS — those group by
// WORKSPACE THEME (e.g. Assets = trustlines+amm+issuer+nft, which are
// scattered across different physical positions on the page), but this
// algorithm picks the LAST entry whose top has scrolled above the
// threshold, which only identifies the true topmost visible section if
// the list order matches the page's actual top-to-bottom DOM order. A
// first attempt here derived this list from the workspace grouping and
// broke exactly that — confirmed live: scrolling to 'drain' (an early
// section) incorrectly activated 'security' (also early, but evaluated
// later in the theme-grouped array, so its already-scrolled-past
// negative top wrongly "won" as the last match). This list must always
// match _mountInspectorHTML's real section order — now includes 6 ids
// ('dist-market-flow', 'benfords', 'entropy', 'zipf', 'timeseries',
// 'granger') a prior version of this list was missing entirely.
const INSPECTOR_SECTION_SCROLL_ORDER = [
  'overview', 'events', 'security', 'drain', 'flowmotifs', 'inbound', 'trustlines',
  'tx', 'pathdepth', 'issuer-connections', 'dist-market-flow', 'desttag',
  'wash', 'volconc', 'livebook', 'amm', 'issuer', 'nft',
  'evidence-matrix', 'forensic-suite', 'benfords', 'entropy', 'zipf', 'timeseries', 'granger', 'fee-analysis', 'memos',
  'escrow-depth', 'checks', 'report',
];
function _navOnScroll() {
  // Skip if inspector tab not active or results not showing
  if (!document.body.classList.contains('inspector')) return;
  if ($('inspect-result')?.style.display === 'none') return;
  let activeSection = null;
  for (const id of INSPECTOR_SECTION_SCROLL_ORDER) {
    const el = document.getElementById('section-' + id);
    // offsetParent is null for display:none elements (several advanced-only
    // sections like #section-checks stay display:none when there's nothing
    // to show) — without this guard, a hidden element's all-zero
    // getBoundingClientRect() (top: 0) always satisfies "<= 150" and, being
    // last in this array, permanently wins over whichever section is
    // actually scrolled into view.
    if (el && el.offsetParent !== null && el.getBoundingClientRect().top <= 150) activeSection = id;
  }
  const key = activeSection && _sectionToNavKey.get(activeSection);
  if (key) _navSetActive(key);
}

function _setBadge(id, findings) {
  const el = $(id);
  if (!el) return;
  const crits = findings.filter(f => f.sev === 'critical').length;
  const warns  = findings.filter(f => f.sev === 'warn').length;
  if (crits)  { el.textContent = crits + ' critical'; el.className = 'section-badge section-badge--crit'; }
  else if (warns) { el.textContent = warns + ' warn'; el.className = 'section-badge section-badge--warn'; }
  else        { el.textContent = 'OK';                el.className = 'section-badge section-badge--ok';   }
}

function _setBadgeDrainLevel(id, level) {
  const el = $(id);
  if (!el) return;
  const map = { low:'ok', medium:'warn', high:'warn', critical:'crit' };
  el.textContent = level;
  el.className = 'section-badge section-badge--' + (map[level] || 'ok');
}

/* Forensic engine tab toggle */
window._toggleForensicTab = function(name) {
  const body = document.getElementById('forensic-tab-' + name);
  if (!body) return;
  const isOpen = body.style.display !== 'none';
  body.style.display = isOpen ? 'none' : '';
  // Update chevron
  const chev = document.getElementById('ftab-chevron-' + name);
  if (chev) chev.textContent = isOpen ? '▾' : '▴';
  document.getElementById('ftab-btn-' + name)?.setAttribute('aria-expanded', String(!isOpen));
  // Auto-expand: if opening and content is empty (not yet rendered), show a note
  if (!isOpen && body.querySelector('[id^="inspect-"]')?.innerHTML === '') {
    body.querySelector('[id^="inspect-"]').innerHTML = "<div style=\"opacity:.45;font-size:.8rem;padding:8px 0\">Run an inspection first.</div>";
  }
};

function _copyAddr() {
  const badge = $('inspect-addr-badge');
  const addr  = badge?.dataset?.fullAddr || badge?.textContent;
  if (!addr || addr === '—') return;
  navigator.clipboard?.writeText(addr).then(() => {
    const btn = document.querySelector('.irb-copy-btn');
    if (btn) { btn.textContent = '✓'; setTimeout(() => (btn.textContent = '📋'), 1500); }
  });
}

window.inspectorGoBack = function() {
  const resEl   = $('inspect-result');
  const emptyEl = $('inspect-empty');
  const errEl   = $('inspect-err');
  const inp     = $('inspect-addr');
  const navEl   = $('inspector-nav');
  const intelEl = $('inspector-intel-panel');
  if (resEl)   resEl.style.display   = 'none';
  if (errEl)   errEl.style.display   = 'none';
  if (emptyEl) emptyEl.style.display = '';
  if (navEl)   navEl.style.display   = 'none';
  if (intelEl) intelEl.style.display = 'none';
  if (inp)     inp.value = '';
  _loadWallets();
  _loadRecentHistory();
  window.scrollTo({ top: 0, behavior: 'smooth' });
  setTimeout(() => inp?.focus(), 300);
};

function _showHowTo() {
  const el = document.getElementById('inspector-howto');
  if (el) { el.style.display = ''; requestAnimationFrame(() => el.classList.add('howto-visible')); }
}

function _hideHowTo() {
  const el = document.getElementById('inspector-howto');
  if (!el) return;
  el.classList.remove('howto-visible');
  setTimeout(() => { if (!el.classList.contains('howto-visible')) el.style.display = 'none'; }, 260);
}

/* ═══════════════════════════════════════════════════
   INITIAL STATE DASHBOARD
═══════════════════════════════════════════════════ */

const LS_INSPECT_HISTORY = 'nalulf_inspect_history';
const LS_WALLETS         = 'nalulf_wallets';
// Watchlist storage now lives in shared-analysis.js (unified with profile.js's
// token watchlist) — see _getWatchlist/_addToWatchlist/etc. below.
const LS_ANALYST_MODE    = 'nalulf_analyst_mode';
const LS_FINDINGS_SNAP   = 'nalulf_findings_snap'; // per-address finding fingerprints
// "Risk score trend" (roadmap: how has this address changed over
// inspections) — distinct from LS_INSPECT_HISTORY above, which keeps only
// ONE entry per address (overwritten on every re-inspection, used for the
