window.inspectorLoadAddr = function(addr) {
  const inp = $('inspect-addr');
  if (inp) inp.value = addr;
  runInspect();
};

// window.inspectWalletAddr is defined once, in profile.js (exported and
// wired via main.js) — it used to be redefined here too, under the same
// global name, with its own independently-drifted copy of the same
// dashboard/tab/load ordering. Two definitions of one global meant
// whichever module's top-level code happened to evaluate last silently won,
// and a fix to one wouldn't apply to the other — exactly the kind of
// duplicate-implementation drift this codebase should avoid.

// "Share inspection as link" — a URL fragment, not a query param (this app
// already uses the query string for DEX chart view state) and never sent to
// any server, matching the roadmap item's own "no server needed." Consumed
// by main.js's boot sequence (_extractSharedInspectAddrFromHash /
// _applyPendingSharedInspect), which waits for both a real session and a
// real XRPL connection before auto-opening it.
window.shareInspectionLink = function() {
  const addr = window._lastInspectResult?.addr;
  if (!addr) return;
  const url = `${location.origin}${location.pathname}#inspect=${encodeURIComponent(addr)}`;
  copyToClipboard(url);
};

// "Export analytics + inspection data as CSV" — one row per finding across
// every module (Security/Market Integrity/Counterparty/Issuer/Liquidity/
// Automation/External Exposure), matching profile.js's exportTxCSV's own
// data-URI-download technique exactly, so this app has one consistent way
// of exporting a CSV rather than two different ones.
window.exportInspectorReportCSV = function() {
  const findings = window._lastAllFindings || [];
  const addr = window._lastInspectResult?.addr;
  if (!findings.length) { toastWarn('No findings to export — run an inspection first.'); return; }
  const esc = v => `"${String(v ?? '').replace(/"/g, '""')}"`;
  const rows = [
    ['Module', 'Category', 'Severity', 'Confidence', 'Headline', 'Detail'],
    ...findings.map(f => [f.module || '', f.category || '', f.sev || '', f.confidence != null ? f.confidence : '', f.headline || f.label || '', f.detail || '']),
  ];
  const csv = rows.map(r => r.map(esc).join(',')).join('\n');
  const a = document.createElement('a');
  a.href = 'data:text/csv;charset=utf-8,' + encodeURIComponent(csv);
  a.download = `nalulf-findings-${(addr || 'inspection').slice(0, 12)}-${new Date().toISOString().slice(0, 10)}.csv`;
  a.click();
};

window.printInspectorReport = function() {
  const body = document.getElementById('inspect-report-body');
  if (!body) return;
  const addr = document.getElementById('inspect-addr-badge')?.dataset?.fullAddr || 'wallet';
  const w = window.open('', '_blank', 'width=900,height=700');
  w.document.write(`<!DOCTYPE html><html><head>
    <title>NaluXRP Report — ${addr}</title>
    <style>
      body { font-family: -apple-system, system-ui, sans-serif; background:#fff; color:#111; margin:40px; line-height:1.6; }
      .report-cover { display:flex; justify-content:space-between; align-items:flex-start; border-bottom:2px solid #111; padding-bottom:20px; margin-bottom:24px; }
      .report-section { margin-bottom:28px; }
      .report-section-h { font-size:1.05rem; font-weight:800; border-bottom:1px solid #ddd; padding-bottom:6px; margin-bottom:12px; }
      .report-stat-row { display:flex; gap:12px; padding:4px 0; border-bottom:1px solid #f0f0f0; font-size:.88rem; }
      .report-stat-k { color:#555; min-width:220px; flex-shrink:0; }
      .report-finding-row { margin-bottom:10px; padding:8px; border-left:3px solid #ddd; }
      .report-module-h { font-weight:700; font-size:.9rem; margin:16px 0 6px; color:#333; }
      .report-rec { display:flex; gap:10px; margin-bottom:8px; font-size:.88rem; }
      @media print { body { margin:20px; } button { display:none; } }
    </style>
  </head><body>
    <button onclick="window.print()" style="margin-bottom:20px;padding:8px 16px;cursor:pointer">🖨 Print / Save as PDF</button>
    ${body.innerHTML}
  </body></html>`);
  w.document.close();
};

window.exportInspectorReport = function() {
  const body = document.getElementById('inspect-report-body');
  if (!body) return;
  // Copy as plain text
  const text = body.innerText || body.textContent || '';
  navigator.clipboard?.writeText(text).then(() => {
    const btn = document.getElementById('report-export-btn');
    if (btn) { btn.textContent = '✓ Copied!'; setTimeout(() => { btn.textContent = '📋 Copy Report'; }, 2000); }
  }).catch(() => {
    // Fallback: select all text in the section
    const range = document.createRange();
    range.selectNodeContents(body);
    const sel = window.getSelection();
    sel.removeAllRanges();
    sel.addRange(range);
  });
};

window.inspectorClearHistory = function() {
  safeRemove(LS_INSPECT_HISTORY);
  const section = document.getElementById('isd-recent-section');
  if (section) section.style.display = 'none';
};
window.inspectorClearWatchlist = function() {
  _sharedClearWatchlist('address');
  _renderWatchlistSection();
};

/* ─────────────────────────────
   History helpers
──────────────────────────────── */
function _getHistory() {
  return safeJson(safeGet(LS_INSPECT_HISTORY)) || [];
}

function addInspectHistory(addr, riskScore, findings = []) {
  let history = _getHistory();
  history = history.filter(h => h.addr !== addr);
  // Store a fingerprint of critical+warn findings for change detection
  const fingerprint = findings
    .filter(f => f.sev === 'critical' || f.sev === 'warn')
    .map(f => f.module + ':' + f.headline.slice(0, 40))
    .sort().join('|');
  history.unshift({ addr, riskScore, ts: Date.now(), fingerprint });
  history = history.slice(0, 12);
  safeSet(LS_INSPECT_HISTORY, JSON.stringify(history));
}

// Risk score trend — every score this address has ever gotten, not just the
// latest. Inspections are user-initiated and infrequent (unlike the
// balance-history auto-polling elsewhere in this app), so no throttling —
// one real entry per completed inspection, capped at 30.
function _recordRiskScoreTrend(addr, score) {
  if (score == null || isNaN(score)) return;
  const key = LS_RISK_TREND_PFX + addr;
  const hist = safeJson(safeGet(key)) || [];
  hist.push({ score, ts: Date.now() });
  if (hist.length > 30) hist.splice(0, hist.length - 30);
  safeSet(key, JSON.stringify(hist));
}
function _getRiskScoreTrendHistory(addr) { return safeJson(safeGet(LS_RISK_TREND_PFX + addr)) || []; }

function _getRiskTrendRange() { return safeGet(LS_RISK_TREND_RANGE) || 'all'; }
function setRiskTrendRange(addr, key) {
  if (!CHART_RANGES.some(r => r.key === key)) return;
  safeSet(LS_RISK_TREND_RANGE, key);
  _renderRiskScoreTrendChart(addr);
}
window.setRiskTrendRange = setRiskTrendRange;

function _filterTrendByRange(hist, rangeKey) {
  const range = CHART_RANGES.find(r => r.key === rangeKey);
  if (!range || range.days == null) return hist;
  const cutoff = Date.now() - range.days * 86400000;
  return hist.filter(h => h.ts >= cutoff);
}

function _buildTrendRangePicker(addr, activeKey) {
  return `<div class="chart-range-picker" role="group" aria-label="Trend time range">
    ${CHART_RANGES.map(r => `<button type="button" class="chart-range-btn${r.key===activeKey?' chart-range-btn--active':''}" onclick="setRiskTrendRange('${escHtml(addr)}','${r.key}')" aria-pressed="${r.key===activeKey}">${r.label}</button>`).join('')}
  </div>`;
}

function _renderRiskScoreTrendChart(addr) {
  const el = document.getElementById('inspect-risk-trend');
  if (!el) return;
  const fullHist = _getRiskScoreTrendHistory(addr);
  const activeRange = _getRiskTrendRange();
  const hist = _filterTrendByRange(fullHist, activeRange);
  if (hist.length < 2) {
    const picker = fullHist.length >= 2 ? _buildTrendRangePicker(addr, activeRange) : '';
    const msg = fullHist.length >= 2
      ? `Only ${hist.length} inspection${hist.length === 1 ? '' : 's'} in this range — widen the range or keep inspecting to build up the trend.`
      : `Risk score trend builds up as this address is inspected over time — ${fullHist.length} inspection${fullHist.length === 1 ? '' : 's'} recorded so far.`;
    el.innerHTML = `${picker}<div style="font-size:.72rem;color:rgba(255,255,255,.3);padding:6px 0">${msg}</div>`;
    return;
  }
  const W = 560, H = 100, pL = 28, pR = 12, pT = 10, pB = 20;
  const tms = hist.map(h => h.ts), scores = hist.map(h => h.score);
  const tMn = tms[0], tMx = tms[tms.length - 1], tRange = tMx - tMn || 1;
  const toX = ts => pL + ((ts - tMn) / tRange) * (W - pL - pR);
  // Fixed 0-100 scale, not the series' own min/max — a risk score's meaning
  // is anchored to its absolute scale (0=clean, 100=critical), so letting
  // the axis auto-scale to a narrow observed range would visually
  // exaggerate small, possibly-meaningless fluctuations.
  const toY = s => pT + (1 - s / 100) * (H - pT - pB);
  const pts = hist.map(h => `${toX(h.ts).toFixed(1)},${toY(h.score).toFixed(1)}`);
  const delta = scores[scores.length - 1] - scores[0];
  // Rising risk score = worse = red; falling = better = green — the
  // opposite color convention from a typical "up is good" finance chart,
  // deliberately, since this is a risk metric, not a value metric.
  const trendColor = delta > 0 ? '#ff5555' : delta < 0 ? '#50fa7b' : 'rgba(255,255,255,.5)';
  const xTicks = [0, .5, 1].map(f => ({ x: pL + f * (W - pL - pR), l: new Date(tMn + f * tRange).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) }));
  el.innerHTML = `
    ${_buildTrendRangePicker(addr, activeRange)}
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px;font-size:.72rem;color:rgba(255,255,255,.5);flex-wrap:wrap;gap:6px">
      <span style="text-transform:uppercase;letter-spacing:.05em;opacity:.6">Risk Score Trend</span>
      <span style="color:${trendColor};font-weight:700">${delta > 0 ? '▲' : delta < 0 ? '▼' : '—'} ${Math.abs(delta)} pt${Math.abs(delta) === 1 ? '' : 's'} since first inspection</span>
      <span style="opacity:.4">${hist.length} of ${fullHist.length} inspections</span>
    </div>
    <svg viewBox="0 0 ${W} ${H}" style="width:100%;height:${H}px;display:block">
      <defs>
        <linearGradient id="riskTrendFill-${escHtml(addr)}" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stop-color="${trendColor}" stop-opacity=".22"/>
          <stop offset="100%" stop-color="${trendColor}" stop-opacity="0"/>
        </linearGradient>
      </defs>
      <line x1="${pL}" y1="${toY(20).toFixed(1)}" x2="${W - pR}" y2="${toY(20).toFixed(1)}" stroke="rgba(80,250,123,.15)" stroke-width="1"/>
      <line x1="${pL}" y1="${toY(70).toFixed(1)}" x2="${W - pR}" y2="${toY(70).toFixed(1)}" stroke="rgba(255,85,85,.15)" stroke-width="1"/>
      <polygon points="${pts[0]} ${pts.join(' ')} ${toX(tMx).toFixed(1)},${(H - pB).toFixed(1)} ${toX(tMn).toFixed(1)},${(H - pB).toFixed(1)}" fill="url(#riskTrendFill-${escHtml(addr)})"/>
      <polyline points="${pts.join(' ')}" fill="none" stroke="${trendColor}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
      ${hist.map(h => `<circle cx="${toX(h.ts).toFixed(1)}" cy="${toY(h.score).toFixed(1)}" r="3" fill="#0a0e16" stroke="${trendColor}" stroke-width="2"><title>${new Date(h.ts).toLocaleString()}: ${h.score}/100</title></circle>`).join('')}
      ${xTicks.map(t => `<text x="${t.x.toFixed(1)}" y="${H - 4}" text-anchor="middle" fill="rgba(255,255,255,.32)" font-size="9" font-family="JetBrains Mono,monospace">${t.l}</text>`).join('')}
    </svg>`;
}

/* ── Watchlist helpers ─────────────────────────────
   Thin address-flavored wrappers over the unified store in shared-analysis.js
   (now shared with profile.js's token watchlist). Preserve the exact old
   {addr,label,addedTs,lastScore,lastTs} shape so every consumer below
   (_renderWatchlistSection, _renderWatchBtn, etc.) needed zero changes. */
function _getWatchlist() {
  return _sharedGetWatchlist('address').map(w => ({ addr: w.key, label: w.label, addedTs: w.addedAt, lastScore: w.lastScore, lastTs: w.lastTs }));
}
function _addToWatchlist(addr, label) {
  _sharedAddToWatchlist('address', addr, { label: label || shortAddr(addr) });
}
function _removeFromWatchlist(addr) {
  _sharedRemoveFromWatchlist('address', addr);
}
function _isWatched(addr) { return _getWatchlist().some(w => w.addr === addr); }
function _updateWatchlistEntry(addr, score) {
  _sharedUpdateWatchlistEntry('address', addr, { lastScore: score, lastTs: Date.now() });
}

function _relativeTime(ts) {
  const diff = Date.now() - ts;
  if (diff < 60000)    return 'just now';
  if (diff < 3600000)  return Math.floor(diff / 60000) + 'm ago';
  if (diff < 86400000) return Math.floor(diff / 3600000) + 'h ago';
  return Math.floor(diff / 86400000) + 'd ago';
}

function _riskBucket(score) {
  // Maps to isd-risk-pill--ok/medium/high/critical suffix
  const c = riskScoreClass(score); // 'risk-ok' | 'risk-medium' | 'risk-high' | 'risk-critical'
  return c.replace('risk-', '');   // 'ok' | 'medium' | 'high' | 'critical'
}


/* ═══════════════════════════════════════════════════
   DEPTH MODE (Simple / Explain / Analyst)
   Simple  = plain-language findings only — what happened, what matters.
   Explain = adds why Nalu noticed it, supporting/counter evidence,
             alternative explanations, classification — the existing
             .advanced-only content, unchanged from before this 3-tier
             split existed.
   Analyst = adds raw metrics — confidence %, transaction hash chips, and
             other "raw" content gated behind .analyst-only-block/-inline.
   toggleAnalystMode() is kept as a straight simple<->analyst flip (skipping
   the middle tier) for backward compatibility — many existing tests call
   it expecting exactly that binary jump. setDepthMode() is the real 3-way
   control the UI toggle itself uses.
═══════════════════════════════════════════════════ */
const DEPTH_MODES = ['simple', 'explain', 'analyst'];
let _depthMode = 'simple';

function _initAnalystMode() {
  const stored = localStorage.getItem(LS_ANALYST_MODE);
  // 'true'/'false' are the pre-3-tier values this key used to hold —
  // migrated to the nearest equivalent rather than silently reset.
  _depthMode = stored === 'true' ? 'analyst' : DEPTH_MODES.includes(stored) ? stored : 'simple';
  _applyAnalystMode();
}

function _applyAnalystMode() {
  const el = document.getElementById('inspect-result');
  if (!el) return;
  el.classList.toggle('mode-simple', _depthMode === 'simple');
  el.classList.toggle('mode-advanced', _depthMode !== 'simple');
  el.classList.toggle('depth-analyst', _depthMode === 'analyst');
  const group = document.getElementById('depth-mode-group');
  if (group) {
    group.querySelectorAll('[data-depth]').forEach(btn => {
      const active = btn.dataset.depth === _depthMode;
      btn.setAttribute('aria-pressed', String(active));
      btn.classList.toggle('depth-mode-btn--active', active);
    });
  }
}

window.setDepthMode = function(mode) {
  if (!DEPTH_MODES.includes(mode) || mode === _depthMode) return;
  _depthMode = mode;
  localStorage.setItem(LS_ANALYST_MODE, _depthMode);
  _applyAnalystMode();
};

window.toggleAnalystMode = function() {
  window.setDepthMode(_depthMode === 'analyst' ? 'simple' : 'analyst');
};

/* ═══════════════════════════════════════════════════
   SECTION SORT BY SEVERITY — retired
   Used to float flagged sections up the page on every render. This
   actively fought the fixed ACCOUNT PROFILE hierarchy introduced
   afterward (Account Overview / Security / Balance & Asset Activity /
   Transaction Behavior / Counterparties / Market & DEX / Liquidity /
   Issuer Intelligence / NFT Activity / Forensic Findings / Advanced) —
   moving .inspector-section elements without moving the group-header
   dividers alongside them would tear sections out of their labeled
   group on every inspection, and a page whose section order changes
   run to run undermines the "learn the layout once" goal a predictable,
   professional hierarchy is meant to provide. "Surface what matters" is
   now handled without reshuffling the page: _applySmartCollapseDefaults()
   auto-expands only flagged sections, the hero banner's category risk
   bars point straight at which group has a concern, and the jump-nav
   TOC reaches any section in one click regardless of scroll position.
   Kept as a no-op (rather than deleted) in case a future, group-scoped
   version is worth revisiting — the call site is left in place on
   purpose, one line below.
═══════════════════════════════════════════════════ */
function _sortSectionsBySeverity() { /* intentionally a no-op — see comment above */ }

/* ═══════════════════════════════════════════════════
   QUICK VERDICT BANNER
   3-line summary shown at top after inspection.
   Replaces the need to scroll through 20+ sections.
═══════════════════════════════════════════════════ */
/** Per-category evidence strength: the average confidence of that
 *  category's findings, bucketed Strong/Moderate/Weak/Unrated — "this
 *  category scored high" and "this category scored high on strong
 *  evidence" are different claims, and collapsing them was exactly the
 *  gap the Data Quality panel is meant to close. */
/** Every section badge already gets a consistent --crit/--warn/--ok/--neutral
 *  class from its own render*Panel function — reuse that existing signal
 *  rather than re-deriving severity per section. Every one of the ~23
 *  analysis sections defaulted to fully expanded regardless of whether it
 *  found anything, which is what actually produced the "wall of panels"
 *  problem — not the amount of underlying analysis, which is unchanged and
 *  still fully reachable by clicking any header. After each inspection,
 *  only sections carrying an explicit critical/warning badge default open;
 *  everything else (clean findings, informational-only sections, raw data
 *  like Transaction History) defaults collapsed. Re-runs on every
 *  inspection, not just once, so a previously-flagged section correctly
 *  re-collapses on a clean wallet and vice versa. */
const SMART_COLLAPSE_ALWAYS_OPEN = new Set(['section-overview', 'section-evidence-matrix']);

function _applySmartCollapseDefaults() {
  document.querySelectorAll('#inspect-result .inspector-section').forEach(sec => {
    if (SMART_COLLAPSE_ALWAYS_OPEN.has(sec.id)) return;
    const header = sec.querySelector('.section-header');
    if (!header) return;
    const badge = sec.querySelector('.section-badge');
    const flagged = !!badge && (badge.classList.contains('section-badge--crit') || badge.classList.contains('section-badge--warn'));
    sec.classList.toggle('collapsed', !flagged);
    header.setAttribute('aria-expanded', String(flagged));
  });
}

/** Live status nav: reflects each section's own already-computed badge
 *  severity as a small dot on its jump-nav button, so the nav doubles as
 *  an at-a-glance risk map of the whole account without scrolling —
 *  reuses the exact same badge-class signal _applySmartCollapseDefaults
 *  already reads, adding zero new analysis. Sections with no badge at all
 *  (Account Overview, whose content is charts/grids, not findings) simply
 *  get no dot rather than a fabricated one. */
// Phase 2: a nav button now represents several sections (e.g. "Flow" =
// drain + flowmotifs + inbound), so the dot can no longer be a 1:1 mirror
// of one section's own badge — it aggregates to the WORST severity found
// across every section that belongs to that button, via the same
// _sectionToNavKey reverse lookup the click/scrollspy logic uses. A
// workspace whose only flagged section is a less-prominent member (e.g.
// "livebook" inside Market) must still show its dot — silently checking
// only each workspace's first/jump-target section would hide that.
function _syncNavStatusDots() {
  const LEVEL_RANK = { crit: 3, warn: 2, ok: 1 };
  const worstByKey = new Map();
  // Iterates every id this nav tracks (via badge-<id>) rather than
  // querying '.inspector-section' elements — 5 of the Forensics workspace's
  // own members (benfords/entropy/zipf/timeseries/granger) are nested
  // '.forensic-sub-section' <div>s, not '.inspector-section's, so the
  // previous element-first approach silently never saw their badges at
  // all (confirmed live: a real 'crit' on one of them was dropped to the
  // next-worst 'warn' found among the section-level badges).
  for (const id of _sectionToNavKey.keys()) {
    const key = _sectionToNavKey.get(id);
    const badge = document.getElementById('badge-' + id);
    let level = null;
    if (badge?.classList.contains('section-badge--crit')) level = 'crit';
    else if (badge?.classList.contains('section-badge--warn')) level = 'warn';
    else if (badge?.classList.contains('section-badge--ok')) level = 'ok';
    if (!level) continue;
    const prev = worstByKey.get(key);
    if (!prev || LEVEL_RANK[level] > LEVEL_RANK[prev]) worstByKey.set(key, level);
  }

  document.querySelectorAll('#inspector-nav .in-btn[data-jump-key]').forEach(btn => {
    const level = worstByKey.get(btn.dataset.jumpKey);
    let dot = btn.querySelector('.in-status-dot');
    if (!level) { dot?.remove(); return; }
    if (!dot) {
      dot = document.createElement('span');
      dot.className = 'in-status-dot';
      btn.appendChild(dot);
    }
    dot.className = `in-status-dot in-status-dot--${level}`;
  });
}

function _evidenceStrength(findings) {
  const withConfidence = (findings || []).filter(f => f.confidence != null);
  if (!withConfidence.length) return null;
  const avg = withConfidence.reduce((s, f) => s + f.confidence, 0) / withConfidence.length;
  return avg >= 0.7 ? 'Strong' : avg >= 0.4 ? 'Moderate' : 'Weak';
}

/* ═══════════════════════════════════════════════════
   EVIDENCE MATRIX
   A single sortable/filterable table over every finding this inspection
   produced (window._lastAllFindings), so a finding's real strength can be
   scanned at a glance instead of hunting through ~20 separate panels.
   Clicking a row opens the Evidence Inspector for that finding's full
   detail (reuses findingRow's existing evidence-model rendering).
═══════════════════════════════════════════════════ */
let _evidenceMatrixFilter = { sev: 'all', category: 'all' };

function setEvidenceMatrixFilter(kind, value) {
  _evidenceMatrixFilter[kind] = value;
  renderEvidenceMatrix(window._lastAllFindings || []);
}

// One dot color per risk category — used only as an identity marker (which
// category), never as a severity signal (that's the badge column's job) —
// reusing the app's existing hue language (orange=security/nav-group tint,
// cyan=market/analytics, violet=automation/inferred, etc.) so this reads as
// consistent with the rest of the Inspector rather than a new palette.
const RISK_CATEGORY_COLOR = {
  security: '#ff8c42', 'market-integrity': '#00d4ff', counterparty: '#8be9fd',
  issuer: '#f1fa8c', liquidity: '#50fa7b', automation: '#bd93f9', 'external-exposure': '#ff79c6',
};
const _EVMATRIX_SEV_BADGE_CLASS = { critical: 'crit', warn: 'warn', info: 'neutral' };
const _EVMATRIX_EVIDENCE_COLOR = { Strong: '#50fa7b', Moderate: '#ffb86c', Weak: '#ff8c42' };

/** Evidence Pyramid (beginner-UX spec §48) — a visual model of how much
 *  of this inspection's evidence sits at each reliability tier, reusing
 *  the EXACT SAME per-finding Strong/Moderate/Weak classification
 *  (_evidenceStrength) already used for each Evidence Matrix row — no
 *  new scoring logic, just an aggregate view over data already computed.
 *  The band widths are a FIXED visual metaphor (top narrowest, bottom
 *  widest), not literally proportional to count — a literal count-
 *  proportional pyramid could easily render upside-down (more strong
 *  findings than weak ones) and lose the "less-but-more-decisive at the
 *  top" shape the metaphor is meant to convey. Real counts are always
 *  shown as numbers regardless of band width. */
function buildEvidencePyramid(allFindings) {
  const relevant = (allFindings || []).filter(f => f.sev !== 'ok' && f.confidence != null);
  if (!relevant.length) return { applicable: false };
  const tiers = { Strong: [], Moderate: [], Weak: [] };
  for (const f of relevant) {
    const strength = _evidenceStrength([f]);
    if (strength) tiers[strength].push(f);
  }
  return { applicable: true, tiers, total: relevant.length };
}

function _renderEvidencePyramid(pyramid) {
  if (!pyramid?.applicable) return '';
  const band = (label, findings, widthPct) => {
    const example = findings[0]?.headline || findings[0]?.label || '';
    return `
      <div class="evpyramid-band" style="width:${widthPct}%;background:${_EVMATRIX_EVIDENCE_COLOR[label]}22;border-color:${_EVMATRIX_EVIDENCE_COLOR[label]}55">
        <div class="evpyramid-band-label" style="color:${_EVMATRIX_EVIDENCE_COLOR[label]}">${label} <span class="mono">(${findings.length})</span></div>
        ${example ? `<div class="evpyramid-band-example" title="${escHtml(example)}">${escHtml(example)}</div>` : ''}
      </div>`;
  };
  return `
    <div class="evpyramid-wrap">
      <div class="evpyramid-title">Evidence Pyramid — ${pyramid.total} finding${pyramid.total === 1 ? '' : 's'} by reliability tier</div>
      <div class="evpyramid-stack">
        ${band('Strong', pyramid.tiers.Strong, 45)}
        ${band('Moderate', pyramid.tiers.Moderate, 72)}
        ${band('Weak', pyramid.tiers.Weak, 100)}
      </div>
      <div class="evpyramid-caption">Strong = high-confidence, well-corroborated findings. Weak = statistical patterns/single-signal findings — supporting evidence, not conclusions on their own. Band width is a fixed visual scale, not proportional to count.</div>
    </div>`;
}

function renderEvidenceMatrix(allFindings) {
  const el = document.getElementById('inspect-evidence-matrix-body');
  if (!el) return;
  const badge = document.getElementById('badge-evidence-matrix');

  const filtered = allFindings.filter(f => {
    if (_evidenceMatrixFilter.sev !== 'all' && f.sev !== _evidenceMatrixFilter.sev) return false;
    if (_evidenceMatrixFilter.category !== 'all') {
      const cat = f.category || MODULE_DEFAULT_CATEGORY[f.module] || 'security';
      if (cat !== _evidenceMatrixFilter.category) return false;
    }
    return true;
  });

  if (badge) badge.textContent = `${filtered.length} of ${allFindings.length}`;

  const countFor = (sev) => sev === 'all' ? allFindings.length : allFindings.filter(f => f.sev === sev).length;
  const sevOptions = ['all', 'critical', 'warn', 'info'];
  const sevLabel = { all: 'All', critical: 'Critical', warn: 'Warning', info: 'Info' };
  const catOptions = ['all', ...RISK_CATEGORIES];

  const filterBar = `
    <div class="evmatrix-filters">
      <div class="evmatrix-filter-group">
        ${sevOptions.map(s => `<button class="evmatrix-filter-btn evmatrix-filter-btn--${s} ${_evidenceMatrixFilter.sev === s ? 'evmatrix-filter-btn--active' : ''}" onclick="setEvidenceMatrixFilter('sev','${s}')">${sevLabel[s]} <span class="evmatrix-filter-count">${countFor(s)}</span></button>`).join('')}
      </div>
      <div class="evmatrix-filter-group">
        ${catOptions.map(c => `<button class="evmatrix-filter-btn ${_evidenceMatrixFilter.category === c ? 'evmatrix-filter-btn--active' : ''}" onclick="setEvidenceMatrixFilter('category','${c}')">${c !== 'all' ? `<span class="evmatrix-cat-dot" style="background:${RISK_CATEGORY_COLOR[c] || '#888'}"></span>` : ''}${c === 'all' ? 'All Categories' : escHtml(RISK_CATEGORY_LABELS[c] || c)}</button>`).join('')}
      </div>
    </div>`;

  if (!allFindings.length) {
    el.innerHTML = `<div class="inspect-empty-note">No findings recorded for this inspection yet — run an inspection first.</div>`;
    return;
  }
  const pyramidHtml = _renderEvidencePyramid(buildEvidencePyramid(allFindings));
  if (!filtered.length) {
    el.innerHTML = pyramidHtml + filterBar + `<div class="inspect-empty-note">No findings match this filter.</div>`;
    return;
  }

  const sevIcon = { critical: '⛔', warn: '⚠', info: 'ℹ', ok: '✓' };
  const confColor = c => c >= 0.7 ? '#50fa7b' : c >= 0.4 ? '#ffb86c' : '#ff8c42';
  const rows = filtered
    .sort((a, b) => (b.confidence ?? 0) * (_RISK_SEV_WEIGHT[b.sev] ?? 0) - (a.confidence ?? 0) * (_RISK_SEV_WEIGHT[a.sev] ?? 0))
    .map(f => {
      const realIdx = allFindings.indexOf(f);
      const cat = f.category || MODULE_DEFAULT_CATEGORY[f.module] || 'security';
      const strength = _evidenceStrength([f]);
      const headline = f.headline || f.label || '';
      const pct = f.confidence != null ? Math.round(f.confidence * 100) : null;
      return `
      <tr class="evmatrix-row evmatrix-row--${f.sev}" onclick="openEvidenceInspector(${realIdx})" tabindex="0" role="button">
        <td class="evmatrix-finding-cell">
          <div class="evmatrix-finding" title="${escHtml(headline)}">${escHtml(headline)}</div>
          <div class="evmatrix-module">${escHtml(f.module || '')}</div>
        </td>
        <td><span class="evmatrix-cat-tag"><span class="evmatrix-cat-dot" style="background:${RISK_CATEGORY_COLOR[cat] || '#888'}"></span>${escHtml(RISK_CATEGORY_LABELS[cat] || cat)}</span></td>
        <td><span class="section-badge section-badge--${_EVMATRIX_SEV_BADGE_CLASS[f.sev] || 'neutral'} evmatrix-sev-badge">${sevIcon[f.sev] || ''} ${(f.sev || '').toUpperCase()}</span></td>
        <td class="evmatrix-conf-cell">
          ${pct != null ? `
          <div class="evmatrix-conf-bar"><div class="evmatrix-conf-fill" style="width:${pct}%;background:${confColor(f.confidence)}"></div></div>
          <span class="mono evmatrix-conf-val" style="color:${confColor(f.confidence)}">${pct}%</span>` : '<span class="mono" style="opacity:.4">—</span>'}
        </td>
        <td>${strength ? `<span class="evmatrix-evidence-tag" style="color:${_EVMATRIX_EVIDENCE_COLOR[strength]};border-color:${_EVMATRIX_EVIDENCE_COLOR[strength]}66">${strength}</span>` : '<span style="opacity:.35">—</span>'}</td>
      </tr>`;
    }).join('');

  el.innerHTML = `
    ${pyramidHtml}
    ${filterBar}
    <div class="evmatrix-table-wrap">
      <table class="evmatrix-table">
        <thead><tr><th>Finding</th><th>Category</th><th>Severity</th><th>Confidence</th><th>Evidence</th></tr></thead>
        <tbody>${rows}</tbody>
      </table>
    </div>`;
}

/* ── Shared chart tooltip ──
   One delegated tooltip for every hand-built SVG chart in this file
   (balance chart, activity timeline, future charts), mirroring the same
   single-shared-overlay pattern as .acct-peek-overlay/Evidence Inspector
   rather than wiring a separate tooltip per chart. Chart elements just
   need a `data-tooltip="plain text, \n for line breaks"` attribute — no
   per-element listeners, no HTML-escaping (plain text only, rendered via
   textContent + white-space:pre-line in CSS). */
function _mountChartTooltip() {
  if (document.getElementById('chartTooltip')) return;
  const tip = document.createElement('div');
  tip.id = 'chartTooltip';
  tip.className = 'chart-tooltip';
  document.body.appendChild(tip);

  document.addEventListener('mousemove', e => {
    const target = e.target.closest('[data-tooltip]');
    if (!target) { tip.classList.remove('chart-tooltip--visible'); return; }
    if (tip.dataset.for !== target.dataset.tooltip) {
      tip.textContent = target.dataset.tooltip;
      tip.dataset.for = target.dataset.tooltip;
    }
    // Position near the cursor, nudged left/up near the viewport edges
    // rather than letting the tooltip run off-screen.
    const pad = 14;
    let left = e.clientX + pad, top = e.clientY + pad;
    if (left + 220 > window.innerWidth) left = e.clientX - 220 - pad;
    if (top + 80 > window.innerHeight) top = e.clientY - 80 - pad;
    tip.style.left = left + 'px';
    tip.style.top = top + 'px';
    tip.classList.add('chart-tooltip--visible');
  }, { passive: true });
}

/* ── Evidence Inspector — shared modal, mirrors dashboard.js's
   mountAccountPeekModal()/.acct-peek-overlay pattern exactly, reusing its
   CSS (dashboard.css) rather than duplicating overlay styling here. ── */
function _mountEvidenceInspector() {
  if (document.getElementById('evidenceInspectorOverlay')) return;

  const overlay = document.createElement('div');
  overlay.id = 'evidenceInspectorOverlay';
  overlay.className = 'acct-peek-overlay';
  overlay.style.display = 'none';
  overlay.innerHTML = `
    <div class="acct-peek-box" role="dialog" aria-modal="true" aria-label="Evidence inspector">
      <button class="acct-peek-close" id="evInspectorClose" aria-label="Close">✕</button>
      <div class="acct-peek-head">
        <div style="min-width:0">
          <div class="acct-peek-title">Evidence Inspector</div>
          <div class="acct-peek-addr cut" id="evInspectorHeadline" style="white-space:normal">—</div>
        </div>
      </div>
      <div class="acct-peek-grid" id="evInspectorGrid"></div>
      <div class="acct-peek-section" id="evInspectorDetail"></div>
    </div>`;
  document.body.appendChild(overlay);

  const close = () => { overlay.style.display = 'none'; overlay._a11yFocusOut?.(); };
  bindOverlayA11y(overlay, close);
  overlay.addEventListener('click', e => { if (e.target === overlay) close(); });
  document.getElementById('evInspectorClose')?.addEventListener('click', close);
}

function openEvidenceInspector(idx) {
  _mountEvidenceInspector();
  const f = (window._lastAllFindings || [])[idx];
  const overlay = document.getElementById('evidenceInspectorOverlay');
  if (!f || !overlay) return;

  const cat = f.category || MODULE_DEFAULT_CATEGORY[f.module] || 'security';
  const strength = _evidenceStrength([f]) || '—';

  document.getElementById('evInspectorHeadline').textContent = f.headline || f.label || '';
  document.getElementById('evInspectorGrid').innerHTML = `
    <div class="acct-peek-stat"><span>Module</span><b>${escHtml(f.module || '—')}</b></div>
    <div class="acct-peek-stat"><span>Category</span><b>${escHtml(RISK_CATEGORY_LABELS[cat] || cat)}</b></div>
    <div class="acct-peek-stat"><span>Severity</span><b>${(f.sev || '').toUpperCase()}</b></div>
    <div class="acct-peek-stat"><span>Confidence</span><b>${f.confidence != null ? Math.round(f.confidence * 100) + '%' : '—'}</b></div>`;
  // Evidence strength shown alongside — a full-width fifth stat rather than
  // squeezed into the 4-up grid above.
  document.getElementById('evInspectorGrid').innerHTML += `
    <div class="acct-peek-stat" style="grid-column:1 / -1"><span>Evidence Strength</span><b>${escHtml(strength)}</b></div>`;
  // Reuse findingRow's existing evidence-model rendering wholesale — same
  // Observed/Calculated/Inferred/Hypothesis/Alternative-explanations/
  // Evidence-against-benign/Classification breakdown shown inline in the
  // panels, just focused into a single-finding view. `label` is aliased
  // from `headline` since allFindings entries (built by push()) don't
  // carry `.label` themselves — only mkFinding()'s own return value does.
  document.getElementById('evInspectorDetail').innerHTML = findingRow({ ...f, label: f.headline || f.label });

  overlay.style.display = 'flex';
  overlay._a11yFocusIn?.();
}

// Opens the Transaction Detail Drawer for a hash cited as evidence on a
// finding — closes whichever finding-detail overlay (Evidence Inspector or
// an inline panel's own) is currently open first, rather than stacking two
// .acct-peek-overlay modals at the same z-index on top of each other.
window.openTxEvidence = function(hash) {
  const evOverlay = document.getElementById('evidenceInspectorOverlay');
  if (evOverlay && evOverlay.style.display !== 'none') {
    evOverlay.style.display = 'none';
    evOverlay._a11yFocusOut?.();
  }
  window.openTxDetailDrawer(hash);
};

/* ── Compare Accounts — side-by-side forensic summary ──
   Beginner-UX spec §57. Deliberately does NOT duplicate any analysis
   logic or run a second, parallel copy of the pipeline: it just captures
   the same globals every inspection already caches (window._lastInspectResult/
   _lastCategoryRisk/_lastBalXrp) once for the CURRENTLY-shown account, then
   runs a second real inspection (awaiting the same runInspect() the main
   Inspect button calls) and captures those globals again — two snapshots,
   zero new forensic computation. Mirrors _mountEvidenceInspector's exact
   .acct-peek-overlay/.acct-peek-box shell. */
function _captureCompareSnapshot(addr) {
  const r = window._lastInspectResult;
  if (!r || r.addr !== addr) return null;
  const findings = window._lastAllFindings || [];
  const topFindings = [...findings]
    .filter(f => f.sev === 'critical' || f.sev === 'warn')
    .sort((a, b) => (b.confidence ?? 0) - (a.confidence ?? 0))
    .slice(0, 3);
  return {
    addr,
    riskScore: r.riskScore,
    walletAgeDays: r.walletAgeDays,
    walletAgeVerified: r.walletAgeVerified,
    txCount: r.txCount,
    balXrp: window._lastBalXrp ?? null,
    categoryRisk: window._lastCategoryRisk || {},
    topFindings,
  };
}

function _mountCompareModal() {
  if (document.getElementById('compareOverlay')) return;
  const overlay = document.createElement('div');
  overlay.id = 'compareOverlay';
  overlay.className = 'acct-peek-overlay';
  overlay.style.display = 'none';
  overlay.innerHTML = `
    <div class="acct-peek-box" role="dialog" aria-modal="true" aria-label="Compare accounts">
      <button class="acct-peek-close" id="compareClose" aria-label="Close">✕</button>
      <div class="acct-peek-head">
        <div style="min-width:0">
          <div class="acct-peek-title">⚖️ Compare Accounts</div>
          <div class="acct-peek-addr cut" style="white-space:normal;font-size:.8rem;opacity:.65">Compare this account's forensic profile against another, side by side.</div>
        </div>
      </div>
      <div id="compareStepInput">
        <div style="font-size:.8rem;color:rgba(255,255,255,.6);margin-bottom:10px">Account A (current): <span class="mono" id="compareAddrA">—</span></div>
        <input id="compareAddrBInput" class="xrpl-input" type="text" placeholder="r…  second XRPL address to compare against"
          autocomplete="off" spellcheck="false" style="width:100%;margin-bottom:10px;box-sizing:border-box" />
        <div id="compareInputErr" style="display:none;color:#ff5555;font-size:.78rem;margin-bottom:10px"></div>
        <button class="xrpl-btn btn-inspect" onclick="runAccountComparison()">Compare →</button>
      </div>
      <div id="compareStepResult" style="display:none"></div>
    </div>`;
  document.body.appendChild(overlay);

  const close = () => { overlay.style.display = 'none'; overlay._a11yFocusOut?.(); };
  bindOverlayA11y(overlay, close);
  overlay.addEventListener('click', e => { if (e.target === overlay) close(); });
  document.getElementById('compareClose')?.addEventListener('click', close);
}

window.openCompareModal = function() {
  const currentAddr = window._lastInspectResult?.addr;
  if (!currentAddr) { alert('Run an inspection first, then compare it against another account.'); return; }
  _mountCompareModal();
  const overlay = document.getElementById('compareOverlay');
  document.getElementById('compareAddrA').textContent = shortAddr(currentAddr);
  document.getElementById('compareAddrBInput').value = '';
  document.getElementById('compareInputErr').style.display = 'none';
  document.getElementById('compareStepInput').style.display = '';
  document.getElementById('compareStepResult').style.display = 'none';
  overlay.style.display = 'flex';
  overlay._a11yFocusIn?.();
};

window.runAccountComparison = async function() {
  const addrA    = window._lastInspectResult?.addr;
  const addrBRaw = document.getElementById('compareAddrBInput')?.value.trim() || '';
  const errEl    = document.getElementById('compareInputErr');
  const showErr  = msg => { errEl.textContent = msg; errEl.style.display = ''; };

  if (!addrA) { showErr('No current inspection to compare from.'); return; }
  if (!isValidXrpAddress(addrBRaw)) { showErr(`Invalid address: ${addrBRaw}`); return; }
  if (addrBRaw === addrA) { showErr('Enter a different address to compare against.'); return; }
  errEl.style.display = 'none';

  // Snapshot A from the inspection already showing — no need to re-run it.
  const snapA = _captureCompareSnapshot(addrA);

  const btn = document.querySelector('#compareStepInput .btn-inspect');
  if (btn) { btn.disabled = true; btn.textContent = 'Comparing…'; }
  try {
    const inp = document.getElementById('inspect-addr');
    if (inp) inp.value = addrBRaw;
    await runInspect();
    const snapB = _captureCompareSnapshot(addrBRaw);

    if (!snapA || !snapB) { showErr('Could not complete one of the inspections — try again.'); return; }

    _renderCompareResult(snapA, snapB);
    document.getElementById('compareStepInput').style.display = 'none';
    document.getElementById('compareStepResult').style.display = '';
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = 'Compare →'; }
  }
};

function _renderCompareResult(a, b) {
  const el = document.getElementById('compareStepResult');
  if (!el) return;
  const riskColor = s => s >= 70 ? '#ff5555' : s >= 40 ? '#ffb86c' : '#50fa7b';
  const catRow = catKey => {
    const av = a.categoryRisk[catKey]?.score ?? 0;
    const bv = b.categoryRisk[catKey]?.score ?? 0;
    return `<div class="compare-row">
      <div class="compare-label">${escHtml(RISK_CATEGORY_LABELS[catKey])}</div>
      <div class="compare-cell mono" style="color:${riskColor(av)}">${av}</div>
      <div class="compare-cell mono" style="color:${riskColor(bv)}">${bv}</div>
    </div>`;
  };
  const findingsCol = snap => snap.topFindings.length
    ? snap.topFindings.map(f => `<div style="font-size:.72rem;color:rgba(255,255,255,.6);margin-bottom:4px">• ${escHtml(f.headline || f.label || '')}</div>`).join('')
    : `<div style="font-size:.72rem;color:rgba(255,255,255,.35)">No critical/warning findings</div>`;

  el.innerHTML = `
    <div class="compare-header-row">
      <div></div>
      <div class="compare-addr-col mono" title="${escHtml(a.addr)}">${shortAddr(a.addr)}</div>
      <div class="compare-addr-col mono" title="${escHtml(b.addr)}">${shortAddr(b.addr)}</div>
    </div>
    <div class="compare-row compare-row--headline">
      <div class="compare-label">Overall Risk Score</div>
      <div class="compare-cell mono" style="color:${riskColor(a.riskScore)};font-size:1.15rem;font-weight:800">${a.riskScore}</div>
      <div class="compare-cell mono" style="color:${riskColor(b.riskScore)};font-size:1.15rem;font-weight:800">${b.riskScore}</div>
    </div>
    <div class="compare-row">
      <div class="compare-label">Wallet Age</div>
      <div class="compare-cell">${a.walletAgeDays != null ? a.walletAgeDays + 'd' + (a.walletAgeVerified ? '' : ' (est.)') : '—'}</div>
      <div class="compare-cell">${b.walletAgeDays != null ? b.walletAgeDays + 'd' + (b.walletAgeVerified ? '' : ' (est.)') : '—'}</div>
    </div>
    <div class="compare-row">
      <div class="compare-label">Balance</div>
      <div class="compare-cell mono">${a.balXrp != null ? fmt(a.balXrp, 2) + ' XRP' : '—'}</div>
      <div class="compare-cell mono">${b.balXrp != null ? fmt(b.balXrp, 2) + ' XRP' : '—'}</div>
    </div>
    <div class="compare-row">
      <div class="compare-label">Transactions Analysed</div>
      <div class="compare-cell mono">${a.txCount ?? '—'}</div>
      <div class="compare-cell mono">${b.txCount ?? '—'}</div>
    </div>
    <div class="compare-section-title">By Risk Category</div>
    ${RISK_CATEGORIES.map(catRow).join('')}
    <div class="compare-section-title">Top Findings</div>
    <div class="compare-header-row" style="align-items:start">
      <div></div>
      <div>${findingsCol(a)}</div>
      <div>${findingsCol(b)}</div>
    </div>
    <div class="compare-actions">
      <button class="xrpl-btn" onclick="inspectorLoadAddr('${a.addr}');document.getElementById('compareOverlay').style.display='none'">View ${shortAddr(a.addr)}</button>
      <button class="xrpl-btn" onclick="document.getElementById('compareOverlay').style.display='none'">View ${shortAddr(b.addr)}</button>
    </div>`;
}

/** Data Quality / Analysis Coverage strip (Inspector-wide roadmap item
 *  #6) — a persistent, compact summary of how complete the data behind
 *  THIS analysis actually is, computed entirely from fields the pipeline
 *  already tracks (historyCoverage, execution-routing stats, AMM LP-line
 *  truncation) — no new RPC calls, no new analysis. Each section still
 *  carries its own specific caveats where relevant (dataCompleteness on
 *  drain episodes, "history capped" tags on auction stats, etc.); this is
 *  the one-glance summary so a polished chart never implies more
 *  certainty than the underlying fetch actually supports. */
function computeDataQualitySummary(historyCoverage, executionLedger, issuerAmmPool, isIssuer) {
  const history = (historyCoverage?.newestToOldestComplete || historyCoverage?.oldestToNewestFetched)
    ? { label: 'Complete', tone: 'ok' }
    : (historyCoverage?.hitTxCap || historyCoverage?.hitPageCap)
      ? { label: 'Capped', tone: 'warn' }
      : { label: 'Partial', tone: 'warn' };

  const execStats = executionLedger?.stats;
  const execution = execStats?.total
    ? { label: `${Math.round(((execStats.total - execStats.unknown) / execStats.total) * 100)}%`, tone: (execStats.unknown / execStats.total) > 0.3 ? 'warn' : 'ok' }
    : { label: 'N/A', tone: 'neutral' };

  // Only meaningful for an issuer — a personal account has no "holder
  // history" of its own to be complete or partial about.
  const holderHistory = !isIssuer
    ? { label: 'N/A', tone: 'neutral' }
    : historyCoverage?.oldestToNewestFetched
      ? { label: 'Complete', tone: 'ok' }
      : { label: 'Partial', tone: 'warn' };

  const amm = !issuerAmmPool
    ? { label: 'N/A', tone: 'neutral' }
    : issuerAmmPool.lpLinesTruncated
      ? { label: 'Partial', tone: 'warn' }
      : { label: 'High', tone: 'ok' };

  return { history, execution, holderHistory, amm, version: ANALYSIS_VERSION };
}

function _renderDataQualityStrip(dq) {
  const el = document.getElementById('inspect-dataquality-strip');
  if (!el || !dq) return;
  const toneColor = { ok: '#50fa7b', warn: '#ffb86c', neutral: 'rgba(255,255,255,.4)' };
  const item = (label, v) => `<span class="dq-item"><span class="dq-item-label">${escHtml(label)}</span><span class="dq-item-val" style="color:${toneColor[v.tone]}">${escHtml(v.label)}</span></span>`;
  el.innerHTML = `
    <div class="dq-strip" title="A compact summary of how complete the data behind this analysis is — each section below still carries its own specific caveats where relevant">
      ${item('History', dq.history)}<span class="dq-sep">·</span>
      ${item('Execution reconstruction', dq.execution)}<span class="dq-sep">·</span>
      ${item('Holder history', dq.holderHistory)}<span class="dq-sep">·</span>
      ${item('AMM coverage', dq.amm)}<span class="dq-sep">·</span>
      <span class="dq-item"><span class="dq-item-label">Analysis</span><span class="dq-item-val mono" style="color:rgba(255,255,255,.5)">${escHtml(dq.version)}</span></span>
    </div>`;

  // Mirror into the Intelligence Panel's Coverage block (desktop shell) —
  // same already-computed dq.history/dq.version, never recomputed.
  const intelHistory = document.getElementById('intel-coverage-history');
  if (intelHistory) intelHistory.textContent = dq.history.label;
  const intelVersion = document.getElementById('intel-coverage-version');
  if (intelVersion) intelVersion.textContent = dq.version;
}

// Stashed so a Signal Composition row's click-to-expand (toggleSignalCategory,
// below) can re-run this exact render with the real original arguments,
// instead of threading expand/collapse state through every caller — same
// "stash + replay" pattern as _lastNetworkMapArgs/_distMarketFlowState.
let _lastQuickVerdictArgs = null;
let _expandedRiskCategory = null;
window.toggleSignalCategory = function(cat) {
  _expandedRiskCategory = _expandedRiskCategory === cat ? null : cat;
  if (_lastQuickVerdictArgs) renderQuickVerdict(..._lastQuickVerdictArgs);
};

function renderQuickVerdict(riskScore, allFindings, walletAgeDays, txCount, categoryRisk = {}, walletAgeVerified = false, historyCoverage = null, issuerAnalysis = null, accountRoles = []) {
  const el = document.getElementById('quick-verdict-body');
  if (!el) return;
  _lastQuickVerdictArgs = [riskScore, allFindings, walletAgeDays, txCount, categoryRisk, walletAgeVerified, historyCoverage, issuerAnalysis, accountRoles];

  const criticals = allFindings.filter(f => f.sev === 'critical');
  const warnings  = allFindings.filter(f => f.sev === 'warn');
  const riskColor = riskScore < 20 ? '#50fa7b' : riskScore < 45 ? '#ffb86c' : riskScore < 70 ? '#ff8c42' : '#ff5555';
  const riskWord  = riskScore < 20 ? 'Low Risk' : riskScore < 45 ? 'Moderate' : riskScore < 70 ? 'High Risk' : 'Critical';

  // Worst-first, not push-order-first: a finding's own module contributed
  // it to allFindings in whatever order that module happened to run in,
  // which has nothing to do with which finding actually matters most.
  // Sort by confidence (when present) so the two headlined here are
  // genuinely the strongest evidence, not just whichever ran first.
  const byConfidenceDesc = (a, b) => (b.confidence ?? 0.5) - (a.confidence ?? 0.5);
  const rankedCriticals = [...criticals].sort(byConfidenceDesc);
  const rankedWarnings  = [...warnings].sort(byConfidenceDesc);

  let verdict = '';
  let action  = '';

  if (criticals.length === 0 && warnings.length === 0) {
    verdict = `No elevated signals found across ${txCount.toLocaleString()} transactions${walletAgeDays != null ? ` and ${walletAgeDays} days of history` : ''}.`;
    action  = 'This wallet appears to operate within normal parameters.';
  } else {
    const topCrit = rankedCriticals.slice(0, 2).map(f => f.headline).join('; ');
    const topWarn = rankedWarnings.slice(0, 2).map(f => f.headline).join('; ');
    verdict = criticals.length
      ? `${criticals.length} critical issue${criticals.length > 1 ? 's' : ''}: ${topCrit}.`
      : `${warnings.length} warning${warnings.length > 1 ? 's' : ''}: ${topWarn}.`;
    action = criticals.length
      ? 'Review the highlighted sections below. Scroll to the Report for full recommendations.'
      : 'Review the flagged sections below for context before drawing conclusions.';
  }

  // Category breakdown: only categories with a nonzero score are shown, so
  // this stays a short scan, not six bars every time. Order matches the
  // user-facing convention (Security first, Automation last, since
  // automation alone was deliberately designed not to read as risk).
  // external-exposure is deliberately excluded here and rendered as its own
  // separate block below — it measures what happened TO this account
  // (inbound phishing/spam), not the account's own behavior, and folding it
  // into the same ranked list would visually imply it's another flavor of
  // this wallet's own risk the way Security/Automation/etc. are.
  const catRows = RISK_CATEGORIES
    .filter(cat => cat !== 'external-exposure')
    .map(cat => ({ cat, ...categoryRisk[cat] }))
    .filter(c => c.score > 0)
    .sort((a, b) => b.score - a.score);
  const exposure = categoryRisk['external-exposure'];
  const exposureBlock = exposure?.score > 0 ? `
    <div style="margin-top:10px;padding-top:10px;border-top:1px solid rgba(255,255,255,.06)">
      <div style="font-size:.65rem;font-weight:800;letter-spacing:.08em;color:rgba(255,255,255,.35);text-transform:uppercase;margin-bottom:6px">External exposure — things that happened TO this account, not its own behavior</div>
      <div style="display:flex;align-items:center;gap:8px;font-size:.76rem">
        <span style="width:150px;color:rgba(255,255,255,.6);flex-shrink:0">${escHtml(RISK_CATEGORY_LABELS['external-exposure'])}</span>
        <div style="flex:1;height:5px;border-radius:3px;background:rgba(255,255,255,.06);overflow:hidden">
          <div style="width:${exposure.score}%;height:100%;background:${exposure.score < 20 ? '#50fa7b' : exposure.score < 45 ? '#ffb86c' : '#ff8c42'};border-radius:3px"></div>
        </div>
        <span class="mono" style="color:rgba(255,255,255,.7);width:28px;text-align:right;flex-shrink:0">${exposure.score}</span>
      </div>
    </div>` : '';
  const catColor = s => s < 20 ? '#50fa7b' : s < 45 ? '#ffb86c' : s < 70 ? '#ff8c42' : '#ff5555';
  const evidenceColor = { Strong: '#50fa7b', Moderate: '#ffb86c', Weak: '#ff8c42' };
  // This is deliberately the LEAD element of Quick Verdict, not a footnote
  // below the verdict prose — a single blended 0-100 "risk score" reads as
  // false-precision ("scam score"-style) and can hide which specific kind
  // of risk, if any, is actually present. The independent per-category
  // breakdown (each with its own real evidence-strength label) is the
  // primary analytical takeaway; the headline number elsewhere on the page
  // is kept only as a small, secondary reference, not the first thing a
  // reader sees.
  const categoryBlock = catRows.length ? `
    <div>
      <div style="font-size:.78rem;font-weight:800;letter-spacing:.04em;color:rgba(255,255,255,.85);text-transform:uppercase;margin-bottom:8px">Risk by category — a single blended score can hide which kind of risk is present</div>
      <div style="display:flex;flex-direction:column;gap:4px">
        ${catRows.map(c => {
          const strength = _evidenceStrength(c.findings);
          // "Issuer Risk" is fed by both this account's own issuer behavior
          // (Token Issuer module) AND its exposure to OTHER issuers as a
          // counterparty (Issuer Connections module) — for a non-issuer
          // account, a nonzero score here almost always means the latter,
          // not "this account was evaluated as an issuer and scored low."
          // A full split into two categories is a larger change than this
          // annotation; this at least prevents the score being misread as
          // a safety rating for issuer behavior this account doesn't have.
          const issuerCaveat = (c.cat === 'issuer' && !issuerAnalysis?.isIssuer)
            ? '<div style="font-size:.66rem;color:rgba(255,255,255,.35);margin-left:158px;margin-top:-2px">Not a token issuer — reflects exposure to other issuers as a counterparty, not this account\'s own issuer risk</div>' : '';
          const isOpen = _expandedRiskCategory === c.cat;
          // Click-to-expand (roadmap: Inspector 2.0 Signal Composition) —
          // the top 3 findings actually driving this category's score, by
          // confidence, reusing data this category block already has
          // (c.findings) rather than a new lookup. Collapsed by default so
          // this stays a short scan; expanding is opt-in per category.
          const topCatFindings = [...(c.findings || [])].sort((a, b) => (b.confidence ?? 0.5) - (a.confidence ?? 0.5)).slice(0, 3);
          const expandPanel = isOpen ? `
            <div style="margin:4px 0 8px;padding:10px 12px;border-radius:9px;background:rgba(255,255,255,.025);border:1px solid rgba(255,255,255,.08);display:flex;flex-direction:column;gap:7px">
              ${topCatFindings.length ? topCatFindings.map(f => `
                <div style="display:flex;gap:8px;align-items:flex-start;font-size:.74rem">
                  <span style="color:${f.sev === 'critical' ? '#ff5555' : f.sev === 'warn' ? '#ffb86c' : 'rgba(255,255,255,.4)'};flex-shrink:0">${f.sev === 'critical' ? '⛔' : f.sev === 'warn' ? '⚠' : 'ℹ'}</span>
                  <span style="color:rgba(255,255,255,.72);line-height:1.5">${escHtml(f.headline || f.label || '')}</span>
                </div>`).join('') : '<div style="font-size:.74rem;color:rgba(255,255,255,.4)">No individual findings recorded for this category.</div>'}
            </div>` : '';
          return `
          <div onclick="toggleSignalCategory('${c.cat}')" style="display:flex;align-items:center;gap:8px;font-size:.76rem;cursor:pointer;padding:3px 0;border-radius:6px" tabindex="0" role="button" aria-expanded="${isOpen}">
            <span style="width:150px;color:rgba(255,255,255,.6);flex-shrink:0">${escHtml(RISK_CATEGORY_LABELS[c.cat])}</span>
            <div style="flex:1;height:5px;border-radius:3px;background:rgba(255,255,255,.06);overflow:hidden">
              <div style="width:${c.score}%;height:100%;background:${catColor(c.score)};border-radius:3px"></div>
            </div>
            <span class="mono" style="color:${catColor(c.score)};width:28px;text-align:right;flex-shrink:0">${c.score}</span>
            ${strength ? `<span style="width:62px;text-align:right;flex-shrink:0;font-size:.66rem;color:${evidenceColor[strength]}" title="Evidence strength — average confidence across this category's findings">${strength}</span>` : '<span style="width:62px;flex-shrink:0"></span>'}
            <span style="width:14px;flex-shrink:0;text-align:center;color:rgba(255,255,255,.3);font-size:.6rem">${isOpen ? '▾' : '▸'}</span>
          </div>${issuerCaveat}${expandPanel}`;
        }).join('')}
      </div>
    </div>` : '';

  // Data Quality: this report is only as good as the data it was built
  // from. History coverage and wallet-age confirmation are surfaced here,
  // not buried in a tooltip, because "how much of this account's history
  // did we actually see" changes how much weight everything above deserves.
  const coverageText = historyCoverage?.newestToOldestComplete
    ? `Full history confirmed — pagination reached this account's earliest transaction`
    : historyCoverage?.hitTxCap
      ? `Capped at ${txCount.toLocaleString()} transactions — this account has more history than was analyzed`
      : historyCoverage?.fetchErrorOccurred
        ? `A fetch error occurred during pagination — history may be incomplete`
        : `History coverage not confirmed complete`;
  const coverageOk = !!historyCoverage?.newestToOldestComplete;
  const dataQualityBlock = `
    <div style="margin-top:10px;padding-top:10px;border-top:1px solid rgba(255,255,255,.06)">
      <div style="font-size:.65rem;font-weight:800;letter-spacing:.08em;color:rgba(255,255,255,.35);text-transform:uppercase;margin-bottom:6px">Data quality — this report is only as good as the history it saw</div>
      <div style="display:flex;flex-direction:column;gap:3px;font-size:.76rem;color:rgba(255,255,255,.55)">
        <div><span style="color:${coverageOk ? '#50fa7b' : '#ffb86c'}">${coverageOk ? '✓' : '⚠'}</span> ${escHtml(coverageText)} (${txCount.toLocaleString()} transactions)</div>
        <div><span style="color:${walletAgeVerified ? '#50fa7b' : '#ffb86c'}">${walletAgeVerified ? '✓' : '⚠'}</span> Wallet age ${walletAgeVerified ? 'verified' : 'estimated'}${walletAgeDays != null ? ` — ${walletAgeDays} day(s)${walletAgeVerified ? '' : ', true age may be older'}` : ''}</div>
        ${historyCoverage?.fetchErrorOccurred ? `<div><span style="color:#ffb86c">⚠</span> A network fetch error occurred during history pagination — some transactions may be missing</div>` : ''}
      </div>
    </div>`;

  // Account type: a currency-issuing account is not a "regular" personal
  // wallet, and several patterns elsewhere in this report (self-payments,
  // high internal transaction volume) are common and often benign for
  // that account type in a way they wouldn't be for an ordinary personal
  // wallet. Detected from gateway_balances-derived obligations / negative
  // trustline balances — see the Token Issuer panel for full detail.
  //
  // Deliberately does NOT use NFT mint count as a signal here (previously
  // did, and it was wrong in practice): minting a handful of NFTs is
  // common, single-click behavior for an ordinary individual, not
  // evidence of running a project — unlike fungible-token issuance, which
  // requires other accounts to have deliberately extended trust to this
  // one first.
  // Shown for every account. Critical distinction from an earlier version
  // of this banner: absence of a verified role must NEVER be presented as
  // "Personal / general-purpose account" — that's an identity claim this
  // app has no evidence for. A non-issuer, non-minting account could still
  // be a project treasury, an exchange wallet, a distribution wallet, or
  // anything else this app simply can't verify without external data. The
  // honest default is "General / Unclassified," stated explicitly as not
  // proving anything about what the account actually is.
  //
  // Role classification stays evidence-gated: VERIFIED roles (Token
  // Issuer, NFT Holder, NFT Trader, NFT Minter, Liquidity Participant)
  // come from real on-ledger facts; BEHAVIORAL roles (DEX Market-Making-
  // Like Activity) are an
  // explicitly-labeled pattern inference, not an identity claim. Anything
  // requiring external registries, peer-group baselines, or pool-share-of-
  // project data (project treasury, exchange, confirmed market maker) is
  // deliberately left unclassified rather than guessed — see
  // getKnownAccountRole() and analyseAccountRoles() for the extension
  // point this leaves for a future real registry.
  const verifiedRoles   = accountRoles.filter(r => r.state === ROLE_STATE.VERIFIED);
  const behavioralRoles = accountRoles.filter(r => r.state === ROLE_STATE.BEHAVIORAL);
  const primaryLabel = verifiedRoles.length
    ? verifiedRoles.map(r => r.label).join(' + ')
    : 'General / Unclassified';
  const roleIcon = { token_issuer: '🏭', nft_holder: '🖼️', nft_trader: '🔄', nft_minter: '🎨', liquidity_participant: '💧', market_making_behavior: '📈' };
  const roleLines = [...verifiedRoles, ...behavioralRoles].map(r => `
        <div style="margin-top:6px">
          ${roleIcon[r.role] || '•'} <strong>${escHtml(r.label)}</strong> <span style="color:rgba(255,255,255,.4);font-size:.7rem">(${r.state === ROLE_STATE.VERIFIED ? 'verified on-ledger' : `behavioral inference, ${(r.confidence * 100).toFixed(0)}% confidence`})</span>
          <div style="color:rgba(255,255,255,.5);font-size:.72rem">${escHtml(r.evidence.join(' · '))}</div>
          ${r.caveat ? `<div style="color:rgba(255,255,255,.4);font-size:.7rem;font-style:italic">${escHtml(r.caveat)}</div>` : ''}
        </div>`).join('');
  const accountTypeBlock = accountRoles.length ? `
    <div style="margin-top:10px;padding:10px 12px;border-radius:10px;background:rgba(0,212,255,.06);border:1px solid rgba(0,212,255,.2)">
      <div style="font-size:.65rem;font-weight:800;letter-spacing:.08em;color:var(--accent);text-transform:uppercase;margin-bottom:4px">Account context — ${escHtml(primaryLabel)}</div>
      <div style="font-size:.78rem;color:rgba(255,255,255,.7);line-height:1.5">
        ${verifiedRoles.some(r => r.role === 'token_issuer' || r.role === 'nft_minter') ? 'Patterns like repeated self-payments or high internal transaction volume are common for accounts with these roles doing routine treasury/accounting work — findings below are weighted with this in mind, but still worth reviewing independently.' : 'Behavior below is interpreted with these roles in mind where relevant.'}
        ${roleLines}
        <div style="margin-top:8px;padding-top:8px;border-top:1px solid rgba(255,255,255,.06);color:rgba(255,255,255,.4);font-size:.7rem">Project association: not established — this app has no project-disclosure registry to confirm which project, if any, this account is connected to.</div>
      </div>
    </div>` : `
    <div style="margin-top:10px;padding:10px 12px;border-radius:10px;background:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.08)">
      <div style="font-size:.65rem;font-weight:800;letter-spacing:.08em;color:rgba(255,255,255,.4);text-transform:uppercase;margin-bottom:4px">Account context — General / Unclassified</div>
      <div style="font-size:.78rem;color:rgba(255,255,255,.6);line-height:1.5">
        No specialized role (token issuance, NFT minting, liquidity provision, or DEX market-making-like activity) was identified from available ledger evidence.
        <br><strong>This does not prove the account is a personal wallet</strong> — it may still be a project treasury, exchange wallet, distribution wallet, or another role this app cannot verify without external data. Nalu is evaluating this account using general behavioral assumptions, not project-, issuer-, exchange-, or treasury-specific ones.
        <br>Moving, consolidating, or spending an account's own funds is ordinary behavior for most account types and is not treated as inherently risky on its own — findings below focus on independent compromise signals (authorization changes, liquidate-then-withdraw sequences, breaks from this account's own established pattern), not just the size of a transfer.
      </div>
    </div>`;

  // Lead with the category breakdown (categoryBlock), not the blended
  // score — see that block's own comment. The verdict/action prose follows
  // with the headline number demoted to a small inline badge rather than a
  // standalone hero stat; when there's nothing elevated in any category
  // (catRows empty), the verdict row has nothing to follow and naturally
  // becomes the lead itself, so this still reads correctly for a clean
  // account.
  el.innerHTML = `
    ${categoryBlock}
    <div style="${catRows.length ? 'margin-top:12px;padding-top:10px;border-top:1px solid rgba(255,255,255,.06);' : ''}display:flex;align-items:flex-start;gap:10px;flex-wrap:wrap">
      <span class="mono" style="font-size:.78rem;font-weight:800;color:${riskColor};flex-shrink:0;padding-top:2px" title="Overall blended score (0-100) — secondary to the category breakdown above">${riskScore} · ${riskWord}</span>
      <div style="flex:1;min-width:200px">
        <div style="font-size:.92rem;color:rgba(255,255,255,.88);line-height:1.6;margin-bottom:6px">${escHtml(verdict)}</div>
        <div style="font-size:.8rem;color:rgba(255,255,255,.45);line-height:1.5">${escHtml(action)}</div>
        ${criticals.length || warnings.length ? `
        <div style="display:flex;gap:8px;margin-top:8px;flex-wrap:wrap">
          ${criticals.length ? `<span style="background:rgba(255,85,85,.12);border:1px solid rgba(255,85,85,.3);color:#ff5555;border-radius:999px;padding:2px 10px;font-size:.72rem;font-weight:700">${criticals.length} Critical</span>` : ''}
          ${warnings.length  ? `<span style="background:rgba(255,184,108,.10);border:1px solid rgba(255,184,108,.25);color:#ffb86c;border-radius:999px;padding:2px 10px;font-size:.72rem;font-weight:700">${warnings.length} Warnings</span>` : ''}
          <button onclick="document.getElementById('section-report')?.scrollIntoView({behavior:'smooth'})"
            style="background:rgba(0,212,255,.08);border:1px solid rgba(0,212,255,.2);color:var(--accent);border-radius:999px;padding:2px 10px;font-size:.72rem;cursor:pointer">Full Report ↓</button>
        </div>` : ''}
      </div>
    </div>
    ${accountTypeBlock}
    ${exposureBlock}
    ${dataQualityBlock}`;
}

/* ═══════════════════════════════════════════════════
   CHANGE DETECTION BANNER
   Compares current findings fingerprint vs stored one.
   Shows "NEW: 2 new critical findings since 3 days ago"
═══════════════════════════════════════════════════ */
function _renderChangeBanner(addr, currentFindings) {
  const el = document.getElementById('change-banner');
  if (!el) return;
  el.style.display = 'none';

  const history = _getHistory();
  const prev = history.find(h => h.addr === addr);
  if (!prev?.fingerprint) return;  // no previous inspection with fingerprint

  const currentKeys = new Set(
    currentFindings.filter(f => f.sev === 'critical' || f.sev === 'warn')
      .map(f => f.module + ':' + f.headline.slice(0, 40))
  );
  const prevKeys = new Set((prev.fingerprint || '').split('|').filter(Boolean));

  const newFindings  = [...currentKeys].filter(k => !prevKeys.has(k));
  const goneFindings = [...prevKeys].filter(k => !currentKeys.has(k));

  if (!newFindings.length && !goneFindings.length) return;

  const ago = _relativeTime(prev.ts);
  const parts = [];
  if (newFindings.length)  parts.push(`<span style="color:#ff5555">+${newFindings.length} new finding${newFindings.length>1?'s':''}</span>`);
  if (goneFindings.length) parts.push(`<span style="color:#50fa7b">${goneFindings.length} resolved</span>`);

  el.style.display = '';
  el.innerHTML = `
    <div style="background:rgba(255,184,108,.07);border:1px solid rgba(255,184,108,.25);border-radius:10px;
                padding:10px 14px;margin-bottom:10px;display:flex;align-items:center;gap:10px;flex-wrap:wrap">
      <span style="font-size:1rem">🔔</span>
      <span style="font-size:.84rem;color:rgba(255,255,255,.75)">
        Since last inspection <strong>${ago}</strong>: ${parts.join(', ')}
        ${newFindings.length ? '— ' + newFindings.slice(0,2).map(k=>k.split(':')[1]).join('; ') : ''}
      </span>
      <button onclick="document.getElementById('change-banner').style.display='none'" aria-label="Dismiss"
        style="margin-left:auto;background:none;border:none;color:rgba(255,255,255,.35);font-size:.9rem;cursor:pointer">✕</button>
    </div>`;
}

/* ═══════════════════════════════════════════════════
   WATCHLIST UI
═══════════════════════════════════════════════════ */
function _renderWatchlistSection() {
  const section = document.getElementById('isd-watchlist-section');
  const list    = document.getElementById('isd-watchlist-list');
  if (!section || !list) return;
  const watchlist = _getWatchlist();
  if (!watchlist.length) { section.style.display = 'none'; return; }
  section.style.display = '';
  list.innerHTML = watchlist.map(w => {
    const short  = w.addr.slice(0,8) + '…' + w.addr.slice(-6);
    const pill   = w.lastScore != null
      ? `<span class="isd-risk-pill isd-risk-pill--${_riskBucket(w.lastScore)}">${w.lastScore}</span>` : '';
    const age    = w.lastTs ? _relativeTime(w.lastTs) : 'never checked';
    return `
      <div class="isd-recent-row" style="align-items:center">
        <button class="isd-recent-addr mono" style="flex:1;text-align:left;background:none;border:none;cursor:pointer;color:inherit"
          onclick="inspectorLoadAddr('${escHtml(w.addr)}')">${escHtml(w.label || short)} <span style="opacity:.45;font-size:.75em">${short}</span></button>
        <div style="display:flex;align-items:center;gap:8px">
          ${pill}
          <span style="font-size:.72rem;opacity:.45">${age}</span>
          <button onclick="_removeFromWatchlistUI('${escHtml(w.addr)}')" aria-label="Remove ${escHtml(w.label || short)} from watchlist"
            style="background:none;border:none;color:rgba(255,85,85,.6);font-size:.85rem;cursor:pointer;padding:2px 4px">✕</button>
        </div>
      </div>`;
  }).join('');
}

window._removeFromWatchlistUI = function(addr) {
  _removeFromWatchlist(addr);
  _renderWatchlistSection();
};

function _renderWatchBtn(addr) {
  const btn = document.getElementById('watchlist-btn');
  if (!btn) return;
  const watched = _isWatched(addr);
  btn.innerHTML = watched ? '★<span class="irb-btn-label"> Watching</span>' : '☆<span class="irb-btn-label"> Watch</span>';
  btn.title = watched ? 'Remove from watchlist' : 'Add to watchlist';
  btn.setAttribute('aria-label', watched ? 'Remove from watchlist' : 'Add to watchlist');
  btn.style.color = watched ? '#ffb86c' : '';
  btn.onclick = () => {
    if (_isWatched(addr)) {
      _removeFromWatchlist(addr);
    } else {
      _addToWatchlist(addr, null);
    }
    _renderWatchBtn(addr);
    _renderWatchlistSection();
  };
}

/* ═══════════════════════════════════════════════════
   ACTIVITY TIMELINE CHART
   Bars per week over the wallet's full tx history,
   colored by dominant tx type. Shows lifecycle arc.
═══════════════════════════════════════════════════ */
function renderActivityTimeline(txList, targetId = 'inspect-activity-chart') {
  const el = document.getElementById(targetId);
  if (!el) return;
  if (!txList.length) {
    el.innerHTML = '<div style="opacity:.4;font-size:.8rem;padding:10px 0">No transaction history to chart.</div>';
    return;
  }

  const RIPPLE_EPOCH = 946684800;
  const TYPE_COLOR = {
    Payment: '#50fa7b', OfferCreate: '#00d4ff', OfferCancel: '#8be9fd',
    NFTokenMint: '#bd93f9', NFTokenCreateOffer: '#bd93f9', NFTokenAcceptOffer: '#ff79c6',
    AMMDeposit: '#ffb86c', AMMWithdraw: '#ffb86c', AMMCreate: '#ffb86c',
    SetRegularKey: '#ff5555', SignerListSet: '#ff5555', AccountSet: '#f1fa8c',
  };
  const DEFAULT_COLOR = 'rgba(255,255,255,.25)';

  // Bucket by ISO week
  const weeks = {};
  for (const {tx} of txList) {
    if (!tx.date) continue;
    const d = new Date((tx.date + RIPPLE_EPOCH) * 1000);
    // ISO week key: YYYY-Www
    const jan1 = new Date(d.getFullYear(), 0, 1);
    const wk   = Math.ceil(((d - jan1) / 86400000 + jan1.getDay() + 1) / 7);
    const key  = `${d.getFullYear()}-${String(wk).padStart(2,'0')}`;
    if (!weeks[key]) weeks[key] = { count: 0, types: {} };
    weeks[key].count++;
    const t = tx.TransactionType || 'Other';
    weeks[key].types[t] = (weeks[key].types[t] || 0) + 1;
  }

  const sorted = Object.entries(weeks).sort((a,b) => a[0].localeCompare(b[0]));
  if (sorted.length < 2) { el.innerHTML = '<div style="opacity:.4;font-size:.8rem;padding:10px 0">Not enough dated transactions for timeline.</div>'; return; }

  const maxCount = Math.max(...sorted.map(([,v]) => v.count), 1);
  const BAR_W    = Math.max(3, Math.min(16, Math.floor(600 / sorted.length)));
  const BAR_GAP  = 1;
  const H        = 60;
  const W        = sorted.length * (BAR_W + BAR_GAP);

  // Full per-type breakdown (not just the single dominant type) shown via
  // the shared chart tooltip, one bar-building pass instead of computing
  // the same bars twice.
  const bars = sorted.map(([key, v], i) => {
    const h     = Math.max(2, Math.round((v.count / maxCount) * H));
    const top   = H - h;
    const dom   = Object.entries(v.types).sort((a,b)=>b[1]-a[1])[0]?.[0] || 'Other';
    const color = TYPE_COLOR[dom] || DEFAULT_COLOR;
    const breakdown = Object.entries(v.types).sort((a,b)=>b[1]-a[1]).map(([t,n]) => `${t}: ${n}`).join('\n');
    const tip = `${key}: ${v.count} tx\n${breakdown}`;
    return `<rect x="${i*(BAR_W+BAR_GAP)}" y="${top}" width="${BAR_W}" height="${h}" fill="${color}" opacity=".8" rx="1" data-tooltip="${escHtml(tip)}" style="cursor:pointer"></rect>`;
  }).join('');

  el.innerHTML = `
    <div style="font-size:.65rem;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:.08em;margin-bottom:6px">
      Activity Timeline — ${sorted.length} weeks · ${txList.length.toLocaleString()} transactions
    </div>
    <div style="overflow-x:auto;padding-bottom:4px;touch-action:pan-x">
      <svg width="${W}" height="${H}" xmlns="http://www.w3.org/2000/svg" style="display:block;min-width:${W}px">
        ${bars}
      </svg>
    </div>
    <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:5px">
      ${Object.entries(TYPE_COLOR).slice(0,8).map(([t,c])=>
        `<span style="font-size:.62rem;color:${c};opacity:.7">● ${t}</span>`).join('')}
    </div>`;
}

/* ═══════════════════════════════════════════════════
   NETWORK MAP (D3 force-directed)
   Shows wallet at center, edges to top counterparties.
   Color: exchange=blue, flagged=red, unknown=grey.
═══════════════════════════════════════════════════ */
/** Shared counterparty aggregation — tx count, XRP volume in each direction,
 *  entity classification, and first/last-seen timestamps — used by both the
 *  radial network map and the ranked counterparty list so they can never
 *  disagree about the underlying numbers, just how they're laid out. */
/** Real counterparty discovery + volume, not just Account/Destination on
 *  Payment transactions. The naive Account/Destination check misses two
 *  real cases: (1) a token-denominated Payment's delivered amount is an
 *  IOU object, not a drops string, so the old code silently recorded it as
 *  "0 XRP" moved even though real value changed hands; (2) OfferCreate/AMM
 *  transactions have no Destination field at all, and for many accounts —
 *  a token issuer especially, since every trustline for its currency names
 *  the issuer as one of its two parties — those ARE the bulk of real
 *  interactions, previously invisible here entirely. Reuses the Balance
 *  Change Engine (extractBalanceDeltas) already trusted everywhere else in
 *  this file: its tokenDeltas/lpDeltas carry the real counterparty account
 *  per trustline change, regardless of who technically submitted the tx. */
function _buildCounterpartyData(txList, addr) {
  const cpData = new Map();
  const getOrCreate = (cp, ts) => {
    if (!cpData.has(cp)) cpData.set(cp, { cnt: 0, xrpOut: 0, xrpIn: 0, tokenVolume: new Map(), entity: getEntity(cp), firstSeen: ts, lastSeen: ts, _seenHashes: new Set() });
    const d = cpData.get(cp);
    if (ts) { d.firstSeen = d.firstSeen ? Math.min(d.firstSeen, ts) : ts; d.lastSeen = Math.max(d.lastSeen, ts); }
    return d;
  };

  for (const { tx, meta } of txList) {
    if (meta?.TransactionResult && meta.TransactionResult !== 'tesSUCCESS') continue;
    const ts = getCloseTime(tx);
    const delta = extractBalanceDeltas(tx, meta, addr);

    const counterparties = new Set();
    const isOut = tx.Account === addr;
    const isIn  = tx.Destination === addr;
    if (isOut || isIn) {
      const cp = isOut ? tx.Destination : tx.Account;
      if (cp && cp !== addr) counterparties.add(cp);
    }
    // tokenDeltas'/lpDeltas' `issuer` field is the OTHER account on that
    // specific trustline — the real counterparty for that piece of value,
    // independent of who technically submitted the transaction.
    for (const d of delta.tokenDeltas) if (d.issuer && d.issuer !== addr) counterparties.add(d.issuer);
    for (const d of delta.lpDeltas)    if (d.issuer && d.issuer !== addr) counterparties.add(d.issuer);
    if (!counterparties.size) continue;

    for (const cp of counterparties) {
      const d = getOrCreate(cp, ts);
      if (!d._seenHashes.has(tx.hash)) { d.cnt++; d._seenHashes.add(tx.hash); }
      // XRP delta is attributed only when there's exactly one counterparty
      // this transaction — splitting it across several would double count
      // the same movement against multiple unrelated parties.
      if (counterparties.size === 1) {
        if (delta.xrpDelta > 0) d.xrpIn += delta.xrpDelta;
        else if (delta.xrpDelta < 0) d.xrpOut += Math.abs(delta.xrpDelta);
      }
    }
    for (const td of delta.tokenDeltas) {
      if (!td.issuer || td.issuer === addr || !td.delta) continue;
      const d = getOrCreate(td.issuer, ts);
      d.tokenVolume.set(td.currency, (d.tokenVolume.get(td.currency) || 0) + Math.abs(td.delta));
    }
  }
  for (const d of cpData.values()) delete d._seenHashes;
  return cpData;
}

/** A counterparty's XRP volume is directly comparable across the whole
 *  map; raw token volume generally isn't (different currencies, different
 *  units) EXCEPT it's still a fair proxy for ranking/sizing that specific
 *  relationship when no XRP moved at all — which is exactly the common
 *  case for a token issuer's counterparties. Falls back to the single
 *  largest token-volume currency; a relationship touching several
 *  currencies with no XRP leg is rare enough not to warrant a blended
 *  cross-currency number here. */
function _cpVolume(d) {
  const xrpVol = d.xrpOut + d.xrpIn;
  if (xrpVol > 0) return { sortValue: xrpVol, display: `${fmt(xrpVol, 2)} XRP`, isXrp: true };
  if (d.tokenVolume && d.tokenVolume.size) {
    const [currency, amount] = [...d.tokenVolume.entries()].sort((a, b) => b[1] - a[1])[0];
    return { sortValue: amount, display: `${fmt(amount, 2)} ${hexToAscii(currency)}`, isXrp: false, currency };
  }
  return { sortValue: 0, display: null, isXrp: true };
}

/** "Who Is Connected" — Flow Intelligence spec §18: a short, beginner-
 *  facing sentence-level summary sitting above the detailed Top
 *  Counterparties list and Network Map, not duplicating either. Reuses
 *  _buildCounterpartyData/_cpVolume (the exact same data Top
 *  Counterparties already computes) and the Flow Motifs round-trip/
 *  exchange-round-trip counts already detected — no new RPC, no new
 *  analysis, purely a narrative synthesis layer. */
function buildWhoIsConnectedSummary(txList, addr, flowMotifs) {
  const cpData = _buildCounterpartyData(txList, addr);
  if (!cpData.size) return { applicable: false };

  const withVol  = [...cpData.entries()].map(([cp, d]) => [cp, d, _cpVolume(d)]);
  const totalVol = withVol.reduce((s, [, , v]) => s + (v.sortValue || 0), 0);
  const sorted   = [...withVol].sort((a, b) => b[2].sortValue - a[2].sortValue);

  // "Most activity involved N wallets" — the smallest leading group
  // covering at least 80% of total ranked value. Falls back to "all of
  // them" when there's no XRP/token volume to rank by at all (e.g. every
  // relationship here is an OfferCreate-only counterparty with no
  // completed value moved) — a real, honest "no dominant subset" case,
  // not something to paper over with a fabricated 80% split.
  let coreCount = sorted.length;
  if (totalVol > 0) {
    let cum = 0;
    for (let i = 0; i < sorted.length; i++) {
      cum += sorted[i][2].sortValue || 0;
      if (cum / totalVol >= 0.8) { coreCount = i + 1; break; }
    }
  }

  // null/undefined (not computed) is kept distinct from 0 (computed, none
  // found) — the render layer must never claim "no reciprocal activity"
  // when it simply wasn't checked.
  const reciprocalCount = flowMotifs
    ? flowMotifs.motifs.filter(m => m.type === 'ROUND_TRIP' || m.type === 'EXCHANGE_ROUND_TRIP').length
    : null;

  return { applicable: true, total: cpData.size, coreCount, reciprocalCount };
}

function _renderWhoIsConnected(summary) {
  const el = document.getElementById('inspect-who-connected');
  if (!el) return;
  if (!summary?.applicable) { el.innerHTML = ''; return; }

  const lines = [
    `<strong>${summary.total}</strong> wallet${summary.total === 1 ? '' : 's'} interacted directly with this account.`,
    summary.coreCount < summary.total
      ? `Most activity involved <strong>${summary.coreCount}</strong> of them.`
      : null,
    summary.reciprocalCount == null ? null
      : summary.reciprocalCount > 0
        ? `<strong>${summary.reciprocalCount}</strong> wallet${summary.reciprocalCount === 1 ? '' : 's'} show${summary.reciprocalCount === 1 ? 's' : ''} repeated two-way activity — see Flow Motifs below for detail.`
        : 'No wallets show repeated two-way (round-trip) activity.',
  ].filter(Boolean);

  el.innerHTML = `
    <div style="font-size:.65rem;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:.08em;margin-bottom:6px">Who This Account Is Connected To</div>
    <div style="font-size:.86rem;color:rgba(255,255,255,.8);line-height:1.6">${lines.join(' ')}</div>
  `;
}

/** Ranked, report-friendly alternative to the radial network map — same
 *  underlying counterparty data, laid out as a sorted list (rank, address,
 *  entity badge, direction, volume-proportional bar, first→last-seen span)
 *  instead of a graph. A report is read top-to-bottom, not explored by
 *  clicking around, so "who's the biggest counterparty and by how much" is
 *  easier to answer from a sorted list than from comparing circle sizes. */
function buildRankedCounterpartyList(txList, addr, limit = 15) {
  const cpData = _buildCounterpartyData(txList, addr);
  const withVol = [...cpData.entries()].map(([cp, d]) => [cp, d, _cpVolume(d)]);
  const top = withVol
    .sort((a, b) => b[2].sortValue - a[2].sortValue || b[1].cnt - a[1].cnt)
    .slice(0, limit);
  if (!top.length) return '<div class="inspect-empty-note">No counterparty interactions found.</div>';

  const maxVol = Math.max(...top.map(([, , v]) => v.sortValue), 1);

  const rows = top.map(([cp, d, v], i) => {
    const pct   = Math.max(1.5, (v.sortValue / maxVol) * 100);
    const color = CP_CATEGORY_COLOR[d.entity?.type] || CP_CATEGORY_COLOR.other;
    const xrpVol = d.xrpOut + d.xrpIn;
    const dirRatio = xrpVol > 0 ? d.xrpOut / xrpVol : 0.5;
    const dirLabel = xrpVol === 0 ? '—' : dirRatio > 0.65 ? '→ out' : dirRatio < 0.35 ? '← in' : '⇄ both';
    const entityBadge = d.entity ? `<span style="font-size:.64rem;color:${color};border:1px solid ${color};border-radius:999px;padding:1px 7px;margin-left:6px">${escHtml(d.entity.name)}</span>` : '';
    const span = _fmtDateRange(d.firstSeen, d.lastSeen);
    const volLabel = v.display || 'no direct value moved';

    return `
      <div class="ranked-cp-row"
        title="Click to view the relationship with ${escHtml(cp)}" onclick="openRelationshipDrawer('${cp}')">
        <div class="ranked-cp-rank">${i+1}</div>
        <div class="ranked-cp-addr">
          <div style="display:flex;align-items:center">
            <span class="mono" style="font-size:.76rem;color:rgba(255,255,255,.85)" title="${escHtml(cp)}">${escHtml(shortAddr(cp))}</span>
            ${entityBadge}
          </div>
          ${span ? `<div class="ranked-cp-span">${escHtml(span)}</div>` : ''}
        </div>
        <div class="ranked-cp-bar">
          <div style="width:${pct.toFixed(1)}%;height:100%;background:${color}"></div>
        </div>
        <div class="ranked-cp-dir">${dirLabel}</div>
        <div class="ranked-cp-vol mono" style="color:${v.display ? 'rgba(255,255,255,.8)' : 'rgba(255,255,255,.3)'};font-style:${v.display ? 'normal' : 'italic'}">${escHtml(volLabel)}</div>
        <div class="ranked-cp-tx">${d.cnt} tx</div>
      </div>`;
  }).join('');

  return `
    <div style="font-size:.65rem;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:.08em;margin-bottom:8px">
      Top Counterparties — ${top.length} of ${cpData.size} addresses, ranked by value moved (XRP or the account's own token) · click any row to inspect
    </div>
    ${rows}`;
}

/** Mounts the ranked counterparty list (same data/logic as the report's
 *  version, capped tighter for an at-a-glance Overview card) directly in
 *  Account Overview — answers "who does this account interact with most"
 *  without scrolling to the Full Report section at the bottom. */
function renderTopCounterparties(txList, addr, targetId = 'inspect-top-counterparties') {
  const el = document.getElementById(targetId);
  if (!el) return;
  el.innerHTML = buildRankedCounterpartyList(txList, addr, 10);
}

/** Relationship Intelligence — Tree / Flow / Matrix / Timeline, four
 *  synchronized views over one canonical dataset (never recomputed per
 *  view). Replaces the single-view Relationship Landscape, which itself
 *  replaced the old radial bubble network. renderNetworkMap/
 *  buildRankedCounterpartyList are kept fully intact: the Full Report
 *  still calls buildRankedCounterpartyList directly for its written
 *  output, and both keep their own debug-hook tests exercising the
 *  underlying data/SVG logic in isolation — only the LIVE Overview mount
 *  changes. Same canonical _buildCounterpartyData/_cpVolume/getEntity
 *  data every prior version used — no new analysis.
 *
 *  Scope, deliberately: branch/column classification is limited to
 *  Funding/Inbound, Outbound/Destinations, Token/Issuer, Known Services,
 *  and Possible Clusters — the only categories with a real,
 *  already-computed per-address tag (entity.type, mirrorGroups).
 *  Market/DEX, AMM/Liquidity, and NFT branches are omitted until a real
 *  per-address tag exists for them, rather than fabricating one. Node
 *  selection opens the existing openRelationshipDrawer (shared with every
 *  other counterparty surface in the app) rather than a new Context Panel
 *  wiring — that panel's own contextual-selection behavior is a later,
 *  not-yet-built phase. Deferred to a later pass: multi-select cluster
 *  investigation, "Find Connection Between" pathfinding, a dedicated
 *  layout engine/Web Worker (unnecessary at the data sizes seen so far —
 *  revisit if that changes), and a mobile-specific composition (today it
 *  reuses the same responsive column-stacking as the rest of the Account
 *  Overview subpanels). */
let _lastRelIntelArgs = null;             // [txList, addr, mirrorGroups, inboundFlow, targetId]
let _relIntelView = 'tree';               // 'tree' | 'flow' | 'matrix' | 'timeline'
let _relIntelExpandedBranch = null;       // which Tree branch is expanded
let _relIntelShowAll = {};                // { [branchKey]: true } — per-branch "show all" state
let _relIntelMatrixSort = { col: 'value', dir: 'desc' };
let _relIntelFocusAddr = null;            // Focus Tunnel: counterparty address, or null
let _relIntelExpandedCohort = null;       // Tree: which cohort (within the expanded branch) is expanded
let _relIntelFlowAsset = 'All';           // Flow: which real asset's ribbons are shown ('All' = count-based, never a cross-asset value mix)
let _relIntelMatrixHeat = 'value';        // Matrix: 'value' | 'frequency' | 'reciprocity' — which real column drives row heat tint

function _rerenderRelIntel() {
  if (_lastRelIntelArgs) renderRelationshipLandscape(..._lastRelIntelArgs);
}
window.setRelIntelView = function(view) { _relIntelView = view; _rerenderRelIntel(); };
window.toggleRelIntelBranch = function(key) {
  _relIntelExpandedBranch = _relIntelExpandedBranch === key ? null : key;
  _relIntelExpandedCohort = null; // a cohort only makes sense inside the branch it belongs to
  _rerenderRelIntel();
};
window.toggleRelIntelCohort = function(key) {
  _relIntelExpandedCohort = _relIntelExpandedCohort === key ? null : key;
  _rerenderRelIntel();
};
window.setRelIntelFlowAsset = function(asset) {
  _relIntelFlowAsset = asset;
  _rerenderRelIntel();
};
window.setRelIntelMatrixHeat = function(layer) {
  _relIntelMatrixHeat = layer;
  _rerenderRelIntel();
};
// A row's own real dominant asset — _cpVolume already resolved this
// (XRP if any XRP moved, else the top token by amount). Shared by Flow's
// asset filter and Tree's cohort bucketing so both use the same real,
// already-computed label rather than two slightly different derivations.
function _relIntelRowAsset(r) {
  if (!r.v.display) return null;
  return r.v.isXrp ? 'XRP' : (r.v.display.trim().split(/\s+/).pop() || 'Other');
}
window.toggleRelIntelShowAll = function(key) {
  _relIntelShowAll = { ..._relIntelShowAll, [key]: !_relIntelShowAll[key] };
  _rerenderRelIntel();
};
window.setRelIntelMatrixSort = function(col) {
  _relIntelMatrixSort = _relIntelMatrixSort.col === col
    ? { col, dir: _relIntelMatrixSort.dir === 'desc' ? 'asc' : 'desc' }
    : { col, dir: 'desc' };
  _rerenderRelIntel();
};
// Backward-compat alias — the prior single-view Landscape's expand toggle.
window.toggleRelationshipLandscapeExpanded = function() { window.toggleRelIntelShowAll('inbound'); window.toggleRelIntelShowAll('outbound'); };

function renderRelationshipLandscape(txList, addr, mirrorGroups = [], inboundFlow = null, targetId = 'inspect-relationship-landscape') {
  const el = document.getElementById(targetId);
  if (!el) return;
  _lastRelIntelArgs = [txList, addr, mirrorGroups, inboundFlow, targetId];

  const cpData = _buildCounterpartyData(txList, addr);
  if (!cpData.size) { el.innerHTML = '<div class="inspect-empty-note">No counterparty interactions found.</div>'; return; }

  // mirrorGroups is the one explicitly-labeled INFERRED (not verified)
  // relationship in the app — the "(inferred)" wording and "not verified
  // common ownership" caveat below must never be softened or dropped.
  const clusterMembers = new Map();
  mirrorGroups.forEach((g, gi) => {
    (g.accounts || []).forEach(a => clusterMembers.set(a.addr, { ...g, groupIndex: gi }));
  });

  const rows = [...cpData.entries()].map(([cp, d]) => {
    const v = _cpVolume(d);
    const xrpVol = d.xrpOut + d.xrpIn;
    const dirRatio = xrpVol > 0 ? d.xrpOut / xrpVol : 0.5;
    const dir = xrpVol === 0 ? 'both' : dirRatio > 0.65 ? 'out' : dirRatio < 0.35 ? 'in' : 'both';
    return { cp, d, v, dir, cluster: clusterMembers.get(cp) || null, netXrp: d.xrpOut - d.xrpIn };
  }).sort((a, b) => b.v.sortValue - a.v.sortValue || b.d.cnt - a.d.cnt);

  // Focus Tunnel lookup — see relDrawerFocusPartner's own comment on why
  // "related" is scoped strictly to real, already-computed mirror-cluster
  // membership rather than any fabricated cross-counterparty comparison.
  const focusedRow = _relIntelFocusAddr ? rows.find(r => r.cp === _relIntelFocusAddr) : null;
  const focusState = (r) => {
    if (!_relIntelFocusAddr) return '';
    if (r.cp === _relIntelFocusAddr) return ' rel-intel-card--focused';
    if (focusedRow?.cluster && r.cluster && r.cluster.groupIndex === focusedRow.cluster.groupIndex) return ' rel-intel-card--related';
    return ' rel-intel-card--dimmed';
  };

  const rowHtml = (r, i) => {
    const color = CP_CATEGORY_COLOR[r.d.entity?.type] || CP_CATEGORY_COLOR.other;
    const dirIcon = r.dir === 'out' ? '↗' : r.dir === 'in' ? '↙' : '⇄';
    const dirLabel = r.dir === 'out' ? '→ out' : r.dir === 'in' ? '← in' : '⇄ both';
    const entityBadge = r.d.entity ? `<span class="rel-intel-chip" style="color:${color};border-color:${color}">${escHtml(r.d.entity.name)}</span>` : '';
    const clusterBadge = r.cluster ? `<span class="rel-intel-chip rel-intel-chip--cluster" title="Possibly part of a ${r.cluster.accounts.length}-wallet cluster — not verified common ownership">⚬ cluster (inferred)</span>` : '';
    const span = _fmtDateRange(r.d.firstSeen, r.d.lastSeen);
    const volLabel = r.v.display || 'no direct value moved';
    return `
      <div class="ranked-cp-row${focusState(r)}" title="Click to view the relationship with ${escHtml(r.cp)}" onclick="openRelationshipDrawer('${r.cp}')">
        <div class="ranked-cp-rank">${i + 1}</div>
        <div class="ranked-cp-addr">
          <div style="display:flex;align-items:center;flex-wrap:wrap">
            <span class="mono" style="font-size:.76rem;color:rgba(255,255,255,.85)" title="${escHtml(r.cp)}">${escHtml(shortAddr(r.cp))}</span>
            ${entityBadge}${clusterBadge}
          </div>
          ${span ? `<div class="ranked-cp-span">${escHtml(span)}</div>` : ''}
        </div>
        <div class="ranked-cp-dir" data-dir="${r.dir}"><span class="ranked-cp-dir-icon">${dirIcon}</span>${dirLabel}</div>
        <div class="ranked-cp-vol mono" style="color:${r.v.display ? 'rgba(255,255,255,.8)' : 'rgba(255,255,255,.3)'};font-style:${r.v.display ? 'normal' : 'italic'}">${escHtml(volLabel)}</div>
        <div class="ranked-cp-tx">${r.d.cnt} tx</div>
        <div class="ranked-cp-view" aria-hidden="true">›</div>
      </div>`;
  };

  const inbound  = rows.filter(r => r.dir === 'in');
  const outbound = rows.filter(r => r.dir === 'out' || r.dir === 'both');
  const issuerRows  = rows.filter(r => r.d.entity?.type === 'issuer');
  const serviceRows = rows.filter(r => r.d.entity?.type === 'exchange' || r.d.entity?.type === 'wallet');

  const branches = [
    { key: 'inbound',  label: 'Funding / Inbound',       items: inbound,     kind: 'rows' },
    { key: 'outbound', label: 'Outbound / Destinations', items: outbound,    kind: 'rows' },
    { key: 'issuer',   label: 'Token / Issuer',          items: issuerRows,  kind: 'rows' },
    { key: 'services', label: 'Known Services',          items: serviceRows, kind: 'rows' },
    { key: 'clusters', label: 'Possible Clusters',       items: mirrorGroups, kind: 'clusters' },
  ];

  const tabs = ['tree', 'flow', 'matrix', 'timeline'];
  const tabLabel = { tree: 'Tree', flow: 'Flow', matrix: 'Matrix', timeline: 'Timeline' };
  const focusedRowOuter = _relIntelFocusAddr ? rows.find(r => r.cp === _relIntelFocusAddr) : null;
  const focusBanner = focusedRowOuter ? `
    <div class="rel-intel-focus-banner">
      <span>🎯 Focus: <span class="mono">${escHtml(shortAddr(_relIntelFocusAddr))}</span> — unrelated relationships dimmed${focusedRowOuter.cluster ? `, possible cluster members outlined` : ''}</span>
      <button type="button" class="rel-intel-focus-exit" onclick="exitRelIntelFocus()">Exit Focus</button>
    </div>` : '';

  el.innerHTML = `
   <div class="rel-intel-console">
    <div class="rel-intel-header">
      <span class="rel-intel-title">Forensic Relationship Tree — ${rows.length} ${rows.length === 1 ? 'address' : 'addresses'} · click any row to inspect</span>
      <div class="rel-intel-tabs">
        ${tabs.map(t => `<button type="button" class="rel-intel-tab${_relIntelView === t ? ' active' : ''}" onclick="setRelIntelView('${t}')">${tabLabel[t]}</button>`).join('')}
      </div>
      <button type="button" class="rel-intel-fullscreen-btn" onclick="toggleRelIntelFullscreen()" aria-label="Toggle fullscreen investigation" title="Fullscreen Investigation">⛶</button>
    </div>
    <div class="rel-intel-hud">
      <span class="rel-intel-hud-stat"><b>${rows.length}</b> relationships</span>
      <span class="rel-intel-hud-stat"><b>${inbound.length}</b> funding sources</span>
      <span class="rel-intel-hud-stat"><b>${outbound.length}</b> recipients</span>
      <span class="rel-intel-hud-stat"><b>${issuerRows.length}</b> token/issuer</span>
      <span class="rel-intel-hud-stat"><b>${serviceRows.length}</b> known services</span>
      <span class="rel-intel-hud-stat"><b>${mirrorGroups.length}</b> possible group${mirrorGroups.length === 1 ? '' : 's'}</span>
    </div>
    <div class="rel-intel-verified-note">Every relationship shown here is a <strong>verified</strong> direct on-ledger value transfer. The dashed "cluster (inferred)" badge is the one exception — a possible shared-controller signal, never proof of common ownership.</div>
    ${focusBanner}
    <div class="rel-intel-body">
      ${_relIntelView === 'tree'     ? _renderRelIntelTree(addr, branches)
      : _relIntelView === 'flow'     ? _renderRelIntelFlow(addr, rows, inbound, outbound)
      : _relIntelView === 'matrix'   ? _renderRelIntelMatrix(rows)
      :                                 _renderRelIntelTimeline(rows, txList, addr)}
    </div>
   </div>
  `;
}

/* ── Tree view: a real node-link hierarchy (SVG connector geometry + HTML
   node content via <foreignObject>) — root at top-center, the 5 category
   branches fan out below it, and clicking a branch grows its top accounts
   as a further level beneath THAT branch. For a branch past REL_TREE_CAP
   items, that level shows COHORT nodes instead of a flat dump (the single
   biggest scaling problem at e.g. 171 recipients: either shrink hundreds
   of nodes to fit, or let the user drown in them) — "Top Accounts" plus
   groups keyed by each item's own already-computed display asset (real
   per-counterparty data, not an invented category). Clicking a cohort
   reveals ITS accounts as a 3rd level. The canvas itself never scales
   down to fit — it renders at fixed pixel size and the wrapper scrolls —
   so node/text size stays constant no matter how large the network is.
   Stops at 3 levels below root: a 4th (each account's OWN further
   relationships) would need that counterparty's own tx history, which
   this function doesn't have — showing it would mean fabricating data
   this app has no real way to verify here. ── */
const REL_INTEL_LANE = {
  inbound:  { color: '#00d4ff', icon: '📥' },
  outbound: { color: '#8be9fd', icon: '📤' },
  issuer:   { color: '#50fa7b', icon: '🪙' },
  services: { color: '#ffb86c', icon: '🏛' },
  clusters: { color: '#bd93f9', icon: '🕸' },
};
const REL_TREE_LAYOUT = { rootW: 196, rootH: 78, branchW: 152, branchH: 58, childW: 178, childH: 76, gapX: 16, gapY: 44, pad: 22 };
const REL_TREE_CAP = 8;        // branch items shown directly before cohorting kicks in
const REL_TREE_COHORT_CAP = 10; // accounts shown directly once a cohort is expanded
const REL_TREE_MAX_ASSET_COHORTS = 3; // beyond this, remaining asset buckets fold into "Other"

// Groups branch overflow into a "Top Accounts" cohort (highest value) plus
// buckets keyed by each row's own real display asset (the currency/token
// name _cpVolume already resolved) — never a fabricated category.
function _relIntelBuildCohorts(items) {
  if (items.length <= REL_TREE_CAP) return null;
  const top = items.slice(0, REL_TREE_CAP);
  const rest = items.slice(REL_TREE_CAP);
  const buckets = new Map();
  rest.forEach(r => {
    const key = _relIntelRowAsset(r) || 'No Value';
    if (!buckets.has(key)) buckets.set(key, []);
    buckets.get(key).push(r);
  });
  let assetCohorts = [...buckets.entries()]
    .map(([key, arr]) => ({ key: `asset:${key}`, label: key === 'No Value' ? 'No Direct Value' : `${key} Accounts`, items: arr }))
    .sort((a, b) => b.items.length - a.items.length);
  if (assetCohorts.length > REL_TREE_MAX_ASSET_COHORTS) {
    const kept = assetCohorts.slice(0, REL_TREE_MAX_ASSET_COHORTS);
    const other = assetCohorts.slice(REL_TREE_MAX_ASSET_COHORTS).flatMap(c => c.items);
    assetCohorts = [...kept, { key: 'asset:other', label: 'Other', items: other }];
  }
  return [{ key: 'top', label: 'Top Accounts', items: top }, ...assetCohorts];
}

function _renderRelIntelTree(addr, branches) {
  const L = REL_TREE_LAYOUT;
  const lane = (key) => REL_INTEL_LANE[key] || { color: 'rgba(255,255,255,.3)', icon: '•' };

  // Focus Tunnel: auto-reveal the branch holding the focused relationship
  // (a view-only override — doesn't touch the persistent expand state, so
  // exiting focus returns to whatever was expanded before).
  const focusBranchKey = _relIntelFocusAddr
    ? branches.find(b => b.kind === 'rows' && b.items.some(r => r.cp === _relIntelFocusAddr))?.key
    : null;
  const expandedKey = focusBranchKey || _relIntelExpandedBranch;
  const expandedBranch = branches.find(b => b.key === expandedKey) || null;
  const focusedRow = _relIntelFocusAddr ? branches.flatMap(b => b.kind === 'rows' ? b.items : []).find(r => r.cp === _relIntelFocusAddr) : null;
  const focusCardClass = (r) => {
    if (!_relIntelFocusAddr) return '';
    if (r.cp === _relIntelFocusAddr) return ' rel-tree-node--focused';
    if (focusedRow?.cluster && r.cluster && r.cluster.groupIndex === focusedRow.cluster.groupIndex) return ' rel-tree-node--related';
    return ' rel-tree-node--dimmed';
  };

  // ── Level 2 (the expanded branch's direct content: accounts, cohorts, or clusters) ──
  let level2 = [];
  let cohorts = null; // non-null only when the branch needed cohorting
  if (expandedBranch) {
    if (expandedBranch.kind === 'rows') {
      cohorts = _relIntelBuildCohorts(expandedBranch.items);
      if (cohorts) {
        level2 = cohorts.map(c => ({ kind: 'cohort', c }));
      } else if (expandedBranch.items.length) {
        level2 = expandedBranch.items.map(r => ({ kind: 'account', r }));
      } else {
        level2 = [{ kind: 'empty', label: 'No relationships in this branch.' }];
      }
    } else {
      level2 = expandedBranch.items.length
        ? expandedBranch.items.map(g => ({ kind: 'cluster', g }))
        : [{ kind: 'empty', label: 'No possible clusters detected' }];
    }
  }

  // ── Level 3 (only when a Level-2 cohort is expanded) ──
  let level3 = [];
  const expandedCohort = cohorts ? cohorts.find(c => c.key === _relIntelExpandedCohort) : null;
  if (expandedCohort) {
    level3 = expandedCohort.items.slice(0, REL_TREE_COHORT_CAP).map(r => ({ kind: 'account', r }));
    if (expandedCohort.items.length > REL_TREE_COHORT_CAP) level3.push({ kind: 'overflow-note', count: expandedCohort.items.length - REL_TREE_COHORT_CAP });
  }

  // ── Layout: deterministic, hand-computed (no graph library needed at
  // this scale — each level is capped, so node COUNT per row never runs
  // away; the canvas instead grows in fixed-size pixels and the wrapper
  // scrolls, rather than shrinking nodes to force everything to fit). ──
  const rowWidth = (n, w) => n ? n * w + (n - 1) * L.gapX : 0;
  const branchRowW = rowWidth(branches.length, L.branchW);
  const level2RowW = rowWidth(level2.length, L.childW);
  const level3RowW = rowWidth(level3.length, L.childW);
  const canvasW = Math.max(L.rootW, branchRowW, level2RowW, level3RowW) + L.pad * 2;
  const canvasH = L.pad * 2 + L.rootH + L.gapY + L.branchH
    + (level2.length ? L.gapY + L.childH : 0)
    + (level3.length ? L.gapY + L.childH : 0);

  const rootX = canvasW / 2 - L.rootW / 2, rootY = L.pad;
  const branchRowX = canvasW / 2 - branchRowW / 2, branchY = rootY + L.rootH + L.gapY;
  const branchPositions = branches.map((b, i) => ({ b, x: branchRowX + i * (L.branchW + L.gapX), y: branchY }));
  const expandedPos = branchPositions.find(p => p.b.key === expandedKey);

  const centeredRow = (items, parentX, parentW, rowW, y) => {
    const parentCenterX = parentX + parentW / 2;
    const rowX = Math.max(L.pad, Math.min(parentCenterX - rowW / 2, canvasW - L.pad - rowW));
    return items.map((item, i) => ({ item, x: rowX + i * (L.childW + L.gapX), y }));
  };
  const level2Y = branchY + L.branchH + L.gapY;
  const level2Positions = (level2.length && expandedPos) ? centeredRow(level2, expandedPos.x, L.branchW, level2RowW, level2Y) : [];
  const level2CohortPos = level2Positions.find(p => p.item.kind === 'cohort' && p.item.c.key === _relIntelExpandedCohort);
  const level3Y = level2Y + L.childH + L.gapY;
  const level3Positions = (level3.length && level2CohortPos) ? centeredRow(level3, level2CohortPos.x, L.childW, level3RowW, level3Y) : [];

  // ── Connectors (drawn before nodes so nodes render on top) ──
  const edge = (x1, y1, x2, y2, active) => {
    const my = (y1 + y2) / 2;
    return `<path class="rel-tree-edge${active ? ' rel-tree-edge--active' : ''}" d="M${x1},${y1} C${x1},${my} ${x2},${my} ${x2},${y2}" fill="none" />`;
  };
  const rootCenterX = rootX + L.rootW / 2, rootBottomY = rootY + L.rootH;
  let edgesHtml = branchPositions.map(p => edge(rootCenterX, rootBottomY, p.x + L.branchW / 2, p.y, p.b.key === expandedKey)).join('');
  if (expandedPos && level2Positions.length) {
    const px = expandedPos.x + L.branchW / 2, py = expandedPos.y + L.branchH;
    edgesHtml += level2Positions.map(p => edge(px, py, p.x + L.childW / 2, p.y, p.item.kind === 'cohort' && p.item.c.key === _relIntelExpandedCohort)).join('');
  }
  if (level2CohortPos && level3Positions.length) {
    const px = level2CohortPos.x + L.childW / 2, py = level2CohortPos.y + L.childH;
    edgesHtml += level3Positions.map(p => edge(px, py, p.x + L.childW / 2, p.y, true)).join('');
  }

  // ── Node content (HTML, placed via <foreignObject>) ──
  const fo = (x, y, w, h, html) => `<foreignObject x="${x}" y="${y}" width="${w}" height="${h}"><div xmlns="http://www.w3.org/1999/xhtml" style="width:100%;height:100%">${html}</div></foreignObject>`;

  const relCount = branches.filter(b => b.kind === 'rows').reduce((s, b) => s + b.items.length, 0);
  const rootHtml = `
    <div class="rel-tree-node rel-tree-node--root">
      <div class="rel-tree-root-ring"><span class="rel-tree-root-icon">◎</span></div>
      <div class="rel-tree-root-addr mono" title="${escHtml(addr)}">${escHtml(shortAddr(addr))}</div>
      <div class="rel-tree-root-meta">${relCount} relationship${relCount === 1 ? '' : 's'}</div>
    </div>`;

  const branchHtml = (b, isExpanded) => {
    const l = lane(b.key);
    const inactiveFocus = _relIntelFocusAddr && b.kind === 'rows' && !b.items.some(r => r.cp === _relIntelFocusAddr);
    return `
      <div class="rel-tree-node rel-tree-node--branch${isExpanded ? ' rel-tree-node--active' : ''}${b.items.length === 0 ? ' rel-tree-node--empty' : ''}${inactiveFocus ? ' rel-tree-node--inactive-focus' : ''}"
           style="--lane-color:${l.color}" onclick="toggleRelIntelBranch('${b.key}')" role="button" tabindex="0" aria-expanded="${isExpanded}">
        <span class="rel-tree-branch-icon">${l.icon}</span>
        <span class="rel-tree-branch-label">${escHtml(b.label)}</span>
        <span class="rel-tree-branch-count">${b.items.length}</span>
      </div>`;
  };

  const accountHtml = (r) => {
    const color = CP_CATEGORY_COLOR[r.d.entity?.type] || CP_CATEGORY_COLOR.other;
    const dirIcon = r.dir === 'out' ? '↗' : r.dir === 'in' ? '↙' : '⇄';
    const volLabel = r.v.display || 'no direct value moved';
    const clusterGlyph = r.cluster ? ` <span class="rel-tree-cluster-dot" title="Possibly part of a ${r.cluster.accounts.length}-wallet cluster — not verified common ownership">⚬</span>` : '';
    return `
      <div class="rel-tree-node rel-tree-node--account${focusCardClass(r)}" style="--entity-color:${color}" title="Click to view the relationship with ${escHtml(r.cp)}" onclick="openRelationshipDrawer('${r.cp}')">
        <div class="rel-tree-acct-addr mono" title="${escHtml(r.cp)}">${escHtml(shortAddr(r.cp))}${r.d.entity ? ` <span class="rel-tree-entity" style="color:${color}">${escHtml(r.d.entity.name)}</span>` : ''}${clusterGlyph}</div>
        <div class="rel-tree-acct-vol mono" style="color:${r.v.display ? 'rgba(255,255,255,.82)' : 'rgba(255,255,255,.3)'};font-style:${r.v.display ? 'normal' : 'italic'}">${escHtml(volLabel)}</div>
        <div class="rel-tree-acct-dir" data-dir="${r.dir}"><span class="rel-tree-acct-dir-icon">${dirIcon}</span>${r.d.cnt} tx</div>
      </div>`;
  };

  const clusterHtml = (g) => `
    <div class="rel-tree-node rel-tree-node--cluster" title="Possible Related Group — ${g.accounts.length} wallets, ${escHtml(g.tier || 'inferred')} evidence. Not verified common ownership.">
      <div class="rel-tree-cluster-title">Possible Group <span class="rel-tree-cluster-tier">${escHtml(g.tier || 'inferred')}</span></div>
      <div class="rel-tree-cluster-members">${g.accounts.length} wallets</div>
    </div>`;

  const cohortHtml = (c, isExpanded) => `
    <div class="rel-tree-node rel-tree-node--cohort${isExpanded ? ' rel-tree-node--active' : ''}" onclick="toggleRelIntelCohort('${c.key}')" role="button" tabindex="0" aria-expanded="${isExpanded}">
      <div class="rel-tree-cohort-label">${escHtml(c.label)}</div>
      <div class="rel-tree-cohort-count">${c.items.length}</div>
    </div>`;

  const nodeHtml = (item) => {
    if (item.kind === 'account') return accountHtml(item.r);
    if (item.kind === 'cluster') return clusterHtml(item.g);
    if (item.kind === 'cohort') return cohortHtml(item.c, item.c.key === _relIntelExpandedCohort);
    if (item.kind === 'overflow-note') return `<div class="rel-tree-node rel-tree-node--empty-note">+${item.count} more in this cohort</div>`;
    return `<div class="rel-tree-node rel-tree-node--empty-note">${escHtml(item.label)}</div>`;
  };

  let nodesHtml = fo(rootX, rootY, L.rootW, L.rootH, rootHtml);
  nodesHtml += branchPositions.map(p => fo(p.x, p.y, L.branchW, L.branchH, branchHtml(p.b, p.b.key === expandedKey))).join('');
  nodesHtml += level2Positions.map(p => fo(p.x, p.y, L.childW, L.childH, nodeHtml(p.item))).join('');
  nodesHtml += level3Positions.map(p => fo(p.x, p.y, L.childW, L.childH, nodeHtml(p.item))).join('');

  return `
    <div class="rel-tree-canvas">
      <svg class="rel-tree-svg" width="${canvasW}" height="${canvasH}" viewBox="0 0 ${canvasW} ${canvasH}" role="group" aria-label="Relationship Tree">
        <g class="rel-tree-edges">${edgesHtml}</g>
        <g class="rel-tree-nodes">${nodesHtml}</g>
      </svg>
    </div>`;
}

/* ── Flow view: a real ribbon/value-flow diagram — funding sources on the
   left, the Account Core in the center, destinations on the right, joined
   by SVG ribbons. An asset filter (built from each row's own real
   dominant asset, same _relIntelRowAsset Tree's cohorts use) governs
   ribbon width: a single selected asset scales ribbons by its real value
   (all comparable, same unit), while "All" deliberately falls back to a
   neutral, non-value width — mixing raw XRP and token quantities into one
   scale would misrepresent magnitude, not just look inconsistent. ── */
// midGap must exceed coreW with real margin: coreX is centered within
// midGap (coreX = pad+nodeW + midGap/2 - coreW/2), so midGap <= coreW
// means the core's own left edge sits AT OR BEFORE the left column's
// right edge — a real bounding-box overlap, not just a tight visual gap.
const REL_FLOW_LAYOUT = { nodeW: 176, nodeH: 68, coreW: 150, coreH: 100, gapY: 14, pad: 24, midGap: 230 };
const REL_FLOW_CAP = 10;

function _renderRelIntelFlow(addr, rows, inbound, outbound) {
  const L = REL_FLOW_LAYOUT;
  const assetCounts = new Map();
  rows.forEach(r => { const a = _relIntelRowAsset(r); if (a) assetCounts.set(a, (assetCounts.get(a) || 0) + 1); });
  const assets = ['All', ...[...assetCounts.entries()].sort((a, b) => b[1] - a[1]).map(([a]) => a)];
  const activeAsset = assets.includes(_relIntelFlowAsset) ? _relIntelFlowAsset : 'All';

  const matchesAsset = (r) => activeAsset === 'All' || _relIntelRowAsset(r) === activeAsset;
  const filteredIn = inbound.filter(matchesAsset);
  const filteredOut = outbound.filter(matchesAsset);
  const shownIn = filteredIn.slice(0, REL_FLOW_CAP);
  const shownOut = filteredOut.slice(0, REL_FLOW_CAP);
  const overflowIn = filteredIn.length - shownIn.length;
  const overflowOut = filteredOut.length - shownOut.length;

  const focusedRow = _relIntelFocusAddr ? rows.find(r => r.cp === _relIntelFocusAddr) : null;
  const dimClass = (r) => {
    if (!_relIntelFocusAddr) return '';
    if (r.cp === _relIntelFocusAddr) return ' rel-tree-node--focused';
    if (focusedRow?.cluster && r.cluster && r.cluster.groupIndex === focusedRow.cluster.groupIndex) return ' rel-tree-node--related';
    return ' rel-tree-node--dimmed';
  };

  const colH = (n) => n * L.nodeH + Math.max(0, n - 1) * L.gapY;
  const leftH = colH(shownIn.length) + (overflowIn > 0 ? L.nodeH + L.gapY : 0);
  const rightH = colH(shownOut.length) + (overflowOut > 0 ? L.nodeH + L.gapY : 0);
  const canvasH = Math.max(leftH, rightH, L.coreH) + L.pad * 2;
  const canvasW = L.nodeW * 2 + L.midGap + L.coreW + L.pad * 2;

  const leftX = L.pad, rightX = canvasW - L.pad - L.nodeW;
  const coreX = L.pad + L.nodeW + L.midGap / 2 - L.coreW / 2, coreY = canvasH / 2 - L.coreH / 2;

  const stackPositions = (count, overflow, x, totalH) => {
    let y = (canvasH - totalH) / 2;
    const pos = [];
    for (let i = 0; i < count; i++) { pos.push({ x, y, h: L.nodeH }); y += L.nodeH + L.gapY; }
    if (overflow > 0) pos.push({ x, y, h: L.nodeH, overflow: true });
    return pos;
  };
  const inPos = stackPositions(shownIn.length, overflowIn, leftX, leftH);
  const outPos = stackPositions(shownOut.length, overflowOut, rightX, rightH);

  const maxVal = Math.max(1, ...filteredIn.map(r => r.v.sortValue || 0), ...filteredOut.map(r => r.v.sortValue || 0));
  const ribbonWidth = (r) => {
    if (activeAsset === 'All') return 2; // count-only: no fabricated cross-asset magnitude
    const w = 1 + ((r.v.sortValue || 0) / maxVal) * 9;
    return Math.min(10, Math.max(1.5, w));
  };
  const ribbon = (x1, y1, x2, y2, width, cls) => {
    const mx = (x1 + x2) / 2;
    return `<path class="rel-flow-ribbon${cls}" stroke-width="${width}" d="M${x1},${y1} C${mx},${y1} ${mx},${y2} ${x2},${y2}" fill="none" />`;
  };

  let ribbonsHtml = inPos.filter(p => !p.overflow).map((p, i) => {
    const r = shownIn[i];
    const active = _relIntelFocusAddr && r.cp === _relIntelFocusAddr;
    return ribbon(p.x + L.nodeW, p.y + p.h / 2, coreX, coreY + L.coreH / 2, ribbonWidth(r), ` rel-flow-ribbon--in${active ? ' rel-flow-ribbon--active' : ''}${_relIntelFocusAddr && !active ? ' rel-flow-ribbon--dimmed' : ''}`);
  }).join('');
  ribbonsHtml += outPos.filter(p => !p.overflow).map((p, i) => {
    const r = shownOut[i];
    const active = _relIntelFocusAddr && r.cp === _relIntelFocusAddr;
    return ribbon(coreX + L.coreW, coreY + L.coreH / 2, p.x, p.y + p.h / 2, ribbonWidth(r), ` rel-flow-ribbon--out${active ? ' rel-flow-ribbon--active' : ''}${_relIntelFocusAddr && !active ? ' rel-flow-ribbon--dimmed' : ''}`);
  }).join('');

  const fo = (x, y, w, h, html) => `<foreignObject x="${x}" y="${y}" width="${w}" height="${h}"><div xmlns="http://www.w3.org/1999/xhtml" style="width:100%;height:100%">${html}</div></foreignObject>`;
  const accountNode = (r) => {
    const color = CP_CATEGORY_COLOR[r.d.entity?.type] || CP_CATEGORY_COLOR.other;
    const volLabel = r.v.display || 'no direct value moved';
    const clusterGlyph = r.cluster ? ` <span class="rel-tree-cluster-dot" title="Possibly part of a ${r.cluster.accounts.length}-wallet cluster — not verified common ownership">⚬</span>` : '';
    return `
      <div class="rel-tree-node rel-tree-node--account${dimClass(r)}" style="--entity-color:${color}" title="Click to view the relationship with ${escHtml(r.cp)}" onclick="openRelationshipDrawer('${r.cp}')">
        <div class="rel-tree-acct-addr mono" title="${escHtml(r.cp)}">${escHtml(shortAddr(r.cp))}${r.d.entity ? ` <span class="rel-tree-entity" style="color:${color}">${escHtml(r.d.entity.name)}</span>` : ''}${clusterGlyph}</div>
        <div class="rel-tree-acct-vol mono" style="color:${r.v.display ? 'rgba(255,255,255,.82)' : 'rgba(255,255,255,.3)'};font-style:${r.v.display ? 'normal' : 'italic'}">${escHtml(volLabel)}</div>
        <div class="rel-tree-acct-dir">${r.d.cnt} tx</div>
      </div>`;
  };
  const overflowNode = (count) => `<div class="rel-tree-node rel-tree-node--empty-note">+${count} more</div>`;

  let nodesHtml = inPos.map((p, i) => fo(p.x, p.y, L.nodeW, p.h, p.overflow ? overflowNode(overflowIn) : accountNode(shownIn[i]))).join('');
  nodesHtml += outPos.map((p, i) => fo(p.x, p.y, L.nodeW, p.h, p.overflow ? overflowNode(overflowOut) : accountNode(shownOut[i]))).join('');
  nodesHtml += fo(coreX, coreY, L.coreW, L.coreH, `
    <div class="rel-tree-node rel-tree-node--root">
      <div class="rel-tree-root-ring"><span class="rel-tree-root-icon">◎</span></div>
      <div class="rel-tree-root-addr mono" title="${escHtml(addr)}">${escHtml(shortAddr(addr))}</div>
      <div class="rel-tree-root-meta">Account Core</div>
    </div>`);

  return `
    <div class="rel-flow-assets">
      ${assets.map(a => `<button type="button" class="rel-flow-asset-chip${a === activeAsset ? ' active' : ''}" onclick="setRelIntelFlowAsset('${escHtml(a)}')">${escHtml(a)}</button>`).join('')}
    </div>
    ${activeAsset === 'All'
      ? '<div class="rel-flow-note">Showing relationship count only — XRP and token amounts aren\'t one scale, so "All" never mixes them into a single ribbon width. Pick an asset above to size ribbons by real value.</div>'
      : `<div class="rel-flow-note">Ribbon width reflects real ${escHtml(activeAsset)} value for this relationship, capped so no single relationship visually overwhelms the rest.</div>`}
    <div class="rel-tree-canvas">
      <svg class="rel-tree-svg" width="${canvasW}" height="${canvasH}" viewBox="0 0 ${canvasW} ${canvasH}" role="group" aria-label="Relationship Flow">
        <g class="rel-tree-edges">${ribbonsHtml}</g>
        <g class="rel-tree-nodes">${nodesHtml}</g>
      </svg>
    </div>`;
}

/* ── Matrix view: sortable analyst table over every relationship ── */
/* ── Matrix view: an analyst heat-grid, not a plain table. Account/Role
   stay pinned (position:sticky) while scrolling the technical columns.
   Net Flow/Activity/Reciprocity render as real microbars built only from
   fields already computed per-row (d.xrpIn/xrpOut/cnt, firstSeen/lastSeen)
   — no "Market"/"Event" columns, since this function has no real
   per-counterparty market or event data to back them honestly. Heat tint
   normalizes the selected real column (value/frequency/reciprocity)
   against its own max across all rows — never a fabricated 4th metric. */
function _renderRelIntelMatrix(rows) {
  const COLS = [
    { key: 'addr', label: 'Account' },
    { key: 'role', label: 'Role' },
    { key: 'in', label: 'In' },
    { key: 'out', label: 'Out' },
    { key: 'net', label: 'Net Flow' },
    { key: 'tx', label: 'Activity' },
    { key: 'span', label: 'Span' },
    { key: 'reciprocity', label: 'Reciprocity' },
    { key: 'token', label: 'Token' },
  ];
  const reciprocityOf = (r) => (r.d.xrpIn > 0 && r.d.xrpOut > 0) ? (Math.min(r.d.xrpIn, r.d.xrpOut) / Math.max(r.d.xrpIn, r.d.xrpOut)) * 100 : 0;
  const sortVal = (r) => {
    switch (_relIntelMatrixSort.col) {
      case 'in': return r.d.xrpIn;
      case 'out': return r.d.xrpOut;
      case 'net': return r.netXrp;
      case 'tx': return r.d.cnt;
      case 'span': return (r.d.lastSeen || 0) - (r.d.firstSeen || 0);
      case 'reciprocity': return reciprocityOf(r);
      default: return r.v.sortValue || 0;
    }
  };
  const sorted = [...rows].sort((a, b) => _relIntelMatrixSort.dir === 'desc' ? sortVal(b) - sortVal(a) : sortVal(a) - sortVal(b));
  const roleOf = (r) => r.cluster ? 'Cluster' : r.d.entity?.name || (r.dir === 'in' ? 'Funder' : r.dir === 'out' ? 'Recipient' : 'Reciprocal');
  const sortIndicator = (col) => _relIntelMatrixSort.col === col ? (_relIntelMatrixSort.dir === 'desc' ? ' ▾' : ' ▴') : '';

  const heatVal = (r) => _relIntelMatrixHeat === 'frequency' ? r.d.cnt : _relIntelMatrixHeat === 'reciprocity' ? reciprocityOf(r) : (r.v.sortValue || 0);
  const maxHeat = Math.max(1, ...rows.map(heatVal));
  const maxAbsNet = Math.max(1, ...rows.map(r => Math.abs(r.netXrp || 0)));
  const maxTx = Math.max(1, ...rows.map(r => r.d.cnt || 0));

  const focusedRow = _relIntelFocusAddr ? rows.find(r => r.cp === _relIntelFocusAddr) : null;
  const rowStateClass = (r) => {
    if (!_relIntelFocusAddr) return '';
    if (r.cp === _relIntelFocusAddr) return ' rel-intel-matrix-row--focused';
    if (focusedRow?.cluster && r.cluster && r.cluster.groupIndex === focusedRow.cluster.groupIndex) return ' rel-intel-matrix-row--related';
    return ' rel-intel-matrix-row--dimmed';
  };

  const netBar = (r) => {
    const pct = Math.min(100, (Math.abs(r.netXrp || 0) / maxAbsNet) * 100);
    const side = r.netXrp > 0 ? 'out' : r.netXrp < 0 ? 'in' : 'flat';
    return `<div class="rim-net" data-side="${side}"><div class="rim-net-fill" style="width:${pct / 2}%"></div></div>`;
  };
  const activityBar = (r) => `<div class="rim-bar"><div class="rim-bar-fill" style="width:${Math.min(100, (r.d.cnt / maxTx) * 100)}%"></div></div>`;
  const reciprocityBar = (r) => { const pct = reciprocityOf(r); return `<div class="rim-bar"><div class="rim-bar-fill rim-bar-fill--recip" style="width:${pct}%"></div></div><span class="rim-bar-val">${pct.toFixed(0)}%</span>`; };

  const heatLayers = [['value', 'Value'], ['frequency', 'Frequency'], ['reciprocity', 'Reciprocity']];

  return `
    <div class="rel-intel-matrix-controls">
      <span class="rel-intel-matrix-heat-label">Heat:</span>
      ${heatLayers.map(([key, label]) => `<button type="button" class="rel-intel-matrix-heat-btn${_relIntelMatrixHeat === key ? ' active' : ''}" onclick="setRelIntelMatrixHeat('${key}')">${escHtml(label)}</button>`).join('')}
    </div>
    <div class="rel-intel-matrix-wrap">
      <table class="rel-intel-matrix">
        <thead><tr>
          ${COLS.map(c => c.key === 'addr' || c.key === 'role'
            ? `<th class="rim-sticky${c.key === 'role' ? ' rim-sticky--2' : ''}">${escHtml(c.label)}</th>`
            : `<th><button type="button" class="rel-intel-matrix-sortbtn" onclick="setRelIntelMatrixSort('${c.key}')">${escHtml(c.label)}${sortIndicator(c.key)}</button></th>`
          ).join('')}
        </tr></thead>
        <tbody>
          ${sorted.map(r => {
            const heatFrac = (heatVal(r) / maxHeat).toFixed(3);
            return `
            <tr class="rel-intel-matrix-row${rowStateClass(r)}" style="--heat:${heatFrac}" onclick="openRelationshipDrawer('${r.cp}')" title="Click to view the relationship with ${escHtml(r.cp)}">
              <td class="mono rim-sticky">${escHtml(shortAddr(r.cp))}</td>
              <td class="rim-sticky rim-sticky--2">${escHtml(roleOf(r))}</td>
              <td class="mono">${r.d.xrpIn > 0 ? fmt(r.d.xrpIn, 2) : '—'}</td>
              <td class="mono">${r.d.xrpOut > 0 ? fmt(r.d.xrpOut, 2) : '—'}</td>
              <td class="mono rim-net-cell">${netBar(r)}</td>
              <td class="rim-activity-cell">${activityBar(r)}<span class="rim-bar-val">${r.d.cnt}</span></td>
              <td>${escHtml(_fmtDateRange(r.d.firstSeen, r.d.lastSeen) || '—')}</td>
              <td class="rim-recip-cell">${reciprocityBar(r)}</td>
              <td>${r.d.tokenVolume?.size ? '✓' : ''}</td>
            </tr>`;
          }).join('')}
        </tbody>
      </table>
    </div>`;
}

/* ── Timeline view: when each relationship was active, on a shared axis —
   top N by value (a full unranked render of hundreds of bars is neither
   legible nor necessary; "see more" would gain analyst coverage at real
   cost to the common "who matters, when" question this view answers). */
// One pass over txList collecting each counterparty's REAL individual
// transaction timestamps — _buildCounterpartyData only keeps firstSeen/
// lastSeen (the aggregate span), not the dates in between, and Timeline's
// swimlane ticks need the real in-between activity, not a fabricated
// even spread across the span. Mirrors _buildCounterpartyData's own
// counterparty-matching rules (direct Account/Destination + tokenDeltas'/
// lpDeltas' issuer) so a tick only appears for a transaction that
// actually, verifiably involved that counterparty.
function _relIntelTxDatesByCounterparty(txList, addr) {
  const dates = new Map();
  const add = (cp, ts) => { if (ts == null) return; if (!dates.has(cp)) dates.set(cp, []); dates.get(cp).push(ts); };
  for (const { tx, meta } of txList) {
    if (meta?.TransactionResult && meta.TransactionResult !== 'tesSUCCESS') continue;
    const ts = getCloseTime(tx);
    const delta = extractBalanceDeltas(tx, meta, addr);
    const counterparties = new Set();
    const isOut = tx.Account === addr, isIn = tx.Destination === addr;
    if (isOut || isIn) { const cp = isOut ? tx.Destination : tx.Account; if (cp && cp !== addr) counterparties.add(cp); }
    for (const d of delta.tokenDeltas) if (d.issuer && d.issuer !== addr) counterparties.add(d.issuer);
    for (const d of delta.lpDeltas) if (d.issuer && d.issuer !== addr) counterparties.add(d.issuer);
    counterparties.forEach(cp => add(cp, ts));
  }
  return dates;
}

/* ── Timeline view: real forensic swimlanes — each lane's span bar is the
   same verified firstSeen/lastSeen range as before, but now carries real
   tick marks for every individual transaction date in between (not a
   fabricated even spread), with more recent ticks rendered brighter than
   older ones (recency, not risk — see the explicit caption). ── */
function _renderRelIntelTimeline(rows, txList, addr) {
  const dated = rows.filter(r => r.d.firstSeen != null && r.d.lastSeen != null);
  if (!dated.length) return '<div class="inspect-empty-note">No dated relationships to plot.</div>';
  const minT = Math.min(...dated.map(r => r.d.firstSeen));
  const maxT = Math.max(...dated.map(r => r.d.lastSeen));
  const span = Math.max(1, maxT - minT);
  const TOP_N = 15;
  const top = dated.slice(0, TOP_N);
  // r.d.firstSeen/lastSeen and the tick timestamps below all come from
  // getCloseTime(tx), which already adds XRPL_EPOCH internally (see its
  // own definition) — these are already real unix-epoch seconds. Adding
  // XRPL_EPOCH again here was a real bug: it silently pushed every date
  // ~30 years into the future (e.g. a real 2014 date rendered as "44").
  const fmtAxisDate = (t) => new Date(t * 1000).toLocaleDateString('en-US', { month: 'short', year: '2-digit' });
  const fmtFullDate = (t) => new Date(t * 1000).toLocaleDateString();

  // Axis gets 4 intermediate marks (not just the 2 endpoints) so it reads
  // like a real calendar grid rather than a bare start/end caption.
  const AXIS_TICKS = 5;
  const axisMarks = Array.from({ length: AXIS_TICKS }, (_, i) => minT + (span * i) / (AXIS_TICKS - 1));

  const txDates = _relIntelTxDatesByCounterparty(txList, addr);

  return `
    <div class="rel-intel-timeline">
      <div class="rel-intel-timeline-axis">
        ${axisMarks.map(t => `<span>${escHtml(fmtAxisDate(t))}</span>`).join('')}
      </div>
      ${top.map(r => {
        const left = ((r.d.firstSeen - minT) / span) * 100;
        const width = Math.max(0.8, ((r.d.lastSeen - r.d.firstSeen) / span) * 100);
        const color = CP_CATEGORY_COLOR[r.d.entity?.type] || CP_CATEGORY_COLOR.other;
        const ticks = (txDates.get(r.cp) || []).filter(t => t >= r.d.firstSeen && t <= r.d.lastSeen);
        const tickHtml = ticks.map(t => {
          const pos = ((t - minT) / span) * 100;
          const recency = maxT > minT ? (t - minT) / (maxT - minT) : 1;
          return `<span class="rel-intel-timeline-tick" style="left:${pos.toFixed(2)}%;opacity:${(0.35 + recency * 0.65).toFixed(2)}" title="${escHtml(fmtFullDate(t))}"></span>`;
        }).join('');
        return `
          <div class="rel-intel-timeline-row" onclick="openRelationshipDrawer('${r.cp}')" title="Click to view the relationship with ${escHtml(r.cp)}">
            <span class="mono rel-intel-timeline-label">${escHtml(shortAddr(r.cp))}</span>
            <div class="rel-intel-timeline-track">
              <div class="rel-intel-timeline-bar" style="left:${left.toFixed(2)}%;width:${width.toFixed(2)}%;background:${color}"></div>
              ${tickHtml}
            </div>
          </div>`;
      }).join('')}
      <div class="rel-intel-timeline-legend">● = a real transaction date with that account. Brighter = more recent — brightness reflects recency, never risk.</div>
      ${dated.length > TOP_N ? `<div class="rel-intel-timeline-note">Showing the ${TOP_N} highest-value relationships of ${dated.length} dated ones. Switch to Matrix for the full ranked list.</div>` : ''}
    </div>`;
}

// Which counterparty attribute drives node size — volume-only sizing hides
// a real pattern (e.g. a spam/dust-memo target with huge tx count but
// negligible XRP amounts looks like the smallest node on the map). The
// SET of nodes shown never changes with this toggle, only their size —
// switching metric mid-inspection must not make different accounts appear.
let _networkMapSizeMetric = 'volume';
let _lastNetworkMapArgs = null;

// Expand (if collapsed) and scroll to a section by its bare id (e.g.
// 'wash', not 'section-wash') — the same behavior the bottom nav's
// data-jump buttons already use, extracted so other click-to-navigate
// features (e.g. the Ledger Interaction Map's branches) don't duplicate it.
window._jumpToInspectorSection = function(bareId) {
  const sec = document.getElementById('section-' + bareId);
  if (!sec) return;
  sec.classList.remove('collapsed');
  sec.querySelector('.section-header')?.setAttribute('aria-expanded', 'true');
  sec.scrollIntoView({ behavior: 'smooth', block: 'start' });
};

window._setNetworkMapSizeMetric = function(metric) {
  _networkMapSizeMetric = metric;
  if (_lastNetworkMapArgs) renderNetworkMap(..._lastNetworkMapArgs);
};

function renderNetworkMap(txList, addr, fundFlow, inboundFlow, mirrorGroups = [], targetId = 'inspect-network-map') {
  const el = document.getElementById(targetId);
  if (!el) return;
  _lastNetworkMapArgs = [txList, addr, fundFlow, inboundFlow, mirrorGroups, targetId];

  // Flow Intelligence spec §9-10: every edge in this map is a REAL,
  // ledger-verified direct value transfer (from _buildCounterpartyData's
  // balance-delta walk) — never speculative. The one genuinely INFERRED
  // relationship this app has computed anywhere is Issuer Connections'
  // mirror-wallet clusters (accounts that MAY share a controller, based on
  // amount-similarity + timing/creation corroboration — never proof of
  // common ownership). Nodes that are also mirror-cluster members get a
  // distinct dashed marker so that inference is visible ON the node
  // without ever implying the edge itself (a real transfer) is anything
  // other than verified.
  const clusterByAddr = new Map();
  for (const g of mirrorGroups) {
    for (const a of g.accounts) clusterByAddr.set(a.addr, g);
  }

  const cpData = _buildCounterpartyData(txList, addr);

  const top = [...cpData.entries()]
    .map(([cp, d]) => [cp, d, _cpVolume(d)])
    .sort((a, b) => b[2].sortValue - a[2].sortValue || b[1].cnt - a[1].cnt)
    .slice(0, 20);

  // A 1-node radial map has nothing to lay out (no second point to draw a
  // ring around), so this genuinely can't render below 2 — unlike the other
  // fixes in this pass, hiding is the right call here, not showing an empty
  // chart. What was missing was any indication *why* — the map is a sub-div
  // inside the always-visible Account Overview section, so it used to just
  // leave an unexplained gap where a chart should be.
  if (top.length < 2) {
    el.style.display = '';
    el.innerHTML = `<div class="inspect-empty-note">${top.length === 0 ? 'No counterparty interactions found.' : 'Only one counterparty found — not enough to chart a network map.'}</div>`;
    return;
  }
  el.style.display = '';

  // ── Layout: two rings based on volume rank ────────────────────────────────
  const W = 560, H = 340;
  const cx = W / 2, cy = H / 2;
  const INNER_R = 95,  INNER_MAX = 7;   // top 7 = inner ring
  const OUTER_R = 155, OUTER_MAX = 13;  // next 13 = outer ring

  // maxVol drives edge thickness and (when not sizing by count) node
  // radius — uses the same "real value" measure as ranking (XRP, or the
  // account's own token when no XRP moved), not raw XRP alone, so a
  // token-issuer's counterparty map isn't flattened to uniform tiny nodes.
  const maxVol = Math.max(...top.map(([, , v]) => v.sortValue), 1);
  // The true max tx count across the shown set — NOT necessarily top[0]'s
  // count, since `top` is ranked by volume first. Sizing by count needs its
  // own real max or a high-count/low-volume node would size incorrectly.
  const maxCnt = Math.max(...top.map(([, d]) => d.cnt), 1);
  const sizeByCount = _networkMapSizeMetric === 'count';

  const nodes = [
    { id: addr, x: cx, y: cy, r: 13, main: true, label: shortAddr(addr), color: '#00d4ff', xrpOut: 0, xrpIn: 0, cnt: 0 },
  ];

  top.forEach(([cp, d, v], i) => {
    const ring   = i < INNER_MAX ? INNER_R : OUTER_R;
    const count  = i < INNER_MAX ? INNER_MAX : OUTER_MAX;
    const offset = i < INNER_MAX ? i : i - INNER_MAX;
    const angle  = (offset / count) * 2 * Math.PI - Math.PI / 2;
    const sizeRatio = sizeByCount ? (d.cnt / maxCnt) : (v.sortValue / maxVol);
    const nr     = Math.max(5, Math.min(14, 4 + sizeRatio * 10));

    const ent   = d.entity;
    const color = CP_CATEGORY_COLOR[ent?.type] || CP_CATEGORY_COLOR.other;

    // Direction: mostly-out, mostly-in, or balanced. Only meaningful for
    // the XRP leg — a pure token relationship (the common case for a token
    // issuer's counterparties) has no directional signal here, so it
    // reads as "both" rather than a fabricated in/out guess.
    const xrpVol = d.xrpOut + d.xrpIn;
    const dirRatio = xrpVol > 0 ? d.xrpOut / xrpVol : 0.5;
    const dir = dirRatio > 0.65 ? 'out' : dirRatio < 0.35 ? 'in' : 'both';

    nodes.push({
      id: cp, x: cx + ring * Math.cos(angle), y: cy + ring * Math.sin(angle),
      r: nr, color, label: ent?.name || shortAddr(cp), ent,
      xrpOut: d.xrpOut, xrpIn: d.xrpIn, cnt: d.cnt, dir,
      vol: v.sortValue, volLabel: v.display, ring,
      cluster: clusterByAddr.get(cp) || null,
    });
  });

  // ── Arrow marker defs ─────────────────────────────────────────────────────
  const defs = `<defs>
    <marker id="arrow-out" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto">
      <path d="M0,0 L6,3 L0,6 Z" fill="rgba(80,250,123,.6)"/>
    </marker>
    <marker id="arrow-in" markerWidth="6" markerHeight="6" refX="1" refY="3" orient="auto-start-reverse">
      <path d="M0,0 L6,3 L0,6 Z" fill="rgba(0,212,255,.6)"/>
    </marker>
    <marker id="arrow-both" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto">
      <path d="M0,0 L6,3 L0,6 Z" fill="rgba(255,184,108,.6)"/>
    </marker>
    <filter id="glow-red">
      <feGaussianBlur stdDeviation="3" result="blur"/>
      <feMerge><feMergeNode in="blur"/><feMergeNode in="SourceGraphic"/></feMerge>
    </filter>
  </defs>`;

  // ── Edges ─────────────────────────────────────────────────────────────────
  const edges = nodes.slice(1).map(n => {
    const volFrac  = n.vol / maxVol;
    const sw       = Math.max(0.8, volFrac * 3);
    const opaque   = 0.12 + volFrac * 0.45;
    const markerColor = n.dir === 'out' ? 'rgba(80,250,123,' : n.dir === 'in' ? 'rgba(0,212,255,' : 'rgba(255,184,108,';
    const stroke   = n.dir === 'out' ? `rgba(80,250,123,${opaque})`
      : n.dir === 'in'  ? `rgba(0,212,255,${opaque})`
      : `rgba(255,184,108,${opaque})`;
    const dash     = n.dir === 'in' ? '5,3' : 'none';
    const mEnd     = `marker-end="url(#arrow-${n.dir})"`;

    // Shorten line so arrow doesn't overlap node
    const dx = n.x - cx, dy = n.y - cy;
    const len = Math.sqrt(dx*dx + dy*dy);
    const trim = (n.r + 2) / len;
    const x2 = cx + dx * (1 - trim), y2 = cy + dy * (1 - trim);

    const tooltip = n.xrpOut > 0 || n.xrpIn > 0
      ? `${n.xrpOut > 0 ? '→ ' + fmt(n.xrpOut,2) + ' XRP out' : ''}${n.xrpIn > 0 ? (n.xrpOut > 0 ? ' / ' : '') + '← ' + fmt(n.xrpIn,2) + ' XRP in' : ''}, ${n.cnt} tx`
      : `${n.volLabel || 'no direct value moved'}, ${n.cnt} tx`;

    return `<line class="netmap-edge" data-addr="${escHtml(n.id)}" x1="${cx}" y1="${cy}" x2="${x2.toFixed(1)}" y2="${y2.toFixed(1)}"
      stroke="${stroke}" stroke-width="${sw.toFixed(1)}" stroke-dasharray="${dash}" ${mEnd}
      data-tooltip="${escHtml(tooltip)}" style="cursor:pointer"></line>`;
  }).join('');

  // ── Node elements ─────────────────────────────────────────────────────────
  const nodeEls = nodes.map(n => {
    if (n.main) {
      // Was hardcoded "YOU" regardless of whose address this is — wrong for
      // the primary use case of this tool, inspecting someone ELSE'S
      // account, not your own wallet. Show the actual (truncated) address
      // being inspected instead, same label format the satellite nodes use,
      // plus a tooltip with the full address since the visible label is cut
      // short to fit inside a 26px circle.
      const centerLbl = shortAddr(n.id);
      return `<g class="netmap-node netmap-node--main" data-tooltip="${escHtml('Inspected account: ' + n.id)}">
        <circle cx="${cx}" cy="${cy}" r="13" fill="rgba(0,212,255,.2)" stroke="#00d4ff" stroke-width="2"/>
        <circle cx="${cx}" cy="${cy}" r="13" fill="rgba(0,212,255,.15)"/>
        <text x="${cx}" y="${cy+4}" text-anchor="middle" font-size="6.5" fill="#00d4ff" font-weight="800">${escHtml(centerLbl)}</text>
        <text x="${cx}" y="${cy + 13 + 10}" text-anchor="middle" font-size="6"
          fill="rgba(255,255,255,.4)">Inspected account</text>
      </g>`;
    }

    const isBlackhole = n.ent?.type === 'blackhole';
    const isExchange  = n.ent?.type === 'exchange';
    const glow        = isBlackhole ? 'filter="url(#glow-red)"' : '';
    const strokeColor = n.dir === 'out' ? 'rgba(80,250,123,.5)' : n.dir === 'in' ? 'rgba(0,212,255,.5)' : 'rgba(255,184,108,.5)';
    const strokeW     = 1.5;

    // Label: entity name (if known) or shortened address
    const lbl = n.label.length > 14 ? n.label.slice(0,14) + '…' : n.label;

    // Amount labels under node — XRP direction when this relationship
    // actually moved XRP; otherwise the account's own token volume (the
    // common case for a token issuer's counterparties, previously shown
    // as a misleading "0 XRP"); otherwise just the interaction count.
    const amtLabel = (n.xrpOut > 0 || n.xrpIn > 0)
      ? (n.xrpOut > 0 && n.xrpIn > 0
          ? `⇄ ${fmt(n.xrpOut + n.xrpIn,0)} XRP`
          : n.xrpOut > 0 ? `→ ${fmt(n.xrpOut,0)} XRP` : `← ${fmt(n.xrpIn,0)} XRP`)
      : n.volLabel ? n.volLabel : `${n.cnt} tx`;

    const tooltipText = n.id +
      (n.ent ? ' (' + n.ent.name + ')' : '') + ' | ' +
      (n.xrpOut > 0 ? 'Sent: ' + fmt(n.xrpOut,2) + ' XRP' + _usd(n.xrpOut) + ' | ' : '') +
      (n.xrpIn > 0  ? 'Received: ' + fmt(n.xrpIn,2) + ' XRP' + _usd(n.xrpIn) + ' | ' : '') +
      (n.xrpOut === 0 && n.xrpIn === 0 && n.volLabel ? 'Volume: ' + n.volLabel + ' (no XRP leg — token-denominated) | ' : '') +
      'Interactions: ' + n.cnt +
      (n.cluster ? ` | ⊘ INFERRED: possibly part of a ${n.cluster.accounts.length}-wallet cluster (${n.cluster.tier} evidence) — amount similarity${n.cluster.timingCorrelated ? ' + funding timing' : ''}${n.cluster.issuerCreated ? ' + issuer-created' : ''}, not verified common ownership` : '');

    return `<g class="netmap-node" data-addr="${escHtml(n.id)}" style="cursor:pointer" data-tooltip="${escHtml(tooltipText)}" onclick="inspectorLoadAddr('${n.id}')">
      ${isBlackhole ? `<circle cx="${n.x}" cy="${n.y}" r="${n.r+4}" fill="rgba(255,85,85,.1)" stroke="rgba(255,85,85,.4)" stroke-width="1" stroke-dasharray="3,2"/>` : ''}
      ${n.cluster ? `<circle cx="${n.x}" cy="${n.y}" r="${n.r+4}" fill="none" stroke="rgba(189,147,249,.55)" stroke-width="1" stroke-dasharray="2,2"/>` : ''}
      <circle cx="${n.x}" cy="${n.y}" r="${n.r}" fill="${n.color}" opacity=".18" ${glow}/>
      <circle cx="${n.x}" cy="${n.y}" r="${n.r}" fill="${n.color}" opacity=".1" stroke="${strokeColor}" stroke-width="${strokeW}"/>
      <text x="${n.x}" y="${n.y + 3.5}" text-anchor="middle" font-size="${n.ring === INNER_R ? 7.5 : 6.5}"
        fill="${n.color}" font-weight="700" opacity=".95">${escHtml(lbl)}</text>
      <text x="${n.x}" y="${n.y + n.r + 10}" text-anchor="middle" font-size="6"
        fill="rgba(255,255,255,.4)">${escHtml(amtLabel)}</text>
    </g>`;
  }).join('');

  // ── Ring labels ───────────────────────────────────────────────────────────
  const ringLabels = `
    <text x="${cx}" y="${cy - INNER_R - 8}" text-anchor="middle" font-size="6"
      fill="rgba(255,255,255,.15)" font-style="italic">inner ring</text>
    <text x="${cx}" y="${cy - OUTER_R - 8}" text-anchor="middle" font-size="6"
      fill="rgba(255,255,255,.10)" font-style="italic">outer ring</text>`;

  const sizeToggle = `
    <div class="netmap-size-toggle" role="group" aria-label="Node size metric">
      <button type="button" class="netmap-size-btn${sizeByCount ? '' : ' active'}" onclick="_setNetworkMapSizeMetric('volume')">Size: Volume</button>
      <button type="button" class="netmap-size-btn${sizeByCount ? ' active' : ''}" onclick="_setNetworkMapSizeMetric('count')">Size: Tx Count</button>
    </div>`;

  const clusterCount = nodes.filter(n => n.cluster).length;

  el.innerHTML = `
    <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px;margin-bottom:6px">
      <div style="font-size:.65rem;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:.08em">
        Counterparty Network Map — ${top.length} addresses · click any node to inspect
      </div>
      ${sizeToggle}
    </div>
    <div style="font-size:.68rem;color:rgba(255,255,255,.3);margin-bottom:6px">
      Every line here is a <strong style="color:rgba(255,255,255,.5)">verified</strong> direct on-ledger value transfer${clusterCount ? ` — the ${clusterCount} dashed-outline node${clusterCount === 1 ? '' : 's'} below ${clusterCount === 1 ? 'is' : 'are'} a separate, <strong style="color:#bd93f9">inferred</strong> relationship (a possible shared-controller cluster; see Issuer Connections), not a verified one` : ''}.
    </div>
    <div style="overflow-x:auto;touch-action:pan-x">
      <svg class="netmap-svg" width="${W}" height="${H}" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}"
        style="display:block;border-radius:10px;background:rgba(255,255,255,.015);border:1px solid rgba(255,255,255,.06);min-width:${Math.min(W,360)}px">
        ${defs}${ringLabels}${edges}${nodeEls}
      </svg>
    </div>
    <div style="display:flex;gap:12px;margin-top:8px;flex-wrap:wrap;align-items:center">
      <span style="font-size:.66rem;color:rgba(80,250,123,.8)">→ Outbound</span>
      <span style="font-size:.66rem;color:rgba(0,212,255,.8)">← Inbound</span>
      <span style="font-size:.66rem;color:rgba(255,184,108,.8)">⇄ Both</span>
      <span style="font-size:.66rem;color:rgba(255,255,255,.3)">|</span>
      <span style="font-size:.66rem;color:#00d4ff">● Exchange</span>
      <span style="font-size:.66rem;color:#ff5555">● Blackhole</span>
      <span style="font-size:.66rem;color:#ffb86c">● Issuer</span>
      <span style="font-size:.66rem;color:#8be9fd">● Other</span>
      ${clusterCount ? `<span style="font-size:.66rem;color:#bd93f9">⊘ Possible cluster (inferred)</span>` : ''}
      <span style="font-size:.66rem;color:rgba(255,255,255,.3)">|</span>
      <span style="font-size:.66rem;color:rgba(255,255,255,.3)">Node size = ${sizeByCount ? 'transaction count' : 'value moved (XRP, or the account\'s own token when no XRP leg exists)'} · Edge thickness = same measure · which nodes appear never changes with this toggle</span>
    </div>`;

  // Hover-focus: hovering a node dims every unrelated node/edge and keeps
  // the hovered relationship (and the always-visible inspected-account
  // center) at full strength, turning a static diagram into something you
  // can actually pick a single relationship out of a crowded map with.
  const svgEl = el.querySelector('.netmap-svg');
  if (svgEl) {
    const allNodes = svgEl.querySelectorAll('.netmap-node[data-addr]');
    const allEdges = svgEl.querySelectorAll('.netmap-edge');
    const setFocus = addr => {
      allNodes.forEach(g => { g.style.opacity = (!addr || g.dataset.addr === addr) ? '1' : '.15'; });
      allEdges.forEach(l => { l.style.opacity = (!addr || l.dataset.addr === addr) ? '1' : '.08'; });
    };
    svgEl.addEventListener('mouseover', e => {
      const g = e.target.closest('.netmap-node[data-addr]');
      if (g) setFocus(g.dataset.addr);
    });
    svgEl.addEventListener('mouseleave', () => setFocus(null));

    // Clicking an edge opens the Trading Relationship drawer (reciprocity,
    // gross/net, round-trip timing) — deliberately NOT the node itself,
    // since nodes already navigate straight to inspecting that address
    // ("click any node to inspect") and stacking a second click meaning on
    // the same element would make one of the two behaviors unreachable.
    svgEl.addEventListener('click', e => {
      const edge = e.target.closest('.netmap-edge[data-addr]');
      if (edge) openRelationshipDrawer(edge.dataset.addr);
    });
  }
}

/** Trading Relationship detail for one counterparty, reusing
 *  _roundTripQuality wholesale plus a fresh gross/net XRP tally — the same
 *  "reuse what's already computed" discipline as Value Circulation. XRP-
 *  denominated payments only, same reasoning as valueCirculation.note.
 *  mirrorGroups is the same inferred-cluster data the Network Map already
 *  receives — surfaced here as context, never as proof of common
 *  ownership. */
function _computeRelationshipDetail(addr, partnerAddr, txList, mirrorGroups = []) {
  const payments = txList.filter(({ tx }) => tx.TransactionType === 'Payment');
  const outPayments = payments.filter(({ tx }) => tx.Account === addr && tx.Destination === partnerAddr);
  const inPayments  = payments.filter(({ tx }) => tx.Destination === addr && tx.Account === partnerAddr);

  // XRP and issued-token flow computed together in one pass via the shared
  // amount-extraction helper (also used by Fund Flow, Inbound Flow, and
  // Wash Execution's round-trip pairing) — previously this function
  // independently re-parsed tx.Amount twice (once for xrpOut/xrpIn, once
  // more for the token breakdown below), both times ignoring
  // meta.delivered_amount the way Inbound Flow's own copy already didn't.
  let xrpOut = 0, xrpIn = 0, unknownAmountCount = 0;
  const tokenFlows = new Map();
  const addFlow = ({ tx, meta }, dir) => {
    const { amtXrp, amtToken } = _extractPaymentAmount(tx, meta);
    // See _extractPaymentAmount's comment — null means undeterminable,
    // excluded from the sum rather than poisoning it with NaN.
    if (amtXrp == null) unknownAmountCount++;
    else if (dir === 'out') xrpOut += amtXrp;
    else xrpIn += amtXrp;
    if (!amtToken) return;
    const key = `${amtToken.currency}|${amtToken.issuer || ''}`;
    const entry = tokenFlows.get(key) || { currency: amtToken.currency, issuer: amtToken.issuer || null, outAmt: 0, inAmt: 0, outCount: 0, inCount: 0 };
    if (dir === 'out') { entry.outAmt += amtToken.value; entry.outCount++; } else { entry.inAmt += amtToken.value; entry.inCount++; }
    tokenFlows.set(key, entry);
  };
  outPayments.forEach(p => addFlow(p, 'out'));
  inPayments.forEach(p => addFlow(p, 'in'));
  const tokenFlowList = [...tokenFlows.values()].sort((a, b) => (b.inAmt + b.outAmt) - (a.inAmt + a.outAmt));

  const gross = xrpOut + xrpIn;
  const net = Math.abs(xrpOut - xrpIn);
  const reciprocityPct = (xrpOut > 0 && xrpIn > 0) ? (Math.min(xrpOut, xrpIn) / Math.max(xrpOut, xrpIn)) * 100 : 0;
  const roundTrip = _roundTripQuality(addr, partnerAddr, payments);
  const cluster = mirrorGroups.find(g => g.accounts.some(a => a.addr === partnerAddr)) || null;

  // First/last interaction across BOTH assets — raw ripple-epoch (tx.date),
  // converted with +XRPL_EPOCH only at render time, matching every other
  // date in this file (see the earlier ~30-years-too-early bug this exact
  // omission caused elsewhere).
  const allDates = [...outPayments, ...inPayments].map(({ tx }) => tx.date).filter(d => d != null);
  const firstDate = allDates.length ? Math.min(...allDates) : null;
  const lastDate  = allDates.length ? Math.max(...allDates) : null;
  const activeSpanDays = (firstDate != null && lastDate != null) ? Math.round((lastDate - firstDate) / 86400) : null;

  // Behavioral description, not a risk signal — direction (of the XRP leg
  // only, matching the rest of this function's XRP-scoped stats) plus
  // frequency. A token-only relationship (both xrpIn/xrpOut are 0 despite
  // real payment counts) correctly gets no direction label here — the
  // asset-by-asset breakdown above is what actually describes it.
  const totalCount = outPayments.length + inPayments.length;
  let patternDirection = null;
  if (xrpIn > 0 && xrpOut > 0) patternDirection = reciprocityPct >= 70 ? 'Highly reciprocal' : 'Two-way';
  else if (xrpIn > 0) patternDirection = 'Primarily inbound';
  else if (xrpOut > 0) patternDirection = 'Primarily outbound';
  const patternFrequency = totalCount === 0 ? null : (totalCount === 1 ? 'One-time' : 'Recurring');
  const pattern = [patternDirection, patternFrequency].filter(Boolean).join(' · ') || null;

  return {
    partnerAddr, outCount: outPayments.length, inCount: inPayments.length, xrpOut, xrpIn, gross, net, reciprocityPct, roundTrip, cluster,
    tokenFlowList, firstDate, lastDate, activeSpanDays, pattern, unknownAmountCount,
  };
}

/** Shared "Trading Relationship" drawer — mirrors _mountEvidenceInspector's
 *  exact .acct-peek-overlay/.acct-peek-box shell rather than inventing a
 *  new modal pattern. Opened by clicking an edge on the Network Map. */
function _mountRelationshipDrawer() {
  if (document.getElementById('relationshipDrawerOverlay')) return;
  const overlay = document.createElement('div');
  overlay.id = 'relationshipDrawerOverlay';
  overlay.className = 'acct-peek-overlay';
  overlay.style.display = 'none';
  overlay.innerHTML = `
    <div class="acct-peek-box" role="dialog" aria-modal="true" aria-label="Trading relationship">
      <button class="acct-peek-close" id="relDrawerClose" aria-label="Close">✕</button>
      <div class="acct-peek-head">
        <div style="min-width:0">
          <div class="acct-peek-title">Trading Relationship</div>
          <div class="acct-peek-addr cut" id="relDrawerHeadline" style="white-space:normal">—</div>
        </div>
      </div>
      <div class="rel-fingerprint" id="relDrawerFingerprint"></div>
      <div class="acct-peek-grid" id="relDrawerGrid"></div>
      <div class="acct-peek-section" id="relDrawerDetail"></div>
    </div>`;
  document.body.appendChild(overlay);
  const close = () => { overlay.style.display = 'none'; overlay._a11yFocusOut?.(); };
  bindOverlayA11y(overlay, close);
  overlay.addEventListener('click', e => { if (e.target === overlay) close(); });
  document.getElementById('relDrawerClose')?.addEventListener('click', close);
}

// Relationship age (how long this specific pair has interacted) and account
// age (how long the PARTNER has existed) are easily conflated but describe
// different things — spec example: "Relationship began 2026 / Partner
// account activated 2017." Resolving the partner's real age needs its own
// lightweight lookup (a single oldest-anchor account_tx page, exactly the
// pattern already used for the common-funder lookup) since it's a wallet
// the main inspection never fetched full history for. Triggered only when
// the drawer actually opens for a given partner — not for every
// counterparty automatically — and guarded against a stale response
// landing after the drawer has since been reopened for someone else.
let _relDrawerPartnerAgeFor = null;
async function _loadRelDrawerPartnerAge(partnerAddr) {
  _relDrawerPartnerAgeFor = partnerAddr;
  const res = await wsSend({
    command: 'account_tx', account: partnerAddr,
    limit: 400, ledger_index_min: -1, ledger_index_max: -1, forward: true,
  }).catch(() => null);
  if (_relDrawerPartnerAgeFor !== partnerAddr) return; // drawer moved on to a different partner
  const el = document.getElementById('relDrawerPartnerAge');
  if (!el) return;
  const holderTxList = normaliseTxList(res?.result?.transactions || []);
  const evidence = _findAccountRootCreationEvidence(holderTxList, partnerAddr);
  if (!evidence) {
    // Genuinely unverifiable from one page — never fabricate a lower-bound
    // guess for a wallet we only glanced at once; just say so.
    el.innerHTML = `<span>Partner account age</span><b style="opacity:.5">Not verifiable from one lookup</b>`;
    return;
  }
  const ageDays = Math.max(0, Math.floor((Date.now() - (evidence.timestamp + XRPL_EPOCH) * 1000) / 86400000));
  const ageStr = ageDays < 30 ? `${ageDays} day${ageDays === 1 ? '' : 's'}`
    : ageDays < 365 ? `${Math.floor(ageDays / 30)} months`
    : `${(ageDays / 365).toFixed(1)} years`;
  const activatedStr = new Date((evidence.timestamp + XRPL_EPOCH) * 1000).toLocaleDateString();
  el.innerHTML = `<span>Partner account age</span><b title="Activated ${activatedStr} — verified via AccountRoot creation">${ageStr} (verified)</b>`;
}

// Compact visual signature of a relationship — every row here is a real
// field _computeRelationshipDetail already computes (outCount/inCount/
// activeSpanDays/reciprocityPct). Deliberately has NO "market overlap"
// row — the app has no real per-counterparty market-overlap computation
// to back one, and a fabricated bar would be worse than no bar at all.
function _renderRelFingerprint(rel) {
  const maxIO = Math.max(rel.outCount, rel.inCount, 1);
  const totalCount = rel.outCount + rel.inCount;
  const freqPct = Math.min(100, Math.round((totalCount / 20) * 100)); // soft visual cap, not a judgment
  const durPct = rel.activeSpanDays != null ? Math.min(100, Math.round((rel.activeSpanDays / 365) * 100)) : 0;
  const bar = (label, pct, display) => {
    const w = pct > 0 ? Math.max(pct, 3) : 0; // keep any nonzero value visible as a sliver, never inflate a real zero
    return `
    <div class="rel-fp-row">
      <span class="rel-fp-label">${escHtml(label)}</span>
      <span class="rel-fp-track"><span class="rel-fp-fill" style="width:${w}%"></span></span>
      <span class="rel-fp-val">${escHtml(display)}</span>
    </div>`;
  };
  return `
    <div class="rel-fp-title">Relationship Fingerprint</div>
    ${bar('Inbound', (rel.inCount / maxIO) * 100, `${rel.inCount}`)}
    ${bar('Outbound', (rel.outCount / maxIO) * 100, `${rel.outCount}`)}
    ${bar('Frequency', freqPct, `${totalCount} tx`)}
    ${rel.activeSpanDays != null ? bar('Duration', durPct, `${rel.activeSpanDays}d`) : ''}
    ${bar('Reciprocity', rel.reciprocityPct, `${rel.reciprocityPct.toFixed(0)}%`)}
  `;
}

function openRelationshipDrawer(partnerAddr) {
  _mountRelationshipDrawer();
  const overlay = document.getElementById('relationshipDrawerOverlay');
  // Relationship Intelligence (the live Tree/Flow/Matrix/Timeline view) is
  // checked first; _lastNetworkMapArgs only still gets set by
  // renderNetworkMap's own debug hook (used in isolation by a couple of
  // tests exercising the retired bubble-graph code directly) — note the
  // two have DIFFERENT array shapes (_lastRelIntelArgs has no unused
  // fundFlow slot), so they're destructured separately, not as one shared shape.
  const relIntelArgs = _lastRelIntelArgs;
  const args = relIntelArgs || _lastNetworkMapArgs;
  if (!overlay || !args) return;
  const [txList, addr, mirrorGroups, inboundFlow] = relIntelArgs
    ? relIntelArgs
    : [args[0], args[1], args[4], args[3]]; // _lastNetworkMapArgs shape: [txList, addr, fundFlow, inboundFlow, mirrorGroups, targetId]
  const rel = _computeRelationshipDetail(addr, partnerAddr, txList, mirrorGroups || []);
  const ent = getEntity(partnerAddr);
  const arrow = rel.xrpOut > 0 && rel.xrpIn > 0 ? '⇄' : rel.xrpIn > 0 ? '←' : '→';

  // Rank/share among funding sources — Inbound Flow's own Top Funding
  // Sources list already computed this; reusing it here (rather than
  // recomputing) is free since inboundFlow is already part of
  // _lastNetworkMapArgs. Only shown when the partner is actually a KNOWN
  // inbound source (an "Examine" opened from elsewhere — NFT issuer, LP
  // participant, etc. — correctly shows neither, rather than a fabricated
  // "not ranked").
  const sourceIdx = inboundFlow?.topSources?.findIndex(s => s.addr === partnerAddr) ?? -1;
  const sourceEntry = sourceIdx >= 0 ? inboundFlow.topSources[sourceIdx] : null;
  const sourceSharePct = sourceEntry && inboundFlow.totalIn > 0 ? (sourceEntry.totalXrp / inboundFlow.totalIn) * 100 : null;

  const savedLabel = getAddrBookLabel(partnerAddr);
  document.getElementById('relDrawerHeadline').textContent = `${shortAddr(addr)} ${arrow} ${savedLabel || ent?.name || shortAddr(partnerAddr)}`;
  document.getElementById('relDrawerFingerprint').innerHTML = _renderRelFingerprint(rel);
  const fmtDate = d => d != null ? new Date((d + XRPL_EPOCH) * 1000).toLocaleDateString() : '—';
  document.getElementById('relDrawerGrid').innerHTML = `
    <div class="acct-peek-stat"><span>Payments (out / in)</span><b>${rel.outCount} / ${rel.inCount}</b></div>
    <div class="acct-peek-stat"><span>${escHtml(shortAddr(addr))} → partner</span><b>${fmt(rel.xrpOut, 2)} XRP</b></div>
    <div class="acct-peek-stat"><span>Partner → ${escHtml(shortAddr(addr))}</span><b>${fmt(rel.xrpIn, 2)} XRP</b></div>
    <div class="acct-peek-stat"><span>Gross exchanged</span><b>${fmt(rel.gross, 2)} XRP</b></div>
    <div class="acct-peek-stat"><span>Net difference</span><b>${fmt(rel.net, 2)} XRP</b></div>
    ${sourceEntry ? `<div class="acct-peek-stat"><span>Share of tracked XRP inflow</span><b>${sourceSharePct.toFixed(0)}%</b></div>` : ''}
    ${sourceEntry ? `<div class="acct-peek-stat"><span>Rank among funding sources</span><b>#${sourceIdx + 1} of ${inboundFlow.topSources.length}</b></div>` : ''}
    ${rel.pattern ? `<div class="acct-peek-stat"><span>Relationship pattern</span><b>${escHtml(rel.pattern)}</b></div>` : ''}
    <div class="acct-peek-stat"><span>Reciprocity</span><b>${rel.reciprocityPct.toFixed(0)}%</b></div>
    ${rel.roundTrip ? `<div class="acct-peek-stat"><span>Round-trip cycles</span><b>${rel.roundTrip.occurrences}</b></div>` : ''}
    ${rel.roundTrip ? `<div class="acct-peek-stat"><span>Median return time</span><b>${fmt(rel.roundTrip.medianElapsedSec / 60, 1)} min</b></div>` : ''}
    ${rel.firstDate != null ? `<div class="acct-peek-stat"><span>First interaction</span><b>${fmtDate(rel.firstDate)}</b></div>` : ''}
    ${rel.lastDate != null ? `<div class="acct-peek-stat"><span>Last interaction</span><b>${fmtDate(rel.lastDate)}</b></div>` : ''}
    ${rel.activeSpanDays != null ? `<div class="acct-peek-stat"><span>Active span</span><b>${rel.activeSpanDays} day${rel.activeSpanDays === 1 ? '' : 's'}</b></div>` : ''}
    <div class="acct-peek-stat" id="relDrawerPartnerAge"><span>Partner account age</span><b>Checking…</b></div>
  `;
  _loadRelDrawerPartnerAge(partnerAddr);

  // Asset-by-asset breakdown — a relationship built ENTIRELY on issued-token
  // payments previously showed as an all-zero XRP grid above with only a
  // small caveat explaining why (a real reported case: 7 inbound payments,
  // every XRP stat reading 0). Each currency gets its own line since
  // incompatible token quantities can't be summed together.
  let detail = `<div style="font-size:.72rem;color:rgba(255,255,255,.35);margin-bottom:8px">The stats above are XRP-denominated payments only — see Assets Moved below for issued-token transfers between these two addresses.</div>`;
  if (rel.tokenFlowList.length) {
    detail += `<div style="font-size:.72rem;color:rgba(255,255,255,.4);text-transform:uppercase;letter-spacing:.05em;margin:10px 0 4px">Assets Moved</div>`;
    detail += rel.tokenFlowList.map(t => {
      const cur = t.currency.length > 4 ? (hexToAscii(t.currency) || `${t.currency.slice(0, 4)}…`) : t.currency;
      const parts = [];
      if (t.inAmt) parts.push(`<span style="color:var(--ac3,#50fa7b)">+${fmt(t.inAmt, 2)} in</span> (${t.inCount})`);
      if (t.outAmt) parts.push(`<span style="color:#ff7070">−${fmt(t.outAmt, 2)} out</span> (${t.outCount})`);
      return `<div style="display:flex;justify-content:space-between;align-items:center;font-size:.78rem;padding:5px 0;border-bottom:1px solid rgba(255,255,255,.05)">
        <span>${escHtml(cur)}${t.issuer ? ` <span style="opacity:.4;font-size:.7rem">(${escHtml(shortAddr(t.issuer))})</span>` : ''}</span>
        <span>${parts.join(' · ')}</span>
      </div>`;
    }).join('');
  }
  if (!rel.roundTrip) {
    detail += `<div style="font-size:.76rem;color:rgba(255,255,255,.45);margin-top:8px">No reciprocal payment relationship found — value moved in one direction only here (a returning leg, if any, predates the outgoing one and isn't paired).</div>`;
  }
  if (rel.cluster) {
    detail += `<div style="font-size:.76rem;color:#bd93f9;margin-top:8px">⊘ Possible wallet relationship: ${escHtml(rel.cluster.tier)} evidence — part of a ${rel.cluster.accounts.length}-wallet cluster based on amount similarity${rel.cluster.timingCorrelated ? ' + funding timing' : ''}${rel.cluster.issuerCreated ? ' + issuer-created' : ''}. Not verified common ownership.</div>`;
  }
  detail += `<div style="display:flex;gap:8px;margin-top:12px;flex-wrap:wrap">
    <button type="button" class="mi-rel-examine" onclick="relDrawerFocusPartner('${escHtml(partnerAddr)}')">🎯 Focus</button>
    <button type="button" class="mi-rel-examine" onclick="relDrawerInspectPartner('${escHtml(partnerAddr)}')">🔍 Inspect this account</button>
    <button type="button" class="mi-rel-examine" onclick="relDrawerComparePartner('${escHtml(partnerAddr)}')">⚖ Compare accounts</button>
    ${savedLabel
      ? `<button type="button" class="mi-rel-examine" disabled title="Already saved as “${escHtml(savedLabel)}”">🏷 ${escHtml(savedLabel)}</button>`
      : `<button type="button" class="mi-rel-examine" onclick="relDrawerSaveToAddrBook('${escHtml(partnerAddr)}')">🏷 Save to Address Book</button>`}
  </div>`;
  document.getElementById('relDrawerDetail').innerHTML = detail;
  overlay.style.display = 'flex';
  overlay._a11yFocusIn?.();
}
window.openRelationshipDrawer = openRelationshipDrawer;

// Cross-links from the relationship drawer — closes the drawer first so it
// doesn't linger stale-open behind whatever it navigates to/spawns.
window.relDrawerInspectPartner = function(partnerAddr) {
  document.getElementById('relationshipDrawerOverlay').style.display = 'none';
  window.inspectorLoadAddr(partnerAddr);
};
window.relDrawerComparePartner = function(partnerAddr) {
  document.getElementById('relationshipDrawerOverlay').style.display = 'none';
  window.openCompareModal();
  const input = document.getElementById('compareAddrBInput');
  if (input) input.value = partnerAddr;
  window.runAccountComparison();
};
// Focus Tunnel — isolates one relationship in the Tree: its own row (and
// any OTHER row that shares its real, already-computed mirror-cluster
// membership — never a fabricated "shared AMM/issuer" cross-reference,
// since this function only has the ROOT's own tx history in scope, not
// each counterparty's, so that kind of comparison can't be computed
// honestly here) stay fully lit; everything else dims.
window.relDrawerFocusPartner = function(partnerAddr) {
  document.getElementById('relationshipDrawerOverlay').style.display = 'none';
  _relIntelFocusAddr = partnerAddr;
  _rerenderRelIntel();
  document.getElementById(_lastRelIntelArgs?.[4] || 'inspect-relationship-landscape')?.scrollIntoView({ behavior: 'smooth', block: 'center' });
};
window.exitRelIntelFocus = function() {
  _relIntelFocusAddr = null;
  _rerenderRelIntel();
};
// Fullscreen Investigation — the native Fullscreen API rather than a
// hand-rolled "hide everything else" overlay: the browser already
// guarantees only this element (and its descendants) renders, with no
// custom CSS needed to enumerate and hide unrelated app chrome.
window.toggleRelIntelFullscreen = function() {
  const el = document.getElementById('inspect-relationship-landscape');
  if (!el) return;
  if (document.fullscreenElement) document.exitFullscreen();
  else el.requestFullscreen?.().catch(() => {});
};
// Re-renders the SAME drawer in place afterward (rather than closing it) —
// addToAddrBook's own prompt() already confirmed the label, so the natural
// next thing to see is this drawer now showing it, not a jump elsewhere.
// Also refreshes the Inbound Flow panel behind it (if mounted) — its Top
// Funding Sources list already rendered once before this label existed and
// won't otherwise reflect it until the next full inspection.
window.relDrawerSaveToAddrBook = function(partnerAddr) {
  addToAddrBook(partnerAddr);
  if (!getAddrBookLabel(partnerAddr)) return;
  openRelationshipDrawer(partnerAddr);
  const inboundFlow = _lastRelIntelArgs?.[3] ?? _lastNetworkMapArgs?.[3];
  if (inboundFlow) renderInboundFlowPanel(inboundFlow);
};

/* ═══════════════════════════════════════════════════
   TRANSACTION DETAIL DRAWER — reuses the exact .acct-peek-overlay/
   .acct-peek-box shell already established for the Evidence Inspector and
   Relationship Drawer, rather than inventing a 4th modal pattern. Three
   tabs: Summary (plain explanation + key fields), Balance Changes (reuses
   extractBalanceDeltas — already-built, addr-scoped — computed once for
   the inspected account and once for the immediate counterparty, covering
   the common 2-party case from Payment's own shape), and Raw JSON.
═══════════════════════════════════════════════════ */
let _txDetailCurrent = null; // { tx, meta } for whatever's open
let _txDetailTab = 'summary';

function _mountTxDetailDrawer() {
  if (document.getElementById('txDetailOverlay')) return;
  const overlay = document.createElement('div');
  overlay.id = 'txDetailOverlay';
  overlay.className = 'acct-peek-overlay';
  overlay.style.display = 'none';
  overlay.innerHTML = `
    <div class="acct-peek-box" role="dialog" aria-modal="true" aria-label="Transaction inspector">
      <button class="acct-peek-close" id="txDetailClose" aria-label="Close">✕</button>
      <div class="acct-peek-head">
        <div style="min-width:0">
          <div class="acct-peek-title">Transaction Inspector</div>
          <div class="acct-peek-addr mono cut" id="txDetailHash">—</div>
        </div>
      </div>
      <div class="sec-modal-tabs" style="margin:10px 0 12px">
        <button class="wdt-btn active" id="txdetail-tab-btn-summary" onclick="switchTxDetailTab('summary')">Summary</button>
        <button class="wdt-btn" id="txdetail-tab-btn-balance" onclick="switchTxDetailTab('balance')">Balance Changes</button>
        <button class="wdt-btn" id="txdetail-tab-btn-raw" onclick="switchTxDetailTab('raw')">Raw JSON</button>
      </div>
      <div class="acct-peek-section" id="txDetailBody"></div>
    </div>`;
  document.body.appendChild(overlay);
  const close = () => { overlay.style.display = 'none'; _txDetailCurrent = null; overlay._a11yFocusOut?.(); };
  bindOverlayA11y(overlay, close);
  overlay.addEventListener('click', e => { if (e.target === overlay) close(); });
  document.getElementById('txDetailClose')?.addEventListener('click', close);
}

window.openTxDetailDrawer = function(hash) {
  const entry = (window._lastTxList || []).find(({ tx }) => tx.hash === hash);
  if (!entry) return;
  _mountTxDetailDrawer();
  _txDetailCurrent = entry;
  const overlay = document.getElementById('txDetailOverlay');
  overlay.style.display = 'flex';
  overlay._a11yFocusIn?.();
  document.getElementById('txDetailHash').textContent = hash;
  switchTxDetailTab('summary');
};

window.switchTxDetailTab = function(tab) {
  _txDetailTab = tab;
  ['summary', 'balance', 'raw'].forEach(t => {
    document.getElementById(`txdetail-tab-btn-${t}`)?.classList.toggle('active', t === tab);
  });
  const body = document.getElementById('txDetailBody');
  if (!body || !_txDetailCurrent) return;
  const addr = window._lastInspectResult?.addr;
  if (tab === 'summary') body.innerHTML = _renderTxDetailSummary(_txDetailCurrent, addr);
  else if (tab === 'balance') body.innerHTML = _renderTxDetailBalance(_txDetailCurrent, addr);
  else body.innerHTML = _renderTxDetailRaw(_txDetailCurrent);
};

function _renderTxDetailSummary({ tx, meta }, addr) {
  const type = tx.TransactionType || 'Unknown';
  const ts = getCloseTime(tx);
  const timeStr = ts ? new Date(ts * 1000).toLocaleString() : '—';
  const success = meta?.TransactionResult === 'tesSUCCESS';
  const brief = txBrief(tx, addr) || type;
  const memos = (tx.Memos || []).map(m => {
    try { return decodeURIComponent(escape(atob(m.Memo?.MemoData || ''))); } catch { return null; }
  }).filter(Boolean);

  const fields = [
    ['Ledger', tx.ledger_index?.toLocaleString?.() ?? tx.ledger_index ?? '—'],
    ['Sequence', tx.Sequence ?? '—'],
    ['Fee', tx.Fee ? `${fmt(Number(tx.Fee) / 1e6, 6)} XRP` : '—'],
    ['Destination Tag', tx.DestinationTag ?? '—'],
    ['Source Tag', tx.SourceTag ?? '—'],
    ['Flags', tx.Flags != null ? `0x${Number(tx.Flags).toString(16)}` : '—'],
    ['Result', meta?.TransactionResult || '—'],
    ['Validated', 'Yes'],
  ];

  return `
    <div style="text-align:center;padding:6px 0 14px">
      <div style="font-size:.72rem;color:rgba(255,255,255,.4);text-transform:uppercase;letter-spacing:.08em">${escHtml(type)}</div>
      <div style="font-size:.82rem;color:rgba(255,255,255,.5);margin-top:4px">${timeStr}</div>
      <div style="font-size:.95rem;font-weight:700;margin-top:10px;color:${success ? 'var(--ac3,#50fa7b)' : '#ff7070'}">${success ? '✓' : '✗'} ${escHtml(brief)}</div>
    </div>
    <div class="acct-peek-grid">
      ${fields.map(([k, v]) => `<div class="acct-peek-stat"><span>${escHtml(k)}</span><b>${escHtml(String(v))}</b></div>`).join('')}
    </div>
    ${memos.length ? `<div style="margin-top:12px"><div style="font-size:.72rem;color:rgba(255,255,255,.4);text-transform:uppercase;letter-spacing:.05em;margin-bottom:4px">Memo</div>${memos.map(m => `<div style="font-size:.8rem;color:rgba(255,255,255,.7);word-break:break-word;padding:6px 0;border-bottom:1px solid rgba(255,255,255,.05)">${escHtml(m)}</div>`).join('')}</div>` : ''}
  `;
}

function _renderTxDetailBalance({ tx, meta }, addr) {
  // The two natural parties to most transaction types — a full N-party
  // reconstruction would need to walk every RippleState/AccountRoot node
  // for EVERY account it touches, not just these two; scoped to what the
  // common Payment/TrustSet/OfferCreate cases actually need.
  const parties = [...new Set([addr, tx.Account, tx.Destination].filter(Boolean))];
  const rows = [];
  for (const p of parties) {
    const d = extractBalanceDeltas(tx, meta, p);
    if (d.xrpDelta) rows.push({ addr: p, currency: 'XRP', delta: d.xrpDelta });
    for (const t of d.tokenDeltas) rows.push({ addr: p, currency: hexToAscii(t.currency) || t.currency, issuer: t.issuer, delta: t.delta });
    for (const t of d.lpDeltas) rows.push({ addr: p, currency: 'LP Tokens', issuer: t.issuer, delta: t.delta });
  }
  if (!rows.length) return `<div class="inspect-empty-note">No reconstructable balance changes found for the accounts involved in this transaction.</div>`;

  return `
    <div style="font-size:.72rem;color:rgba(255,255,255,.35);margin-bottom:8px">Reconstructed from this transaction's own ledger metadata — covers the ${parties.length === 1 ? 'inspected account' : 'inspected account and its immediate counterparty'} only, not every account this transaction may have touched.</div>
    ${rows.map(r => `<div style="display:flex;justify-content:space-between;align-items:center;font-size:.8rem;padding:6px 0;border-bottom:1px solid rgba(255,255,255,.05)">
      <span class="mono">${escHtml(shortAddr(r.addr))}${r.addr === addr ? ' <span style="opacity:.4;font-size:.68rem">(inspected)</span>' : ''}</span>
      <span>${escHtml(r.currency)}${r.issuer ? ` <span style="opacity:.4;font-size:.7rem">(${escHtml(shortAddr(r.issuer))})</span>` : ''}</span>
      <b style="color:${r.delta > 0 ? 'var(--ac3,#50fa7b)' : '#ff7070'}">${r.delta > 0 ? '+' : ''}${fmt(r.delta, 6)}</b>
    </div>`).join('')}
    ${tx.Fee ? `<div style="font-size:.74rem;color:rgba(255,255,255,.35);margin-top:8px">Fee (already reflected in the sender's XRP delta above): ${fmt(Number(tx.Fee) / 1e6, 6)} XRP</div>` : ''}
  `;
}

function _renderTxDetailRaw({ tx, meta }) {
  return `
    <div style="font-size:.72rem;color:rgba(255,255,255,.4);text-transform:uppercase;letter-spacing:.05em;margin-bottom:4px">Transaction</div>
    <pre style="font-size:.72rem;line-height:1.5;white-space:pre-wrap;word-break:break-all;background:rgba(0,0,0,.3);border-radius:8px;padding:10px;max-height:220px;overflow:auto">${escHtml(JSON.stringify(tx, null, 2))}</pre>
    <div style="font-size:.72rem;color:rgba(255,255,255,.4);text-transform:uppercase;letter-spacing:.05em;margin:12px 0 4px">Metadata</div>
    <pre style="font-size:.72rem;line-height:1.5;white-space:pre-wrap;word-break:break-all;background:rgba(0,0,0,.3);border-radius:8px;padding:10px;max-height:220px;overflow:auto">${escHtml(JSON.stringify(meta || {}, null, 2))}</pre>
  `;
}

/* ═══════════════════════════════════════════════════
   COPY ANALYSIS FOR AI (on-demand — no API key, no server, no download;
   the user pastes it into whatever AI model they already use)
═══════════════════════════════════════════════════ */
function _buildInspectorAiPrompt() {
  const result = window._lastInspectResult;
  const findings = window._lastAllFindings || [];
  if (!result) return null;

  const findingsText = findings.length
    ? findings.map(f => `- [${f.sev.toUpperCase()}] ${f.module}: ${f.headline}${f.detail ? ' — ' + f.detail : ''}`).join('\n')
    : '(No elevated findings — all checks returned normal ranges.)';

  const ageQualifier = result.walletAgeDays != null
    ? (result.walletAgeVerified ? ' (verified — full history confirmed)' : ' (estimated — full history not confirmed, true age may be older)')
    : '';

  return `XRPL ACCOUNT FORENSIC ANALYSIS
Account: ${result.addr}
Risk score: ${result.riskScore}/100
Wallet age: ${result.walletAgeDays != null ? result.walletAgeDays + ' days' : 'unknown'}${ageQualifier}
Transactions analyzed: ${result.txCount}
Snapshot taken: ${result.timestamp}

Automated findings from a rule-based XRPL forensics scan:
${findingsText}

---
You are acting as a security analyst explaining automated blockchain forensics findings to someone who isn't a blockchain expert. Write a clear, plain-English explanation of what this account's activity suggests. Synthesize the findings above into a coherent read of the account rather than restating them one by one — call out which ones reinforce each other and which are weak signals on their own. Be direct about how concerning (or not) this looks, and be skeptical of your own confidence where the evidence is thin rather than overstating it. Do not repeat the address or risk score back verbatim; the reader can already see those above your response.`;
}

window.copyInspectorAnalysisForAi = function() {
  const el = document.getElementById('ai-explanation-body');
  const prompt = _buildInspectorAiPrompt();
  if (!prompt) {
    if (el) el.innerHTML = `<p style="font-size:.82rem;color:#ff5555">Run an inspection first.</p>`;
    return;
  }
  copyToClipboard(prompt);
};

/* ═══════════════════════════════════════════════════
   JSON EXPORT
═══════════════════════════════════════════════════ */
window.exportInspectorJSON = function() {
  const data = window._lastInspectResult;
  if (!data) { alert('Run an inspection first.'); return; }
  const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
  const url  = URL.createObjectURL(blob);
  const a    = document.createElement('a');
  const addr = document.getElementById('inspect-addr-badge')?.dataset?.fullAddr || 'wallet';
  a.href = url;
  a.download = `naluxrp_${addr.slice(0,10)}_${new Date().toISOString().slice(0,10)}.json`;
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  URL.revokeObjectURL(url);
};

/* ─────────────────────────────
   Cleanup (called on page/tab leave)
──────────────────────────────── */
export function destroyInspector() {
  if (_pulseInterval) { clearInterval(_pulseInterval); _pulseInterval = null; }
  _inspectAbort = true;
  _dom = null;
  _p   = null; // release all cached DOM refs
}